--
-- Table structure for table `mst_security_policy`
--

DROP TABLE IF EXISTS `mst_security_policy`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mst_security_policy` (
  `Id` smallint unsigned NOT NULL AUTO_INCREMENT,
  `Max_Attempts` smallint unsigned NOT NULL DEFAULT '5' COMMENT 'Failed logins before lock',
  `Lock_Minutes` smallint unsigned NOT NULL DEFAULT '15' COMMENT 'Account lock duration',
  `Daily_Reset_Time` time NOT NULL DEFAULT '00:00:00' COMMENT 'Daily fail-counter reset',
  `Min_Chars` smallint unsigned NOT NULL DEFAULT '8',
  `Max_Chars` smallint unsigned NOT NULL DEFAULT '32',
  `Require_Upper` tinyint(1) NOT NULL DEFAULT '1',
  `Require_Lower` tinyint(1) NOT NULL DEFAULT '1',
  `Require_Number` tinyint(1) NOT NULL DEFAULT '1',
  `Require_Special` tinyint(1) NOT NULL DEFAULT '1',
  `Unique_Recent` smallint unsigned NOT NULL DEFAULT '5' COMMENT '0 = unlimited reuse',
  `Passwords_Expire` tinyint(1) NOT NULL DEFAULT '1',
  `Expire_Days` smallint unsigned NOT NULL DEFAULT '90',
  `Updated_by` smallint unsigned DEFAULT NULL,
  `Created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`Id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

