DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_ADVANCE_PART`(p_collection_id BIGINT, p_upto DATE) RETURNS decimal(14,2)
    READS SQL DATA
BEGIN
    DECLARE v_acct BIGINT;
    DECLARE v_eff DATE;
    DECLARE v_p DECIMAL(14,2) DEFAULT 0;
    DECLARE v_i DECIMAL(14,2) DEFAULT 0;
    DECLARE v_bp DECIMAL(14,2) DEFAULT 0;
    DECLARE v_bi DECIMAL(14,2) DEFAULT 0;
    DECLARE v_lo_p DECIMAL(14,2) DEFAULT 0;
    DECLARE v_lo_i DECIMAL(14,2) DEFAULT 0;
    DECLARE v_res DECIMAL(14,2) DEFAULT 0;

    SELECT MAX(Account_Id), MAX(IFNULL(Effect_Date, DATE(Collection_Date))), IFNULL(MAX(Principal_Collected), 0),
           IFNULL(MAX(Interest_Collected), 0)
    INTO v_acct, v_eff, v_p, v_i
    FROM trans_loan_collection WHERE Collection_Id = p_collection_id;

    IF v_acct IS NULL THEN
        RETURN 0;
    END IF;

    SET v_bp = FN_LOAN_PAID_BEFORE(v_acct, p_collection_id, 'P');
    SET v_bi = FN_LOAN_PAID_BEFORE(v_acct, p_collection_id, 'I');
    SET v_lo_p = GREATEST(v_bp, FN_LOAN_DEMAND(v_acct, v_eff, 'P'));
    SET v_lo_i = GREATEST(v_bi, FN_LOAN_DEMAND(v_acct, v_eff, 'I'));

    IF p_upto IS NULL THEN
        SET v_res = GREATEST(0, v_bp + v_p - v_lo_p) + GREATEST(0, v_bi + v_i - v_lo_i);
    ELSE
        SET v_res = GREATEST(0, LEAST(v_bp + v_p, FN_LOAN_DEMAND(v_acct, p_upto, 'P')) - v_lo_p)
                  + GREATEST(0, LEAST(v_bi + v_i, FN_LOAN_DEMAND(v_acct, p_upto, 'I')) - v_lo_i);
    END IF;

    RETURN v_res;
END ;;
DELIMITER ;
