/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_APPL_STAGE`(p_app BIGINT) RETURNS varchar(30) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_status INT DEFAULT NULL;
    DECLARE v_disb DECIMAL(14,2) DEFAULT 0;
    DECLARE v_appr INT DEFAULT NULL;
    DECLARE v_insp INT DEFAULT NULL;

    SELECT MAX(Appl_Status_Cd) INTO v_status FROM mst_loan_application WHERE Application_Id = p_app;
    SELECT IFNULL(MAX(Disbursed_Amount), 0) INTO v_disb FROM mst_loan_account WHERE Application_Id = p_app;

    IF v_disb > 0 THEN
        RETURN 'disbursed';
    END IF;

    SET v_appr = (SELECT x.Approval_Status_Cd FROM mst_loan_application_approval x
                  WHERE x.Loan_Application_Id = p_app
                  ORDER BY x.Approval_Date DESC, x.Loan_Approval_Id DESC LIMIT 1);

    IF v_appr = 1 THEN
        RETURN 'sanctioned';
    END IF;

    IF v_status = 3 OR v_appr = 2 THEN
        RETURN 'rejected';
    END IF;

    SET v_insp = (SELECT i.Inspection_Result_Cd FROM mst_loan_application_inspection i
                  WHERE i.Loan_Application_Id = p_app
                  ORDER BY i.Inspection_Date DESC, i.Inspection_Id DESC LIMIT 1);

    IF v_insp = 1 THEN
        RETURN 'approval';
    END IF;

    RETURN 'field_verification';
END ;;
DELIMITER ;
