/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_CHARGE_AMOUNT`(p_charge_id INT, p_base DECIMAL(18,2)) RETURNS decimal(12,2)
    READS SQL DATA
BEGIN
    DECLARE v_rate DECIMAL(8,2) DEFAULT NULL;
    DECLARE v_fig INT DEFAULT NULL;
    DECLARE v_max DECIMAL(8,2) DEFAULT NULL;
    DECLARE v_amt DECIMAL(18,2) DEFAULT 0;

    SELECT MAX(Charge_Rate), MAX(Figure_Cd), MAX(Max_Amount)
    INTO v_rate, v_fig, v_max
    FROM mst_loan_charges WHERE Charge_Id = p_charge_id;

    IF v_fig = 2 THEN
        SET v_amt = ROUND(IFNULL(p_base, 0) * IFNULL(v_rate, 0) / 100, 2);
        IF IFNULL(v_max, 0) > 0 AND v_amt > v_max THEN
            SET v_amt = v_max;
        END IF;
    ELSE
        SET v_amt = IFNULL(v_rate, IFNULL(v_max, 0));
    END IF;

    RETURN GREATEST(IFNULL(v_amt, 0), 0);
END ;;
DELIMITER ;
