CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_CHARGE_TAX`(p_charge_id INT, p_amount DECIMAL(12,2)) RETURNS decimal(12,2)
    READS SQL DATA
BEGIN
    RETURN ROUND(IFNULL(p_amount, 0) * IFNULL((SELECT MAX(Tax_Prcent) FROM mst_loan_charges WHERE Charge_Id = p_charge_id), 0) / 100, 2);
END ;;
