CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_DEMAND`(p_acct BIGINT, p_as_on DATE, p_comp CHAR(1)) RETURNS decimal(14,2)
    READS SQL DATA
BEGIN
    RETURN (
        SELECT IFNULL(SUM(IF(p_comp = 'P',
                             s.Principal_Due - IFNULL(s.Principal_Waived, 0),
                             s.Interest_Due - IFNULL(s.Interest_Waived, 0))), 0)
        FROM trans_loanac_schedule s
        WHERE s.Loan_Account_Id = p_acct
          AND IFNULL(s.Is_Active, 1) = 1
          AND (p_as_on IS NULL OR s.Due_Date <= p_as_on)
    );
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `FN_LOAN_MC_PENDING` */;
