DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_MC_PENDING`(p_voucher_type INT, p_amount DECIMAL(14,2), p_user_id INT) RETURNS tinyint
    READS SQL DATA
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_threshold DECIMAL(14,2);
    DECLARE v_roles VARCHAR(25);
    DECLARE v_dual INT DEFAULT 1;
    DECLARE v_auto INT DEFAULT 0;
    DECLARE v_is_checker INT DEFAULT 0;

    SELECT COUNT(*), MAX(Thresold_Limit), MAX(Checker_Role_Id), MAX(IFNULL(DualAuth_Req, 1)), MAX(IFNULL(Auto_Apprv, 0))
    INTO v_cnt, v_threshold, v_roles, v_dual, v_auto
    FROM mst_settings_maker_checker
    WHERE Voucher_Type = p_voucher_type AND IFNULL(Is_Active, 0) = 1;

    IF v_cnt = 0 OR v_auto = 1 OR p_amount <= IFNULL(v_threshold, 0) THEN
        RETURN 0;
    END IF;

    SELECT COUNT(*) INTO v_is_checker
    FROM mst_user_role ur
    WHERE ur.User_Id = p_user_id AND IFNULL(ur.Status, 0) = 1
      AND FIND_IN_SET(ur.Role_Id, REPLACE(IFNULL(v_roles, ''), ' ', '')) > 0;

    RETURN IF(v_dual = 0 AND v_is_checker > 0, 0, 1);
END ;;
DELIMITER ;
