CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_MEMBER_KYC_OK`(p_member_id INT) RETURNS tinyint
    READS SQL DATA
BEGIN
    RETURN IF(EXISTS (SELECT 1 FROM mst_member_kyc k
                      WHERE k.Member_Id = p_member_id AND IFNULL(k.KYC_Verified, 0) = 1
                        AND (k.Is_Active IS NULL OR k.Is_Active = 1)), 1, 0);
END ;;
