CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_MEMBER_OVERDUE`(p_member_id INT, p_as_on DATE) RETURNS decimal(14,2)
    READS SQL DATA
BEGIN
    DECLARE v_prev DATE;
    SET v_prev = DATE_SUB(p_as_on, INTERVAL 1 DAY);

    RETURN (
        SELECT IFNULL(SUM(
                   GREATEST(0, FN_LOAN_DEMAND(la.Loan_Account_Id, v_prev, 'P') - FN_LOAN_PAID(la.Loan_Account_Id, p_as_on, 'P'))
                 + GREATEST(0, FN_LOAN_DEMAND(la.Loan_Account_Id, v_prev, 'I') - FN_LOAN_PAID(la.Loan_Account_Id, p_as_on, 'I'))), 0)
        FROM mst_loan_account la
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        WHERE la.Ln_Status_Cd = 1
          AND ((ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = p_member_id)
               OR EXISTS (SELECT 1 FROM mst_loan_application_bulk b
                          WHERE b.Loan_Application_Id = ap.Application_Id AND b.Customer_Id = p_member_id))
    );
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `FN_LOAN_OLDEST_UNPAID` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
