DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_OPT_DESC`(p_grp INT, p_code INT) RETURNS varchar(100) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    IF p_code IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN (SELECT MIN(o.Opt_Description) FROM mst_appl_options o
            WHERE o.Opt_Grp_Id = p_grp AND o.Opt_Code = p_code);
END ;;
DELIMITER ;
