/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_PAID`(p_acct BIGINT, p_as_on DATE, p_comp CHAR(1)) RETURNS decimal(14,2)
    READS SQL DATA
BEGIN
    RETURN (
        SELECT IFNULL(SUM(CASE p_comp
                    WHEN 'P' THEN c.Principal_Collected
                    WHEN 'I' THEN c.Interest_Collected
                    WHEN 'N' THEN c.Penalty_Collected
                    ELSE IF(IFNULL(c.Payment_Mode_Cd, 0) = 5, 0, c.Total_Collected) END), 0)
        FROM trans_loan_collection c
        WHERE c.Account_Id = p_acct
          AND c.Tr_Status_Cd = 2
          AND (p_as_on IS NULL OR IFNULL(c.Effect_Date, DATE(c.Collection_Date)) <= p_as_on)
    );
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `FN_LOAN_PAID_BEFORE` */;
