/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_PAID_BEFORE`(p_acct BIGINT, p_collection_id BIGINT, p_comp CHAR(1)) RETURNS decimal(14,2)
    READS SQL DATA
BEGIN
    RETURN (
        SELECT IFNULL(SUM(IF(p_comp = 'P', c.Principal_Collected, c.Interest_Collected)), 0)
        FROM trans_loan_collection c
        WHERE c.Account_Id = p_acct AND c.Tr_Status_Cd = 2 AND c.Collection_Id < p_collection_id
    );
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
