/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_PENALTY_DUE`(p_acct BIGINT, p_as_on DATE) RETURNS decimal(12,2)
    READS SQL DATA
BEGIN
    DECLARE v_is_od INT DEFAULT 0;
    DECLARE v_grace INT DEFAULT 0;
    DECLARE v_on INT DEFAULT 1;
    DECLARE v_rate DECIMAL(7,2) DEFAULT 0;
    DECLARE v_outs DECIMAL(14,2) DEFAULT 0;
    DECLARE v_oldest DATE DEFAULT NULL;
    DECLARE v_days INT DEFAULT 0;
    DECLARE v_od_p DECIMAL(14,2) DEFAULT 0;
    DECLARE v_od_i DECIMAL(14,2) DEFAULT 0;
    DECLARE v_base DECIMAL(14,2) DEFAULT 0;
    DECLARE v_pen DECIMAL(14,2) DEFAULT 0;
    DECLARE v_paid DECIMAL(14,2) DEFAULT 0;
    DECLARE v_prev DATE;

    SET v_prev = DATE_SUB(p_as_on, INTERVAL 1 DAY);

    SELECT IFNULL(MAX(s.Is_Overdue), 0), IFNULL(MAX(s.Repay_Grace_Days), 0), IFNULL(MAX(s.OverdueOn_Cd), 1),
           IFNULL(MAX(s.Overdur_Rate), 0), IFNULL(MAX(la.Principal_Outstanding), 0)
    INTO v_is_od, v_grace, v_on, v_rate, v_outs
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    WHERE la.Loan_Account_Id = p_acct;

    IF v_is_od <> 1 OR v_rate <= 0 OR p_as_on IS NULL THEN
        RETURN 0;
    END IF;

    SET v_oldest = FN_LOAN_OLDEST_UNPAID(p_acct, p_as_on);
    IF v_oldest IS NULL OR v_oldest >= p_as_on THEN
        RETURN 0;
    END IF;

    SET v_days = DATEDIFF(p_as_on, v_oldest) - v_grace;
    IF v_days <= 0 THEN
        RETURN 0;
    END IF;

    SET v_od_p = GREATEST(0, FN_LOAN_DEMAND(p_acct, v_prev, 'P') - FN_LOAN_PAID(p_acct, p_as_on, 'P'));
    SET v_od_i = GREATEST(0, FN_LOAN_DEMAND(p_acct, v_prev, 'I') - FN_LOAN_PAID(p_acct, p_as_on, 'I'));

    SET v_base = CASE v_on WHEN 2 THEN v_od_p + v_od_i WHEN 3 THEN v_outs ELSE v_od_p END;
    SET v_pen = ROUND(v_base * v_rate / 100 * v_days / 365, 2);

    SELECT IFNULL(SUM(c.Penalty_Collected), 0) INTO v_paid
    FROM trans_loan_collection c
    WHERE c.Account_Id = p_acct AND c.Tr_Status_Cd = 2
      AND IFNULL(c.Effect_Date, DATE(c.Collection_Date)) BETWEEN v_oldest AND p_as_on;

    RETURN GREATEST(0, v_pen - v_paid);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `FN_LOAN_PERIODS_PER_YEAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` FUNCTION `FN_LOAN_PERIODS_PER_YEAR`(p_kind CHAR(1), p_code INT) RETURNS int
    DETERMINISTIC
BEGIN
    IF p_kind = 'S' THEN
        RETURN CASE p_code WHEN 1 THEN 365 WHEN 2 THEN 52 ELSE 12 END;
    END IF;

    RETURN CASE p_code
        WHEN 1 THEN 365 WHEN 2 THEN 52 WHEN 3 THEN 26 WHEN 4 THEN 12
        WHEN 5 THEN 6 WHEN 6 THEN 4 WHEN 7 THEN 2 WHEN 8 THEN 1 ELSE 12 END;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
