/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_CATEGORY_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_categ_id INT,
    IN p_categ_code VARCHAR(50),
    IN p_categ_name VARCHAR(100),
    IN p_categy_type VARCHAR(2)
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;
    DECLARE v_name VARCHAR(100);
    DECLARE v_code VARCHAR(50);
    DECLARE v_type VARCHAR(2);
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_gen_code VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET v_name = NULLIF(TRIM(p_categ_name), '');
    SET v_code = NULLIF(TRIM(IFNULL(p_categ_code, '')), '');
    SET v_type = NULLIF(UPPER(TRIM(IFNULL(p_categy_type, ''))), '');

    IF UPPER(p_action) = 'ADD' THEN
        IF v_name IS NULL THEN
            SELECT 'ERROR' AS status, NULL AS categ_id, NULL AS categ_code,
                   'Category name is required' AS message;
        ELSE
            IF v_code IS NULL THEN
                CALL USP_CODE_SERIES_GENERATE('acct_category', v_gen_code, v_gen_status, v_gen_msg);
                IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
                    SELECT 'ERROR' AS status, NULL AS categ_id, NULL AS categ_code,
                           IFNULL(v_gen_msg, 'Unable to generate category code') AS message;
                ELSE
                    SET v_code = CONVERT(v_gen_code USING utf8mb4) COLLATE utf8mb4_unicode_ci;
                END IF;
            END IF;

            IF v_code IS NOT NULL THEN
                SELECT COUNT(*) INTO v_dup
                FROM mst_acct_category
                WHERE UPPER(Categ_Code) = UPPER(v_code);

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, NULL AS categ_id, NULL AS categ_code,
                           'Category code already exists' AS message;
                ELSE
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_acct_category
                    WHERE LOWER(Categ_Name) = LOWER(v_name);

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, NULL AS categ_id, NULL AS categ_code,
                               'Category name already exists' AS message;
                    ELSE
                        INSERT INTO mst_acct_category (Categ_Code, Categ_Name, Categy_Type)
                        VALUES (v_code, v_name, v_type);

                        SET v_new_id = LAST_INSERT_ID();

                        SELECT 'SUCCESS' AS status, v_new_id AS categ_id, v_code AS categ_code,
                               'Account category created successfully' AS message;
                    END IF;
                END IF;
            END IF;
        END IF;

    ELSEIF UPPER(p_action) = 'EDIT' THEN
        SELECT COUNT(*) INTO v_exists FROM mst_acct_category WHERE Categ_Id = p_categ_id;

        IF v_exists = 0 THEN
            SELECT 'ERROR' AS status, p_categ_id AS categ_id, NULL AS categ_code,
                   'Category not found' AS message;
        ELSEIF v_name IS NULL THEN
            SELECT 'ERROR' AS status, p_categ_id AS categ_id, NULL AS categ_code,
                   'Category name is required' AS message;
        ELSE
            IF v_code IS NULL THEN
                SELECT Categ_Code INTO v_code FROM mst_acct_category WHERE Categ_Id = p_categ_id;
            END IF;

            SELECT COUNT(*) INTO v_dup
            FROM mst_acct_category
            WHERE UPPER(Categ_Code) = UPPER(v_code)
              AND Categ_Id <> p_categ_id;

            IF v_dup > 0 THEN
                SELECT 'ERROR' AS status, p_categ_id AS categ_id, NULL AS categ_code,
                       'Category code already exists' AS message;
            ELSE
                SELECT COUNT(*) INTO v_dup
                FROM mst_acct_category
                WHERE LOWER(Categ_Name) = LOWER(v_name)
                  AND Categ_Id <> p_categ_id;

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, p_categ_id AS categ_id, NULL AS categ_code,
                           'Category name already exists' AS message;
                ELSE
                    UPDATE mst_acct_category
                    SET Categ_Code = v_code,
                        Categ_Name = v_name,
                        Categy_Type = v_type
                    WHERE Categ_Id = p_categ_id;

                    SELECT 'SUCCESS' AS status, p_categ_id AS categ_id, v_code AS categ_code,
                           'Account category updated successfully' AS message;
                END IF;
            END IF;
        END IF;

    ELSE
        SELECT 'ERROR' AS status, p_categ_id AS categ_id, NULL AS categ_code,
               'Invalid action. Use ADD or EDIT' AS message;
    END IF;
END ;;
DELIMITER ;
