CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_CATEGORY_LIST`(
    IN p_categ_id INT,
    IN p_keyword VARCHAR(100),
    IN p_categy_type VARCHAR(2),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_acct_category c
    WHERE (p_categ_id IS NULL OR c.Categ_Id = p_categ_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR c.Categ_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(c.Categ_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (
          p_categy_type IS NULL OR p_categy_type = ''
          OR UPPER(IFNULL(c.Categy_Type, '')) = UPPER(p_categy_type)
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        c.Categ_Id,
        c.Categ_Code,
        c.Categ_Name,
        c.Categy_Type,
        (
            SELECT COUNT(*)
            FROM mst_acct_head h
            WHERE h.Categ_Id = c.Categ_Id
        ) AS Head_Count
    FROM mst_acct_category c
    WHERE (p_categ_id IS NULL OR c.Categ_Id = p_categ_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR c.Categ_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(c.Categ_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (
          p_categy_type IS NULL OR p_categy_type = ''
          OR UPPER(IFNULL(c.Categy_Type, '')) = UPPER(p_categy_type)
      )
    ORDER BY c.Categ_Code ASC, c.Categ_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
