CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_HEAD_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_mainhd_id INT,
    IN p_mainhd_code VARCHAR(50),
    IN p_mainhd_name VARCHAR(150),
    IN p_categ_id INT,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_categ_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;
    DECLARE v_name VARCHAR(150);
    DECLARE v_code VARCHAR(50);
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_gen_code VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET v_name = NULLIF(TRIM(p_mainhd_name), '');
    SET v_code = NULLIF(TRIM(IFNULL(p_mainhd_code, '')), '');

    IF UPPER(p_action) = 'ADD' THEN
        IF v_name IS NULL THEN
            SELECT 'ERROR' AS status, NULL AS mainhd_id, NULL AS mainhd_code,
                   'Main head name is required' AS message;
        ELSEIF p_categ_id IS NULL OR p_categ_id < 1 THEN
            SELECT 'ERROR' AS status, NULL AS mainhd_id, NULL AS mainhd_code,
                   'Category is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_categ_exists
            FROM mst_acct_category
            WHERE Categ_Id = p_categ_id;

            IF v_categ_exists = 0 THEN
                SELECT 'ERROR' AS status, NULL AS mainhd_id, NULL AS mainhd_code,
                       'Category not found' AS message;
            ELSE
                IF v_code IS NULL THEN
                    CALL USP_CODE_SERIES_GENERATE('acct_head', v_gen_code, v_gen_status, v_gen_msg);
                    IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
                        SELECT 'ERROR' AS status, NULL AS mainhd_id, NULL AS mainhd_code,
                               IFNULL(v_gen_msg, 'Unable to generate main head code') AS message;
                    ELSE
                        SET v_code = CONVERT(v_gen_code USING utf8mb4) COLLATE utf8mb4_unicode_ci;
                    END IF;
                END IF;

                IF v_code IS NOT NULL THEN
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_acct_head
                    WHERE UPPER(MainHd_Code) = UPPER(v_code);

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, NULL AS mainhd_id, NULL AS mainhd_code,
                               'Main head code already exists' AS message;
                    ELSE
                        SELECT COUNT(*) INTO v_dup
                        FROM mst_acct_head
                        WHERE Categ_Id = p_categ_id
                          AND LOWER(MainHd_Name) = LOWER(v_name);

                        IF v_dup > 0 THEN
                            SELECT 'ERROR' AS status, NULL AS mainhd_id, NULL AS mainhd_code,
                                   'Main head name already exists for this category' AS message;
                        ELSE
                            INSERT INTO mst_acct_head (MainHd_Code, MainHd_Name, Categ_Id, Is_Active)
                            VALUES (v_code, v_name, p_categ_id, IFNULL(p_is_active, 1));

                            SET v_new_id = LAST_INSERT_ID();

                            SELECT 'SUCCESS' AS status, v_new_id AS mainhd_id, v_code AS mainhd_code,
                                   'Account main head created successfully' AS message;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;

    ELSEIF UPPER(p_action) = 'EDIT' THEN
        SELECT COUNT(*) INTO v_exists FROM mst_acct_head WHERE MainHd_Id = p_mainhd_id;

        IF v_exists = 0 THEN
            SELECT 'ERROR' AS status, p_mainhd_id AS mainhd_id, NULL AS mainhd_code,
                   'Main head not found' AS message;
        ELSEIF v_name IS NULL THEN
            SELECT 'ERROR' AS status, p_mainhd_id AS mainhd_id, NULL AS mainhd_code,
                   'Main head name is required' AS message;
        ELSEIF p_categ_id IS NULL OR p_categ_id < 1 THEN
            SELECT 'ERROR' AS status, p_mainhd_id AS mainhd_id, NULL AS mainhd_code,
                   'Category is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_categ_exists
            FROM mst_acct_category
            WHERE Categ_Id = p_categ_id;

            IF v_categ_exists = 0 THEN
                SELECT 'ERROR' AS status, p_mainhd_id AS mainhd_id, NULL AS mainhd_code,
                       'Category not found' AS message;
            ELSE
                IF v_code IS NULL THEN
                    SELECT MainHd_Code INTO v_code FROM mst_acct_head WHERE MainHd_Id = p_mainhd_id;
                END IF;

                SELECT COUNT(*) INTO v_dup
                FROM mst_acct_head
                WHERE UPPER(MainHd_Code) = UPPER(v_code)
                  AND MainHd_Id <> p_mainhd_id;

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, p_mainhd_id AS mainhd_id, NULL AS mainhd_code,
                           'Main head code already exists' AS message;
                ELSE
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_acct_head
                    WHERE Categ_Id = p_categ_id
                      AND LOWER(MainHd_Name) = LOWER(v_name)
                      AND MainHd_Id <> p_mainhd_id;

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, p_mainhd_id AS mainhd_id, NULL AS mainhd_code,
                               'Main head name already exists for this category' AS message;
                    ELSE
                        UPDATE mst_acct_head
                        SET MainHd_Code = v_code,
                            MainHd_Name = v_name,
                            Categ_Id = p_categ_id,
                            Is_Active = IFNULL(p_is_active, Is_Active)
                        WHERE MainHd_Id = p_mainhd_id;

                        SELECT 'SUCCESS' AS status, p_mainhd_id AS mainhd_id, v_code AS mainhd_code,
                               'Account main head updated successfully' AS message;
                    END IF;
                END IF;
            END IF;
        END IF;

    ELSE
        SELECT 'ERROR' AS status, p_mainhd_id AS mainhd_id, NULL AS mainhd_code,
               'Invalid action. Use ADD or EDIT' AS message;
    END IF;
END ;;
DELIMITER ;
