CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_HEAD_LIST`(
    IN p_mainhd_id INT,
    IN p_categ_id INT,
    IN p_keyword VARCHAR(100),
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_acct_head h
    WHERE (p_mainhd_id IS NULL OR h.MainHd_Id = p_mainhd_id)
      AND (p_categ_id IS NULL OR h.Categ_Id = p_categ_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR h.MainHd_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(h.MainHd_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_is_active IS NULL OR IFNULL(h.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        h.MainHd_Id,
        h.MainHd_Code,
        h.MainHd_Name,
        h.Categ_Id,
        c.Categ_Code,
        c.Categ_Name,
        c.Categy_Type,
        h.Is_Active
    FROM mst_acct_head h
    LEFT JOIN mst_acct_category c ON c.Categ_Id = h.Categ_Id
    WHERE (p_mainhd_id IS NULL OR h.MainHd_Id = p_mainhd_id)
      AND (p_categ_id IS NULL OR h.Categ_Id = p_categ_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR h.MainHd_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(h.MainHd_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_is_active IS NULL OR IFNULL(h.Is_Active, 0) = p_is_active)
    ORDER BY h.MainHd_Code ASC, h.MainHd_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
