CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_LEDGER_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_ledger_id INT,
    IN p_ledger_code VARCHAR(50),
    IN p_ledger_name VARCHAR(150),
    IN p_ledger_type VARCHAR(1),
    IN p_mainhd_id INT,
    IN p_is_active TINYINT,
    IN p_created_by INT
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_head_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;
    DECLARE v_name VARCHAR(150);
    DECLARE v_code VARCHAR(50);
    DECLARE v_type VARCHAR(1);
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_gen_code VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET v_name = NULLIF(TRIM(p_ledger_name), '');
    SET v_code = NULLIF(TRIM(IFNULL(p_ledger_code, '')), '');
    SET v_type = NULLIF(UPPER(TRIM(IFNULL(p_ledger_type, ''))), '');

    IF UPPER(p_action) = 'ADD' THEN
        IF v_name IS NULL THEN
            SELECT 'ERROR' AS status, NULL AS ledger_id, NULL AS ledger_code,
                   'Ledger name is required' AS message;
        ELSEIF p_mainhd_id IS NULL OR p_mainhd_id < 1 THEN
            SELECT 'ERROR' AS status, NULL AS ledger_id, NULL AS ledger_code,
                   'Main head is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_head_exists FROM mst_acct_head WHERE MainHd_Id = p_mainhd_id;

            IF v_head_exists = 0 THEN
                SELECT 'ERROR' AS status, NULL AS ledger_id, NULL AS ledger_code,
                       'Main head not found' AS message;
            ELSE
                IF v_code IS NULL THEN
                    CALL USP_CODE_SERIES_GENERATE('acct_ledger', v_gen_code, v_gen_status, v_gen_msg);
                    IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
                        SELECT 'ERROR' AS status, NULL AS ledger_id, NULL AS ledger_code,
                               IFNULL(v_gen_msg, 'Unable to generate ledger code') AS message;
                    ELSE
                        SET v_code = CONVERT(v_gen_code USING utf8mb4) COLLATE utf8mb4_0900_ai_ci;
                    END IF;
                END IF;

                IF v_code IS NOT NULL THEN
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_acct_ledger WHERE UPPER(Ledger_Code) = UPPER(v_code);

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, NULL AS ledger_id, NULL AS ledger_code,
                               'Ledger code already exists' AS message;
                    ELSE
                        SELECT COUNT(*) INTO v_dup
                        FROM mst_acct_ledger
                        WHERE MainHd_Id = p_mainhd_id
                          AND LOWER(Ledger_Name) = LOWER(v_name);

                        IF v_dup > 0 THEN
                            SELECT 'ERROR' AS status, NULL AS ledger_id, NULL AS ledger_code,
                                   'Ledger name already exists for this main head' AS message;
                        ELSE
                            INSERT INTO mst_acct_ledger
                                (Ledger_Code, Ledger_Name, Ledger_Type, MainHd_Id, Is_Active, Created_By, Created_At)
                            VALUES
                                (v_code, v_name, v_type, p_mainhd_id, IFNULL(p_is_active, 1), p_created_by, NOW());

                            SET v_new_id = LAST_INSERT_ID();

                            SELECT 'SUCCESS' AS status, v_new_id AS ledger_id, v_code AS ledger_code,
                                   'Account ledger created successfully' AS message;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;

    ELSEIF UPPER(p_action) = 'EDIT' THEN
        SELECT COUNT(*) INTO v_exists FROM mst_acct_ledger WHERE Ledger_Id = p_ledger_id;

        IF v_exists = 0 THEN
            SELECT 'ERROR' AS status, p_ledger_id AS ledger_id, NULL AS ledger_code,
                   'Ledger not found' AS message;
        ELSEIF v_name IS NULL THEN
            SELECT 'ERROR' AS status, p_ledger_id AS ledger_id, NULL AS ledger_code,
                   'Ledger name is required' AS message;
        ELSEIF p_mainhd_id IS NULL OR p_mainhd_id < 1 THEN
            SELECT 'ERROR' AS status, p_ledger_id AS ledger_id, NULL AS ledger_code,
                   'Main head is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_head_exists FROM mst_acct_head WHERE MainHd_Id = p_mainhd_id;

            IF v_head_exists = 0 THEN
                SELECT 'ERROR' AS status, p_ledger_id AS ledger_id, NULL AS ledger_code,
                       'Main head not found' AS message;
            ELSE
                IF v_code IS NULL THEN
                    SELECT Ledger_Code INTO v_code FROM mst_acct_ledger WHERE Ledger_Id = p_ledger_id;
                END IF;

                SELECT COUNT(*) INTO v_dup
                FROM mst_acct_ledger
                WHERE UPPER(Ledger_Code) = UPPER(v_code)
                  AND Ledger_Id <> p_ledger_id;

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, p_ledger_id AS ledger_id, NULL AS ledger_code,
                           'Ledger code already exists' AS message;
                ELSE
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_acct_ledger
                    WHERE MainHd_Id = p_mainhd_id
                      AND LOWER(Ledger_Name) = LOWER(v_name)
                      AND Ledger_Id <> p_ledger_id;

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, p_ledger_id AS ledger_id, NULL AS ledger_code,
                               'Ledger name already exists for this main head' AS message;
                    ELSE
                        UPDATE mst_acct_ledger
                        SET Ledger_Code = v_code,
                            Ledger_Name = v_name,
                            Ledger_Type = v_type,
                            MainHd_Id = p_mainhd_id,
                            Is_Active = IFNULL(p_is_active, Is_Active)
                        WHERE Ledger_Id = p_ledger_id;

                        SELECT 'SUCCESS' AS status, p_ledger_id AS ledger_id, v_code AS ledger_code,
                               'Account ledger updated successfully' AS message;
                    END IF;
                END IF;
            END IF;
        END IF;

    ELSE
        SELECT 'ERROR' AS status, p_ledger_id AS ledger_id, NULL AS ledger_code,
               'Invalid action. Use ADD or EDIT' AS message;
    END IF;
END ;;
DELIMITER ;
