CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_LEDGER_LIST`(
    IN p_ledger_id INT,
    IN p_mainhd_id INT,
    IN p_keyword VARCHAR(100),
    IN p_ledger_type VARCHAR(1),
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_acct_ledger l
    WHERE (p_ledger_id IS NULL OR l.Ledger_Id = p_ledger_id)
      AND (p_mainhd_id IS NULL OR l.MainHd_Id = p_mainhd_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR l.Ledger_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Ledger_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (
          p_ledger_type IS NULL OR p_ledger_type = ''
          OR UPPER(IFNULL(l.Ledger_Type, '')) = UPPER(p_ledger_type)
      )
      AND (p_is_active IS NULL OR IFNULL(l.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        l.Ledger_Id,
        l.Ledger_Code,
        l.Ledger_Name,
        l.Ledger_Type,
        l.MainHd_Id,
        h.MainHd_Code,
        h.MainHd_Name,
        h.Categ_Id,
        c.Categ_Code,
        c.Categ_Name,
        l.Is_Active,
        l.Created_By,
        l.Created_At,
        (
            SELECT COUNT(*) FROM mst_acct_subledger s WHERE s.Ledger_Id = l.Ledger_Id
        ) AS Subledger_Count
    FROM mst_acct_ledger l
    LEFT JOIN mst_acct_head h ON h.MainHd_Id = l.MainHd_Id
    LEFT JOIN mst_acct_category c ON c.Categ_Id = h.Categ_Id
    WHERE (p_ledger_id IS NULL OR l.Ledger_Id = p_ledger_id)
      AND (p_mainhd_id IS NULL OR l.MainHd_Id = p_mainhd_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR l.Ledger_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Ledger_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (
          p_ledger_type IS NULL OR p_ledger_type = ''
          OR UPPER(IFNULL(l.Ledger_Type, '')) = UPPER(p_ledger_type)
      )
      AND (p_is_active IS NULL OR IFNULL(l.Is_Active, 0) = p_is_active)
    ORDER BY l.Ledger_Code ASC, l.Ledger_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
