/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_SUBLEDGER_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_subledg_id INT,
    IN p_subledg_code VARCHAR(50),
    IN p_subledg_name VARCHAR(100),
    IN p_ledger_id INT,
    IN p_is_active TINYINT,
    IN p_created_by INT
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_ledger_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;
    DECLARE v_name VARCHAR(100);
    DECLARE v_code VARCHAR(50);
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_gen_code VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET v_name = NULLIF(TRIM(p_subledg_name), '');
    SET v_code = NULLIF(TRIM(IFNULL(p_subledg_code, '')), '');

    IF UPPER(p_action) = 'ADD' THEN
        IF v_name IS NULL THEN
            SELECT 'ERROR' AS status, NULL AS subledg_id, NULL AS subledg_code,
                   'Subledger name is required' AS message;
        ELSEIF p_ledger_id IS NULL OR p_ledger_id < 1 THEN
            SELECT 'ERROR' AS status, NULL AS subledg_id, NULL AS subledg_code,
                   'Ledger is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_ledger_exists FROM mst_acct_ledger WHERE Ledger_Id = p_ledger_id;

            IF v_ledger_exists = 0 THEN
                SELECT 'ERROR' AS status, NULL AS subledg_id, NULL AS subledg_code,
                       'Ledger not found' AS message;
            ELSE
                IF v_code IS NULL THEN
                    CALL USP_CODE_SERIES_GENERATE('acct_subledger', v_gen_code, v_gen_status, v_gen_msg);
                    IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
                        SELECT 'ERROR' AS status, NULL AS subledg_id, NULL AS subledg_code,
                               IFNULL(v_gen_msg, 'Unable to generate subledger code') AS message;
                    ELSE
                        SET v_code = CONVERT(v_gen_code USING utf8mb4) COLLATE utf8mb4_0900_ai_ci;
                    END IF;
                END IF;

                IF v_code IS NOT NULL THEN
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_acct_subledger WHERE UPPER(SubLedg_Code) = UPPER(v_code);

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, NULL AS subledg_id, NULL AS subledg_code,
                               'Subledger code already exists' AS message;
                    ELSE
                        SELECT COUNT(*) INTO v_dup
                        FROM mst_acct_subledger
                        WHERE Ledger_Id = p_ledger_id
                          AND LOWER(SubLedg_Name) = LOWER(v_name);

                        IF v_dup > 0 THEN
                            SELECT 'ERROR' AS status, NULL AS subledg_id, NULL AS subledg_code,
                                   'Subledger name already exists for this ledger' AS message;
                        ELSE
                            INSERT INTO mst_acct_subledger
                                (SubLedg_Code, SubLedg_Name, Ledger_Id, Is_Active, Created_By, Created_At)
                            VALUES
                                (v_code, v_name, p_ledger_id, IFNULL(p_is_active, 1), p_created_by, NOW());

                            SET v_new_id = LAST_INSERT_ID();

                            SELECT 'SUCCESS' AS status, v_new_id AS subledg_id, v_code AS subledg_code,
                                   'Account subledger created successfully' AS message;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;

    ELSEIF UPPER(p_action) = 'EDIT' THEN
        SELECT COUNT(*) INTO v_exists FROM mst_acct_subledger WHERE SubLedg_Id = p_subledg_id;

        IF v_exists = 0 THEN
            SELECT 'ERROR' AS status, p_subledg_id AS subledg_id, NULL AS subledg_code,
                   'Subledger not found' AS message;
        ELSEIF v_name IS NULL THEN
            SELECT 'ERROR' AS status, p_subledg_id AS subledg_id, NULL AS subledg_code,
                   'Subledger name is required' AS message;
        ELSEIF p_ledger_id IS NULL OR p_ledger_id < 1 THEN
            SELECT 'ERROR' AS status, p_subledg_id AS subledg_id, NULL AS subledg_code,
                   'Ledger is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_ledger_exists FROM mst_acct_ledger WHERE Ledger_Id = p_ledger_id;

            IF v_ledger_exists = 0 THEN
                SELECT 'ERROR' AS status, p_subledg_id AS subledg_id, NULL AS subledg_code,
                       'Ledger not found' AS message;
            ELSE
                IF v_code IS NULL THEN
                    SELECT SubLedg_Code INTO v_code FROM mst_acct_subledger WHERE SubLedg_Id = p_subledg_id;
                END IF;

                SELECT COUNT(*) INTO v_dup
                FROM mst_acct_subledger
                WHERE UPPER(SubLedg_Code) = UPPER(v_code)
                  AND SubLedg_Id <> p_subledg_id;

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, p_subledg_id AS subledg_id, NULL AS subledg_code,
                           'Subledger code already exists' AS message;
                ELSE
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_acct_subledger
                    WHERE Ledger_Id = p_ledger_id
                      AND LOWER(SubLedg_Name) = LOWER(v_name)
                      AND SubLedg_Id <> p_subledg_id;

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, p_subledg_id AS subledg_id, NULL AS subledg_code,
                               'Subledger name already exists for this ledger' AS message;
                    ELSE
                        UPDATE mst_acct_subledger
                        SET SubLedg_Code = v_code,
                            SubLedg_Name = v_name,
                            Ledger_Id = p_ledger_id,
                            Is_Active = IFNULL(p_is_active, Is_Active)
                        WHERE SubLedg_Id = p_subledg_id;

                        SELECT 'SUCCESS' AS status, p_subledg_id AS subledg_id, v_code AS subledg_code,
                               'Account subledger updated successfully' AS message;
                    END IF;
                END IF;
            END IF;
        END IF;

    ELSE
        SELECT 'ERROR' AS status, p_subledg_id AS subledg_id, NULL AS subledg_code,
               'Invalid action. Use ADD or EDIT' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_ACCT_SUBLEDGER_BRANCH_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_SUBLEDGER_BRANCH_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_id INT,
    IN p_branch_id SMALLINT,
    IN p_subledg_id INT,
    IN p_is_active TINYINT,
    IN p_created_by INT
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_branch_exists INT DEFAULT 0;
    DECLARE v_sub_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;
    DECLARE v_new_id INT DEFAULT NULL;

    IF UPPER(p_action) = 'ADD' THEN
        IF p_branch_id IS NULL OR p_branch_id < 1 THEN
            SELECT 'ERROR' AS status, NULL AS id, 'Branch is required' AS message;
        ELSEIF p_subledg_id IS NULL OR p_subledg_id < 1 THEN
            SELECT 'ERROR' AS status, NULL AS id, 'Subledger is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_branch_exists
            FROM priomicro_core.mst_org_branch
            WHERE Branch_Id = p_branch_id;

            SELECT COUNT(*) INTO v_sub_exists
            FROM mst_acct_subledger
            WHERE SubLedg_Id = p_subledg_id;

            IF v_branch_exists = 0 THEN
                SELECT 'ERROR' AS status, NULL AS id, 'Branch not found' AS message;
            ELSEIF v_sub_exists = 0 THEN
                SELECT 'ERROR' AS status, NULL AS id, 'Subledger not found' AS message;
            ELSE
                SELECT COUNT(*) INTO v_dup
                FROM mst_acct_subledger_branch
                WHERE Branch_Id = p_branch_id
                  AND SubLedg_Id = p_subledg_id;

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, NULL AS id,
                           'Subledger already mapped to this branch' AS message;
                ELSE
                    INSERT INTO mst_acct_subledger_branch
                        (Branch_Id, SubLedg_Id, Is_Active, Created_By, Created_At)
                    VALUES
                        (p_branch_id, p_subledg_id, IFNULL(p_is_active, 1), p_created_by, NOW());

                    SET v_new_id = LAST_INSERT_ID();

                    SELECT 'SUCCESS' AS status, v_new_id AS id,
                           'Subledger branch mapping created successfully' AS message;
                END IF;
            END IF;
        END IF;

    ELSEIF UPPER(p_action) = 'EDIT' THEN
        SELECT COUNT(*) INTO v_exists FROM mst_acct_subledger_branch WHERE Id = p_id;

        IF v_exists = 0 THEN
            SELECT 'ERROR' AS status, p_id AS id, 'Mapping not found' AS message;
        ELSEIF p_branch_id IS NULL OR p_branch_id < 1 THEN
            SELECT 'ERROR' AS status, p_id AS id, 'Branch is required' AS message;
        ELSEIF p_subledg_id IS NULL OR p_subledg_id < 1 THEN
            SELECT 'ERROR' AS status, p_id AS id, 'Subledger is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_branch_exists
            FROM priomicro_core.mst_org_branch
            WHERE Branch_Id = p_branch_id;

            SELECT COUNT(*) INTO v_sub_exists
            FROM mst_acct_subledger
            WHERE SubLedg_Id = p_subledg_id;

            IF v_branch_exists = 0 THEN
                SELECT 'ERROR' AS status, p_id AS id, 'Branch not found' AS message;
            ELSEIF v_sub_exists = 0 THEN
                SELECT 'ERROR' AS status, p_id AS id, 'Subledger not found' AS message;
            ELSE
                SELECT COUNT(*) INTO v_dup
                FROM mst_acct_subledger_branch
                WHERE Branch_Id = p_branch_id
                  AND SubLedg_Id = p_subledg_id
                  AND Id <> p_id;

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, p_id AS id,
                           'Subledger already mapped to this branch' AS message;
                ELSE
                    UPDATE mst_acct_subledger_branch
                    SET Branch_Id = p_branch_id,
                        SubLedg_Id = p_subledg_id,
                        Is_Active = IFNULL(p_is_active, Is_Active)
                    WHERE Id = p_id;

                    SELECT 'SUCCESS' AS status, p_id AS id,
                           'Subledger branch mapping updated successfully' AS message;
                END IF;
            END IF;
        END IF;

    ELSE
        SELECT 'ERROR' AS status, p_id AS id, 'Invalid action. Use ADD or EDIT' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_ACCT_SUBLEDGER_BRANCH_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_SUBLEDGER_BRANCH_LIST`(
    IN p_id INT,
    IN p_subledg_id INT,
    IN p_branch_id SMALLINT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_acct_subledger_branch sb
    WHERE (p_id IS NULL OR sb.Id = p_id)
      AND (p_subledg_id IS NULL OR sb.SubLedg_Id = p_subledg_id)
      AND (p_branch_id IS NULL OR sb.Branch_Id = p_branch_id)
      AND (p_is_active IS NULL OR IFNULL(sb.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        sb.Id,
        sb.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        sb.SubLedg_Id,
        s.SubLedg_Code,
        s.SubLedg_Name,
        s.Ledger_Id,
        l.Ledger_Code,
        l.Ledger_Name,
        sb.Is_Active,
        sb.Created_By,
        sb.Created_At
    FROM mst_acct_subledger_branch sb
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = sb.Branch_Id
    LEFT JOIN mst_acct_subledger s ON s.SubLedg_Id = sb.SubLedg_Id
    LEFT JOIN mst_acct_ledger l ON l.Ledger_Id = s.Ledger_Id
    WHERE (p_id IS NULL OR sb.Id = p_id)
      AND (p_subledg_id IS NULL OR sb.SubLedg_Id = p_subledg_id)
      AND (p_branch_id IS NULL OR sb.Branch_Id = p_branch_id)
      AND (p_is_active IS NULL OR IFNULL(sb.Is_Active, 0) = p_is_active)
    ORDER BY sb.Branch_Id ASC, sb.SubLedg_Id ASC, sb.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_ACCT_SUBLEDGER_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ACCT_SUBLEDGER_LIST`(
    IN p_subledg_id INT,
    IN p_ledger_id INT,
    IN p_keyword VARCHAR(100),
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_acct_subledger s
    WHERE (p_subledg_id IS NULL OR s.SubLedg_Id = p_subledg_id)
      AND (p_ledger_id IS NULL OR s.Ledger_Id = p_ledger_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR s.SubLedg_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(s.SubLedg_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_is_active IS NULL OR IFNULL(s.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        s.SubLedg_Id,
        s.SubLedg_Code,
        s.SubLedg_Name,
        s.Ledger_Id,
        l.Ledger_Code,
        l.Ledger_Name,
        l.MainHd_Id,
        h.MainHd_Code,
        h.MainHd_Name,
        s.Is_Active,
        s.Created_By,
        s.Created_At,
        (
            SELECT COUNT(*) FROM mst_acct_subledger_branch b WHERE b.SubLedg_Id = s.SubLedg_Id
        ) AS Branch_Count
    FROM mst_acct_subledger s
    LEFT JOIN mst_acct_ledger l ON l.Ledger_Id = s.Ledger_Id
    LEFT JOIN mst_acct_head h ON h.MainHd_Id = l.MainHd_Id
    WHERE (p_subledg_id IS NULL OR s.SubLedg_Id = p_subledg_id)
      AND (p_ledger_id IS NULL OR s.Ledger_Id = p_ledger_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR s.SubLedg_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(s.SubLedg_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_is_active IS NULL OR IFNULL(s.Is_Active, 0) = p_is_active)
    ORDER BY s.SubLedg_Code ASC, s.SubLedg_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_APPL_OPTIONS_LIST` */;
