CREATE DEFINER=`priority`@`%` PROCEDURE `USP_APPL_OPTIONS_LIST`(
    IN p_opt_grp_id SMALLINT,
    IN p_is_active TINYINT
)
BEGIN
    SELECT
        o.Option_Id,
        o.Opt_Grp_Id,
        o.Opt_Group,
        o.Opt_Code,
        o.Opt_Description,
        CAST(o.Is_Active AS UNSIGNED) AS Is_Active,
        o.Srl_No
    FROM mst_appl_options o
    WHERE (p_opt_grp_id IS NULL OR o.Opt_Grp_Id = p_opt_grp_id)
      AND (p_is_active IS NULL OR CAST(o.Is_Active AS UNSIGNED) = p_is_active)
    ORDER BY o.Opt_Grp_Id ASC, IFNULL(o.Srl_No, 255) ASC, o.Opt_Code ASC;
END ;;
DELIMITER ;
