CREATE DEFINER=`priority`@`%` PROCEDURE `USP_AUDIT_LOG_INSERT`(
    IN p_user_id SMALLINT UNSIGNED,
    IN p_menu_name VARCHAR(50),
    IN p_table_name VARCHAR(100),
    IN p_record_id BIGINT UNSIGNED,
    IN p_action TINYINT,
    IN p_old_values LONGTEXT,
    IN p_new_values LONGTEXT,
    IN p_ip_address VARCHAR(50),
    IN p_user_agent VARCHAR(500)
)
BEGIN
    DECLARE v_old LONGTEXT DEFAULT NULL;
    DECLARE v_new LONGTEXT DEFAULT NULL;

    IF p_action IS NULL OR p_action < 1 OR p_action > 5 THEN
        SELECT 'ERROR' AS status, NULL AS audit_id,
               'Invalid audit action. Use 1=Create, 2=Update, 3=Delete, 4=Login, 5=Logout' AS message;
    ELSE
        SET v_old = NULLIF(TRIM(IFNULL(p_old_values, '')), '');
        SET v_new = NULLIF(TRIM(IFNULL(p_new_values, '')), '');

        IF v_old IS NOT NULL AND JSON_VALID(v_old) = 0 THEN
            SELECT 'ERROR' AS status, NULL AS audit_id, 'Old values must be valid JSON' AS message;
        ELSEIF v_new IS NOT NULL AND JSON_VALID(v_new) = 0 THEN
            SELECT 'ERROR' AS status, NULL AS audit_id, 'New values must be valid JSON' AS message;
        ELSE
            INSERT INTO trans_audit_log (
                User_id, Menu_name, Table_name, Record_id, Action,
                Old_values, New_values, Ip_address, user_agent
            ) VALUES (
                p_user_id, p_menu_name, p_table_name, p_record_id, p_action,
                v_old, v_new, p_ip_address, p_user_agent
            );

            SELECT 'SUCCESS' AS status, LAST_INSERT_ID() AS audit_id,
                   'Audit log created successfully' AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
