CREATE DEFINER=`priority`@`%` PROCEDURE `USP_AUDIT_LOG_LIST`(
    IN p_audit_id INT UNSIGNED,
    IN p_user_id SMALLINT UNSIGNED,
    IN p_menu_name VARCHAR(50),
    IN p_table_name VARCHAR(100),
    IN p_record_id BIGINT UNSIGNED,
    IN p_action TINYINT,
    IN p_keyword VARCHAR(100),
    IN p_from_date DATETIME,
    IN p_to_date DATETIME,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM trans_audit_log a
    WHERE (p_audit_id IS NULL OR a.Audit_id = p_audit_id)
      AND (p_user_id IS NULL OR a.User_id = p_user_id)
      AND (p_menu_name IS NULL OR p_menu_name = '' OR a.Menu_name = p_menu_name)
      AND (p_table_name IS NULL OR p_table_name = '' OR a.Table_name = p_table_name)
      AND (p_record_id IS NULL OR a.Record_id = p_record_id)
      AND (p_action IS NULL OR a.Action = p_action)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR a.Menu_name LIKE CONCAT('%', p_keyword, '%')
          OR a.Table_name LIKE CONCAT('%', p_keyword, '%')
          OR a.Ip_address LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_from_date IS NULL OR a.Created_at >= p_from_date)
      AND (p_to_date IS NULL OR a.Created_at <= p_to_date);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        a.Audit_id,
        a.User_id,
        a.Menu_name,
        a.Table_name,
        a.Record_id,
        a.Action,
        CASE a.Action
            WHEN 1 THEN 'Create'
            WHEN 2 THEN 'Update'
            WHEN 3 THEN 'Delete'
            WHEN 4 THEN 'Login'
            WHEN 5 THEN 'Logout'
            ELSE 'Unknown'
        END AS Action_Name,
        a.Old_values,
        a.New_values,
        a.Ip_address,
        a.user_agent,
        a.Created_at
    FROM trans_audit_log a
    WHERE (p_audit_id IS NULL OR a.Audit_id = p_audit_id)
      AND (p_user_id IS NULL OR a.User_id = p_user_id)
      AND (p_menu_name IS NULL OR p_menu_name = '' OR a.Menu_name = p_menu_name)
      AND (p_table_name IS NULL OR p_table_name = '' OR a.Table_name = p_table_name)
      AND (p_record_id IS NULL OR a.Record_id = p_record_id)
      AND (p_action IS NULL OR a.Action = p_action)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR a.Menu_name LIKE CONCAT('%', p_keyword, '%')
          OR a.Table_name LIKE CONCAT('%', p_keyword, '%')
          OR a.Ip_address LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_from_date IS NULL OR a.Created_at >= p_from_date)
      AND (p_to_date IS NULL OR a.Created_at <= p_to_date)
    ORDER BY a.Created_at DESC, a.Audit_id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
