CREATE DEFINER=`priority`@`%` PROCEDURE `USP_AUTH_GET_USER_ROLES`(IN p_user_id SMALLINT)
BEGIN
    SELECT
        ur.Usr_Role_Id,
        ur.Role_Id,
        ur.Status AS User_Role_Status,
        r.Role_Name,
        r.Is_Admin,
        r.Status AS Role_Status
    FROM mst_user_role ur
    INNER JOIN mst_role r ON r.Id = ur.Role_Id
    WHERE ur.User_Id = p_user_id
      AND ur.Status = 1
      AND r.Status = 1
    ORDER BY r.Is_Admin DESC, ur.Usr_Role_Id ASC;
END ;;
