CREATE DEFINER=`priority`@`%` PROCEDURE `USP_CENTER_ADD_EDIT`(
    IN p_mode VARCHAR(10),
    IN p_center_id SMALLINT,
    IN p_branch_id SMALLINT,
    IN p_center_name VARCHAR(100),
    IN p_center_address VARCHAR(255),
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_center_id SMALLINT DEFAULT NULL;
    DECLARE v_branch_exists INT DEFAULT 0;
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;

    IF p_mode IS NULL OR p_mode NOT IN ('ADD', 'EDIT') THEN
        SELECT 'ERROR' AS status, NULL AS center_id, 'Invalid mode. Use ADD or EDIT' AS message;
    ELSEIF p_branch_id IS NULL OR p_branch_id < 1 THEN
        SELECT 'ERROR' AS status, NULL AS center_id, 'Branch is required' AS message;
    ELSEIF p_center_name IS NULL OR TRIM(p_center_name) = '' THEN
        SELECT 'ERROR' AS status, NULL AS center_id, 'Center name is required' AS message;
    ELSE
        SELECT COUNT(*) INTO v_branch_exists
        FROM priomicro_core.mst_org_branch
        WHERE Branch_Id = p_branch_id
          AND IFNULL(Is_Active, 0) = 1;

        IF v_branch_exists = 0 THEN
            SELECT 'ERROR' AS status, NULL AS center_id, 'Active branch not found' AS message;
        ELSEIF p_mode = 'ADD' THEN
            SELECT COUNT(*) INTO v_dup
            FROM mst_center
            WHERE Branch_Id = p_branch_id
              AND LOWER(TRIM(Center_Name)) = LOWER(TRIM(p_center_name));

            IF v_dup > 0 THEN
                SELECT 'ERROR' AS status, NULL AS center_id, 'Center name already exists for this branch' AS message;
            ELSE
                INSERT INTO mst_center (Branch_Id, Center_Name, Center_Address, Is_Active)
                VALUES (
                    p_branch_id,
                    TRIM(p_center_name),
                    NULLIF(TRIM(IFNULL(p_center_address, '')), ''),
                    IFNULL(p_is_active, 1)
                );

                SET v_center_id = LAST_INSERT_ID();
                SELECT 'SUCCESS' AS status, v_center_id AS center_id, 'Center created successfully' AS message;
            END IF;
        ELSE
            IF p_center_id IS NULL OR p_center_id < 1 THEN
                SELECT 'ERROR' AS status, NULL AS center_id, 'Center id is required for EDIT' AS message;
            ELSE
                SELECT COUNT(*) INTO v_exists
                FROM mst_center
                WHERE Center_Id = p_center_id;

                IF v_exists = 0 THEN
                    SELECT 'ERROR' AS status, p_center_id AS center_id, 'Center not found' AS message;
                ELSE
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_center
                    WHERE Branch_Id = p_branch_id
                      AND LOWER(TRIM(Center_Name)) = LOWER(TRIM(p_center_name))
                      AND Center_Id <> p_center_id;

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, p_center_id AS center_id, 'Center name already exists for this branch' AS message;
                    ELSE
                        UPDATE mst_center
                        SET
                            Branch_Id = p_branch_id,
                            Center_Name = TRIM(p_center_name),
                            Center_Address = NULLIF(TRIM(IFNULL(p_center_address, '')), ''),
                            Is_Active = IFNULL(p_is_active, Is_Active)
                        WHERE Center_Id = p_center_id;

                        SELECT 'SUCCESS' AS status, p_center_id AS center_id, 'Center updated successfully' AS message;
                    END IF;
                END IF;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_CENTER_LIST` */;
