CREATE DEFINER=`priority`@`%` PROCEDURE `USP_CODE_SERIES_GENERATE`(
    IN p_module_key VARCHAR(50),
    OUT p_generated_code VARCHAR(150),
    OUT p_status VARCHAR(10),
    OUT p_message VARCHAR(255)
)
BEGIN
    DECLARE v_series_id SMALLINT UNSIGNED DEFAULT NULL;
    DECLARE v_prefix VARCHAR(50);
    DECLARE v_suffix VARCHAR(50);
    DECLARE v_counter INT UNSIGNED;
    DECLARE v_padding TINYINT UNSIGNED;
    DECLARE v_lock_name VARCHAR(128);
    DECLARE v_got_lock INT DEFAULT 0;

    SET p_generated_code = NULL;
    SET p_status = 'ERROR';
    SET p_message = 'Code series not configured or inactive';

    SET v_lock_name = CONCAT('mfin_code_series_', IFNULL(TRIM(p_module_key), ''));
    SET v_got_lock = GET_LOCK(v_lock_name, 10);

    IF v_got_lock <> 1 THEN
        SET p_message = 'Unable to acquire code series lock';
    ELSE
        SELECT Series_id, Prefix, Suffix, Next_counter, Padding_digits
        INTO v_series_id, v_prefix, v_suffix, v_counter, v_padding
        FROM mst_code_series
        WHERE Module_key = p_module_key
          AND Status = 1
        LIMIT 1;

        IF v_series_id IS NOT NULL THEN
            SET p_generated_code = CONCAT(
                IFNULL(v_prefix, ''),
                LPAD(v_counter, v_padding, '0'),
                IFNULL(v_suffix, '')
            );

            UPDATE mst_code_series
            SET Next_counter = Next_counter + 1,
                Gen_Code = LEFT(p_generated_code, 50),
                Updated_at = NOW()
            WHERE Series_id = v_series_id;

            SET p_status = 'SUCCESS';
            SET p_message = 'Code generated successfully';
        END IF;

        DO RELEASE_LOCK(v_lock_name);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_CODE_SERIES_LIST` */;
