CREATE DEFINER=`priority`@`%` PROCEDURE `USP_CODE_SERIES_LIST`(
    IN p_series_id SMALLINT UNSIGNED,
    IN p_module_key VARCHAR(50),
    IN p_keyword VARCHAR(150),
    IN p_status TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_code_series cs
    WHERE (p_series_id IS NULL OR cs.Series_id = p_series_id)
      AND (p_module_key IS NULL OR p_module_key = '' OR cs.Module_key = p_module_key)
      AND (
          p_keyword IS NULL
          OR p_keyword = ''
          OR cs.Module_name LIKE CONCAT('%', p_keyword, '%')
          OR cs.Module_key LIKE CONCAT('%', p_keyword, '%')
          OR cs.Prefix LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(cs.Gen_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_status IS NULL OR cs.Status = p_status);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE
            WHEN v_total = 0 THEN 1
            ELSE CEIL(v_total / v_per_page)
        END AS last_page;

    SELECT
        cs.Series_id,
        cs.Module_key,
        cs.Module_name,
        cs.Prefix,
        cs.Next_counter,
        cs.Padding_digits,
        cs.Suffix,
        cs.Gen_Code,
        cs.Status,
        CONCAT(
            IFNULL(cs.Prefix, ''),
            LPAD(cs.Next_counter, cs.Padding_digits, '0'),
            IFNULL(cs.Suffix, '')
        ) AS Formatted_sample,
        cs.Created_by,
        cs.Created_at,
        cs.Updated_at
    FROM mst_code_series cs
    WHERE (p_series_id IS NULL OR cs.Series_id = p_series_id)
      AND (p_module_key IS NULL OR p_module_key = '' OR cs.Module_key = p_module_key)
      AND (
          p_keyword IS NULL
          OR p_keyword = ''
          OR cs.Module_name LIKE CONCAT('%', p_keyword, '%')
          OR cs.Module_key LIKE CONCAT('%', p_keyword, '%')
          OR cs.Prefix LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(cs.Gen_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_status IS NULL OR cs.Status = p_status)
    ORDER BY cs.Series_id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
