CREATE DEFINER=`priority`@`%` PROCEDURE `USP_CODE_SERIES_NEXT`(
    IN p_module_key VARCHAR(50)
)
BEGIN
    DECLARE v_code VARCHAR(150);
    DECLARE v_status VARCHAR(10);
    DECLARE v_message VARCHAR(255);

    CALL USP_CODE_SERIES_GENERATE(p_module_key, v_code, v_status, v_message);

    SELECT
        v_status AS status,
        v_code AS generated_code,
        v_message AS message,
        p_module_key AS module_key;
END ;;
