CREATE DEFINER=`priority`@`%` PROCEDURE `USP_CODE_SERIES_UPDATE`(
    IN p_series_id SMALLINT UNSIGNED,
    IN p_prefix VARCHAR(50),
    IN p_next_counter INT UNSIGNED,
    IN p_padding_digits TINYINT UNSIGNED,
    IN p_suffix VARCHAR(50),
    IN p_status TINYINT
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_prefix VARCHAR(50);
    DECLARE v_suffix VARCHAR(50);
    DECLARE v_gen_code VARCHAR(50);

    SELECT COUNT(*) INTO v_exists
    FROM mst_code_series
    WHERE Series_id = p_series_id;

    IF v_exists = 0 THEN
        SELECT 'ERROR' AS status, p_series_id AS series_id, 'Code series not found' AS message;
    ELSEIF p_next_counter IS NULL OR p_next_counter < 1 THEN
        SELECT 'ERROR' AS status, p_series_id AS series_id, 'Next counter must be at least 1' AS message;
    ELSEIF p_padding_digits IS NULL OR p_padding_digits < 1 OR p_padding_digits > 12 THEN
        SELECT 'ERROR' AS status, p_series_id AS series_id, 'Padding digits must be between 1 and 12' AS message;
    ELSE
        SELECT
            IFNULL(p_prefix, Prefix),
            IFNULL(p_suffix, Suffix)
        INTO v_prefix, v_suffix
        FROM mst_code_series
        WHERE Series_id = p_series_id;

        SET v_gen_code = CONCAT(
            IFNULL(v_prefix, ''),
            LPAD(p_next_counter, p_padding_digits, '0'),
            IFNULL(v_suffix, '')
        );

        UPDATE mst_code_series
        SET
            Prefix = IFNULL(p_prefix, Prefix),
            Next_counter = p_next_counter,
            Padding_digits = p_padding_digits,
            Suffix = IFNULL(p_suffix, Suffix),
            Gen_Code = v_gen_code,
            Status = IFNULL(p_status, Status),
            Updated_at = NOW()
        WHERE Series_id = p_series_id;

        SELECT 'SUCCESS' AS status, p_series_id AS series_id, 'Code series updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_ACCOUNT_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_ACCOUNT_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_account_id INT,
    IN p_appl_no VARCHAR(25),
    IN p_appl_date DATE,
    IN p_deposit_type_cd INT,
    IN p_scheme_id INT,
    IN p_special_catg_cd INT,
    IN p_cust_type_cd INT,
    IN p_cust_id_primary INT,
    IN p_cust_id_joint1 INT,
    IN p_cust_id_joint2 INT,
    IN p_holder_name VARCHAR(300),
    IN p_op_mode_cd INT,
    IN p_nom_regd TINYINT,
    IN p_fo_id INT,
    IN p_branch_id INT,
    IN p_status_cd INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_action VARCHAR(10);
    DECLARE v_account_id INT DEFAULT NULL;
    DECLARE v_status INT DEFAULT 1;
    DECLARE v_appl_no VARCHAR(25);
    DECLARE v_holder VARCHAR(300);
    DECLARE v_deposit_type INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_fo INT DEFAULT NULL;
    DECLARE v_nom TINYINT DEFAULT 0;
    DECLARE v_seq INT DEFAULT 0;
    DECLARE v_has_activity INT DEFAULT 0;

    DECLARE v_cur_scheme INT DEFAULT NULL;
    DECLARE v_cur_deposit_type INT DEFAULT NULL;
    DECLARE v_cur_cust_type INT DEFAULT NULL;
    DECLARE v_cur_primary INT DEFAULT NULL;
    DECLARE v_cur_joint1 INT DEFAULT NULL;
    DECLARE v_cur_joint2 INT DEFAULT NULL;
    DECLARE v_cur_branch INT DEFAULT NULL;
    DECLARE v_cur_fo INT DEFAULT NULL;
    DECLARE v_cur_appl_no VARCHAR(25) DEFAULT NULL;
    DECLARE v_cur_closing DATE DEFAULT NULL;

    DECLARE v_scheme_type INT DEFAULT NULL;
    DECLARE v_scheme_active INT DEFAULT 0;
    DECLARE v_cust_branch INT DEFAULT NULL;
    DECLARE v_cust_fo INT DEFAULT NULL;
    DECLARE v_cust_status INT DEFAULT NULL;
    DECLARE v_cust_name VARCHAR(300) DEFAULT NULL;
    DECLARE v_cust_since DATE DEFAULT NULL;
    DECLARE v_cust_dob DATE DEFAULT NULL;
    DECLARE v_j1_name VARCHAR(150) DEFAULT NULL;
    DECLARE v_j1_status INT DEFAULT NULL;
    DECLARE v_j2_name VARCHAR(150) DEFAULT NULL;
    DECLARE v_j2_status INT DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_appl_no = UPPER(NULLIF(TRIM(IFNULL(p_appl_no, '')), ''));
    SET v_holder = NULLIF(TRIM(IFNULL(p_holder_name, '')), '');

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Scheme_Id), MAX(Deposit_Type_Cd), MAX(Cust_Type_Cd), MAX(Cust_Id_Primay),
               MAX(Cust_Id_Joint1), MAX(Cust_Id_Joint2), MAX(Branch_Id), MAX(FO_Id), MAX(Appl_No), MAX(Closing_Date)
        INTO v_cnt, v_cur_scheme, v_cur_deposit_type, v_cur_cust_type, v_cur_primary,
             v_cur_joint1, v_cur_joint2, v_cur_branch, v_cur_fo, v_cur_appl_no, v_cur_closing
        FROM mst_deposit_account WHERE Account_Id = p_account_id;

        IF p_account_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Deposit account not found';
        ELSEIF v_cur_closing IS NOT NULL THEN
            SET v_err = 'Closed deposit account cannot be edited';
        ELSE
            SELECT (SELECT COUNT(*) FROM mst_deposit_account_sb WHERE Account_Id = p_account_id)
                 + (SELECT COUNT(*) FROM mst_deposit_account_td WHERE Account_Id = p_account_id)
                 + (SELECT COUNT(*) FROM trans_savings_transaction WHERE Account_Id = p_account_id)
            INTO v_has_activity;
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        SET v_status = IFNULL(p_status_cd, 1);
        IF v_status NOT IN (1, 7) THEN
            SET v_err = 'New account status must be 1 (Active) or 7 (KYC Pending)';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        IF p_appl_date IS NULL THEN
            SET v_err = 'Application date is required';
        ELSEIF p_appl_date > CURDATE() THEN
            SET v_err = 'Application date cannot be in the future';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Deposit_Type_Cd), MAX(IFNULL(Is_Active, 0))
        INTO v_cnt, v_scheme_type, v_scheme_active
        FROM mst_deposit_scheme WHERE Scheme_Id = p_scheme_id;

        IF p_scheme_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Deposit scheme not found';
        ELSEIF v_scheme_active <> 1 AND NOT (v_action = 'EDIT' AND p_scheme_id = v_cur_scheme) THEN
            SET v_err = 'Deposit scheme is inactive';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_deposit_type = IFNULL(p_deposit_type_cd, v_scheme_type);
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 3 AND Opt_Code = v_deposit_type AND Is_Active = 1;
        IF v_deposit_type IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid deposit type';
        ELSEIF v_scheme_type IS NOT NULL AND v_deposit_type <> v_scheme_type THEN
            SET v_err = 'Deposit type does not match the deposit type of the selected scheme';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 34 AND Opt_Code = p_cust_type_cd AND Is_Active = 1;
        IF p_cust_type_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid customer type';
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' AND v_has_activity > 0
       AND (p_scheme_id <> v_cur_scheme OR v_deposit_type <> v_cur_deposit_type
            OR p_cust_type_cd <> v_cur_cust_type OR IFNULL(p_cust_id_primary, 0) <> v_cur_primary) THEN
        SET v_err = 'Scheme, deposit type and primary customer cannot be changed once SB/TD details or transactions exist';
    END IF;

    IF v_err IS NULL AND p_cust_type_cd = 1 THEN
        SELECT COUNT(*), MAX(Branch_Id), MAX(FO_Id), MAX(Current_Status_Cd), MAX(Group_Name), MAX(Formation_Date)
        INTO v_cnt, v_cust_branch, v_cust_fo, v_cust_status, v_cust_name, v_cust_since
        FROM mst_group WHERE Group_Id = p_cust_id_primary;

        IF p_cust_id_primary IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Group not found';
        ELSEIF IFNULL(v_cust_status, 0) <> 1
               AND NOT (v_action = 'EDIT' AND v_cur_cust_type = 1 AND p_cust_id_primary = v_cur_primary) THEN
            SET v_err = 'Only active groups can open a deposit account';
        ELSEIF p_cust_id_joint1 IS NOT NULL OR p_cust_id_joint2 IS NOT NULL THEN
            SET v_err = 'Group accounts cannot have joint holders';
        END IF;
    ELSEIF v_err IS NULL AND p_cust_type_cd = 2 THEN
        SELECT COUNT(*), MAX(Branch_Id), MAX(FO_Id), MAX(Current_Status_Cd), MAX(Member_Name), MAX(Joining_Date), MAX(Date_of_Birth)
        INTO v_cnt, v_cust_branch, v_cust_fo, v_cust_status, v_cust_name, v_cust_since, v_cust_dob
        FROM mst_member WHERE Member_Id = p_cust_id_primary;

        IF p_cust_id_primary IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Primary member not found';
        ELSEIF IFNULL(v_cust_status, 0) <> 1
               AND NOT (v_action = 'EDIT' AND v_cur_cust_type = 2 AND p_cust_id_primary = v_cur_primary) THEN
            SET v_err = 'Only active members can open a deposit account';
        END IF;
    END IF;

    IF v_err IS NULL AND v_cust_since IS NOT NULL AND p_appl_date < v_cust_since THEN
        SET v_err = IF(p_cust_type_cd = 1,
                       'Application date cannot be before the group formation date',
                       'Application date cannot be before the member joining date');
    END IF;

    
    IF v_err IS NULL AND p_cust_type_cd = 2 THEN
        IF p_cust_id_joint2 IS NOT NULL AND p_cust_id_joint1 IS NULL THEN
            SET v_err = 'Joint holder 1 is required before joint holder 2';
        ELSEIF p_cust_id_joint1 IS NOT NULL AND p_cust_id_joint1 = p_cust_id_primary THEN
            SET v_err = 'Joint holder 1 cannot be the primary holder';
        ELSEIF p_cust_id_joint2 IS NOT NULL AND p_cust_id_joint2 IN (p_cust_id_primary, p_cust_id_joint1) THEN
            SET v_err = 'Joint holder 2 must be different from the primary holder and joint holder 1';
        END IF;
    END IF;

    IF v_err IS NULL AND p_cust_id_joint1 IS NOT NULL THEN
        SELECT COUNT(*), MAX(Member_Name), MAX(Current_Status_Cd) INTO v_cnt, v_j1_name, v_j1_status
        FROM mst_member WHERE Member_Id = p_cust_id_joint1;
        IF v_cnt = 0 THEN
            SET v_err = 'Joint holder 1 not found';
        ELSEIF IFNULL(v_j1_status, 0) <> 1 AND NOT (v_action = 'EDIT' AND p_cust_id_joint1 = IFNULL(v_cur_joint1, 0)) THEN
            SET v_err = 'Joint holder 1 is not an active member';
        END IF;
    END IF;

    IF v_err IS NULL AND p_cust_id_joint2 IS NOT NULL THEN
        SELECT COUNT(*), MAX(Member_Name), MAX(Current_Status_Cd) INTO v_cnt, v_j2_name, v_j2_status
        FROM mst_member WHERE Member_Id = p_cust_id_joint2;
        IF v_cnt = 0 THEN
            SET v_err = 'Joint holder 2 not found';
        ELSEIF IFNULL(v_j2_status, 0) <> 1 AND NOT (v_action = 'EDIT' AND p_cust_id_joint2 = IFNULL(v_cur_joint2, 0)) THEN
            SET v_err = 'Joint holder 2 is not an active member';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 9 AND Opt_Code = p_op_mode_cd AND Is_Active = 1;
        IF p_op_mode_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid operation mode';
        ELSEIF p_op_mode_cd = 1 AND p_cust_id_joint1 IS NOT NULL THEN
            SET v_err = 'Single operation mode cannot have joint holders';
        ELSEIF p_op_mode_cd IN (2, 3) AND p_cust_id_joint1 IS NULL THEN
            SET v_err = 'Jointly / Either Or Survivor operation needs at least one joint holder';
        ELSEIF p_op_mode_cd = 4 AND (p_cust_id_joint1 IS NULL OR p_cust_id_joint2 IS NULL) THEN
            SET v_err = 'Any 2 Or 3 operation needs two joint holders';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_special_catg_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 11 AND Opt_Code = p_special_catg_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid special category';
        ELSEIF p_cust_type_cd = 1 AND p_special_catg_cd IN (2, 3, 4, 5) THEN
            SET v_err = 'This special category applies to individual accounts only';
        ELSEIF p_special_catg_cd = 2 AND v_cust_dob IS NOT NULL
               AND TIMESTAMPDIFF(YEAR, v_cust_dob, p_appl_date) < 60 THEN
            SET v_err = 'Senior citizen category needs the primary holder to be at least 60 years old';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SET v_branch = IFNULL(p_branch_id, v_cust_branch);
        SELECT COUNT(*) INTO v_cnt
        FROM priomicro_core.mst_org_branch
        WHERE Branch_Id = v_branch
          AND (IFNULL(Is_Active, 0) = 1 OR (v_action = 'EDIT' AND Branch_Id = v_cur_branch));
        IF v_branch IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Active branch not found';
        ELSEIF v_cust_branch IS NOT NULL AND v_branch <> v_cust_branch THEN
            SET v_err = IF(p_cust_type_cd = 1,
                           'Branch must be the branch of the group',
                           'Branch must be the branch of the primary member');
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        IF p_fo_id IS NOT NULL THEN
            SELECT COUNT(*) INTO v_cnt
            FROM mst_staff
            WHERE Staff_Id = p_fo_id
              AND Branch_Id = v_branch
              AND (IFNULL(Status, 0) = 1 OR (v_action = 'EDIT' AND Staff_Id = v_cur_fo));
            IF v_cnt = 0 THEN
                SET v_err = 'Active field officer not found for this branch';
            ELSE
                SET v_fo = p_fo_id;
            END IF;
        ELSEIF v_action = 'ADD' AND v_cust_fo IS NOT NULL THEN
            SELECT MAX(Staff_Id) INTO v_fo
            FROM mst_staff WHERE Staff_Id = v_cust_fo AND Branch_Id = v_branch AND IFNULL(Status, 0) = 1;
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SET v_nom = IFNULL(p_nom_regd, 0);
        IF v_nom NOT IN (0, 1) THEN
            SET v_err = 'Nominee registered must be 1 (yes) or 0 (no)';
        ELSEIF v_nom = 1 AND p_cust_type_cd = 1 THEN
            SET v_err = 'Nominee cannot be registered for a group account';
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_deposit_type = 1 THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account
        WHERE Scheme_Id = p_scheme_id
          AND Cust_Type_Cd = p_cust_type_cd
          AND Cust_Id_Primay = p_cust_id_primary
          AND Closing_Date IS NULL
          AND (v_action = 'ADD' OR Account_Id <> p_account_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Customer already has an open account in this savings scheme';
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_holder IS NULL THEN
        SET v_holder = LEFT(CONCAT_WS(' & ', v_cust_name, v_j1_name, v_j2_name), 300);
    END IF;

    
    IF v_err IS NULL AND v_appl_no IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account
        WHERE UPPER(Appl_No) = v_appl_no AND (v_action = 'ADD' OR Account_Id <> p_account_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Application number already exists';
        END IF;
    END IF;

    IF v_err IS NULL AND v_appl_no IS NULL THEN
        IF v_action = 'EDIT' AND v_cur_appl_no IS NOT NULL THEN
            SET v_appl_no = v_cur_appl_no;
        ELSE
            SELECT COUNT(*) INTO v_seq FROM mst_deposit_account
            WHERE Appl_No LIKE CONCAT('DA-', YEAR(p_appl_date), '-%') FOR UPDATE;
            REPEAT
                SET v_seq = v_seq + 1;
                SET v_appl_no = CONCAT('DA-', YEAR(p_appl_date), '-', LPAD(v_seq, 5, '0'));
                SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account WHERE UPPER(Appl_No) = v_appl_no;
            UNTIL v_cnt = 0 END REPEAT;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_account_id AS account_id, NULL AS appl_no, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_deposit_account (
            Appl_No, Appl_Date, Deposit_Type_Cd, Scheme_Id, Special_Catg_Cd, Cust_Type_Cd,
            Cust_Id_Primay, Cust_Id_Joint1, Cust_Id_Joint2, Holder_Name, Op_Mode_Cd, Nom_Regd,
            FO_Id, Branch_Id, Appl_Status_Cd, Created_By, Created_At
        ) VALUES (
            v_appl_no, p_appl_date, v_deposit_type, p_scheme_id, p_special_catg_cd, p_cust_type_cd,
            p_cust_id_primary, p_cust_id_joint1, p_cust_id_joint2, v_holder, p_op_mode_cd, v_nom,
            v_fo, v_branch, v_status, p_user_id, NOW()
        );

        SET v_account_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_account_id AS account_id, v_appl_no AS appl_no,
               'Deposit account created successfully' AS message;
    ELSE
        UPDATE mst_deposit_account
        SET Appl_No = v_appl_no,
            Appl_Date = p_appl_date,
            Deposit_Type_Cd = v_deposit_type,
            Scheme_Id = p_scheme_id,
            Special_Catg_Cd = p_special_catg_cd,
            Cust_Type_Cd = p_cust_type_cd,
            Cust_Id_Primay = p_cust_id_primary,
            Cust_Id_Joint1 = p_cust_id_joint1,
            Cust_Id_Joint2 = p_cust_id_joint2,
            Holder_Name = v_holder,
            Op_Mode_Cd = p_op_mode_cd,
            Nom_Regd = v_nom,
            FO_Id = v_fo,
            Branch_Id = v_branch
        WHERE Account_Id = p_account_id;

        SELECT 'SUCCESS' AS status, p_account_id AS account_id, v_appl_no AS appl_no,
               'Deposit account updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_ACCOUNT_CLOSE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_ACCOUNT_CLOSE`(
    IN p_account_id INT,
    IN p_closing_date DATE,
    IN p_closing_reason VARCHAR(250),
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT DEFAULT NULL;
    DECLARE v_appl_date DATE DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_balance DECIMAL(12,2) DEFAULT 0;
    DECLARE v_date DATE;
    DECLARE v_reason VARCHAR(250);
    DECLARE v_err VARCHAR(255) DEFAULT NULL;

    SET v_date = IFNULL(p_closing_date, CURDATE());
    SET v_reason = NULLIF(TRIM(IFNULL(p_closing_reason, '')), '');

    SELECT COUNT(*), MAX(Appl_Status_Cd), MAX(Appl_Date), MAX(Closing_Date)
    INTO v_cnt, v_status, v_appl_date, v_closing
    FROM mst_deposit_account WHERE Account_Id = p_account_id;

    IF p_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Deposit account not found';
    ELSEIF v_closing IS NOT NULL THEN
        SET v_err = CONCAT('Deposit account is already closed on ', DATE_FORMAT(v_closing, '%d-%m-%Y'));
    ELSEIF v_status = 4 THEN
        SET v_err = 'Freezed deposit account cannot be closed';
    ELSEIF v_reason IS NULL THEN
        SET v_err = 'Closing reason is required';
    ELSEIF v_date > CURDATE() THEN
        SET v_err = 'Closing date cannot be in the future';
    ELSEIF v_date < v_appl_date THEN
        SET v_err = 'Closing date cannot be before the application date';
    END IF;

    IF v_err IS NULL THEN
        SELECT IFNULL((SELECT SUM(Current_Balance) FROM mst_deposit_account_sb WHERE Account_Id = p_account_id), 0)
             + IFNULL((SELECT SUM(Current_Balance) FROM mst_deposit_account_td WHERE Account_Id = p_account_id), 0)
        INTO v_balance;
        IF v_balance <> 0 THEN
            SET v_err = CONCAT('Account balance must be zero before closing (current balance ', FORMAT(v_balance, 2), ')');
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_account_id AS account_id, v_err AS message;
    ELSE
        UPDATE mst_deposit_account
        SET Closing_Date = v_date, Closing_Reason = v_reason
        WHERE Account_Id = p_account_id;

        SELECT 'SUCCESS' AS status, p_account_id AS account_id, 'Deposit account closed successfully' AS message;
    END IF;
END ;;
DELIMITER ;
