/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_ACCOUNT_LIST`(
    IN p_account_id INT,
    IN p_branch_id INT,
    IN p_fo_id INT,
    IN p_scheme_id INT,
    IN p_deposit_type_cd INT,
    IN p_cust_type_cd INT,
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_op_mode_cd INT,
    IN p_status_cd INT,
    IN p_is_closed TINYINT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_deposit_account a
    LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
    LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
    LEFT JOIN mst_member j1 ON j1.Member_Id = a.Cust_Id_Joint1
    LEFT JOIN mst_member j2 ON j2.Member_Id = a.Cust_Id_Joint2
    WHERE (p_account_id IS NULL OR a.Account_Id = p_account_id)
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
      AND (p_fo_id IS NULL OR a.FO_Id = p_fo_id)
      AND (p_scheme_id IS NULL OR a.Scheme_Id = p_scheme_id)
      AND (p_deposit_type_cd IS NULL OR a.Deposit_Type_Cd = p_deposit_type_cd)
      AND (p_cust_type_cd IS NULL OR a.Cust_Type_Cd = p_cust_type_cd)
      AND (p_member_id IS NULL OR (a.Cust_Type_Cd = 2 AND p_member_id IN (a.Cust_Id_Primay, IFNULL(a.Cust_Id_Joint1, 0), IFNULL(a.Cust_Id_Joint2, 0))))
      AND (p_group_id IS NULL OR (a.Cust_Type_Cd = 1 AND a.Cust_Id_Primay = p_group_id))
      AND (p_op_mode_cd IS NULL OR a.Op_Mode_Cd = p_op_mode_cd)
      AND (p_status_cd IS NULL OR a.Appl_Status_Cd = p_status_cd)
      AND (p_is_closed IS NULL OR (a.Closing_Date IS NOT NULL) = (p_is_closed = 1))
      AND (p_from_date IS NULL OR a.Appl_Date >= p_from_date)
      AND (p_to_date IS NULL OR a.Appl_Date <= p_to_date)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(a.Appl_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Holder_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(j1.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(j2.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR EXISTS (SELECT 1 FROM mst_deposit_account_sb sb WHERE sb.Account_Id = a.Account_Id
                     AND (CAST(sb.Account_No AS CHAR) = p_keyword OR IFNULL(sb.Ref_AcNo, '') LIKE CONCAT('%', p_keyword, '%')))
          OR EXISTS (SELECT 1 FROM mst_deposit_account_td td WHERE td.Account_Id = a.Account_Id
                     AND (CAST(td.Account_No AS CHAR) = p_keyword OR IFNULL(td.Ref_AcNo, '') LIKE CONCAT('%', p_keyword, '%')))
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        a.Account_Id,
        a.Appl_No,
        a.Appl_Date,
        a.Deposit_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 3 AND o.Opt_Code = a.Deposit_Type_Cd) AS Deposit_Type_Desc,
        a.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        s.RoI_Percent AS Scheme_RoI_Percent,
        a.Special_Catg_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 11 AND o.Opt_Code = a.Special_Catg_Cd) AS Special_Catg_Desc,
        a.Cust_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 34 AND o.Opt_Code = a.Cust_Type_Cd) AS Cust_Type_Desc,
        a.Cust_Id_Primay AS Cust_Id_Primary,
        IF(a.Cust_Type_Cd = 1, pg.Ref_Code, pm.Ref_Code) AS Primary_Ref_Code,
        IF(a.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Primary_Name,
        IF(a.Cust_Type_Cd = 1, NULL, pm.Mobile_No) AS Primary_Mobile,
        a.Cust_Id_Joint1,
        j1.Ref_Code AS Joint1_Ref_Code,
        j1.Member_Name AS Joint1_Name,
        a.Cust_Id_Joint2,
        j2.Ref_Code AS Joint2_Ref_Code,
        j2.Member_Name AS Joint2_Name,
        a.Holder_Name,
        a.Op_Mode_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 9 AND o.Opt_Code = a.Op_Mode_Cd) AS Op_Mode_Desc,
        IFNULL(a.Nom_Regd, 0) AS Nom_Regd,
        (SELECT COUNT(*) FROM mst_deposit_account_nominee n WHERE n.Account_Id = a.Account_Id AND IFNULL(n.Is_Active, 1) = 1) AS Nominee_Count,
        (SELECT COUNT(*) FROM mst_deposit_account_signatory sg WHERE sg.Account_Id = a.Account_Id AND IFNULL(sg.Is_Active, 1) = 1) AS Signatory_Count,
        COALESCE(
            (SELECT sb.Account_No FROM mst_deposit_account_sb sb WHERE sb.Account_Id = a.Account_Id ORDER BY sb.Id DESC LIMIT 1),
            (SELECT td.Account_No FROM mst_deposit_account_td td WHERE td.Account_Id = a.Account_Id ORDER BY td.Id DESC LIMIT 1)
        ) AS Account_No,
        COALESCE(
            (SELECT sb.Ref_AcNo FROM mst_deposit_account_sb sb WHERE sb.Account_Id = a.Account_Id ORDER BY sb.Id DESC LIMIT 1),
            (SELECT td.Ref_AcNo FROM mst_deposit_account_td td WHERE td.Account_Id = a.Account_Id ORDER BY td.Id DESC LIMIT 1)
        ) AS Ref_AcNo,
        COALESCE(
            (SELECT sb.Start_Date FROM mst_deposit_account_sb sb WHERE sb.Account_Id = a.Account_Id ORDER BY sb.Id DESC LIMIT 1),
            (SELECT td.Start_Date FROM mst_deposit_account_td td WHERE td.Account_Id = a.Account_Id ORDER BY td.Id DESC LIMIT 1)
        ) AS Start_Date,
        (IFNULL((SELECT SUM(sb.Current_Balance) FROM mst_deposit_account_sb sb WHERE sb.Account_Id = a.Account_Id), 0)
         + IFNULL((SELECT SUM(td.Current_Balance) FROM mst_deposit_account_td td WHERE td.Account_Id = a.Account_Id), 0)) AS Current_Balance,
        s.Prod_Type_Cd AS Scheme_Prod_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o
         WHERE o.Opt_Grp_Id = IF(a.Deposit_Type_Cd = 2, 6, 5) AND o.Opt_Code = s.Prod_Type_Cd) AS Scheme_Prod_Type_Desc,
        sbd.Id AS SB_Id,
        sbd.Start_Date AS SB_Start_Date,
        sbd.Account_No AS SB_Account_No,
        sbd.Ref_AcNo AS SB_Ref_AcNo,
        sbd.CBS_AcNo AS SB_CBS_AcNo,
        sbd.RoI AS SB_RoI,
        sbd.Opening_Deposit AS SB_Opening_Deposit,
        sbd.Current_Balance AS SB_Current_Balance,
        sbd.Available_Balance AS SB_Available_Balance,
        sbd.Created_On AS SB_Created_On,
        tdd.Id AS TD_Id,
        tdd.Start_Date AS TD_Start_Date,
        tdd.Account_No AS TD_Account_No,
        tdd.Ref_AcNo AS TD_Ref_AcNo,
        tdd.Period_YY AS TD_Period_YY,
        tdd.Period_MM AS TD_Period_MM,
        tdd.Period_DD AS TD_Period_DD,
        tdd.RoI AS TD_RoI,
        tdd.Inst_No AS TD_Inst_No,
        tdd.Inst_Amount AS TD_Inst_Amount,
        tdd.Maturity_Date AS TD_Maturity_Date,
        tdd.Maturity_Amt AS TD_Maturity_Amt,
        tdd.Intt_Payable_Amt AS TD_Intt_Payable_Amt,
        tdd.Matu_Ins_Cd AS TD_Matu_Ins_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 13 AND o.Opt_Code = tdd.Matu_Ins_Cd) AS TD_Matu_Ins_Desc,
        tdd.SBCredit_AcId AS TD_SBCredit_AcId,
        sbc.Appl_No AS TD_SBCredit_Appl_No,
        (SELECT x.Account_No FROM mst_deposit_account_sb x WHERE x.Account_Id = tdd.SBCredit_AcId ORDER BY x.Id DESC LIMIT 1) AS TD_SBCredit_Account_No,
        tdd.TDS_Deduct AS TD_TDS_Deduct,
        tdd.Current_Balance AS TD_Current_Balance,
        tdd.Created_At AS TD_Created_At,
        a.Closing_Date,
        a.Closing_Reason,
        IF(a.Closing_Date IS NULL, 0, 1) AS Is_Closed,
        a.FO_Id,
        fo.Employee_Code AS FO_Code,
        fo.Full_Name AS FO_Name,
        a.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        a.Appl_Status_Cd AS Status_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 14 AND o.Opt_Code = a.Appl_Status_Cd) AS Status_Desc,
        a.Created_By,
        u.User_Name AS Created_By_Name,
        a.Created_At
    FROM mst_deposit_account a
    LEFT JOIN mst_deposit_scheme s ON s.Scheme_Id = a.Scheme_Id
    LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
    LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
    LEFT JOIN mst_member j1 ON j1.Member_Id = a.Cust_Id_Joint1
    LEFT JOIN mst_member j2 ON j2.Member_Id = a.Cust_Id_Joint2
    LEFT JOIN mst_staff fo ON fo.Staff_Id = a.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = a.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = a.Created_By
    LEFT JOIN mst_deposit_account_sb sbd
           ON sbd.Id = (SELECT MAX(x.Id) FROM mst_deposit_account_sb x WHERE x.Account_Id = a.Account_Id)
    LEFT JOIN mst_deposit_account_td tdd
           ON tdd.Id = (SELECT MAX(x.Id) FROM mst_deposit_account_td x WHERE x.Account_Id = a.Account_Id)
    LEFT JOIN mst_deposit_account sbc ON sbc.Account_Id = tdd.SBCredit_AcId
    WHERE (p_account_id IS NULL OR a.Account_Id = p_account_id)
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
      AND (p_fo_id IS NULL OR a.FO_Id = p_fo_id)
      AND (p_scheme_id IS NULL OR a.Scheme_Id = p_scheme_id)
      AND (p_deposit_type_cd IS NULL OR a.Deposit_Type_Cd = p_deposit_type_cd)
      AND (p_cust_type_cd IS NULL OR a.Cust_Type_Cd = p_cust_type_cd)
      AND (p_member_id IS NULL OR (a.Cust_Type_Cd = 2 AND p_member_id IN (a.Cust_Id_Primay, IFNULL(a.Cust_Id_Joint1, 0), IFNULL(a.Cust_Id_Joint2, 0))))
      AND (p_group_id IS NULL OR (a.Cust_Type_Cd = 1 AND a.Cust_Id_Primay = p_group_id))
      AND (p_op_mode_cd IS NULL OR a.Op_Mode_Cd = p_op_mode_cd)
      AND (p_status_cd IS NULL OR a.Appl_Status_Cd = p_status_cd)
      AND (p_is_closed IS NULL OR (a.Closing_Date IS NOT NULL) = (p_is_closed = 1))
      AND (p_from_date IS NULL OR a.Appl_Date >= p_from_date)
      AND (p_to_date IS NULL OR a.Appl_Date <= p_to_date)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(a.Appl_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Holder_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(j1.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(j2.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR EXISTS (SELECT 1 FROM mst_deposit_account_sb sb WHERE sb.Account_Id = a.Account_Id
                     AND (CAST(sb.Account_No AS CHAR) = p_keyword OR IFNULL(sb.Ref_AcNo, '') LIKE CONCAT('%', p_keyword, '%')))
          OR EXISTS (SELECT 1 FROM mst_deposit_account_td td WHERE td.Account_Id = a.Account_Id
                     AND (CAST(td.Account_No AS CHAR) = p_keyword OR IFNULL(td.Ref_AcNo, '') LIKE CONCAT('%', p_keyword, '%')))
      )
    ORDER BY a.Appl_Date DESC, a.Account_Id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_ACCOUNT_SB_SAVE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_ACCOUNT_SB_SAVE`(
    IN p_account_id INT,
    IN p_start_date DATE,
    IN p_account_no INT,
    IN p_ref_ac_no VARCHAR(15),
    IN p_cbs_ac_no VARCHAR(25),
    IN p_roi DECIMAL(6,2),
    IN p_opening_deposit DECIMAL(12,2),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_sb_id INT DEFAULT NULL;
    DECLARE v_deposit_type INT DEFAULT NULL;
    DECLARE v_scheme INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_appl_date DATE DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_scheme_roi DECIMAL(5,2) DEFAULT NULL;
    DECLARE v_locked INT DEFAULT 0;

    DECLARE v_cur_start DATE DEFAULT NULL;
    DECLARE v_cur_acno INT DEFAULT NULL;
    DECLARE v_cur_opening DECIMAL(10,2) DEFAULT NULL;
    DECLARE v_cur_balance DECIMAL(10,2) DEFAULT 0;

    DECLARE v_start DATE;
    DECLARE v_acno INT;
    DECLARE v_ref VARCHAR(15);
    DECLARE v_cbs VARCHAR(25);
    DECLARE v_roi DECIMAL(6,2);
    DECLARE v_opening DECIMAL(12,2);

    SET v_ref = UPPER(NULLIF(TRIM(IFNULL(p_ref_ac_no, '')), ''));
    SET v_cbs = UPPER(NULLIF(TRIM(IFNULL(p_cbs_ac_no, '')), ''));

    SELECT COUNT(*), MAX(Deposit_Type_Cd), MAX(Scheme_Id), MAX(Branch_Id), MAX(Appl_Date), MAX(Closing_Date)
    INTO v_cnt, v_deposit_type, v_scheme, v_branch, v_appl_date, v_closing
    FROM mst_deposit_account WHERE Account_Id = p_account_id;

    IF p_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Deposit account not found';
    ELSEIF v_closing IS NOT NULL THEN
        SET v_err = 'Savings details of a closed deposit account cannot be changed';
    ELSEIF IFNULL(v_deposit_type, 0) <> 1 THEN
        SET v_err = 'Savings (SB) details apply to savings accounts only';
    END IF;

    IF v_err IS NULL THEN
        SELECT MAX(Id) INTO v_sb_id FROM mst_deposit_account_sb WHERE Account_Id = p_account_id FOR UPDATE;

        IF v_sb_id IS NOT NULL THEN
            SELECT Start_Date, Account_No, IFNULL(Opening_Deposit, 0), IFNULL(Current_Balance, 0)
            INTO v_cur_start, v_cur_acno, v_cur_opening, v_cur_balance
            FROM mst_deposit_account_sb WHERE Id = v_sb_id;

            SELECT COUNT(*) INTO v_locked FROM trans_savings_transaction WHERE Account_Id = p_account_id;
            IF v_cur_balance <> 0 THEN
                SET v_locked = v_locked + 1;
            END IF;
        END IF;

        SELECT MAX(RoI_Percent) INTO v_scheme_roi FROM mst_deposit_scheme WHERE Scheme_Id = v_scheme;
    END IF;

    SET v_start = IFNULL(p_start_date, v_appl_date);
    SET v_roi = IFNULL(p_roi, v_scheme_roi);
    SET v_opening = IFNULL(p_opening_deposit, 0);

    IF v_err IS NULL THEN
        IF v_start < v_appl_date THEN
            SET v_err = 'SB start date cannot be before the application date';
        ELSEIF v_start > CURDATE() THEN
            SET v_err = 'SB start date cannot be in the future';
        ELSEIF v_roi IS NULL THEN
            SET v_err = 'SB rate of interest is required (the scheme has no rate)';
        ELSEIF v_roi < 0 OR v_roi > 100 THEN
            SET v_err = 'SB rate of interest must be between 0 and 100';
        ELSEIF v_opening < 0 OR v_opening > 99999999.99 THEN
            SET v_err = 'Opening deposit must be between 0 and 99999999.99';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        IF p_account_no IS NOT NULL THEN
            IF p_account_no < 1 OR p_account_no > 32767 THEN
                SET v_err = 'Account number must be between 1 and 32767';
            ELSE
                SET v_acno = p_account_no;
            END IF;
        ELSEIF v_cur_acno IS NOT NULL THEN
            SET v_acno = v_cur_acno;
        ELSE
            SELECT IFNULL(MAX(sb.Account_No), 0) + 1 INTO v_acno
            FROM mst_deposit_account_sb sb
            JOIN mst_deposit_account a ON a.Account_Id = sb.Account_Id
            WHERE a.Scheme_Id = v_scheme AND a.Branch_Id = v_branch
            FOR UPDATE;
            IF v_acno > 32767 THEN
                SET v_err = 'No account number left for this scheme and branch';
            END IF;
        END IF;
    END IF;

    IF v_err IS NULL AND v_locked > 0
       AND (NOT (v_start <=> v_cur_start) OR NOT (v_acno <=> v_cur_acno) OR v_opening <> v_cur_opening) THEN
        SET v_err = 'SB start date, account number and opening deposit cannot be changed once transactions exist';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_deposit_account_sb sb
        JOIN mst_deposit_account a ON a.Account_Id = sb.Account_Id
        WHERE a.Scheme_Id = v_scheme AND a.Branch_Id = v_branch AND sb.Account_No = v_acno
          AND sb.Account_Id <> p_account_id;
        IF v_cnt > 0 THEN
            SET v_err = CONCAT('Account number ', v_acno, ' already exists for this scheme and branch');
        END IF;
    END IF;

    IF v_err IS NULL AND v_ref IS NOT NULL THEN
        SELECT (SELECT COUNT(*) FROM mst_deposit_account_sb WHERE UPPER(Ref_AcNo) = v_ref AND Account_Id <> p_account_id)
             + (SELECT COUNT(*) FROM mst_deposit_account_td WHERE UPPER(Ref_AcNo) = v_ref)
        INTO v_cnt;
        IF v_cnt > 0 THEN
            SET v_err = 'Reference account number already exists';
        END IF;
    END IF;

    IF v_err IS NULL AND v_cbs IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account_sb
        WHERE UPPER(CBS_AcNo) = v_cbs AND Account_Id <> p_account_id;
        IF v_cnt > 0 THEN
            SET v_err = 'CBS account number already exists';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, v_sb_id AS sb_id, p_account_id AS account_id, NULL AS account_no, v_err AS message;
    ELSEIF v_sb_id IS NULL THEN
        INSERT INTO mst_deposit_account_sb (
            Account_Id, Start_Date, Account_No, Ref_AcNo, CBS_AcNo, RoI, Opening_Deposit,
            Current_Balance, Available_Balance, Created_By, Created_On
        ) VALUES (
            p_account_id, v_start, v_acno, v_ref, v_cbs, v_roi, v_opening,
            0, 0, p_user_id, NOW()
        );

        SET v_sb_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_sb_id AS sb_id, p_account_id AS account_id, v_acno AS account_no,
               'Savings details created successfully' AS message;
    ELSE
        UPDATE mst_deposit_account_sb
        SET Start_Date = v_start,
            Account_No = v_acno,
            Ref_AcNo = v_ref,
            CBS_AcNo = v_cbs,
            RoI = v_roi,
            Opening_Deposit = v_opening
        WHERE Id = v_sb_id;

        SELECT 'SUCCESS' AS status, v_sb_id AS sb_id, p_account_id AS account_id, v_acno AS account_no,
               'Savings details updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_ACCOUNT_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_ACCOUNT_STATUS`(
    IN p_account_id INT,
    IN p_status_cd INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_err VARCHAR(255) DEFAULT NULL;

    SELECT COUNT(*), MAX(Appl_Status_Cd), MAX(Branch_Id), MAX(Closing_Date)
    INTO v_cnt, v_current, v_branch, v_closing
    FROM mst_deposit_account WHERE Account_Id = p_account_id;

    SELECT MIN(Opt_Description) INTO v_desc
    FROM mst_appl_options WHERE Opt_Grp_Id = 14 AND Opt_Code = p_status_cd AND Is_Active = 1;

    IF p_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Deposit account not found';
    ELSEIF p_status_cd IS NULL OR v_desc IS NULL THEN
        SET v_err = 'Invalid deposit account status';
    ELSEIF v_closing IS NOT NULL THEN
        SET v_err = 'Closed deposit account status cannot be changed';
    END IF;

    IF v_err IS NULL AND IFNULL(v_current, 0) <> p_status_cd AND p_status_cd = 1 THEN
        SELECT COUNT(*) INTO v_cnt FROM priomicro_core.mst_org_branch
        WHERE Branch_Id = v_branch AND IFNULL(Is_Active, 0) = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Branch is inactive; account cannot be activated';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_account_id AS account_id, v_current AS status_cd, v_err AS message;
    ELSEIF v_current = p_status_cd THEN
        SELECT 'SUCCESS' AS status, p_account_id AS account_id, v_current AS status_cd,
               CONCAT('Deposit account is already ', LOWER(v_desc)) AS message;
    ELSE
        UPDATE mst_deposit_account SET Appl_Status_Cd = p_status_cd WHERE Account_Id = p_account_id;

        SELECT 'SUCCESS' AS status, p_account_id AS account_id, p_status_cd AS status_cd,
               CONCAT('Deposit account status changed to ', v_desc) AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_ACCOUNT_TD_SAVE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_ACCOUNT_TD_SAVE`(
    IN p_account_id INT,
    IN p_start_date DATE,
    IN p_account_no INT,
    IN p_ref_ac_no VARCHAR(15),
    IN p_period_yy INT,
    IN p_period_mm INT,
    IN p_period_dd INT,
    IN p_roi DECIMAL(6,2),
    IN p_inst_no INT,
    IN p_inst_amount DECIMAL(12,2),
    IN p_matu_ins_cd INT,
    IN p_sbcredit_ac_id INT,
    IN p_tds_deduct TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_td_id INT DEFAULT NULL;
    DECLARE v_deposit_type INT DEFAULT NULL;
    DECLARE v_scheme INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_appl_date DATE DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_cust_type INT DEFAULT NULL;
    DECLARE v_primary INT DEFAULT NULL;
    DECLARE v_scheme_roi DECIMAL(5,2) DEFAULT NULL;
    DECLARE v_prod_type INT DEFAULT NULL;
    DECLARE v_intt_type INT DEFAULT NULL;
    DECLARE v_locked INT DEFAULT 0;

    DECLARE v_cur_start DATE DEFAULT NULL;
    DECLARE v_cur_acno INT DEFAULT NULL;
    DECLARE v_cur_yy INT DEFAULT NULL;
    DECLARE v_cur_mm INT DEFAULT NULL;
    DECLARE v_cur_dd INT DEFAULT NULL;
    DECLARE v_cur_roi DECIMAL(6,2) DEFAULT NULL;
    DECLARE v_cur_inst_no INT DEFAULT NULL;
    DECLARE v_cur_inst_amt DECIMAL(12,2) DEFAULT NULL;
    DECLARE v_cur_matu_date DATE DEFAULT NULL;
    DECLARE v_cur_matu_amt DECIMAL(12,2) DEFAULT NULL;
    DECLARE v_cur_intt DECIMAL(12,2) DEFAULT NULL;
    DECLARE v_cur_balance DECIMAL(10,2) DEFAULT 0;

    DECLARE v_start DATE;
    DECLARE v_acno INT;
    DECLARE v_ref VARCHAR(15);
    DECLARE v_yy INT;
    DECLARE v_mm INT;
    DECLARE v_dd INT;
    DECLARE v_roi DECIMAL(6,2);
    DECLARE v_inst_no INT;
    DECLARE v_max_inst INT DEFAULT 1;
    DECLARE v_inst_amt DECIMAL(12,2);
    DECLARE v_matu_ins INT;
    DECLARE v_sbcredit INT;
    DECLARE v_tds TINYINT;
    DECLARE v_installment TINYINT DEFAULT 0;
    DECLARE v_changed TINYINT DEFAULT 1;

    DECLARE v_matu_date DATE DEFAULT NULL;
    DECLARE v_days INT DEFAULT 0;
    DECLARE v_months INT DEFAULT 0;
    DECLARE v_years INT DEFAULT 0;
    DECLARE v_comp INT DEFAULT 0;
    DECLARE v_term DOUBLE DEFAULT 0;
    DECLARE v_rate DOUBLE DEFAULT 0;
    DECLARE v_step DOUBLE DEFAULT 0;
    DECLARE v_q DOUBLE DEFAULT 0;
    DECLARE v_principal DOUBLE DEFAULT 0;
    DECLARE v_amount DOUBLE DEFAULT 0;
    DECLARE v_matu_amt DECIMAL(14,2) DEFAULT NULL;
    DECLARE v_intt DECIMAL(14,2) DEFAULT NULL;

    SET v_ref = UPPER(NULLIF(TRIM(IFNULL(p_ref_ac_no, '')), ''));
    SET v_yy = IFNULL(p_period_yy, 0);
    SET v_mm = IFNULL(p_period_mm, 0);
    SET v_dd = IFNULL(p_period_dd, 0);
    SET v_inst_amt = p_inst_amount;
    SET v_matu_ins = p_matu_ins_cd;
    SET v_sbcredit = p_sbcredit_ac_id;
    SET v_tds = IFNULL(p_tds_deduct, 0);

    SELECT COUNT(*), MAX(Deposit_Type_Cd), MAX(Scheme_Id), MAX(Branch_Id), MAX(Appl_Date), MAX(Closing_Date),
           MAX(Cust_Type_Cd), MAX(Cust_Id_Primay)
    INTO v_cnt, v_deposit_type, v_scheme, v_branch, v_appl_date, v_closing, v_cust_type, v_primary
    FROM mst_deposit_account WHERE Account_Id = p_account_id;

    IF p_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Deposit account not found';
    ELSEIF v_closing IS NOT NULL THEN
        SET v_err = 'Term deposit details of a closed deposit account cannot be changed';
    ELSEIF IFNULL(v_deposit_type, 0) <> 2 THEN
        SET v_err = 'Term deposit (TD) details apply to term deposit accounts only';
    END IF;

    IF v_err IS NULL THEN
        SELECT MAX(Id) INTO v_td_id FROM mst_deposit_account_td WHERE Account_Id = p_account_id FOR UPDATE;

        IF v_td_id IS NOT NULL THEN
            SELECT Start_Date, Account_No, IFNULL(Period_YY, 0), IFNULL(Period_MM, 0), IFNULL(Period_DD, 0), RoI,
                   Inst_No, Inst_Amount, Maturity_Date, Maturity_Amt, Intt_Payable_Amt, IFNULL(Current_Balance, 0)
            INTO v_cur_start, v_cur_acno, v_cur_yy, v_cur_mm, v_cur_dd, v_cur_roi,
                 v_cur_inst_no, v_cur_inst_amt, v_cur_matu_date, v_cur_matu_amt, v_cur_intt, v_cur_balance
            FROM mst_deposit_account_td WHERE Id = v_td_id;

            SELECT COUNT(*) INTO v_locked FROM trans_savings_transaction WHERE Account_Id = p_account_id;
            IF v_cur_balance <> 0 THEN
                SET v_locked = v_locked + 1;
            END IF;
        END IF;

        SELECT MAX(RoI_Percent), MAX(Prod_Type_Cd), MAX(Intt_Type_Cd)
        INTO v_scheme_roi, v_prod_type, v_intt_type
        FROM mst_deposit_scheme WHERE Scheme_Id = v_scheme;

        SET v_installment = IF(v_prod_type IN (1, 2), 1, 0);
    END IF;

    SET v_start = IFNULL(p_start_date, v_appl_date);

    
    IF v_err IS NULL THEN
        IF v_start < v_appl_date THEN
            SET v_err = 'TD start date cannot be before the application date';
        ELSEIF v_start > CURDATE() THEN
            SET v_err = 'TD start date cannot be in the future';
        ELSEIF v_yy < 0 OR v_yy > 50 OR v_mm < 0 OR v_mm > 120 OR v_dd < 0 OR v_dd > 120 THEN
            SET v_err = 'Deposit period must be 0-50 years, 0-120 months and 0-120 days';
        ELSEIF v_yy + v_mm + v_dd = 0 THEN
            SET v_err = 'Deposit period is required (years, months or days)';
        ELSEIF v_prod_type = 2 AND v_dd > 0 THEN
            SET v_err = 'Recurring deposit period must be in whole months (period days must be 0)';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_matu_date = DATE_ADD(DATE_ADD(DATE_ADD(v_start, INTERVAL v_yy YEAR), INTERVAL v_mm MONTH), INTERVAL v_dd DAY);
        SET v_days = DATEDIFF(v_matu_date, v_start);
        SET v_months = TIMESTAMPDIFF(MONTH, v_start, v_matu_date);
        SET v_years = TIMESTAMPDIFF(YEAR, v_start, v_matu_date);
    END IF;

    
    IF v_err IS NULL THEN
        SET v_roi = IFNULL(p_roi, (
            SELECT s.RoI
            FROM mst_deposit_scheme_slab s
            WHERE s.Scheme_Id = v_scheme
              AND IFNULL(s.Is_Active, 0) = 1
              AND s.RoI IS NOT NULL
              AND (s.Effect_Frm IS NULL OR s.Effect_Frm <= v_start)
              AND (s.Effect_Upto IS NULL OR s.Effect_Upto >= v_start)
              AND (CASE s.Term_Cd WHEN 1 THEN v_days WHEN 2 THEN v_months WHEN 3 THEN v_years END)
                  BETWEEN s.Min_Duration AND s.Max_Duration
            ORDER BY s.Term_Cd ASC, s.Id DESC
            LIMIT 1
        ));
        SET v_roi = IFNULL(v_roi, v_scheme_roi);

        IF v_roi IS NULL THEN
            SET v_err = 'TD rate of interest is required (no scheme slab or scheme rate found)';
        ELSEIF v_roi < 0 OR v_roi > 100 THEN
            SET v_err = 'TD rate of interest must be between 0 and 100';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        IF v_inst_amt IS NULL OR v_inst_amt <= 0 OR v_inst_amt > 99999999.99 THEN
            SET v_err = 'Deposit amount must be greater than 0 and at most 99999999.99';
        ELSEIF v_installment = 1 THEN
            SET v_max_inst = IF(v_prod_type = 2, v_yy * 12 + v_mm, v_days);
            SET v_inst_no = IFNULL(p_inst_no, v_max_inst);
            IF v_inst_no < 1 OR v_inst_no > v_max_inst OR v_inst_no > 32767 THEN
                SET v_err = CONCAT('Number of installments must be between 1 and ', LEAST(v_max_inst, 32767), ' for this period');
            END IF;
        ELSEIF IFNULL(p_inst_no, 1) <> 1 THEN
            SET v_err = 'Installments apply to daily / recurring deposits only; this scheme takes a single deposit';
        ELSE
            SET v_inst_no = 1;
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        IF p_account_no IS NOT NULL THEN
            IF p_account_no < 1 OR p_account_no > 32767 THEN
                SET v_err = 'Account number must be between 1 and 32767';
            ELSE
                SET v_acno = p_account_no;
            END IF;
        ELSEIF v_cur_acno IS NOT NULL THEN
            SET v_acno = v_cur_acno;
        ELSE
            SELECT IFNULL(MAX(td.Account_No), 0) + 1 INTO v_acno
            FROM mst_deposit_account_td td
            JOIN mst_deposit_account a ON a.Account_Id = td.Account_Id
            WHERE a.Scheme_Id = v_scheme AND a.Branch_Id = v_branch
            FOR UPDATE;
            IF v_acno > 32767 THEN
                SET v_err = 'No account number left for this scheme and branch';
            END IF;
        END IF;
    END IF;

    IF v_err IS NULL AND v_td_id IS NOT NULL THEN
        SET v_changed = IF(v_start <=> v_cur_start AND v_yy = v_cur_yy AND v_mm = v_cur_mm AND v_dd = v_cur_dd
                           AND v_roi <=> v_cur_roi AND v_inst_no <=> v_cur_inst_no AND v_inst_amt <=> v_cur_inst_amt, 0, 1);

        IF v_locked > 0 AND (v_changed = 1 OR NOT (v_acno <=> v_cur_acno)) THEN
            SET v_err = 'TD start date, account number, period, rate and amount cannot be changed once transactions exist';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_deposit_account_td td
        JOIN mst_deposit_account a ON a.Account_Id = td.Account_Id
        WHERE a.Scheme_Id = v_scheme AND a.Branch_Id = v_branch AND td.Account_No = v_acno
          AND td.Account_Id <> p_account_id;
        IF v_cnt > 0 THEN
            SET v_err = CONCAT('Account number ', v_acno, ' already exists for this scheme and branch');
        END IF;
    END IF;

    IF v_err IS NULL AND v_ref IS NOT NULL THEN
        SELECT (SELECT COUNT(*) FROM mst_deposit_account_td WHERE UPPER(Ref_AcNo) = v_ref AND Account_Id <> p_account_id)
             + (SELECT COUNT(*) FROM mst_deposit_account_sb WHERE UPPER(Ref_AcNo) = v_ref)
        INTO v_cnt;
        IF v_cnt > 0 THEN
            SET v_err = 'Reference account number already exists';
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_matu_ins IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 13 AND Opt_Code = v_matu_ins AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid maturity instruction';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        IF IFNULL(v_matu_ins, 0) NOT IN (1, 4) THEN
            SET v_sbcredit = NULL;
        ELSEIF v_matu_ins = 4 AND v_sbcredit IS NULL THEN
            SET v_err = 'SB credit account is required when maturity is paid to SB';
        END IF;
    END IF;

    IF v_err IS NULL AND v_sbcredit IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account
        WHERE Account_Id = v_sbcredit
          AND Deposit_Type_Cd = 1
          AND Closing_Date IS NULL
          AND Cust_Type_Cd = v_cust_type
          AND Cust_Id_Primay = v_primary;
        IF v_sbcredit = p_account_id OR v_cnt = 0 THEN
            SET v_err = 'SB credit account must be an open savings account of the same customer';
        END IF;
    END IF;

    IF v_err IS NULL AND v_tds NOT IN (0, 1) THEN
        SET v_err = 'TDS deduct must be 1 (yes) or 0 (no)';
    END IF;

    
    IF v_err IS NULL AND v_changed = 0 THEN
        SET v_matu_date = v_cur_matu_date;
        SET v_matu_amt = v_cur_matu_amt;
        SET v_intt = v_cur_intt;
    ELSEIF v_err IS NULL THEN
        SET v_rate = v_roi / 100e0;
        SET v_term = v_days / 365e0;
        SET v_comp = CASE v_intt_type WHEN 4 THEN 12 WHEN 5 THEN 4 WHEN 6 THEN 2 WHEN 7 THEN 1 ELSE 0 END;
        IF v_prod_type = 4 AND v_comp = 0 THEN
            SET v_comp = 4;
        END IF;
        SET v_principal = v_inst_amt * v_inst_no;

        IF v_prod_type = 5 THEN
            SET v_amount = v_principal * (1 + v_rate * v_term);
        ELSEIF v_installment = 0 THEN
            IF v_comp = 0 OR v_rate = 0 THEN
                SET v_amount = v_principal * (1 + v_rate * v_term);
            ELSE
                SET v_amount = v_principal * POW(1 + v_rate / v_comp, v_comp * v_term);
            END IF;
        ELSE
            SET v_step = v_term / v_inst_no;
            IF v_comp = 0 OR v_rate = 0 THEN
                SET v_amount = v_inst_amt * v_inst_no + v_inst_amt * v_rate * v_step * v_inst_no * (v_inst_no + 1) / 2;
            ELSE
                SET v_q = POW(1 + v_rate / v_comp, v_comp * v_step);
                SET v_amount = v_inst_amt * v_q * (POW(v_q, v_inst_no) - 1) / (v_q - 1);
            END IF;
        END IF;

        SET v_intt = ROUND(v_amount - v_principal, 2);
        SET v_matu_amt = IF(v_prod_type = 5, ROUND(v_principal, 2), ROUND(v_amount, 2));

        IF v_matu_amt > 99999999.99 OR v_intt > 99999999.99 THEN
            SET v_err = 'Maturity amount is too large';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, v_td_id AS td_id, p_account_id AS account_id, NULL AS account_no,
               NULL AS maturity_date, NULL AS maturity_amt, v_err AS message;
    ELSEIF v_td_id IS NULL THEN
        INSERT INTO mst_deposit_account_td (
            Account_Id, Start_Date, Account_No, Ref_AcNo, Period_YY, Period_MM, Period_DD, RoI, Inst_No,
            Inst_Amount, Maturity_Date, Maturity_Amt, Intt_Payable_Amt, Matu_Ins_Cd, SBCredit_AcId, TDS_Deduct,
            Current_Balance, Created_By, Created_At
        ) VALUES (
            p_account_id, v_start, v_acno, v_ref, v_yy, v_mm, v_dd, v_roi, v_inst_no,
            v_inst_amt, v_matu_date, v_matu_amt, v_intt, v_matu_ins, v_sbcredit, v_tds,
            0, p_user_id, NOW()
        );

        SET v_td_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_td_id AS td_id, p_account_id AS account_id, v_acno AS account_no,
               v_matu_date AS maturity_date, v_matu_amt AS maturity_amt,
               'Term deposit details created successfully' AS message;
    ELSE
        UPDATE mst_deposit_account_td
        SET Start_Date = v_start,
            Account_No = v_acno,
            Ref_AcNo = v_ref,
            Period_YY = v_yy,
            Period_MM = v_mm,
            Period_DD = v_dd,
            RoI = v_roi,
            Inst_No = v_inst_no,
            Inst_Amount = v_inst_amt,
            Maturity_Date = v_matu_date,
            Maturity_Amt = v_matu_amt,
            Intt_Payable_Amt = v_intt,
            Matu_Ins_Cd = v_matu_ins,
            SBCredit_AcId = v_sbcredit,
            TDS_Deduct = v_tds
        WHERE Id = v_td_id;

        SELECT 'SUCCESS' AS status, v_td_id AS td_id, p_account_id AS account_id, v_acno AS account_no,
               v_matu_date AS maturity_date, v_matu_amt AS maturity_amt,
               'Term deposit details updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_CHARGES_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_CHARGES_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_charge_id INT,
    IN p_charge_name VARCHAR(100),
    IN p_charge_rate DECIMAL(8,2),
    IN p_figure_cd TINYINT,
    IN p_max_amount DECIMAL(8,2),
    IN p_tax_prcent DECIMAL(5,2),
    IN p_charges_during_cd TINYINT,
    IN p_charges_gl INT,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_action VARCHAR(10);
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_active TINYINT DEFAULT 1;
    DECLARE v_current TINYINT DEFAULT NULL;
    DECLARE v_name VARCHAR(100);
    DECLARE v_new_id INT DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_name = TRIM(IFNULL(p_charge_name, ''));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Invalid action. Use ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_deposit_charges WHERE Charge_Id = p_charge_id;
        IF p_charge_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Deposit charge not found';
        ELSE
            SELECT IFNULL(Is_Active, 0) INTO v_current
            FROM mst_deposit_charges WHERE Charge_Id = p_charge_id;

            SET v_active = IF(p_is_active IS NULL, v_current, IF(p_is_active = 1, 1, 0));
        END IF;
    ELSE
        SET v_active = IF(IFNULL(p_is_active, 1) = 1, 1, 0);
    END IF;

    IF v_err IS NULL AND v_name = '' THEN
        SET v_err = 'Charge name is required';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_deposit_charges
        WHERE LOWER(TRIM(Charge_Name)) = LOWER(v_name)
          AND (v_action = 'ADD' OR Charge_Id <> p_charge_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Charge name already exists';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 16 AND Opt_Code = p_figure_cd AND Is_Active = 1;
        IF p_figure_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid figure type';
        END IF;
    END IF;

    IF v_err IS NULL AND (p_charge_rate IS NULL OR p_charge_rate < 0) THEN
        SET v_err = 'Charge rate is required and cannot be negative';
    END IF;

    IF v_err IS NULL AND p_figure_cd = 2 AND p_charge_rate > 100 THEN
        SET v_err = 'Charge percentage cannot exceed 100';
    END IF;

    IF v_err IS NULL AND p_max_amount IS NOT NULL AND p_max_amount < 0 THEN
        SET v_err = 'Max amount cannot be negative';
    END IF;

    IF v_err IS NULL AND p_figure_cd = 1 AND p_max_amount IS NOT NULL AND p_max_amount < p_charge_rate THEN
        SET v_err = 'Max amount cannot be less than the fixed charge rate';
    END IF;

    IF v_err IS NULL AND p_tax_prcent IS NOT NULL AND (p_tax_prcent < 0 OR p_tax_prcent > 100) THEN
        SET v_err = 'Tax percent must be between 0 and 100';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 15 AND Opt_Code = p_charges_during_cd AND Is_Active = 1;
        IF p_charges_during_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid charges during';
        END IF;
    END IF;

    IF v_err IS NULL AND p_charges_gl IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_acct_ledger WHERE Ledger_Id = p_charges_gl;
        IF v_cnt = 0 THEN
            SET v_err = 'Charges ledger not found';
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' AND v_current = 1 AND v_active = 0 THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_deposit_scheme_charges
        WHERE Charges_Id = p_charge_id AND IFNULL(Is_Active, 0) = 1;
        IF v_cnt > 0 THEN
            SET v_err = 'Deposit charge is linked to an active deposit scheme and cannot be deactivated';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, IF(v_action = 'EDIT', p_charge_id, NULL) AS charge_id, v_err AS message;

    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_deposit_charges (
            Charge_Name, Charge_Rate, Figure_Cd, Max_Amount, Tax_Prcent,
            Charges_During_Cd, Charges_Gl, Is_Active, Created_By, Created_At
        ) VALUES (
            v_name, p_charge_rate, p_figure_cd, p_max_amount, IFNULL(p_tax_prcent, 0),
            p_charges_during_cd, p_charges_gl, v_active, p_user_id, NOW()
        );

        SET v_new_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_new_id AS charge_id, 'Deposit charge created successfully' AS message;

    ELSE
        UPDATE mst_deposit_charges
        SET Charge_Name = v_name,
            Charge_Rate = p_charge_rate,
            Figure_Cd = p_figure_cd,
            Max_Amount = p_max_amount,
            Tax_Prcent = IFNULL(p_tax_prcent, 0),
            Charges_During_Cd = p_charges_during_cd,
            Charges_Gl = p_charges_gl,
            Is_Active = v_active
        WHERE Charge_Id = p_charge_id;

        SELECT 'SUCCESS' AS status, p_charge_id AS charge_id, 'Deposit charge updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
