/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_CHARGES_STATUS`(
    IN p_charge_id INT,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current TINYINT DEFAULT NULL;

    SELECT COUNT(*) INTO v_cnt FROM mst_deposit_charges WHERE Charge_Id = p_charge_id;

    IF p_charge_id IS NULL OR v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_charge_id AS charge_id, NULL AS is_active, 'Deposit charge not found' AS message;
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_charge_id AS charge_id, NULL AS is_active,
               'Status must be 1 (active) or 0 (inactive)' AS message;
    ELSE
        SELECT IFNULL(Is_Active, 0) INTO v_current
        FROM mst_deposit_charges
        WHERE Charge_Id = p_charge_id;

        IF v_current = p_is_active THEN
            SELECT 'SUCCESS' AS status, p_charge_id AS charge_id, v_current AS is_active,
                   IF(p_is_active = 1, 'Deposit charge is already active', 'Deposit charge is already inactive') AS message;
        ELSE
            SET v_cnt = 0;

            IF p_is_active = 0 THEN
                SELECT COUNT(*) INTO v_cnt
                FROM mst_deposit_scheme_charges
                WHERE Charges_Id = p_charge_id AND IFNULL(Is_Active, 0) = 1;
            END IF;

            IF v_cnt > 0 THEN
                SELECT 'ERROR' AS status, p_charge_id AS charge_id, v_current AS is_active,
                       'Deposit charge is linked to an active deposit scheme and cannot be deactivated' AS message;
            ELSE
                UPDATE mst_deposit_charges SET Is_Active = p_is_active WHERE Charge_Id = p_charge_id;

                SELECT 'SUCCESS' AS status, p_charge_id AS charge_id, p_is_active AS is_active,
                       IF(p_is_active = 1, 'Deposit charge activated successfully', 'Deposit charge deactivated successfully') AS message;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
