DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_NOMINEE_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_nominee_id INT,
    IN p_account_id INT,
    IN p_nom_cust_id INT,
    IN p_nom_name VARCHAR(120),
    IN p_contact_no VARCHAR(25),
    IN p_relation_cd INT,
    IN p_age INT,
    IN p_birth_date DATE,
    IN p_address VARCHAR(150),
    IN p_guardian_name VARCHAR(100),
    IN p_share_percent DECIMAL(6,2),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_action VARCHAR(10);
    DECLARE v_nominee_id INT DEFAULT NULL;
    DECLARE v_account_id INT DEFAULT NULL;
    DECLARE v_active TINYINT DEFAULT 1;
    DECLARE v_name VARCHAR(120);
    DECLARE v_contact VARCHAR(25);
    DECLARE v_address VARCHAR(150);
    DECLARE v_guardian VARCHAR(100);
    DECLARE v_birth DATE;
    DECLARE v_age INT DEFAULT NULL;
    DECLARE v_minor TINYINT DEFAULT 0;
    DECLARE v_share DECIMAL(6,2) DEFAULT NULL;
    DECLARE v_other_share DECIMAL(8,2) DEFAULT 0;
    DECLARE v_other_count INT DEFAULT 0;

    DECLARE v_cust_type INT DEFAULT NULL;
    DECLARE v_primary INT DEFAULT NULL;
    DECLARE v_joint1 INT DEFAULT NULL;
    DECLARE v_joint2 INT DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;

    DECLARE v_mem_name VARCHAR(150) DEFAULT NULL;
    DECLARE v_mem_mobile VARCHAR(20) DEFAULT NULL;
    DECLARE v_mem_dob DATE DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_name = NULLIF(TRIM(IFNULL(p_nom_name, '')), '');
    SET v_contact = NULLIF(TRIM(IFNULL(p_contact_no, '')), '');
    SET v_address = NULLIF(TRIM(IFNULL(p_address, '')), '');
    SET v_guardian = NULLIF(TRIM(IFNULL(p_guardian_name, '')), '');
    SET v_birth = p_birth_date;
    SET v_account_id = p_account_id;

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Account_Id), MAX(IFNULL(Is_Active, 0))
        INTO v_cnt, v_account_id, v_active
        FROM mst_deposit_account_nominee WHERE Id = p_nominee_id;

        IF p_nominee_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Nominee not found';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Cust_Type_Cd), MAX(Cust_Id_Primay), MAX(Cust_Id_Joint1), MAX(Cust_Id_Joint2), MAX(Closing_Date)
        INTO v_cnt, v_cust_type, v_primary, v_joint1, v_joint2, v_closing
        FROM mst_deposit_account WHERE Account_Id = v_account_id;

        IF v_account_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Deposit account not found';
        ELSEIF v_closing IS NOT NULL THEN
            SET v_err = 'Nominees of a closed deposit account cannot be changed';
        ELSEIF v_cust_type <> 2 THEN
            SET v_err = 'Nominees can be added to individual deposit accounts only';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_nom_cust_id IS NOT NULL THEN
        SELECT COUNT(*), MAX(Member_Name), MAX(Mobile_No), MAX(Date_of_Birth)
        INTO v_cnt, v_mem_name, v_mem_mobile, v_mem_dob
        FROM mst_member WHERE Member_Id = p_nom_cust_id;

        IF v_cnt = 0 THEN
            SET v_err = 'Nominee member not found';
        ELSEIF p_nom_cust_id IN (v_primary, IFNULL(v_joint1, 0), IFNULL(v_joint2, 0)) THEN
            SET v_err = 'An account holder cannot be a nominee of the same account';
        ELSE
            SET v_name = IFNULL(v_name, LEFT(v_mem_name, 120));
            SET v_contact = IFNULL(v_contact, v_mem_mobile);
            SET v_birth = IFNULL(v_birth, v_mem_dob);
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_name IS NULL THEN
        SET v_err = 'Nominee name is required';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 35 AND Opt_Code = p_relation_cd AND Is_Active = 1;
        IF p_relation_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid relation';
        ELSEIF p_relation_cd = 9 THEN
            SET v_err = 'Relation cannot be Self; a holder cannot nominate themselves';
        END IF;
    END IF;

    IF v_err IS NULL AND v_contact IS NOT NULL AND v_contact NOT REGEXP '^[6-9][0-9]{9}$' THEN
        SET v_err = 'Contact number must be a valid 10-digit number';
    END IF;

    
    IF v_err IS NULL THEN
        IF v_birth IS NOT NULL THEN
            IF v_birth > CURDATE() THEN
                SET v_err = 'Birth date cannot be in the future';
            ELSE
                SET v_age = TIMESTAMPDIFF(YEAR, v_birth, CURDATE());
            END IF;
        ELSE
            SET v_age = p_age;
        END IF;
    END IF;

    IF v_err IS NULL THEN
        IF v_age IS NULL THEN
            SET v_err = 'Birth date or age is required';
        ELSEIF v_age < 0 OR v_age > 120 THEN
            SET v_err = 'Age must be between 0 and 120';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_minor = IF(v_age < 18, 1, 0);
        IF v_minor = 1 AND v_guardian IS NULL THEN
            SET v_err = 'Guardian name is required for a minor nominee';
        ELSEIF v_minor = 0 THEN
            SET v_guardian = NULL;
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_active = 1 THEN
        SELECT COUNT(*), IFNULL(SUM(Share_Percent), 0)
        INTO v_other_count, v_other_share
        FROM mst_deposit_account_nominee
        WHERE Account_Id = v_account_id AND IFNULL(Is_Active, 0) = 1
          AND (v_action = 'ADD' OR Id <> p_nominee_id);

        IF p_nom_cust_id IS NOT NULL THEN
            SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account_nominee
            WHERE Account_Id = v_account_id AND IFNULL(Is_Active, 0) = 1 AND Nom_Cust_Id = p_nom_cust_id
              AND (v_action = 'ADD' OR Id <> p_nominee_id);
            IF v_cnt > 0 THEN
                SET v_err = 'This member is already a nominee of the account';
            END IF;
        END IF;

        IF v_err IS NULL THEN
            SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account_nominee
            WHERE Account_Id = v_account_id AND IFNULL(Is_Active, 0) = 1
              AND LOWER(TRIM(Nom_Name)) = LOWER(v_name) AND Relation_Cd = p_relation_cd
              AND (v_action = 'ADD' OR Id <> p_nominee_id);
            IF v_cnt > 0 THEN
                SET v_err = 'A nominee with the same name and relation already exists for this account';
            END IF;
        END IF;

        IF v_err IS NULL AND v_action = 'ADD' AND v_other_count >= 4 THEN
            SET v_err = 'An account can have at most 4 active nominees';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_share = IF(p_share_percent IS NULL AND v_action = 'ADD', 100 - v_other_share, p_share_percent);
        IF v_share IS NULL OR v_share <= 0 OR v_share > 100 THEN
            SET v_err = IF(p_share_percent IS NULL AND v_action = 'ADD',
                           'No share left to allocate; the account''s nominees already hold 100%',
                           'Share percent must be greater than 0 and at most 100');
        ELSEIF v_active = 1 AND v_other_share + v_share > 100 THEN
            SET v_err = CONCAT('Total nominee share cannot exceed 100% (other nominees hold ',
                               TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM FORMAT(v_other_share, 2))), '%)');
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_nominee_id AS nominee_id, v_account_id AS account_id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_deposit_account_nominee (
            Account_Id, Nom_Cust_Id, Nom_Name, Contact_No, Relation_Cd, Age, Birth_Date, Address,
            Is_Minor, Guardian_Name, Share_Percent, Is_Active, Created_By, Created_At
        ) VALUES (
            v_account_id, p_nom_cust_id, v_name, v_contact, p_relation_cd, v_age, v_birth, v_address,
            v_minor, v_guardian, v_share, 1, p_user_id, NOW()
        );

        SET v_nominee_id = LAST_INSERT_ID();

        UPDATE mst_deposit_account SET Nom_Regd = 1 WHERE Account_Id = v_account_id;

        SELECT 'SUCCESS' AS status, v_nominee_id AS nominee_id, v_account_id AS account_id,
               'Nominee added successfully' AS message;
    ELSE
        UPDATE mst_deposit_account_nominee
        SET Nom_Cust_Id = p_nom_cust_id,
            Nom_Name = v_name,
            Contact_No = v_contact,
            Relation_Cd = p_relation_cd,
            Age = v_age,
            Birth_Date = v_birth,
            Address = v_address,
            Is_Minor = v_minor,
            Guardian_Name = v_guardian,
            Share_Percent = v_share
        WHERE Id = p_nominee_id;

        SELECT 'SUCCESS' AS status, p_nominee_id AS nominee_id, v_account_id AS account_id,
               'Nominee updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_NOMINEE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_NOMINEE_LIST`(
    IN p_nominee_id INT,
    IN p_account_id INT,
    IN p_nom_cust_id INT,
    IN p_branch_id INT,
    IN p_relation_cd INT,
    IN p_is_minor TINYINT,
    IN p_is_active TINYINT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_deposit_account_nominee n
    LEFT JOIN mst_deposit_account a ON a.Account_Id = n.Account_Id
    LEFT JOIN mst_member m ON m.Member_Id = n.Nom_Cust_Id
    WHERE (p_nominee_id IS NULL OR n.Id = p_nominee_id)
      AND (p_account_id IS NULL OR n.Account_Id = p_account_id)
      AND (p_nom_cust_id IS NULL OR n.Nom_Cust_Id = p_nom_cust_id)
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
      AND (p_relation_cd IS NULL OR n.Relation_Cd = p_relation_cd)
      AND (p_is_minor IS NULL OR IF(n.Birth_Date IS NULL, IFNULL(n.Is_Minor, 0), IF(TIMESTAMPDIFF(YEAR, n.Birth_Date, CURDATE()) < 18, 1, 0)) = p_is_minor)
      AND (p_is_active IS NULL OR IFNULL(n.Is_Active, 0) = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(n.Nom_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(n.Contact_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(n.Guardian_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Appl_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Holder_Name, '') LIKE CONCAT('%', p_keyword, '%')
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        n.Id,
        n.Account_Id,
        a.Appl_No,
        a.Holder_Name,
        COALESCE(
            (SELECT sb.Account_No FROM mst_deposit_account_sb sb WHERE sb.Account_Id = a.Account_Id ORDER BY sb.Id DESC LIMIT 1),
            (SELECT td.Account_No FROM mst_deposit_account_td td WHERE td.Account_Id = a.Account_Id ORDER BY td.Id DESC LIMIT 1)
        ) AS Account_No,
        a.Branch_Id,
        IF(a.Closing_Date IS NULL, 0, 1) AS Account_Is_Closed,
        n.Nom_Cust_Id,
        m.Ref_Code AS Nom_Cust_Ref_Code,
        n.Nom_Name,
        n.Contact_No,
        n.Relation_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 35 AND o.Opt_Code = n.Relation_Cd) AS Relation_Desc,
        IF(n.Birth_Date IS NULL, n.Age, TIMESTAMPDIFF(YEAR, n.Birth_Date, CURDATE())) AS Age,
        n.Birth_Date,
        n.Address,
        IF(n.Birth_Date IS NULL, IFNULL(n.Is_Minor, 0), IF(TIMESTAMPDIFF(YEAR, n.Birth_Date, CURDATE()) < 18, 1, 0)) AS Is_Minor,
        n.Guardian_Name,
        n.Share_Percent,
        IFNULL((SELECT SUM(x.Share_Percent) FROM mst_deposit_account_nominee x
                WHERE x.Account_Id = n.Account_Id AND IFNULL(x.Is_Active, 0) = 1), 0) AS Account_Total_Share,
        IFNULL(n.Is_Active, 0) AS Is_Active,
        n.Created_By,
        u.User_Name AS Created_By_Name,
        n.Created_At
    FROM mst_deposit_account_nominee n
    LEFT JOIN mst_deposit_account a ON a.Account_Id = n.Account_Id
    LEFT JOIN mst_member m ON m.Member_Id = n.Nom_Cust_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = n.Created_By
    WHERE (p_nominee_id IS NULL OR n.Id = p_nominee_id)
      AND (p_account_id IS NULL OR n.Account_Id = p_account_id)
      AND (p_nom_cust_id IS NULL OR n.Nom_Cust_Id = p_nom_cust_id)
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
      AND (p_relation_cd IS NULL OR n.Relation_Cd = p_relation_cd)
      AND (p_is_minor IS NULL OR IF(n.Birth_Date IS NULL, IFNULL(n.Is_Minor, 0), IF(TIMESTAMPDIFF(YEAR, n.Birth_Date, CURDATE()) < 18, 1, 0)) = p_is_minor)
      AND (p_is_active IS NULL OR IFNULL(n.Is_Active, 0) = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(n.Nom_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(n.Contact_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(n.Guardian_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Appl_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Holder_Name, '') LIKE CONCAT('%', p_keyword, '%')
      )
    ORDER BY n.Account_Id DESC, IFNULL(n.Is_Active, 0) DESC, n.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_NOMINEE_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
