CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_NOMINEE_STATUS`(
    IN p_nominee_id INT,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current TINYINT DEFAULT NULL;
    DECLARE v_account_id INT DEFAULT NULL;
    DECLARE v_cust_id INT DEFAULT NULL;
    DECLARE v_name VARCHAR(120) DEFAULT NULL;
    DECLARE v_relation INT DEFAULT NULL;
    DECLARE v_share DECIMAL(6,2) DEFAULT 0;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_other_share DECIMAL(8,2) DEFAULT 0;
    DECLARE v_other_count INT DEFAULT 0;
    DECLARE v_err VARCHAR(255) DEFAULT NULL;

    SELECT COUNT(*), MAX(IFNULL(Is_Active, 0)), MAX(Account_Id), MAX(Nom_Cust_Id), MAX(Nom_Name), MAX(Relation_Cd), MAX(Share_Percent)
    INTO v_cnt, v_current, v_account_id, v_cust_id, v_name, v_relation, v_share
    FROM mst_deposit_account_nominee WHERE Id = p_nominee_id;

    IF p_nominee_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Nominee not found';
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SET v_err = 'Status must be 1 (active) or 0 (inactive)';
    ELSE
        SELECT MAX(Closing_Date) INTO v_closing FROM mst_deposit_account WHERE Account_Id = v_account_id;
        IF v_closing IS NOT NULL THEN
            SET v_err = 'Nominees of a closed deposit account cannot be changed';
        END IF;
    END IF;

    IF v_err IS NULL AND p_is_active = 1 AND v_current = 0 THEN
        SELECT COUNT(*), IFNULL(SUM(Share_Percent), 0) INTO v_other_count, v_other_share
        FROM mst_deposit_account_nominee
        WHERE Account_Id = v_account_id AND IFNULL(Is_Active, 0) = 1 AND Id <> p_nominee_id;

        IF v_other_count >= 4 THEN
            SET v_err = 'An account can have at most 4 active nominees';
        ELSEIF v_other_share + IFNULL(v_share, 0) > 100 THEN
            SET v_err = CONCAT('Total nominee share cannot exceed 100% (other nominees hold ',
                               TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM FORMAT(v_other_share, 2))), '%). Reduce the share first');
        ELSE
            SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account_nominee
            WHERE Account_Id = v_account_id AND IFNULL(Is_Active, 0) = 1 AND Id <> p_nominee_id
              AND ((v_cust_id IS NOT NULL AND Nom_Cust_Id = v_cust_id)
                   OR (LOWER(TRIM(Nom_Name)) = LOWER(TRIM(v_name)) AND Relation_Cd = v_relation));
            IF v_cnt > 0 THEN
                SET v_err = 'The same nominee is already active for this account';
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_nominee_id AS nominee_id, v_account_id AS account_id, v_err AS message;
    ELSEIF v_current = p_is_active THEN
        SELECT 'SUCCESS' AS status, p_nominee_id AS nominee_id, v_account_id AS account_id,
               IF(p_is_active = 1, 'Nominee is already active', 'Nominee is already inactive') AS message;
    ELSE
        UPDATE mst_deposit_account_nominee SET Is_Active = p_is_active WHERE Id = p_nominee_id;

        UPDATE mst_deposit_account
        SET Nom_Regd = IF(EXISTS (SELECT 1 FROM mst_deposit_account_nominee
                                  WHERE Account_Id = v_account_id AND IFNULL(Is_Active, 0) = 1), 1, 0)
        WHERE Account_Id = v_account_id;

        SELECT 'SUCCESS' AS status, p_nominee_id AS nominee_id, v_account_id AS account_id,
               IF(p_is_active = 1, 'Nominee activated successfully', 'Nominee deactivated successfully') AS message;
    END IF;
END ;;
DELIMITER ;
