DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SCHEME_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_scheme_id INT,
    IN p_scheme_name VARCHAR(100),
    IN p_deposit_type_cd TINYINT,
    IN p_prod_type_cd TINYINT,
    IN p_roi_percent DECIMAL(5,2),
    IN p_intt_type_cd TINYINT,
    IN p_intt_payout_cd TINYINT,
    IN p_min_balance DECIMAL(8,2),
    IN p_withd_allow TINYINT,
    IN p_max_withd_amt DECIMAL(8,2),
    IN p_inop_days SMALLINT,
    IN p_prn_ledger INT,
    IN p_intt_ledg INT,
    IN p_field_coll TINYINT,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_action VARCHAR(10);
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_name VARCHAR(100);
    DECLARE v_code VARCHAR(25) DEFAULT NULL;
    DECLARE v_prod_grp SMALLINT DEFAULT NULL;
    DECLARE v_withd_allow TINYINT DEFAULT 0;
    DECLARE v_max_withd DECIMAL(8,2) DEFAULT NULL;
    DECLARE v_old_prn INT DEFAULT NULL;
    DECLARE v_old_intt INT DEFAULT NULL;
    DECLARE v_ledger_active TINYINT DEFAULT NULL;
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_gen_code VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_name = NULLIF(TRIM(IFNULL(p_scheme_name, '')), '');
    SET v_withd_allow = IF(IFNULL(p_withd_allow, 0) = 1, 1, 0);
    SET v_max_withd = IF(v_withd_allow = 1, p_max_withd_amt, NULL);

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Invalid action. Use ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_deposit_scheme WHERE Scheme_Id = p_scheme_id;
        IF v_cnt = 0 THEN
            SET v_err = 'Deposit scheme not found';
        END IF;
    END IF;

    IF v_err IS NULL AND v_name IS NULL THEN
        SET v_err = 'Scheme name is required';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_deposit_scheme
        WHERE LOWER(Scheme_Name) = LOWER(v_name)
          AND (v_action = 'ADD' OR Scheme_Id <> p_scheme_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Scheme name already exists';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 3 AND Opt_Code = p_deposit_type_cd AND Is_Active = 1;
        IF p_deposit_type_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid deposit type';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_prod_grp = CASE p_deposit_type_cd WHEN 1 THEN 5 WHEN 2 THEN 6 ELSE NULL END;
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = v_prod_grp AND Opt_Code = p_prod_type_cd AND Is_Active = 1;
        IF p_prod_type_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid product type for the selected deposit type';
        END IF;
    END IF;

    IF v_err IS NULL AND p_roi_percent IS NOT NULL AND (p_roi_percent < 0 OR p_roi_percent > 100) THEN
        SET v_err = 'Rate of interest must be between 0 and 100';
    END IF;

    IF v_err IS NULL AND p_intt_type_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 12 AND Opt_Code = p_intt_type_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid interest type';
        END IF;
    END IF;

    IF v_err IS NULL AND p_intt_payout_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 10 AND Opt_Code = p_intt_payout_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid interest payout';
        END IF;
    END IF;

    IF v_err IS NULL AND p_min_balance IS NOT NULL AND p_min_balance < 0 THEN
        SET v_err = 'Minimum balance cannot be negative';
    END IF;

    IF v_err IS NULL AND v_max_withd IS NOT NULL AND v_max_withd < 0 THEN
        SET v_err = 'Maximum withdrawal amount cannot be negative';
    END IF;

    IF v_err IS NULL AND p_inop_days IS NOT NULL AND p_inop_days < 0 THEN
        SET v_err = 'Inoperative days cannot be negative';
    END IF;

    
    
    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT Prn_Ledger, Intt_Ledg INTO v_old_prn, v_old_intt
        FROM mst_deposit_scheme WHERE Scheme_Id = p_scheme_id;
    END IF;

    IF v_err IS NULL AND p_prn_ledger IS NOT NULL THEN
        SET v_ledger_active = (SELECT IFNULL(Is_Active, 0) FROM mst_acct_ledger WHERE Ledger_Id = p_prn_ledger);
        IF v_ledger_active IS NULL THEN
            SET v_err = 'Principal ledger not found';
        ELSEIF v_ledger_active <> 1 AND NOT (p_prn_ledger <=> v_old_prn) THEN
            SET v_err = 'Principal ledger is inactive';
        END IF;
    END IF;

    IF v_err IS NULL AND p_intt_ledg IS NOT NULL THEN
        SET v_ledger_active = (SELECT IFNULL(Is_Active, 0) FROM mst_acct_ledger WHERE Ledger_Id = p_intt_ledg);
        IF v_ledger_active IS NULL THEN
            SET v_err = 'Interest ledger not found';
        ELSEIF v_ledger_active <> 1 AND NOT (p_intt_ledg <=> v_old_intt) THEN
            SET v_err = 'Interest ledger is inactive';
        END IF;
    END IF;

    IF v_err IS NULL AND p_prn_ledger IS NOT NULL AND p_prn_ledger = p_intt_ledg THEN
        SET v_err = 'Principal ledger and interest ledger must be different';
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        CALL USP_CODE_SERIES_GENERATE('deposit_scheme', v_gen_code, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
            SET v_err = IFNULL(v_gen_msg, 'Unable to generate scheme code');
        ELSEIF CHAR_LENGTH(v_gen_code) > 25 THEN
            SET v_err = 'Generated scheme code exceeds 25 characters. Check deposit_scheme code series';
        ELSE
            SET v_code = CONVERT(v_gen_code USING utf8mb4) COLLATE utf8mb4_0900_ai_ci;
            SELECT COUNT(*) INTO v_cnt FROM mst_deposit_scheme WHERE UPPER(Scheme_Code) = UPPER(v_code);
            IF v_cnt > 0 THEN
                SET v_err = 'Scheme code already exists. Check deposit_scheme code series counter';
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status,
               IF(v_action = 'EDIT', p_scheme_id, NULL) AS scheme_id,
               NULL AS scheme_code,
               v_err AS message;

    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_deposit_scheme (
            Scheme_Name, Scheme_Code, Deposit_Type_Cd, Prod_Type_Cd, RoI_Percent,
            Intt_Type_Cd, Intt_Payout_Cd, Min_Balance, Withd_Allow, Max_Withd_Amt,
            Inop_Days, Prn_Ledger, Intt_Ledg, Field_Coll, Is_Active, Created_By, Created_At
        ) VALUES (
            v_name, v_code, p_deposit_type_cd, p_prod_type_cd, p_roi_percent,
            p_intt_type_cd, p_intt_payout_cd, p_min_balance, v_withd_allow, v_max_withd,
            p_inop_days, p_prn_ledger, p_intt_ledg, IF(IFNULL(p_field_coll, 0) = 1, 1, 0),
            IF(IFNULL(p_is_active, 1) = 1, 1, 0), p_user_id, NOW()
        );

        SET v_new_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_new_id AS scheme_id, v_code AS scheme_code,
               'Deposit scheme created successfully' AS message;

    ELSE
        UPDATE mst_deposit_scheme
        SET Scheme_Name = v_name,
            Deposit_Type_Cd = p_deposit_type_cd,
            Prod_Type_Cd = p_prod_type_cd,
            RoI_Percent = p_roi_percent,
            Intt_Type_Cd = p_intt_type_cd,
            Intt_Payout_Cd = p_intt_payout_cd,
            Min_Balance = p_min_balance,
            Withd_Allow = v_withd_allow,
            Max_Withd_Amt = v_max_withd,
            Inop_Days = p_inop_days,
            Prn_Ledger = p_prn_ledger,
            Intt_Ledg = p_intt_ledg,
            Field_Coll = IF(IFNULL(p_field_coll, 0) = 1, 1, 0),
            Is_Active = IF(p_is_active IS NULL, Is_Active, IF(p_is_active = 1, 1, 0)),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Scheme_Id = p_scheme_id;

        SELECT 'SUCCESS' AS status, p_scheme_id AS scheme_id, Scheme_Code AS scheme_code,
               'Deposit scheme updated successfully' AS message
        FROM mst_deposit_scheme
        WHERE Scheme_Id = p_scheme_id;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_SCHEME_CHARGES_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SCHEME_CHARGES_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_scheme_id INT,
    IN p_charges_ids TEXT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_action VARCHAR(10);
    DECLARE v_err VARCHAR(500) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_bad TEXT DEFAULT NULL;
    DECLARE v_inserted INT DEFAULT 0;
    DECLARE v_reactivated INT DEFAULT 0;
    DECLARE v_deactivated INT DEFAULT 0;
    DECLARE v_unchanged INT DEFAULT 0;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Invalid action. Use ADD or EDIT';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_deposit_scheme WHERE Scheme_Id = p_scheme_id;
        IF p_scheme_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Deposit scheme not found';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        IF p_charges_ids IS NULL OR JSON_VALID(p_charges_ids) = 0 THEN
            SET v_err = 'Charges ids must be a JSON array';
        ELSEIF JSON_TYPE(p_charges_ids) <> 'ARRAY' THEN
            SET v_err = 'Charges ids must be a JSON array';
        ELSEIF v_action = 'ADD' AND JSON_LENGTH(p_charges_ids) = 0 THEN
            SET v_err = 'At least one charge is required';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM JSON_TABLE(p_charges_ids, '$[*]' COLUMNS (cid INT PATH '$' NULL ON EMPTY NULL ON ERROR)) jt
        WHERE jt.cid IS NULL OR jt.cid < 1;
        IF v_cnt > 0 THEN
            SET v_err = 'Charges ids must be positive integers';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT GROUP_CONCAT(DISTINCT jt.cid ORDER BY jt.cid SEPARATOR ', ') INTO v_bad
        FROM JSON_TABLE(p_charges_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
        LEFT JOIN mst_deposit_charges c ON c.Charge_Id = jt.cid AND IFNULL(c.Is_Active, 0) = 1
        WHERE c.Charge_Id IS NULL;
        IF v_bad IS NOT NULL THEN
            SET v_err = CONCAT('Invalid or inactive deposit charge id(s): ', v_bad);
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_scheme_id AS scheme_id,
               0 AS inserted, 0 AS reactivated, 0 AS deactivated, 0 AS unchanged,
               v_err AS message;
    ELSE
        SELECT COUNT(DISTINCT jt.cid) INTO v_unchanged
        FROM JSON_TABLE(p_charges_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
        JOIN mst_deposit_scheme_charges sc
          ON sc.Scheme_Id = p_scheme_id AND sc.Charges_Id = jt.cid AND IFNULL(sc.Is_Active, 0) = 1;

        UPDATE mst_deposit_scheme_charges sc
        JOIN (
            SELECT DISTINCT jt.cid
            FROM JSON_TABLE(p_charges_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
        ) j ON j.cid = sc.Charges_Id
        SET sc.Is_Active = 1
        WHERE sc.Scheme_Id = p_scheme_id
          AND IFNULL(sc.Is_Active, 0) = 0;
        SET v_reactivated = ROW_COUNT();

        INSERT INTO mst_deposit_scheme_charges (Scheme_Id, Charges_Id, Is_Active, Created_By, Created_At)
        SELECT p_scheme_id, j.cid, 1, p_user_id, NOW()
        FROM (
            SELECT DISTINCT jt.cid
            FROM JSON_TABLE(p_charges_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
        ) j
        WHERE NOT EXISTS (
            SELECT 1 FROM mst_deposit_scheme_charges sc
            WHERE sc.Scheme_Id = p_scheme_id AND sc.Charges_Id = j.cid
        );
        SET v_inserted = ROW_COUNT();

        IF v_action = 'EDIT' THEN
            UPDATE mst_deposit_scheme_charges
            SET Is_Active = 0
            WHERE Scheme_Id = p_scheme_id
              AND IFNULL(Is_Active, 0) = 1
              AND Charges_Id NOT IN (
                  SELECT jt.cid
                  FROM JSON_TABLE(p_charges_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
              );
            SET v_deactivated = ROW_COUNT();
        END IF;

        SELECT 'SUCCESS' AS status, p_scheme_id AS scheme_id,
               v_inserted AS inserted, v_reactivated AS reactivated,
               v_deactivated AS deactivated, v_unchanged AS unchanged,
               IF(v_action = 'ADD',
                  'Deposit scheme charges assigned successfully',
                  'Deposit scheme charges updated successfully') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_SCHEME_CHARGES_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SCHEME_CHARGES_LIST`(
    IN p_id INT,
    IN p_scheme_id INT,
    IN p_charges_id INT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_deposit_scheme_charges sc
    WHERE (p_id IS NULL OR sc.Id = p_id)
      AND (p_scheme_id IS NULL OR sc.Scheme_Id = p_scheme_id)
      AND (p_charges_id IS NULL OR sc.Charges_Id = p_charges_id)
      AND (p_is_active IS NULL OR IFNULL(sc.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        sc.Id,
        sc.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        sc.Charges_Id,
        c.Charge_Name,
        c.Charge_Rate,
        c.Figure_Cd,
        fg.Opt_Description AS Figure_Desc,
        c.Max_Amount,
        c.Tax_Prcent,
        c.Charges_During_Cd,
        cd.Opt_Description AS Charges_During_Desc,
        c.Charges_Gl,
        l.Ledger_Code AS Charges_Gl_Code,
        l.Ledger_Name AS Charges_Gl_Name,
        IFNULL(c.Is_Active, 0) AS Charge_Is_Active,
        IFNULL(sc.Is_Active, 0) AS Is_Active,
        sc.Created_By,
        sc.Created_At
    FROM mst_deposit_scheme_charges sc
    LEFT JOIN mst_deposit_scheme s ON s.Scheme_Id = sc.Scheme_Id
    LEFT JOIN mst_deposit_charges c ON c.Charge_Id = sc.Charges_Id
    LEFT JOIN mst_appl_options fg ON fg.Opt_Grp_Id = 16 AND fg.Opt_Code = c.Figure_Cd
    LEFT JOIN mst_appl_options cd ON cd.Opt_Grp_Id = 15 AND cd.Opt_Code = c.Charges_During_Cd
    LEFT JOIN mst_acct_ledger l ON l.Ledger_Id = c.Charges_Gl
    WHERE (p_id IS NULL OR sc.Id = p_id)
      AND (p_scheme_id IS NULL OR sc.Scheme_Id = p_scheme_id)
      AND (p_charges_id IS NULL OR sc.Charges_Id = p_charges_id)
      AND (p_is_active IS NULL OR IFNULL(sc.Is_Active, 0) = p_is_active)
    ORDER BY s.Scheme_Code ASC, c.Charge_Name ASC, sc.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_SCHEME_CHARGES_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
