CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SCHEME_LIST`(
    IN p_scheme_id INT,
    IN p_keyword VARCHAR(100),
    IN p_deposit_type_cd TINYINT,
    IN p_prod_type_cd TINYINT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_deposit_scheme s
    WHERE (p_scheme_id IS NULL OR s.Scheme_Id = p_scheme_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(s.Scheme_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(s.Scheme_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_deposit_type_cd IS NULL OR s.Deposit_Type_Cd = p_deposit_type_cd)
      AND (p_prod_type_cd IS NULL OR s.Prod_Type_Cd = p_prod_type_cd)
      AND (p_is_active IS NULL OR IFNULL(s.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        s.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        s.Deposit_Type_Cd,
        dt.Opt_Description AS Deposit_Type_Desc,
        s.Prod_Type_Cd,
        pt.Opt_Description AS Prod_Type_Desc,
        s.RoI_Percent,
        s.Intt_Type_Cd,
        it.Opt_Description AS Intt_Type_Desc,
        s.Intt_Payout_Cd,
        ip.Opt_Description AS Intt_Payout_Desc,
        s.Min_Balance,
        s.Withd_Allow,
        s.Max_Withd_Amt,
        s.Inop_Days,
        s.Prn_Ledger,
        pl.Ledger_Code AS Prn_Ledger_Code,
        pl.Ledger_Name AS Prn_Ledger_Name,
        pl.Ledger_Type AS Prn_Ledger_Type,
        pl.MainHd_Id AS Prn_Ledger_MainHd_Id,
        ph.MainHd_Name AS Prn_Ledger_MainHd_Name,
        pl.Is_Active AS Prn_Ledger_Is_Active,
        s.Intt_Ledg,
        il.Ledger_Code AS Intt_Ledger_Code,
        il.Ledger_Name AS Intt_Ledger_Name,
        il.Ledger_Type AS Intt_Ledger_Type,
        il.MainHd_Id AS Intt_Ledger_MainHd_Id,
        ih.MainHd_Name AS Intt_Ledger_MainHd_Name,
        il.Is_Active AS Intt_Ledger_Is_Active,
        s.Field_Coll,
        s.Is_Active,
        s.Created_By,
        s.Created_At,
        s.Updated_By,
        s.Updated_At
    FROM mst_deposit_scheme s
    LEFT JOIN mst_appl_options dt
           ON dt.Opt_Grp_Id = 3 AND dt.Opt_Code = s.Deposit_Type_Cd
    LEFT JOIN mst_appl_options pt
           ON pt.Opt_Grp_Id = CASE s.Deposit_Type_Cd WHEN 1 THEN 5 WHEN 2 THEN 6 END
          AND pt.Opt_Code = s.Prod_Type_Cd
    LEFT JOIN mst_appl_options it
           ON it.Opt_Grp_Id = 12 AND it.Opt_Code = s.Intt_Type_Cd
    LEFT JOIN mst_appl_options ip
           ON ip.Opt_Grp_Id = 10 AND ip.Opt_Code = s.Intt_Payout_Cd
    LEFT JOIN mst_acct_ledger pl ON pl.Ledger_Id = s.Prn_Ledger
    LEFT JOIN mst_acct_head ph ON ph.MainHd_Id = pl.MainHd_Id
    LEFT JOIN mst_acct_ledger il ON il.Ledger_Id = s.Intt_Ledg
    LEFT JOIN mst_acct_head ih ON ih.MainHd_Id = il.MainHd_Id
    WHERE (p_scheme_id IS NULL OR s.Scheme_Id = p_scheme_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(s.Scheme_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(s.Scheme_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_deposit_type_cd IS NULL OR s.Deposit_Type_Cd = p_deposit_type_cd)
      AND (p_prod_type_cd IS NULL OR s.Prod_Type_Cd = p_prod_type_cd)
      AND (p_is_active IS NULL OR IFNULL(s.Is_Active, 0) = p_is_active)
    ORDER BY s.Scheme_Code ASC, s.Scheme_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
