/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SCHEME_SLAB_ADD`(
    IN p_scheme_id INT,
    IN p_min_duration SMALLINT,
    IN p_max_duration SMALLINT,
    IN p_term_cd TINYINT,
    IN p_roi DECIMAL(5,2),
    IN p_lock_period SMALLINT,
    IN p_effect_frm DATE,
    IN p_effect_upto DATE,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_active TINYINT DEFAULT 1;

    SET v_active = IF(IFNULL(p_is_active, 1) = 1, 1, 0);

    SELECT COUNT(*) INTO v_cnt FROM mst_deposit_scheme WHERE Scheme_Id = p_scheme_id;
    IF p_scheme_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Deposit scheme not found';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 7 AND Opt_Code = p_term_cd AND Is_Active = 1;
        IF p_term_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid term';
        END IF;
    END IF;

    IF v_err IS NULL AND (p_min_duration IS NULL OR p_min_duration < 1) THEN
        SET v_err = 'Minimum duration must be at least 1';
    END IF;

    IF v_err IS NULL AND (p_max_duration IS NULL OR p_max_duration < p_min_duration) THEN
        SET v_err = 'Maximum duration cannot be less than minimum duration';
    END IF;

    IF v_err IS NULL AND (p_roi IS NULL OR p_roi < 0 OR p_roi > 100) THEN
        SET v_err = 'Rate of interest is required and must be between 0 and 100';
    END IF;

    IF v_err IS NULL AND p_lock_period IS NOT NULL AND p_lock_period < 0 THEN
        SET v_err = 'Lock period cannot be negative';
    END IF;

    IF v_err IS NULL AND p_effect_frm IS NULL THEN
        SET v_err = 'Effective from date is required';
    END IF;

    IF v_err IS NULL AND p_effect_upto IS NOT NULL AND p_effect_upto < p_effect_frm THEN
        SET v_err = 'Effective upto date cannot be before effective from date';
    END IF;

    IF v_err IS NULL AND v_active = 1 THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_deposit_scheme_slab
        WHERE Scheme_Id = p_scheme_id
          AND Term_Cd = p_term_cd
          AND IFNULL(Is_Active, 0) = 1
          AND Min_Duration <= p_max_duration
          AND Max_Duration >= p_min_duration
          AND Effect_Frm <= IFNULL(p_effect_upto, '9999-12-31')
          AND IFNULL(Effect_Upto, '9999-12-31') >= p_effect_frm;
        IF v_cnt > 0 THEN
            SET v_err = 'An active slab already covers this duration range for this scheme in the given date range';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS id, v_err AS message;
    ELSE
        INSERT INTO mst_deposit_scheme_slab (
            Scheme_Id, Min_Duration, Max_Duration, Term_Cd, RoI, Lock_Period,
            Effect_Frm, Effect_Upto, Is_Active, Created_By, Created_At
        ) VALUES (
            p_scheme_id, p_min_duration, p_max_duration, p_term_cd, p_roi, p_lock_period,
            p_effect_frm, p_effect_upto, v_active, p_user_id, NOW()
        );

        SELECT 'SUCCESS' AS status, LAST_INSERT_ID() AS id, 'Deposit scheme slab created successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_SCHEME_SLAB_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SCHEME_SLAB_LIST`(
    IN p_id INT,
    IN p_scheme_id INT,
    IN p_term_cd TINYINT,
    IN p_duration SMALLINT,
    IN p_effective_on DATE,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_deposit_scheme_slab sl
    WHERE (p_id IS NULL OR sl.Id = p_id)
      AND (p_scheme_id IS NULL OR sl.Scheme_Id = p_scheme_id)
      AND (p_term_cd IS NULL OR sl.Term_Cd = p_term_cd)
      AND (p_duration IS NULL OR (sl.Min_Duration <= p_duration AND sl.Max_Duration >= p_duration))
      AND (
          p_effective_on IS NULL
          OR (sl.Effect_Frm <= p_effective_on AND IFNULL(sl.Effect_Upto, '9999-12-31') >= p_effective_on)
      )
      AND (p_is_active IS NULL OR IFNULL(sl.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        sl.Id,
        sl.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        sl.Min_Duration,
        sl.Max_Duration,
        sl.Term_Cd,
        t.Opt_Description AS Term_Desc,
        sl.RoI,
        sl.Lock_Period,
        sl.Effect_Frm,
        sl.Effect_Upto,
        sl.Is_Active,
        sl.Created_By,
        sl.Created_At
    FROM mst_deposit_scheme_slab sl
    LEFT JOIN mst_deposit_scheme s ON s.Scheme_Id = sl.Scheme_Id
    LEFT JOIN mst_appl_options t ON t.Opt_Grp_Id = 7 AND t.Opt_Code = sl.Term_Cd
    WHERE (p_id IS NULL OR sl.Id = p_id)
      AND (p_scheme_id IS NULL OR sl.Scheme_Id = p_scheme_id)
      AND (p_term_cd IS NULL OR sl.Term_Cd = p_term_cd)
      AND (p_duration IS NULL OR (sl.Min_Duration <= p_duration AND sl.Max_Duration >= p_duration))
      AND (
          p_effective_on IS NULL
          OR (sl.Effect_Frm <= p_effective_on AND IFNULL(sl.Effect_Upto, '9999-12-31') >= p_effective_on)
      )
      AND (p_is_active IS NULL OR IFNULL(sl.Is_Active, 0) = p_is_active)
    ORDER BY s.Scheme_Code ASC, sl.Term_Cd ASC, sl.Min_Duration ASC, sl.Effect_Frm DESC, sl.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_SCHEME_SLAB_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
