/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SCHEME_SLAB_STATUS`(
    IN p_id INT,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current TINYINT DEFAULT NULL;
    DECLARE v_scheme_id INT;
    DECLARE v_term_cd TINYINT;
    DECLARE v_min SMALLINT;
    DECLARE v_max SMALLINT;
    DECLARE v_frm DATE;
    DECLARE v_upto DATE;

    SELECT COUNT(*) INTO v_cnt FROM mst_deposit_scheme_slab WHERE Id = p_id;

    IF v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_id AS id, NULL AS is_active, 'Deposit scheme slab not found' AS message;
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_id AS id, NULL AS is_active,
               'Status must be 1 (active) or 0 (inactive)' AS message;
    ELSE
        SELECT IFNULL(Is_Active, 0), Scheme_Id, Term_Cd, Min_Duration, Max_Duration, Effect_Frm, Effect_Upto
        INTO v_current, v_scheme_id, v_term_cd, v_min, v_max, v_frm, v_upto
        FROM mst_deposit_scheme_slab
        WHERE Id = p_id;

        IF v_current = p_is_active THEN
            SELECT 'SUCCESS' AS status, p_id AS id, v_current AS is_active,
                   IF(p_is_active = 1, 'Deposit scheme slab is already active', 'Deposit scheme slab is already inactive') AS message;
        ELSE
            SET v_cnt = 0;

            IF p_is_active = 1 THEN
                SELECT COUNT(*) INTO v_cnt
                FROM mst_deposit_scheme_slab
                WHERE Scheme_Id = v_scheme_id
                  AND Term_Cd = v_term_cd
                  AND IFNULL(Is_Active, 0) = 1
                  AND Id <> p_id
                  AND Min_Duration <= v_max
                  AND Max_Duration >= v_min
                  AND Effect_Frm <= IFNULL(v_upto, '9999-12-31')
                  AND IFNULL(Effect_Upto, '9999-12-31') >= v_frm;
            END IF;

            IF v_cnt > 0 THEN
                SELECT 'ERROR' AS status, p_id AS id, v_current AS is_active,
                       'An active slab already covers this duration range for this scheme in the given date range' AS message;
            ELSE
                UPDATE mst_deposit_scheme_slab SET Is_Active = p_is_active WHERE Id = p_id;

                SELECT 'SUCCESS' AS status, p_id AS id, p_is_active AS is_active,
                       IF(p_is_active = 1, 'Deposit scheme slab activated successfully', 'Deposit scheme slab deactivated successfully') AS message;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_SCHEME_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SCHEME_STATUS`(
    IN p_scheme_id INT,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_code VARCHAR(25) DEFAULT NULL;
    DECLARE v_current TINYINT DEFAULT NULL;

    SELECT COUNT(*) INTO v_cnt FROM mst_deposit_scheme WHERE Scheme_Id = p_scheme_id;

    IF v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_scheme_id AS scheme_id, NULL AS scheme_code, NULL AS is_active,
               'Deposit scheme not found' AS message;
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_scheme_id AS scheme_id, NULL AS scheme_code, NULL AS is_active,
               'Status must be 1 (active) or 0 (inactive)' AS message;
    ELSE
        SELECT Scheme_Code, IFNULL(Is_Active, 0) INTO v_code, v_current
        FROM mst_deposit_scheme
        WHERE Scheme_Id = p_scheme_id;

        IF v_current = p_is_active THEN
            SELECT 'SUCCESS' AS status, p_scheme_id AS scheme_id, v_code AS scheme_code, v_current AS is_active,
                   IF(p_is_active = 1, 'Deposit scheme is already active', 'Deposit scheme is already inactive') AS message;
        ELSE
            UPDATE mst_deposit_scheme
            SET Is_Active = p_is_active,
                Updated_By = p_user_id,
                Updated_At = NOW()
            WHERE Scheme_Id = p_scheme_id;

            SELECT 'SUCCESS' AS status, p_scheme_id AS scheme_id, v_code AS scheme_code, p_is_active AS is_active,
                   IF(p_is_active = 1, 'Deposit scheme activated successfully', 'Deposit scheme deactivated successfully') AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_SIGNATORY_ADD_EDIT` */;
