CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SIGNATORY_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_signatory_id INT,
    IN p_account_id INT,
    IN p_cust_id INT,
    IN p_sign_file_nm VARCHAR(75),
    IN p_photo_file_nm VARCHAR(75),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_action VARCHAR(10);
    DECLARE v_signatory_id INT DEFAULT NULL;
    DECLARE v_account_id INT DEFAULT NULL;
    DECLARE v_cust_id INT DEFAULT NULL;
    DECLARE v_sign VARCHAR(75);
    DECLARE v_photo VARCHAR(75);

    DECLARE v_cust_type INT DEFAULT NULL;
    DECLARE v_primary INT DEFAULT NULL;
    DECLARE v_joint1 INT DEFAULT NULL;
    DECLARE v_joint2 INT DEFAULT NULL;
    DECLARE v_op_mode INT DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_mem_status INT DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_sign = NULLIF(TRIM(IFNULL(p_sign_file_nm, '')), '');
    SET v_photo = NULLIF(TRIM(IFNULL(p_photo_file_nm, '')), '');
    SET v_account_id = p_account_id;
    SET v_cust_id = p_cust_id;

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Account_Id), MAX(Cust_Id)
        INTO v_cnt, v_account_id, v_cust_id
        FROM mst_deposit_account_signatory WHERE Id = p_signatory_id;

        IF p_signatory_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Signatory not found';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Cust_Type_Cd), MAX(Cust_Id_Primay), MAX(Cust_Id_Joint1), MAX(Cust_Id_Joint2),
               MAX(Op_Mode_Cd), MAX(Closing_Date)
        INTO v_cnt, v_cust_type, v_primary, v_joint1, v_joint2, v_op_mode, v_closing
        FROM mst_deposit_account WHERE Account_Id = v_account_id;

        IF v_account_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Deposit account not found';
        ELSEIF v_closing IS NOT NULL THEN
            SET v_err = 'Signatories of a closed deposit account cannot be changed';
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_action = 'ADD' THEN
        SELECT COUNT(*), MAX(Current_Status_Cd) INTO v_cnt, v_mem_status
        FROM mst_member WHERE Member_Id = v_cust_id;

        IF v_cust_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Signatory member not found';
        ELSEIF IFNULL(v_mem_status, 0) <> 1 THEN
            SET v_err = 'Signatory member is not active';
        ELSEIF v_cust_type = 1 THEN
            SELECT COUNT(*) INTO v_cnt FROM mst_member_group
            WHERE Group_Id = v_primary AND Member_Id = v_cust_id AND IFNULL(Is_Active, 0) = 1;
            IF v_cnt = 0 THEN
                SET v_err = 'Signatory must be an active member of the account''s group';
            END IF;
        ELSEIF IFNULL(v_op_mode, 0) <> 5
               AND v_cust_id NOT IN (v_primary, IFNULL(v_joint1, 0), IFNULL(v_joint2, 0)) THEN
            SET v_err = 'Signatory must be an account holder (any member only for Authorised Signatory operation)';
        END IF;

        IF v_err IS NULL THEN
            SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account_signatory
            WHERE Account_Id = v_account_id AND Cust_Id = v_cust_id AND IFNULL(Is_Active, 0) = 1;
            IF v_cnt > 0 THEN
                SET v_err = 'This member is already a signatory of the account';
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_signatory_id AS signatory_id, v_account_id AS account_id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_deposit_account_signatory (
            Account_Id, Cust_Id, Sign_FileNm, Photo_FileNm, Is_Active, Created_By, Created_At
        ) VALUES (
            v_account_id, v_cust_id, v_sign, v_photo, 1, p_user_id, NOW()
        );

        SET v_signatory_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_signatory_id AS signatory_id, v_account_id AS account_id,
               'Signatory added successfully' AS message;
    ELSE
        UPDATE mst_deposit_account_signatory
        SET Sign_FileNm = v_sign,
            Photo_FileNm = v_photo
        WHERE Id = p_signatory_id;

        SELECT 'SUCCESS' AS status, p_signatory_id AS signatory_id, v_account_id AS account_id,
               'Signatory updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
