/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SIGNATORY_LIST`(
    IN p_signatory_id INT,
    IN p_account_id INT,
    IN p_cust_id INT,
    IN p_branch_id INT,
    IN p_is_active TINYINT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_deposit_account_signatory sg
    LEFT JOIN mst_deposit_account a ON a.Account_Id = sg.Account_Id
    LEFT JOIN mst_member m ON m.Member_Id = sg.Cust_Id
    WHERE (p_signatory_id IS NULL OR sg.Id = p_signatory_id)
      AND (p_account_id IS NULL OR sg.Account_Id = p_account_id)
      AND (p_cust_id IS NULL OR sg.Cust_Id = p_cust_id)
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
      AND (p_is_active IS NULL OR IFNULL(sg.Is_Active, 0) = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(m.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Appl_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Holder_Name, '') LIKE CONCAT('%', p_keyword, '%')
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        sg.Id,
        sg.Account_Id,
        a.Appl_No,
        a.Holder_Name,
        COALESCE(
            (SELECT sb.Account_No FROM mst_deposit_account_sb sb WHERE sb.Account_Id = a.Account_Id ORDER BY sb.Id DESC LIMIT 1),
            (SELECT td.Account_No FROM mst_deposit_account_td td WHERE td.Account_Id = a.Account_Id ORDER BY td.Id DESC LIMIT 1)
        ) AS Account_No,
        a.Cust_Type_Cd,
        a.Op_Mode_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 9 AND o.Opt_Code = a.Op_Mode_Cd) AS Op_Mode_Desc,
        a.Branch_Id,
        IF(a.Closing_Date IS NULL, 0, 1) AS Account_Is_Closed,
        sg.Cust_Id,
        m.Ref_Code AS Cust_Ref_Code,
        m.Member_Name AS Cust_Name,
        m.Mobile_No AS Cust_Mobile,
        CASE
            WHEN a.Cust_Type_Cd = 2 AND sg.Cust_Id = a.Cust_Id_Primay THEN 'Primary Holder'
            WHEN a.Cust_Type_Cd = 2 AND sg.Cust_Id = a.Cust_Id_Joint1 THEN 'Joint Holder 1'
            WHEN a.Cust_Type_Cd = 2 AND sg.Cust_Id = a.Cust_Id_Joint2 THEN 'Joint Holder 2'
            WHEN a.Cust_Type_Cd = 1 THEN NULLIF((SELECT MAX(mg.Member_Role) FROM mst_member_group mg
                                                WHERE mg.Group_Id = a.Cust_Id_Primay AND mg.Member_Id = sg.Cust_Id
                                                  AND IFNULL(mg.Is_Active, 0) = 1), '')
            ELSE 'Authorised Signatory'
        END AS Signatory_Role,
        sg.Sign_FileNm,
        sg.Photo_FileNm,
        m.Signature_Path AS Member_Signature_Path,
        m.Photo_Path AS Member_Photo_Path,
        IFNULL(sg.Is_Active, 0) AS Is_Active,
        sg.Created_By,
        u.User_Name AS Created_By_Name,
        sg.Created_At
    FROM mst_deposit_account_signatory sg
    LEFT JOIN mst_deposit_account a ON a.Account_Id = sg.Account_Id
    LEFT JOIN mst_member m ON m.Member_Id = sg.Cust_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = sg.Created_By
    WHERE (p_signatory_id IS NULL OR sg.Id = p_signatory_id)
      AND (p_account_id IS NULL OR sg.Account_Id = p_account_id)
      AND (p_cust_id IS NULL OR sg.Cust_Id = p_cust_id)
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
      AND (p_is_active IS NULL OR IFNULL(sg.Is_Active, 0) = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(m.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Appl_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Holder_Name, '') LIKE CONCAT('%', p_keyword, '%')
      )
    ORDER BY sg.Account_Id DESC, IFNULL(sg.Is_Active, 0) DESC, sg.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_DEPOSIT_SIGNATORY_STATUS` */;
