/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DEPOSIT_SIGNATORY_STATUS`(
    IN p_signatory_id INT,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current TINYINT DEFAULT NULL;
    DECLARE v_account_id INT DEFAULT NULL;
    DECLARE v_cust_id INT DEFAULT NULL;
    DECLARE v_cust_type INT DEFAULT NULL;
    DECLARE v_primary INT DEFAULT NULL;
    DECLARE v_joint1 INT DEFAULT NULL;
    DECLARE v_joint2 INT DEFAULT NULL;
    DECLARE v_op_mode INT DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_mem_status INT DEFAULT NULL;
    DECLARE v_err VARCHAR(255) DEFAULT NULL;

    SELECT COUNT(*), MAX(IFNULL(Is_Active, 0)), MAX(Account_Id), MAX(Cust_Id)
    INTO v_cnt, v_current, v_account_id, v_cust_id
    FROM mst_deposit_account_signatory WHERE Id = p_signatory_id;

    IF p_signatory_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Signatory not found';
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SET v_err = 'Status must be 1 (active) or 0 (inactive)';
    ELSE
        SELECT MAX(Cust_Type_Cd), MAX(Cust_Id_Primay), MAX(Cust_Id_Joint1), MAX(Cust_Id_Joint2),
               MAX(Op_Mode_Cd), MAX(Closing_Date)
        INTO v_cust_type, v_primary, v_joint1, v_joint2, v_op_mode, v_closing
        FROM mst_deposit_account WHERE Account_Id = v_account_id;
        IF v_closing IS NOT NULL THEN
            SET v_err = 'Signatories of a closed deposit account cannot be changed';
        END IF;
    END IF;

    IF v_err IS NULL AND p_is_active = 1 AND v_current = 0 THEN
        SELECT MAX(Current_Status_Cd) INTO v_mem_status FROM mst_member WHERE Member_Id = v_cust_id;

        IF IFNULL(v_mem_status, 0) <> 1 THEN
            SET v_err = 'Signatory member is not active';
        ELSEIF v_cust_type = 1 THEN
            SELECT COUNT(*) INTO v_cnt FROM mst_member_group
            WHERE Group_Id = v_primary AND Member_Id = v_cust_id AND IFNULL(Is_Active, 0) = 1;
            IF v_cnt = 0 THEN
                SET v_err = 'Signatory is no longer an active member of the account''s group';
            END IF;
        ELSEIF IFNULL(v_op_mode, 0) <> 5
               AND v_cust_id NOT IN (v_primary, IFNULL(v_joint1, 0), IFNULL(v_joint2, 0)) THEN
            SET v_err = 'Signatory is no longer an account holder';
        END IF;

        IF v_err IS NULL THEN
            SELECT COUNT(*) INTO v_cnt FROM mst_deposit_account_signatory
            WHERE Account_Id = v_account_id AND Cust_Id = v_cust_id AND IFNULL(Is_Active, 0) = 1
              AND Id <> p_signatory_id;
            IF v_cnt > 0 THEN
                SET v_err = 'This member is already an active signatory of the account';
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_signatory_id AS signatory_id, v_account_id AS account_id, v_err AS message;
    ELSEIF v_current = p_is_active THEN
        SELECT 'SUCCESS' AS status, p_signatory_id AS signatory_id, v_account_id AS account_id,
               IF(p_is_active = 1, 'Signatory is already active', 'Signatory is already inactive') AS message;
    ELSE
        UPDATE mst_deposit_account_signatory SET Is_Active = p_is_active WHERE Id = p_signatory_id;

        SELECT 'SUCCESS' AS status, p_signatory_id AS signatory_id, v_account_id AS account_id,
               IF(p_is_active = 1, 'Signatory activated successfully', 'Signatory deactivated successfully') AS message;
    END IF;
END ;;
DELIMITER ;
