CREATE DEFINER=`priority`@`%` PROCEDURE `USP_DESIGNATION_LIST`(
    IN p_status TINYINT
)
BEGIN
    SELECT Designation_Id, Designation_Name, Status
    FROM mst_designation
    WHERE (p_status IS NULL OR Status = p_status)
    ORDER BY Designation_Name ASC;
END ;;
