/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_FIN_YEAR_UPDATE`(
    IN p_year_id SMALLINT,
    IN p_year_name VARCHAR(25),
    IN p_start_date DATE,
    IN p_end_date DATE,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_year_id SMALLINT DEFAULT NULL;
    DECLARE v_exists INT DEFAULT 0;

    IF p_year_name IS NULL OR TRIM(p_year_name) = '' THEN
        SELECT 'ERROR' AS status, NULL AS year_id, 'Year name is required' AS message;
    ELSEIF p_start_date IS NULL OR p_end_date IS NULL THEN
        SELECT 'ERROR' AS status, NULL AS year_id, 'Start date and end date are required' AS message;
    ELSEIF p_end_date <= p_start_date THEN
        SELECT 'ERROR' AS status, NULL AS year_id, 'End date must be after start date' AS message;
    ELSE
        IF p_year_id IS NOT NULL AND p_year_id > 0 THEN
            SELECT COUNT(*) INTO v_exists
            FROM mst_fin_year
            WHERE Year_Id = p_year_id;

            IF v_exists = 0 THEN
                SELECT 'ERROR' AS status, p_year_id AS year_id, 'Financial year not found' AS message;
            ELSE
                UPDATE mst_fin_year
                SET
                    Year_Name = TRIM(p_year_name),
                    Start_Date = p_start_date,
                    End_Date = p_end_date,
                    Is_Active = IFNULL(p_is_active, Is_Active)
                WHERE Year_Id = p_year_id;

                SET v_year_id = p_year_id;

                IF IFNULL(p_is_active, 0) = 1 THEN
                    UPDATE mst_fin_year
                    SET Is_Active = 0
                    WHERE Year_Id <> v_year_id;
                END IF;

                SELECT 'SUCCESS' AS status, v_year_id AS year_id, 'Financial year updated successfully' AS message;
            END IF;
        ELSE
            INSERT INTO mst_fin_year (Year_Name, Start_Date, End_Date, Is_Active)
            VALUES (
                TRIM(p_year_name),
                p_start_date,
                p_end_date,
                IFNULL(p_is_active, 0)
            );

            SET v_year_id = LAST_INSERT_ID();

            IF IFNULL(p_is_active, 0) = 1 THEN
                UPDATE mst_fin_year
                SET Is_Active = 0
                WHERE Year_Id <> v_year_id;
            END IF;

            SELECT 'SUCCESS' AS status, v_year_id AS year_id, 'Financial year saved successfully' AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
