CREATE DEFINER=`priority`@`%` PROCEDURE `USP_GROUP_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_group_id INT,
    IN p_ref_code VARCHAR(25),
    IN p_group_name VARCHAR(250),
    IN p_branch_id INT,
    IN p_center_id INT,
    IN p_formation_date DATE,
    IN p_registration_no VARCHAR(50),
    IN p_registration_date DATE,
    IN p_member_no INT,
    IN p_group_type_cd INT,
    IN p_group_gender_cd INT,
    IN p_meeting_frequency_cd INT,
    IN p_meeting_day_cd INT,
    IN p_meeting_time TIME,
    IN p_village_name VARCHAR(100),
    IN p_gp_name VARCHAR(100),
    IN p_block_name VARCHAR(100),
    IN p_district_name VARCHAR(100),
    IN p_state_cd INT,
    IN p_pin_code VARCHAR(10),
    IN p_president_member_id INT,
    IN p_secretary_member_id INT,
    IN p_treasurer_member_id INT,
    IN p_bank_name VARCHAR(150),
    IN p_bank_branch VARCHAR(150),
    IN p_bank_account_no VARCHAR(40),
    IN p_ifsc_code VARCHAR(20),
    IN p_savings_amount DECIMAL(12,2),
    IN p_internal_lending TINYINT,
    IN p_grade VARCHAR(10),
    IN p_grade_date DATE,
    IN p_fo_id INT,
    IN p_adm_fees DECIMAL(10,2),
    IN p_remarks VARCHAR(100),
    IN p_status_cd INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_action VARCHAR(10);
    DECLARE v_group_id INT DEFAULT NULL;
    DECLARE v_group_code VARCHAR(25) DEFAULT NULL;
    DECLARE v_gen_code VARCHAR(150) DEFAULT NULL;
    DECLARE v_gen_status VARCHAR(10) DEFAULT NULL;
    DECLARE v_gen_msg VARCHAR(255) DEFAULT NULL;
    DECLARE v_cur_branch INT DEFAULT NULL;
    DECLARE v_cur_center INT DEFAULT NULL;
    DECLARE v_cur_fo INT DEFAULT NULL;
    DECLARE v_cur_status INT DEFAULT NULL;
    DECLARE v_active_members INT DEFAULT 0;
    DECLARE v_min_mem INT DEFAULT 0;
    DECLARE v_max_mem INT DEFAULT 0;
    DECLARE v_status INT DEFAULT 1;
    DECLARE v_name VARCHAR(250);
    DECLARE v_ref VARCHAR(25);
    DECLARE v_reg_no VARCHAR(50);
    DECLARE v_pin VARCHAR(10);
    DECLARE v_acct VARCHAR(40);
    DECLARE v_ifsc VARCHAR(20);
    DECLARE v_grade VARCHAR(10);

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_name = NULLIF(TRIM(IFNULL(p_group_name, '')), '');
    SET v_ref = NULLIF(TRIM(IFNULL(p_ref_code, '')), '');
    SET v_reg_no = NULLIF(TRIM(IFNULL(p_registration_no, '')), '');
    SET v_pin = NULLIF(TRIM(IFNULL(p_pin_code, '')), '');
    SET v_acct = NULLIF(TRIM(IFNULL(p_bank_account_no, '')), '');
    SET v_ifsc = UPPER(NULLIF(TRIM(IFNULL(p_ifsc_code, '')), ''));
    SET v_grade = UPPER(NULLIF(TRIM(IFNULL(p_grade, '')), ''));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Branch_Id), MAX(Center_Id), MAX(FO_Id), MAX(Current_Status_Cd)
        INTO v_cnt, v_cur_branch, v_cur_center, v_cur_fo, v_cur_status
        FROM mst_group WHERE Group_Id = p_group_id;

        IF p_group_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Group not found';
        ELSEIF v_cur_status = 4 THEN
            SET v_err = 'Closed group cannot be edited';
        ELSE
            SELECT COUNT(*) INTO v_active_members
            FROM mst_member_group WHERE Group_Id = p_group_id AND Is_Active = 1;
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        SET v_status = IFNULL(p_status_cd, 1);
        IF v_status NOT IN (1, 2) THEN
            SET v_err = 'New group status must be 1 (Active) or 2 (Inactive)';
        END IF;
    END IF;

    IF v_err IS NULL AND v_name IS NULL THEN
        SET v_err = 'Group name is required';
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM priomicro_core.mst_org_branch
        WHERE Branch_Id = p_branch_id
          AND (IFNULL(Is_Active, 0) = 1 OR (v_action = 'EDIT' AND Branch_Id = v_cur_branch));
        IF p_branch_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Active branch not found';
        ELSEIF v_action = 'EDIT' AND p_branch_id <> v_cur_branch AND v_active_members > 0 THEN
            SET v_err = 'Branch cannot be changed while the group has active members';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_center_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_center
        WHERE Center_Id = p_center_id
          AND Branch_Id = p_branch_id
          AND (IFNULL(Is_Active, 0) = 1 OR (v_action = 'EDIT' AND Center_Id = v_cur_center));
        IF v_cnt = 0 THEN
            SET v_err = 'Active center not found for this branch';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_group
        WHERE Branch_Id = p_branch_id
          AND LOWER(TRIM(Group_Name)) = LOWER(v_name)
          AND (v_action = 'ADD' OR Group_Id <> p_group_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Group name already exists for this branch';
        END IF;
    END IF;

    IF v_err IS NULL AND v_ref IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_group
        WHERE LOWER(Ref_Code) = LOWER(v_ref)
          AND (v_action = 'ADD' OR Group_Id <> p_group_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Reference code already exists';
        END IF;
    END IF;

    IF v_err IS NULL AND v_reg_no IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_group
        WHERE LOWER(Registration_No) = LOWER(v_reg_no)
          AND (v_action = 'ADD' OR Group_Id <> p_group_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Registration number already exists';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_formation_date IS NOT NULL AND p_formation_date > CURDATE() THEN
        SET v_err = 'Formation date cannot be in the future';
    END IF;

    IF v_err IS NULL AND p_registration_date IS NOT NULL THEN
        IF p_registration_date > CURDATE() THEN
            SET v_err = 'Registration date cannot be in the future';
        ELSEIF p_formation_date IS NOT NULL AND p_registration_date < p_formation_date THEN
            SET v_err = 'Registration date cannot be before formation date';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_member_no IS NOT NULL THEN
        SELECT IFNULL(MAX(CASE WHEN Id = 3 THEN Value END), 0),
               IFNULL(MAX(CASE WHEN Id = 4 THEN Value END), 0)
        INTO v_min_mem, v_max_mem
        FROM mst_settings_global
        WHERE Id IN (3, 4);

        IF p_member_no < 1 OR p_member_no > 127 THEN
            SET v_err = 'Number of members must be between 1 and 127';
        ELSEIF v_min_mem > 0 AND p_member_no < v_min_mem THEN
            SET v_err = CONCAT('Number of members cannot be less than ', v_min_mem);
        ELSEIF v_max_mem > 0 AND p_member_no > v_max_mem THEN
            SET v_err = CONCAT('Number of members cannot be more than ', v_max_mem);
        ELSEIF p_member_no < v_active_members THEN
            SET v_err = CONCAT('Number of members cannot be less than the active members (', v_active_members, ')');
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 24 AND Opt_Code = p_group_type_cd AND Is_Active = 1;
        IF p_group_type_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid group type';
        END IF;
    END IF;

    IF v_err IS NULL AND p_group_gender_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 25 AND Opt_Code = p_group_gender_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid group gender';
        END IF;
    END IF;

    IF v_err IS NULL AND p_meeting_frequency_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 26 AND Opt_Code = p_meeting_frequency_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid meeting frequency';
        END IF;
    END IF;

    IF v_err IS NULL AND p_meeting_day_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 2 AND Opt_Code = p_meeting_day_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid meeting day';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_state_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM priomicro_core.mst_states WHERE State_Cd = p_state_cd;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid state';
        END IF;
    END IF;

    IF v_err IS NULL AND v_pin IS NOT NULL AND v_pin NOT REGEXP '^[1-9][0-9]{5}$' THEN
        SET v_err = 'PIN code must be 6 digits';
    END IF;

    
    IF v_err IS NULL AND v_action = 'ADD'
       AND (p_president_member_id IS NOT NULL OR p_secretary_member_id IS NOT NULL OR p_treasurer_member_id IS NOT NULL) THEN
        SET v_err = 'President, secretary and treasurer can be set after members join the group';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' AND (
        (p_president_member_id IS NOT NULL AND p_president_member_id = p_secretary_member_id)
        OR (p_president_member_id IS NOT NULL AND p_president_member_id = p_treasurer_member_id)
        OR (p_secretary_member_id IS NOT NULL AND p_secretary_member_id = p_treasurer_member_id)
    ) THEN
        SET v_err = 'President, secretary and treasurer must be different members';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*) INTO v_cnt
        FROM (
            SELECT p_president_member_id AS Member_Id
            UNION ALL SELECT p_secretary_member_id
            UNION ALL SELECT p_treasurer_member_id
        ) ob
        WHERE ob.Member_Id IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM mst_member_group mg
              WHERE mg.Group_Id = p_group_id
                AND mg.Member_Id = ob.Member_Id
                AND mg.Is_Active = 1
          );
        IF v_cnt > 0 THEN
            SET v_err = 'President, secretary and treasurer must be active members of this group';
        END IF;
    END IF;

    
    IF v_err IS NULL AND (v_acct IS NULL) <> (v_ifsc IS NULL) THEN
        SET v_err = 'Bank account number and IFSC code must be given together';
    END IF;

    IF v_err IS NULL AND v_acct IS NOT NULL AND v_acct NOT REGEXP '^[0-9]{6,20}$' THEN
        SET v_err = 'Bank account number must be 6 to 20 digits';
    END IF;

    IF v_err IS NULL AND v_ifsc IS NOT NULL AND v_ifsc NOT REGEXP '^[A-Z]{4}0[A-Z0-9]{6}$' THEN
        SET v_err = 'Invalid IFSC code';
    END IF;

    
    IF v_err IS NULL AND p_savings_amount IS NOT NULL AND (p_savings_amount < 0 OR p_savings_amount > 999999.99) THEN
        SET v_err = 'Savings amount must be between 0 and 999999.99';
    END IF;

    IF v_err IS NULL AND p_adm_fees IS NOT NULL AND (p_adm_fees < 0 OR p_adm_fees > 9999.99) THEN
        SET v_err = 'Admission fees must be between 0 and 9999.99';
    END IF;

    IF v_err IS NULL AND p_internal_lending IS NOT NULL AND p_internal_lending NOT IN (0, 1) THEN
        SET v_err = 'Internal lending must be 1 or 0';
    END IF;

    IF v_err IS NULL AND p_grade_date IS NOT NULL THEN
        IF v_grade IS NULL THEN
            SET v_err = 'Grade is required when grade date is given';
        ELSEIF p_grade_date > CURDATE() THEN
            SET v_err = 'Grade date cannot be in the future';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_fo_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_staff
        WHERE Staff_Id = p_fo_id
          AND Branch_Id = p_branch_id
          AND (IFNULL(Status, 0) = 1 OR (v_action = 'EDIT' AND Staff_Id = v_cur_fo));
        IF v_cnt = 0 THEN
            SET v_err = 'Active field officer not found for this branch';
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        CALL USP_CODE_SERIES_GENERATE('group', v_gen_code, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
            SET v_err = CONCAT('Unable to generate group code: ', IFNULL(v_gen_msg, 'check the group code series'));
        ELSEIF CHAR_LENGTH(v_gen_code) > 25 THEN
            SET v_err = 'Generated group code exceeds 25 characters. Check group code series';
        ELSE
            SET v_group_code = v_gen_code;
            SELECT COUNT(*) INTO v_cnt FROM mst_group WHERE UPPER(Group_Code) = UPPER(v_group_code);
            IF v_cnt > 0 THEN
                SET v_err = 'Generated group code already exists. Check group code series counter';
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_group_id AS group_id, NULL AS group_code, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        SELECT IFNULL(MAX(Group_Id), 0) + 1
        INTO v_group_id
        FROM mst_group
        FOR UPDATE;

        IF v_group_id > 32767 THEN
            SELECT 'ERROR' AS status, NULL AS group_id, NULL AS group_code, 'Group id limit reached' AS message;
        ELSE
            INSERT INTO mst_group (
                Group_Id, Group_Code, Ref_Code, Group_Name, Branch_Id, Center_Id,
                Formation_Date, Registration_No, Registration_Date, Member_No,
                Group_Type_Cd, Group_Gender_Cd, Meeting_Frequency_Cd, Meeting_Day_Cd, Meeting_Time,
                Village_Name, GP_Name, Block_Name, District_Name, State_Cd, Pin_Code,
                Bank_Name, Bank_Branch, Bank_Account_No, IFSC_Code,
                Savings_Amount, Internal_Lending, Grade, Grade_Date, FO_Id, Adm_Fees, Remarks,
                Current_Status_Cd, Created_By, Created_At
            ) VALUES (
                v_group_id, v_group_code, v_ref, v_name, p_branch_id, p_center_id,
                p_formation_date, v_reg_no, p_registration_date, p_member_no,
                p_group_type_cd, p_group_gender_cd, p_meeting_frequency_cd, p_meeting_day_cd, p_meeting_time,
                NULLIF(TRIM(IFNULL(p_village_name, '')), ''),
                NULLIF(TRIM(IFNULL(p_gp_name, '')), ''),
                NULLIF(TRIM(IFNULL(p_block_name, '')), ''),
                NULLIF(TRIM(IFNULL(p_district_name, '')), ''),
                p_state_cd, v_pin,
                NULLIF(TRIM(IFNULL(p_bank_name, '')), ''),
                NULLIF(TRIM(IFNULL(p_bank_branch, '')), ''),
                v_acct, v_ifsc,
                IFNULL(p_savings_amount, 0), IFNULL(p_internal_lending, 0), v_grade, p_grade_date,
                p_fo_id, p_adm_fees, NULLIF(TRIM(IFNULL(p_remarks, '')), ''),
                v_status, p_user_id, NOW()
            );

            SELECT 'SUCCESS' AS status, v_group_id AS group_id, v_group_code AS group_code,
                   'Group created successfully' AS message;
        END IF;
    ELSE
        UPDATE mst_group
        SET Ref_Code = v_ref,
            Group_Name = v_name,
            Branch_Id = p_branch_id,
            Center_Id = p_center_id,
            Formation_Date = p_formation_date,
            Registration_No = v_reg_no,
            Registration_Date = p_registration_date,
            Member_No = p_member_no,
            Group_Type_Cd = p_group_type_cd,
            Group_Gender_Cd = p_group_gender_cd,
            Meeting_Frequency_Cd = p_meeting_frequency_cd,
            Meeting_Day_Cd = p_meeting_day_cd,
            Meeting_Time = p_meeting_time,
            Village_Name = NULLIF(TRIM(IFNULL(p_village_name, '')), ''),
            GP_Name = NULLIF(TRIM(IFNULL(p_gp_name, '')), ''),
            Block_Name = NULLIF(TRIM(IFNULL(p_block_name, '')), ''),
            District_Name = NULLIF(TRIM(IFNULL(p_district_name, '')), ''),
            State_Cd = p_state_cd,
            Pin_Code = v_pin,
            President_Member_Id = p_president_member_id,
            Secretary_Member_Id = p_secretary_member_id,
            Treasurer_Member_Id = p_treasurer_member_id,
            Bank_Name = NULLIF(TRIM(IFNULL(p_bank_name, '')), ''),
            Bank_Branch = NULLIF(TRIM(IFNULL(p_bank_branch, '')), ''),
            Bank_Account_No = v_acct,
            IFSC_Code = v_ifsc,
            Savings_Amount = IFNULL(p_savings_amount, 0),
            Internal_Lending = IFNULL(p_internal_lending, 0),
            Grade = v_grade,
            Grade_Date = p_grade_date,
            FO_Id = p_fo_id,
            Adm_Fees = p_adm_fees,
            Remarks = NULLIF(TRIM(IFNULL(p_remarks, '')), ''),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Group_Id = p_group_id;

        
        UPDATE mst_member_group
        SET Member_Role = CASE
                WHEN Member_Id = p_president_member_id THEN 'President'
                WHEN Member_Id = p_secretary_member_id THEN 'Secretary'
                WHEN Member_Id = p_treasurer_member_id THEN 'Treasurer'
                ELSE 'Member'
            END,
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Group_Id = p_group_id
          AND Is_Active = 1
          AND (
              Member_Role IN ('President', 'Secretary', 'Treasurer')
              OR Member_Id IN (p_president_member_id, p_secretary_member_id, p_treasurer_member_id)
          );

        SELECT 'SUCCESS' AS status, p_group_id AS group_id,
               (SELECT Group_Code FROM mst_group WHERE Group_Id = p_group_id) AS group_code,
               'Group updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_GROUP_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_GROUP_LIST`(
    IN p_group_id INT,
    IN p_branch_id INT,
    IN p_center_id INT,
    IN p_fo_id INT,
    IN p_group_type_cd INT,
    IN p_status_cd INT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_group g
    WHERE (p_group_id IS NULL OR g.Group_Id = p_group_id)
      AND (p_branch_id IS NULL OR g.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR g.Center_Id = p_center_id)
      AND (p_fo_id IS NULL OR g.FO_Id = p_fo_id)
      AND (p_group_type_cd IS NULL OR g.Group_Type_Cd = p_group_type_cd)
      AND (p_status_cd IS NULL OR g.Current_Status_Cd = p_status_cd)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR g.Group_Name LIKE CONCAT('%', p_keyword, '%')
          OR g.Group_Code LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(g.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(g.Registration_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(g.Village_Name, '') LIKE CONCAT('%', p_keyword, '%')
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        g.Group_Id,
        g.Group_Code,
        g.Ref_Code,
        g.Group_Name,
        g.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        g.Center_Id,
        c.Center_Name,
        g.Formation_Date,
        g.Registration_No,
        g.Registration_Date,
        g.Member_No,
        IFNULL(mc.Active_Members, 0) AS Active_Members,
        g.Group_Type_Cd,
        gt.Opt_Description AS Group_Type_Desc,
        g.Group_Gender_Cd,
        gg.Opt_Description AS Group_Gender_Desc,
        g.Meeting_Frequency_Cd,
        mf.Opt_Description AS Meeting_Frequency_Desc,
        g.Meeting_Day_Cd,
        md.Opt_Description AS Meeting_Day_Desc,
        TIME_FORMAT(g.Meeting_Time, '%H:%i') AS Meeting_Time,
        g.Village_Name,
        g.GP_Name,
        g.Block_Name,
        g.District_Name,
        g.State_Cd,
        stt.State_Name,
        g.Pin_Code,
        g.President_Member_Id,
        pm.Member_Name AS President_Name,
        g.Secretary_Member_Id,
        sm.Member_Name AS Secretary_Name,
        g.Treasurer_Member_Id,
        tm.Member_Name AS Treasurer_Name,
        g.Bank_Name,
        g.Bank_Branch,
        g.Bank_Account_No,
        g.IFSC_Code,
        g.Savings_Amount,
        g.Internal_Lending,
        g.Grade,
        g.Grade_Date,
        g.FO_Id,
        fo.Employee_Code AS FO_Code,
        fo.Full_Name AS FO_Name,
        g.Adm_Fees,
        g.Remarks,
        g.Current_Status_Cd AS Status_Cd,
        st.Opt_Description AS Status_Desc,
        g.Created_By,
        g.Created_At,
        g.Updated_By,
        g.Updated_At
    FROM mst_group g
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = g.Branch_Id
    LEFT JOIN mst_center c ON c.Center_Id = g.Center_Id
    LEFT JOIN priomicro_core.mst_states stt ON stt.State_Cd = g.State_Cd
    LEFT JOIN mst_staff fo ON fo.Staff_Id = g.FO_Id
    LEFT JOIN mst_member pm ON pm.Member_Id = g.President_Member_Id
    LEFT JOIN mst_member sm ON sm.Member_Id = g.Secretary_Member_Id
    LEFT JOIN mst_member tm ON tm.Member_Id = g.Treasurer_Member_Id
    LEFT JOIN mst_appl_options gt ON gt.Opt_Grp_Id = 24 AND gt.Opt_Code = g.Group_Type_Cd
    LEFT JOIN mst_appl_options gg ON gg.Opt_Grp_Id = 25 AND gg.Opt_Code = g.Group_Gender_Cd
    LEFT JOIN mst_appl_options mf ON mf.Opt_Grp_Id = 26 AND mf.Opt_Code = g.Meeting_Frequency_Cd
    LEFT JOIN mst_appl_options md ON md.Opt_Grp_Id = 2 AND md.Opt_Code = g.Meeting_Day_Cd
    LEFT JOIN mst_appl_options st ON st.Opt_Grp_Id = 27 AND st.Opt_Code = g.Current_Status_Cd
    LEFT JOIN (
        SELECT Group_Id, COUNT(*) AS Active_Members
        FROM mst_member_group
        WHERE Is_Active = 1
        GROUP BY Group_Id
    ) mc ON mc.Group_Id = g.Group_Id
    WHERE (p_group_id IS NULL OR g.Group_Id = p_group_id)
      AND (p_branch_id IS NULL OR g.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR g.Center_Id = p_center_id)
      AND (p_fo_id IS NULL OR g.FO_Id = p_fo_id)
      AND (p_group_type_cd IS NULL OR g.Group_Type_Cd = p_group_type_cd)
      AND (p_status_cd IS NULL OR g.Current_Status_Cd = p_status_cd)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR g.Group_Name LIKE CONCAT('%', p_keyword, '%')
          OR g.Group_Code LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(g.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(g.Registration_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(g.Village_Name, '') LIKE CONCAT('%', p_keyword, '%')
      )
    ORDER BY g.Group_Name ASC, g.Group_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_GROUP_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_GROUP_STATUS`(
    IN p_group_id INT,
    IN p_status_cd INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_center INT DEFAULT NULL;
    DECLARE v_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_err VARCHAR(255) DEFAULT NULL;

    SELECT COUNT(*), MAX(Current_Status_Cd), MAX(Branch_Id), MAX(Center_Id)
    INTO v_cnt, v_current, v_branch, v_center
    FROM mst_group WHERE Group_Id = p_group_id;

    SELECT MAX(Opt_Description) INTO v_desc
    FROM mst_appl_options WHERE Opt_Grp_Id = 27 AND Opt_Code = p_status_cd;

    IF p_group_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Group not found';
    ELSEIF p_status_cd IS NULL OR p_status_cd NOT IN (1, 2, 3, 4) THEN
        SET v_err = 'Status must be 1 (Active), 2 (Inactive), 3 (Suspended) or 4 (Closed)';
    END IF;

    IF v_err IS NULL AND IFNULL(v_current, 0) <> p_status_cd THEN
        IF p_status_cd = 1 THEN
            SELECT COUNT(*) INTO v_cnt FROM priomicro_core.mst_org_branch
            WHERE Branch_Id = v_branch AND IFNULL(Is_Active, 0) = 1;
            IF v_cnt = 0 THEN
                SET v_err = 'Branch is inactive; group cannot be activated';
            ELSEIF v_center IS NOT NULL THEN
                SELECT COUNT(*) INTO v_cnt FROM mst_center
                WHERE Center_Id = v_center AND IFNULL(Is_Active, 0) = 1;
                IF v_cnt = 0 THEN
                    SET v_err = 'Center is inactive; group cannot be activated';
                END IF;
            END IF;
        ELSEIF p_status_cd = 4 THEN
            SELECT COUNT(*) INTO v_cnt FROM mst_member_group
            WHERE Group_Id = p_group_id AND Is_Active = 1;
            IF v_cnt > 0 THEN
                SET v_err = CONCAT('Group has ', v_cnt, ' active member(s) and cannot be closed');
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_group_id AS group_id, v_current AS status_cd, v_err AS message;
    ELSEIF v_current = p_status_cd THEN
        SELECT 'SUCCESS' AS status, p_group_id AS group_id, v_current AS status_cd,
               CONCAT('Group is already ', LOWER(IFNULL(v_desc, 'in this status'))) AS message;
    ELSE
        UPDATE mst_group
        SET Current_Status_Cd = p_status_cd, Updated_By = p_user_id, Updated_At = NOW()
        WHERE Group_Id = p_group_id;

        SELECT 'SUCCESS' AS status, p_group_id AS group_id, p_status_cd AS status_cd,
               CONCAT('Group status changed to ', IFNULL(v_desc, p_status_cd)) AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_HOLIDAY_GET` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
