/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_HOLIDAY_GET`(
    IN p_id SMALLINT,
    IN p_year_sl SMALLINT,
    IN p_holi_type TINYINT,
    IN p_keyword VARCHAR(100),
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_holidays h
    WHERE (p_id IS NULL OR h.Id = p_id)
      AND (p_year_sl IS NULL OR h.Year_Sl = p_year_sl)
      AND (p_holi_type IS NULL OR h.Holi_Type = p_holi_type)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR h.Purpose LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_from_date IS NULL OR h.Holiday_Date >= p_from_date)
      AND (p_to_date IS NULL OR h.Holiday_Date <= p_to_date);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        h.Id,
        h.Year_Sl,
        fy.Year_Name,
        h.Holiday_Date,
        h.Purpose,
        h.Holi_Type
    FROM mst_holidays h
    LEFT JOIN mst_fin_year fy ON fy.Year_Id = h.Year_Sl
    WHERE (p_id IS NULL OR h.Id = p_id)
      AND (p_year_sl IS NULL OR h.Year_Sl = p_year_sl)
      AND (p_holi_type IS NULL OR h.Holi_Type = p_holi_type)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR h.Purpose LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_from_date IS NULL OR h.Holiday_Date >= p_from_date)
      AND (p_to_date IS NULL OR h.Holiday_Date <= p_to_date)
    ORDER BY h.Holiday_Date ASC, h.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_HOLIDAY_UPDATE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_HOLIDAY_UPDATE`(
    IN p_id SMALLINT,
    IN p_year_sl SMALLINT,
    IN p_holiday_date DATE,
    IN p_purpose VARCHAR(100),
    IN p_holi_type TINYINT
)
BEGIN
    DECLARE v_id SMALLINT DEFAULT NULL;
    DECLARE v_year_exists INT DEFAULT 0;
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;

    IF p_year_sl IS NULL OR p_year_sl < 1 THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Year_Sl (financial year) is required' AS message;
    ELSEIF p_holiday_date IS NULL THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Holiday date is required' AS message;
    ELSEIF p_purpose IS NULL OR TRIM(p_purpose) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Purpose is required' AS message;
    ELSE
        SELECT COUNT(*) INTO v_year_exists
        FROM mst_fin_year
        WHERE Year_Id = p_year_sl;

        IF v_year_exists = 0 THEN
            SELECT 'ERROR' AS status, NULL AS id, 'Financial year not found for Year_Sl' AS message;
        ELSE
            IF p_id IS NOT NULL AND p_id > 0 THEN
                SELECT COUNT(*) INTO v_exists
                FROM mst_holidays
                WHERE Id = p_id;

                IF v_exists = 0 THEN
                    SELECT 'ERROR' AS status, p_id AS id, 'Holiday not found' AS message;
                ELSE
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_holidays
                    WHERE Year_Sl = p_year_sl
                      AND Holiday_Date = p_holiday_date
                      AND Id <> p_id;

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, p_id AS id, 'Holiday already exists for this date in the year' AS message;
                    ELSE
                        UPDATE mst_holidays
                        SET
                            Year_Sl = p_year_sl,
                            Holiday_Date = p_holiday_date,
                            Purpose = TRIM(p_purpose),
                            Holi_Type = p_holi_type
                        WHERE Id = p_id;

                        SELECT 'SUCCESS' AS status, p_id AS id, 'Holiday updated successfully' AS message;
                    END IF;
                END IF;
            ELSE
                SELECT COUNT(*) INTO v_dup
                FROM mst_holidays
                WHERE Year_Sl = p_year_sl
                  AND Holiday_Date = p_holiday_date;

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, NULL AS id, 'Holiday already exists for this date in the year' AS message;
                ELSE
                    INSERT INTO mst_holidays (Year_Sl, Holiday_Date, Purpose, Holi_Type)
                    VALUES (p_year_sl, p_holiday_date, TRIM(p_purpose), p_holi_type);

                    SET v_id = LAST_INSERT_ID();
                    SELECT 'SUCCESS' AS status, v_id AS id, 'Holiday saved successfully' AS message;
                END IF;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_ACCOUNT_ADD_EDIT` */;
