/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ACCOUNT_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_loan_account_id BIGINT,
    IN p_loan_account_no INT,
    IN p_ref_account_no VARCHAR(30),
    IN p_application_id BIGINT,
    IN p_loan_date DATE,
    IN p_loan_amount DECIMAL(18,2),
    IN p_interest_rate DECIMAL(5,2),
    IN p_final_due_date DATE,
    IN p_is_defaulter TINYINT,
    IN p_is_npa TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_action VARCHAR(10);
    DECLARE v_loan_account_id BIGINT DEFAULT NULL;
    DECLARE v_account_no INT DEFAULT NULL;
    DECLARE v_ref_no VARCHAR(30) DEFAULT NULL;
    DECLARE v_amount DECIMAL(18,2) DEFAULT NULL;
    DECLARE v_rate DECIMAL(5,2) DEFAULT NULL;
    DECLARE v_defaulter TINYINT DEFAULT 0;
    DECLARE v_npa TINYINT DEFAULT 0;
    DECLARE v_disbursed INT DEFAULT 0;
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_gen_code VARCHAR(150);

    DECLARE v_cur_account_no INT DEFAULT NULL;
    DECLARE v_cur_ref_no VARCHAR(30) DEFAULT NULL;
    DECLARE v_cur_application BIGINT DEFAULT NULL;
    DECLARE v_cur_loan_date DATE DEFAULT NULL;
    DECLARE v_cur_amount DECIMAL(18,2) DEFAULT NULL;
    DECLARE v_cur_rate DECIMAL(5,2) DEFAULT NULL;
    DECLARE v_cur_disbursed DECIMAL(12,2) DEFAULT 0;
    DECLARE v_cur_status INT DEFAULT NULL;

    DECLARE v_app_date DATE DEFAULT NULL;
    DECLARE v_app_status INT DEFAULT NULL;
    DECLARE v_app_amount DECIMAL(18,2) DEFAULT NULL;
    DECLARE v_app_scheme INT DEFAULT NULL;
    DECLARE v_app_cust_type INT DEFAULT NULL;
    DECLARE v_app_cust INT DEFAULT NULL;
    DECLARE v_cust_status INT DEFAULT NULL;
    DECLARE v_scheme_rate DECIMAL(5,2) DEFAULT NULL;
    DECLARE v_sanction_id BIGINT DEFAULT NULL;
    DECLARE v_sanction_amount DECIMAL(18,2) DEFAULT NULL;
    DECLARE v_sanction_rate DECIMAL(5,2) DEFAULT NULL;
    DECLARE v_sanction_date DATE DEFAULT NULL;
    DECLARE v_max_amount DECIMAL(18,2) DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_ref_no = UPPER(NULLIF(TRIM(IFNULL(p_ref_account_no, '')), ''));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Loan_Account_No), MAX(Ref_Account_No), MAX(Application_Id), MAX(Loan_Date),
               MAX(Loan_Amount), MAX(Interest_Rate), MAX(Disbursed_Amount), MAX(Ln_Status_Cd)
        INTO v_cnt, v_cur_account_no, v_cur_ref_no, v_cur_application, v_cur_loan_date,
             v_cur_amount, v_cur_rate, v_cur_disbursed, v_cur_status
        FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id
        FOR UPDATE;

        IF p_loan_account_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan account not found';
        ELSEIF v_cur_status <> 1 THEN
            SET v_err = 'Closed or written-off loan account cannot be edited';
        ELSE
            SELECT COUNT(*) INTO v_disbursed
            FROM mst_loan_account_disbursement WHERE Loan_Account_Id = p_loan_account_id;
            IF IFNULL(v_cur_disbursed, 0) > 0 THEN
                SET v_disbursed = v_disbursed + 1;
            END IF;
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Application_Date), MAX(Appl_Status_Cd), MAX(Appl_Amount), MAX(Scheme_Id),
               MAX(Cust_Type_Cd), MAX(Cust_Id_Primay)
        INTO v_cnt, v_app_date, v_app_status, v_app_amount, v_app_scheme, v_app_cust_type, v_app_cust
        FROM mst_loan_application WHERE Application_Id = p_application_id;

        IF p_application_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan application not found';
        ELSEIF IFNULL(v_app_status, 0) <> 2 AND NOT (v_action = 'EDIT' AND p_application_id = v_cur_application) THEN
            SET v_err = 'Loan account can only be opened for an approved loan application';
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' AND v_disbursed > 0 AND p_application_id <> v_cur_application THEN
        SET v_err = 'Loan application cannot be changed once the loan is disbursed';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_loan_account
        WHERE Application_Id = p_application_id
          AND (v_action = 'ADD' OR Loan_Account_Id <> p_loan_account_id);
        IF v_cnt > 0 THEN
            SET v_err = 'A loan account already exists for this loan application';
        END IF;
    END IF;

    
    IF v_err IS NULL AND (v_action = 'ADD' OR p_application_id <> v_cur_application) THEN
        IF v_app_cust_type = 1 THEN
            SELECT MAX(Current_Status_Cd) INTO v_cust_status FROM mst_group WHERE Group_Id = v_app_cust;
            IF IFNULL(v_cust_status, 0) <> 1 THEN
                SET v_err = 'Group of the loan application is not active';
            END IF;
        ELSE
            SELECT MAX(Current_Status_Cd) INTO v_cust_status FROM mst_member WHERE Member_Id = v_app_cust;
            IF IFNULL(v_cust_status, 0) <> 1 THEN
                SET v_err = 'Member of the loan application is not active';
            END IF;
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SET v_sanction_id = (
            SELECT x.Loan_Approval_Id FROM mst_loan_application_approval x
            WHERE x.Loan_Application_Id = p_application_id AND x.Approval_Status_Cd = 1
            ORDER BY x.Approval_Date DESC, x.Loan_Approval_Id DESC
            LIMIT 1
        );

        IF v_sanction_id IS NOT NULL THEN
            SELECT MAX(Sanctioned_Amount), MAX(Interest_Rate), MAX(DATE(Approval_Date))
            INTO v_sanction_amount, v_sanction_rate, v_sanction_date
            FROM mst_loan_application_approval WHERE Loan_Approval_Id = v_sanction_id;
        END IF;

        SELECT MAX(RoI_Percent) INTO v_scheme_rate FROM mst_loan_scheme WHERE Scheme_Id = v_app_scheme;

        SET v_max_amount = IFNULL(v_sanction_amount, v_app_amount);
    END IF;

    
    IF v_err IS NULL THEN
        IF p_loan_date IS NULL THEN
            SET v_err = 'Loan date is required';
        ELSEIF p_loan_date > CURDATE() THEN
            SET v_err = 'Loan date cannot be in the future';
        ELSEIF v_app_date IS NOT NULL AND p_loan_date < v_app_date THEN
            SET v_err = 'Loan date cannot be before the application date';
        ELSEIF v_sanction_date IS NOT NULL AND p_loan_date < v_sanction_date THEN
            SET v_err = 'Loan date cannot be before the approval date';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SET v_amount = IFNULL(p_loan_amount, v_max_amount);
        SET v_rate = IFNULL(p_interest_rate, IFNULL(v_sanction_rate, v_scheme_rate));

        IF v_amount IS NULL OR v_amount <= 0 THEN
            SET v_err = 'Loan amount must be greater than zero';
        ELSEIF v_max_amount IS NOT NULL AND v_amount > v_max_amount THEN
            SET v_err = CONCAT(IF(v_sanction_amount IS NULL, 'Loan amount cannot exceed the applied amount (',
                                  'Loan amount cannot exceed the sanctioned amount ('),
                               FORMAT(v_max_amount, 2), ')');
        ELSEIF v_rate IS NULL THEN
            SET v_err = 'Interest rate is required (no sanction or scheme rate found)';
        ELSEIF v_rate < 0 OR v_rate > 100 THEN
            SET v_err = 'Interest rate must be between 0 and 100';
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' AND v_disbursed > 0
       AND (p_loan_date <> v_cur_loan_date OR v_amount <> v_cur_amount OR v_rate <> v_cur_rate
            OR IFNULL(p_loan_account_no, v_cur_account_no) <> v_cur_account_no) THEN
        SET v_err = 'Loan date, amount, interest rate and account number cannot be changed once the loan is disbursed';
    END IF;

    
    IF v_err IS NULL AND p_final_due_date IS NOT NULL AND p_final_due_date <= p_loan_date THEN
        SET v_err = 'Final due date must be after the loan date';
    END IF;

    
    IF v_err IS NULL THEN
        SET v_defaulter = IFNULL(p_is_defaulter, 0);
        SET v_npa = IFNULL(p_is_npa, 0);
        IF v_defaulter NOT IN (0, 1) OR v_npa NOT IN (0, 1) THEN
            SET v_err = 'Defaulter / NPA flag must be 1 (yes) or 0 (no)';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        IF p_loan_account_no IS NOT NULL THEN
            IF p_loan_account_no <= 0 THEN
                SET v_err = 'Loan account number must be greater than zero';
            ELSE
                SELECT COUNT(*) INTO v_cnt FROM mst_loan_account
                WHERE Loan_Account_No = p_loan_account_no
                  AND (v_action = 'ADD' OR Loan_Account_Id <> p_loan_account_id);
                IF v_cnt > 0 THEN
                    SET v_err = 'Loan account number already exists';
                ELSE
                    SET v_account_no = p_loan_account_no;
                END IF;
            END IF;
        ELSEIF v_action = 'EDIT' THEN
            SET v_account_no = v_cur_account_no;
        ELSE
            SELECT IFNULL(MAX(Loan_Account_No), 0) + 1 INTO v_account_no FROM mst_loan_account FOR UPDATE;
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_ref_no IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_loan_account
        WHERE UPPER(Ref_Account_No) = v_ref_no
          AND (v_action = 'ADD' OR Loan_Account_Id <> p_loan_account_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Reference account number already exists';
        END IF;
    END IF;

    IF v_err IS NULL AND v_ref_no IS NULL THEN
        IF v_action = 'EDIT' THEN
            SET v_ref_no = v_cur_ref_no;
        ELSE
            CALL USP_CODE_SERIES_GENERATE('loan_account', v_gen_code, v_gen_status, v_gen_msg);
            IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
                SET v_err = CONCAT('Reference account number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
            ELSE
                SET v_ref_no = LEFT(v_gen_code, 30);
                SELECT COUNT(*) INTO v_cnt FROM mst_loan_account WHERE UPPER(Ref_Account_No) = UPPER(v_ref_no);
                IF v_cnt > 0 THEN
                    SET v_err = CONCAT('Generated reference account number ', v_ref_no, ' already exists; check the loan_account code series');
                END IF;
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, NULL AS loan_account_no,
               NULL AS ref_account_no, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_account (
            Loan_Account_No, Ref_Account_No, Application_Id, Loan_Date, Loan_Amount, Interest_Rate,
            Disbursed_Amount, Principal_Outstanding, Final_Due_Date, Is_Defaulter, Is_NPA, Ln_Status_Cd,
            Created_By, Created_On
        ) VALUES (
            v_account_no, v_ref_no, p_application_id, p_loan_date, v_amount, v_rate,
            0, 0, p_final_due_date, v_defaulter, v_npa, 1,
            p_user_id, NOW()
        );

        SET v_loan_account_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_loan_account_id AS loan_account_id, v_account_no AS loan_account_no,
               v_ref_no AS ref_account_no, 'Loan account created successfully' AS message;
    ELSE
        UPDATE mst_loan_account
        SET Loan_Account_No = v_account_no,
            Ref_Account_No = v_ref_no,
            Application_Id = p_application_id,
            Loan_Date = p_loan_date,
            Loan_Amount = v_amount,
            Interest_Rate = v_rate,
            Final_Due_Date = p_final_due_date,
            Is_Defaulter = v_defaulter,
            Is_NPA = v_npa
        WHERE Loan_Account_Id = p_loan_account_id;

        SELECT 'SUCCESS' AS status, p_loan_account_id AS loan_account_id, v_account_no AS loan_account_no,
               v_ref_no AS ref_account_no, 'Loan account updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_ACCOUNT_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
