/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ACCOUNT_LIST`(
    IN p_loan_account_id BIGINT,
    IN p_application_id BIGINT,
    IN p_branch_id INT,
    IN p_fo_id INT,
    IN p_scheme_id INT,
    IN p_cust_type_cd INT,
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_status_cd INT,
    IN p_is_defaulter TINYINT,
    IN p_is_npa TINYINT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_loan_account la
    LEFT JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE (p_loan_account_id IS NULL OR la.Loan_Account_Id = p_loan_account_id)
      AND (p_application_id IS NULL OR la.Application_Id = p_application_id)
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
      AND (p_fo_id IS NULL OR ap.FO_Id = p_fo_id)
      AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
      AND (p_cust_type_cd IS NULL OR ap.Cust_Type_Cd = p_cust_type_cd)
      AND (p_member_id IS NULL OR (ap.Cust_Type_Cd = 2 AND p_member_id IN (ap.Cust_Id_Primay, IFNULL(ap.Cust_Id_Joint1, 0), IFNULL(ap.Cust_Id_Joint2, 0))))
      AND (p_group_id IS NULL OR (ap.Cust_Type_Cd = 1 AND ap.Cust_Id_Primay = p_group_id))
      AND (p_status_cd IS NULL OR la.Ln_Status_Cd = p_status_cd)
      AND (p_is_defaulter IS NULL OR la.Is_Defaulter = p_is_defaulter)
      AND (p_is_npa IS NULL OR la.Is_NPA = p_is_npa)
      AND (p_from_date IS NULL OR la.Loan_Date >= p_from_date)
      AND (p_to_date IS NULL OR la.Loan_Date <= p_to_date)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR CAST(la.Loan_Account_No AS CHAR) = p_keyword
          OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(ap.Application_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(ap.Beneficiary_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        la.Loan_Account_Id,
        la.Loan_Account_No,
        la.Ref_Account_No,
        la.Application_Id,
        ap.Application_No,
        ap.Application_Date,
        ap.Appl_Amount,
        ap.Appl_Tenure,
        ap.Repay_Duration_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 8 AND o.Opt_Code = ap.Repay_Duration_Cd) AS Repay_Duration_Desc,
        ap.Loan_Cycle,
        ap.Cust_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 34 AND o.Opt_Code = ap.Cust_Type_Cd) AS Cust_Type_Desc,
        ap.Cust_Id_Primay AS Cust_Id_Primary,
        IF(ap.Cust_Type_Cd = 1, pg.Ref_Code, pm.Ref_Code) AS Primary_Ref_Code,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Primary_Name,
        IF(ap.Cust_Type_Cd = 1, NULL, pm.Mobile_No) AS Primary_Mobile,
        ap.Cust_Id_Joint1,
        j1.Member_Name AS Joint1_Name,
        ap.Cust_Id_Joint2,
        j2.Member_Name AS Joint2_Name,
        ap.Beneficiary_Name,
        ap.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        s.RoI_Percent AS Scheme_RoI_Percent,
        apr.Loan_Approval_Id,
        apr.Sanctioned_Amount,
        apr.Interest_Rate AS Sanctioned_Interest_Rate,
        apr.Loan_Duration AS Sanctioned_Duration,
        apr.First_Due_Date,
        apr.Approval_Date,
        la.Loan_Date,
        la.Loan_Amount,
        la.Interest_Rate,
        la.Disbursed_Amount,
        la.Principal_Outstanding,
        (la.Loan_Amount - la.Disbursed_Amount) AS Undisbursed_Amount,
        (SELECT COUNT(*) FROM mst_loan_account_disbursement d WHERE d.Loan_Account_Id = la.Loan_Account_Id) AS Disbursement_Count,
        la.Final_Due_Date,
        la.Is_Defaulter,
        la.Is_NPA,
        ap.FO_Id,
        fo.Employee_Code AS FO_Code,
        fo.Full_Name AS FO_Name,
        ap.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        la.Ln_Status_Cd AS Status_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 40 AND o.Opt_Code = la.Ln_Status_Cd) AS Status_Desc,
        la.Created_By,
        u.User_Name AS Created_By_Name,
        la.Created_On
    FROM mst_loan_account la
    LEFT JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_member j1 ON j1.Member_Id = ap.Cust_Id_Joint1
    LEFT JOIN mst_member j2 ON j2.Member_Id = ap.Cust_Id_Joint2
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    LEFT JOIN mst_loan_application_approval apr
           ON apr.Loan_Approval_Id = (SELECT x.Loan_Approval_Id FROM mst_loan_application_approval x
                                      WHERE x.Loan_Application_Id = la.Application_Id AND x.Approval_Status_Cd = 1
                                      ORDER BY x.Approval_Date DESC, x.Loan_Approval_Id DESC LIMIT 1)
    LEFT JOIN mst_staff fo ON fo.Staff_Id = ap.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = la.Created_By
    WHERE (p_loan_account_id IS NULL OR la.Loan_Account_Id = p_loan_account_id)
      AND (p_application_id IS NULL OR la.Application_Id = p_application_id)
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
      AND (p_fo_id IS NULL OR ap.FO_Id = p_fo_id)
      AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
      AND (p_cust_type_cd IS NULL OR ap.Cust_Type_Cd = p_cust_type_cd)
      AND (p_member_id IS NULL OR (ap.Cust_Type_Cd = 2 AND p_member_id IN (ap.Cust_Id_Primay, IFNULL(ap.Cust_Id_Joint1, 0), IFNULL(ap.Cust_Id_Joint2, 0))))
      AND (p_group_id IS NULL OR (ap.Cust_Type_Cd = 1 AND ap.Cust_Id_Primay = p_group_id))
      AND (p_status_cd IS NULL OR la.Ln_Status_Cd = p_status_cd)
      AND (p_is_defaulter IS NULL OR la.Is_Defaulter = p_is_defaulter)
      AND (p_is_npa IS NULL OR la.Is_NPA = p_is_npa)
      AND (p_from_date IS NULL OR la.Loan_Date >= p_from_date)
      AND (p_to_date IS NULL OR la.Loan_Date <= p_to_date)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR CAST(la.Loan_Account_No AS CHAR) = p_keyword
          OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(ap.Application_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(ap.Beneficiary_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
    ORDER BY la.Loan_Date DESC, la.Loan_Account_Id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
