/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ACCOUNT_STATUS`(
    IN p_loan_account_id BIGINT,
    IN p_status_cd INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current INT DEFAULT NULL;
    DECLARE v_outstanding DECIMAL(12,2) DEFAULT 0;
    DECLARE v_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_cur_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_err VARCHAR(255) DEFAULT NULL;

    SELECT COUNT(*), MAX(Ln_Status_Cd), MAX(Principal_Outstanding)
    INTO v_cnt, v_current, v_outstanding
    FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id
    FOR UPDATE;

    SELECT MIN(Opt_Description) INTO v_desc
    FROM mst_appl_options WHERE Opt_Grp_Id = 40 AND Opt_Code = p_status_cd AND Is_Active = 1;

    SELECT MIN(Opt_Description) INTO v_cur_desc
    FROM mst_appl_options WHERE Opt_Grp_Id = 40 AND Opt_Code = v_current;

    IF p_loan_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Loan account not found';
    ELSEIF p_status_cd IS NULL OR v_desc IS NULL THEN
        SET v_err = 'Invalid loan account status';
    ELSEIF v_current = p_status_cd THEN
        SET v_err = NULL;
    ELSEIF v_current <> 1 THEN
        SET v_err = CONCAT(IFNULL(v_cur_desc, 'This'), ' loan account status cannot be changed');
    ELSEIF p_status_cd = 2 AND IFNULL(v_outstanding, 0) <> 0 THEN
        SET v_err = CONCAT('Principal outstanding must be zero before closing (outstanding ', FORMAT(v_outstanding, 2), ')');
    ELSEIF p_status_cd = 3 AND IFNULL(v_outstanding, 0) <= 0 THEN
        SET v_err = 'Nothing to write off: principal outstanding is zero';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, v_current AS status_cd, v_err AS message;
    ELSEIF v_current = p_status_cd THEN
        SELECT 'SUCCESS' AS status, p_loan_account_id AS loan_account_id, v_current AS status_cd,
               CONCAT('Loan account is already ', LOWER(v_desc)) AS message;
    ELSE
        UPDATE mst_loan_account SET Ln_Status_Cd = p_status_cd WHERE Loan_Account_Id = p_loan_account_id;

        SELECT 'SUCCESS' AS status, p_loan_account_id AS loan_account_id, p_status_cd AS status_cd,
               CONCAT('Loan account status changed to ', v_desc) AS message;
    END IF;
END ;;
DELIMITER ;
