DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ADJUSTMENT_ADD`(
    IN p_loan_account_id BIGINT,
    IN p_type_cd INT,
    IN p_component VARCHAR(20),
    IN p_amount DECIMAL(14,2),
    IN p_effective_date DATE,
    IN p_reason VARCHAR(250),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_outs DECIMAL(14,2) DEFAULT 0;
    DECLARE v_branch INT;
    DECLARE v_first DATE;
    DECLARE v_comp VARCHAR(20);
    DECLARE v_limit DECIMAL(14,2) DEFAULT 0;
    DECLARE v_paid_p DECIMAL(14,2) DEFAULT 0;
    DECLARE v_paid_i DECIMAL(14,2) DEFAULT 0;
    DECLARE v_no VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_id BIGINT;
    DECLARE v_vid BIGINT;
    DECLARE v_vno VARCHAR(25);
    DECLARE v_note VARCHAR(255);
    DECLARE v_ref VARCHAR(30);
    DECLARE v_loan_gl INT;
    DECLARE v_int_gl INT;
    DECLARE v_pen_gl INT;
    DECLARE v_exp_gl INT;
    DECLARE v_new_outs DECIMAL(14,2);
    DECLARE v_last_sched BIGINT;
    DECLARE v_reason VARCHAR(250);

    SET v_comp = LOWER(TRIM(IFNULL(p_component, '')));
    SET p_effective_date = IFNULL(p_effective_date, CURDATE());
    SET v_reason = NULLIF(TRIM(IFNULL(p_reason, '')), '');
    IF p_type_cd = 2 THEN
        SET v_comp = 'interest';
    END IF;

    SELECT COUNT(*), MAX(la.Ln_Status_Cd), IFNULL(MAX(la.Principal_Outstanding), 0), MAX(ap.Branch_Id), MAX(la.Ref_Account_No),
           MAX(NULLIF(s.Loan_Ledger, 0)), MAX(NULLIF(s.Intt_Ledger, 0)), MAX(NULLIF(s.OdIntt_Ledger, 0))
    INTO v_cnt, v_status, v_outs, v_branch, v_ref, v_loan_gl, v_int_gl, v_pen_gl
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    WHERE la.Loan_Account_Id = p_loan_account_id FOR UPDATE;

    IF v_pen_gl IS NULL THEN
        SELECT NULLIF(MAX(Value), 0) INTO v_pen_gl FROM mst_settings_global WHERE Id = 104;
    END IF;
    SELECT NULLIF(MAX(Value), 0) INTO v_exp_gl FROM mst_settings_global WHERE Id = 105;

    SELECT MIN(Disbursement_Date) INTO v_first FROM mst_loan_account_disbursement
    WHERE Loan_Account_Id = p_loan_account_id AND Approved_By IS NOT NULL;

    SET v_paid_p = FN_LOAN_PAID(p_loan_account_id, NULL, 'P');
    SET v_paid_i = FN_LOAN_PAID(p_loan_account_id, NULL, 'I');

    IF p_loan_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Loan account not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Loan account is not active';
    ELSEIF v_first IS NULL THEN
        SET v_err = 'Loan is not disbursed yet';
    ELSEIF p_type_cd = 3 THEN
        SET v_err = 'Correction adjustments are not supported (no adjustment table); reverse the collection and enter it again';
    ELSEIF p_type_cd IS NULL OR p_type_cd NOT IN (1, 2) THEN
        SET v_err = 'Adjustment type must be 1 (Waiver) or 2 (Capitalization)';
    ELSEIF v_comp NOT IN ('principal', 'interest', 'penalty') THEN
        SET v_err = 'Component must be principal, interest or penalty';
    ELSEIF EXISTS (SELECT 1 FROM trans_loan_collection WHERE Account_Id = p_loan_account_id AND Tr_Status_Cd = 1) THEN
        SET v_err = 'A collection on this loan is waiting for approval';
    ELSEIF p_effective_date > CURDATE() THEN
        SET v_err = 'Effective date cannot be in the future';
    ELSEIF p_effective_date < v_first THEN
        SET v_err = 'Effective date cannot be before the first disbursement';
    ELSEIF p_amount IS NULL OR p_amount <= 0 THEN
        SET v_err = 'Amount must be greater than zero';
    ELSEIF v_reason IS NULL THEN
        SET v_err = 'Reason is required';
    END IF;

    IF v_err IS NULL THEN
        SET v_limit = CASE
            WHEN p_type_cd = 2 THEN GREATEST(0, FN_LOAN_DEMAND(p_loan_account_id, DATE_SUB(p_effective_date, INTERVAL 1 DAY), 'I') - v_paid_i)
            WHEN v_comp = 'penalty' THEN FN_LOAN_PENALTY_DUE(p_loan_account_id, p_effective_date)
            WHEN v_comp = 'interest' THEN GREATEST(0, FN_LOAN_DEMAND(p_loan_account_id, NULL, 'I') - v_paid_i)
            ELSE LEAST(v_outs, GREATEST(0, FN_LOAN_DEMAND(p_loan_account_id, NULL, 'P') - v_paid_p))
        END;

        IF p_amount > v_limit + 0.005 THEN
            SET v_err = CONCAT('Amount cannot exceed ', FORMAT(v_limit, 2), CASE
                WHEN p_type_cd = 2 THEN ' (overdue interest)'
                WHEN v_comp = 'penalty' THEN ' (penalty due)'
                WHEN v_comp = 'interest' THEN ' (unpaid interest)'
                ELSE ' (unpaid principal)' END);
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_CODE_SERIES_GENERATE('loan_adjustment', v_no, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_no IS NULL THEN
            SET v_err = CONCAT('Adjustment number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS adjustment_id, NULL AS adjustment_no, NULL AS amount, NULL AS outs_principal,
               NULL AS voucher_id, NULL AS voucher_no, NULL AS voucher_note, v_err AS message;
    ELSE
        IF v_comp IN ('interest', 'principal') THEN
            DROP TEMPORARY TABLE IF EXISTS tmp_loan_waive;
            CREATE TEMPORARY TABLE tmp_loan_waive (
                Schedule_Id BIGINT PRIMARY KEY, Unpaid DECIMAL(14,2), Cum_Before DECIMAL(14,2), Take DECIMAL(14,2) DEFAULT 0
            );

            INSERT INTO tmp_loan_waive (Schedule_Id, Unpaid, Cum_Before)
            SELECT z.Schedule_Id, z.unpaid, IFNULL(SUM(z.unpaid) OVER (ORDER BY z.Installment_No, z.Schedule_Id
                                                     ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0)
            FROM (
                SELECT w.Schedule_Id, w.Installment_No,
                       w.amt - LEAST(w.amt, GREATEST(0, IF(v_comp = 'principal', v_paid_p, v_paid_i) - (w.cum - w.amt))) AS unpaid,
                       w.Due_Date
                FROM (
                    SELECT s.Schedule_Id, s.Installment_No, s.Due_Date,
                           IF(v_comp = 'principal', s.Principal_Due - IFNULL(s.Principal_Waived, 0),
                              s.Interest_Due - IFNULL(s.Interest_Waived, 0)) AS amt,
                           SUM(IF(v_comp = 'principal', s.Principal_Due - IFNULL(s.Principal_Waived, 0),
                                  s.Interest_Due - IFNULL(s.Interest_Waived, 0))) OVER (ORDER BY s.Installment_No, s.Schedule_Id) AS cum
                    FROM trans_loanac_schedule s
                    WHERE s.Loan_Account_Id = p_loan_account_id AND IFNULL(s.Is_Active, 1) = 1
                ) w
                WHERE p_type_cd = 1 OR w.Due_Date < p_effective_date
            ) z
            WHERE z.unpaid > 0;

            UPDATE tmp_loan_waive SET Take = GREATEST(0, LEAST(Unpaid, p_amount - Cum_Before));

            IF v_comp = 'principal' THEN
                UPDATE trans_loanac_schedule s JOIN tmp_loan_waive t ON t.Schedule_Id = s.Schedule_Id
                SET s.Principal_Waived = IFNULL(s.Principal_Waived, 0) + t.Take
                WHERE t.Take > 0;
                UPDATE mst_loan_account SET Principal_Outstanding = Principal_Outstanding - p_amount WHERE Loan_Account_Id = p_loan_account_id;
                SET v_new_outs = v_outs - p_amount;
            ELSE
                UPDATE trans_loanac_schedule s JOIN tmp_loan_waive t ON t.Schedule_Id = s.Schedule_Id
                SET s.Interest_Waived = IFNULL(s.Interest_Waived, 0) + t.Take
                WHERE t.Take > 0;
                SET v_new_outs = v_outs;
            END IF;
        ELSE
            SET v_new_outs = v_outs;
        END IF;

        IF p_type_cd = 2 THEN
            SELECT Schedule_Id INTO v_last_sched FROM trans_loanac_schedule
            WHERE Loan_Account_Id = p_loan_account_id AND IFNULL(Is_Active, 1) = 1
            ORDER BY Installment_No DESC, Schedule_Id DESC LIMIT 1;

            UPDATE trans_loanac_schedule
            SET Principal_Due = Principal_Due + p_amount, Total_Due = Total_Due + p_amount
            WHERE Schedule_Id = v_last_sched;

            UPDATE mst_loan_account SET Principal_Outstanding = Principal_Outstanding + p_amount WHERE Loan_Account_Id = p_loan_account_id;
            SET v_new_outs = v_outs + p_amount;
        END IF;

        INSERT INTO trans_loan_collection (
            Account_Id, Trans_No, Collection_Date, Effect_Date, Payment_Mode_Cd, Principal_Collected, Interest_Collected,
            Penalty_Collected, Total_Collected, Interest_Demand, Interest_Due, Interest_Capitalized, Outs_Principal,
            Trans_Ref_No, Ledger_Narration, FO_Id, Branch_Id, Voucher_Id, Tr_Status_Cd, Remarks, Created_By, Created_At
        ) VALUES (
            p_loan_account_id, LEFT(v_no, 40), NOW(), p_effective_date, 5, 0, 0,
            IF(p_type_cd = 1 AND v_comp = 'penalty', p_amount, 0),
            IF(p_type_cd = 1, p_amount, 0), 0, 0, IF(p_type_cd = 2, p_amount, 0), v_new_outs, NULL,
            IF(p_type_cd = 2, 'Capitalization', CONCAT('Waiver - ', CONCAT(UPPER(LEFT(v_comp, 1)), SUBSTRING(v_comp, 2)))),
            NULL, v_branch, NULL, 2, LEFT(v_reason, 250), p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();

        CALL USP_LOAN_SCHEDULE_SYNC(p_loan_account_id, v_id, p_effective_date);

        CALL USP_LOAN_VOUCHER_RESET();
        IF p_type_cd = 2 THEN
            INSERT INTO tmp_loan_voucher_lines (Line_Role, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration)
            VALUES ('LOAN', v_loan_gl, p_amount, 0, CONCAT('Interest capitalized ', IFNULL(v_ref, ''))),
                   ('INTEREST', v_int_gl, 0, p_amount, CONCAT('Interest capitalized ', IFNULL(v_ref, '')));
        ELSE
            INSERT INTO tmp_loan_voucher_lines (Line_Role, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration)
            VALUES ('WAIVER EXPENSE', v_exp_gl, p_amount, 0, CONCAT('Waiver ', v_comp, ' ', IFNULL(v_ref, ''))),
                   (UPPER(v_comp), CASE v_comp WHEN 'principal' THEN v_loan_gl WHEN 'interest' THEN v_int_gl ELSE v_pen_gl END,
                    0, p_amount, CONCAT('Waiver ', v_comp, ' ', IFNULL(v_ref, '')));
        END IF;

        CALL USP_LOAN_VOUCHER_POST(v_branch, p_effective_date, 3, 5, CONCAT('Loan adjustment ', LEFT(v_no, 40), ' / ', IFNULL(v_ref, '')),
                                   p_user_id, v_vid, v_vno, v_note);
        UPDATE trans_loan_collection SET Voucher_Id = v_vid WHERE Collection_Id = v_id;

        SELECT 'SUCCESS' AS status, v_id AS adjustment_id, LEFT(v_no, 40) AS adjustment_no, p_amount AS amount,
               v_new_outs AS outs_principal, v_vid AS voucher_id, v_vno AS voucher_no, v_note AS voucher_note,
               IF(p_type_cd = 2, 'Overdue interest capitalized', CONCAT(UPPER(LEFT(v_comp, 1)), SUBSTRING(v_comp, 2), ' waived')) AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_ADJUSTMENT_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ADJUSTMENT_LIST`(
    IN p_adjustment_id BIGINT,
    IN p_loan_account_id BIGINT,
    IN p_type_cd INT,
    IN p_branch_id INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_adj_ids;
    CREATE TEMPORARY TABLE tmp_loan_adj_ids (Collection_Id BIGINT PRIMARY KEY);

    INSERT INTO tmp_loan_adj_ids (Collection_Id)
    SELECT c.Collection_Id
    FROM trans_loan_collection c
    JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE c.Payment_Mode_Cd = 5
      AND (p_adjustment_id IS NULL OR c.Collection_Id = p_adjustment_id)
      AND (p_loan_account_id IS NULL OR c.Account_Id = p_loan_account_id)
      AND (p_type_cd IS NULL
           OR (p_type_cd = 1 AND c.Ledger_Narration LIKE 'Waiver%')
           OR (p_type_cd = 2 AND c.Ledger_Narration LIKE 'Capitalization%'))
      AND (p_branch_id IS NULL OR c.Branch_Id = p_branch_id)
      AND (p_from_date IS NULL OR c.Effect_Date >= p_from_date)
      AND (p_to_date IS NULL OR c.Effect_Date <= p_to_date)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(c.Trans_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));

    SELECT COUNT(*) INTO v_total FROM tmp_loan_adj_ids;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        c.Collection_Id AS Adjustment_Id,
        c.Trans_No AS Adjustment_No,
        c.Account_Id AS Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        IF(c.Ledger_Narration LIKE 'Capitalization%', 2, 1) AS Adjustment_Type_Cd,
        IF(c.Ledger_Narration LIKE 'Capitalization%', 'Capitalization', 'Waiver') AS Adjustment_Type_Desc,
        CASE
            WHEN c.Ledger_Narration LIKE 'Capitalization%' THEN 'interest'
            WHEN c.Ledger_Narration LIKE '%Principal%' THEN 'principal'
            WHEN c.Ledger_Narration LIKE '%Penalty%' THEN 'penalty'
            ELSE 'interest'
        END AS Component,
        IF(c.Ledger_Narration LIKE 'Capitalization%', c.Interest_Capitalized, c.Total_Collected) AS Amount,
        c.Effect_Date AS Effective_Date,
        c.Remarks AS Reason,
        c.Outs_Principal,
        c.Voucher_Id,
        v.Vou_No_Ref AS Voucher_No,
        c.Tr_Status_Cd,
        FN_LOAN_OPT_DESC(48, c.Tr_Status_Cd) AS Tr_Status_Desc,
        c.Branch_Id,
        b.Branch_Name,
        c.Created_By,
        u.User_Name AS Created_By_Name,
        c.Created_At
    FROM tmp_loan_adj_ids t
    JOIN trans_loan_collection c ON c.Collection_Id = t.Collection_Id
    JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN trans_vouchers v ON v.Voucher_Id = c.Voucher_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = c.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = c.Created_By
    ORDER BY c.Effect_Date DESC, c.Collection_Id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_ADVANCE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ADVANCE_LIST`(
    IN p_loan_account_id BIGINT,
    IN p_fo_id INT,
    IN p_branch_id INT,
    IN p_tr_status_cd INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_as_on DATE,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;
    SET p_as_on = IFNULL(p_as_on, CURDATE());

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_adv_ids;
    CREATE TEMPORARY TABLE tmp_loan_adv_ids (Collection_Id BIGINT PRIMARY KEY);

    INSERT INTO tmp_loan_adv_ids (Collection_Id)
    SELECT c.Collection_Id
    FROM trans_loan_collection c
    JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE c.Ledger_Narration LIKE 'Advance collection%' AND IFNULL(c.Payment_Mode_Cd, 0) <> 5
      AND (p_loan_account_id IS NULL OR c.Account_Id = p_loan_account_id)
      AND (p_fo_id IS NULL OR c.FO_Id = p_fo_id)
      AND (p_branch_id IS NULL OR c.Branch_Id = p_branch_id)
      AND (p_tr_status_cd IS NULL OR c.Tr_Status_Cd = p_tr_status_cd)
      AND (p_from_date IS NULL OR IFNULL(c.Effect_Date, DATE(c.Collection_Date)) >= p_from_date)
      AND (p_to_date IS NULL OR IFNULL(c.Effect_Date, DATE(c.Collection_Date)) <= p_to_date)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(c.Trans_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));

    SELECT COUNT(*) INTO v_total FROM tmp_loan_adv_ids;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT x.*, GREATEST(0, x.Advance_Amount - x.Adjusted_Amount) AS Balance_Advance
    FROM (
        SELECT
            c.Collection_Id,
            c.Trans_No,
            c.Account_Id AS Loan_Account_Id,
            la.Ref_Account_No AS Loan_Account_No,
            IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
            c.Collection_Date,
            c.Effect_Date,
            c.Total_Collected,
            IF(c.Tr_Status_Cd = 2, FN_LOAN_ADVANCE_PART(c.Collection_Id, NULL), 0) AS Advance_Amount,
            IF(c.Tr_Status_Cd = 2, FN_LOAN_ADVANCE_PART(c.Collection_Id, p_as_on), 0) AS Adjusted_Amount,
            c.Payment_Mode_Cd,
            FN_LOAN_OPT_DESC(41, c.Payment_Mode_Cd) AS Payment_Mode_Desc,
            c.Trans_Ref_No,
            c.FO_Id,
            fo.Full_Name AS FO_Name,
            c.Branch_Id,
            b.Branch_Name,
            c.Tr_Status_Cd,
            FN_LOAN_OPT_DESC(48, c.Tr_Status_Cd) AS Tr_Status_Desc
        FROM tmp_loan_adv_ids t
        JOIN trans_loan_collection c ON c.Collection_Id = t.Collection_Id
        JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
        LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
        LEFT JOIN mst_staff fo ON fo.Staff_Id = c.FO_Id
        LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = c.Branch_Id
        ORDER BY c.Collection_Date DESC, c.Collection_Id DESC
        LIMIT v_per_page OFFSET v_offset
    ) x;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPLICATION_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPLICATION_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_application_id BIGINT,
    IN p_application_date DATE,
    IN p_cust_type_cd INT,
    IN p_cust_id_primary INT,
    IN p_cust_id_joint1 INT,
    IN p_cust_id_joint2 INT,
    IN p_scheme_id INT,
    IN p_purpose_id INT,
    IN p_appl_amount DECIMAL(18,2),
    IN p_appl_tenure INT,
    IN p_repay_duration_cd INT,
    IN p_beneficiary_name VARCHAR(150),
    IN p_bank_account_no VARCHAR(40),
    IN p_ifsc_code VARCHAR(20),
    IN p_fo_id INT,
    IN p_branch_id INT,
    IN p_remarks VARCHAR(500),
    IN p_is_bulk TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(500) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cur_status INT DEFAULT NULL;
    DECLARE v_cur_type INT DEFAULT NULL;
    DECLARE v_cur_bulk INT DEFAULT 0;
    DECLARE v_cust_status INT DEFAULT NULL;
    DECLARE v_cust_branch INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_scheme_active INT DEFAULT NULL;
    DECLARE v_slab_cnt INT DEFAULT 0;
    DECLARE v_slab_id INT DEFAULT NULL;
    DECLARE v_slab_dur INT DEFAULT NULL;
    DECLARE v_slab_min DECIMAL(18,2) DEFAULT NULL;
    DECLARE v_slab_max DECIMAL(18,2) DEFAULT NULL;
    DECLARE v_pending VARCHAR(40) DEFAULT NULL;
    DECLARE v_fail VARCHAR(500) DEFAULT NULL;
    DECLARE v_cycle INT DEFAULT 1;
    DECLARE v_app_no VARCHAR(150) DEFAULT NULL;
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_id BIGINT DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET p_is_bulk = IFNULL(p_is_bulk, 0);
    SET p_ifsc_code = UPPER(NULLIF(TRIM(IFNULL(p_ifsc_code, '')), ''));
    SET p_bank_account_no = NULLIF(TRIM(IFNULL(p_bank_account_no, '')), '');
    SET p_beneficiary_name = NULLIF(TRIM(IFNULL(p_beneficiary_name, '')), '');
    SET p_remarks = NULLIF(TRIM(IFNULL(p_remarks, '')), '');

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Appl_Status_Cd), MAX(Cust_Type_Cd)
        INTO v_cnt, v_cur_status, v_cur_type
        FROM mst_loan_application WHERE Application_Id = p_application_id FOR UPDATE;

        SELECT COUNT(*) INTO v_cur_bulk FROM mst_loan_application_bulk WHERE Loan_Application_Id = p_application_id;

        IF p_application_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan application not found';
        ELSEIF v_cur_status NOT IN (1, 4) THEN
            SET v_err = CONCAT('Only Submitted or Resubmission applications can be edited (current status: ',
                               IFNULL(FN_LOAN_OPT_DESC(37, v_cur_status), v_cur_status), ')');
        ELSEIF EXISTS (SELECT 1 FROM mst_loan_account WHERE Application_Id = p_application_id) THEN
            SET v_err = 'Application cannot be edited after the loan account is opened';
        ELSEIF p_cust_type_cd <> v_cur_type THEN
            SET v_err = 'Customer type cannot be changed';
        ELSEIF v_cur_bulk > 0 AND p_is_bulk = 0 THEN
            SET v_err = 'This is a group (JLG) application with members; send the members list';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        IF p_application_date IS NULL THEN
            SET v_err = 'Application date is required';
        ELSEIF p_application_date > CURDATE() THEN
            SET v_err = 'Application date cannot be in the future';
        ELSEIF p_cust_type_cd IS NULL OR p_cust_type_cd NOT IN (1, 2) THEN
            SET v_err = 'Customer type must be 1 (Group) or 2 (Individual)';
        ELSEIF p_is_bulk = 1 AND p_cust_type_cd <> 1 THEN
            SET v_err = 'A members list is only allowed for group (JLG) applications';
        ELSEIF p_appl_amount IS NULL OR p_appl_amount <= 0 THEN
            SET v_err = 'Applied amount must be greater than zero';
        ELSEIF p_appl_tenure IS NULL OR p_appl_tenure < 1 THEN
            SET v_err = 'Tenure must be at least 1 installment';
        ELSEIF FN_LOAN_OPT_DESC(8, p_repay_duration_cd) IS NULL THEN
            SET v_err = 'Invalid repayment duration';
        END IF;
    END IF;

    IF v_err IS NULL AND p_cust_type_cd = 2 THEN
        SELECT COUNT(*), MAX(Current_Status_Cd), MAX(Branch_Id)
        INTO v_cnt, v_cust_status, v_cust_branch
        FROM mst_member WHERE Member_Id = p_cust_id_primary;

        IF p_cust_id_primary IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Borrower (member) not found';
        ELSEIF IFNULL(v_cust_status, 0) <> 1 THEN
            SET v_err = 'Borrower is not active';
        ELSEIF FN_LOAN_MEMBER_KYC_OK(p_cust_id_primary) = 0 THEN
            SET v_err = 'Borrower KYC is not verified';
        ELSEIF p_cust_id_joint1 IS NOT NULL AND p_cust_id_joint1 = p_cust_id_primary THEN
            SET v_err = 'Joint applicant 1 cannot be the primary borrower';
        ELSEIF p_cust_id_joint2 IS NOT NULL AND p_cust_id_joint2 IN (p_cust_id_primary, IFNULL(p_cust_id_joint1, 0)) THEN
            SET v_err = 'Joint applicant 2 must be different from the borrower and joint applicant 1';
        ELSEIF p_cust_id_joint1 IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM mst_member WHERE Member_Id = p_cust_id_joint1 AND IFNULL(Current_Status_Cd, 0) = 1) THEN
            SET v_err = 'Joint applicant 1 not found or not active';
        ELSEIF p_cust_id_joint2 IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM mst_member WHERE Member_Id = p_cust_id_joint2 AND IFNULL(Current_Status_Cd, 0) = 1) THEN
            SET v_err = 'Joint applicant 2 not found or not active';
        END IF;
    ELSEIF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Current_Status_Cd), MAX(Branch_Id)
        INTO v_cnt, v_cust_status, v_cust_branch
        FROM mst_group WHERE Group_Id = p_cust_id_primary;

        IF p_cust_id_primary IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Group not found';
        ELSEIF IFNULL(v_cust_status, 0) <> 1 THEN
            SET v_err = 'Group is not active';
        ELSEIF p_cust_id_joint1 IS NOT NULL OR p_cust_id_joint2 IS NOT NULL THEN
            SET v_err = 'Joint applicants are not allowed on a group application';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_branch = IFNULL(p_branch_id, v_cust_branch);
        IF p_branch_id IS NOT NULL AND p_branch_id <> v_cust_branch THEN
            SET v_err = 'Branch must be the borrower''s branch';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT MAX(Is_Active) INTO v_scheme_active FROM mst_loan_scheme WHERE Scheme_Id = p_scheme_id;
        IF v_scheme_active IS NULL THEN
            SET v_err = 'Loan scheme not found';
        ELSEIF v_scheme_active <> 1 THEN
            SET v_err = 'Loan scheme is not active';
        END IF;
    END IF;

    IF v_err IS NULL AND p_is_bulk = 0 THEN
        SELECT COUNT(*), MIN(Min_Amount), MAX(Max_Amount) INTO v_slab_cnt, v_slab_min, v_slab_max
        FROM mst_loan_scheme_slab
        WHERE Scheme_Id = p_scheme_id AND Is_Active = 1 AND (Effect_From IS NULL OR Effect_From <= p_application_date);

        IF v_slab_cnt > 0 THEN
            SET v_slab_id = (SELECT sl.Id FROM mst_loan_scheme_slab sl
                             WHERE sl.Scheme_Id = p_scheme_id AND sl.Is_Active = 1
                               AND (sl.Effect_From IS NULL OR sl.Effect_From <= p_application_date)
                               AND p_appl_amount BETWEEN IFNULL(sl.Min_Amount, 0) AND IFNULL(sl.Max_Amount, 9999999999)
                             ORDER BY sl.Effect_From DESC, sl.Id DESC LIMIT 1);
            IF v_slab_id IS NULL THEN
                SET v_err = CONCAT('Applied amount must be within the scheme slab range (',
                                   FORMAT(IFNULL(v_slab_min, 0), 2), ' - ', FORMAT(IFNULL(v_slab_max, 0), 2), ')');
            ELSE
                SELECT MAX(Max_Duration) INTO v_slab_dur FROM mst_loan_scheme_slab WHERE Id = v_slab_id;
                IF v_slab_dur IS NOT NULL AND p_appl_tenure > v_slab_dur THEN
                    SET v_err = CONCAT('Tenure cannot exceed the scheme slab maximum of ', v_slab_dur);
                END IF;
            END IF;
        END IF;
    END IF;

    IF v_err IS NULL AND p_fo_id IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM mst_staff WHERE Staff_Id = p_fo_id AND Branch_Id = v_branch AND IFNULL(Status, 0) = 1) THEN
            SET v_err = 'Active field officer not found for the branch';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_pending = (
            SELECT ap.Application_No FROM mst_loan_application ap
            WHERE ap.Cust_Type_Cd = p_cust_type_cd AND ap.Cust_Id_Primay = p_cust_id_primary
              AND ap.Appl_Status_Cd IN (1, 4)
              AND ap.Application_Id <> IFNULL(p_application_id, 0)
              AND NOT EXISTS (SELECT 1 FROM mst_loan_account la WHERE la.Application_Id = ap.Application_Id)
            ORDER BY ap.Application_Id DESC LIMIT 1);
        IF v_pending IS NOT NULL THEN
            SET v_err = CONCAT('Borrower already has a pending loan application (', v_pending, ')');
        END IF;
    END IF;

    IF v_err IS NULL AND p_cust_type_cd = 2 THEN
        CALL USP_LOAN_ELIGIBILITY_RESET();
        CALL USP_LOAN_ELIGIBILITY_EVAL(p_cust_id_primary, p_application_date, NULL, NULL, NULL, p_application_id);

        SELECT CONCAT('Eligibility check failed: ', IFNULL(Rule_Text, Parameter_Name),
                      ' (actual: ', IFNULL(Actual_Value, 'not available'), ')')
        INTO v_fail
        FROM tmp_loan_eligibility WHERE Is_Mandatory = 1 AND Passed = 0
        ORDER BY Row_No LIMIT 1;

        IF v_fail IS NOT NULL THEN
            SET v_err = v_fail;
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) + 1 INTO v_cycle
        FROM mst_loan_account la
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        WHERE ap.Cust_Type_Cd = p_cust_type_cd AND ap.Cust_Id_Primay = p_cust_id_primary
          AND ap.Application_Id <> IFNULL(p_application_id, 0);
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        CALL USP_CODE_SERIES_GENERATE('loan_application', v_app_no, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_app_no IS NULL THEN
            SET v_err = CONCAT('Application number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        ELSEIF EXISTS (SELECT 1 FROM mst_loan_application WHERE Application_No = LEFT(v_app_no, 40)) THEN
            SET v_err = CONCAT('Generated application number ', v_app_no, ' already exists; check the loan_application code series');
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_application_id AS application_id, NULL AS application_no, v_err AS message;
    ELSE
        IF v_action = 'ADD' THEN
            INSERT INTO mst_loan_application (
                Application_No, Application_Date, Cust_Type_Cd, Cust_Id_Primay, Cust_Id_Joint1, Cust_Id_Joint2,
                Scheme_Id, Purpose_Id, Loan_Cycle, Appl_Amount, Appl_Tenure, Repay_Duration_Cd, Beneficiary_Name,
                Bank_Account_No, IFSC_Code, Appl_Status_Cd, Remarks, FO_Id, Branch_Id, Created_By, Created_At
            ) VALUES (
                LEFT(v_app_no, 40), p_application_date, p_cust_type_cd, p_cust_id_primary, p_cust_id_joint1, p_cust_id_joint2,
                p_scheme_id, p_purpose_id, v_cycle, p_appl_amount, p_appl_tenure, p_repay_duration_cd, p_beneficiary_name,
                p_bank_account_no, p_ifsc_code, 1, p_remarks, p_fo_id, v_branch, p_user_id, NOW()
            );
            SET v_id = LAST_INSERT_ID();
        ELSE
            SET v_id = p_application_id;
            SELECT Application_No INTO v_app_no FROM mst_loan_application WHERE Application_Id = v_id;

            UPDATE mst_loan_application
            SET Application_Date = p_application_date,
                Cust_Id_Primay = p_cust_id_primary,
                Cust_Id_Joint1 = p_cust_id_joint1,
                Cust_Id_Joint2 = p_cust_id_joint2,
                Scheme_Id = p_scheme_id,
                Purpose_Id = p_purpose_id,
                Loan_Cycle = v_cycle,
                Appl_Amount = p_appl_amount,
                Appl_Tenure = p_appl_tenure,
                Repay_Duration_Cd = p_repay_duration_cd,
                Beneficiary_Name = p_beneficiary_name,
                Bank_Account_No = p_bank_account_no,
                IFSC_Code = p_ifsc_code,
                Appl_Status_Cd = 1,
                Remarks = p_remarks,
                FO_Id = p_fo_id,
                Branch_Id = v_branch,
                Modified_By = p_user_id,
                Modified_At = NOW()
            WHERE Application_Id = v_id;

            DELETE ch FROM mst_loan_application_charge ch
            JOIN mst_loan_charges c ON c.Charge_Id = ch.Charge_Id
            WHERE ch.Loan_Application_Id = v_id AND ch.Tr_Status_Cd = 1 AND ch.Voucher_Id IS NULL
              AND IFNULL(ch.Waived_Amount, 0) = 0 AND c.Deduct_During_Cd = 1;
        END IF;

        INSERT INTO mst_loan_application_charge (
            Loan_Application_Id, Charge_Id, Charge_Amount, Tax_Amount, Total_Charge, Waived_Amount, Tr_Status_Cd, Created_By, Created_At
        )
        SELECT v_id, x.Charge_Id, x.amt, x.tax, x.amt + x.tax, 0, 1, p_user_id, NOW()
        FROM (
            SELECT c.Charge_Id,
                   FN_LOAN_CHARGE_AMOUNT(c.Charge_Id, p_appl_amount) AS amt,
                   FN_LOAN_CHARGE_TAX(c.Charge_Id, FN_LOAN_CHARGE_AMOUNT(c.Charge_Id, p_appl_amount)) AS tax
            FROM mst_loan_scheme_charges sc
            JOIN mst_loan_charges c ON c.Charge_Id = sc.Charge_Id
            WHERE sc.Scheme_Id = p_scheme_id AND sc.Is_Active = 1 AND c.Is_Active = 1 AND c.Deduct_During_Cd = 1
              AND NOT EXISTS (SELECT 1 FROM mst_loan_application_charge e
                              WHERE e.Loan_Application_Id = v_id AND e.Charge_Id = c.Charge_Id AND e.Tr_Status_Cd IN (1, 2))
        ) x;

        SELECT 'SUCCESS' AS status, v_id AS application_id, LEFT(v_app_no, 40) AS application_no,
               IF(v_action = 'ADD', 'Loan application submitted successfully', 'Loan application updated successfully') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPLICATION_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
