/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPLICATION_LIST`(
    IN p_application_id BIGINT,
    IN p_keyword VARCHAR(150),
    IN p_stage VARCHAR(30),
    IN p_scheme_id INT,
    IN p_branch_id INT,
    IN p_cust_type_cd INT,
    IN p_appl_status_cd INT,
    IN p_fo_id INT,
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;
    SET p_stage = NULLIF(TRIM(IFNULL(p_stage, '')), '');

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_app_ids;
    CREATE TEMPORARY TABLE tmp_loan_app_ids (
        Application_Id BIGINT PRIMARY KEY,
        Stage VARCHAR(30) NOT NULL,
        Appl_Amount DECIMAL(18,2) NOT NULL DEFAULT 0,
        Sanctioned DECIMAL(18,2) NULL,
        Sort_Date DATE NULL
    );

    INSERT INTO tmp_loan_app_ids (Application_Id, Stage, Appl_Amount, Sanctioned, Sort_Date)
    SELECT a.Application_Id, FN_LOAN_APPL_STAGE(a.Application_Id), a.Appl_Amount,
           (SELECT x.Sanctioned_Amount FROM mst_loan_application_approval x
            WHERE x.Loan_Application_Id = a.Application_Id AND x.Approval_Status_Cd = 1
            ORDER BY x.Approval_Date DESC, x.Loan_Approval_Id DESC LIMIT 1),
           a.Application_Date
    FROM mst_loan_application a
    LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
    LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
    WHERE (p_application_id IS NULL OR a.Application_Id = p_application_id)
      AND (p_scheme_id IS NULL OR a.Scheme_Id = p_scheme_id)
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
      AND (p_cust_type_cd IS NULL OR a.Cust_Type_Cd = p_cust_type_cd)
      AND (p_appl_status_cd IS NULL OR a.Appl_Status_Cd = p_appl_status_cd)
      AND (p_fo_id IS NULL OR a.FO_Id = p_fo_id)
      AND (p_group_id IS NULL OR (a.Cust_Type_Cd = 1 AND a.Cust_Id_Primay = p_group_id))
      AND (p_member_id IS NULL
           OR (a.Cust_Type_Cd = 2 AND p_member_id IN (a.Cust_Id_Primay, IFNULL(a.Cust_Id_Joint1, 0), IFNULL(a.Cust_Id_Joint2, 0)))
           OR EXISTS (SELECT 1 FROM mst_loan_application_bulk lb WHERE lb.Loan_Application_Id = a.Application_Id AND lb.Customer_Id = p_member_id))
      AND (p_from_date IS NULL OR a.Application_Date >= p_from_date)
      AND (p_to_date IS NULL OR a.Application_Date <= p_to_date)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR a.Application_No LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Beneficiary_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR EXISTS (SELECT 1 FROM mst_loan_application_bulk lb JOIN mst_member bm ON bm.Member_Id = lb.Customer_Id
                     WHERE lb.Loan_Application_Id = a.Application_Id
                       AND (bm.Member_Name LIKE CONCAT('%', p_keyword, '%') OR IFNULL(bm.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')))
      );

    SELECT COUNT(*) INTO v_total FROM tmp_loan_app_ids WHERE p_stage IS NULL OR Stage = p_stage;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        a.Application_Id,
        a.Application_No,
        a.Application_Date,
        a.Cust_Type_Cd,
        FN_LOAN_OPT_DESC(34, a.Cust_Type_Cd) AS Cust_Type_Desc,
        a.Cust_Id_Primay AS Cust_Id_Primary,
        IF(a.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        IF(a.Cust_Type_Cd = 1, pg.Ref_Code, pm.Ref_Code) AS Member_Ref_Code,
        IF(a.Cust_Type_Cd = 1, NULL, pm.Mobile_No) AS Mobile_No,
        IF(a.Cust_Type_Cd = 1, a.Cust_Id_Primay,
           (SELECT mg.Group_Id FROM mst_member_group mg WHERE mg.Member_Id = a.Cust_Id_Primay AND mg.Is_Active = 1
            ORDER BY mg.Mem_Group_Id DESC LIMIT 1)) AS Group_Id,
        a.Cust_Id_Joint1,
        j1.Member_Name AS Joint1_Name,
        a.Cust_Id_Joint2,
        j2.Member_Name AS Joint2_Name,
        a.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        a.Purpose_Id,
        IF(a.Cust_Type_Cd = 1,
           (SELECT GROUP_CONCAT(DISTINCT lb.Loan_Purpose ORDER BY lb.Loan_Purpose SEPARATOR ', ')
            FROM mst_loan_application_bulk lb WHERE lb.Loan_Application_Id = a.Application_Id AND lb.Loan_Purpose IS NOT NULL),
           NULL) AS Member_Purposes,
        a.Loan_Cycle,
        a.Appl_Amount,
        a.Appl_Tenure,
        a.Repay_Duration_Cd,
        FN_LOAN_OPT_DESC(8, a.Repay_Duration_Cd) AS Repay_Duration_Desc,
        a.Beneficiary_Name,
        a.Bank_Account_No,
        a.IFSC_Code,
        (SELECT gm.Member_Name FROM mst_loan_application_guarantor lg JOIN mst_member gm ON gm.Member_Id = lg.Guarantor_Id
         WHERE lg.Loan_Application_Id = a.Application_Id AND lg.Release_Date IS NULL
         ORDER BY lg.Loan_Guarantor_Id LIMIT 1) AS Guarantor_Name,
        (SELECT COUNT(*) FROM mst_loan_application_guarantor lg
         WHERE lg.Loan_Application_Id = a.Application_Id AND lg.Release_Date IS NULL) AS Guarantor_Count,
        (SELECT CONCAT(IFNULL(FN_LOAN_OPT_DESC(44, mo.Collateral_Type_Cd), 'Collateral'),
                       IF(mo.Mortgage_Description IS NULL, '', CONCAT(': ', mo.Mortgage_Description)))
         FROM mst_loan_application_mortgage mo
         WHERE mo.Loan_Application_Id = a.Application_Id AND mo.Release_Date IS NULL
         ORDER BY mo.Mortgage_Id LIMIT 1) AS Mortgage_Summary,
        (SELECT COUNT(*) FROM mst_loan_application_mortgage mo
         WHERE mo.Loan_Application_Id = a.Application_Id AND mo.Release_Date IS NULL) AS Mortgage_Count,
        (SELECT COUNT(*) FROM mst_loan_application_deposit_freeze df
         WHERE df.Loan_Application_Id = a.Application_Id AND df.Freeze_Status_Cd = 1) AS Freeze_Count,
        (SELECT COUNT(*) FROM mst_loan_application_charge ch
         WHERE ch.Loan_Application_Id = a.Application_Id AND ch.Tr_Status_Cd IN (1, 2)) AS Charges_Count,
        (SELECT IFNULL(SUM(ch.Total_Charge - IFNULL(ch.Waived_Amount, 0)), 0) FROM mst_loan_application_charge ch
         WHERE ch.Loan_Application_Id = a.Application_Id AND ch.Tr_Status_Cd IN (1, 2)) AS Charges_Total,
        (SELECT IFNULL(SUM(ch.Total_Charge - IFNULL(ch.Waived_Amount, 0)), 0) FROM mst_loan_application_charge ch
         WHERE ch.Loan_Application_Id = a.Application_Id AND ch.Tr_Status_Cd = 1) AS Charges_Pending,
        (SELECT COUNT(*) FROM mst_loan_application_bulk lb WHERE lb.Loan_Application_Id = a.Application_Id) AS Member_Count,
        t.Sanctioned AS Sanctioned_Amount,
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        la.Disbursed_Amount,
        la.Principal_Outstanding,
        la.Ln_Status_Cd,
        IF(la.Loan_Account_Id IS NULL OR la.Ln_Status_Cd <> 1, NULL,
           GREATEST(0, FN_LOAN_DEMAND(la.Loan_Account_Id, CURDATE(), 'P') - FN_LOAN_PAID(la.Loan_Account_Id, CURDATE(), 'P'))
         + GREATEST(0, FN_LOAN_DEMAND(la.Loan_Account_Id, CURDATE(), 'I') - FN_LOAN_PAID(la.Loan_Account_Id, CURDATE(), 'I'))) AS Due_Amount,
        IF(la.Loan_Account_Id IS NULL, NULL, FN_LOAN_PAID(la.Loan_Account_Id, NULL, 'T')) AS Collected_Amount,
        a.Appl_Status_Cd,
        FN_LOAN_OPT_DESC(37, a.Appl_Status_Cd) AS Appl_Status_Desc,
        t.Stage,
        a.Remarks,
        a.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        a.FO_Id,
        fo.Employee_Code AS FO_Code,
        fo.Full_Name AS FO_Name,
        a.Created_By,
        u.User_Name AS Created_By_Name,
        a.Created_At,
        a.Modified_By,
        mu.User_Name AS Modified_By_Name,
        a.Modified_At
    FROM tmp_loan_app_ids t
    JOIN mst_loan_application a ON a.Application_Id = t.Application_Id
    LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
    LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
    LEFT JOIN mst_member j1 ON j1.Member_Id = a.Cust_Id_Joint1
    LEFT JOIN mst_member j2 ON j2.Member_Id = a.Cust_Id_Joint2
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = a.Scheme_Id
    LEFT JOIN mst_loan_account la ON la.Application_Id = a.Application_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = a.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = a.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = a.Created_By
    LEFT JOIN priomicro_core.mst_org_user mu ON mu.User_Id = a.Modified_By
    WHERE p_stage IS NULL OR t.Stage = p_stage
    ORDER BY t.Sort_Date DESC, t.Application_Id DESC
    LIMIT v_per_page OFFSET v_offset;

    SELECT
        COUNT(*) AS Total_Count,
        IFNULL(SUM(Stage = 'field_verification'), 0) AS Field_Verification_Count,
        IFNULL(SUM(Stage = 'approval'), 0) AS Approval_Count,
        IFNULL(SUM(Stage = 'sanctioned'), 0) AS Sanctioned_Count,
        IFNULL(SUM(Stage = 'disbursed'), 0) AS Disbursed_Count,
        IFNULL(SUM(Stage = 'rejected'), 0) AS Rejected_Count,
        IFNULL(SUM(Appl_Amount), 0) AS Total_Requested,
        IFNULL(SUM(Sanctioned), 0) AS Total_Sanctioned
    FROM tmp_loan_app_ids;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPLICATION_MEMBER_CLEAR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
