DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPLICATION_MEMBER_CLEAR`(IN p_application_id BIGINT)
BEGIN
    IF EXISTS (SELECT 1 FROM mst_loan_application WHERE Application_Id = p_application_id AND Appl_Status_Cd IN (1, 4))
       AND NOT EXISTS (SELECT 1 FROM mst_loan_account WHERE Application_Id = p_application_id) THEN
        DELETE FROM mst_loan_application_bulk WHERE Loan_Application_Id = p_application_id;
        SELECT 'SUCCESS' AS status, 'Members cleared' AS message;
    ELSE
        SELECT 'ERROR' AS status, 'Members can only be changed while the application is Submitted or Resubmission' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPLICATION_MEMBER_FINALIZE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPLICATION_MEMBER_FINALIZE`(IN p_application_id BIGINT)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_total DECIMAL(18,2) DEFAULT 0;

    SELECT COUNT(*), IFNULL(SUM(Requested_Amount), 0) INTO v_cnt, v_total
    FROM mst_loan_application_bulk WHERE Loan_Application_Id = p_application_id;

    IF v_cnt = 0 THEN
        SELECT 'ERROR' AS status, 0 AS total_amount, 0 AS member_count, 'At least one member is required' AS message;
    ELSE
        UPDATE mst_loan_application SET Appl_Amount = v_total WHERE Application_Id = p_application_id;

        UPDATE mst_loan_application_charge ch
        JOIN mst_loan_charges c ON c.Charge_Id = ch.Charge_Id
        SET ch.Charge_Amount = FN_LOAN_CHARGE_AMOUNT(ch.Charge_Id, v_total),
            ch.Tax_Amount = FN_LOAN_CHARGE_TAX(ch.Charge_Id, FN_LOAN_CHARGE_AMOUNT(ch.Charge_Id, v_total)),
            ch.Total_Charge = FN_LOAN_CHARGE_AMOUNT(ch.Charge_Id, v_total)
                            + FN_LOAN_CHARGE_TAX(ch.Charge_Id, FN_LOAN_CHARGE_AMOUNT(ch.Charge_Id, v_total))
        WHERE ch.Loan_Application_Id = p_application_id AND ch.Tr_Status_Cd = 1 AND ch.Voucher_Id IS NULL
          AND IFNULL(ch.Waived_Amount, 0) = 0 AND c.Deduct_During_Cd = 1;

        SELECT 'SUCCESS' AS status, v_total AS total_amount, v_cnt AS member_count, 'Members saved' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPLICATION_MEMBER_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPLICATION_MEMBER_LIST`(IN p_application_id BIGINT)
BEGIN
    SELECT
        lb.Id,
        lb.Loan_Application_Id,
        lb.Customer_Id,
        m.Ref_Code,
        m.Member_Name,
        m.Mobile_No,
        lb.Group_Id,
        g.Group_Name,
        (SELECT mg.Member_Role FROM mst_member_group mg WHERE mg.Member_Id = lb.Customer_Id AND mg.Group_Id = lb.Group_Id
         ORDER BY mg.Is_Active DESC, mg.Mem_Group_Id DESC LIMIT 1) AS Member_Role,
        lb.Requested_Amount,
        lb.Loan_Purpose,
        lb.Monthly_Income,
        lb.Monthly_Expense,
        lb.Existing_Loan_Obligation,
        lb.Sanction_Amount,
        lb.Disb_Amount,
        lb.Appl_Status_Cd,
        FN_LOAN_OPT_DESC(37, lb.Appl_Status_Cd) AS Appl_Status_Desc,
        lb.Remarks,
        lb.Created_At
    FROM mst_loan_application_bulk lb
    LEFT JOIN mst_member m ON m.Member_Id = lb.Customer_Id
    LEFT JOIN mst_group g ON g.Group_Id = lb.Group_Id
    WHERE lb.Loan_Application_Id = p_application_id
    ORDER BY lb.Id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPLICATION_MEMBER_SAVE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPLICATION_MEMBER_SAVE`(
    IN p_application_id BIGINT,
    IN p_customer_id INT,
    IN p_requested_amount DECIMAL(18,2),
    IN p_loan_purpose VARCHAR(100),
    IN p_monthly_income DECIMAL(10,2),
    IN p_monthly_expense DECIMAL(10,2),
    IN p_obligation DECIMAL(10,2),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(500) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_type INT DEFAULT NULL;
    DECLARE v_status INT DEFAULT NULL;
    DECLARE v_group INT DEFAULT NULL;
    DECLARE v_scheme INT DEFAULT NULL;
    DECLARE v_tenure INT DEFAULT NULL;
    DECLARE v_date DATE DEFAULT NULL;
    DECLARE v_name VARCHAR(150) DEFAULT NULL;
    DECLARE v_mstatus INT DEFAULT NULL;
    DECLARE v_slab_cnt INT DEFAULT 0;
    DECLARE v_slab_id INT DEFAULT NULL;
    DECLARE v_slab_dur INT DEFAULT NULL;
    DECLARE v_slab_min DECIMAL(18,2);
    DECLARE v_slab_max DECIMAL(18,2);
    DECLARE v_pending VARCHAR(40) DEFAULT NULL;
    DECLARE v_fail VARCHAR(500) DEFAULT NULL;

    SELECT COUNT(*), MAX(Cust_Type_Cd), MAX(Appl_Status_Cd), MAX(Cust_Id_Primay), MAX(Scheme_Id), MAX(Appl_Tenure), MAX(Application_Date)
    INTO v_cnt, v_type, v_status, v_group, v_scheme, v_tenure, v_date
    FROM mst_loan_application WHERE Application_Id = p_application_id;

    SELECT MAX(Member_Name), MAX(Current_Status_Cd) INTO v_name, v_mstatus FROM mst_member WHERE Member_Id = p_customer_id;

    IF v_cnt = 0 THEN
        SET v_err = 'Loan application not found';
    ELSEIF v_type <> 1 THEN
        SET v_err = 'Members can only be added to a group (JLG) application';
    ELSEIF v_status NOT IN (1, 4) THEN
        SET v_err = 'Members can only be changed while the application is Submitted or Resubmission';
    ELSEIF v_name IS NULL THEN
        SET v_err = CONCAT('Member ', IFNULL(p_customer_id, ''), ' not found');
    ELSEIF IFNULL(v_mstatus, 0) <> 1 THEN
        SET v_err = CONCAT('Member ', v_name, ' is not active');
    ELSEIF FN_LOAN_MEMBER_KYC_OK(p_customer_id) = 0 THEN
        SET v_err = CONCAT('KYC of member ', v_name, ' is not verified');
    ELSEIF NOT EXISTS (SELECT 1 FROM mst_member_group WHERE Member_Id = p_customer_id AND Group_Id = v_group AND Is_Active = 1) THEN
        SET v_err = CONCAT('Member ', v_name, ' is not an active member of this group');
    ELSEIF EXISTS (SELECT 1 FROM mst_loan_application_bulk WHERE Loan_Application_Id = p_application_id AND Customer_Id = p_customer_id) THEN
        SET v_err = CONCAT('Member ', v_name, ' is listed more than once');
    ELSEIF p_requested_amount IS NULL OR p_requested_amount <= 0 THEN
        SET v_err = CONCAT('Requested amount of member ', v_name, ' must be greater than zero');
    END IF;

    IF v_err IS NULL THEN
        SET v_pending = (
            SELECT ap.Application_No FROM mst_loan_application ap
            WHERE ap.Application_Id <> p_application_id AND ap.Appl_Status_Cd IN (1, 4)
              AND NOT EXISTS (SELECT 1 FROM mst_loan_account la WHERE la.Application_Id = ap.Application_Id)
              AND ((ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = p_customer_id)
                   OR EXISTS (SELECT 1 FROM mst_loan_application_bulk lb WHERE lb.Loan_Application_Id = ap.Application_Id AND lb.Customer_Id = p_customer_id))
            ORDER BY ap.Application_Id DESC LIMIT 1);
        IF v_pending IS NOT NULL THEN
            SET v_err = CONCAT('Member ', v_name, ' already has a pending loan application (', v_pending, ')');
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*), MIN(Min_Amount), MAX(Max_Amount) INTO v_slab_cnt, v_slab_min, v_slab_max
        FROM mst_loan_scheme_slab
        WHERE Scheme_Id = v_scheme AND Is_Active = 1 AND (Effect_From IS NULL OR Effect_From <= v_date);

        IF v_slab_cnt > 0 THEN
            SET v_slab_id = (SELECT sl.Id FROM mst_loan_scheme_slab sl
                             WHERE sl.Scheme_Id = v_scheme AND sl.Is_Active = 1
                               AND (sl.Effect_From IS NULL OR sl.Effect_From <= v_date)
                               AND p_requested_amount BETWEEN IFNULL(sl.Min_Amount, 0) AND IFNULL(sl.Max_Amount, 9999999999)
                             ORDER BY sl.Effect_From DESC, sl.Id DESC LIMIT 1);
            IF v_slab_id IS NULL THEN
                SET v_err = CONCAT('Requested amount of member ', v_name, ' must be within the scheme slab range (',
                                   FORMAT(IFNULL(v_slab_min, 0), 2), ' - ', FORMAT(IFNULL(v_slab_max, 0), 2), ')');
            ELSE
                SELECT MAX(Max_Duration) INTO v_slab_dur FROM mst_loan_scheme_slab WHERE Id = v_slab_id;
                IF v_slab_dur IS NOT NULL AND v_tenure > v_slab_dur THEN
                    SET v_err = CONCAT('Tenure cannot exceed the scheme slab maximum of ', v_slab_dur);
                END IF;
            END IF;
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_ELIGIBILITY_RESET();
        CALL USP_LOAN_ELIGIBILITY_EVAL(p_customer_id, v_date, p_monthly_income, p_monthly_expense, p_obligation, p_application_id);

        SELECT CONCAT('Eligibility check failed for ', v_name, ': ', IFNULL(Rule_Text, Parameter_Name),
                      ' (actual: ', IFNULL(Actual_Value, 'not available'), ')')
        INTO v_fail
        FROM tmp_loan_eligibility WHERE Is_Mandatory = 1 AND Passed = 0
        ORDER BY Row_No LIMIT 1;

        IF v_fail IS NOT NULL THEN
            SET v_err = v_fail;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS id, v_err AS message;
    ELSE
        INSERT INTO mst_loan_application_bulk (
            Loan_Application_Id, Customer_Id, Group_Id, Requested_Amount, Loan_Purpose, Monthly_Income,
            Monthly_Expense, Existing_Loan_Obligation, Appl_Status_Cd, Created_By, Created_At
        ) VALUES (
            p_application_id, p_customer_id, v_group, p_requested_amount, NULLIF(TRIM(IFNULL(p_loan_purpose, '')), ''),
            IFNULL(p_monthly_income, 0), IFNULL(p_monthly_expense, 0), IFNULL(p_obligation, 0), 1, p_user_id, NOW()
        );

        SELECT 'SUCCESS' AS status, LAST_INSERT_ID() AS id, CONCAT('Member ', v_name, ' added') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPLICATION_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
