/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPLICATION_STATUS`(
    IN p_application_id BIGINT,
    IN p_status_cd INT,
    IN p_remarks VARCHAR(500),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_cur INT DEFAULT NULL;
    DECLARE v_note VARCHAR(500);

    SET v_note = NULLIF(TRIM(IFNULL(p_remarks, '')), '');

    SELECT COUNT(*), MAX(Appl_Status_Cd) INTO v_cnt, v_cur
    FROM mst_loan_application WHERE Application_Id = p_application_id FOR UPDATE;

    IF p_application_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Loan application not found';
    ELSEIF p_status_cd IS NULL OR p_status_cd NOT IN (1, 3, 4) THEN
        SET v_err = 'Status must be 3 (Rejected), 4 (Resubmission) or 1 (Submitted, to resubmit). Use LoanApprovalAdd to approve';
    ELSEIF EXISTS (SELECT 1 FROM mst_loan_account WHERE Application_Id = p_application_id) THEN
        SET v_err = 'Status cannot change after the loan account is opened';
    ELSEIF v_cur = p_status_cd THEN
        SET v_err = NULL;
    ELSEIF v_cur NOT IN (1, 4) THEN
        SET v_err = CONCAT('A ', IFNULL(FN_LOAN_OPT_DESC(37, v_cur), 'closed'), ' application cannot change status');
    ELSEIF p_status_cd = 1 AND v_cur <> 4 THEN
        SET v_err = 'Only a Resubmission application can be resubmitted';
    ELSEIF p_status_cd IN (3, 4) AND v_note IS NULL THEN
        SET v_err = 'Remarks are required to reject or send back an application';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_application_id AS application_id, v_cur AS appl_status_cd, v_err AS message;
    ELSEIF v_cur = p_status_cd THEN
        SELECT 'SUCCESS' AS status, p_application_id AS application_id, v_cur AS appl_status_cd,
               CONCAT('Application is already ', LOWER(FN_LOAN_OPT_DESC(37, v_cur))) AS message;
    ELSE
        UPDATE mst_loan_application
        SET Appl_Status_Cd = p_status_cd,
            Remarks = IF(v_note IS NULL, Remarks,
                         LEFT(CONCAT_WS(' | ', Remarks, CONCAT(FN_LOAN_OPT_DESC(37, p_status_cd), ': ', v_note)), 500)),
            Modified_By = p_user_id,
            Modified_At = NOW()
        WHERE Application_Id = p_application_id;

        UPDATE mst_loan_application_bulk SET Appl_Status_Cd = p_status_cd WHERE Loan_Application_Id = p_application_id;

        SELECT 'SUCCESS' AS status, p_application_id AS application_id, p_status_cd AS appl_status_cd,
               CONCAT('Application status changed to ', FN_LOAN_OPT_DESC(37, p_status_cd)) AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPLICATION_TIMELINE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPLICATION_TIMELINE`(IN p_application_id BIGINT)
BEGIN
    SELECT * FROM (
        SELECT 1 AS Seq, 'submitted' AS Stage,
               TIMESTAMP(a.Application_Date, TIME(IFNULL(a.Created_At, '00:00:00'))) AS Event_At,
               CONCAT_WS(' ', u.User_Name, IF(fo.Full_Name IS NULL, NULL, CONCAT('(FO: ', fo.Full_Name, ')'))) AS By_Name,
               NULL AS Result, a.Appl_Amount AS Amount, a.Application_No AS Ref_No, NULL AS Remarks
        FROM mst_loan_application a
        LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = a.Created_By
        LEFT JOIN mst_staff fo ON fo.Staff_Id = a.FO_Id
        WHERE a.Application_Id = p_application_id

        UNION ALL
        SELECT 2, 'field_verification', TIMESTAMP(i.Inspection_Date, TIME(IFNULL(i.Created_At, '00:00:00'))),
               CONCAT(IFNULL(fo.Full_Name, 'Field officer'), IF(fo.Employee_Code IS NULL, '', CONCAT(' (', fo.Employee_Code, ')'))),
               FN_LOAN_OPT_DESC(38, i.Inspection_Result_Cd), i.Recommended_Amount, NULL, i.Inspection_Notes
        FROM mst_loan_application_inspection i
        LEFT JOIN mst_staff fo ON fo.Staff_Id = i.FO_Id
        WHERE i.Loan_Application_Id = p_application_id

        UNION ALL
        SELECT 3, CASE ap.Approval_Status_Cd WHEN 1 THEN 'sanctioned' WHEN 2 THEN 'rejected' ELSE 'revision' END,
               ap.Approval_Date, u.User_Name, FN_LOAN_OPT_DESC(39, ap.Approval_Status_Cd), ap.Sanctioned_Amount, NULL, ap.Remarks
        FROM mst_loan_application_approval ap
        LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = ap.Approved_By
        WHERE ap.Loan_Application_Id = p_application_id

        UNION ALL
        SELECT 3, IF(a.Appl_Status_Cd = 3, 'rejected', 'resubmission'), a.Modified_At, u.User_Name,
               FN_LOAN_OPT_DESC(37, a.Appl_Status_Cd), NULL, NULL, a.Remarks
        FROM mst_loan_application a
        LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = a.Modified_By
        WHERE a.Application_Id = p_application_id AND a.Appl_Status_Cd IN (3, 4) AND a.Modified_At IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM mst_loan_application_approval x
                          WHERE x.Loan_Application_Id = a.Application_Id AND x.Approval_Status_Cd IN (2, 3))

        UNION ALL
        SELECT 4, 'account_opened', TIMESTAMP(la.Loan_Date, TIME(IFNULL(la.Created_On, '00:00:00'))), u.User_Name, NULL, la.Loan_Amount, la.Ref_Account_No, NULL
        FROM mst_loan_account la
        LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = la.Created_By
        WHERE la.Application_Id = p_application_id

        UNION ALL
        SELECT 5, 'disbursed', TIMESTAMP(d.Disbursement_Date, TIME(IFNULL(d.Created_On, '00:00:00'))),
               IFNULL(au.User_Name, cu.User_Name), IF(d.Approved_By IS NULL, 'Pending approval', IF(d.Is_Final = 1, 'Final', 'Tranche')),
               d.Net_Amount, d.Disbursement_No, d.Remarks
        FROM mst_loan_account_disbursement d
        JOIN mst_loan_account la ON la.Loan_Account_Id = d.Loan_Account_Id
        LEFT JOIN priomicro_core.mst_org_user au ON au.User_Id = d.Approved_By
        LEFT JOIN priomicro_core.mst_org_user cu ON cu.User_Id = d.Created_By
        WHERE la.Application_Id = p_application_id

        UNION ALL
        SELECT 6, IF(la.Ln_Status_Cd = 2, 'closed', 'written_off'),
               IFNULL((SELECT MAX(c.Collection_Date) FROM trans_loan_collection c
                       WHERE c.Account_Id = la.Loan_Account_Id AND c.Tr_Status_Cd = 2 AND c.Ledger_Narration LIKE 'Loan closure%'),
                      (SELECT MAX(c.Collection_Date) FROM trans_loan_collection c WHERE c.Account_Id = la.Loan_Account_Id AND c.Tr_Status_Cd = 2)),
               NULL, FN_LOAN_OPT_DESC(40, la.Ln_Status_Cd), NULL, la.Ref_Account_No, NULL
        FROM mst_loan_account la
        WHERE la.Application_Id = p_application_id AND la.Ln_Status_Cd IN (2, 3)
    ) e
    ORDER BY e.Event_At IS NULL, e.Event_At, e.Seq;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_CHARGE_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_CHARGE_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_loan_charge_id BIGINT,
    IN p_application_id BIGINT,
    IN p_charge_id INT,
    IN p_charge_amount DECIMAL(12,2),
    IN p_tax_amount DECIMAL(12,2),
    IN p_waived_amount DECIMAL(12,2),
    IN p_waiver_reason VARCHAR(250),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT DEFAULT NULL;
    DECLARE v_app BIGINT DEFAULT NULL;
    DECLARE v_charge INT DEFAULT NULL;
    DECLARE v_active INT DEFAULT NULL;
    DECLARE v_base DECIMAL(18,2) DEFAULT 0;
    DECLARE v_amt DECIMAL(12,2);
    DECLARE v_tax DECIMAL(12,2);
    DECLARE v_waived DECIMAL(12,2);
    DECLARE v_reason VARCHAR(250);
    DECLARE v_id BIGINT;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_reason = NULLIF(TRIM(IFNULL(p_waiver_reason, '')), '');

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    ELSEIF v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Tr_Status_Cd), MAX(Loan_Application_Id), MAX(Charge_Id)
        INTO v_cnt, v_status, v_app, v_charge
        FROM mst_loan_application_charge WHERE Loan_Charge_Id = p_loan_charge_id FOR UPDATE;

        IF v_cnt = 0 OR v_status = 5 THEN
            SET v_err = 'Application charge not found';
        ELSEIF v_status <> 1 THEN
            SET v_err = 'Only pending (Entered) charges can be edited';
        END IF;
    ELSE
        SET v_app = p_application_id;
        SET v_charge = p_charge_id;
        SELECT MAX(Is_Active) INTO v_active FROM mst_loan_charges WHERE Charge_Id = p_charge_id;

        IF v_active IS NULL THEN
            SET v_err = 'Loan charge not found';
        ELSEIF v_active <> 1 THEN
            SET v_err = 'Loan charge is not active';
        ELSEIF EXISTS (SELECT 1 FROM mst_loan_application_charge
                       WHERE Loan_Application_Id = p_application_id AND Charge_Id = p_charge_id AND Tr_Status_Cd IN (1, 2)) THEN
            SET v_err = 'This charge is already on the application';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_APPL_CHILD_GUARD(v_app, v_err);
    END IF;

    IF v_err IS NULL THEN
        SELECT IFNULL((SELECT x.Sanctioned_Amount FROM mst_loan_application_approval x
                       WHERE x.Loan_Application_Id = v_app AND x.Approval_Status_Cd = 1
                       ORDER BY x.Approval_Date DESC, x.Loan_Approval_Id DESC LIMIT 1), MAX(a.Appl_Amount))
        INTO v_base
        FROM mst_loan_application a WHERE a.Application_Id = v_app;

        SET v_amt = IFNULL(p_charge_amount, FN_LOAN_CHARGE_AMOUNT(v_charge, v_base));
        SET v_tax = IFNULL(p_tax_amount, FN_LOAN_CHARGE_TAX(v_charge, v_amt));
        SET v_waived = IFNULL(p_waived_amount, 0);

        IF v_amt < 0 OR v_tax < 0 OR v_waived < 0 THEN
            SET v_err = 'Charge, tax and waived amounts cannot be negative';
        ELSEIF v_waived > v_amt + v_tax THEN
            SET v_err = 'Waived amount cannot exceed the total charge';
        ELSEIF v_waived > 0 AND v_reason IS NULL THEN
            SET v_err = 'Waiver reason is required when an amount is waived';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_loan_charge_id AS loan_charge_id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_application_charge (
            Loan_Application_Id, Charge_Id, Charge_Amount, Tax_Amount, Total_Charge, Waived_Amount, Waiver_Reason,
            Tr_Status_Cd, Created_By, Created_At
        ) VALUES (
            v_app, v_charge, v_amt, v_tax, v_amt + v_tax, v_waived, IF(v_waived > 0, v_reason, NULL), 1, p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();
        SELECT 'SUCCESS' AS status, v_id AS loan_charge_id, 'Charge added to the application' AS message;
    ELSE
        UPDATE mst_loan_application_charge
        SET Charge_Amount = v_amt,
            Tax_Amount = v_tax,
            Total_Charge = v_amt + v_tax,
            Waived_Amount = v_waived,
            Waiver_Reason = IF(v_waived > 0, v_reason, NULL)
        WHERE Loan_Charge_Id = p_loan_charge_id;
        SELECT 'SUCCESS' AS status, p_loan_charge_id AS loan_charge_id, 'Application charge updated' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_CHARGE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_CHARGE_LIST`(IN p_application_id BIGINT, IN p_loan_charge_id BIGINT)
BEGIN
    SELECT
        ch.Loan_Charge_Id,
        ch.Loan_Application_Id,
        ch.Charge_Id,
        c.Charge_Name,
        c.Figure_Cd,
        FN_LOAN_OPT_DESC(16, c.Figure_Cd) AS Figure_Desc,
        c.Charge_Rate,
        c.Deduct_During_Cd,
        FN_LOAN_OPT_DESC(23, c.Deduct_During_Cd) AS Deduct_During_Desc,
        c.Is_Refundable,
        ch.Charge_Amount,
        ch.Tax_Amount,
        ch.Total_Charge,
        ch.Waived_Amount,
        ch.Total_Charge - IFNULL(ch.Waived_Amount, 0) AS Net_Amount,
        ch.Waiver_Reason,
        ch.Voucher_Id,
        v.Vou_No_Ref AS Voucher_No,
        ch.Tr_Status_Cd,
        FN_LOAN_OPT_DESC(48, ch.Tr_Status_Cd) AS Tr_Status_Desc,
        ch.Created_By,
        u.User_Name AS Created_By_Name,
        ch.Created_At
    FROM mst_loan_application_charge ch
    LEFT JOIN mst_loan_charges c ON c.Charge_Id = ch.Charge_Id
    LEFT JOIN trans_vouchers v ON v.Voucher_Id = ch.Voucher_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = ch.Created_By
    WHERE (p_application_id IS NULL OR ch.Loan_Application_Id = p_application_id)
      AND (p_loan_charge_id IS NULL OR ch.Loan_Charge_Id = p_loan_charge_id)
      AND ch.Tr_Status_Cd <> 5
    ORDER BY ch.Loan_Charge_Id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_CHARGE_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
