/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_CHILD_GUARD`(IN p_application_id BIGINT, OUT p_err VARCHAR(255))
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT DEFAULT NULL;
    DECLARE v_ln INT DEFAULT NULL;

    SET p_err = NULL;

    SELECT COUNT(*), MAX(Appl_Status_Cd) INTO v_cnt, v_status
    FROM mst_loan_application WHERE Application_Id = p_application_id;

    SELECT MAX(Ln_Status_Cd) INTO v_ln FROM mst_loan_account WHERE Application_Id = p_application_id;

    IF p_application_id IS NULL OR v_cnt = 0 THEN
        SET p_err = 'Loan application not found';
    ELSEIF v_status = 3 THEN
        SET p_err = 'Application is rejected; its records cannot be changed';
    ELSEIF v_ln IS NOT NULL AND v_ln <> 1 THEN
        SET p_err = 'Loan is closed or written off; its records cannot be changed';
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
