/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_FREEZE_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_FREEZE_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_freeze_id BIGINT,
    IN p_application_id BIGINT,
    IN p_deposit_account_id INT,
    IN p_freeze_type_cd INT,
    IN p_freeze_amount DECIMAL(12,2),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_status INT;
    DECLARE v_old_acct INT DEFAULT NULL;
    DECLARE v_old_amt DECIMAL(12,2) DEFAULT 0;
    DECLARE v_type INT;
    DECLARE v_p INT;
    DECLARE v_j1 INT;
    DECLARE v_j2 INT;
    DECLARE v_da_type INT;
    DECLARE v_da_cust INT;
    DECLARE v_da_close DATE;
    DECLARE v_da_kind INT;
    DECLARE v_sb_id INT DEFAULT NULL;
    DECLARE v_avail DECIMAL(14,2) DEFAULT 0;
    DECLARE v_amount DECIMAL(12,2);
    DECLARE v_ref VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_id BIGINT;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    ELSEIF v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Loan_Application_Id), MAX(Freeze_Status_Cd), MAX(Deposit_Account_Id), MAX(Freeze_Amount)
        INTO v_cnt, v_app, v_status, v_old_acct, v_old_amt
        FROM mst_loan_application_deposit_freeze WHERE Freeze_Id = p_freeze_id FOR UPDATE;
        IF v_cnt = 0 THEN
            SET v_err = 'Deposit freeze not found';
        ELSEIF v_status <> 1 THEN
            SET v_err = 'Released freeze cannot be edited';
        ELSEIF p_deposit_account_id <> v_old_acct THEN
            SET v_err = 'Deposit account of a freeze cannot be changed; release it and add a new one';
        END IF;
    ELSE
        SET v_app = p_application_id;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_APPL_CHILD_GUARD(v_app, v_err);
    END IF;

    IF v_err IS NULL THEN
        SELECT MAX(Cust_Type_Cd), MAX(Cust_Id_Primay), MAX(Cust_Id_Joint1), MAX(Cust_Id_Joint2)
        INTO v_type, v_p, v_j1, v_j2
        FROM mst_loan_application WHERE Application_Id = v_app;

        SELECT COUNT(*), MAX(Cust_Type_Cd), MAX(Cust_Id_Primay), MAX(Closing_Date), MAX(Deposit_Type_Cd)
        INTO v_cnt, v_da_type, v_da_cust, v_da_close, v_da_kind
        FROM mst_deposit_account WHERE Account_Id = p_deposit_account_id;

        IF v_cnt = 0 THEN
            SET v_err = 'Deposit account not found';
        ELSEIF v_da_close IS NOT NULL THEN
            SET v_err = 'Deposit account is closed';
        ELSEIF NOT (
            (v_type = 2 AND v_da_type = 2 AND v_da_cust IN (v_p, IFNULL(v_j1, 0), IFNULL(v_j2, 0)))
            OR (v_type = 1 AND v_da_type = 1 AND v_da_cust = v_p)
            OR (v_type = 1 AND v_da_type = 2 AND EXISTS (SELECT 1 FROM mst_loan_application_bulk lb
                                                         WHERE lb.Loan_Application_Id = v_app AND lb.Customer_Id = v_da_cust))
        ) THEN
            SET v_err = 'Deposit account does not belong to the borrower of this application';
        ELSEIF FN_LOAN_OPT_DESC(42, p_freeze_type_cd) IS NULL THEN
            SET v_err = 'Freeze type must be 1 (Full) or 2 (Partial)';
        ELSEIF v_action = 'ADD' AND EXISTS (SELECT 1 FROM mst_loan_application_deposit_freeze
                                            WHERE Loan_Application_Id = v_app AND Deposit_Account_Id = p_deposit_account_id
                                              AND Freeze_Status_Cd = 1) THEN
            SET v_err = 'This deposit account is already frozen for the application';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        IF v_da_kind = 1 THEN
            SELECT MAX(Id) INTO v_sb_id FROM mst_deposit_account_sb WHERE Account_Id = p_deposit_account_id;
            SELECT IFNULL(MAX(Available_Balance), 0) INTO v_avail FROM mst_deposit_account_sb WHERE Id = v_sb_id FOR UPDATE;
            SET v_avail = v_avail + IF(v_action = 'EDIT', v_old_amt, 0);
        ELSE
            SELECT IFNULL(MAX(Current_Balance), 0) INTO v_avail
            FROM mst_deposit_account_td WHERE Account_Id = p_deposit_account_id;
            SET v_avail = v_avail - IFNULL((SELECT SUM(Freeze_Amount) FROM mst_loan_application_deposit_freeze
                                            WHERE Deposit_Account_Id = p_deposit_account_id AND Freeze_Status_Cd = 1
                                              AND Freeze_Id <> IFNULL(p_freeze_id, 0)), 0);
        END IF;

        SET v_amount = IF(p_freeze_type_cd = 1, v_avail, p_freeze_amount);

        IF v_amount IS NULL OR v_amount <= 0 THEN
            SET v_err = IF(p_freeze_type_cd = 1, 'No available balance to freeze', 'Freeze amount must be greater than zero');
        ELSEIF v_amount > v_avail THEN
            SET v_err = CONCAT('Freeze amount cannot exceed the available balance (', FORMAT(v_avail, 2), ')');
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        CALL USP_CODE_SERIES_GENERATE('loan_deposit_freeze', v_ref, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_ref IS NULL THEN
            SET v_err = CONCAT('Freeze reference could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_freeze_id AS freeze_id, v_err AS message;
    ELSE
        IF v_sb_id IS NOT NULL THEN
            UPDATE mst_deposit_account_sb
            SET Available_Balance = Available_Balance + IF(v_action = 'EDIT', v_old_amt, 0) - v_amount
            WHERE Id = v_sb_id;
        END IF;

        IF v_action = 'ADD' THEN
            INSERT INTO mst_loan_application_deposit_freeze (
                Loan_Application_Id, Deposit_Account_Id, Freeze_Reference_No, Freeze_Type_Cd, Freeze_Amount, Freeze_Date,
                Freeze_Status_Cd, Created_By, Created_At
            ) VALUES (
                v_app, p_deposit_account_id, LEFT(v_ref, 30), p_freeze_type_cd, v_amount, NOW(), 1, p_user_id, NOW()
            );
            SET v_id = LAST_INSERT_ID();
            SELECT 'SUCCESS' AS status, v_id AS freeze_id, CONCAT('Deposit of ', FORMAT(v_amount, 2), ' frozen') AS message;
        ELSE
            UPDATE mst_loan_application_deposit_freeze
            SET Freeze_Type_Cd = p_freeze_type_cd, Freeze_Amount = v_amount, Updated_By = p_user_id, Updated_At = NOW()
            WHERE Freeze_Id = p_freeze_id;
            SELECT 'SUCCESS' AS status, p_freeze_id AS freeze_id, 'Deposit freeze updated' AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_FREEZE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_FREEZE_LIST`(IN p_application_id BIGINT, IN p_freeze_id BIGINT, IN p_deposit_account_id INT)
BEGIN
    SELECT
        df.Freeze_Id,
        df.Loan_Application_Id,
        ap.Application_No,
        df.Deposit_Account_Id,
        da.Appl_No AS Deposit_Appl_No,
        da.Holder_Name,
        da.Deposit_Type_Cd,
        FN_LOAN_OPT_DESC(3, da.Deposit_Type_Cd) AS Deposit_Type_Desc,
        COALESCE((SELECT sb.Ref_AcNo FROM mst_deposit_account_sb sb WHERE sb.Account_Id = df.Deposit_Account_Id ORDER BY sb.Id DESC LIMIT 1),
                 (SELECT td.Ref_AcNo FROM mst_deposit_account_td td WHERE td.Account_Id = df.Deposit_Account_Id ORDER BY td.Id DESC LIMIT 1),
                 da.Appl_No) AS Deposit_Account_No,
        COALESCE((SELECT sb.Current_Balance FROM mst_deposit_account_sb sb WHERE sb.Account_Id = df.Deposit_Account_Id ORDER BY sb.Id DESC LIMIT 1),
                 (SELECT td.Current_Balance FROM mst_deposit_account_td td WHERE td.Account_Id = df.Deposit_Account_Id ORDER BY td.Id DESC LIMIT 1)) AS Current_Balance,
        (SELECT sb.Available_Balance FROM mst_deposit_account_sb sb WHERE sb.Account_Id = df.Deposit_Account_Id ORDER BY sb.Id DESC LIMIT 1) AS Available_Balance,
        df.Freeze_Reference_No,
        df.Freeze_Type_Cd,
        FN_LOAN_OPT_DESC(42, df.Freeze_Type_Cd) AS Freeze_Type_Desc,
        df.Freeze_Amount,
        df.Freeze_Date,
        df.Freeze_Status_Cd,
        FN_LOAN_OPT_DESC(43, df.Freeze_Status_Cd) AS Freeze_Status_Desc,
        df.Release_Date,
        df.Release_By,
        ru.User_Name AS Release_By_Name,
        df.Release_Reason,
        df.Created_By,
        u.User_Name AS Created_By_Name,
        df.Created_At,
        df.Updated_At
    FROM mst_loan_application_deposit_freeze df
    LEFT JOIN mst_loan_application ap ON ap.Application_Id = df.Loan_Application_Id
    LEFT JOIN mst_deposit_account da ON da.Account_Id = df.Deposit_Account_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = df.Created_By
    LEFT JOIN priomicro_core.mst_org_user ru ON ru.User_Id = df.Release_By
    WHERE (p_application_id IS NULL OR df.Loan_Application_Id = p_application_id)
      AND (p_freeze_id IS NULL OR df.Freeze_Id = p_freeze_id)
      AND (p_deposit_account_id IS NULL OR df.Deposit_Account_Id = p_deposit_account_id)
    ORDER BY df.Freeze_Id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_FREEZE_RELEASE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_FREEZE_RELEASE`(
    IN p_freeze_id BIGINT,
    IN p_reason VARCHAR(100),
    IN p_user_id INT,
    IN p_force TINYINT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_status INT;
    DECLARE v_acct INT;
    DECLARE v_amt DECIMAL(12,2);
    DECLARE v_sb_id INT DEFAULT NULL;

    SELECT COUNT(*), MAX(Loan_Application_Id), MAX(Freeze_Status_Cd), MAX(Deposit_Account_Id), MAX(Freeze_Amount)
    INTO v_cnt, v_app, v_status, v_acct, v_amt
    FROM mst_loan_application_deposit_freeze WHERE Freeze_Id = p_freeze_id FOR UPDATE;

    IF v_cnt = 0 THEN
        SET v_err = 'Deposit freeze not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Deposit freeze is already released';
    ELSEIF NULLIF(TRIM(IFNULL(p_reason, '')), '') IS NULL THEN
        SET v_err = 'Release reason is required';
    ELSEIF IFNULL(p_force, 0) = 0 AND EXISTS (SELECT 1 FROM mst_loan_account WHERE Application_Id = v_app AND Ln_Status_Cd = 1) THEN
        SET v_err = 'Deposit freeze cannot be released while the loan is active (it is released on loan closure)';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_freeze_id AS freeze_id, v_err AS message;
    ELSE
        SELECT MAX(Id) INTO v_sb_id FROM mst_deposit_account_sb WHERE Account_Id = v_acct;
        IF v_sb_id IS NOT NULL THEN
            UPDATE mst_deposit_account_sb SET Available_Balance = Available_Balance + v_amt WHERE Id = v_sb_id;
        END IF;

        UPDATE mst_loan_application_deposit_freeze
        SET Freeze_Status_Cd = 2, Release_Date = NOW(), Release_By = p_user_id, Release_Reason = LEFT(TRIM(p_reason), 100),
            Updated_By = p_user_id, Updated_At = NOW()
        WHERE Freeze_Id = p_freeze_id;

        SELECT 'SUCCESS' AS status, p_freeze_id AS freeze_id, 'Deposit freeze released' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_GUARANTOR_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_GUARANTOR_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_loan_guarantor_id BIGINT,
    IN p_application_id BIGINT,
    IN p_guarantor_id INT,
    IN p_relationship VARCHAR(50),
    IN p_guarantee_amount DECIMAL(12,2),
    IN p_consent_date DATETIME,
    IN p_consent_path VARCHAR(100),
    IN p_remarks VARCHAR(200),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT DEFAULT NULL;
    DECLARE v_released DATETIME DEFAULT NULL;
    DECLARE v_type INT;
    DECLARE v_p INT;
    DECLARE v_j1 INT;
    DECLARE v_j2 INT;
    DECLARE v_amount DECIMAL(18,2);
    DECLARE v_mstatus INT;
    DECLARE v_id BIGINT;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    ELSEIF v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Loan_Application_Id), MAX(Release_Date) INTO v_cnt, v_app, v_released
        FROM mst_loan_application_guarantor WHERE Loan_Guarantor_Id = p_loan_guarantor_id FOR UPDATE;
        IF v_cnt = 0 THEN
            SET v_err = 'Guarantor record not found';
        ELSEIF v_released IS NOT NULL THEN
            SET v_err = 'Released guarantor cannot be edited';
        END IF;
    ELSE
        SET v_app = p_application_id;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_APPL_CHILD_GUARD(v_app, v_err);
    END IF;

    IF v_err IS NULL THEN
        SELECT MAX(Cust_Type_Cd), MAX(Cust_Id_Primay), MAX(Cust_Id_Joint1), MAX(Cust_Id_Joint2), MAX(Appl_Amount)
        INTO v_type, v_p, v_j1, v_j2, v_amount
        FROM mst_loan_application WHERE Application_Id = v_app;

        SELECT MAX(Current_Status_Cd) INTO v_mstatus FROM mst_member WHERE Member_Id = p_guarantor_id;

        IF v_mstatus IS NULL THEN
            SET v_err = 'Guarantor (member) not found';
        ELSEIF v_mstatus <> 1 THEN
            SET v_err = 'Guarantor is not active';
        ELSEIF v_type = 2 AND p_guarantor_id IN (v_p, IFNULL(v_j1, 0), IFNULL(v_j2, 0)) THEN
            SET v_err = 'Guarantor cannot be the borrower or a joint applicant';
        ELSEIF EXISTS (SELECT 1 FROM mst_loan_application_bulk WHERE Loan_Application_Id = v_app AND Customer_Id = p_guarantor_id) THEN
            SET v_err = 'Guarantor cannot be a borrowing member of this application';
        ELSEIF EXISTS (SELECT 1 FROM mst_loan_application_guarantor
                       WHERE Loan_Application_Id = v_app AND Guarantor_Id = p_guarantor_id AND Release_Date IS NULL
                         AND Loan_Guarantor_Id <> IFNULL(p_loan_guarantor_id, 0)) THEN
            SET v_err = 'This guarantor is already on the application';
        ELSEIF IFNULL(p_guarantee_amount, 0) < 0 THEN
            SET v_err = 'Guarantee amount cannot be negative';
        ELSEIF IFNULL(p_guarantee_amount, 0) > v_amount THEN
            SET v_err = CONCAT('Guarantee amount cannot exceed the applied amount (', FORMAT(v_amount, 2), ')');
        ELSEIF p_consent_date IS NOT NULL AND p_consent_date > NOW() THEN
            SET v_err = 'Consent date cannot be in the future';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_loan_guarantor_id AS loan_guarantor_id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_application_guarantor (
            Loan_Application_Id, Guarantor_Id, Relationship_With_Borrower, Guarantee_Amount, Consent_Date,
            Consent_Document_Path, Remarks, Created_By, Created_At
        ) VALUES (
            v_app, p_guarantor_id, NULLIF(TRIM(IFNULL(p_relationship, '')), ''), IFNULL(p_guarantee_amount, 0), p_consent_date,
            p_consent_path, NULLIF(TRIM(IFNULL(p_remarks, '')), ''), p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();
        SELECT 'SUCCESS' AS status, v_id AS loan_guarantor_id, 'Guarantor added' AS message;
    ELSE
        UPDATE mst_loan_application_guarantor
        SET Guarantor_Id = p_guarantor_id,
            Relationship_With_Borrower = NULLIF(TRIM(IFNULL(p_relationship, '')), ''),
            Guarantee_Amount = IFNULL(p_guarantee_amount, 0),
            Consent_Date = p_consent_date,
            Consent_Document_Path = p_consent_path,
            Remarks = NULLIF(TRIM(IFNULL(p_remarks, '')), '')
        WHERE Loan_Guarantor_Id = p_loan_guarantor_id;
        SELECT 'SUCCESS' AS status, p_loan_guarantor_id AS loan_guarantor_id, 'Guarantor updated' AS message;
    END IF;
END ;;
