CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_GUARANTOR_LIST`(IN p_application_id BIGINT, IN p_loan_guarantor_id BIGINT)
BEGIN
    SELECT
        lg.Loan_Guarantor_Id,
        lg.Loan_Application_Id,
        lg.Guarantor_Id,
        m.Ref_Code,
        m.Member_Name AS Guarantor_Name,
        m.Mobile_No,
        lg.Relationship_With_Borrower,
        lg.Guarantee_Amount,
        lg.Consent_Date,
        lg.Consent_Document_Path,
        lg.Release_Date,
        lg.Release_By,
        ru.User_Name AS Release_By_Name,
        lg.Remarks,
        lg.Created_By,
        u.User_Name AS Created_By_Name,
        lg.Created_At
    FROM mst_loan_application_guarantor lg
    LEFT JOIN mst_member m ON m.Member_Id = lg.Guarantor_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = lg.Created_By
    LEFT JOIN priomicro_core.mst_org_user ru ON ru.User_Id = lg.Release_By
    WHERE (p_application_id IS NULL OR lg.Loan_Application_Id = p_application_id)
      AND (p_loan_guarantor_id IS NULL OR lg.Loan_Guarantor_Id = p_loan_guarantor_id)
    ORDER BY lg.Loan_Guarantor_Id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
