DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_GUARANTOR_RELEASE`(IN p_loan_guarantor_id BIGINT, IN p_remarks VARCHAR(200), IN p_user_id INT)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_released DATETIME;

    SELECT COUNT(*), MAX(Loan_Application_Id), MAX(Release_Date) INTO v_cnt, v_app, v_released
    FROM mst_loan_application_guarantor WHERE Loan_Guarantor_Id = p_loan_guarantor_id FOR UPDATE;

    IF v_cnt = 0 THEN
        SET v_err = 'Guarantor record not found';
    ELSEIF v_released IS NOT NULL THEN
        SET v_err = 'Guarantor is already released';
    ELSEIF EXISTS (SELECT 1 FROM mst_loan_account WHERE Application_Id = v_app AND Ln_Status_Cd = 1) THEN
        SET v_err = 'Guarantor cannot be released while the loan is active (it is released on loan closure)';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_loan_guarantor_id AS loan_guarantor_id, v_err AS message;
    ELSE
        UPDATE mst_loan_application_guarantor
        SET Release_Date = NOW(), Release_By = p_user_id,
            Remarks = IF(NULLIF(TRIM(IFNULL(p_remarks, '')), '') IS NULL, Remarks,
                         LEFT(CONCAT_WS(' | ', Remarks, CONCAT('Released: ', TRIM(p_remarks))), 200))
        WHERE Loan_Guarantor_Id = p_loan_guarantor_id;
        SELECT 'SUCCESS' AS status, p_loan_guarantor_id AS loan_guarantor_id, 'Guarantor released' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
