CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_MORTGAGE_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_mortgage_id BIGINT,
    IN p_application_id BIGINT,
    IN p_collateral_type_cd INT,
    IN p_description VARCHAR(250),
    IN p_ownership_type_cd INT,
    IN p_market_value DECIMAL(12,2),
    IN p_expiry_date DATE,
    IN p_execution_date DATE,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_released DATETIME;
    DECLARE v_no VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_id BIGINT;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    ELSEIF v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Loan_Application_Id), MAX(Release_Date) INTO v_cnt, v_app, v_released
        FROM mst_loan_application_mortgage WHERE Mortgage_Id = p_mortgage_id FOR UPDATE;
        IF v_cnt = 0 THEN
            SET v_err = 'Mortgage not found';
        ELSEIF v_released IS NOT NULL THEN
            SET v_err = 'Released mortgage cannot be edited';
        END IF;
    ELSE
        SET v_app = p_application_id;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_APPL_CHILD_GUARD(v_app, v_err);
    END IF;

    IF v_err IS NULL THEN
        IF FN_LOAN_OPT_DESC(44, p_collateral_type_cd) IS NULL THEN
            SET v_err = 'Invalid collateral type';
        ELSEIF p_ownership_type_cd IS NOT NULL AND FN_LOAN_OPT_DESC(45, p_ownership_type_cd) IS NULL THEN
            SET v_err = 'Invalid ownership type';
        ELSEIF p_market_value IS NULL OR p_market_value <= 0 THEN
            SET v_err = 'Market value must be greater than zero';
        ELSEIF p_execution_date IS NOT NULL AND p_execution_date > CURDATE() THEN
            SET v_err = 'Mortgage execution date cannot be in the future';
        ELSEIF p_expiry_date IS NOT NULL AND p_execution_date IS NOT NULL AND p_expiry_date <= p_execution_date THEN
            SET v_err = 'Expiry date must be after the execution date';
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        CALL USP_CODE_SERIES_GENERATE('loan_mortgage', v_no, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_no IS NULL THEN
            SET v_err = CONCAT('Mortgage number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_mortgage_id AS mortgage_id, NULL AS mortgage_no, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_application_mortgage (
            Mortgage_No, Loan_Application_Id, Collateral_Type_Cd, Mortgage_Description, Ownership_Type_Cd,
            Market_Value, Expiry_Date, Mortgage_Execution_Date, Created_By, Created_At
        ) VALUES (
            LEFT(v_no, 30), v_app, p_collateral_type_cd, NULLIF(TRIM(IFNULL(p_description, '')), ''), p_ownership_type_cd,
            p_market_value, p_expiry_date, p_execution_date, p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();
        SELECT 'SUCCESS' AS status, v_id AS mortgage_id, LEFT(v_no, 30) AS mortgage_no, 'Mortgage added' AS message;
    ELSE
        UPDATE mst_loan_application_mortgage
        SET Collateral_Type_Cd = p_collateral_type_cd,
            Mortgage_Description = NULLIF(TRIM(IFNULL(p_description, '')), ''),
            Ownership_Type_Cd = p_ownership_type_cd,
            Market_Value = p_market_value,
            Expiry_Date = p_expiry_date,
            Mortgage_Execution_Date = p_execution_date,
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Mortgage_Id = p_mortgage_id;
        SELECT 'SUCCESS' AS status, p_mortgage_id AS mortgage_id,
               (SELECT Mortgage_No FROM mst_loan_application_mortgage WHERE Mortgage_Id = p_mortgage_id) AS mortgage_no,
               'Mortgage updated' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_MORTGAGE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_MORTGAGE_LIST`(IN p_application_id BIGINT, IN p_mortgage_id BIGINT)
BEGIN
    SELECT
        mo.Mortgage_Id,
        mo.Mortgage_No,
        mo.Loan_Application_Id,
        mo.Collateral_Type_Cd,
        FN_LOAN_OPT_DESC(44, mo.Collateral_Type_Cd) AS Collateral_Type_Desc,
        mo.Mortgage_Description,
        mo.Ownership_Type_Cd,
        FN_LOAN_OPT_DESC(45, mo.Ownership_Type_Cd) AS Ownership_Type_Desc,
        mo.Market_Value,
        mo.Expiry_Date,
        mo.Mortgage_Execution_Date,
        mo.Release_Date,
        mo.Released_By,
        ru.User_Name AS Released_By_Name,
        mo.Release_Reason,
        mo.Created_By,
        u.User_Name AS Created_By_Name,
        mo.Created_At,
        mo.Updated_At
    FROM mst_loan_application_mortgage mo
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = mo.Created_By
    LEFT JOIN priomicro_core.mst_org_user ru ON ru.User_Id = mo.Released_By
    WHERE (p_application_id IS NULL OR mo.Loan_Application_Id = p_application_id)
      AND (p_mortgage_id IS NULL OR mo.Mortgage_Id = p_mortgage_id)
    ORDER BY mo.Mortgage_Id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
