DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_MORTGAGE_RELEASE`(IN p_mortgage_id BIGINT, IN p_reason VARCHAR(100), IN p_user_id INT)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_released DATETIME;

    SELECT COUNT(*), MAX(Loan_Application_Id), MAX(Release_Date) INTO v_cnt, v_app, v_released
    FROM mst_loan_application_mortgage WHERE Mortgage_Id = p_mortgage_id FOR UPDATE;

    IF v_cnt = 0 THEN
        SET v_err = 'Mortgage not found';
    ELSEIF v_released IS NOT NULL THEN
        SET v_err = 'Mortgage is already released';
    ELSEIF NULLIF(TRIM(IFNULL(p_reason, '')), '') IS NULL THEN
        SET v_err = 'Release reason is required';
    ELSEIF EXISTS (SELECT 1 FROM mst_loan_account WHERE Application_Id = v_app AND Ln_Status_Cd = 1) THEN
        SET v_err = 'Mortgage cannot be released while the loan is active (it is released on loan closure)';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_mortgage_id AS mortgage_id, v_err AS message;
    ELSE
        UPDATE mst_loan_application_mortgage
        SET Release_Date = NOW(), Released_By = p_user_id, Release_Reason = LEFT(TRIM(p_reason), 100),
            Updated_By = p_user_id, Updated_At = NOW()
        WHERE Mortgage_Id = p_mortgage_id;
        SELECT 'SUCCESS' AS status, p_mortgage_id AS mortgage_id, 'Mortgage released' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
