CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_PROJECT_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_project_id BIGINT,
    IN p_application_id BIGINT,
    IN p_category VARCHAR(150),
    IN p_name VARCHAR(150),
    IN p_activity VARCHAR(150),
    IN p_address TEXT,
    IN p_latitude DECIMAL(10,7),
    IN p_longitude DECIMAL(10,7),
    IN p_existing TINYINT,
    IN p_start_date DATE,
    IN p_total_cost DECIMAL(12,2),
    IN p_contribution DECIMAL(12,2),
    IN p_other DECIMAL(12,2),
    IN p_proposed DECIMAL(12,2),
    IN p_expected_income DECIMAL(12,2),
    IN p_existing_income DECIMAL(12,2),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_id BIGINT;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET p_total_cost = IFNULL(p_total_cost, 0);
    SET p_contribution = IFNULL(p_contribution, 0);
    SET p_other = IFNULL(p_other, 0);
    SET p_proposed = IFNULL(p_proposed, 0);

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    ELSEIF v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Loan_Application_Id) INTO v_cnt, v_app
        FROM mst_loan_application_project WHERE Project_Id = p_project_id FOR UPDATE;
        IF v_cnt = 0 THEN
            SET v_err = 'Project not found';
        END IF;
    ELSE
        SET v_app = p_application_id;
        IF EXISTS (SELECT 1 FROM mst_loan_application_project WHERE Loan_Application_Id = p_application_id) THEN
            SET v_err = 'The application already has a project; edit it instead';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_APPL_CHILD_GUARD(v_app, v_err);
    END IF;

    IF v_err IS NULL THEN
        IF NULLIF(TRIM(IFNULL(p_name, '')), '') IS NULL THEN
            SET v_err = 'Project name is required';
        ELSEIF p_total_cost < 0 OR p_contribution < 0 OR p_other < 0 OR p_proposed < 0 THEN
            SET v_err = 'Project amounts cannot be negative';
        ELSEIF p_proposed > p_total_cost THEN
            SET v_err = 'Proposed loan amount cannot exceed the total project cost';
        ELSEIF p_contribution + p_other + p_proposed > p_total_cost THEN
            SET v_err = 'Contribution + other funding + proposed loan cannot exceed the total project cost';
        ELSEIF p_latitude IS NOT NULL AND (p_latitude < -90 OR p_latitude > 90) THEN
            SET v_err = 'Latitude must be between -90 and 90';
        ELSEIF p_longitude IS NOT NULL AND (p_longitude < -180 OR p_longitude > 180) THEN
            SET v_err = 'Longitude must be between -180 and 180';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_project_id AS project_id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_application_project (
            Loan_Application_Id, Project_Category, Project_Name, Business_Activity, Project_Address, Latitude, Longitude,
            Existing_Project, Project_Start_Date, Total_Project_Cost, Applicant_Contribution, Other_Funding,
            Proposed_Loan_Amount, Expected_Monthly_Net_Income, Existing_Monthly_Income, Created_By, Created_At
        ) VALUES (
            v_app, NULLIF(TRIM(IFNULL(p_category, '')), ''), TRIM(p_name), NULLIF(TRIM(IFNULL(p_activity, '')), ''),
            NULLIF(TRIM(IFNULL(p_address, '')), ''), p_latitude, p_longitude, IFNULL(p_existing, 0), p_start_date,
            p_total_cost, p_contribution, p_other, p_proposed, IFNULL(p_expected_income, 0), IFNULL(p_existing_income, 0),
            p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();
        SELECT 'SUCCESS' AS status, v_id AS project_id, 'Project added' AS message;
    ELSE
        UPDATE mst_loan_application_project
        SET Project_Category = NULLIF(TRIM(IFNULL(p_category, '')), ''),
            Project_Name = TRIM(p_name),
            Business_Activity = NULLIF(TRIM(IFNULL(p_activity, '')), ''),
            Project_Address = NULLIF(TRIM(IFNULL(p_address, '')), ''),
            Latitude = p_latitude,
            Longitude = p_longitude,
            Existing_Project = IFNULL(p_existing, 0),
            Project_Start_Date = p_start_date,
            Total_Project_Cost = p_total_cost,
            Applicant_Contribution = p_contribution,
            Other_Funding = p_other,
            Proposed_Loan_Amount = p_proposed,
            Expected_Monthly_Net_Income = IFNULL(p_expected_income, 0),
            Existing_Monthly_Income = IFNULL(p_existing_income, 0)
        WHERE Project_Id = p_project_id;
        SELECT 'SUCCESS' AS status, p_project_id AS project_id, 'Project updated' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPL_PROJECT_LIST` */;
