CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPL_PROJECT_LIST`(IN p_application_id BIGINT, IN p_project_id BIGINT)
BEGIN
    SELECT
        pr.Project_Id, pr.Loan_Application_Id, pr.Project_Category, pr.Project_Name, pr.Business_Activity,
        pr.Project_Address, pr.Latitude, pr.Longitude, pr.Existing_Project, pr.Project_Start_Date,
        pr.Total_Project_Cost, pr.Applicant_Contribution, pr.Other_Funding, pr.Proposed_Loan_Amount,
        pr.Expected_Monthly_Net_Income, pr.Existing_Monthly_Income, pr.Created_By,
        u.User_Name AS Created_By_Name, pr.Created_At
    FROM mst_loan_application_project pr
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = pr.Created_By
    WHERE (p_application_id IS NULL OR pr.Loan_Application_Id = p_application_id)
      AND (p_project_id IS NULL OR pr.Project_Id = p_project_id)
    ORDER BY pr.Project_Id;
END ;;
