DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPROVAL_ADD`(
    IN p_application_id BIGINT,
    IN p_status_cd INT,
    IN p_amount DECIMAL(18,2),
    IN p_rate DECIMAL(7,2),
    IN p_duration INT,
    IN p_schedule_cd INT,
    IN p_moratorium INT,
    IN p_first_due DATE,
    IN p_remarks VARCHAR(500),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_appl DECIMAL(18,2);
    DECLARE v_scheme INT;
    DECLARE v_intt INT;
    DECLARE v_repay INT;
    DECLARE v_note VARCHAR(500);
    DECLARE v_new_status INT;
    DECLARE v_id BIGINT;
    DECLARE v_req_total DECIMAL(18,2) DEFAULT 0;
    DECLARE v_last_id BIGINT DEFAULT NULL;

    SET v_note = NULLIF(TRIM(IFNULL(p_remarks, '')), '');

    SELECT COUNT(*), MAX(Appl_Status_Cd), MAX(Appl_Amount), MAX(Scheme_Id) INTO v_cnt, v_status, v_appl, v_scheme
    FROM mst_loan_application WHERE Application_Id = p_application_id FOR UPDATE;

    IF p_application_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Loan application not found';
    ELSEIF p_status_cd IS NULL OR FN_LOAN_OPT_DESC(39, p_status_cd) IS NULL THEN
        SET v_err = 'Approval status must be 1 (Approved), 2 (Rejected) or 3 (Revision)';
    ELSEIF v_status NOT IN (1, 4) THEN
        SET v_err = CONCAT('Only Submitted or Resubmission applications can be approved (current status: ',
                           IFNULL(FN_LOAN_OPT_DESC(37, v_status), v_status), ')');
    ELSEIF EXISTS (SELECT 1 FROM mst_loan_account WHERE Application_Id = p_application_id) THEN
        SET v_err = 'A loan account already exists for this application';
    ELSEIF p_status_cd = 1 AND FN_LOAN_APPL_STAGE(p_application_id) <> 'approval' THEN
        SET v_err = 'Application needs a Positive field verification before approval';
    ELSEIF p_status_cd IN (2, 3) AND v_note IS NULL THEN
        SET v_err = 'Remarks are required to reject or send the application for revision';
    END IF;

    IF v_err IS NULL AND p_status_cd = 1 THEN
        CALL USP_LOAN_SANCTION_TERMS(p_application_id, p_amount, p_rate, p_duration, p_schedule_cd, p_moratorium, p_first_due,
                                     v_intt, v_repay, v_err);
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS loan_approval_id, v_status AS appl_status_cd, v_err AS message;
    ELSE
        SET v_new_status = CASE p_status_cd WHEN 1 THEN 2 WHEN 2 THEN 3 ELSE 4 END;

        INSERT INTO mst_loan_application_approval (
            Loan_Application_Id, Approval_Status_Cd, Application_Amount, Sanctioned_Amount, Interest_Rate, Loan_Duration,
            Repay_Schedule_Cd, Moratorium_Days, First_Due_Date, Approval_Date, Approved_By, Remarks, Created_At
        ) VALUES (
            p_application_id, p_status_cd, v_appl, IF(p_status_cd = 1, p_amount, 0),
            IF(p_status_cd = 1, p_rate, NULL), IF(p_status_cd = 1, p_duration, NULL), IF(p_status_cd = 1, p_schedule_cd, NULL),
            IF(p_status_cd = 1, p_moratorium, 0), IF(p_status_cd = 1, p_first_due, NULL), NOW(), p_user_id, v_note, NOW()
        );
        SET v_id = LAST_INSERT_ID();

        UPDATE mst_loan_application
        SET Appl_Status_Cd = v_new_status, Modified_By = p_user_id, Modified_At = NOW()
        WHERE Application_Id = p_application_id;

        UPDATE mst_loan_application_bulk SET Appl_Status_Cd = v_new_status WHERE Loan_Application_Id = p_application_id;

        IF p_status_cd = 1 THEN
            SELECT IFNULL(SUM(Requested_Amount), 0), MAX(Id) INTO v_req_total, v_last_id
            FROM mst_loan_application_bulk WHERE Loan_Application_Id = p_application_id;

            IF v_req_total > 0 THEN
                UPDATE mst_loan_application_bulk
                SET Sanction_Amount = ROUND(Requested_Amount * p_amount / v_req_total, 2)
                WHERE Loan_Application_Id = p_application_id;

                UPDATE mst_loan_application_bulk
                SET Sanction_Amount = Sanction_Amount + (p_amount - (SELECT s FROM (SELECT SUM(Sanction_Amount) AS s
                                                                                     FROM mst_loan_application_bulk
                                                                                     WHERE Loan_Application_Id = p_application_id) z))
                WHERE Id = v_last_id;
            END IF;

            INSERT INTO mst_loan_application_charge (
                Loan_Application_Id, Charge_Id, Charge_Amount, Tax_Amount, Total_Charge, Waived_Amount, Tr_Status_Cd, Created_By, Created_At
            )
            SELECT p_application_id, x.Charge_Id, x.amt, x.tax, x.amt + x.tax, 0, 1, p_user_id, NOW()
            FROM (
                SELECT c.Charge_Id,
                       FN_LOAN_CHARGE_AMOUNT(c.Charge_Id, p_amount) AS amt,
                       FN_LOAN_CHARGE_TAX(c.Charge_Id, FN_LOAN_CHARGE_AMOUNT(c.Charge_Id, p_amount)) AS tax
                FROM mst_loan_scheme_charges sc
                JOIN mst_loan_charges c ON c.Charge_Id = sc.Charge_Id
                WHERE sc.Scheme_Id = v_scheme AND sc.Is_Active = 1 AND c.Is_Active = 1 AND c.Deduct_During_Cd IN (2, 3)
                  AND NOT EXISTS (SELECT 1 FROM mst_loan_application_charge e
                                  WHERE e.Loan_Application_Id = p_application_id AND e.Charge_Id = c.Charge_Id AND e.Tr_Status_Cd IN (1, 2))
            ) x;
        END IF;

        SELECT 'SUCCESS' AS status, v_id AS loan_approval_id, v_new_status AS appl_status_cd,
               p_amount AS sanctioned_amount, p_rate AS interest_rate,
               CASE p_status_cd
                   WHEN 1 THEN CONCAT('Loan sanctioned for ', FORMAT(p_amount, 2))
                   WHEN 2 THEN 'Loan application rejected'
                   ELSE 'Loan application sent back for revision'
               END AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_APPROVAL_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
