/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_APPROVAL_LIST`(
    IN p_loan_approval_id BIGINT,
    IN p_application_id BIGINT,
    IN p_status_cd INT,
    IN p_branch_id INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_pending_only TINYINT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_appr_ids;
    CREATE TEMPORARY TABLE tmp_loan_appr_ids (
        Row_Key BIGINT PRIMARY KEY,
        Application_Id BIGINT NOT NULL,
        Loan_Approval_Id BIGINT NULL,
        Sort_At DATETIME NULL
    );

    IF IFNULL(p_pending_only, 0) = 1 THEN
        INSERT INTO tmp_loan_appr_ids (Row_Key, Application_Id, Loan_Approval_Id, Sort_At)
        SELECT a.Application_Id, a.Application_Id, NULL, a.Application_Date
        FROM mst_loan_application a
        LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
        LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
        WHERE a.Appl_Status_Cd IN (1, 4)
          AND FN_LOAN_APPL_STAGE(a.Application_Id) = 'approval'
          AND (p_application_id IS NULL OR a.Application_Id = p_application_id)
          AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
          AND (p_from_date IS NULL OR a.Application_Date >= p_from_date)
          AND (p_to_date IS NULL OR a.Application_Date <= p_to_date)
          AND (p_keyword IS NULL OR p_keyword = ''
               OR a.Application_No LIKE CONCAT('%', p_keyword, '%')
               OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
               OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));
    ELSE
        INSERT INTO tmp_loan_appr_ids (Row_Key, Application_Id, Loan_Approval_Id, Sort_At)
        SELECT ap.Loan_Approval_Id, ap.Loan_Application_Id, ap.Loan_Approval_Id, ap.Approval_Date
        FROM mst_loan_application_approval ap
        JOIN mst_loan_application a ON a.Application_Id = ap.Loan_Application_Id
        LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
        LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
        WHERE (p_loan_approval_id IS NULL OR ap.Loan_Approval_Id = p_loan_approval_id)
          AND (p_application_id IS NULL OR ap.Loan_Application_Id = p_application_id)
          AND (p_status_cd IS NULL OR ap.Approval_Status_Cd = p_status_cd)
          AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
          AND (p_from_date IS NULL OR DATE(ap.Approval_Date) >= p_from_date)
          AND (p_to_date IS NULL OR DATE(ap.Approval_Date) <= p_to_date)
          AND (p_keyword IS NULL OR p_keyword = ''
               OR a.Application_No LIKE CONCAT('%', p_keyword, '%')
               OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
               OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));
    END IF;

    SELECT COUNT(*) INTO v_total FROM tmp_loan_appr_ids;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        ap.Loan_Approval_Id,
        a.Application_Id AS Loan_Application_Id,
        a.Application_No,
        a.Application_Date,
        a.Cust_Type_Cd,
        FN_LOAN_OPT_DESC(34, a.Cust_Type_Cd) AS Cust_Type_Desc,
        a.Cust_Id_Primay AS Cust_Id_Primary,
        IF(a.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        a.Scheme_Id,
        s.Scheme_Name,
        IFNULL(ap.Application_Amount, a.Appl_Amount) AS Application_Amount,
        a.Appl_Tenure,
        (SELECT i.Recommended_Amount FROM mst_loan_application_inspection i
         WHERE i.Loan_Application_Id = a.Application_Id AND i.Inspection_Result_Cd = 1
         ORDER BY i.Inspection_Date DESC, i.Inspection_Id DESC LIMIT 1) AS Recommended_Amount,
        ap.Sanctioned_Amount,
        ap.Interest_Rate,
        ap.Loan_Duration,
        ap.Repay_Schedule_Cd,
        FN_LOAN_OPT_DESC(22, ap.Repay_Schedule_Cd) AS Repay_Schedule_Desc,
        ap.Moratorium_Days,
        ap.First_Due_Date,
        ap.Approval_Date,
        ap.Approved_By,
        u.User_Name AS Approver_Name,
        ap.Approval_Status_Cd,
        FN_LOAN_OPT_DESC(39, ap.Approval_Status_Cd) AS Approval_Status_Desc,
        ap.Remarks,
        a.Appl_Status_Cd,
        FN_LOAN_OPT_DESC(37, a.Appl_Status_Cd) AS Appl_Status_Desc,
        a.Branch_Id,
        b.Branch_Name,
        a.FO_Id,
        fo.Full_Name AS FO_Name,
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No
    FROM tmp_loan_appr_ids t
    JOIN mst_loan_application a ON a.Application_Id = t.Application_Id
    LEFT JOIN mst_loan_application_approval ap ON ap.Loan_Approval_Id = t.Loan_Approval_Id
    LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
    LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = a.Scheme_Id
    LEFT JOIN mst_loan_account la ON la.Application_Id = a.Application_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = a.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = a.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = ap.Approved_By
    ORDER BY t.Sort_At DESC, t.Row_Key DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_BOOK_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_BOOK_LIST`(
    IN p_loan_account_id BIGINT,
    IN p_keyword VARCHAR(150),
    IN p_branch_id INT,
    IN p_group_id INT,
    IN p_center_id INT,
    IN p_scheme_id INT,
    IN p_fo_id INT,
    IN p_member_id INT,
    IN p_ln_status_cd INT,
    IN p_bucket VARCHAR(20),
    IN p_is_defaulter TINYINT,
    IN p_is_npa TINYINT,
    IN p_as_on DATE,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;
    SET p_as_on = IFNULL(p_as_on, CURDATE());

    CALL USP_LOAN_FACTS_RESET();

    INSERT INTO tmp_loan_facts (Loan_Account_Id)
    SELECT la.Loan_Account_Id
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE (p_loan_account_id IS NULL OR la.Loan_Account_Id = p_loan_account_id)
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
      AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
      AND (p_fo_id IS NULL OR ap.FO_Id = p_fo_id)
      AND (p_ln_status_cd IS NULL OR la.Ln_Status_Cd = p_ln_status_cd)
      AND (p_is_defaulter IS NULL OR IFNULL(la.Is_Defaulter, 0) = p_is_defaulter)
      AND (p_is_npa IS NULL OR IFNULL(la.Is_NPA, 0) = p_is_npa)
      AND (p_member_id IS NULL
           OR (ap.Cust_Type_Cd = 2 AND p_member_id IN (ap.Cust_Id_Primay, IFNULL(ap.Cust_Id_Joint1, 0), IFNULL(ap.Cust_Id_Joint2, 0)))
           OR (ap.Cust_Type_Cd = 1 AND EXISTS (SELECT 1 FROM mst_loan_application_bulk bk
                                               WHERE bk.Loan_Application_Id = ap.Application_Id AND bk.Customer_Id = p_member_id)))
      AND (p_group_id IS NULL
           OR (ap.Cust_Type_Cd = 1 AND ap.Cust_Id_Primay = p_group_id)
           OR (ap.Cust_Type_Cd = 2 AND EXISTS (SELECT 1 FROM mst_member_group mg
                                               WHERE mg.Member_Id = ap.Cust_Id_Primay AND mg.Group_Id = p_group_id AND mg.Is_Active = 1)))
      AND (p_center_id IS NULL OR IFNULL(pg.Center_Id, pm.Center_Id) = p_center_id)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR ap.Application_No LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));

    CALL USP_LOAN_FACTS_FILL(p_as_on);

    IF p_bucket IS NOT NULL AND p_bucket <> '' THEN
        DELETE FROM tmp_loan_facts
        WHERE NOT (
            (p_bucket IN ('current', 'par', 'npa', 'closed') AND Bucket = p_bucket)
            OR (p_bucket = 'par_1_30' AND IFNULL(Ln_Status_Cd, 1) = 1 AND Dpd BETWEEN 1 AND 30)
            OR (p_bucket = 'par_31_60' AND IFNULL(Ln_Status_Cd, 1) = 1 AND Dpd BETWEEN 31 AND 60)
            OR (p_bucket = 'par_61_90' AND IFNULL(Ln_Status_Cd, 1) = 1 AND Dpd BETWEEN 61 AND 90)
            OR (p_bucket = 'npa_90_plus' AND IFNULL(Ln_Status_Cd, 1) = 1 AND Dpd > 90)
        );
    END IF;

    SELECT COUNT(*) INTO v_total FROM tmp_loan_facts;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        la.Application_Id,
        ap.Application_No,
        ap.Cust_Type_Cd,
        FN_LOAN_OPT_DESC(34, ap.Cust_Type_Cd) AS Cust_Type_Desc,
        IF(ap.Cust_Type_Cd = 1, NULL, ap.Cust_Id_Primay) AS Member_Id,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        pm.Ref_Code AS Member_Ref_Code,
        pm.Mobile_No,
        IF(ap.Cust_Type_Cd = 1, ap.Cust_Id_Primay,
           (SELECT mg.Group_Id FROM mst_member_group mg WHERE mg.Member_Id = ap.Cust_Id_Primay AND mg.Is_Active = 1
            ORDER BY mg.Mem_Group_Id DESC LIMIT 1)) AS Group_Id,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name,
           (SELECT g2.Group_Name FROM mst_member_group mg JOIN mst_group g2 ON g2.Group_Id = mg.Group_Id
            WHERE mg.Member_Id = ap.Cust_Id_Primay AND mg.Is_Active = 1 ORDER BY mg.Mem_Group_Id DESC LIMIT 1)) AS Group_Name,
        IFNULL(pg.Center_Id, pm.Center_Id) AS Center_Id,
        ct.Center_Name,
        ap.Scheme_Id,
        s.Scheme_Name,
        la.Loan_Date,
        la.Loan_Amount,
        la.Interest_Rate,
        la.Disbursed_Amount,
        f.Outstanding AS Principal_Outstanding,
        f.Collected_Total AS Total_Collected,
        f.Paid_P AS Principal_Collected,
        f.Paid_I AS Interest_Collected,
        f.Inst_Amount AS Installment_Amount,
        f.Tenure,
        f.Paid_Inst AS Paid_Installments,
        f.Next_Due_Date,
        f.Next_Due_Amount,
        f.Due_P AS Principal_Due,
        f.Due_I AS Interest_Due,
        f.Od_P AS Overdue_Principal,
        f.Od_I AS Overdue_Interest,
        (f.Od_P + f.Od_I) AS Overdue_Amount,
        f.Od_Installments AS Overdue_Installments,
        f.Penalty_Due,
        f.Oldest_Unpaid AS Oldest_Due_Date,
        f.Dpd,
        f.Bucket,
        IFNULL(la.Is_Defaulter, 0) AS Is_Defaulter,
        IFNULL(la.Is_NPA, 0) AS Is_NPA,
        la.Final_Due_Date,
        la.Ln_Status_Cd,
        FN_LOAN_OPT_DESC(40, la.Ln_Status_Cd) AS Ln_Status_Desc,
        ap.Branch_Id,
        b.Branch_Name,
        ap.FO_Id,
        fo.Full_Name AS FO_Name
    FROM tmp_loan_facts f
    JOIN mst_loan_account la ON la.Loan_Account_Id = f.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_center ct ON ct.Center_Id = IFNULL(pg.Center_Id, pm.Center_Id)
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = ap.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
    ORDER BY la.Loan_Date DESC, la.Loan_Account_Id DESC
    LIMIT v_per_page OFFSET v_offset;

    SELECT
        COUNT(*) AS Total_Count,
        IFNULL(SUM(IF(IFNULL(Ln_Status_Cd, 1) = 1, 1, 0)), 0) AS Active_Count,
        IFNULL(SUM(IF(IFNULL(Ln_Status_Cd, 1) = 1, Outstanding, 0)), 0) AS Total_Outstanding,
        IFNULL(SUM(IF(IFNULL(Ln_Status_Cd, 1) = 1, Od_P + Od_I, 0)), 0) AS Total_Overdue,
        IFNULL(SUM(IF(Bucket = 'par', 1, 0)), 0) AS Par_Count,
        IFNULL(SUM(IF(Bucket IN ('par', 'npa'), Outstanding, 0)), 0) AS Par_Amount,
        IFNULL(SUM(IF(Bucket = 'npa', 1, 0)), 0) AS Npa_Count,
        IFNULL(SUM(IF(Bucket = 'npa', Outstanding, 0)), 0) AS Npa_Amount,
        IFNULL(SUM(IF(Bucket = 'current', 1, 0)), 0) AS Current_Count,
        IFNULL(SUM(IF(Bucket = 'closed', 1, 0)), 0) AS Closed_Count
    FROM tmp_loan_facts;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
