DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_BORROWER_LOOKUP`(
    IN p_keyword VARCHAR(150),
    IN p_branch_id INT,
    IN p_group_id INT,
    IN p_center_id INT,
    IN p_cust_type_cd INT,
    IN p_eligible_only TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;
    SET p_eligible_only = IFNULL(p_eligible_only, 1);

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_borrower;
    CREATE TEMPORARY TABLE tmp_loan_borrower (
        Member_Id INT PRIMARY KEY,
        Group_Id INT NULL,
        Kyc_Ok TINYINT NOT NULL DEFAULT 0,
        Overdue DECIMAL(14,2) NOT NULL DEFAULT 0
    );

    INSERT INTO tmp_loan_borrower (Member_Id, Group_Id, Kyc_Ok)
    SELECT m.Member_Id,
           (SELECT mg.Group_Id FROM mst_member_group mg
            WHERE mg.Member_Id = m.Member_Id AND mg.Is_Active = 1 ORDER BY mg.Mem_Group_Id DESC LIMIT 1),
           FN_LOAN_MEMBER_KYC_OK(m.Member_Id)
    FROM mst_member m
    WHERE IFNULL(m.Current_Status_Cd, 0) = 1
      AND (p_branch_id IS NULL OR m.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR m.Center_Id = p_center_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR CAST(m.Member_Code AS CHAR) = p_keyword
      );

    DELETE FROM tmp_loan_borrower
    WHERE (p_group_id IS NOT NULL AND IFNULL(Group_Id, 0) <> p_group_id)
       OR (p_cust_type_cd = 1 AND Group_Id IS NULL)
       OR (p_eligible_only = 1 AND Kyc_Ok = 0);

    UPDATE tmp_loan_borrower SET Overdue = FN_LOAN_MEMBER_OVERDUE(Member_Id, CURDATE());

    IF p_eligible_only = 1 THEN
        DELETE FROM tmp_loan_borrower WHERE Overdue > 0;
    END IF;

    SELECT COUNT(*) INTO v_total FROM tmp_loan_borrower;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        m.Member_Id,
        m.Ref_Code,
        m.Member_Name,
        m.Mobile_No,
        t.Group_Id,
        g.Group_Name,
        COALESCE(m.Center_Id, g.Center_Id) AS Center_Id,
        c.Center_Name,
        m.Branch_Id,
        b.Branch_Name,
        m.FO_Id,
        fo.Full_Name AS FO_Name,
        m.Date_of_Birth,
        m.Joining_Date,
        m.Monthly_Income,
        m.Monthly_Expense,
        m.Bank_Name,
        m.Bank_Account_No,
        m.IFSC_Code,
        (SELECT COUNT(*) FROM mst_loan_account la
         JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
         WHERE la.Ln_Status_Cd = 1
           AND ((ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = m.Member_Id)
                OR EXISTS (SELECT 1 FROM mst_loan_application_bulk lb WHERE lb.Loan_Application_Id = ap.Application_Id AND lb.Customer_Id = m.Member_Id))
        ) AS Active_Loan_Count,
        (SELECT COUNT(*) + 1 FROM mst_loan_account la
         JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
         WHERE (ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = m.Member_Id)
            OR EXISTS (SELECT 1 FROM mst_loan_application_bulk lb WHERE lb.Loan_Application_Id = ap.Application_Id AND lb.Customer_Id = m.Member_Id)
        ) AS Loan_Cycle,
        (SELECT ap.Application_No FROM mst_loan_application ap
         WHERE ap.Appl_Status_Cd IN (1, 4)
           AND NOT EXISTS (SELECT 1 FROM mst_loan_account la WHERE la.Application_Id = ap.Application_Id)
           AND ((ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = m.Member_Id)
                OR EXISTS (SELECT 1 FROM mst_loan_application_bulk lb WHERE lb.Loan_Application_Id = ap.Application_Id AND lb.Customer_Id = m.Member_Id))
         ORDER BY ap.Application_Id DESC LIMIT 1
        ) AS Pending_Application_No,
        t.Overdue AS Overdue_Amount,
        t.Kyc_Ok AS Kyc_Verified
    FROM tmp_loan_borrower t
    JOIN mst_member m ON m.Member_Id = t.Member_Id
    LEFT JOIN mst_group g ON g.Group_Id = t.Group_Id
    LEFT JOIN mst_center c ON c.Center_Id = COALESCE(m.Center_Id, g.Center_Id)
    LEFT JOIN mst_staff fo ON fo.Staff_Id = m.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = m.Branch_Id
    ORDER BY m.Member_Name, m.Member_Id
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_CHARGES_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_CHARGES_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_charge_id INT,
    IN p_charge_name VARCHAR(100),
    IN p_charge_rate DECIMAL(8,2),
    IN p_figure_cd TINYINT,
    IN p_max_amount DECIMAL(8,2),
    IN p_tax_prcent DECIMAL(5,2),
    IN p_deduct_during_cd TINYINT,
    IN p_charges_gl INT,
    IN p_is_refundable TINYINT,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_action VARCHAR(10);
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_active TINYINT DEFAULT 1;
    DECLARE v_current TINYINT DEFAULT NULL;
    DECLARE v_refundable TINYINT DEFAULT 0;
    DECLARE v_cur_refundable TINYINT DEFAULT 0;
    DECLARE v_name VARCHAR(100);
    DECLARE v_new_id INT DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_name = TRIM(IFNULL(p_charge_name, ''));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Invalid action. Use ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_loan_charges WHERE Charge_Id = p_charge_id;
        IF p_charge_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan charge not found';
        ELSE
            SELECT IFNULL(Is_Active, 0), IFNULL(Is_Refundable, 0) INTO v_current, v_cur_refundable
            FROM mst_loan_charges WHERE Charge_Id = p_charge_id;

            SET v_active = IF(p_is_active IS NULL, v_current, IF(p_is_active = 1, 1, 0));
            SET v_refundable = IFNULL(p_is_refundable, v_cur_refundable);
        END IF;
    ELSE
        SET v_active = IF(IFNULL(p_is_active, 1) = 1, 1, 0);
        SET v_refundable = IFNULL(p_is_refundable, 0);
    END IF;

    IF v_err IS NULL AND v_refundable NOT IN (0, 1) THEN
        SET v_err = 'Is refundable must be 1 (yes) or 0 (no)';
    END IF;

    IF v_err IS NULL AND v_name = '' THEN
        SET v_err = 'Charge name is required';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_loan_charges
        WHERE LOWER(TRIM(Charge_Name)) = LOWER(v_name)
          AND (v_action = 'ADD' OR Charge_Id <> p_charge_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Charge name already exists';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 16 AND Opt_Code = p_figure_cd AND Is_Active = 1;
        IF p_figure_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid figure type';
        END IF;
    END IF;

    IF v_err IS NULL AND (p_charge_rate IS NULL OR p_charge_rate < 0) THEN
        SET v_err = 'Charge rate is required and cannot be negative';
    END IF;

    IF v_err IS NULL AND p_figure_cd = 2 AND p_charge_rate > 100 THEN
        SET v_err = 'Charge percentage cannot exceed 100';
    END IF;

    IF v_err IS NULL AND p_max_amount IS NOT NULL AND p_max_amount < 0 THEN
        SET v_err = 'Max amount cannot be negative';
    END IF;

    IF v_err IS NULL AND p_figure_cd = 1 AND p_max_amount IS NOT NULL AND p_max_amount < p_charge_rate THEN
        SET v_err = 'Max amount cannot be less than the fixed charge rate';
    END IF;

    IF v_err IS NULL AND p_tax_prcent IS NOT NULL AND (p_tax_prcent < 0 OR p_tax_prcent > 100) THEN
        SET v_err = 'Tax percent must be between 0 and 100';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 23 AND Opt_Code = p_deduct_during_cd AND Is_Active = 1;
        IF p_deduct_during_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid deduct during';
        END IF;
    END IF;

    IF v_err IS NULL AND p_charges_gl IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_acct_ledger WHERE Ledger_Id = p_charges_gl;
        IF v_cnt = 0 THEN
            SET v_err = 'Charges ledger not found';
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' AND v_current = 1 AND v_active = 0 THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_loan_scheme_charges
        WHERE Charge_Id = p_charge_id AND IFNULL(Is_Active, 0) = 1;
        IF v_cnt > 0 THEN
            SET v_err = 'Loan charge is linked to an active loan scheme and cannot be deactivated';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, IF(v_action = 'EDIT', p_charge_id, NULL) AS charge_id, v_err AS message;

    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_charges (
            Charge_Name, Charge_Rate, Figure_Cd, Max_Amount, Tax_Prcent,
            Deduct_During_Cd, Charges_Gl, Is_Refundable, Is_Active, Created_By, Created_At
        ) VALUES (
            v_name, p_charge_rate, p_figure_cd, p_max_amount, IFNULL(p_tax_prcent, 0),
            p_deduct_during_cd, p_charges_gl, v_refundable, v_active, p_user_id, NOW()
        );

        SET v_new_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_new_id AS charge_id, 'Loan charge created successfully' AS message;

    ELSE
        UPDATE mst_loan_charges
        SET Charge_Name = v_name,
            Charge_Rate = p_charge_rate,
            Figure_Cd = p_figure_cd,
            Max_Amount = p_max_amount,
            Tax_Prcent = IFNULL(p_tax_prcent, 0),
            Deduct_During_Cd = p_deduct_during_cd,
            Charges_Gl = p_charges_gl,
            Is_Refundable = v_refundable,
            Is_Active = v_active
        WHERE Charge_Id = p_charge_id;

        SELECT 'SUCCESS' AS status, p_charge_id AS charge_id, 'Loan charge updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_CHARGES_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_CHARGES_LIST`(
    IN p_charge_id INT,
    IN p_keyword VARCHAR(100),
    IN p_figure_cd TINYINT,
    IN p_deduct_during_cd TINYINT,
    IN p_is_refundable TINYINT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_loan_charges c
    WHERE (p_charge_id IS NULL OR c.Charge_Id = p_charge_id)
      AND (p_keyword IS NULL OR p_keyword = '' OR c.Charge_Name LIKE CONCAT('%', p_keyword, '%'))
      AND (p_figure_cd IS NULL OR c.Figure_Cd = p_figure_cd)
      AND (p_deduct_during_cd IS NULL OR c.Deduct_During_Cd = p_deduct_during_cd)
      AND (p_is_refundable IS NULL OR IFNULL(c.Is_Refundable, 0) = p_is_refundable)
      AND (p_is_active IS NULL OR IFNULL(c.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        c.Charge_Id,
        c.Charge_Name,
        c.Charge_Rate,
        c.Figure_Cd,
        fg.Opt_Description AS Figure_Desc,
        c.Max_Amount,
        c.Tax_Prcent,
        c.Deduct_During_Cd,
        dd.Opt_Description AS Deduct_During_Desc,
        c.Charges_Gl,
        l.Ledger_Code AS Charges_Gl_Code,
        l.Ledger_Name AS Charges_Gl_Name,
        IFNULL(c.Is_Refundable, 0) AS Is_Refundable,
        IFNULL(c.Is_Active, 0) AS Is_Active,
        c.Created_By,
        c.Created_At
    FROM mst_loan_charges c
    LEFT JOIN mst_appl_options fg ON fg.Opt_Grp_Id = 16 AND fg.Opt_Code = c.Figure_Cd
    LEFT JOIN mst_appl_options dd ON dd.Opt_Grp_Id = 23 AND dd.Opt_Code = c.Deduct_During_Cd
    LEFT JOIN mst_acct_ledger l ON l.Ledger_Id = c.Charges_Gl
    WHERE (p_charge_id IS NULL OR c.Charge_Id = p_charge_id)
      AND (p_keyword IS NULL OR p_keyword = '' OR c.Charge_Name LIKE CONCAT('%', p_keyword, '%'))
      AND (p_figure_cd IS NULL OR c.Figure_Cd = p_figure_cd)
      AND (p_deduct_during_cd IS NULL OR c.Deduct_During_Cd = p_deduct_during_cd)
      AND (p_is_refundable IS NULL OR IFNULL(c.Is_Refundable, 0) = p_is_refundable)
      AND (p_is_active IS NULL OR IFNULL(c.Is_Active, 0) = p_is_active)
    ORDER BY c.Charge_Name ASC, c.Charge_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_CHARGES_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_CHARGES_STATUS`(
    IN p_charge_id INT,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current TINYINT DEFAULT NULL;

    SELECT COUNT(*) INTO v_cnt FROM mst_loan_charges WHERE Charge_Id = p_charge_id;

    IF p_charge_id IS NULL OR v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_charge_id AS charge_id, NULL AS is_active, 'Loan charge not found' AS message;
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_charge_id AS charge_id, NULL AS is_active,
               'Status must be 1 (active) or 0 (inactive)' AS message;
    ELSE
        SELECT IFNULL(Is_Active, 0) INTO v_current
        FROM mst_loan_charges
        WHERE Charge_Id = p_charge_id;

        IF v_current = p_is_active THEN
            SELECT 'SUCCESS' AS status, p_charge_id AS charge_id, v_current AS is_active,
                   IF(p_is_active = 1, 'Loan charge is already active', 'Loan charge is already inactive') AS message;
        ELSE
            SET v_cnt = 0;

            IF p_is_active = 0 THEN
                SELECT COUNT(*) INTO v_cnt
                FROM mst_loan_scheme_charges
                WHERE Charge_Id = p_charge_id AND IFNULL(Is_Active, 0) = 1;
            END IF;

            IF v_cnt > 0 THEN
                SELECT 'ERROR' AS status, p_charge_id AS charge_id, v_current AS is_active,
                       'Loan charge is linked to an active loan scheme and cannot be deactivated' AS message;
            ELSE
                UPDATE mst_loan_charges SET Is_Active = p_is_active WHERE Charge_Id = p_charge_id;

                SELECT 'SUCCESS' AS status, p_charge_id AS charge_id, p_is_active AS is_active,
                       IF(p_is_active = 1, 'Loan charge activated successfully', 'Loan charge deactivated successfully') AS message;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_CLOSURE_ADD` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_CLOSURE_ADD`(
    IN p_loan_account_id BIGINT,
    IN p_closure_date DATE,
    IN p_settlement DECIMAL(14,2),
    IN p_payment_mode_cd INT,
    IN p_trans_ref_no VARCHAR(25),
    IN p_release_freeze TINYINT,
    IN p_release_mortgage TINYINT,
    IN p_remarks VARCHAR(250),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_app BIGINT;
    DECLARE v_branch INT;
    DECLARE v_last DATE;
    DECLARE v_outs DECIMAL(14,2) DEFAULT 0;
    DECLARE v_idue DECIMAL(14,2) DEFAULT 0;
    DECLARE v_acc DECIMAL(14,2) DEFAULT 0;
    DECLARE v_pen DECIMAL(14,2) DEFAULT 0;
    DECLARE v_chg DECIMAL(14,2) DEFAULT 0;
    DECLARE v_set DECIMAL(14,2) DEFAULT 0;
    DECLARE v_no VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_id BIGINT DEFAULT NULL;
    DECLARE v_vid BIGINT;
    DECLARE v_vno VARCHAR(25);
    DECLARE v_note VARCHAR(255);
    DECLARE v_fr INT DEFAULT 0;
    DECLARE v_mg INT DEFAULT 0;
    DECLARE v_gu INT DEFAULT 0;
    DECLARE v_reason VARCHAR(100);

    SET p_closure_date = IFNULL(p_closure_date, CURDATE());

    SELECT COUNT(*), MAX(la.Ln_Status_Cd), MAX(la.Application_Id), MAX(ap.Branch_Id)
    INTO v_cnt, v_status, v_app, v_branch
    FROM mst_loan_account la JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE la.Loan_Account_Id = p_loan_account_id FOR UPDATE;

    SELECT MAX(IFNULL(Effect_Date, DATE(Collection_Date))) INTO v_last
    FROM trans_loan_collection WHERE Account_Id = p_loan_account_id AND Tr_Status_Cd = 2;

    IF p_loan_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Loan account not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Loan account is not active';
    ELSEIF EXISTS (SELECT 1 FROM trans_loan_collection WHERE Account_Id = p_loan_account_id AND Tr_Status_Cd = 1) THEN
        SET v_err = 'A collection on this loan is waiting for approval';
    ELSEIF EXISTS (SELECT 1 FROM mst_loan_account_disbursement WHERE Loan_Account_Id = p_loan_account_id AND Approved_By IS NULL) THEN
        SET v_err = 'A disbursement on this loan is waiting for approval';
    ELSEIF p_closure_date > CURDATE() THEN
        SET v_err = 'Closure date cannot be in the future';
    ELSEIF v_last IS NOT NULL AND p_closure_date < v_last THEN
        SET v_err = 'Closure date cannot be before the last collection';
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_CLOSURE_CALC(p_loan_account_id, p_closure_date, v_outs, v_idue, v_acc, v_pen, v_chg, v_set);

        IF p_settlement IS NULL OR ABS(p_settlement - v_set) > 0.01 THEN
            SET v_err = CONCAT('Settlement amount must be ', FORMAT(v_set, 2), ' as on ', DATE_FORMAT(p_closure_date, '%d-%m-%Y'));
        ELSEIF v_set > 0 AND (p_payment_mode_cd IS NULL OR p_payment_mode_cd NOT IN (1, 2, 3)) THEN
            SET v_err = 'Payment mode must be 1 (Cash), 2 (Bank Cheque) or 3 (Bank Transfer)';
        ELSEIF v_set > 0 AND p_payment_mode_cd IN (2, 3) AND NULLIF(TRIM(IFNULL(p_trans_ref_no, '')), '') IS NULL THEN
            SET v_err = 'Reference / cheque number is required for bank payments';
        END IF;
    END IF;

    IF v_err IS NULL AND v_set > 0 THEN
        CALL USP_CODE_SERIES_GENERATE('loan_collection', v_no, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_no IS NULL THEN
            SET v_err = CONCAT('Receipt number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        END IF;
    END IF;

    IF v_err IS NULL AND v_set > 0 THEN
        INSERT INTO trans_loan_collection (
            Account_Id, Trans_No, Collection_Date, Effect_Date, Payment_Mode_Cd, Principal_Collected, Interest_Collected,
            Penalty_Collected, Total_Collected, Interest_Demand, Interest_Due, Interest_Capitalized, Outs_Principal,
            Trans_Ref_No, Ledger_Narration, FO_Id, Branch_Id, Voucher_Id, Tr_Status_Cd, Remarks, Created_By, Created_At
        ) VALUES (
            p_loan_account_id, LEFT(v_no, 40), NOW(), p_closure_date, p_payment_mode_cd, v_outs, v_idue + v_acc, v_pen, v_set,
            v_idue, 0, 0, 0, NULLIF(TRIM(IFNULL(p_trans_ref_no, '')), ''), 'Loan closure', NULL, v_branch, NULL, 1,
            NULLIF(TRIM(IFNULL(p_remarks, '')), ''), p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();

        CALL USP_LOAN_COLLECTION_POST(v_id, p_user_id, v_vid, v_vno, v_note, v_err);
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, NULL AS collection_id, NULL AS trans_no,
               NULL AS settlement_amount, NULL AS voucher_id, NULL AS voucher_no, NULL AS voucher_note,
               0 AS released_freezes, 0 AS released_mortgages, 0 AS released_guarantors, v_err AS message;
    ELSE
        SET v_reason = 'Loan closed';

        IF IFNULL(p_release_freeze, 1) = 1 THEN
            UPDATE mst_deposit_account_sb sb
            JOIN (SELECT Deposit_Account_Id, SUM(Freeze_Amount) AS amt FROM mst_loan_application_deposit_freeze
                  WHERE Loan_Application_Id = v_app AND Freeze_Status_Cd = 1 GROUP BY Deposit_Account_Id) f
              ON f.Deposit_Account_Id = sb.Account_Id
            SET sb.Available_Balance = sb.Available_Balance + f.amt;

            UPDATE mst_loan_application_deposit_freeze
            SET Freeze_Status_Cd = 2, Release_Date = NOW(), Release_By = p_user_id, Release_Reason = v_reason,
                Updated_By = p_user_id, Updated_At = NOW()
            WHERE Loan_Application_Id = v_app AND Freeze_Status_Cd = 1;
            SET v_fr = ROW_COUNT();
        END IF;

        IF IFNULL(p_release_mortgage, 1) = 1 THEN
            UPDATE mst_loan_application_mortgage
            SET Release_Date = CURDATE(), Released_By = p_user_id, Release_Reason = v_reason, Updated_By = p_user_id, Updated_At = NOW()
            WHERE Loan_Application_Id = v_app AND Release_Date IS NULL;
            SET v_mg = ROW_COUNT();
        END IF;

        UPDATE mst_loan_application_guarantor
        SET Release_Date = CURDATE(), Release_By = p_user_id
        WHERE Loan_Application_Id = v_app AND Release_Date IS NULL;
        SET v_gu = ROW_COUNT();

        SELECT 'SUCCESS' AS status, p_loan_account_id AS loan_account_id, v_id AS collection_id, LEFT(v_no, 40) AS trans_no,
               v_set AS settlement_amount, v_vid AS voucher_id, v_vno AS voucher_no, v_note AS voucher_note,
               v_fr AS released_freezes, v_mg AS released_mortgages, v_gu AS released_guarantors,
               'Loan settled' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_CLOSURE_CALC` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_CLOSURE_CALC`(
    IN p_acct BIGINT,
    IN p_date DATE,
    OUT p_outs DECIMAL(14,2),
    OUT p_int_due DECIMAL(14,2),
    OUT p_accrued DECIMAL(14,2),
    OUT p_penalty DECIMAL(14,2),
    OUT p_charges DECIMAL(14,2),
    OUT p_settlement DECIMAL(14,2)
)
BEGIN
    DECLARE v_rate DECIMAL(7,2) DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_from DATE;
    DECLARE v_first DATE;

    SELECT IFNULL(MAX(Principal_Outstanding), 0), IFNULL(MAX(Interest_Rate), 0), MAX(Application_Id)
    INTO p_outs, v_rate, v_app
    FROM mst_loan_account WHERE Loan_Account_Id = p_acct;

    SELECT MIN(Disbursement_Date) INTO v_first FROM mst_loan_account_disbursement
    WHERE Loan_Account_Id = p_acct AND Approved_By IS NOT NULL;

    SELECT MAX(Due_Date) INTO v_from FROM trans_loanac_schedule
    WHERE Loan_Account_Id = p_acct AND IFNULL(Is_Active, 1) = 1 AND Due_Date <= p_date;
    SET v_from = GREATEST(IFNULL(v_from, v_first), IFNULL(v_first, v_from));

    SET p_int_due = GREATEST(0, FN_LOAN_DEMAND(p_acct, p_date, 'I') - FN_LOAN_PAID(p_acct, NULL, 'I'));
    SET p_accrued = IF(v_from IS NULL OR v_from >= p_date, 0, ROUND(p_outs * v_rate / 100 * DATEDIFF(p_date, v_from) / 365, 2));
    SET p_penalty = FN_LOAN_PENALTY_DUE(p_acct, p_date);

    SELECT IFNULL(SUM(Total_Charge - IFNULL(Waived_Amount, 0)), 0) INTO p_charges
    FROM mst_loan_application_charge WHERE Loan_Application_Id = v_app AND Tr_Status_Cd = 1;

    SET p_settlement = p_outs + p_int_due + p_accrued + p_penalty + p_charges;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_CLOSURE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_CLOSURE_LIST`(
    IN p_loan_account_id BIGINT,
    IN p_status VARCHAR(20),
    IN p_branch_id INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    CALL USP_LOAN_FACTS_RESET();

    INSERT INTO tmp_loan_facts (Loan_Account_Id)
    SELECT la.Loan_Account_Id
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE la.Ln_Status_Cd IN (1, 2) AND la.Disbursed_Amount > 0
      AND (p_loan_account_id IS NULL OR la.Loan_Account_Id = p_loan_account_id)
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));

    CALL USP_LOAN_FACTS_FILL(CURDATE());

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_closure_rows;
    CREATE TEMPORARY TABLE tmp_loan_closure_rows (
        Loan_Account_Id BIGINT PRIMARY KEY,
        Status VARCHAR(20),
        Closure_Date DATE NULL,
        Settlement_Amount DECIMAL(14,2) NULL,
        Pending_Dues DECIMAL(14,2) NOT NULL DEFAULT 0,
        Outstanding DECIMAL(14,2) NOT NULL DEFAULT 0
    );

    INSERT INTO tmp_loan_closure_rows (Loan_Account_Id, Status, Pending_Dues, Outstanding)
    SELECT f.Loan_Account_Id,
           CASE WHEN f.Ln_Status_Cd = 2 THEN 'closed'
                WHEN f.Due_P + f.Due_I + f.Penalty_Due > 0 THEN 'pending_dues'
                ELSE 'open' END,
           IF(f.Ln_Status_Cd = 2, 0, f.Due_P + f.Due_I + f.Penalty_Due),
           IF(f.Ln_Status_Cd = 2, 0, f.Outstanding)
    FROM tmp_loan_facts f;

    UPDATE tmp_loan_closure_rows r
    JOIN (SELECT c.Account_Id, MAX(IFNULL(c.Effect_Date, DATE(c.Collection_Date))) AS d,
                 SUBSTRING_INDEX(GROUP_CONCAT(c.Total_Collected ORDER BY c.Collection_Id DESC), ',', 1) AS amt
          FROM trans_loan_collection c
          WHERE c.Tr_Status_Cd = 2 AND c.Ledger_Narration LIKE 'Loan closure%'
          GROUP BY c.Account_Id) x ON x.Account_Id = r.Loan_Account_Id
    SET r.Closure_Date = x.d, r.Settlement_Amount = x.amt
    WHERE r.Status = 'closed';

    DELETE FROM tmp_loan_closure_rows
    WHERE (p_status IS NOT NULL AND p_status <> '' AND Status <> p_status)
       OR (p_from_date IS NOT NULL AND (Closure_Date IS NULL OR Closure_Date < p_from_date))
       OR (p_to_date IS NOT NULL AND (Closure_Date IS NULL OR Closure_Date > p_to_date));

    SELECT COUNT(*) INTO v_total FROM tmp_loan_closure_rows;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        s.Scheme_Name,
        la.Loan_Amount,
        la.Disbursed_Amount,
        r.Outstanding AS Principal_Outstanding,
        r.Pending_Dues,
        r.Closure_Date,
        r.Settlement_Amount,
        la.Final_Due_Date,
        r.Status,
        CASE r.Status WHEN 'closed' THEN 'Closed' WHEN 'pending_dues' THEN 'Pending dues' ELSE 'Open' END AS Status_Desc,
        la.Ln_Status_Cd,
        FN_LOAN_OPT_DESC(40, la.Ln_Status_Cd) AS Ln_Status_Desc,
        ap.Branch_Id,
        b.Branch_Name
    FROM tmp_loan_closure_rows r
    JOIN mst_loan_account la ON la.Loan_Account_Id = r.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
    ORDER BY IFNULL(r.Closure_Date, la.Final_Due_Date) DESC, la.Loan_Account_Id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_CLOSURE_PREVIEW` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_CLOSURE_PREVIEW`(IN p_loan_account_id BIGINT, IN p_closure_date DATE)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_app BIGINT;
    DECLARE v_outs DECIMAL(14,2) DEFAULT 0;
    DECLARE v_idue DECIMAL(14,2) DEFAULT 0;
    DECLARE v_acc DECIMAL(14,2) DEFAULT 0;
    DECLARE v_pen DECIMAL(14,2) DEFAULT 0;
    DECLARE v_chg DECIMAL(14,2) DEFAULT 0;
    DECLARE v_set DECIMAL(14,2) DEFAULT 0;
    DECLARE v_pend_c INT DEFAULT 0;
    DECLARE v_pend_d INT DEFAULT 0;

    SET p_closure_date = IFNULL(p_closure_date, CURDATE());

    SELECT COUNT(*), MAX(Ln_Status_Cd), MAX(Application_Id) INTO v_cnt, v_status, v_app
    FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id;

    SELECT COUNT(*) INTO v_pend_c FROM trans_loan_collection WHERE Account_Id = p_loan_account_id AND Tr_Status_Cd = 1;
    SELECT COUNT(*) INTO v_pend_d FROM mst_loan_account_disbursement WHERE Loan_Account_Id = p_loan_account_id AND Approved_By IS NULL;

    IF v_cnt = 0 THEN
        SET v_err = 'Loan account not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Loan account is not active';
    ELSEIF p_closure_date > CURDATE() THEN
        SET v_err = 'Closure date cannot be in the future';
    ELSE
        CALL USP_LOAN_CLOSURE_CALC(p_loan_account_id, p_closure_date, v_outs, v_idue, v_acc, v_pen, v_chg, v_set);
    END IF;

    SELECT
        IF(v_err IS NULL, 'SUCCESS', 'ERROR') AS status,
        IFNULL(v_err, CASE
            WHEN v_pend_c > 0 THEN 'A collection is waiting for approval; approve or reject it before closure'
            WHEN v_pend_d > 0 THEN 'A disbursement is waiting for approval; approve or reject it before closure'
            ELSE 'Closure preview generated' END) AS message,
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        p_closure_date AS Closure_Date,
        v_outs AS Principal_Outstanding,
        v_idue AS Interest_Due,
        v_acc AS Interest_Accrued,
        (v_idue + v_acc) AS Interest_Till_Date,
        v_pen AS Penalty_Due,
        v_chg AS Pending_Charges,
        0 AS Rebate,
        v_set AS Settlement_Amount,
        IF(v_err IS NULL AND v_pend_c = 0 AND v_pend_d = 0, 1, 0) AS Can_Close
    FROM (SELECT 1) d
    LEFT JOIN mst_loan_account la ON la.Loan_Account_Id = p_loan_account_id
    LEFT JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay;

    SELECT f.Freeze_Id, f.Freeze_Reference_No, f.Deposit_Account_Id, sb.Ref_AcNo AS Deposit_Account_No, f.Freeze_Type_Cd,
           FN_LOAN_OPT_DESC(42, f.Freeze_Type_Cd) AS Freeze_Type_Desc, f.Freeze_Amount, f.Freeze_Date
    FROM mst_loan_application_deposit_freeze f
    LEFT JOIN mst_deposit_account_sb sb ON sb.Account_Id = f.Deposit_Account_Id
    WHERE f.Loan_Application_Id = v_app AND f.Freeze_Status_Cd = 1
    ORDER BY f.Freeze_Id;

    SELECT m.Mortgage_Id, m.Mortgage_No, m.Collateral_Type_Cd, FN_LOAN_OPT_DESC(44, m.Collateral_Type_Cd) AS Collateral_Type_Desc,
           m.Mortgage_Description, m.Market_Value
    FROM mst_loan_application_mortgage m
    WHERE m.Loan_Application_Id = v_app AND m.Release_Date IS NULL
    ORDER BY m.Mortgage_Id;

    SELECT g.Loan_Guarantor_Id, g.Guarantor_Id, mm.Member_Name AS Guarantor_Name, g.Guarantee_Amount
    FROM mst_loan_application_guarantor g
    LEFT JOIN mst_member mm ON mm.Member_Id = g.Guarantor_Id
    WHERE g.Loan_Application_Id = v_app AND g.Release_Date IS NULL
    ORDER BY g.Loan_Guarantor_Id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_ADD` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_ADD`(
    IN p_loan_account_id BIGINT,
    IN p_collection_date DATETIME,
    IN p_effect_date DATE,
    IN p_payment_mode_cd INT,
    IN p_total DECIMAL(14,2),
    IN p_trans_ref_no VARCHAR(25),
    IN p_fo_id INT,
    IN p_is_advance TINYINT,
    IN p_remarks VARCHAR(250),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_disb DECIMAL(14,2) DEFAULT 0;
    DECLARE v_outs DECIMAL(14,2) DEFAULT 0;
    DECLARE v_branch INT;
    DECLARE v_first DATE;
    DECLARE v_p DECIMAL(14,2) DEFAULT 0;
    DECLARE v_i DECIMAL(14,2) DEFAULT 0;
    DECLARE v_n DECIMAL(14,2) DEFAULT 0;
    DECLARE v_idem DECIMAL(14,2) DEFAULT 0;
    DECLARE v_pending INT DEFAULT 0;
    DECLARE v_no VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_id BIGINT;
    DECLARE v_vid BIGINT;
    DECLARE v_vno VARCHAR(25);
    DECLARE v_note VARCHAR(255);
    DECLARE v_narr VARCHAR(75);
    DECLARE v_od DATE;

    SET p_collection_date = IFNULL(p_collection_date, NOW());
    SET p_effect_date = IFNULL(p_effect_date, DATE(p_collection_date));

    SELECT COUNT(*), MAX(la.Ln_Status_Cd), IFNULL(MAX(la.Disbursed_Amount), 0), IFNULL(MAX(la.Principal_Outstanding), 0), MAX(ap.Branch_Id)
    INTO v_cnt, v_status, v_disb, v_outs, v_branch
    FROM mst_loan_account la JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE la.Loan_Account_Id = p_loan_account_id FOR UPDATE;

    SELECT MIN(Disbursement_Date) INTO v_first FROM mst_loan_account_disbursement
    WHERE Loan_Account_Id = p_loan_account_id AND Approved_By IS NOT NULL;

    IF p_loan_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Loan account not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Loan account is not active';
    ELSEIF v_disb <= 0 OR v_first IS NULL THEN
        SET v_err = 'Loan is not disbursed yet';
    ELSEIF EXISTS (SELECT 1 FROM trans_loan_collection WHERE Account_Id = p_loan_account_id AND Tr_Status_Cd = 1) THEN
        SET v_err = 'A collection on this loan is waiting for approval';
    ELSEIF p_payment_mode_cd IS NULL OR p_payment_mode_cd NOT IN (1, 2, 3) THEN
        SET v_err = 'Payment mode must be 1 (Cash), 2 (Bank Cheque) or 3 (Bank Transfer)';
    ELSEIF p_payment_mode_cd IN (2, 3) AND NULLIF(TRIM(IFNULL(p_trans_ref_no, '')), '') IS NULL THEN
        SET v_err = 'Reference / cheque number is required for bank payments';
    ELSEIF p_collection_date > NOW() THEN
        SET v_err = 'Collection date cannot be in the future';
    ELSEIF p_effect_date > CURDATE() THEN
        SET v_err = 'Effect date cannot be in the future';
    ELSEIF p_effect_date < v_first THEN
        SET v_err = 'Effect date cannot be before the first disbursement';
    ELSEIF p_fo_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mst_staff WHERE Staff_Id = p_fo_id AND IFNULL(Status, 0) = 1) THEN
        SET v_err = 'Active field officer not found';
    ELSEIF p_total IS NULL OR p_total <= 0 THEN
        SET v_err = 'Collection amount must be greater than zero';
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_COLLECTION_SPLIT(p_loan_account_id, p_effect_date, p_total, p_is_advance, v_p, v_i, v_n, v_idem, v_err);
    END IF;

    IF v_err IS NULL THEN
        CALL USP_CODE_SERIES_GENERATE('loan_collection', v_no, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_no IS NULL THEN
            SET v_err = CONCAT('Receipt number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_pending = FN_LOAN_MC_PENDING(1, p_total, p_user_id);
        SET v_od = FN_LOAN_OLDEST_UNPAID(p_loan_account_id, p_effect_date);
        SET v_narr = CASE
            WHEN IFNULL(p_is_advance, 0) = 1 THEN 'Advance collection'
            WHEN v_od IS NOT NULL AND v_od < p_effect_date THEN 'Overdue collection'
            ELSE 'Installment collection'
        END;

        INSERT INTO trans_loan_collection (
            Account_Id, Trans_No, Collection_Date, Effect_Date, Payment_Mode_Cd, Principal_Collected, Interest_Collected,
            Penalty_Collected, Total_Collected, Interest_Demand, Interest_Due, Interest_Capitalized, Outs_Principal,
            Trans_Ref_No, Ledger_Narration, FO_Id, Branch_Id, Voucher_Id, Tr_Status_Cd, Remarks, Created_By, Created_At
        ) VALUES (
            p_loan_account_id, LEFT(v_no, 40), p_collection_date, p_effect_date, p_payment_mode_cd, v_p, v_i, v_n, p_total,
            v_idem, GREATEST(0, v_idem - v_i), 0, v_outs - v_p, NULLIF(TRIM(IFNULL(p_trans_ref_no, '')), ''), v_narr,
            p_fo_id, v_branch, NULL, 1, NULLIF(TRIM(IFNULL(p_remarks, '')), ''), p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();

        IF v_pending = 0 THEN
            CALL USP_LOAN_COLLECTION_POST(v_id, p_user_id, v_vid, v_vno, v_note, v_err);
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS collection_id, NULL AS trans_no, NULL AS tr_status_cd, NULL AS principal_collected,
               NULL AS interest_collected, NULL AS penalty_collected, NULL AS total_collected, NULL AS outs_principal,
               NULL AS voucher_id, NULL AS voucher_no, NULL AS voucher_note, v_err AS message;
    ELSE
        SELECT 'SUCCESS' AS status, v_id AS collection_id, LEFT(v_no, 40) AS trans_no, IF(v_pending = 1, 1, 2) AS tr_status_cd,
               v_p AS principal_collected, v_i AS interest_collected, v_n AS penalty_collected, p_total AS total_collected,
               v_outs - v_p AS outs_principal, v_vid AS voucher_id, v_vno AS voucher_no, v_note AS voucher_note,
               IF(v_pending = 1, 'Collection saved and sent for approval', 'Collection posted') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_APPROVE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_APPROVE`(
    IN p_collection_id BIGINT,
    IN p_approve TINYINT,
    IN p_remarks VARCHAR(250),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_maker INT;
    DECLARE v_acct BIGINT;
    DECLARE v_ln_status INT;
    DECLARE v_vid BIGINT;
    DECLARE v_vno VARCHAR(25);
    DECLARE v_note VARCHAR(255);
    DECLARE v_note_txt VARCHAR(250);

    SET v_note_txt = NULLIF(TRIM(IFNULL(p_remarks, '')), '');

    SELECT COUNT(*), MAX(Tr_Status_Cd), MAX(Created_By), MAX(Account_Id) INTO v_cnt, v_status, v_maker, v_acct
    FROM trans_loan_collection WHERE Collection_Id = p_collection_id FOR UPDATE;
    SELECT MAX(Ln_Status_Cd) INTO v_ln_status FROM mst_loan_account WHERE Loan_Account_Id = v_acct;

    IF p_collection_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Collection not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Only pending collections can be approved or rejected';
    ELSEIF p_approve IS NULL OR p_approve NOT IN (0, 1) THEN
        SET v_err = 'Approve must be 1 (approve) or 0 (reject)';
    ELSEIF p_approve = 0 AND v_note_txt IS NULL THEN
        SET v_err = 'Rejection reason is required';
    ELSEIF p_approve = 1 AND v_ln_status <> 1 THEN
        SET v_err = 'Loan account is not active; reject this collection instead';
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_MC_CHECKER(1, v_maker, p_user_id, v_err);
    END IF;

    IF v_err IS NULL AND p_approve = 1 THEN
        CALL USP_LOAN_COLLECTION_POST(p_collection_id, p_user_id, v_vid, v_vno, v_note, v_err);
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_collection_id AS collection_id, v_status AS tr_status_cd, NULL AS voucher_id,
               NULL AS voucher_no, NULL AS voucher_note, v_err AS message;
    ELSEIF p_approve = 1 THEN
        SELECT 'SUCCESS' AS status, p_collection_id AS collection_id, 2 AS tr_status_cd, v_vid AS voucher_id,
               v_vno AS voucher_no, v_note AS voucher_note, 'Collection approved' AS message;
    ELSE
        UPDATE trans_loan_collection
        SET Tr_Status_Cd = 3, Remarks = LEFT(CONCAT_WS(' | ', Remarks, CONCAT('Rejected: ', v_note_txt)), 250)
        WHERE Collection_Id = p_collection_id;
        SELECT 'SUCCESS' AS status, p_collection_id AS collection_id, 3 AS tr_status_cd, NULL AS voucher_id,
               NULL AS voucher_no, NULL AS voucher_note, 'Collection rejected' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_BULK_FINALIZE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_BULK_FINALIZE`(IN p_collection_id BIGINT)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_t DECIMAL(14,2);
    DECLARE v_p DECIMAL(14,2);
    DECLARE v_i DECIMAL(14,2);
    DECLARE v_n DECIMAL(14,2);
    DECLARE v_idem DECIMAL(14,2);
    DECLARE v_idue DECIMAL(14,2);
    DECLARE v_outs DECIMAL(14,2);
    DECLARE v_app BIGINT;
    DECLARE v_sum DECIMAL(14,2) DEFAULT 0;
    DECLARE v_lines INT DEFAULT 0;
    DECLARE v_last BIGINT;

    SELECT MAX(c.Total_Collected), MAX(c.Principal_Collected), MAX(c.Interest_Collected), MAX(c.Penalty_Collected),
           MAX(c.Interest_Demand), MAX(c.Interest_Due), MAX(c.Outs_Principal), MAX(la.Application_Id)
    INTO v_t, v_p, v_i, v_n, v_idem, v_idue, v_outs, v_app
    FROM trans_loan_collection c JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
    WHERE c.Collection_Id = p_collection_id;

    SELECT IFNULL(SUM(Total_Amount), 0), COUNT(*), MAX(Detail_Id) INTO v_sum, v_lines, v_last
    FROM trans_loan_collection_bulk WHERE Collection_Id = p_collection_id;

    IF v_t IS NULL THEN
        SET v_err = 'Collection not found';
    ELSEIF v_lines = 0 THEN
        SET v_err = 'No member lines saved for this collection';
    ELSEIF ABS(v_sum - v_t) > 0.01 THEN
        SET v_err = CONCAT('Member amounts (', FORMAT(v_sum, 2), ') must add up to the collection total (', FORMAT(v_t, 2), ')');
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_collection_id AS collection_id, v_err AS message;
    ELSE
        DROP TEMPORARY TABLE IF EXISTS tmp_loan_bulk_share;
        CREATE TEMPORARY TABLE tmp_loan_bulk_share (Detail_Id BIGINT PRIMARY KEY, Amt_Share DECIMAL(18,10), Outs_Share DECIMAL(18,10));

        INSERT INTO tmp_loan_bulk_share
        SELECT bk.Detail_Id,
               IF(v_t > 0, bk.Total_Amount / v_t, 1 / v_lines),
               IFNULL(
                   IFNULL(NULLIF(ab.Sanction_Amount, 0), ab.Requested_Amount)
                   / NULLIF((SELECT SUM(IFNULL(NULLIF(a2.Sanction_Amount, 0), a2.Requested_Amount)) FROM mst_loan_application_bulk a2
                             WHERE a2.Loan_Application_Id = v_app), 0),
                   IF(v_t > 0, bk.Total_Amount / v_t, 1 / v_lines))
        FROM trans_loan_collection_bulk bk
        LEFT JOIN mst_loan_application_bulk ab ON ab.Loan_Application_Id = v_app AND ab.Customer_Id = bk.Customer_Id
        WHERE bk.Collection_Id = p_collection_id;

        UPDATE trans_loan_collection_bulk bk
        JOIN tmp_loan_bulk_share s ON s.Detail_Id = bk.Detail_Id
        SET bk.Principal_Amount = ROUND(v_p * s.Amt_Share, 2),
            bk.Interest_Amount = ROUND(v_i * s.Amt_Share, 2),
            bk.Penalty_Amount = ROUND(v_n * s.Amt_Share, 2),
            bk.Interest_Demand = ROUND(v_idem * s.Outs_Share, 2),
            bk.Interest_Due = ROUND(v_idue * s.Outs_Share, 2),
            bk.Principal_Outstanding = ROUND(v_outs * s.Outs_Share, 2);

        SELECT IFNULL(SUM(Principal_Amount), 0), IFNULL(SUM(Interest_Amount), 0), IFNULL(SUM(Penalty_Amount), 0)
        INTO v_sum, v_idem, v_idue
        FROM trans_loan_collection_bulk WHERE Collection_Id = p_collection_id;

        UPDATE trans_loan_collection_bulk
        SET Principal_Amount = Principal_Amount + (v_p - v_sum),
            Interest_Amount = Interest_Amount + (v_i - v_idem),
            Penalty_Amount = Penalty_Amount + (v_n - v_idue),
            Total_Amount = Total_Amount + (v_t - (SELECT s FROM (SELECT SUM(Total_Amount) AS s FROM trans_loan_collection_bulk
                                                                 WHERE Collection_Id = p_collection_id) z))
        WHERE Detail_Id = v_last;

        SELECT 'SUCCESS' AS status, p_collection_id AS collection_id, CONCAT(v_lines, ' member line(s) saved') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_BULK_MEMBER_SAVE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_BULK_MEMBER_SAVE`(
    IN p_collection_id BIGINT,
    IN p_customer_id INT,
    IN p_group_id INT,
    IN p_total DECIMAL(14,2),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_type INT;
    DECLARE v_p INT;
    DECLARE v_j1 INT;
    DECLARE v_j2 INT;
    DECLARE v_group INT;

    SELECT COUNT(*), MAX(ap.Application_Id), MAX(ap.Cust_Type_Cd), MAX(ap.Cust_Id_Primay), MAX(ap.Cust_Id_Joint1), MAX(ap.Cust_Id_Joint2)
    INTO v_cnt, v_app, v_type, v_p, v_j1, v_j2
    FROM trans_loan_collection c
    JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE c.Collection_Id = p_collection_id;

    SET v_group = IF(v_type = 1, v_p, IFNULL(p_group_id,
                     (SELECT mg.Group_Id FROM mst_member_group mg WHERE mg.Member_Id = p_customer_id AND mg.Is_Active = 1
                      ORDER BY mg.Mem_Group_Id DESC LIMIT 1)));

    IF v_cnt = 0 THEN
        SET v_err = 'Collection not found';
    ELSEIF p_total IS NULL OR p_total < 0 THEN
        SET v_err = 'Member amount cannot be negative';
    ELSEIF v_type = 1 AND NOT EXISTS (SELECT 1 FROM mst_loan_application_bulk WHERE Loan_Application_Id = v_app AND Customer_Id = p_customer_id) THEN
        SET v_err = CONCAT('Member ', IFNULL(p_customer_id, ''), ' is not on this group loan');
    ELSEIF v_type = 2 AND IFNULL(p_customer_id, 0) NOT IN (v_p, IFNULL(v_j1, 0), IFNULL(v_j2, 0)) THEN
        SET v_err = CONCAT('Member ', IFNULL(p_customer_id, ''), ' is not a borrower on this loan');
    ELSEIF EXISTS (SELECT 1 FROM trans_loan_collection_bulk WHERE Collection_Id = p_collection_id AND Customer_Id = p_customer_id) THEN
        SET v_err = CONCAT('Member ', p_customer_id, ' is listed twice for the same loan');
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS detail_id, v_err AS message;
    ELSE
        INSERT INTO trans_loan_collection_bulk (
            Collection_Id, Customer_Id, Group_Id, Principal_Amount, Interest_Amount, Penalty_Amount, Total_Amount,
            Interest_Demand, Interest_Due, Principal_Outstanding, Created_By, Created_At
        ) VALUES (p_collection_id, p_customer_id, v_group, 0, 0, 0, p_total, 0, 0, 0, p_user_id, NOW());
        SELECT 'SUCCESS' AS status, LAST_INSERT_ID() AS detail_id, 'Member line saved' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_DUE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_DUE`(IN p_loan_account_id BIGINT, IN p_as_on DATE)
BEGIN
    SET p_as_on = IFNULL(p_as_on, CURDATE());

    CALL USP_LOAN_FACTS_RESET();
    INSERT INTO tmp_loan_facts (Loan_Account_Id)
    SELECT Loan_Account_Id FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id;
    CALL USP_LOAN_FACTS_FILL(p_as_on);

    SELECT
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        ap.Cust_Type_Cd,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        p_as_on AS As_On_Date,
        f.Due_P AS Principal_Due,
        f.Due_I AS Interest_Due,
        f.Penalty_Due,
        (f.Due_P + f.Due_I + f.Penalty_Due) AS Total_Due,
        f.Od_P AS Overdue_Principal,
        f.Od_I AS Overdue_Interest,
        f.Od_Installments AS Overdue_Installments,
        f.Dpd,
        f.Next_Due_Date,
        f.Next_Due_Amount,
        f.Inst_Amount AS Installment_Amount,
        f.Outstanding AS Principal_Outstanding,
        GREATEST(0, (f.Outstanding - f.Due_P)) AS Max_Advance_Principal,
        la.Ln_Status_Cd,
        FN_LOAN_OPT_DESC(40, la.Ln_Status_Cd) AS Ln_Status_Desc,
        IF(EXISTS (SELECT 1 FROM trans_loan_collection c WHERE c.Account_Id = la.Loan_Account_Id AND c.Tr_Status_Cd = 1), 1, 0)
            AS Has_Pending_Collection
    FROM tmp_loan_facts f
    JOIN mst_loan_account la ON la.Loan_Account_Id = f.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_LIST`(
    IN p_collection_id BIGINT,
    IN p_loan_account_id BIGINT,
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_fo_id INT,
    IN p_branch_id INT,
    IN p_payment_mode_cd INT,
    IN p_tr_status_cd INT,
    IN p_collection_type VARCHAR(20),
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_coll_ids;
    CREATE TEMPORARY TABLE tmp_loan_coll_ids (Collection_Id BIGINT PRIMARY KEY);

    INSERT INTO tmp_loan_coll_ids (Collection_Id)
    SELECT c.Collection_Id
    FROM trans_loan_collection c
    JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE (p_collection_id IS NULL OR c.Collection_Id = p_collection_id)
      AND (p_loan_account_id IS NULL OR c.Account_Id = p_loan_account_id)
      AND (p_member_id IS NULL
           OR (ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = p_member_id)
           OR EXISTS (SELECT 1 FROM trans_loan_collection_bulk bk WHERE bk.Collection_Id = c.Collection_Id AND bk.Customer_Id = p_member_id))
      AND (p_group_id IS NULL
           OR (ap.Cust_Type_Cd = 1 AND ap.Cust_Id_Primay = p_group_id)
           OR EXISTS (SELECT 1 FROM trans_loan_collection_bulk bk WHERE bk.Collection_Id = c.Collection_Id AND bk.Group_Id = p_group_id))
      AND (p_fo_id IS NULL OR c.FO_Id = p_fo_id)
      AND (p_branch_id IS NULL OR c.Branch_Id = p_branch_id)
      AND (p_payment_mode_cd IS NULL OR c.Payment_Mode_Cd = p_payment_mode_cd)
      AND (p_tr_status_cd IS NULL OR c.Tr_Status_Cd = p_tr_status_cd)
      AND (CASE IFNULL(p_collection_type, '')
               WHEN '' THEN IFNULL(c.Payment_Mode_Cd, 0) <> 5
               WHEN 'adjustment' THEN IFNULL(c.Payment_Mode_Cd, 0) = 5
               WHEN 'advance' THEN IFNULL(c.Payment_Mode_Cd, 0) <> 5 AND c.Ledger_Narration LIKE 'Advance collection%'
               WHEN 'overdue' THEN IFNULL(c.Payment_Mode_Cd, 0) <> 5 AND c.Ledger_Narration LIKE 'Overdue collection%'
               WHEN 'closure' THEN IFNULL(c.Payment_Mode_Cd, 0) <> 5 AND c.Ledger_Narration LIKE 'Loan closure%'
               WHEN 'regular' THEN IFNULL(c.Payment_Mode_Cd, 0) <> 5
                                   AND IFNULL(c.Ledger_Narration, '') NOT LIKE 'Advance collection%'
                                   AND IFNULL(c.Ledger_Narration, '') NOT LIKE 'Overdue collection%'
                                   AND IFNULL(c.Ledger_Narration, '') NOT LIKE 'Loan closure%'
               ELSE 0
           END)
      AND (p_from_date IS NULL OR IFNULL(c.Effect_Date, DATE(c.Collection_Date)) >= p_from_date)
      AND (p_to_date IS NULL OR IFNULL(c.Effect_Date, DATE(c.Collection_Date)) <= p_to_date)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(c.Trans_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(c.Trans_Ref_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));

    SELECT COUNT(*) INTO v_total FROM tmp_loan_coll_ids;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        c.Collection_Id,
        c.Trans_No,
        c.Account_Id AS Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        ap.Cust_Type_Cd,
        IF(ap.Cust_Type_Cd = 1, NULL, ap.Cust_Id_Primay) AS Member_Id,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        IF(ap.Cust_Type_Cd = 1, ap.Cust_Id_Primay, NULL) AS Group_Id,
        pg.Group_Name,
        c.Collection_Date,
        c.Effect_Date,
        c.Payment_Mode_Cd,
        FN_LOAN_OPT_DESC(41, c.Payment_Mode_Cd) AS Payment_Mode_Desc,
        c.Principal_Collected,
        c.Interest_Collected,
        c.Penalty_Collected,
        c.Total_Collected,
        c.Interest_Demand,
        c.Interest_Due,
        c.Interest_Capitalized,
        c.Outs_Principal,
        c.Trans_Ref_No,
        c.Ledger_Narration,
        CASE
            WHEN IFNULL(c.Payment_Mode_Cd, 0) = 5 THEN 'adjustment'
            WHEN c.Ledger_Narration LIKE 'Advance collection%' THEN 'advance'
            WHEN c.Ledger_Narration LIKE 'Overdue collection%' THEN 'overdue'
            WHEN c.Ledger_Narration LIKE 'Loan closure%' THEN 'closure'
            ELSE 'regular'
        END AS Collection_Type,
        (SELECT COUNT(*) FROM trans_loan_collection_bulk bk WHERE bk.Collection_Id = c.Collection_Id) AS Member_Count,
        c.FO_Id,
        fo.Full_Name AS FO_Name,
        c.Branch_Id,
        b.Branch_Name,
        c.Voucher_Id,
        v.Vou_No_Ref AS Voucher_No,
        c.Tr_Status_Cd,
        FN_LOAN_OPT_DESC(48, c.Tr_Status_Cd) AS Tr_Status_Desc,
        c.Remarks,
        c.Created_By,
        u.User_Name AS Created_By_Name,
        c.Created_At
    FROM tmp_loan_coll_ids t
    JOIN trans_loan_collection c ON c.Collection_Id = t.Collection_Id
    JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_staff fo ON fo.Staff_Id = c.FO_Id
    LEFT JOIN trans_vouchers v ON v.Voucher_Id = c.Voucher_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = c.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = c.Created_By
    ORDER BY c.Collection_Date DESC, c.Collection_Id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
