CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_MEMBERS`(IN p_collection_id BIGINT)
BEGIN
    SELECT bk.Detail_Id, bk.Collection_Id, bk.Customer_Id, m.Member_Name, m.Ref_Code AS Member_Ref_Code, bk.Group_Id,
           g.Group_Name, bk.Principal_Amount, bk.Interest_Amount, bk.Penalty_Amount, bk.Total_Amount, bk.Interest_Demand,
           bk.Interest_Due, bk.Principal_Outstanding
    FROM trans_loan_collection_bulk bk
    LEFT JOIN mst_member m ON m.Member_Id = bk.Customer_Id
    LEFT JOIN mst_group g ON g.Group_Id = bk.Group_Id
    WHERE bk.Collection_Id = p_collection_id
    ORDER BY bk.Detail_Id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
