CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_POST`(
    IN p_collection_id BIGINT,
    IN p_user_id INT,
    OUT p_voucher_id BIGINT,
    OUT p_voucher_no VARCHAR(25),
    OUT p_note VARCHAR(255),
    OUT p_err VARCHAR(255)
)
BEGIN
    DECLARE v_acct BIGINT;
    DECLARE v_p DECIMAL(14,2);
    DECLARE v_i DECIMAL(14,2);
    DECLARE v_n DECIMAL(14,2);
    DECLARE v_t DECIMAL(14,2);
    DECLARE v_mode INT;
    DECLARE v_eff DATE;
    DECLARE v_no VARCHAR(40);
    DECLARE v_outs DECIMAL(14,2);
    DECLARE v_app BIGINT;
    DECLARE v_branch INT;
    DECLARE v_ref VARCHAR(30);
    DECLARE v_loan_gl INT;
    DECLARE v_int_gl INT;
    DECLARE v_pen_gl INT;
    DECLARE v_extra DECIMAL(14,2) DEFAULT 0;

    SET p_err = NULL;
    SET p_voucher_id = NULL;
    SET p_voucher_no = NULL;
    SET p_note = NULL;

    SELECT MAX(Account_Id), MAX(Principal_Collected), MAX(Interest_Collected), MAX(Penalty_Collected), MAX(Total_Collected),
           MAX(Payment_Mode_Cd), MAX(IFNULL(Effect_Date, DATE(Collection_Date))), MAX(Trans_No)
    INTO v_acct, v_p, v_i, v_n, v_t, v_mode, v_eff, v_no
    FROM trans_loan_collection WHERE Collection_Id = p_collection_id;

    SELECT MAX(la.Principal_Outstanding), MAX(la.Application_Id), MAX(ap.Branch_Id), MAX(la.Ref_Account_No),
           MAX(NULLIF(s.Loan_Ledger, 0)), MAX(NULLIF(s.Intt_Ledger, 0)), MAX(NULLIF(s.OdIntt_Ledger, 0))
    INTO v_outs, v_app, v_branch, v_ref, v_loan_gl, v_int_gl, v_pen_gl
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    WHERE la.Loan_Account_Id = v_acct FOR UPDATE;

    IF v_pen_gl IS NULL THEN
        SELECT NULLIF(MAX(Value), 0) INTO v_pen_gl FROM mst_settings_global WHERE Id = 104;
    END IF;

    IF v_p > v_outs + 0.005 THEN
        SET p_err = CONCAT('Principal collected (', FORMAT(v_p, 2), ') is more than the outstanding (', FORMAT(v_outs, 2), ')');
    END IF;

    IF p_err IS NULL THEN
        UPDATE mst_loan_account SET Principal_Outstanding = Principal_Outstanding - v_p WHERE Loan_Account_Id = v_acct;
        UPDATE trans_loan_collection SET Tr_Status_Cd = 2, Outs_Principal = v_outs - v_p WHERE Collection_Id = p_collection_id;

        CALL USP_LOAN_SCHEDULE_SYNC(v_acct, p_collection_id, v_eff);

        SET v_extra = v_t - v_p - v_i - v_n;

        CALL USP_LOAN_VOUCHER_RESET();
        INSERT INTO tmp_loan_voucher_lines (Line_Role, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration)
        VALUES ('CONTRA', NULL, v_t, 0, CONCAT('Loan collection ', IFNULL(v_no, ''))),
               ('LOAN', v_loan_gl, 0, v_p, CONCAT('Principal ', IFNULL(v_ref, ''))),
               ('INTEREST', v_int_gl, 0, v_i, CONCAT('Interest ', IFNULL(v_ref, ''))),
               ('PENALTY', v_pen_gl, 0, v_n, CONCAT('Penalty ', IFNULL(v_ref, '')));

        IF v_extra > 0.005 THEN
            INSERT INTO tmp_loan_voucher_lines (Line_Role, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration)
            SELECT CONCAT('CHARGE ', IFNULL(c.Charge_Name, ch.Charge_Id)), NULLIF(c.Charges_Gl, 0), 0,
                   ch.Total_Charge - IFNULL(ch.Waived_Amount, 0), LEFT(CONCAT('Charge: ', IFNULL(c.Charge_Name, '')), 300)
            FROM mst_loan_application_charge ch
            LEFT JOIN mst_loan_charges c ON c.Charge_Id = ch.Charge_Id
            WHERE ch.Loan_Application_Id = v_app AND ch.Tr_Status_Cd = 1;
        END IF;

        CALL USP_LOAN_VOUCHER_POST(v_branch, v_eff, 1, v_mode, CONCAT('Loan collection ', IFNULL(v_no, ''), ' / ', IFNULL(v_ref, '')),
                                   p_user_id, p_voucher_id, p_voucher_no, p_note);

        UPDATE trans_loan_collection SET Voucher_Id = p_voucher_id WHERE Collection_Id = p_collection_id;

        IF v_extra > 0.005 THEN
            UPDATE mst_loan_application_charge SET Tr_Status_Cd = 2, Voucher_Id = p_voucher_id
            WHERE Loan_Application_Id = v_app AND Tr_Status_Cd = 1;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_REVERSE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_REVERSE`(
    IN p_collection_id BIGINT,
    IN p_reason VARCHAR(200),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_mode INT;
    DECLARE v_acct BIGINT;
    DECLARE v_p DECIMAL(14,2);
    DECLARE v_vid BIGINT;
    DECLARE v_narr VARCHAR(75);
    DECLARE v_ln_status INT;
    DECLARE v_new_id BIGINT;
    DECLARE v_new_no VARCHAR(25);
    DECLARE v_reason VARCHAR(200);

    SET v_reason = NULLIF(TRIM(IFNULL(p_reason, '')), '');

    SELECT COUNT(*), MAX(Tr_Status_Cd), MAX(Payment_Mode_Cd), MAX(Account_Id), MAX(Principal_Collected), MAX(Voucher_Id),
           MAX(Ledger_Narration)
    INTO v_cnt, v_status, v_mode, v_acct, v_p, v_vid, v_narr
    FROM trans_loan_collection WHERE Collection_Id = p_collection_id FOR UPDATE;
    SELECT MAX(Ln_Status_Cd) INTO v_ln_status FROM mst_loan_account WHERE Loan_Account_Id = v_acct FOR UPDATE;

    IF p_collection_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Collection not found';
    ELSEIF v_status <> 2 THEN
        SET v_err = 'Only approved collections can be reversed';
    ELSEIF IFNULL(v_mode, 0) = 5 THEN
        SET v_err = 'Adjustments cannot be reversed';
    ELSEIF v_ln_status <> 1 THEN
        SET v_err = 'Collections of a closed / written-off loan cannot be reversed';
    ELSEIF v_reason IS NULL THEN
        SET v_err = 'Reversal reason is required';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_collection_id AS collection_id, NULL AS reversal_voucher_id, NULL AS reversal_voucher_no,
               v_err AS message;
    ELSE
        UPDATE trans_loan_collection
        SET Tr_Status_Cd = 4, Remarks = LEFT(CONCAT_WS(' | ', Remarks, CONCAT('Reversed: ', v_reason)), 250)
        WHERE Collection_Id = p_collection_id;

        UPDATE mst_loan_account SET Principal_Outstanding = Principal_Outstanding + v_p WHERE Loan_Account_Id = v_acct;

        CALL USP_LOAN_SCHEDULE_SYNC(v_acct, NULL, NULL);
        CALL USP_LOAN_VOUCHER_REVERSE(v_vid, CURDATE(), p_user_id, v_new_id, v_new_no);

        SELECT 'SUCCESS' AS status, p_collection_id AS collection_id, v_new_id AS reversal_voucher_id,
               v_new_no AS reversal_voucher_no, 'Collection reversed' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_SHEET` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_SHEET`(
    IN p_group_id INT,
    IN p_center_id INT,
    IN p_fo_id INT,
    IN p_branch_id INT,
    IN p_as_on DATE
)
BEGIN
    SET p_as_on = IFNULL(p_as_on, CURDATE());

    CALL USP_LOAN_FACTS_RESET();

    INSERT INTO tmp_loan_facts (Loan_Account_Id)
    SELECT la.Loan_Account_Id
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE la.Ln_Status_Cd = 1 AND la.Disbursed_Amount > 0
      AND (p_group_id IS NOT NULL OR p_center_id IS NOT NULL OR p_fo_id IS NOT NULL OR p_branch_id IS NOT NULL)
      AND (p_group_id IS NULL
           OR (ap.Cust_Type_Cd = 1 AND ap.Cust_Id_Primay = p_group_id)
           OR (ap.Cust_Type_Cd = 2 AND EXISTS (SELECT 1 FROM mst_member_group mg
                                               WHERE mg.Member_Id = ap.Cust_Id_Primay AND mg.Group_Id = p_group_id AND mg.Is_Active = 1)))
      AND (p_center_id IS NULL OR IFNULL(pg.Center_Id, pm.Center_Id) = p_center_id)
      AND (p_fo_id IS NULL OR ap.FO_Id = p_fo_id)
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id);

    CALL USP_LOAN_FACTS_FILL(p_as_on);

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_sheet;
    CREATE TEMPORARY TABLE tmp_loan_sheet (
        Loan_Account_Id BIGINT PRIMARY KEY,
        Due_P DECIMAL(14,2), Due_I DECIMAL(14,2), Penalty DECIMAL(14,2), Outstanding DECIMAL(14,2)
    );
    INSERT INTO tmp_loan_sheet SELECT Loan_Account_Id, Due_P, Due_I, Penalty_Due, Outstanding FROM tmp_loan_facts;

    SELECT
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        ap.Cust_Type_Cd,
        IF(ap.Cust_Type_Cd = 1, NULL, ap.Cust_Id_Primay) AS Member_Id,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        pm.Mobile_No,
        IF(ap.Cust_Type_Cd = 1, ap.Cust_Id_Primay,
           (SELECT mg.Group_Id FROM mst_member_group mg WHERE mg.Member_Id = ap.Cust_Id_Primay AND mg.Is_Active = 1
            ORDER BY mg.Mem_Group_Id DESC LIMIT 1)) AS Group_Id,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name,
           (SELECT g2.Group_Name FROM mst_member_group mg JOIN mst_group g2 ON g2.Group_Id = mg.Group_Id
            WHERE mg.Member_Id = ap.Cust_Id_Primay AND mg.Is_Active = 1 ORDER BY mg.Mem_Group_Id DESC LIMIT 1)) AS Group_Name,
        s.Scheme_Name,
        f.Inst_Amount AS Installment_Amount,
        f.Due_P AS Principal_Due,
        f.Due_I AS Interest_Due,
        f.Penalty_Due,
        (f.Due_P + f.Due_I + f.Penalty_Due) AS Total_Due,
        f.Od_Installments AS Overdue_Installments,
        f.Dpd,
        f.Next_Due_Date,
        f.Outstanding AS Principal_Outstanding,
        IF(EXISTS (SELECT 1 FROM trans_loan_collection c WHERE c.Account_Id = la.Loan_Account_Id AND c.Tr_Status_Cd = 1), 1, 0)
            AS Has_Pending_Collection,
        fo.Full_Name AS FO_Name
    FROM tmp_loan_facts f
    JOIN mst_loan_account la ON la.Loan_Account_Id = f.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = ap.FO_Id
    ORDER BY Group_Name, Member_Name, la.Loan_Account_Id;

    SELECT
        la.Loan_Account_Id,
        bk.Customer_Id,
        m.Member_Name,
        m.Ref_Code AS Member_Ref_Code,
        bk.Group_Id,
        ROUND(x.share * 100, 4) AS Share_Percent,
        ROUND(t.Due_P * x.share, 2) AS Principal_Due,
        ROUND(t.Due_I * x.share, 2) AS Interest_Due,
        ROUND(t.Penalty * x.share, 2) AS Penalty_Due,
        ROUND((t.Due_P + t.Due_I + t.Penalty) * x.share, 2) AS Total_Due,
        ROUND(t.Outstanding * x.share, 2) AS Principal_Outstanding
    FROM tmp_loan_sheet t
    JOIN mst_loan_account la ON la.Loan_Account_Id = t.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id AND ap.Cust_Type_Cd = 1
    JOIN mst_loan_application_bulk bk ON bk.Loan_Application_Id = ap.Application_Id
    JOIN (
        SELECT b2.Id,
               IFNULL(NULLIF(b2.Sanction_Amount, 0), b2.Requested_Amount)
               / NULLIF(SUM(IFNULL(NULLIF(b2.Sanction_Amount, 0), b2.Requested_Amount)) OVER (PARTITION BY b2.Loan_Application_Id), 0) AS share
        FROM mst_loan_application_bulk b2
    ) x ON x.Id = bk.Id
    LEFT JOIN mst_member m ON m.Member_Id = bk.Customer_Id
    ORDER BY la.Loan_Account_Id, m.Member_Name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_COLLECTION_SPLIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_COLLECTION_SPLIT`(
    IN p_acct BIGINT,
    IN p_effect DATE,
    IN p_total DECIMAL(14,2),
    IN p_is_advance TINYINT,
    OUT p_principal DECIMAL(14,2),
    OUT p_interest DECIMAL(14,2),
    OUT p_penalty DECIMAL(14,2),
    OUT p_int_demand DECIMAL(14,2),
    OUT p_err VARCHAR(255)
)
BEGIN
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_pen DECIMAL(14,2) DEFAULT 0;
    DECLARE v_due_i DECIMAL(14,2) DEFAULT 0;
    DECLARE v_due_p DECIMAL(14,2) DEFAULT 0;
    DECLARE v_paid_p DECIMAL(14,2) DEFAULT 0;
    DECLARE v_paid_i DECIMAL(14,2) DEFAULT 0;
    DECLARE v_rem DECIMAL(14,2) DEFAULT 0;
    DECLARE v_take DECIMAL(14,2) DEFAULT 0;
    DECLARE v_ui DECIMAL(14,2);
    DECLARE v_up DECIMAL(14,2);
    DECLARE v_outs DECIMAL(14,2) DEFAULT 0;
    DECLARE cur CURSOR FOR SELECT Unpaid_I, Unpaid_P FROM tmp_loan_future ORDER BY Installment_No, Schedule_Id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    SET p_err = NULL;
    SET v_paid_p = FN_LOAN_PAID(p_acct, NULL, 'P');
    SET v_paid_i = FN_LOAN_PAID(p_acct, NULL, 'I');
    SET v_pen = FN_LOAN_PENALTY_DUE(p_acct, p_effect);
    SET v_due_i = GREATEST(0, FN_LOAN_DEMAND(p_acct, p_effect, 'I') - v_paid_i);
    SELECT IFNULL(MAX(Principal_Outstanding), 0) INTO v_outs FROM mst_loan_account WHERE Loan_Account_Id = p_acct;
    SET v_due_p = LEAST(v_outs, GREATEST(0, FN_LOAN_DEMAND(p_acct, p_effect, 'P') - v_paid_p));
    SET p_int_demand = v_due_i;

    SET v_rem = p_total;
    SET p_penalty = LEAST(v_rem, v_pen);
    SET v_rem = v_rem - p_penalty;
    SET p_interest = LEAST(v_rem, v_due_i);
    SET v_rem = v_rem - p_interest;
    SET p_principal = LEAST(v_rem, v_due_p);
    SET v_rem = v_rem - p_principal;

    IF v_rem > 0 AND IFNULL(p_is_advance, 0) = 1 THEN
        DROP TEMPORARY TABLE IF EXISTS tmp_loan_future;
        CREATE TEMPORARY TABLE tmp_loan_future (
            Schedule_Id BIGINT PRIMARY KEY, Installment_No INT, Unpaid_I DECIMAL(14,2), Unpaid_P DECIMAL(14,2)
        );

        INSERT INTO tmp_loan_future
        SELECT w.Schedule_Id, w.Installment_No,
               w.idue - LEAST(w.idue, GREATEST(0, (v_paid_i + p_interest) - (w.cum_i - w.idue))),
               w.pd - LEAST(w.pd, GREATEST(0, (v_paid_p + p_principal) - (w.cum_p - w.pd)))
        FROM (
            SELECT s.Schedule_Id, s.Installment_No, s.Due_Date,
                   s.Principal_Due - IFNULL(s.Principal_Waived, 0) AS pd,
                   s.Interest_Due - IFNULL(s.Interest_Waived, 0) AS idue,
                   SUM(s.Principal_Due - IFNULL(s.Principal_Waived, 0)) OVER w AS cum_p,
                   SUM(s.Interest_Due - IFNULL(s.Interest_Waived, 0)) OVER w AS cum_i
            FROM trans_loanac_schedule s
            WHERE s.Loan_Account_Id = p_acct AND IFNULL(s.Is_Active, 1) = 1
            WINDOW w AS (ORDER BY s.Installment_No, s.Schedule_Id)
        ) w
        WHERE w.Due_Date > p_effect;

        OPEN cur;
        read_loop: LOOP
            FETCH cur INTO v_ui, v_up;
            IF v_done = 1 OR v_rem <= 0 THEN
                LEAVE read_loop;
            END IF;
            SET v_take = LEAST(v_rem, GREATEST(0, v_ui));
            SET p_interest = p_interest + v_take;
            SET v_rem = v_rem - v_take;
            SET v_take = LEAST(v_rem, GREATEST(0, v_up), GREATEST(0, v_outs - p_principal));
            SET p_principal = p_principal + v_take;
            SET v_rem = v_rem - v_take;
        END LOOP;
        CLOSE cur;

        IF v_rem > 0.005 THEN
            SET p_err = CONCAT('Amount exceeds the total payable on this loan by ', FORMAT(v_rem, 2));
        END IF;
    ELSEIF v_rem > 0.005 THEN
        SET p_err = IF(v_pen + v_due_i + v_due_p <= 0,
                       'Nothing is due on this loan; send is_advance = true to collect in advance',
                       CONCAT('Amount exceeds the amount due (', FORMAT(v_pen + v_due_i + v_due_p, 2),
                              '); send is_advance = true to collect the extra in advance'));
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_DASHBOARD_SUMMARY` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DASHBOARD_SUMMARY`(IN p_branch_id INT, IN p_as_on DATE)
BEGIN
    DECLARE v_month DATE;
    DECLARE v_fv INT DEFAULT 0;
    DECLARE v_ap INT DEFAULT 0;
    DECLARE v_sa INT DEFAULT 0;
    DECLARE v_di INT DEFAULT 0;
    DECLARE v_rj INT DEFAULT 0;
    DECLARE v_sanc_cnt INT DEFAULT 0;
    DECLARE v_sanc_amt DECIMAL(16,2) DEFAULT 0;
    DECLARE v_disb_cnt INT DEFAULT 0;
    DECLARE v_disb_amt DECIMAL(16,2) DEFAULT 0;
    DECLARE v_coll_today DECIMAL(16,2) DEFAULT 0;
    DECLARE v_coll_month DECIMAL(16,2) DEFAULT 0;
    DECLARE v_dem_month DECIMAL(16,2) DEFAULT 0;
    DECLARE v_accounts INT DEFAULT 0;
    DECLARE v_outs DECIMAL(16,2) DEFAULT 0;
    DECLARE v_due_today DECIMAL(16,2) DEFAULT 0;
    DECLARE v_due_total DECIMAL(16,2) DEFAULT 0;
    DECLARE v_par30 DECIMAL(16,2) DEFAULT 0;
    DECLARE v_npa DECIMAL(16,2) DEFAULT 0;
    DECLARE v_pc INT DEFAULT 0;
    DECLARE v_pd INT DEFAULT 0;

    SET p_as_on = IFNULL(p_as_on, CURDATE());
    SET v_month = DATE_FORMAT(p_as_on, '%Y-%m-01');

    SELECT IFNULL(SUM(st = 'field_verification'), 0), IFNULL(SUM(st = 'approval'), 0), IFNULL(SUM(st = 'sanctioned'), 0),
           IFNULL(SUM(st = 'disbursed'), 0), IFNULL(SUM(st = 'rejected'), 0)
    INTO v_fv, v_ap, v_sa, v_di, v_rj
    FROM (SELECT FN_LOAN_APPL_STAGE(a.Application_Id) AS st FROM mst_loan_application a
          WHERE (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)) x;

    SELECT COUNT(*), IFNULL(SUM(ap.Sanctioned_Amount), 0) INTO v_sanc_cnt, v_sanc_amt
    FROM mst_loan_application_approval ap
    JOIN mst_loan_application a ON a.Application_Id = ap.Loan_Application_Id
    WHERE ap.Approval_Status_Cd = 1 AND DATE(ap.Approval_Date) BETWEEN v_month AND p_as_on
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id);

    SELECT COUNT(*), IFNULL(SUM(d.Gross_Amount), 0) INTO v_disb_cnt, v_disb_amt
    FROM mst_loan_account_disbursement d
    JOIN mst_loan_account la ON la.Loan_Account_Id = d.Loan_Account_Id
    JOIN mst_loan_application a ON a.Application_Id = la.Application_Id
    WHERE d.Approved_By IS NOT NULL AND d.Disbursement_Date BETWEEN v_month AND p_as_on
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id);

    SELECT IFNULL(SUM(IF(IFNULL(c.Effect_Date, DATE(c.Collection_Date)) = p_as_on, c.Total_Collected, 0)), 0),
           IFNULL(SUM(c.Principal_Collected + c.Interest_Collected), 0)
    INTO v_coll_today, v_coll_month
    FROM trans_loan_collection c
    WHERE c.Tr_Status_Cd = 2 AND IFNULL(c.Payment_Mode_Cd, 0) <> 5
      AND IFNULL(c.Effect_Date, DATE(c.Collection_Date)) BETWEEN v_month AND p_as_on
      AND (p_branch_id IS NULL OR c.Branch_Id = p_branch_id);

    SELECT IFNULL(SUM(sc.Principal_Due - IFNULL(sc.Principal_Waived, 0) + sc.Interest_Due - IFNULL(sc.Interest_Waived, 0)), 0)
    INTO v_dem_month
    FROM trans_loanac_schedule sc
    JOIN mst_loan_account la ON la.Loan_Account_Id = sc.Loan_Account_Id
    JOIN mst_loan_application a ON a.Application_Id = la.Application_Id
    WHERE IFNULL(sc.Is_Active, 1) = 1 AND la.Disbursed_Amount > 0 AND sc.Due_Date BETWEEN v_month AND p_as_on
      AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id);

    SELECT COUNT(*) INTO v_pc FROM trans_loan_collection c WHERE c.Tr_Status_Cd = 1 AND (p_branch_id IS NULL OR c.Branch_Id = p_branch_id);
    SELECT COUNT(*) INTO v_pd
    FROM mst_loan_account_disbursement d
    JOIN mst_loan_account la ON la.Loan_Account_Id = d.Loan_Account_Id
    JOIN mst_loan_application a ON a.Application_Id = la.Application_Id
    WHERE d.Approved_By IS NULL AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id);

    CALL USP_LOAN_PORTFOLIO_FACTS(p_as_on, p_branch_id, NULL);

    SELECT COUNT(*), IFNULL(SUM(Outstanding), 0), IFNULL(SUM(Due_Today), 0), IFNULL(SUM(Due_P + Due_I + Penalty_Due), 0),
           IFNULL(SUM(IF(Dpd > 30, Outstanding, 0)), 0), IFNULL(SUM(IF(Bucket = 'npa', Outstanding, 0)), 0)
    INTO v_accounts, v_outs, v_due_today, v_due_total, v_par30, v_npa
    FROM tmp_loan_facts;

    SELECT p_as_on AS As_On_Date,
           v_fv AS Field_Verification_Count, v_ap AS Approval_Count, v_sa AS Sanctioned_Count, v_di AS Disbursed_Count,
           v_rj AS Rejected_Count,
           v_sanc_cnt AS Sanctioned_This_Month_Count, v_sanc_amt AS Sanctioned_This_Month_Amount,
           v_disb_cnt AS Disbursed_This_Month_Count, v_disb_amt AS Disbursed_This_Month_Amount,
           v_due_today AS Collection_Due_Today, v_due_total AS Total_Due_Incl_Overdue, v_coll_today AS Collected_Today,
           v_coll_month AS Collected_This_Month, v_dem_month AS Demand_This_Month,
           IF(v_dem_month > 0, ROUND(v_coll_month * 100 / v_dem_month, 2), NULL) AS Collection_Efficiency_Percent,
           v_accounts AS Active_Loans, v_outs AS Total_Outstanding,
           IF(v_outs > 0, ROUND(v_par30 * 100 / v_outs, 2), 0) AS Par30_Percent,
           IF(v_outs > 0, ROUND(v_npa * 100 / v_outs, 2), 0) AS Npa_Percent,
           v_pc AS Pending_Collection_Approvals, v_pd AS Pending_Disbursement_Approvals;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_DEFAULTER_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DEFAULTER_LIST`(
    IN p_branch_id INT,
    IN p_fo_id INT,
    IN p_scheme_id INT,
    IN p_ln_status_cd INT,
    IN p_keyword VARCHAR(150),
    IN p_as_on DATE,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;
    SET p_as_on = IFNULL(p_as_on, CURDATE());

    CALL USP_LOAN_FACTS_RESET();

    INSERT INTO tmp_loan_facts (Loan_Account_Id)
    SELECT la.Loan_Account_Id
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE IFNULL(la.Is_Defaulter, 0) = 1
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
      AND (p_fo_id IS NULL OR ap.FO_Id = p_fo_id)
      AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
      AND (p_ln_status_cd IS NULL OR la.Ln_Status_Cd = p_ln_status_cd)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));

    CALL USP_LOAN_FACTS_FILL(p_as_on);

    SELECT COUNT(*) INTO v_total FROM tmp_loan_facts;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        IF(ap.Cust_Type_Cd = 1, NULL, ap.Cust_Id_Primay) AS Member_Id,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        pm.Mobile_No,
        s.Scheme_Name,
        la.Loan_Date,
        la.Loan_Amount,
        la.Disbursed_Amount,
        f.Outstanding AS Principal_Outstanding,
        f.Od_P AS Overdue_Principal,
        f.Od_I AS Overdue_Interest,
        f.Penalty_Due,
        (f.Od_P + f.Od_I + f.Penalty_Due) AS Total_Overdue,
        f.Oldest_Unpaid AS Oldest_Due_Date,
        f.Dpd,
        f.Bucket,
        IFNULL(la.Is_NPA, 0) AS Is_NPA,
        la.Ln_Status_Cd,
        FN_LOAN_OPT_DESC(40, la.Ln_Status_Cd) AS Ln_Status_Desc,
        (SELECT GROUP_CONCAT(gm.Member_Name ORDER BY g.Loan_Guarantor_Id SEPARATOR ', ')
         FROM mst_loan_application_guarantor g JOIN mst_member gm ON gm.Member_Id = g.Guarantor_Id
         WHERE g.Loan_Application_Id = ap.Application_Id AND g.Release_Date IS NULL) AS Guarantor_Names,
        (SELECT GROUP_CONCAT(gm.Mobile_No ORDER BY g.Loan_Guarantor_Id SEPARATOR ', ')
         FROM mst_loan_application_guarantor g JOIN mst_member gm ON gm.Member_Id = g.Guarantor_Id
         WHERE g.Loan_Application_Id = ap.Application_Id AND g.Release_Date IS NULL) AS Guarantor_Mobiles,
        ap.Branch_Id,
        b.Branch_Name,
        ap.FO_Id,
        fo.Full_Name AS FO_Name
    FROM tmp_loan_facts f
    JOIN mst_loan_account la ON la.Loan_Account_Id = f.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = ap.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
    ORDER BY f.Dpd DESC, la.Loan_Account_Id
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_DEFAULTER_MARK` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DEFAULTER_MARK`(IN p_loan_account_id BIGINT, IN p_is_defaulter TINYINT, IN p_user_id INT)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_old INT;

    SELECT COUNT(*), MAX(Ln_Status_Cd), MAX(IFNULL(Is_Defaulter, 0)) INTO v_cnt, v_status, v_old
    FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id FOR UPDATE;

    IF v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, NULL AS is_defaulter, 'Loan account not found' AS message;
    ELSEIF v_status <> 1 THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, v_old AS is_defaulter, 'Loan account is not active' AS message;
    ELSEIF p_is_defaulter IS NULL OR p_is_defaulter NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, v_old AS is_defaulter, 'is_defaulter must be true or false' AS message;
    ELSE
        UPDATE mst_loan_account SET Is_Defaulter = p_is_defaulter WHERE Loan_Account_Id = p_loan_account_id;
        SELECT 'SUCCESS' AS status, p_loan_account_id AS loan_account_id, p_is_defaulter AS is_defaulter,
               IF(p_is_defaulter = 1, 'Loan marked as defaulter', 'Defaulter flag removed') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
