/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_DISBURSEMENT_ADD` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DISBURSEMENT_ADD`(
    IN p_loan_account_id BIGINT,
    IN p_disbursement_date DATE,
    IN p_gross DECIMAL(14,2),
    IN p_other_deduction DECIMAL(14,2),
    IN p_payment_mode_cd INT,
    IN p_reference_no VARCHAR(20),
    IN p_cheque_no VARCHAR(20),
    IN p_sb_account_id INT,
    IN p_is_final TINYINT,
    IN p_remarks VARCHAR(200),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_app BIGINT;
    DECLARE v_loan DECIMAL(14,2) DEFAULT 0;
    DECLARE v_disb DECIMAL(14,2) DEFAULT 0;
    DECLARE v_loan_date DATE;
    DECLARE v_last DATE;
    DECLARE v_type INT;
    DECLARE v_cust INT;
    DECLARE v_ded DECIMAL(14,2) DEFAULT 0;
    DECLARE v_net DECIMAL(14,2) DEFAULT 0;
    DECLARE v_final INT DEFAULT 0;
    DECLARE v_pending INT DEFAULT 0;
    DECLARE v_no VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_id BIGINT;
    DECLARE v_vid BIGINT;
    DECLARE v_vno VARCHAR(25);
    DECLARE v_note VARCHAR(255);
    DECLARE v_resched DECIMAL(14,2);

    SET p_other_deduction = IFNULL(p_other_deduction, 0);
    SET p_disbursement_date = IFNULL(p_disbursement_date, CURDATE());

    SELECT COUNT(*), MAX(la.Ln_Status_Cd), MAX(la.Application_Id), IFNULL(MAX(la.Loan_Amount), 0), IFNULL(MAX(la.Disbursed_Amount), 0),
           MAX(la.Loan_Date), MAX(ap.Cust_Type_Cd), MAX(ap.Cust_Id_Primay)
    INTO v_cnt, v_status, v_app, v_loan, v_disb, v_loan_date, v_type, v_cust
    FROM mst_loan_account la JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE la.Loan_Account_Id = p_loan_account_id FOR UPDATE;

    SELECT MAX(Disbursement_Date) INTO v_last FROM mst_loan_account_disbursement WHERE Loan_Account_Id = p_loan_account_id;

    IF p_loan_account_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Loan account not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Loan account is not active';
    ELSEIF EXISTS (SELECT 1 FROM mst_loan_account_disbursement WHERE Loan_Account_Id = p_loan_account_id AND Approved_By IS NULL) THEN
        SET v_err = 'A disbursement on this loan is waiting for approval';
    ELSEIF EXISTS (SELECT 1 FROM mst_loan_account_disbursement WHERE Loan_Account_Id = p_loan_account_id AND IFNULL(Is_Final, 0) = 1)
           OR v_disb >= v_loan THEN
        SET v_err = 'Loan is fully disbursed';
    ELSEIF p_disbursement_date > CURDATE() THEN
        SET v_err = 'Disbursement date cannot be in the future';
    ELSEIF p_disbursement_date < v_loan_date THEN
        SET v_err = 'Disbursement date cannot be before the loan date';
    ELSEIF v_last IS NOT NULL AND p_disbursement_date < v_last THEN
        SET v_err = 'Disbursement date cannot be before the previous disbursement';
    ELSEIF p_gross IS NULL OR p_gross <= 0 THEN
        SET v_err = 'Gross amount must be greater than zero';
    ELSEIF v_disb + p_gross > v_loan THEN
        SET v_err = CONCAT('Gross amount cannot exceed the undisbursed amount (', FORMAT(v_loan - v_disb, 2), ')');
    ELSEIF p_other_deduction < 0 THEN
        SET v_err = 'Other deduction cannot be negative';
    ELSEIF p_payment_mode_cd IS NULL OR p_payment_mode_cd NOT IN (1, 2, 3, 4) THEN
        SET v_err = 'Payment mode must be 1 (Cash), 2 (Bank Cheque), 3 (Bank Transfer) or 4 (S/B Account)';
    ELSEIF p_payment_mode_cd = 2 AND NULLIF(TRIM(IFNULL(p_cheque_no, '')), '') IS NULL THEN
        SET v_err = 'Cheque number is required for cheque payment';
    ELSEIF p_payment_mode_cd = 3 AND NULLIF(TRIM(IFNULL(p_reference_no, '')), '') IS NULL THEN
        SET v_err = 'Reference number is required for bank transfer';
    ELSEIF p_payment_mode_cd = 4 AND NOT EXISTS (
            SELECT 1 FROM mst_deposit_account da
            JOIN mst_deposit_account_sb sb ON sb.Account_Id = da.Account_Id
            WHERE da.Account_Id = p_sb_account_id AND da.Deposit_Type_Cd = 1 AND da.Closing_Date IS NULL
              AND IFNULL(da.Appl_Status_Cd, 1) <> 4 AND da.Cust_Type_Cd = v_type AND da.Cust_Id_Primay = v_cust) THEN
        SET v_err = 'S/B account must be an open savings account of the borrower';
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_DISB_CHARGES(p_loan_account_id, p_gross);
        SELECT IFNULL(SUM(Net_Amount), 0) INTO v_ded FROM tmp_loan_disb_charges;
        SET v_net = p_gross - v_ded - p_other_deduction;
        SET v_final = IF(IFNULL(p_is_final, 0) = 1 OR v_disb + p_gross >= v_loan, 1, 0);

        IF v_net <= 0 THEN
            SET v_err = CONCAT('Net amount must be greater than zero (charges ', FORMAT(v_ded, 2), ', other deduction ',
                               FORMAT(p_other_deduction, 2), ')');
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_CODE_SERIES_GENERATE('loan_disbursement', v_no, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_no IS NULL THEN
            SET v_err = CONCAT('Disbursement number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS disbursement_id, NULL AS disbursement_no, NULL AS approval_status,
               NULL AS gross_amount, NULL AS charge_deduction, NULL AS other_deduction, NULL AS net_amount,
               NULL AS voucher_id, NULL AS voucher_no, NULL AS voucher_note, p_payment_mode_cd AS payment_mode_cd,
               NULL AS sb_account_id, NULL AS reschedule_amount, v_err AS message;
    ELSE
        SET v_pending = FN_LOAN_MC_PENDING(2, p_gross, p_user_id);

        INSERT INTO mst_loan_account_disbursement (
            Disbursement_No, Loan_Account_Id, Disbursement_Date, Gross_Amount, Charge_Deduction, Other_Deduction, Net_Amount,
            Payment_Mode_Cd, Reference_No, Cheque_No, SB_Account_ID, Is_Final, Remarks, Voucher_Id, Approved_By,
            Created_By, Created_On
        ) VALUES (
            LEFT(v_no, 25), p_loan_account_id, p_disbursement_date, p_gross, v_ded, p_other_deduction, v_net,
            p_payment_mode_cd, NULLIF(TRIM(IFNULL(p_reference_no, '')), ''), NULLIF(TRIM(IFNULL(p_cheque_no, '')), ''),
            IF(p_payment_mode_cd = 4, p_sb_account_id, NULL), v_final, NULLIF(TRIM(IFNULL(p_remarks, '')), ''), NULL, NULL,
            p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();

        IF v_pending = 0 THEN
            CALL USP_LOAN_DISB_POST(v_id, p_user_id, v_vid, v_vno, v_note, v_resched, v_err);
        END IF;

        IF v_err IS NOT NULL THEN
            SELECT 'ERROR' AS status, NULL AS disbursement_id, NULL AS disbursement_no, NULL AS approval_status,
                   NULL AS gross_amount, NULL AS charge_deduction, NULL AS other_deduction, NULL AS net_amount,
                   NULL AS voucher_id, NULL AS voucher_no, NULL AS voucher_note, p_payment_mode_cd AS payment_mode_cd,
                   NULL AS sb_account_id, NULL AS reschedule_amount, v_err AS message;
        ELSE
            SELECT 'SUCCESS' AS status, v_id AS disbursement_id, LEFT(v_no, 25) AS disbursement_no,
                   IF(v_pending = 1, 'pending', 'approved') AS approval_status,
                   p_gross AS gross_amount, v_ded AS charge_deduction, p_other_deduction AS other_deduction, v_net AS net_amount,
                   v_vid AS voucher_id, v_vno AS voucher_no, v_note AS voucher_note, p_payment_mode_cd AS payment_mode_cd,
                   IF(p_payment_mode_cd = 4, p_sb_account_id, NULL) AS sb_account_id, v_resched AS reschedule_amount,
                   IF(v_pending = 1, 'Disbursement saved and sent for approval', 'Loan disbursed') AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
