DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DISBURSEMENT_APPROVE`(
    IN p_disbursement_id BIGINT,
    IN p_approve TINYINT,
    IN p_remarks VARCHAR(200),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_appr INT;
    DECLARE v_maker INT;
    DECLARE v_acct BIGINT;
    DECLARE v_mode INT;
    DECLARE v_sb INT;
    DECLARE v_net DECIMAL(14,2);
    DECLARE v_no VARCHAR(25);
    DECLARE v_status INT;
    DECLARE v_vid BIGINT;
    DECLARE v_vno VARCHAR(25);
    DECLARE v_note VARCHAR(255);
    DECLARE v_resched DECIMAL(14,2);

    SELECT COUNT(*), MAX(Approved_By), MAX(Created_By), MAX(Loan_Account_Id), MAX(Payment_Mode_Cd), MAX(SB_Account_ID),
           MAX(Net_Amount), MAX(Disbursement_No)
    INTO v_cnt, v_appr, v_maker, v_acct, v_mode, v_sb, v_net, v_no
    FROM mst_loan_account_disbursement WHERE Disbursement_Id = p_disbursement_id FOR UPDATE;

    SELECT MAX(Ln_Status_Cd) INTO v_status FROM mst_loan_account WHERE Loan_Account_Id = v_acct;

    IF p_disbursement_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Disbursement not found';
    ELSEIF v_appr IS NOT NULL THEN
        SET v_err = 'Disbursement is already approved';
    ELSEIF p_approve IS NULL OR p_approve NOT IN (0, 1) THEN
        SET v_err = 'Approve must be 1 (approve) or 0 (reject)';
    ELSEIF p_approve = 0 AND NULLIF(TRIM(IFNULL(p_remarks, '')), '') IS NULL THEN
        SET v_err = 'Rejection reason is required';
    ELSEIF p_approve = 1 AND v_status <> 1 THEN
        SET v_err = 'Loan account is not active; reject this disbursement instead';
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_MC_CHECKER(2, v_maker, p_user_id, v_err);
    END IF;

    IF v_err IS NULL AND p_approve = 1 THEN
        CALL USP_LOAN_DISB_POST(p_disbursement_id, p_user_id, v_vid, v_vno, v_note, v_resched, v_err);
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_disbursement_id AS disbursement_id, NULL AS approval_status, NULL AS voucher_id,
               NULL AS voucher_no, NULL AS voucher_note, NULL AS loan_account_id, NULL AS payment_mode_cd,
               NULL AS sb_account_id, NULL AS net_amount, NULL AS reschedule_amount, v_err AS message;
    ELSEIF p_approve = 1 THEN
        SELECT 'SUCCESS' AS status, p_disbursement_id AS disbursement_id, 'approved' AS approval_status,
               v_vid AS voucher_id, v_vno AS voucher_no, v_note AS voucher_note, v_acct AS loan_account_id,
               v_mode AS payment_mode_cd, v_sb AS sb_account_id, v_net AS net_amount, v_resched AS reschedule_amount,
               'Disbursement approved' AS message;
    ELSE
        DELETE FROM mst_loan_account_disbursement WHERE Disbursement_Id = p_disbursement_id;
        SELECT 'SUCCESS' AS status, p_disbursement_id AS disbursement_id, 'rejected' AS approval_status,
               NULL AS voucher_id, NULL AS voucher_no, NULL AS voucher_note, v_acct AS loan_account_id,
               v_mode AS payment_mode_cd, NULL AS sb_account_id, v_net AS net_amount, NULL AS reschedule_amount,
               CONCAT('Disbursement ', IFNULL(v_no, ''), ' rejected') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_DISBURSEMENT_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DISBURSEMENT_LIST`(
    IN p_disbursement_id BIGINT,
    IN p_loan_account_id BIGINT,
    IN p_is_final TINYINT,
    IN p_payment_mode_cd INT,
    IN p_approval VARCHAR(10),
    IN p_branch_id INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_disb_ids;
    CREATE TEMPORARY TABLE tmp_loan_disb_ids (Disbursement_Id BIGINT PRIMARY KEY);

    INSERT INTO tmp_loan_disb_ids (Disbursement_Id)
    SELECT d.Disbursement_Id
    FROM mst_loan_account_disbursement d
    JOIN mst_loan_account la ON la.Loan_Account_Id = d.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE (p_disbursement_id IS NULL OR d.Disbursement_Id = p_disbursement_id)
      AND (p_loan_account_id IS NULL OR d.Loan_Account_Id = p_loan_account_id)
      AND (p_is_final IS NULL OR IFNULL(d.Is_Final, 0) = p_is_final)
      AND (p_payment_mode_cd IS NULL OR d.Payment_Mode_Cd = p_payment_mode_cd)
      AND (p_approval IS NULL OR p_approval = ''
           OR (p_approval = 'pending' AND d.Approved_By IS NULL)
           OR (p_approval = 'approved' AND d.Approved_By IS NOT NULL))
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
      AND (p_from_date IS NULL OR d.Disbursement_Date >= p_from_date)
      AND (p_to_date IS NULL OR d.Disbursement_Date <= p_to_date)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(d.Disbursement_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));

    SELECT COUNT(*) INTO v_total FROM tmp_loan_disb_ids;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        d.Disbursement_Id,
        d.Disbursement_No,
        d.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        ap.Application_Id,
        ap.Application_No,
        ap.Cust_Type_Cd,
        IF(ap.Cust_Type_Cd = 1, NULL, ap.Cust_Id_Primay) AS Member_Id,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        IF(ap.Cust_Type_Cd = 1, ap.Cust_Id_Primay, NULL) AS Group_Id,
        pg.Group_Name,
        d.Disbursement_Date,
        d.Gross_Amount,
        d.Charge_Deduction,
        d.Other_Deduction,
        d.Net_Amount,
        d.Payment_Mode_Cd,
        FN_LOAN_OPT_DESC(41, d.Payment_Mode_Cd) AS Payment_Mode_Desc,
        d.Reference_No,
        d.Cheque_No,
        d.SB_Account_ID,
        sb.Ref_AcNo AS SB_Account_No,
        IFNULL(d.Is_Final, 0) AS Is_Final,
        IF(IFNULL(d.Is_Final, 0) = 1, 'Final', 'Draft') AS Status,
        IF(d.Approved_By IS NULL, 'Pending', 'Approved') AS Approval_Status,
        d.Voucher_Id,
        v.Vou_No_Ref AS Voucher_No,
        d.Approved_By,
        au.User_Name AS Approved_By_Name,
        d.Remarks,
        ap.Branch_Id,
        b.Branch_Name,
        d.Created_By,
        cu.User_Name AS Created_By_Name,
        d.Created_On
    FROM tmp_loan_disb_ids t
    JOIN mst_loan_account_disbursement d ON d.Disbursement_Id = t.Disbursement_Id
    JOIN mst_loan_account la ON la.Loan_Account_Id = d.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_deposit_account_sb sb ON sb.Account_Id = d.SB_Account_ID
    LEFT JOIN trans_vouchers v ON v.Voucher_Id = d.Voucher_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user au ON au.User_Id = d.Approved_By
    LEFT JOIN priomicro_core.mst_org_user cu ON cu.User_Id = d.Created_By
    ORDER BY d.Disbursement_Date DESC, d.Disbursement_Id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_DISBURSEMENT_PREVIEW` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DISBURSEMENT_PREVIEW`(
    IN p_loan_account_id BIGINT,
    IN p_gross DECIMAL(14,2),
    IN p_other_deduction DECIMAL(14,2)
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_loan DECIMAL(14,2) DEFAULT 0;
    DECLARE v_disb DECIMAL(14,2) DEFAULT 0;
    DECLARE v_avail DECIMAL(14,2) DEFAULT 0;
    DECLARE v_ded DECIMAL(14,2) DEFAULT 0;
    DECLARE v_pending INT DEFAULT 0;
    DECLARE v_final INT DEFAULT 0;

    SELECT COUNT(*), MAX(Ln_Status_Cd), IFNULL(MAX(Loan_Amount), 0), IFNULL(MAX(Disbursed_Amount), 0)
    INTO v_cnt, v_status, v_loan, v_disb
    FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id;

    SELECT COUNT(*) INTO v_pending FROM mst_loan_account_disbursement
    WHERE Loan_Account_Id = p_loan_account_id AND Approved_By IS NULL;
    SELECT COUNT(*) INTO v_final FROM mst_loan_account_disbursement
    WHERE Loan_Account_Id = p_loan_account_id AND Approved_By IS NOT NULL AND IFNULL(Is_Final, 0) = 1;

    SET v_avail = v_loan - v_disb;
    SET p_gross = IFNULL(p_gross, v_avail);
    SET p_other_deduction = IFNULL(p_other_deduction, 0);

    IF v_cnt = 0 THEN
        SET v_err = 'Loan account not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Loan account is not active';
    ELSEIF v_final > 0 OR v_avail <= 0 THEN
        SET v_err = 'Loan is fully disbursed';
    ELSEIF p_gross <= 0 THEN
        SET v_err = 'Gross amount must be greater than zero';
    ELSEIF p_gross > v_avail THEN
        SET v_err = CONCAT('Gross amount cannot exceed the undisbursed amount (', FORMAT(v_avail, 2), ')');
    ELSEIF p_other_deduction < 0 THEN
        SET v_err = 'Other deduction cannot be negative';
    END IF;

    IF v_err IS NULL THEN
        CALL USP_LOAN_DISB_CHARGES(p_loan_account_id, p_gross);
        SELECT IFNULL(SUM(Net_Amount), 0) INTO v_ded FROM tmp_loan_disb_charges;
    ELSE
        DROP TEMPORARY TABLE IF EXISTS tmp_loan_disb_charges;
        CREATE TEMPORARY TABLE tmp_loan_disb_charges (
            Row_No INT, Loan_Charge_Id BIGINT, Charge_Id INT, Charge_Name VARCHAR(100), Deduct_During_Cd INT,
            Ledger_Id INT, Source VARCHAR(20), Charge_Amount DECIMAL(12,2), Tax_Amount DECIMAL(12,2),
            Waived_Amount DECIMAL(12,2), Net_Amount DECIMAL(12,2)
        );
    END IF;

    SELECT IF(v_err IS NULL, 'SUCCESS', 'ERROR') AS status,
           IFNULL(v_err, IF(v_pending > 0, 'Preview generated (a disbursement is waiting for approval)', 'Preview generated')) AS message,
           p_loan_account_id AS Loan_Account_Id,
           v_loan AS Loan_Amount,
           v_disb AS Disbursed_Amount,
           v_avail AS Undisbursed_Amount,
           v_pending AS Pending_Disbursements,
           p_gross AS Gross_Amount,
           v_ded AS Charge_Deduction,
           p_other_deduction AS Other_Deduction,
           IF(v_err IS NULL, p_gross - v_ded - p_other_deduction, NULL) AS Net_Amount,
           IF(v_err IS NULL AND v_disb + p_gross >= v_loan, 1, 0) AS Will_Be_Final;

    SELECT Loan_Charge_Id, Charge_Id, Charge_Name, Deduct_During_Cd, FN_LOAN_OPT_DESC(23, Deduct_During_Cd) AS Deduct_During_Desc,
           Source, Charge_Amount, Tax_Amount, Waived_Amount, Net_Amount
    FROM tmp_loan_disb_charges ORDER BY Row_No;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_DISB_CHARGES` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DISB_CHARGES`(IN p_acct BIGINT, IN p_gross DECIMAL(14,2))
BEGIN
    DECLARE v_app BIGINT;
    DECLARE v_scheme INT;
    DECLARE v_first INT DEFAULT 1;

    SELECT MAX(la.Application_Id), MAX(ap.Scheme_Id) INTO v_app, v_scheme
    FROM mst_loan_account la JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE la.Loan_Account_Id = p_acct;

    SET v_first = IF(EXISTS (SELECT 1 FROM mst_loan_account_disbursement
                             WHERE Loan_Account_Id = p_acct AND Approved_By IS NOT NULL), 0, 1);

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_disb_charges;
    CREATE TEMPORARY TABLE tmp_loan_disb_charges (
        Row_No INT AUTO_INCREMENT PRIMARY KEY,
        Loan_Charge_Id BIGINT NULL,
        Charge_Id INT NULL,
        Charge_Name VARCHAR(100) NULL,
        Deduct_During_Cd INT NULL,
        Ledger_Id INT NULL,
        Source VARCHAR(20) NOT NULL,
        Charge_Amount DECIMAL(12,2) NOT NULL DEFAULT 0,
        Tax_Amount DECIMAL(12,2) NOT NULL DEFAULT 0,
        Waived_Amount DECIMAL(12,2) NOT NULL DEFAULT 0,
        Net_Amount DECIMAL(12,2) NOT NULL DEFAULT 0
    );

    INSERT INTO tmp_loan_disb_charges (Loan_Charge_Id, Charge_Id, Charge_Name, Deduct_During_Cd, Ledger_Id, Source,
                                       Charge_Amount, Tax_Amount, Waived_Amount, Net_Amount)
    SELECT ch.Loan_Charge_Id, ch.Charge_Id, c.Charge_Name, c.Deduct_During_Cd, NULLIF(c.Charges_Gl, 0), 'application',
           ch.Charge_Amount, ch.Tax_Amount, IFNULL(ch.Waived_Amount, 0), ch.Total_Charge - IFNULL(ch.Waived_Amount, 0)
    FROM mst_loan_application_charge ch
    LEFT JOIN mst_loan_charges c ON c.Charge_Id = ch.Charge_Id
    WHERE ch.Loan_Application_Id = v_app AND ch.Tr_Status_Cd = 1;

    INSERT INTO tmp_loan_disb_charges (Loan_Charge_Id, Charge_Id, Charge_Name, Deduct_During_Cd, Ledger_Id, Source,
                                       Charge_Amount, Tax_Amount, Waived_Amount, Net_Amount)
    SELECT NULL, x.Charge_Id, x.Charge_Name, x.Deduct_During_Cd, x.Ledger_Id, 'scheme', x.amt, x.tax, 0, x.amt + x.tax
    FROM (
        SELECT c.Charge_Id, c.Charge_Name, c.Deduct_During_Cd, NULLIF(c.Charges_Gl, 0) AS Ledger_Id,
               FN_LOAN_CHARGE_AMOUNT(c.Charge_Id, p_gross) AS amt,
               FN_LOAN_CHARGE_TAX(c.Charge_Id, FN_LOAN_CHARGE_AMOUNT(c.Charge_Id, p_gross)) AS tax
        FROM mst_loan_scheme_charges sc
        JOIN mst_loan_charges c ON c.Charge_Id = sc.Charge_Id
        WHERE sc.Scheme_Id = v_scheme AND sc.Is_Active = 1 AND c.Is_Active = 1 AND c.Deduct_During_Cd IN (4, 5)
          AND ((v_first = 1 AND NOT EXISTS (SELECT 1 FROM mst_loan_application_charge e
                                            WHERE e.Loan_Application_Id = v_app AND e.Charge_Id = c.Charge_Id
                                              AND e.Tr_Status_Cd IN (1, 2)))
               OR (v_first = 0 AND c.Figure_Cd = 2))
    ) x
    WHERE x.amt > 0;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_DISB_POST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_DISB_POST`(
    IN p_disbursement_id BIGINT,
    IN p_user_id INT,
    OUT p_voucher_id BIGINT,
    OUT p_voucher_no VARCHAR(25),
    OUT p_note VARCHAR(255),
    OUT p_reschedule_amount DECIMAL(14,2),
    OUT p_err VARCHAR(255)
)
BEGIN
    DECLARE v_acct BIGINT;
    DECLARE v_app BIGINT;
    DECLARE v_gross DECIMAL(14,2);
    DECLARE v_charge DECIMAL(14,2);
    DECLARE v_other DECIMAL(14,2);
    DECLARE v_net DECIMAL(14,2);
    DECLARE v_mode INT;
    DECLARE v_date DATE;
    DECLARE v_final INT;
    DECLARE v_no VARCHAR(25);
    DECLARE v_loan DECIMAL(14,2);
    DECLARE v_disb DECIMAL(14,2);
    DECLARE v_ded DECIMAL(14,2) DEFAULT 0;
    DECLARE v_loan_gl INT;
    DECLARE v_branch INT;
    DECLARE v_ref VARCHAR(30);

    SET p_err = NULL;
    SET p_voucher_id = NULL;
    SET p_voucher_no = NULL;
    SET p_note = NULL;
    SET p_reschedule_amount = NULL;

    SELECT MAX(Loan_Account_Id), MAX(Gross_Amount), MAX(Charge_Deduction), MAX(Other_Deduction), MAX(Net_Amount),
           MAX(Payment_Mode_Cd), MAX(Disbursement_Date), MAX(IFNULL(Is_Final, 0)), MAX(Disbursement_No)
    INTO v_acct, v_gross, v_charge, v_other, v_net, v_mode, v_date, v_final, v_no
    FROM mst_loan_account_disbursement WHERE Disbursement_Id = p_disbursement_id;

    SELECT MAX(la.Application_Id), MAX(la.Loan_Amount), MAX(la.Disbursed_Amount), MAX(NULLIF(s.Loan_Ledger, 0)),
           MAX(ap.Branch_Id), MAX(la.Ref_Account_No)
    INTO v_app, v_loan, v_disb, v_loan_gl, v_branch, v_ref
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    WHERE la.Loan_Account_Id = v_acct FOR UPDATE;

    CALL USP_LOAN_DISB_CHARGES(v_acct, v_gross);
    SELECT IFNULL(SUM(Net_Amount), 0) INTO v_ded FROM tmp_loan_disb_charges;

    IF ABS(v_ded - v_charge) > 0.01 THEN
        SET p_err = CONCAT('Charges changed since this disbursement was entered (now ', FORMAT(v_ded, 2),
                           '); reject it and enter it again');
    ELSEIF v_disb + v_gross > v_loan + 0.005 THEN
        SET p_err = 'Disbursement would exceed the loan amount';
    END IF;

    IF p_err IS NULL THEN
        UPDATE mst_loan_account_disbursement SET Approved_By = p_user_id WHERE Disbursement_Id = p_disbursement_id;

        UPDATE mst_loan_account
        SET Disbursed_Amount = Disbursed_Amount + v_gross,
            Principal_Outstanding = Principal_Outstanding + v_gross
        WHERE Loan_Account_Id = v_acct;

        UPDATE mst_loan_application_bulk
        SET Disb_Amount = IFNULL(Disb_Amount, 0) + ROUND(IFNULL(Sanction_Amount, 0) * v_gross / v_loan, 2)
        WHERE Loan_Application_Id = v_app AND v_loan > 0;

        CALL USP_LOAN_VOUCHER_RESET();
        INSERT INTO tmp_loan_voucher_lines (Line_Role, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration)
        VALUES ('LOAN', v_loan_gl, v_gross, 0, CONCAT('Loan disbursed ', IFNULL(v_ref, ''))),
               (IF(v_mode = 4, 'SB ACCOUNT', 'CONTRA'), NULL, 0, v_net, CONCAT('Net disbursement ', IFNULL(v_no, ''))),
               ('OTHER DEDUCTION', (SELECT NULLIF(MAX(Value), 0) FROM mst_settings_global WHERE Id = 103), 0, v_other,
                'Other deduction');
        INSERT INTO tmp_loan_voucher_lines (Line_Role, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration)
        SELECT CONCAT('CHARGE ', IFNULL(Charge_Name, Charge_Id)), Ledger_Id, 0, Net_Amount, LEFT(CONCAT('Charge: ', IFNULL(Charge_Name, '')), 300)
        FROM tmp_loan_disb_charges;

        CALL USP_LOAN_VOUCHER_POST(v_branch, v_date, 2, v_mode, CONCAT('Loan disbursement ', IFNULL(v_no, ''), ' / ', IFNULL(v_ref, '')),
                                   p_user_id, p_voucher_id, p_voucher_no, p_note);

        UPDATE mst_loan_account_disbursement SET Voucher_Id = p_voucher_id WHERE Disbursement_Id = p_disbursement_id;

        UPDATE mst_loan_application_charge ch
        JOIN tmp_loan_disb_charges t ON t.Loan_Charge_Id = ch.Loan_Charge_Id
        SET ch.Tr_Status_Cd = 2, ch.Voucher_Id = p_voucher_id;

        INSERT INTO mst_loan_application_charge (
            Loan_Application_Id, Charge_Id, Charge_Amount, Tax_Amount, Total_Charge, Waived_Amount, Voucher_Id,
            Tr_Status_Cd, Created_By, Created_At
        )
        SELECT v_app, Charge_Id, Charge_Amount, Tax_Amount, Charge_Amount + Tax_Amount, 0, p_voucher_id, 2, p_user_id, NOW()
        FROM tmp_loan_disb_charges WHERE Loan_Charge_Id IS NULL;

        IF v_final = 1 AND ABS(v_disb + v_gross - v_loan) > 0.005
           AND NOT EXISTS (SELECT 1 FROM trans_loan_collection WHERE Account_Id = v_acct AND Tr_Status_Cd IN (1, 2)) THEN
            SET p_reschedule_amount = v_disb + v_gross;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_ELIGIBILITY_CHECK` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
