DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ELIGIBILITY_CHECK`(IN p_application_id BIGINT)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_type INT;
    DECLARE v_cust INT;
    DECLARE v_scheme INT;
    DECLARE v_amount DECIMAL(18,2);
    DECLARE v_tenure INT;
    DECLARE v_duration INT;
    DECLARE v_date DATE;
    DECLARE v_rate DECIMAL(7,2) DEFAULT 0;
    DECLARE v_sched INT DEFAULT 3;
    DECLARE v_ppy INT DEFAULT 12;
    DECLARE v_income DECIMAL(14,2) DEFAULT 0;
    DECLARE v_oblig DECIMAL(14,2) DEFAULT 0;
    DECLARE v_inst DECIMAL(14,2) DEFAULT 0;
    DECLARE v_monthly DECIMAL(14,2) DEFAULT 0;
    DECLARE v_foir DECIMAL(9,2) DEFAULT NULL;
    DECLARE v_max_monthly DECIMAL(14,2) DEFAULT 0;
    DECLARE v_per DECIMAL(14,2) DEFAULT 0;
    DECLARE v_r DOUBLE DEFAULT 0;
    DECLARE v_max_amt DECIMAL(18,2) DEFAULT 0;
    DECLARE v_slab_max DECIMAL(18,2) DEFAULT NULL;
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_mid INT;
    DECLARE v_minc DECIMAL(10,2);
    DECLARE v_mexp DECIMAL(10,2);
    DECLARE v_mobl DECIMAL(10,2);
    DECLARE v_failed INT DEFAULT 0;
    DECLARE v_not_eval INT DEFAULT 0;
    DECLARE cur_members CURSOR FOR
        SELECT Customer_Id, Monthly_Income, Monthly_Expense, Existing_Loan_Obligation
        FROM mst_loan_application_bulk WHERE Loan_Application_Id = p_application_id ORDER BY Id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    SELECT COUNT(*), MAX(Cust_Type_Cd), MAX(Cust_Id_Primay), MAX(Scheme_Id), MAX(Appl_Amount), MAX(Appl_Tenure),
           MAX(Repay_Duration_Cd), MAX(Application_Date)
    INTO v_cnt, v_type, v_cust, v_scheme, v_amount, v_tenure, v_duration, v_date
    FROM mst_loan_application WHERE Application_Id = p_application_id;

    CALL USP_LOAN_ELIGIBILITY_RESET();

    IF v_cnt > 0 THEN
        SET v_rate = IFNULL((SELECT sl.RoI FROM mst_loan_scheme_slab sl
                             WHERE sl.Scheme_Id = v_scheme AND sl.Is_Active = 1 AND (sl.Effect_From IS NULL OR sl.Effect_From <= v_date)
                               AND v_amount BETWEEN IFNULL(sl.Min_Amount, 0) AND IFNULL(sl.Max_Amount, 9999999999)
                             ORDER BY sl.Effect_From DESC, sl.Id DESC LIMIT 1),
                            IFNULL((SELECT MAX(RoI_Percent) FROM mst_loan_scheme WHERE Scheme_Id = v_scheme), 0));
        SELECT MAX(Max_Amount) INTO v_slab_max FROM mst_loan_scheme_slab
        WHERE Scheme_Id = v_scheme AND Is_Active = 1 AND (Effect_From IS NULL OR Effect_From <= v_date);

        SET v_sched = CASE v_duration WHEN 1 THEN 1 WHEN 2 THEN 2 ELSE 3 END;
        SET v_ppy = FN_LOAN_PERIODS_PER_YEAR('S', v_sched);

        IF v_type = 2 THEN
            CALL USP_LOAN_ELIGIBILITY_EVAL(v_cust, v_date, NULL, NULL, NULL, p_application_id);
            SELECT IFNULL(MAX(Monthly_Income), 0) INTO v_income FROM mst_member WHERE Member_Id = v_cust;

            SELECT IFNULL(SUM(x.Total_Due * FN_LOAN_PERIODS_PER_YEAR('S', CASE ap.Repay_Duration_Cd WHEN 1 THEN 1 WHEN 2 THEN 2 ELSE 3 END) / 12), 0)
            INTO v_oblig
            FROM mst_loan_account la
            JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
            JOIN trans_loanac_schedule x ON x.Loan_Account_Id = la.Loan_Account_Id AND x.Installment_No = 1
            WHERE la.Ln_Status_Cd = 1 AND ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = v_cust
              AND ap.Application_Id <> p_application_id;
        ELSE
            OPEN cur_members;
            read_loop: LOOP
                FETCH cur_members INTO v_mid, v_minc, v_mexp, v_mobl;
                IF v_done = 1 THEN
                    LEAVE read_loop;
                END IF;
                CALL USP_LOAN_ELIGIBILITY_EVAL(v_mid, v_date, v_minc, v_mexp, v_mobl, p_application_id);
                SET v_income = v_income + IFNULL(v_minc, 0);
                SET v_oblig = v_oblig + IFNULL(v_mobl, 0);
            END LOOP;
            CLOSE cur_members;
        END IF;

        CALL USP_LOAN_SCHEDULE_BUILD(v_amount, v_rate, v_tenure, v_sched, 1, 1, v_date, NULL, 0);
        SELECT IFNULL(MAX(Total_Due), 0) INTO v_inst FROM tmp_loan_schedule WHERE Installment_No = 1;
        SET v_monthly = ROUND(v_inst * v_ppy / 12, 2);

        IF v_income > 0 THEN
            SET v_foir = ROUND((v_oblig + v_monthly) / v_income * 100, 2);
            SET v_max_monthly = GREATEST(0, v_income * 0.5 - v_oblig);
            SET v_per = v_max_monthly * 12 / v_ppy;
            SET v_r = v_rate / 100 / v_ppy;
            SET v_max_amt = IF(v_r = 0, v_per * v_tenure, v_per * (1 - POW(1 + v_r, -v_tenure)) / v_r);
            IF v_slab_max IS NOT NULL AND v_max_amt > v_slab_max THEN
                SET v_max_amt = v_slab_max;
            END IF;
            SET v_max_amt = FLOOR(v_max_amt * 100) / 100;
        END IF;
    END IF;

    SELECT IFNULL(SUM(Is_Mandatory = 1 AND IFNULL(Passed, 1) = 0), 0), IFNULL(SUM(Passed IS NULL), 0)
    INTO v_failed, v_not_eval
    FROM tmp_loan_eligibility;

    SELECT
        IF(v_cnt = 0, 'ERROR', 'SUCCESS') AS status,
        IF(v_cnt = 0, 'Loan application not found', 'Eligibility evaluated') AS message,
        p_application_id AS Application_Id,
        v_type AS Cust_Type_Cd,
        IF(v_failed > 0, 0, 1) AS All_Mandatory_Passed,
        v_not_eval AS Not_Evaluated_Count,
        v_income AS Monthly_Income,
        v_oblig AS Existing_Obligation,
        v_monthly AS Proposed_Monthly_Installment,
        v_rate AS Interest_Rate,
        v_foir AS Foir_Percent,
        v_max_amt AS Max_Eligible_Amount;

    SELECT Member_Id, Member_Name, Param_Id, Parameter_Name, Rule_Text, Actual_Value, Passed, Is_Mandatory
    FROM tmp_loan_eligibility ORDER BY Row_No;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_ELIGIBILITY_EVAL` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ELIGIBILITY_EVAL`(
    IN p_member_id INT,
    IN p_as_on DATE,
    IN p_income DECIMAL(12,2),
    IN p_expense DECIMAL(12,2),
    IN p_obligation DECIMAL(12,2),
    IN p_exclude_app BIGINT
)
BEGIN
    DECLARE v_name VARCHAR(150) DEFAULT NULL;
    DECLARE v_dob DATE DEFAULT NULL;
    DECLARE v_age INT DEFAULT NULL;
    DECLARE v_join DATE DEFAULT NULL;
    DECLARE v_income DECIMAL(12,2) DEFAULT NULL;
    DECLARE v_expense DECIMAL(12,2) DEFAULT NULL;
    DECLARE v_overdue DECIMAL(14,2) DEFAULT 0;
    DECLARE v_active INT DEFAULT 0;
    DECLARE v_cycle INT DEFAULT 1;
    DECLARE v_kyc INT DEFAULT 0;

    SET p_as_on = IFNULL(p_as_on, CURDATE());

    SELECT MAX(Member_Name), MAX(Date_of_Birth), MAX(Age), MAX(Joining_Date), MAX(Monthly_Income), MAX(Monthly_Expense)
    INTO v_name, v_dob, v_age, v_join, v_income, v_expense
    FROM mst_member WHERE Member_Id = p_member_id;

    SET v_income = IFNULL(p_income, v_income);
    SET v_expense = IFNULL(p_expense, v_expense);
    SET v_overdue = FN_LOAN_MEMBER_OVERDUE(p_member_id, p_as_on);
    SET v_kyc = FN_LOAN_MEMBER_KYC_OK(p_member_id);

    SELECT COUNT(*) INTO v_active
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE la.Ln_Status_Cd = 1 AND ap.Application_Id <> IFNULL(p_exclude_app, 0)
      AND ((ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = p_member_id)
           OR EXISTS (SELECT 1 FROM mst_loan_application_bulk b WHERE b.Loan_Application_Id = ap.Application_Id AND b.Customer_Id = p_member_id));

    SELECT COUNT(*) + 1 INTO v_cycle
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE ap.Application_Id <> IFNULL(p_exclude_app, 0)
      AND ((ap.Cust_Type_Cd = 2 AND ap.Cust_Id_Primay = p_member_id)
           OR EXISTS (SELECT 1 FROM mst_loan_application_bulk b WHERE b.Loan_Application_Id = ap.Application_Id AND b.Customer_Id = p_member_id));

    INSERT INTO tmp_loan_eligibility (Member_Id, Member_Name, Param_Id, Parameter_Name, Rule_Text, Actual_Value, Passed, Is_Mandatory)
    SELECT p_member_id, v_name, z.Param_Id, z.Parameter_Name, z.Parameter_Value,
           IF(z.actual IS NULL, NULL, CAST(ROUND(z.actual, 2) AS CHAR)),
           CASE
               WHEN z.mapped = 0 OR z.Operator IN ('BETWEEN', 'IN') OR z.Req_Value IS NULL THEN NULL
               WHEN z.actual IS NULL THEN 0
               WHEN z.Operator = '='  THEN IF(z.actual =  z.Req_Value, 1, 0)
               WHEN z.Operator = '!=' THEN IF(z.actual <> z.Req_Value, 1, 0)
               WHEN z.Operator = '>'  THEN IF(z.actual >  z.Req_Value, 1, 0)
               WHEN z.Operator = '>=' THEN IF(z.actual >= z.Req_Value, 1, 0)
               WHEN z.Operator = '<'  THEN IF(z.actual <  z.Req_Value, 1, 0)
               WHEN z.Operator = '<=' THEN IF(z.actual <= z.Req_Value, 1, 0)
               ELSE NULL
           END,
           z.Is_Mandatory
    FROM (
        SELECT p.Param_Id, p.Parameter_Name, p.Parameter_Value, p.Operator, p.Req_Value, p.Is_Mandatory,
               CASE
                   WHEN LOWER(p.Parameter_Name) LIKE '%member%' AND LOWER(p.Parameter_Name) LIKE '%age%' THEN 1
                   WHEN LOWER(p.Parameter_Name) LIKE '%age%' THEN 1
                   WHEN LOWER(p.Parameter_Name) LIKE '%income%' THEN 1
                   WHEN LOWER(p.Parameter_Name) LIKE '%expense%' THEN 1
                   WHEN LOWER(p.Parameter_Name) LIKE '%overdue%' THEN 1
                   WHEN LOWER(p.Parameter_Name) LIKE '%obligation%' THEN 1
                   WHEN LOWER(p.Parameter_Name) LIKE '%active loan%' THEN 1
                   WHEN LOWER(p.Parameter_Name) LIKE '%cycle%' THEN 1
                   WHEN LOWER(p.Parameter_Name) LIKE '%kyc%' THEN 1
                   ELSE 0
               END AS mapped,
               CASE
                   WHEN LOWER(p.Parameter_Name) LIKE '%member%' AND LOWER(p.Parameter_Name) LIKE '%age%' THEN
                       IF(v_join IS NULL, NULL, CASE p.Value_Cd
                           WHEN 1 THEN DATEDIFF(p_as_on, v_join)
                           WHEN 3 THEN TIMESTAMPDIFF(YEAR, v_join, p_as_on)
                           ELSE TIMESTAMPDIFF(MONTH, v_join, p_as_on) END)
                   WHEN LOWER(p.Parameter_Name) LIKE '%age%' THEN
                       IF(v_dob IS NULL, IF(v_age IS NULL OR p.Value_Cd IN (1, 2), NULL, v_age), CASE p.Value_Cd
                           WHEN 1 THEN DATEDIFF(p_as_on, v_dob)
                           WHEN 2 THEN TIMESTAMPDIFF(MONTH, v_dob, p_as_on)
                           ELSE TIMESTAMPDIFF(YEAR, v_dob, p_as_on) END)
                   WHEN LOWER(p.Parameter_Name) LIKE '%income%' THEN v_income
                   WHEN LOWER(p.Parameter_Name) LIKE '%expense%' THEN v_expense
                   WHEN LOWER(p.Parameter_Name) LIKE '%overdue%' THEN v_overdue
                   WHEN LOWER(p.Parameter_Name) LIKE '%obligation%' THEN IFNULL(p_obligation, 0)
                   WHEN LOWER(p.Parameter_Name) LIKE '%active loan%' THEN v_active
                   WHEN LOWER(p.Parameter_Name) LIKE '%cycle%' THEN v_cycle
                   WHEN LOWER(p.Parameter_Name) LIKE '%kyc%' THEN v_kyc
                   ELSE NULL
               END AS actual
        FROM mst_loan_eligibility_parameter p
        WHERE p.Is_Active = 1 AND (p.Effective_From IS NULL OR p.Effective_From <= p_as_on)
        ORDER BY p.Param_Id
    ) z;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_ELIGIBILITY_PARAMETER_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
