/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ELIGIBILITY_PARAMETER_EDIT`(
    IN p_param_id INT,
    IN p_operator VARCHAR(10),
    IN p_req_value DECIMAL(14,2),
    IN p_value_cd INT,
    IN p_parameter_value VARCHAR(500),
    IN p_is_mandatory TINYINT,
    IN p_effective_from DATE,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_name VARCHAR(150);
    DECLARE v_type VARCHAR(20);
    DECLARE v_op VARCHAR(10);
    DECLARE v_req DECIMAL(14,2) DEFAULT NULL;
    DECLARE v_value_cd INT DEFAULT NULL;
    DECLARE v_unit VARCHAR(100) DEFAULT NULL;
    DECLARE v_text VARCHAR(500);
    DECLARE v_val_txt VARCHAR(50);

    SET v_op = TRIM(IFNULL(p_operator, ''));
    SET v_text = NULLIF(TRIM(IFNULL(p_parameter_value, '')), '');

    SELECT COUNT(*), MAX(Parameter_Name), MAX(Data_Type)
    INTO v_cnt, v_name, v_type
    FROM mst_loan_eligibility_parameter
    WHERE Param_Id = p_param_id;

    IF p_param_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Loan eligibility parameter not found';
    END IF;

    IF v_err IS NULL AND v_op IN ('BETWEEN', 'IN') THEN
        SET v_err = 'BETWEEN and IN need more than one value; use two parameters instead';
    ELSEIF v_err IS NULL AND v_op NOT IN ('=', '!=', '>', '>=', '<', '<=') THEN
        SET v_err = 'Operator must be one of =, !=, >, >=, <, <=';
    ELSEIF v_err IS NULL AND v_type IN ('BOOLEAN', 'TEXT') AND v_op NOT IN ('=', '!=') THEN
        SET v_err = CONCAT('Operator for ', v_type, ' parameters must be = or !=');
    END IF;

    IF v_err IS NULL THEN
        IF v_type IN ('NUMBER', 'AMOUNT', 'PERCENTAGE', 'BOOLEAN') THEN
            SET v_req = p_req_value;
            IF v_req IS NULL THEN
                SET v_err = 'Required value is required';
            ELSEIF v_req < 0 OR v_req > 9999999999.99 THEN
                SET v_err = 'Required value must be between 0 and 9999999999.99';
            ELSEIF v_type = 'PERCENTAGE' AND v_req > 100 THEN
                SET v_err = 'Percentage value cannot be more than 100';
            ELSEIF v_type = 'BOOLEAN' AND v_req NOT IN (0, 1) THEN
                SET v_err = 'Boolean value must be 1 (Yes) or 0 (No)';
            END IF;
        ELSEIF v_type = 'TEXT' AND v_text IS NULL THEN
            SET v_err = 'Parameter value is required for TEXT parameters';
        ELSEIF v_type = 'DATE' AND (
            v_text IS NULL
            OR v_text NOT REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
            OR STR_TO_DATE(v_text, '%Y-%m-%d') IS NULL
        ) THEN
            SET v_err = 'Parameter value must be a date (YYYY-MM-DD) for DATE parameters';
        END IF;
    END IF;

    IF v_err IS NULL AND v_type = 'NUMBER' AND p_value_cd IS NOT NULL THEN
        SELECT COUNT(*), MAX(Opt_Description) INTO v_cnt, v_unit
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 7 AND Opt_Code = p_value_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid unit (value_cd)';
        ELSE
            SET v_value_cd = p_value_cd;
        END IF;
    END IF;

    IF v_err IS NULL AND p_is_mandatory IS NOT NULL AND p_is_mandatory NOT IN (0, 1) THEN
        SET v_err = 'Mandatory flag must be 1 or 0';
    END IF;

    IF v_err IS NULL AND p_is_active IS NOT NULL AND p_is_active NOT IN (0, 1) THEN
        SET v_err = 'Status must be 1 (active) or 0 (inactive)';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_param_id AS param_id, v_err AS message;
    ELSE
        IF v_text IS NULL THEN
            SET v_val_txt = CASE
                WHEN v_type = 'BOOLEAN' THEN IF(v_req = 1, 'Yes', 'No')
                ELSE TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(v_req AS CHAR)))
            END;
            SET v_text = CONCAT(
                IFNULL(v_name, ''), ' ', v_op, ' ', v_val_txt,
                IF(v_type = 'PERCENTAGE', '%', ''),
                IF(v_unit IS NOT NULL, CONCAT(' ', v_unit), '')
            );
        END IF;

        UPDATE mst_loan_eligibility_parameter
        SET Operator = v_op,
            Req_Value = v_req,
            Value_Cd = v_value_cd,
            Parameter_Value = v_text,
            Is_Mandatory = IFNULL(p_is_mandatory, Is_Mandatory),
            Effective_From = p_effective_from,
            Is_Active = IFNULL(p_is_active, Is_Active)
        WHERE Param_Id = p_param_id;

        SELECT 'SUCCESS' AS status, p_param_id AS param_id, 'Loan eligibility parameter updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_ELIGIBILITY_PARAMETER_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ELIGIBILITY_PARAMETER_LIST`(
    IN p_param_id INT,
    IN p_keyword VARCHAR(150),
    IN p_data_type VARCHAR(20),
    IN p_is_mandatory TINYINT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_loan_eligibility_parameter p
    WHERE (p_param_id IS NULL OR p.Param_Id = p_param_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(p.Parameter_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(p.Parameter_Value, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_data_type IS NULL OR p_data_type = '' OR p.Data_Type = UPPER(p_data_type))
      AND (p_is_mandatory IS NULL OR p.Is_Mandatory = p_is_mandatory)
      AND (p_is_active IS NULL OR p.Is_Active = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        p.Param_Id,
        p.Parameter_Name,
        p.Data_Type,
        p.Operator,
        p.Req_Value,
        p.Value_Cd,
        t.Opt_Description AS Value_Desc,
        p.Parameter_Value,
        p.Is_Mandatory,
        p.Is_Active,
        p.Effective_From,
        p.Created_By,
        p.Created_At
    FROM mst_loan_eligibility_parameter p
    LEFT JOIN mst_appl_options t ON t.Opt_Grp_Id = 7 AND t.Opt_Code = p.Value_Cd
    WHERE (p_param_id IS NULL OR p.Param_Id = p_param_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(p.Parameter_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(p.Parameter_Value, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_data_type IS NULL OR p_data_type = '' OR p.Data_Type = UPPER(p_data_type))
      AND (p_is_mandatory IS NULL OR p.Is_Mandatory = p_is_mandatory)
      AND (p_is_active IS NULL OR p.Is_Active = p_is_active)
    ORDER BY p.Parameter_Name ASC, p.Param_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
