DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ELIGIBILITY_PARAMETER_STATUS`(
    IN p_param_id INT,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current TINYINT DEFAULT NULL;

    SELECT COUNT(*), MAX(Is_Active) INTO v_cnt, v_current
    FROM mst_loan_eligibility_parameter
    WHERE Param_Id = p_param_id;

    IF p_param_id IS NULL OR v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_param_id AS param_id, NULL AS is_active,
               'Loan eligibility parameter not found' AS message;
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_param_id AS param_id, NULL AS is_active,
               'Status must be 1 (active) or 0 (inactive)' AS message;
    ELSEIF v_current = p_is_active THEN
        SELECT 'SUCCESS' AS status, p_param_id AS param_id, v_current AS is_active,
               IF(p_is_active = 1, 'Loan eligibility parameter is already active', 'Loan eligibility parameter is already inactive') AS message;
    ELSE
        UPDATE mst_loan_eligibility_parameter SET Is_Active = p_is_active WHERE Param_Id = p_param_id;

        SELECT 'SUCCESS' AS status, p_param_id AS param_id, p_is_active AS is_active,
               IF(p_is_active = 1, 'Loan eligibility parameter activated successfully', 'Loan eligibility parameter deactivated successfully') AS message;
    END IF;
END ;;
DELIMITER ;
