CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_ELIGIBILITY_RESET`()
BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_loan_eligibility;
    CREATE TEMPORARY TABLE tmp_loan_eligibility (
        Row_No INT AUTO_INCREMENT PRIMARY KEY,
        Member_Id INT NULL,
        Member_Name VARCHAR(150) NULL,
        Param_Id INT NOT NULL,
        Parameter_Name VARCHAR(150) NULL,
        Rule_Text VARCHAR(500) NULL,
        Actual_Value VARCHAR(50) NULL,
