/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_FACTS_FILL`(IN p_as_on DATE)
BEGIN
    SET p_as_on = IFNULL(p_as_on, CURDATE());

    UPDATE tmp_loan_facts f
    JOIN mst_loan_account la ON la.Loan_Account_Id = f.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    SET f.Ln_Status_Cd = la.Ln_Status_Cd,
        f.Paid_P = FN_LOAN_PAID(f.Loan_Account_Id, p_as_on, 'P'),
        f.Paid_I = FN_LOAN_PAID(f.Loan_Account_Id, p_as_on, 'I'),
        f.Collected_Total = FN_LOAN_PAID(f.Loan_Account_Id, p_as_on, 'T'),
        f.Penalty_Due = IF(la.Ln_Status_Cd = 1, FN_LOAN_PENALTY_DUE(f.Loan_Account_Id, p_as_on), 0),
        f.Is_NPA_Flag = IFNULL(la.Is_NPA, 0),
        f.NPA_Days = IF(IFNULL(s.Is_NPA, 0) = 1 AND IFNULL(s.NPA_After_Days, 0) > 0, s.NPA_After_Days, 90),
        f.Disbursed_As_On = (SELECT IFNULL(SUM(d.Gross_Amount), 0) FROM mst_loan_account_disbursement d
                             WHERE d.Loan_Account_Id = f.Loan_Account_Id AND d.Approved_By IS NOT NULL
                               AND d.Disbursement_Date <= p_as_on),
        f.Outstanding = la.Principal_Outstanding;

    UPDATE tmp_loan_facts f
    SET f.Outstanding = GREATEST(0, f.Disbursed_As_On - f.Paid_P)
    WHERE p_as_on < CURDATE();

    DELETE FROM tmp_loan_fact_sched;

    INSERT INTO tmp_loan_fact_sched (Loan_Account_Id, Schedule_Id, Installment_No, Due_Date, Total_Due, Pd, Idue, Cum_P, Cum_I)
    SELECT s.Loan_Account_Id, s.Schedule_Id, s.Installment_No, s.Due_Date, s.Total_Due,
           s.Principal_Due - IFNULL(s.Principal_Waived, 0),
           s.Interest_Due - IFNULL(s.Interest_Waived, 0),
           SUM(s.Principal_Due - IFNULL(s.Principal_Waived, 0)) OVER w,
           SUM(s.Interest_Due - IFNULL(s.Interest_Waived, 0)) OVER w
    FROM trans_loanac_schedule s
    JOIN tmp_loan_facts f ON f.Loan_Account_Id = s.Loan_Account_Id
    WHERE IFNULL(s.Is_Active, 1) = 1
    WINDOW w AS (PARTITION BY s.Loan_Account_Id ORDER BY s.Installment_No, s.Schedule_Id);

    UPDATE tmp_loan_fact_sched x
    JOIN tmp_loan_facts f ON f.Loan_Account_Id = x.Loan_Account_Id
    SET x.Paid_Pr = LEAST(x.Pd, GREATEST(0, f.Paid_P - (x.Cum_P - x.Pd))),
        x.Paid_In = LEAST(x.Idue, GREATEST(0, f.Paid_I - (x.Cum_I - x.Idue)));

    UPDATE tmp_loan_facts f
    JOIN (
        SELECT x.Loan_Account_Id,
               COUNT(*) AS Tenure,
               MAX(x.Due_Date) AS Last_Due,
               SUM(IF(x.Paid_Pr + 0.005 >= x.Pd AND x.Paid_In + 0.005 >= x.Idue, 1, 0)) AS Paid_Inst,
               MIN(IF(x.Paid_Pr + 0.005 < x.Pd OR x.Paid_In + 0.005 < x.Idue, x.Due_Date, NULL)) AS Oldest_Unpaid,
               MIN(IF((x.Paid_Pr + 0.005 < x.Pd OR x.Paid_In + 0.005 < x.Idue) AND x.Due_Date >= p_as_on, x.Due_Date, NULL)) AS Next_Due,
               SUM(IF(x.Due_Date <= p_as_on, x.Pd - x.Paid_Pr, 0)) AS Due_P,
               SUM(IF(x.Due_Date <= p_as_on, x.Idue - x.Paid_In, 0)) AS Due_I,
               SUM(IF(x.Due_Date < p_as_on, x.Pd - x.Paid_Pr, 0)) AS Od_P,
               SUM(IF(x.Due_Date < p_as_on, x.Idue - x.Paid_In, 0)) AS Od_I,
               SUM(IF(x.Due_Date = p_as_on, x.Pd + x.Idue - x.Paid_Pr - x.Paid_In, 0)) AS Due_Today,
               SUM(IF(x.Due_Date < p_as_on AND (x.Paid_Pr + 0.005 < x.Pd OR x.Paid_In + 0.005 < x.Idue), 1, 0)) AS Od_Inst,
               MAX(IF(x.Installment_No = 1, x.Total_Due, NULL)) AS Inst_Amount
        FROM tmp_loan_fact_sched x
        GROUP BY x.Loan_Account_Id
    ) a ON a.Loan_Account_Id = f.Loan_Account_Id
    SET f.Tenure = a.Tenure,
        f.Last_Due = a.Last_Due,
        f.Paid_Inst = a.Paid_Inst,
        f.Oldest_Unpaid = a.Oldest_Unpaid,
        f.Next_Due_Date = a.Next_Due,
        f.Due_P = a.Due_P,
        f.Due_I = a.Due_I,
        f.Od_P = a.Od_P,
        f.Od_I = a.Od_I,
        f.Due_Today = a.Due_Today,
        f.Od_Installments = a.Od_Inst,
        f.Inst_Amount = a.Inst_Amount;

    UPDATE tmp_loan_facts f
    JOIN tmp_loan_fact_sched x ON x.Loan_Account_Id = f.Loan_Account_Id AND x.Due_Date = f.Next_Due_Date
    SET f.Next_Due_Amount = (x.Pd + x.Idue - x.Paid_Pr - x.Paid_In);

    UPDATE tmp_loan_facts f
    SET f.Dpd = IF(f.Oldest_Unpaid IS NOT NULL AND f.Oldest_Unpaid < p_as_on, DATEDIFF(p_as_on, f.Oldest_Unpaid), 0);

    UPDATE tmp_loan_facts f
    SET f.Bucket = CASE
            WHEN IFNULL(f.Ln_Status_Cd, 1) <> 1 THEN 'closed'
            WHEN f.Is_NPA_Flag = 1 OR f.Dpd >= f.NPA_Days THEN 'npa'
            WHEN f.Dpd > 0 THEN 'par'
            ELSE 'current'
        END;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_FACTS_RESET` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_FACTS_RESET`()
BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_loan_facts;
    CREATE TEMPORARY TABLE tmp_loan_facts (
        Loan_Account_Id BIGINT PRIMARY KEY,
        Ln_Status_Cd INT NULL,
        Paid_P DECIMAL(14,2) NOT NULL DEFAULT 0,
        Paid_I DECIMAL(14,2) NOT NULL DEFAULT 0,
        Collected_Total DECIMAL(14,2) NOT NULL DEFAULT 0,
        Penalty_Due DECIMAL(14,2) NOT NULL DEFAULT 0,
        Disbursed_As_On DECIMAL(14,2) NOT NULL DEFAULT 0,
        Outstanding DECIMAL(14,2) NOT NULL DEFAULT 0,
        Tenure INT NOT NULL DEFAULT 0,
        Paid_Inst INT NOT NULL DEFAULT 0,
        Inst_Amount DECIMAL(14,2) NULL,
        Last_Due DATE NULL,
        Oldest_Unpaid DATE NULL,
        Next_Due_Date DATE NULL,
        Next_Due_Amount DECIMAL(14,2) NOT NULL DEFAULT 0,
        Due_P DECIMAL(14,2) NOT NULL DEFAULT 0,
        Due_I DECIMAL(14,2) NOT NULL DEFAULT 0,
        Od_P DECIMAL(14,2) NOT NULL DEFAULT 0,
        Od_I DECIMAL(14,2) NOT NULL DEFAULT 0,
        Due_Today DECIMAL(14,2) NOT NULL DEFAULT 0,
        Od_Installments INT NOT NULL DEFAULT 0,
        Dpd INT NOT NULL DEFAULT 0,
        Is_NPA_Flag INT NOT NULL DEFAULT 0,
        NPA_Days INT NOT NULL DEFAULT 90,
        Bucket VARCHAR(10) NULL
    );

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_fact_sched;
    CREATE TEMPORARY TABLE tmp_loan_fact_sched (
        Loan_Account_Id BIGINT NOT NULL,
        Schedule_Id BIGINT NOT NULL PRIMARY KEY,
        Installment_No INT NOT NULL,
        Due_Date DATE NOT NULL,
        Total_Due DECIMAL(14,2) NOT NULL,
        Pd DECIMAL(14,2) NOT NULL,
        Idue DECIMAL(14,2) NOT NULL,
        Cum_P DECIMAL(14,2) NOT NULL,
        Cum_I DECIMAL(14,2) NOT NULL,
        Paid_Pr DECIMAL(14,2) NOT NULL DEFAULT 0,
        Paid_In DECIMAL(14,2) NOT NULL DEFAULT 0,
        KEY idx_fs_acct (Loan_Account_Id, Due_Date)
    );
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_INSPECTION_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_INSPECTION_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_inspection_id BIGINT,
    IN p_application_id BIGINT,
    IN p_customer_id INT,
    IN p_inspection_date DATE,
    IN p_fo_id INT,
    IN p_all_verified TINYINT,
    IN p_recommended_amount DECIMAL(18,2),
    IN p_notes TEXT,
    IN p_result_cd INT,
    IN p_latitude DECIMAL(10,8),
    IN p_longitude DECIMAL(11,8),
    IN p_photo_path VARCHAR(100),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_status INT;
    DECLARE v_type INT;
    DECLARE v_p INT;
    DECLARE v_j1 INT;
    DECLARE v_j2 INT;
    DECLARE v_date DATE;
    DECLARE v_amount DECIMAL(18,2);
    DECLARE v_branch INT;
    DECLARE v_customer INT;
    DECLARE v_id BIGINT;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    ELSEIF v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Loan_Application_Id) INTO v_cnt, v_app
        FROM mst_loan_application_inspection WHERE Inspection_Id = p_inspection_id FOR UPDATE;
        IF v_cnt = 0 THEN
            SET v_err = 'Inspection not found';
        END IF;
    ELSE
        SET v_app = p_application_id;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Appl_Status_Cd), MAX(Cust_Type_Cd), MAX(Cust_Id_Primay), MAX(Cust_Id_Joint1), MAX(Cust_Id_Joint2),
               MAX(Application_Date), MAX(Appl_Amount), MAX(Branch_Id)
        INTO v_cnt, v_status, v_type, v_p, v_j1, v_j2, v_date, v_amount, v_branch
        FROM mst_loan_application WHERE Application_Id = v_app;

        SET v_customer = IF(v_type = 2, IFNULL(p_customer_id, v_p), p_customer_id);

        IF v_app IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan application not found';
        ELSEIF v_status NOT IN (1, 4) THEN
            SET v_err = 'Field verification is only allowed for Submitted or Resubmission applications';
        ELSEIF EXISTS (SELECT 1 FROM mst_loan_account WHERE Application_Id = v_app)
            OR FN_LOAN_APPL_STAGE(v_app) = 'sanctioned' THEN
            SET v_err = 'Application is already sanctioned';
        ELSEIF p_inspection_date IS NULL THEN
            SET v_err = 'Inspection date is required';
        ELSEIF p_inspection_date > CURDATE() THEN
            SET v_err = 'Inspection date cannot be in the future';
        ELSEIF p_inspection_date < v_date THEN
            SET v_err = 'Inspection date cannot be before the application date';
        ELSEIF FN_LOAN_OPT_DESC(38, p_result_cd) IS NULL THEN
            SET v_err = 'Inspection result must be 1 (Positive), 2 (Negative) or 3 (Re-Inspection)';
        ELSEIF NOT EXISTS (SELECT 1 FROM mst_staff WHERE Staff_Id = p_fo_id AND IFNULL(Status, 0) = 1) THEN
            SET v_err = 'Active field officer not found';
        ELSEIF p_recommended_amount IS NOT NULL AND (p_recommended_amount <= 0 OR p_recommended_amount > v_amount) THEN
            SET v_err = CONCAT('Recommended amount must be greater than zero and not more than the applied amount (', FORMAT(v_amount, 2), ')');
        ELSEIF v_type = 2 AND v_customer NOT IN (v_p, IFNULL(v_j1, 0), IFNULL(v_j2, 0)) THEN
            SET v_err = 'Customer must be the borrower or a joint applicant';
        ELSEIF v_type = 1 AND v_customer IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM mst_loan_application_bulk WHERE Loan_Application_Id = v_app AND Customer_Id = v_customer) THEN
            SET v_err = 'Customer must be a member on this group application';
        ELSEIF p_latitude IS NOT NULL AND (p_latitude < -90 OR p_latitude > 90) THEN
            SET v_err = 'Latitude must be between -90 and 90';
        ELSEIF p_longitude IS NOT NULL AND (p_longitude < -180 OR p_longitude > 180) THEN
            SET v_err = 'Longitude must be between -180 and 180';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_inspection_id AS inspection_id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_application_inspection (
            Loan_Application_Id, Customer_Id, Inspection_Date, FO_Id, All_Verified, Recommended_Amount, Inspection_Notes,
            Inspection_Result_Cd, Latitude, Longitude, Photo_Path, Created_By, Created_At
        ) VALUES (
            v_app, v_customer, p_inspection_date, p_fo_id, IFNULL(p_all_verified, 1), p_recommended_amount,
            NULLIF(TRIM(IFNULL(p_notes, '')), ''), p_result_cd, p_latitude, p_longitude, p_photo_path, p_user_id, NOW()
        );
        SET v_id = LAST_INSERT_ID();
        SELECT 'SUCCESS' AS status, v_id AS inspection_id,
               CONCAT('Field verification saved (', FN_LOAN_OPT_DESC(38, p_result_cd), ')') AS message;
    ELSE
        UPDATE mst_loan_application_inspection
        SET Customer_Id = v_customer,
            Inspection_Date = p_inspection_date,
            FO_Id = p_fo_id,
            All_Verified = IFNULL(p_all_verified, 1),
            Recommended_Amount = p_recommended_amount,
            Inspection_Notes = NULLIF(TRIM(IFNULL(p_notes, '')), ''),
            Inspection_Result_Cd = p_result_cd,
            Latitude = p_latitude,
            Longitude = p_longitude,
            Photo_Path = p_photo_path
        WHERE Inspection_Id = p_inspection_id;
        SELECT 'SUCCESS' AS status, p_inspection_id AS inspection_id, 'Field verification updated' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_INSPECTION_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_INSPECTION_LIST`(
    IN p_inspection_id BIGINT,
    IN p_application_id BIGINT,
    IN p_fo_id INT,
    IN p_result_cd INT,
    IN p_branch_id INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_pending_only TINYINT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_insp_ids;
    CREATE TEMPORARY TABLE tmp_loan_insp_ids (
        Row_Key BIGINT PRIMARY KEY,
        Application_Id BIGINT NOT NULL,
        Inspection_Id BIGINT NULL,
        Sort_Date DATE NULL
    );

    IF IFNULL(p_pending_only, 0) = 1 THEN
        INSERT INTO tmp_loan_insp_ids (Row_Key, Application_Id, Inspection_Id, Sort_Date)
        SELECT a.Application_Id, a.Application_Id,
               (SELECT i.Inspection_Id FROM mst_loan_application_inspection i WHERE i.Loan_Application_Id = a.Application_Id
                ORDER BY i.Inspection_Date DESC, i.Inspection_Id DESC LIMIT 1),
               a.Application_Date
        FROM mst_loan_application a
        LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
        LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
        WHERE a.Appl_Status_Cd IN (1, 4)
          AND NOT EXISTS (SELECT 1 FROM mst_loan_account la WHERE la.Application_Id = a.Application_Id)
          AND IFNULL((SELECT i.Inspection_Result_Cd FROM mst_loan_application_inspection i WHERE i.Loan_Application_Id = a.Application_Id
                      ORDER BY i.Inspection_Date DESC, i.Inspection_Id DESC LIMIT 1), 3) = 3
          AND (p_application_id IS NULL OR a.Application_Id = p_application_id)
          AND (p_fo_id IS NULL OR a.FO_Id = p_fo_id)
          AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
          AND (p_from_date IS NULL OR a.Application_Date >= p_from_date)
          AND (p_to_date IS NULL OR a.Application_Date <= p_to_date)
          AND (p_keyword IS NULL OR p_keyword = ''
               OR a.Application_No LIKE CONCAT('%', p_keyword, '%')
               OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
               OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));
    ELSE
        INSERT INTO tmp_loan_insp_ids (Row_Key, Application_Id, Inspection_Id, Sort_Date)
        SELECT i.Inspection_Id, i.Loan_Application_Id, i.Inspection_Id, i.Inspection_Date
        FROM mst_loan_application_inspection i
        JOIN mst_loan_application a ON a.Application_Id = i.Loan_Application_Id
        LEFT JOIN mst_member pm ON pm.Member_Id = IFNULL(i.Customer_Id, IF(a.Cust_Type_Cd = 2, a.Cust_Id_Primay, NULL))
        LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
        WHERE (p_inspection_id IS NULL OR i.Inspection_Id = p_inspection_id)
          AND (p_application_id IS NULL OR i.Loan_Application_Id = p_application_id)
          AND (p_fo_id IS NULL OR i.FO_Id = p_fo_id)
          AND (p_result_cd IS NULL OR i.Inspection_Result_Cd = p_result_cd)
          AND (p_branch_id IS NULL OR a.Branch_Id = p_branch_id)
          AND (p_from_date IS NULL OR i.Inspection_Date >= p_from_date)
          AND (p_to_date IS NULL OR i.Inspection_Date <= p_to_date)
          AND (p_keyword IS NULL OR p_keyword = ''
               OR a.Application_No LIKE CONCAT('%', p_keyword, '%')
               OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
               OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));
    END IF;

    SELECT COUNT(*) INTO v_total FROM tmp_loan_insp_ids;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        i.Inspection_Id,
        a.Application_Id AS Loan_Application_Id,
        a.Application_No,
        a.Application_Date,
        a.Appl_Amount,
        a.Cust_Type_Cd,
        FN_LOAN_OPT_DESC(34, a.Cust_Type_Cd) AS Cust_Type_Desc,
        IFNULL(i.Customer_Id, IF(a.Cust_Type_Cd = 2, a.Cust_Id_Primay, NULL)) AS Customer_Id,
        IFNULL(cm.Member_Name, IF(a.Cust_Type_Cd = 1, pg.Group_Name, NULL)) AS Member_Name,
        IF(a.Cust_Type_Cd = 1, pg.Group_Name, NULL) AS Group_Name,
        s.Scheme_Name,
        i.Inspection_Date,
        IFNULL(i.FO_Id, a.FO_Id) AS FO_Id,
        fo.Employee_Code AS FO_Code,
        fo.Full_Name AS FO_Name,
        i.All_Verified,
        i.Recommended_Amount,
        i.Inspection_Notes,
        i.Inspection_Result_Cd,
        FN_LOAN_OPT_DESC(38, i.Inspection_Result_Cd) AS Inspection_Result_Desc,
        i.Latitude,
        i.Longitude,
        i.Photo_Path,
        a.Appl_Status_Cd,
        FN_LOAN_OPT_DESC(37, a.Appl_Status_Cd) AS Appl_Status_Desc,
        FN_LOAN_APPL_STAGE(a.Application_Id) AS Stage,
        a.Branch_Id,
        b.Branch_Name,
        i.Created_By,
        u.User_Name AS Created_By_Name,
        i.Created_At
    FROM tmp_loan_insp_ids t
    JOIN mst_loan_application a ON a.Application_Id = t.Application_Id
    LEFT JOIN mst_loan_application_inspection i ON i.Inspection_Id = t.Inspection_Id
    LEFT JOIN mst_member cm ON cm.Member_Id = IFNULL(i.Customer_Id, IF(a.Cust_Type_Cd = 2, a.Cust_Id_Primay, NULL))
    LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = a.Scheme_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = IFNULL(i.FO_Id, a.FO_Id)
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = a.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user u ON u.User_Id = i.Created_By
    ORDER BY t.Sort_Date DESC, t.Row_Key DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
