DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_MC_CHECKER`(IN p_voucher_type INT, IN p_maker INT, IN p_user_id INT, OUT p_err VARCHAR(255))
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_roles VARCHAR(25);
    DECLARE v_dual INT DEFAULT 1;
    DECLARE v_is_checker INT DEFAULT 0;

    SET p_err = NULL;

    SELECT COUNT(*), MAX(Checker_Role_Id), MAX(IFNULL(DualAuth_Req, 1)) INTO v_cnt, v_roles, v_dual
    FROM mst_settings_maker_checker
    WHERE Voucher_Type = p_voucher_type AND IFNULL(Is_Active, 0) = 1;

    SELECT COUNT(*) INTO v_is_checker
    FROM mst_user_role ur
    JOIN mst_role r ON r.Id = ur.Role_Id AND IFNULL(r.Status, 0) = 1
    WHERE ur.User_Id = p_user_id AND IFNULL(ur.Status, 0) = 1
      AND (r.Is_Admin = 1 OR (v_cnt > 0 AND FIND_IN_SET(ur.Role_Id, REPLACE(IFNULL(v_roles, ''), ' ', '')) > 0));

    IF v_is_checker = 0 THEN
        SET p_err = 'You do not have a checker role to approve or reject this entry';
    ELSEIF (v_cnt = 0 OR v_dual = 1) AND p_maker = p_user_id THEN
        SET p_err = 'The maker cannot approve or reject their own entry';
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
