DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_MEMBER_LEDGER`(
    IN p_loan_account_id BIGINT,
    IN p_member_id INT,
    IN p_from_date DATE,
    IN p_to_date DATE
)
BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_loan_ledger_accts;
    CREATE TEMPORARY TABLE tmp_loan_ledger_accts (Loan_Account_Id BIGINT PRIMARY KEY);

    INSERT INTO tmp_loan_ledger_accts
    SELECT la.Loan_Account_Id
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE (p_loan_account_id IS NOT NULL OR p_member_id IS NOT NULL)
      AND (p_loan_account_id IS NULL OR la.Loan_Account_Id = p_loan_account_id)
      AND (p_member_id IS NULL
           OR (ap.Cust_Type_Cd = 2 AND p_member_id IN (ap.Cust_Id_Primay, IFNULL(ap.Cust_Id_Joint1, 0), IFNULL(ap.Cust_Id_Joint2, 0)))
           OR (ap.Cust_Type_Cd = 1 AND EXISTS (SELECT 1 FROM mst_loan_application_bulk bk
                                               WHERE bk.Loan_Application_Id = ap.Application_Id AND bk.Customer_Id = p_member_id)));

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_ledger;
    CREATE TEMPORARY TABLE tmp_loan_ledger (
        Row_No INT AUTO_INCREMENT PRIMARY KEY,
        Entry_Date DATE, Sort_Key BIGINT, Loan_Account_Id BIGINT, Entry_Type VARCHAR(20), Ref_No VARCHAR(40),
        Voucher_Id BIGINT, Narration VARCHAR(150), Debit DECIMAL(14,2), Credit DECIMAL(14,2),
        Interest DECIMAL(14,2), Penalty DECIMAL(14,2), Total DECIMAL(14,2), Status_Cd INT
    );

    INSERT INTO tmp_loan_ledger (Entry_Date, Sort_Key, Loan_Account_Id, Entry_Type, Ref_No, Voucher_Id, Narration, Debit, Credit,
                                 Interest, Penalty, Total, Status_Cd)
    SELECT d.Disbursement_Date, d.Disbursement_Id, d.Loan_Account_Id, 'disbursement', d.Disbursement_No, d.Voucher_Id,
           CONCAT('Disbursement (net ', FORMAT(d.Net_Amount, 2), ')'), d.Gross_Amount, 0, 0, 0, d.Gross_Amount, 2
    FROM mst_loan_account_disbursement d
    JOIN tmp_loan_ledger_accts a ON a.Loan_Account_Id = d.Loan_Account_Id
    WHERE d.Approved_By IS NOT NULL;

    INSERT INTO tmp_loan_ledger (Entry_Date, Sort_Key, Loan_Account_Id, Entry_Type, Ref_No, Voucher_Id, Narration, Debit, Credit,
                                 Interest, Penalty, Total, Status_Cd)
    SELECT IFNULL(c.Effect_Date, DATE(c.Collection_Date)), c.Collection_Id, c.Account_Id,
           IF(IFNULL(c.Payment_Mode_Cd, 0) = 5, 'adjustment', 'collection'),
           c.Trans_No, c.Voucher_Id, IFNULL(c.Ledger_Narration, 'Collection'),
           IF(c.Ledger_Narration LIKE 'Capitalization%', c.Interest_Capitalized, 0),
           IF(c.Ledger_Narration LIKE 'Waiver - Principal%', c.Total_Collected, c.Principal_Collected),
           IF(c.Ledger_Narration LIKE 'Waiver - Interest%', c.Total_Collected, c.Interest_Collected),
           c.Penalty_Collected, c.Total_Collected, c.Tr_Status_Cd
    FROM trans_loan_collection c
    JOIN tmp_loan_ledger_accts a ON a.Loan_Account_Id = c.Account_Id
    WHERE c.Tr_Status_Cd = 2;

    SELECT IFNULL(SUM(Debit - Credit), 0) AS Opening_Balance, COUNT(*) AS Opening_Entries
    FROM tmp_loan_ledger
    WHERE p_from_date IS NOT NULL AND Entry_Date < p_from_date;

    SELECT t.Entry_Date, t.Loan_Account_Id, la.Ref_Account_No AS Loan_Account_No, t.Entry_Type, t.Ref_No, t.Voucher_Id,
           v.Vou_No_Ref AS Voucher_No, t.Narration, t.Debit, t.Credit, t.Interest, t.Penalty, t.Total
    FROM tmp_loan_ledger t
    JOIN mst_loan_account la ON la.Loan_Account_Id = t.Loan_Account_Id
    LEFT JOIN trans_vouchers v ON v.Voucher_Id = t.Voucher_Id
    WHERE (p_from_date IS NULL OR t.Entry_Date >= p_from_date)
      AND (p_to_date IS NULL OR t.Entry_Date <= p_to_date)
    ORDER BY t.Entry_Date, FIELD(t.Entry_Type, 'disbursement', 'collection', 'adjustment'), t.Sort_Key;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_NPA_MARK` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_NPA_MARK`(IN p_loan_account_id BIGINT, IN p_is_npa TINYINT, IN p_user_id INT)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT;
    DECLARE v_old INT;

    SELECT COUNT(*), MAX(Ln_Status_Cd), MAX(IFNULL(Is_NPA, 0)) INTO v_cnt, v_status, v_old
    FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id FOR UPDATE;

    IF v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, NULL AS is_npa, 'Loan account not found' AS message;
    ELSEIF v_status <> 1 THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, v_old AS is_npa, 'Loan account is not active' AS message;
    ELSEIF p_is_npa IS NULL OR p_is_npa NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, v_old AS is_npa, 'is_npa must be true or false' AS message;
    ELSE
        UPDATE mst_loan_account SET Is_NPA = p_is_npa WHERE Loan_Account_Id = p_loan_account_id;
        SELECT 'SUCCESS' AS status, p_loan_account_id AS loan_account_id, p_is_npa AS is_npa,
               IF(p_is_npa = 1, 'Loan marked as NPA', 'NPA flag removed') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
