/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_OVERDUE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_OVERDUE_LIST`(
    IN p_branch_id INT,
    IN p_fo_id INT,
    IN p_group_id INT,
    IN p_scheme_id INT,
    IN p_min_dpd INT,
    IN p_max_dpd INT,
    IN p_as_on DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;
    DECLARE v_month DATE;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;
    SET p_as_on = IFNULL(p_as_on, CURDATE());
    SET v_month = DATE_FORMAT(p_as_on, '%Y-%m-01');

    CALL USP_LOAN_FACTS_RESET();

    INSERT INTO tmp_loan_facts (Loan_Account_Id)
    SELECT la.Loan_Account_Id
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    WHERE la.Ln_Status_Cd = 1
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
      AND (p_fo_id IS NULL OR ap.FO_Id = p_fo_id)
      AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
      AND (p_group_id IS NULL
           OR (ap.Cust_Type_Cd = 1 AND ap.Cust_Id_Primay = p_group_id)
           OR (ap.Cust_Type_Cd = 2 AND EXISTS (SELECT 1 FROM mst_member_group mg
                                               WHERE mg.Member_Id = ap.Cust_Id_Primay AND mg.Group_Id = p_group_id AND mg.Is_Active = 1)))
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(la.Ref_Account_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pm.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%'));

    CALL USP_LOAN_FACTS_FILL(p_as_on);

    DELETE FROM tmp_loan_facts
    WHERE Dpd <= 0
       OR (p_min_dpd IS NOT NULL AND Dpd < p_min_dpd)
       OR (p_max_dpd IS NOT NULL AND Dpd > p_max_dpd);

    SELECT COUNT(*) INTO v_total FROM tmp_loan_facts;

    SELECT v_total AS total, v_page AS page, v_per_page AS per_page,
           CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        la.Loan_Account_Id,
        la.Ref_Account_No AS Loan_Account_No,
        IF(ap.Cust_Type_Cd = 1, NULL, ap.Cust_Id_Primay) AS Member_Id,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Member_Name,
        pm.Mobile_No,
        IF(ap.Cust_Type_Cd = 1, pg.Group_Name,
           (SELECT g2.Group_Name FROM mst_member_group mg JOIN mst_group g2 ON g2.Group_Id = mg.Group_Id
            WHERE mg.Member_Id = ap.Cust_Id_Primay AND mg.Is_Active = 1 ORDER BY mg.Mem_Group_Id DESC LIMIT 1)) AS Group_Name,
        s.Scheme_Name,
        ap.Branch_Id,
        b.Branch_Name,
        f.Oldest_Unpaid AS Oldest_Due_Date,
        f.Dpd,
        f.Od_Installments AS Overdue_Installments,
        f.Od_P AS Overdue_Principal,
        f.Od_I AS Overdue_Interest,
        f.Penalty_Due,
        (f.Od_P + f.Od_I + f.Penalty_Due) AS Total_Overdue,
        (SELECT IFNULL(SUM(c.Total_Collected), 0) FROM trans_loan_collection c
         WHERE c.Account_Id = la.Loan_Account_Id AND c.Tr_Status_Cd = 2 AND IFNULL(c.Payment_Mode_Cd, 0) <> 5
           AND IFNULL(c.Effect_Date, DATE(c.Collection_Date)) BETWEEN v_month AND p_as_on) AS Collected_This_Month,
        f.Outstanding AS Principal_Outstanding,
        f.Bucket,
        IFNULL(la.Is_Defaulter, 0) AS Is_Defaulter,
        IFNULL(la.Is_NPA, 0) AS Is_NPA,
        ap.FO_Id,
        fo.Full_Name AS FO_Name
    FROM tmp_loan_facts f
    JOIN mst_loan_account la ON la.Loan_Account_Id = f.Loan_Account_Id
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    LEFT JOIN mst_member pm ON ap.Cust_Type_Cd = 2 AND pm.Member_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_group pg ON ap.Cust_Type_Cd = 1 AND pg.Group_Id = ap.Cust_Id_Primay
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = ap.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
    ORDER BY f.Dpd DESC, la.Loan_Account_Id
    LIMIT v_per_page OFFSET v_offset;

    SELECT COUNT(*) AS Total_Count,
           IFNULL(SUM(Od_P), 0) AS Total_Overdue_Principal,
           IFNULL(SUM(Od_I), 0) AS Total_Overdue_Interest,
           IFNULL(SUM(Penalty_Due), 0) AS Total_Penalty_Due,
           IFNULL(SUM(Od_P + Od_I + Penalty_Due), 0) AS Total_Overdue,
           IFNULL(SUM(Outstanding), 0) AS Total_Outstanding
    FROM tmp_loan_facts;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_PAR_SUMMARY` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_PAR_SUMMARY`(IN p_as_on DATE, IN p_branch_id INT, IN p_scheme_id INT)
BEGIN
    DECLARE v_total DECIMAL(16,2) DEFAULT 0;
    DECLARE v_accounts INT DEFAULT 0;
    DECLARE v_par30 DECIMAL(16,2) DEFAULT 0;
    DECLARE v_npa DECIMAL(16,2) DEFAULT 0;
    DECLARE v_prov DECIMAL(16,2) DEFAULT 0;

    SET p_as_on = IFNULL(p_as_on, CURDATE());
    CALL USP_LOAN_PORTFOLIO_FACTS(p_as_on, p_branch_id, p_scheme_id);

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_par;
    CREATE TEMPORARY TABLE tmp_loan_par (
        Sort_No INT PRIMARY KEY, Bucket VARCHAR(20), Label VARCHAR(20), Min_Dpd INT, Max_Dpd INT,
        Provision_Rate DECIMAL(6,2), Accounts INT DEFAULT 0, Outstanding DECIMAL(16,2) DEFAULT 0
    );
    INSERT INTO tmp_loan_par (Sort_No, Bucket, Label, Min_Dpd, Max_Dpd, Provision_Rate) VALUES
        (1, 'current', '0 DPD', 0, 0, 0.40),
        (2, 'par_1_30', '1-30', 1, 30, 5.00),
        (3, 'par_31_60', '31-60', 31, 60, 25.00),
        (4, 'par_61_90', '61-90', 61, 90, 50.00),
        (5, 'npa_90_plus', '90+', 91, 999999, 100.00);

    UPDATE tmp_loan_par p
    JOIN (
        SELECT CASE WHEN Dpd <= 0 THEN 1 WHEN Dpd <= 30 THEN 2 WHEN Dpd <= 60 THEN 3 WHEN Dpd <= 90 THEN 4 ELSE 5 END AS Sort_No,
               COUNT(*) AS cnt, SUM(Outstanding) AS outs
        FROM tmp_loan_facts GROUP BY 1
    ) x ON x.Sort_No = p.Sort_No
    SET p.Accounts = x.cnt, p.Outstanding = x.outs;

    SELECT IFNULL(SUM(Outstanding), 0), COUNT(*), IFNULL(SUM(IF(Dpd > 30, Outstanding, 0)), 0), IFNULL(SUM(IF(Bucket = 'npa', Outstanding, 0)), 0)
    INTO v_total, v_accounts, v_par30, v_npa
    FROM tmp_loan_facts;

    SELECT IFNULL(SUM(ROUND(Outstanding * Provision_Rate / 100, 2)), 0) INTO v_prov FROM tmp_loan_par;

    SELECT p_as_on AS As_On_Date, v_accounts AS Total_Accounts, v_total AS Total_Portfolio,
           v_par30 AS Par30_Amount, IF(v_total > 0, ROUND(v_par30 * 100 / v_total, 2), 0) AS Par30_Percent,
           v_npa AS Npa_Amount, IF(v_total > 0, ROUND(v_npa * 100 / v_total, 2), 0) AS Npa_Percent,
           v_prov AS Provision_Required;

    SELECT Bucket, Label, Min_Dpd, IF(Max_Dpd = 999999, NULL, Max_Dpd) AS Max_Dpd, Accounts, Outstanding,
           IF(v_total > 0, ROUND(Outstanding * 100 / v_total, 2), 0) AS Percent,
           Provision_Rate, ROUND(Outstanding * Provision_Rate / 100, 2) AS Provision_Amount
    FROM tmp_loan_par ORDER BY Sort_No;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_PORTFOLIO_FACTS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_PORTFOLIO_FACTS`(IN p_as_on DATE, IN p_branch_id INT, IN p_scheme_id INT)
BEGIN
    CALL USP_LOAN_FACTS_RESET();

    INSERT INTO tmp_loan_facts (Loan_Account_Id)
    SELECT la.Loan_Account_Id
    FROM mst_loan_account la
    JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
    WHERE la.Ln_Status_Cd = 1 AND la.Disbursed_Amount > 0
      AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
      AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
      AND EXISTS (SELECT 1 FROM mst_loan_account_disbursement d
                  WHERE d.Loan_Account_Id = la.Loan_Account_Id AND d.Approved_By IS NOT NULL AND d.Disbursement_Date <= p_as_on);

    CALL USP_LOAN_FACTS_FILL(p_as_on);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_PORTFOLIO_REPORT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_PORTFOLIO_REPORT`(
    IN p_report VARCHAR(30),
    IN p_from DATE,
    IN p_to DATE,
    IN p_branch_id INT,
    IN p_scheme_id INT
)
BEGIN
    SET p_to = IFNULL(p_to, CURDATE());
    SET p_from = IFNULL(p_from, DATE_FORMAT(p_to, '%Y-%m-01'));

    IF p_report = 'disbursement' THEN
        SELECT d.Disbursement_Date, ap.Branch_Id, b.Branch_Name, ap.Scheme_Id, s.Scheme_Name,
               COUNT(*) AS Disbursement_Count, SUM(d.Gross_Amount) AS Gross_Amount, SUM(d.Charge_Deduction) AS Charge_Deduction,
               SUM(d.Other_Deduction) AS Other_Deduction, SUM(d.Net_Amount) AS Net_Amount
        FROM mst_loan_account_disbursement d
        JOIN mst_loan_account la ON la.Loan_Account_Id = d.Loan_Account_Id
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
        LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
        WHERE d.Approved_By IS NOT NULL AND d.Disbursement_Date BETWEEN p_from AND p_to
          AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
          AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
        GROUP BY d.Disbursement_Date, ap.Branch_Id, b.Branch_Name, ap.Scheme_Id, s.Scheme_Name
        ORDER BY d.Disbursement_Date, b.Branch_Name, s.Scheme_Name;

    ELSEIF p_report = 'collection' THEN
        SELECT IFNULL(c.Effect_Date, DATE(c.Collection_Date)) AS Collection_Date, c.Branch_Id, b.Branch_Name, ap.Scheme_Id, s.Scheme_Name,
               COUNT(*) AS Collection_Count, SUM(c.Principal_Collected) AS Principal_Collected,
               SUM(c.Interest_Collected) AS Interest_Collected, SUM(c.Penalty_Collected) AS Penalty_Collected,
               SUM(c.Total_Collected) AS Total_Collected
        FROM trans_loan_collection c
        JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
        LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = c.Branch_Id
        WHERE c.Tr_Status_Cd = 2 AND IFNULL(c.Payment_Mode_Cd, 0) <> 5
          AND IFNULL(c.Effect_Date, DATE(c.Collection_Date)) BETWEEN p_from AND p_to
          AND (p_branch_id IS NULL OR c.Branch_Id = p_branch_id)
          AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
        GROUP BY IFNULL(c.Effect_Date, DATE(c.Collection_Date)), c.Branch_Id, b.Branch_Name, ap.Scheme_Id, s.Scheme_Name
        ORDER BY Collection_Date, b.Branch_Name, s.Scheme_Name;

    ELSEIF p_report = 'demand_vs_collection' THEN
        DROP TEMPORARY TABLE IF EXISTS tmp_loan_dvc;
        CREATE TEMPORARY TABLE tmp_loan_dvc (
            Period CHAR(7), Branch_Id INT, Demand_Principal DECIMAL(16,2) DEFAULT 0, Demand_Interest DECIMAL(16,2) DEFAULT 0,
            Collected_Principal DECIMAL(16,2) DEFAULT 0, Collected_Interest DECIMAL(16,2) DEFAULT 0,
            Collected_Penalty DECIMAL(16,2) DEFAULT 0, PRIMARY KEY (Period, Branch_Id)
        );

        INSERT INTO tmp_loan_dvc (Period, Branch_Id, Demand_Principal, Demand_Interest)
        SELECT DATE_FORMAT(sc.Due_Date, '%Y-%m'), ap.Branch_Id,
               SUM(sc.Principal_Due - IFNULL(sc.Principal_Waived, 0)), SUM(sc.Interest_Due - IFNULL(sc.Interest_Waived, 0))
        FROM trans_loanac_schedule sc
        JOIN mst_loan_account la ON la.Loan_Account_Id = sc.Loan_Account_Id
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        WHERE IFNULL(sc.Is_Active, 1) = 1 AND la.Disbursed_Amount > 0 AND la.Ln_Status_Cd IN (1, 3)
          AND sc.Due_Date BETWEEN p_from AND p_to
          AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
          AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
        GROUP BY DATE_FORMAT(sc.Due_Date, '%Y-%m'), ap.Branch_Id;

        INSERT INTO tmp_loan_dvc (Period, Branch_Id, Collected_Principal, Collected_Interest, Collected_Penalty)
        SELECT DATE_FORMAT(IFNULL(c.Effect_Date, DATE(c.Collection_Date)), '%Y-%m'), ap.Branch_Id,
               SUM(c.Principal_Collected), SUM(c.Interest_Collected), SUM(c.Penalty_Collected)
        FROM trans_loan_collection c
        JOIN mst_loan_account la ON la.Loan_Account_Id = c.Account_Id
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        WHERE c.Tr_Status_Cd = 2 AND IFNULL(c.Payment_Mode_Cd, 0) <> 5
          AND IFNULL(c.Effect_Date, DATE(c.Collection_Date)) BETWEEN p_from AND p_to
          AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
          AND (p_scheme_id IS NULL OR ap.Scheme_Id = p_scheme_id)
        GROUP BY DATE_FORMAT(IFNULL(c.Effect_Date, DATE(c.Collection_Date)), '%Y-%m'), ap.Branch_Id
        ON DUPLICATE KEY UPDATE Collected_Principal = VALUES(Collected_Principal),
                                Collected_Interest = VALUES(Collected_Interest),
                                Collected_Penalty = VALUES(Collected_Penalty);

        SELECT d.Period, d.Branch_Id, b.Branch_Name, d.Demand_Principal, d.Demand_Interest,
               (d.Demand_Principal + d.Demand_Interest) AS Demand_Total,
               d.Collected_Principal, d.Collected_Interest, d.Collected_Penalty,
               (d.Collected_Principal + d.Collected_Interest) AS Collected_Total,
               IF(d.Demand_Principal + d.Demand_Interest > 0,
                  ROUND((d.Collected_Principal + d.Collected_Interest) * 100 / (d.Demand_Principal + d.Demand_Interest), 2), NULL)
                   AS Collection_Efficiency_Percent
        FROM tmp_loan_dvc d
        LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = d.Branch_Id
        ORDER BY d.Period, b.Branch_Name;

    ELSEIF p_report = 'outstanding' THEN
        CALL USP_LOAN_PORTFOLIO_FACTS(p_to, p_branch_id, p_scheme_id);

        SELECT ap.Branch_Id, b.Branch_Name, ap.Scheme_Id, s.Scheme_Name, ap.FO_Id, fo.Full_Name AS FO_Name,
               COUNT(*) AS Accounts, SUM(f.Disbursed_As_On) AS Disbursed_Amount, SUM(f.Outstanding) AS Principal_Outstanding,
               SUM(f.Od_P + f.Od_I) AS Overdue_Amount, SUM(IF(f.Dpd > 0, 1, 0)) AS Overdue_Accounts
        FROM tmp_loan_facts f
        JOIN mst_loan_account la ON la.Loan_Account_Id = f.Loan_Account_Id
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = ap.Scheme_Id
        LEFT JOIN mst_staff fo ON fo.Staff_Id = ap.FO_Id
        LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
        GROUP BY ap.Branch_Id, b.Branch_Name, ap.Scheme_Id, s.Scheme_Name, ap.FO_Id, fo.Full_Name
        ORDER BY b.Branch_Name, s.Scheme_Name, FO_Name;

    ELSEIF p_report = 'par' THEN
        CALL USP_LOAN_PORTFOLIO_FACTS(p_to, p_branch_id, p_scheme_id);

        SELECT ap.Branch_Id, b.Branch_Name,
               COUNT(*) AS Accounts,
               SUM(f.Outstanding) AS Total_Outstanding,
               SUM(IF(f.Dpd <= 0, f.Outstanding, 0)) AS Current_Outstanding,
               SUM(IF(f.Dpd BETWEEN 1 AND 30, f.Outstanding, 0)) AS Par_1_30,
               SUM(IF(f.Dpd BETWEEN 31 AND 60, f.Outstanding, 0)) AS Par_31_60,
               SUM(IF(f.Dpd BETWEEN 61 AND 90, f.Outstanding, 0)) AS Par_61_90,
               SUM(IF(f.Dpd > 90, f.Outstanding, 0)) AS Npa_90_Plus,
               IF(SUM(f.Outstanding) > 0, ROUND(SUM(IF(f.Dpd > 30, f.Outstanding, 0)) * 100 / SUM(f.Outstanding), 2), 0) AS Par30_Percent
        FROM tmp_loan_facts f
        JOIN mst_loan_account la ON la.Loan_Account_Id = f.Loan_Account_Id
        JOIN mst_loan_application ap ON ap.Application_Id = la.Application_Id
        LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = ap.Branch_Id
        GROUP BY ap.Branch_Id, b.Branch_Name
        ORDER BY b.Branch_Name;

    ELSEIF p_report = 'scheme_wise' THEN
        SELECT s.Scheme_Id, s.Scheme_Code, s.Scheme_Name,
               COUNT(la.Loan_Account_Id) AS Accounts,
               SUM(IF(la.Ln_Status_Cd = 1, 1, 0)) AS Active_Accounts,
               SUM(IF(la.Ln_Status_Cd = 2, 1, 0)) AS Closed_Accounts,
               IFNULL(SUM(la.Loan_Amount), 0) AS Sanctioned_Amount,
               IFNULL(SUM(la.Disbursed_Amount), 0) AS Disbursed_Amount,
               IFNULL(SUM(IF(la.Ln_Status_Cd = 1, la.Principal_Outstanding, 0)), 0) AS Principal_Outstanding,
               IFNULL(SUM((SELECT IFNULL(SUM(c.Total_Collected), 0) FROM trans_loan_collection c
                           WHERE c.Account_Id = la.Loan_Account_Id AND c.Tr_Status_Cd = 2 AND IFNULL(c.Payment_Mode_Cd, 0) <> 5
                             AND IFNULL(c.Effect_Date, DATE(c.Collection_Date)) <= p_to)), 0) AS Total_Collected
        FROM mst_loan_scheme s
        LEFT JOIN mst_loan_application ap ON ap.Scheme_Id = s.Scheme_Id AND (p_branch_id IS NULL OR ap.Branch_Id = p_branch_id)
        LEFT JOIN mst_loan_account la ON la.Application_Id = ap.Application_Id AND la.Loan_Date <= p_to
        WHERE (p_scheme_id IS NULL OR s.Scheme_Id = p_scheme_id)
        GROUP BY s.Scheme_Id, s.Scheme_Code, s.Scheme_Name
        ORDER BY s.Scheme_Name;

    ELSE
        SELECT 'ERROR' AS status,
               'report must be disbursement, collection, demand_vs_collection, outstanding, par or scheme_wise' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SANCTION_PREVIEW` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SANCTION_PREVIEW`(
    IN p_application_id BIGINT,
    IN p_amount DECIMAL(18,2),
    IN p_rate DECIMAL(7,2),
    IN p_duration INT,
    IN p_schedule_cd INT,
    IN p_moratorium INT,
    IN p_first_due DATE
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_intt INT DEFAULT 1;
    DECLARE v_repay INT DEFAULT 1;
    DECLARE v_scheme INT;
    DECLARE v_ded DECIMAL(14,2) DEFAULT 0;
    DECLARE v_emi DECIMAL(12,2);
    DECLARE v_tot_int DECIMAL(14,2);
    DECLARE v_tot_due DECIMAL(14,2);
    DECLARE v_first DATE;
    DECLARE v_last DATE;

    CALL USP_LOAN_SANCTION_TERMS(p_application_id, p_amount, p_rate, p_duration, p_schedule_cd, p_moratorium, p_first_due,
                                 v_intt, v_repay, v_err);

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_kfs_charges;
    CREATE TEMPORARY TABLE tmp_loan_kfs_charges (
        Row_No INT AUTO_INCREMENT PRIMARY KEY,
        Charge_Id INT, Charge_Name VARCHAR(100), Deduct_During_Cd INT, Source VARCHAR(20),
        Charge_Amount DECIMAL(12,2), Tax_Amount DECIMAL(12,2), Waived_Amount DECIMAL(12,2), Net_Amount DECIMAL(12,2)
    );

    IF v_err IS NULL THEN
        SELECT Scheme_Id INTO v_scheme FROM mst_loan_application WHERE Application_Id = p_application_id;

        INSERT INTO tmp_loan_kfs_charges (Charge_Id, Charge_Name, Deduct_During_Cd, Source, Charge_Amount, Tax_Amount, Waived_Amount, Net_Amount)
        SELECT ch.Charge_Id, c.Charge_Name, c.Deduct_During_Cd, 'application', ch.Charge_Amount, ch.Tax_Amount,
               IFNULL(ch.Waived_Amount, 0), ch.Total_Charge - IFNULL(ch.Waived_Amount, 0)
        FROM mst_loan_application_charge ch
        LEFT JOIN mst_loan_charges c ON c.Charge_Id = ch.Charge_Id
        WHERE ch.Loan_Application_Id = p_application_id AND ch.Tr_Status_Cd = 1;

        INSERT INTO tmp_loan_kfs_charges (Charge_Id, Charge_Name, Deduct_During_Cd, Source, Charge_Amount, Tax_Amount, Waived_Amount, Net_Amount)
        SELECT x.Charge_Id, x.Charge_Name, x.Deduct_During_Cd, 'scheme', x.amt, x.tax, 0, x.amt + x.tax
        FROM (
            SELECT c.Charge_Id, c.Charge_Name, c.Deduct_During_Cd,
                   FN_LOAN_CHARGE_AMOUNT(c.Charge_Id, p_amount) AS amt,
                   FN_LOAN_CHARGE_TAX(c.Charge_Id, FN_LOAN_CHARGE_AMOUNT(c.Charge_Id, p_amount)) AS tax
            FROM mst_loan_scheme_charges sc
            JOIN mst_loan_charges c ON c.Charge_Id = sc.Charge_Id
            WHERE sc.Scheme_Id = v_scheme AND sc.Is_Active = 1 AND c.Is_Active = 1 AND c.Deduct_During_Cd IN (2, 3, 4, 5)
              AND NOT EXISTS (SELECT 1 FROM mst_loan_application_charge e
                              WHERE e.Loan_Application_Id = p_application_id AND e.Charge_Id = c.Charge_Id AND e.Tr_Status_Cd IN (1, 2))
        ) x;

        SELECT IFNULL(SUM(Net_Amount), 0) INTO v_ded FROM tmp_loan_kfs_charges;

        CALL USP_LOAN_SCHEDULE_BUILD(p_amount, p_rate, p_duration, p_schedule_cd, v_intt, v_repay, CURDATE(), p_first_due, p_moratorium);
    ELSE
        DROP TEMPORARY TABLE IF EXISTS tmp_loan_schedule;
        CREATE TEMPORARY TABLE tmp_loan_schedule (
            Installment_No INT, Due_Date DATE, Principal_Due DECIMAL(12,2), Interest_Due DECIMAL(12,2),
            Total_Due DECIMAL(12,2), Outs_Principal DECIMAL(12,2)
        );
    END IF;

    SELECT IFNULL(SUM(Interest_Due), 0), IFNULL(SUM(Total_Due), 0), MIN(Due_Date), MAX(Due_Date)
    INTO v_tot_int, v_tot_due, v_first, v_last
    FROM tmp_loan_schedule;
    SELECT MAX(Total_Due) INTO v_emi FROM tmp_loan_schedule WHERE Installment_No = 1;

    SELECT
        IF(v_err IS NULL, 'SUCCESS', 'ERROR') AS status,
        IFNULL(v_err, 'Sanction preview generated') AS message,
        p_application_id AS Application_Id,
        p_amount AS Sanctioned_Amount,
        p_rate AS Interest_Rate,
        v_intt AS Intt_Type_Cd,
        FN_LOAN_OPT_DESC(19, v_intt) AS Intt_Type_Desc,
        v_repay AS Repay_Type_Cd,
        FN_LOAN_OPT_DESC(18, v_repay) AS Repay_Type_Desc,
        p_duration AS Loan_Duration,
        p_schedule_cd AS Repay_Schedule_Cd,
        FN_LOAN_OPT_DESC(22, p_schedule_cd) AS Repay_Schedule_Desc,
        p_moratorium AS Moratorium_Days,
        v_emi AS Installment_Amount,
        v_tot_int AS Total_Interest,
        v_tot_due AS Total_Repayable,
        v_first AS First_Due_Date,
        v_last AS Last_Due_Date,
        v_ded AS Total_Deductions,
        IF(v_err IS NULL, p_amount - v_ded, NULL) AS Net_Disbursal_Amount;

    SELECT Charge_Id, Charge_Name, Deduct_During_Cd, FN_LOAN_OPT_DESC(23, Deduct_During_Cd) AS Deduct_During_Desc, Source,
           Charge_Amount, Tax_Amount, Waived_Amount, Net_Amount
    FROM tmp_loan_kfs_charges ORDER BY Row_No;

    SELECT Installment_No, Due_Date, Principal_Due, Interest_Due, Total_Due, Outs_Principal
    FROM tmp_loan_schedule ORDER BY Installment_No;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SANCTION_TERMS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SANCTION_TERMS`(
    IN p_application_id BIGINT,
    INOUT p_amount DECIMAL(18,2),
    INOUT p_rate DECIMAL(7,2),
    INOUT p_duration INT,
    INOUT p_schedule_cd INT,
    INOUT p_moratorium INT,
    IN p_first_due DATE,
    OUT p_intt_type INT,
    OUT p_repay_type INT,
    OUT p_err VARCHAR(255)
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_scheme INT;
    DECLARE v_appl DECIMAL(18,2);
    DECLARE v_tenure INT;
    DECLARE v_dur_cd INT;
    DECLARE v_date DATE;
    DECLARE v_rec DECIMAL(18,2);
    DECLARE v_s_rate DECIMAL(7,2);
    DECLARE v_s_sched INT;
    DECLARE v_slab_rate DECIMAL(7,2);
    DECLARE v_slab_dur INT;

    SET p_err = NULL;

    SELECT COUNT(*), MAX(Scheme_Id), MAX(Appl_Amount), MAX(Appl_Tenure), MAX(Repay_Duration_Cd), MAX(Application_Date)
    INTO v_cnt, v_scheme, v_appl, v_tenure, v_dur_cd, v_date
    FROM mst_loan_application WHERE Application_Id = p_application_id;

    IF v_cnt = 0 THEN
        SET p_err = 'Loan application not found';
    ELSE
        SET v_rec = (SELECT i.Recommended_Amount FROM mst_loan_application_inspection i
                     WHERE i.Loan_Application_Id = p_application_id AND i.Inspection_Result_Cd = 1
                     ORDER BY i.Inspection_Date DESC, i.Inspection_Id DESC LIMIT 1);

        SELECT MAX(RoI_Percent), MAX(Repay_Schedule_Cd), IFNULL(MAX(Intt_Type_Cd), 1), IFNULL(MAX(Repay_Type_Cd), 1)
        INTO v_s_rate, v_s_sched, p_intt_type, p_repay_type
        FROM mst_loan_scheme WHERE Scheme_Id = v_scheme;

        SET p_amount = IFNULL(p_amount, IFNULL(v_rec, v_appl));

        SELECT MAX(sl.RoI), MAX(sl.Max_Duration) INTO v_slab_rate, v_slab_dur
        FROM mst_loan_scheme_slab sl
        WHERE sl.Id = (SELECT x.Id FROM mst_loan_scheme_slab x
                       WHERE x.Scheme_Id = v_scheme AND x.Is_Active = 1 AND (x.Effect_From IS NULL OR x.Effect_From <= CURDATE())
                         AND p_amount BETWEEN IFNULL(x.Min_Amount, 0) AND IFNULL(x.Max_Amount, 9999999999)
                       ORDER BY x.Effect_From DESC, x.Id DESC LIMIT 1);

        SET p_rate = IFNULL(p_rate, IFNULL(v_slab_rate, v_s_rate));
        SET p_duration = IFNULL(p_duration, v_tenure);
        SET p_schedule_cd = IFNULL(p_schedule_cd,
                                   CASE v_dur_cd WHEN 1 THEN 1 WHEN 2 THEN 2 WHEN 4 THEN 3 ELSE IFNULL(v_s_sched, 3) END);
        SET p_moratorium = IFNULL(p_moratorium, 0);

        IF p_amount IS NULL OR p_amount <= 0 THEN
            SET p_err = 'Sanctioned amount must be greater than zero';
        ELSEIF p_amount > v_appl THEN
            SET p_err = CONCAT('Sanctioned amount cannot exceed the applied amount (', FORMAT(v_appl, 2), ')');
        ELSEIF p_rate IS NULL OR p_rate < 0 OR p_rate > 100 THEN
            SET p_err = 'Interest rate must be between 0 and 100';
        ELSEIF p_duration IS NULL OR p_duration < 1 THEN
            SET p_err = 'Loan duration must be at least 1';
        ELSEIF v_slab_dur IS NOT NULL AND p_duration > v_slab_dur THEN
            SET p_err = CONCAT('Loan duration cannot exceed the scheme slab maximum of ', v_slab_dur);
        ELSEIF FN_LOAN_OPT_DESC(22, p_schedule_cd) IS NULL THEN
            SET p_err = 'Repay schedule must be 1 (Daily), 2 (Weekly), 3 (Monthly) or 4 (Balloon)';
        ELSEIF p_moratorium < 0 THEN
            SET p_err = 'Moratorium days cannot be negative';
        ELSEIF p_first_due IS NOT NULL AND p_first_due <= CURDATE() THEN
            SET p_err = 'First due date must be after today';
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEDULE_BUILD` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEDULE_BUILD`(
    IN p_amount DECIMAL(18,2),
    IN p_rate DECIMAL(7,2),
    IN p_n INT,
    IN p_schedule_cd INT,
    IN p_intt_type INT,
    IN p_repay_type INT,
    IN p_start DATE,
    IN p_first_due DATE,
    IN p_moratorium INT
)
BEGIN
    DECLARE v_i INT DEFAULT 1;
    DECLARE v_ppy INT DEFAULT 12;
    DECLARE v_r DOUBLE DEFAULT 0;
    DECLARE v_emi DECIMAL(14,2) DEFAULT 0;
    DECLARE v_outs DECIMAL(18,2) DEFAULT 0;
    DECLARE v_int DECIMAL(14,2) DEFAULT 0;
    DECLARE v_prin DECIMAL(14,2) DEFAULT 0;
    DECLARE v_flat_int DECIMAL(14,2) DEFAULT 0;
    DECLARE v_eq_prin DECIMAL(14,2) DEFAULT 0;
    DECLARE v_first DATE;
    DECLARE v_due DATE;
    DECLARE v_k INT DEFAULT 0;
    DECLARE v_hol_due INT DEFAULT 1;

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_schedule;
    CREATE TEMPORARY TABLE tmp_loan_schedule (
        Installment_No INT NOT NULL,
        Due_Date DATE NOT NULL,
        Principal_Due DECIMAL(12,2) NOT NULL,
        Interest_Due DECIMAL(12,2) NOT NULL,
        Total_Due DECIMAL(12,2) NOT NULL,
        Outs_Principal DECIMAL(12,2) NOT NULL
    );

    SET v_outs = IFNULL(p_amount, 0);
    SET p_n = GREATEST(IFNULL(p_n, 1), 1);
    SET p_rate = IFNULL(p_rate, 0);
    SET p_start = IFNULL(p_start, CURDATE());
    SET p_moratorium = IFNULL(p_moratorium, 0);

    IF p_schedule_cd = 4 THEN
        SET v_due = IFNULL(p_first_due, DATE_ADD(DATE_ADD(p_start, INTERVAL p_moratorium DAY), INTERVAL p_n MONTH));
        SET v_int = ROUND(v_outs * p_rate / 100 * GREATEST(DATEDIFF(v_due, p_start), 0) / 365, 2);
        INSERT INTO tmp_loan_schedule VALUES (1, v_due, v_outs, v_int, v_outs + v_int, 0);
    ELSE
        SET v_ppy = FN_LOAN_PERIODS_PER_YEAR('S', p_schedule_cd);
        SET v_first = IFNULL(p_first_due,
            CASE p_schedule_cd
                WHEN 1 THEN DATE_ADD(DATE_ADD(p_start, INTERVAL p_moratorium DAY), INTERVAL 1 DAY)
                WHEN 2 THEN DATE_ADD(DATE_ADD(p_start, INTERVAL p_moratorium DAY), INTERVAL 7 DAY)
                ELSE DATE_ADD(DATE_ADD(p_start, INTERVAL p_moratorium DAY), INTERVAL 1 MONTH)
            END);
        SET v_r = p_rate / 100 / v_ppy;
        SET v_flat_int = ROUND(v_outs * p_rate / 100 / v_ppy, 2);
        SET v_eq_prin = ROUND(v_outs / p_n, 2);
        SET v_emi = IF(v_r = 0, v_eq_prin, ROUND(v_outs * v_r * POW(1 + v_r, p_n) / (POW(1 + v_r, p_n) - 1), 2));

        WHILE v_i <= p_n DO
            SET v_due = CASE p_schedule_cd
                WHEN 1 THEN DATE_ADD(v_first, INTERVAL (v_i - 1) DAY)
                WHEN 2 THEN DATE_ADD(v_first, INTERVAL (v_i - 1) * 7 DAY)
                ELSE DATE_ADD(v_first, INTERVAL (v_i - 1) MONTH)
            END;

            SET v_int = IF(p_intt_type = 2, v_flat_int, ROUND(v_outs * v_r, 2));

            IF v_i = p_n THEN
                SET v_prin = v_outs;
            ELSEIF p_repay_type = 3 THEN
                SET v_prin = 0;
            ELSEIF p_repay_type = 2 OR p_intt_type = 2 THEN
                SET v_prin = LEAST(v_outs, v_eq_prin);
            ELSE
                SET v_prin = LEAST(v_outs, GREATEST(v_emi - v_int, 0));
            END IF;

            SET v_outs = v_outs - v_prin;
            INSERT INTO tmp_loan_schedule VALUES (v_i, v_due, v_prin, v_int, v_prin + v_int, v_outs);
            SET v_i = v_i + 1;
        END WHILE;
    END IF;

    SELECT IFNULL(MAX(Status), 1) INTO v_hol_due FROM mst_settings_general WHERE Code = 'HolidDue';

    IF v_hol_due = 0 THEN
        WHILE v_k < 10 AND EXISTS (SELECT 1 FROM tmp_loan_schedule t JOIN mst_holidays h ON h.Holiday_Date = t.Due_Date) DO
            UPDATE tmp_loan_schedule t
            JOIN mst_holidays h ON h.Holiday_Date = t.Due_Date
            SET t.Due_Date = DATE_ADD(t.Due_Date, INTERVAL 1 DAY);
            SET v_k = v_k + 1;
        END WHILE;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEDULE_GENERATE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEDULE_GENERATE`(
    IN p_loan_account_id BIGINT,
    IN p_amount DECIMAL(18,2),
    IN p_start DATE,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_app BIGINT;
    DECLARE v_status INT;
    DECLARE v_amount DECIMAL(18,2);
    DECLARE v_rate DECIMAL(7,2);
    DECLARE v_date DATE;
    DECLARE v_dur INT;
    DECLARE v_sched INT;
    DECLARE v_morat INT;
    DECLARE v_first DATE;
    DECLARE v_intt INT;
    DECLARE v_repay INT;
    DECLARE v_appr BIGINT;
    DECLARE v_tenure INT;
    DECLARE v_dur_cd INT;
    DECLARE v_inst INT DEFAULT 0;
    DECLARE v_final DATE;
    DECLARE v_emi DECIMAL(12,2);

    SELECT COUNT(*), MAX(Application_Id), MAX(Ln_Status_Cd), MAX(Loan_Amount), MAX(Interest_Rate), MAX(Loan_Date)
    INTO v_cnt, v_app, v_status, v_amount, v_rate, v_date
    FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id FOR UPDATE;

    IF v_cnt = 0 THEN
        SET v_err = 'Loan account not found';
    ELSEIF v_status <> 1 THEN
        SET v_err = 'Schedule can only be generated for an active loan account';
    ELSEIF EXISTS (SELECT 1 FROM trans_loan_collection WHERE Account_Id = p_loan_account_id AND Tr_Status_Cd IN (1, 2)) THEN
        SET v_err = 'Schedule cannot be regenerated after collections are posted';
    END IF;

    IF v_err IS NULL THEN
        SET v_appr = (SELECT x.Loan_Approval_Id FROM mst_loan_application_approval x
                      WHERE x.Loan_Application_Id = v_app AND x.Approval_Status_Cd = 1
                      ORDER BY x.Approval_Date DESC, x.Loan_Approval_Id DESC LIMIT 1);

        SELECT MAX(Loan_Duration), MAX(Repay_Schedule_Cd), MAX(Moratorium_Days), MAX(First_Due_Date)
        INTO v_dur, v_sched, v_morat, v_first
        FROM mst_loan_application_approval WHERE Loan_Approval_Id = v_appr;

        SELECT MAX(a.Appl_Tenure), MAX(a.Repay_Duration_Cd), IFNULL(MAX(s.Intt_Type_Cd), 1), IFNULL(MAX(s.Repay_Type_Cd), 1),
               MAX(s.Repay_Schedule_Cd)
        INTO v_tenure, v_dur_cd, v_intt, v_repay, v_cnt
        FROM mst_loan_application a LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = a.Scheme_Id
        WHERE a.Application_Id = v_app;

        SET v_dur = IFNULL(v_dur, v_tenure);
        SET v_sched = IFNULL(v_sched, CASE v_dur_cd WHEN 1 THEN 1 WHEN 2 THEN 2 WHEN 4 THEN 3 ELSE IFNULL(v_cnt, 3) END);
        SET v_amount = IFNULL(p_amount, v_amount);
        SET p_start = IFNULL(p_start, v_date);

        IF v_first IS NOT NULL AND v_first <= p_start THEN
            SET v_first = NULL;
        END IF;

        IF v_amount IS NULL OR v_amount <= 0 THEN
            SET v_err = 'Nothing to schedule: amount must be greater than zero';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_loan_account_id AS loan_account_id, 0 AS installments, NULL AS installment_amount,
               NULL AS final_due_date, v_err AS message;
    ELSE
        CALL USP_LOAN_SCHEDULE_BUILD(v_amount, v_rate, v_dur, v_sched, v_intt, v_repay, p_start, v_first, v_morat);

        DELETE FROM trans_loanac_schedule WHERE Loan_Account_Id = p_loan_account_id;

        INSERT INTO trans_loanac_schedule (
            Loan_Account_Id, Installment_No, Due_Date, Principal_Due, Interest_Due, Total_Due, Principal_Waived,
            Interest_Waived, Advance_Paid, Outs_Principal, Collection_Id, Is_Active, Created_By, Created_At
        )
        SELECT p_loan_account_id, Installment_No, Due_Date, Principal_Due, Interest_Due, Total_Due, 0, 0, 0,
               Outs_Principal, NULL, 1, p_user_id, NOW()
        FROM tmp_loan_schedule ORDER BY Installment_No;

        SELECT COUNT(*), MAX(Due_Date) INTO v_inst, v_final FROM tmp_loan_schedule;
        SELECT MAX(Total_Due) INTO v_emi FROM tmp_loan_schedule WHERE Installment_No = 1;

        UPDATE mst_loan_account SET Final_Due_Date = v_final WHERE Loan_Account_Id = p_loan_account_id;

        SELECT 'SUCCESS' AS status, p_loan_account_id AS loan_account_id, v_inst AS installments, v_emi AS installment_amount,
               v_final AS final_due_date, CONCAT('Repayment schedule generated (', v_inst, ' installments)') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEDULE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEDULE_LIST`(IN p_loan_account_id BIGINT, IN p_as_on DATE)
BEGIN
    DECLARE v_tp DECIMAL(14,2) DEFAULT 0;
    DECLARE v_ti DECIMAL(14,2) DEFAULT 0;
    DECLARE v_status INT DEFAULT 1;
    DECLARE v_next DATE;

    SET p_as_on = IFNULL(p_as_on, CURDATE());
    SET v_tp = FN_LOAN_PAID(p_loan_account_id, NULL, 'P');
    SET v_ti = FN_LOAN_PAID(p_loan_account_id, NULL, 'I');
    SELECT IFNULL(MAX(Ln_Status_Cd), 1) INTO v_status FROM mst_loan_account WHERE Loan_Account_Id = p_loan_account_id;

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_sched_view;
    CREATE TEMPORARY TABLE tmp_loan_sched_view (
        Schedule_Id BIGINT PRIMARY KEY,
        Pd DECIMAL(14,2), Idue DECIMAL(14,2), Paid_P DECIMAL(14,2), Paid_I DECIMAL(14,2), Due_Date DATE
    );

    INSERT INTO tmp_loan_sched_view
    SELECT w.Schedule_Id, w.pd, w.idue,
           LEAST(w.pd, GREATEST(0, v_tp - (w.cum_p - w.pd))),
           LEAST(w.idue, GREATEST(0, v_ti - (w.cum_i - w.idue))),
           w.Due_Date
    FROM (
        SELECT s.Schedule_Id, s.Due_Date,
               s.Principal_Due - IFNULL(s.Principal_Waived, 0) AS pd,
               s.Interest_Due - IFNULL(s.Interest_Waived, 0) AS idue,
               SUM(s.Principal_Due - IFNULL(s.Principal_Waived, 0)) OVER w AS cum_p,
               SUM(s.Interest_Due - IFNULL(s.Interest_Waived, 0)) OVER w AS cum_i
        FROM trans_loanac_schedule s
        WHERE s.Loan_Account_Id = p_loan_account_id AND IFNULL(s.Is_Active, 1) = 1
        WINDOW w AS (ORDER BY s.Installment_No, s.Schedule_Id)
    ) w;

    SELECT MIN(Due_Date) INTO v_next FROM tmp_loan_sched_view
    WHERE Due_Date >= p_as_on AND (Paid_P + 0.005 < Pd OR Paid_I + 0.005 < Idue);

    SELECT
        s.Schedule_Id,
        s.Loan_Account_Id,
        s.Installment_No,
        s.Due_Date,
        s.Principal_Due,
        s.Interest_Due,
        s.Total_Due,
        IFNULL(s.Principal_Waived, 0) AS Principal_Waived,
        IFNULL(s.Interest_Waived, 0) AS Interest_Waived,
        IFNULL(s.Advance_Paid, 0) AS Advance_Paid,
        v.Paid_P AS Principal_Paid,
        v.Paid_I AS Interest_Paid,
        (v.Paid_P + v.Paid_I) AS Paid_Amount,
        GREATEST(0, v.Pd + v.Idue - v.Paid_P - v.Paid_I) AS Balance_Due,
        s.Outs_Principal,
        s.Collection_Id,
        c.Trans_No AS Collection_Trans_No,
        CASE
            WHEN v.Paid_P + 0.005 >= v.Pd AND v.Paid_I + 0.005 >= v.Idue THEN 'Paid'
            WHEN v_status <> 1 THEN 'Closed'
            WHEN s.Due_Date < p_as_on THEN 'Overdue'
            WHEN s.Due_Date = v_next AND v.Paid_P + v.Paid_I = 0 THEN 'Due'
            WHEN v.Paid_P + v.Paid_I > 0 THEN 'Partly Paid'
            ELSE 'Upcoming'
        END AS Status
    FROM trans_loanac_schedule s
    JOIN tmp_loan_sched_view v ON v.Schedule_Id = s.Schedule_Id
    LEFT JOIN trans_loan_collection c ON c.Collection_Id = s.Collection_Id
    ORDER BY s.Installment_No, s.Schedule_Id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEDULE_SYNC` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEDULE_SYNC`(
    IN p_acct BIGINT,
    IN p_collection_id BIGINT,
    IN p_effect DATE
)
BEGIN
    DECLARE v_tp DECIMAL(14,2) DEFAULT 0;
    DECLARE v_ti DECIMAL(14,2) DEFAULT 0;

    SET v_tp = FN_LOAN_PAID(p_acct, NULL, 'P');
    SET v_ti = FN_LOAN_PAID(p_acct, NULL, 'I');

    DROP TEMPORARY TABLE IF EXISTS tmp_loan_sched_paid;
    CREATE TEMPORARY TABLE tmp_loan_sched_paid (
        Schedule_Id BIGINT PRIMARY KEY,
        Pd DECIMAL(14,2), Idue DECIMAL(14,2), Paid_P DECIMAL(14,2), Paid_I DECIMAL(14,2)
    );

    INSERT INTO tmp_loan_sched_paid
    SELECT w.Schedule_Id, w.pd, w.idue,
           LEAST(w.pd, GREATEST(0, v_tp - (w.cum_p - w.pd))),
           LEAST(w.idue, GREATEST(0, v_ti - (w.cum_i - w.idue)))
    FROM (
        SELECT s.Schedule_Id,
               s.Principal_Due - IFNULL(s.Principal_Waived, 0) AS pd,
               s.Interest_Due - IFNULL(s.Interest_Waived, 0) AS idue,
               SUM(s.Principal_Due - IFNULL(s.Principal_Waived, 0)) OVER w AS cum_p,
               SUM(s.Interest_Due - IFNULL(s.Interest_Waived, 0)) OVER w AS cum_i
        FROM trans_loanac_schedule s
        WHERE s.Loan_Account_Id = p_acct AND IFNULL(s.Is_Active, 1) = 1
        WINDOW w AS (ORDER BY s.Installment_No, s.Schedule_Id)
    ) w;

    UPDATE trans_loanac_schedule s
    JOIN tmp_loan_sched_paid x ON x.Schedule_Id = s.Schedule_Id
    SET s.Collection_Id = IF(x.Paid_P + 0.005 >= x.Pd AND x.Paid_I + 0.005 >= x.Idue,
                             IFNULL(s.Collection_Id, p_collection_id), NULL),
        s.Advance_Paid = IF(p_effect IS NOT NULL AND s.Due_Date > p_effect,
                            x.Paid_P + x.Paid_I,
                            LEAST(IFNULL(s.Advance_Paid, 0), x.Paid_P + x.Paid_I));
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEME_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_scheme_id INT,
    IN p_scheme_name VARCHAR(150),
    IN p_product_type_cd TINYINT,
    IN p_repay_type_cd TINYINT,
    IN p_roi_percent DECIMAL(5,2),
    IN p_intt_type_cd TINYINT,
    IN p_repay_schedule_cd TINYINT,
    IN p_is_intt_capitalisation TINYINT,
    IN p_capitalisation_on_cd TINYINT,
    IN p_is_incentive TINYINT,
    IN p_incentive_day TINYINT,
    IN p_incentive_rate DECIMAL(5,2),
    IN p_is_overdue TINYINT,
    IN p_repay_grace_days SMALLINT,
    IN p_overdue_on_cd TINYINT,
    IN p_overdur_rate DECIMAL(5,2),
    IN p_is_npa TINYINT,
    IN p_npa_after_days SMALLINT,
    IN p_is_mortgage_reqd TINYINT,
    IN p_is_guarantor_reqd TINYINT,
    IN p_loan_ledger INT,
    IN p_intt_ledger INT,
    IN p_odintt_ledger INT,
    IN p_field_coll_allow TINYINT,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_action VARCHAR(10);
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_name VARCHAR(150);
    DECLARE v_code VARCHAR(25) DEFAULT NULL;
    DECLARE v_cap TINYINT DEFAULT 0;
    DECLARE v_cap_on TINYINT DEFAULT NULL;
    DECLARE v_inc TINYINT DEFAULT 0;
    DECLARE v_inc_day TINYINT DEFAULT NULL;
    DECLARE v_inc_rate DECIMAL(5,2) DEFAULT NULL;
    DECLARE v_od TINYINT DEFAULT 0;
    DECLARE v_grace SMALLINT DEFAULT NULL;
    DECLARE v_od_on TINYINT DEFAULT NULL;
    DECLARE v_od_rate DECIMAL(5,2) DEFAULT NULL;
    DECLARE v_npa TINYINT DEFAULT 0;
    DECLARE v_npa_days SMALLINT DEFAULT NULL;
    DECLARE v_old_loan INT DEFAULT NULL;
    DECLARE v_old_intt INT DEFAULT NULL;
    DECLARE v_old_odintt INT DEFAULT NULL;
    DECLARE v_ledger_active TINYINT DEFAULT NULL;
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_gen_code VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_name = NULLIF(TRIM(IFNULL(p_scheme_name, '')), '');

    SET v_cap = IF(IFNULL(p_is_intt_capitalisation, 0) = 1, 1, 0);
    SET v_cap_on = IF(v_cap = 1, p_capitalisation_on_cd, NULL);
    SET v_inc = IF(IFNULL(p_is_incentive, 0) = 1, 1, 0);
    SET v_inc_day = IF(v_inc = 1, p_incentive_day, NULL);
    SET v_inc_rate = IF(v_inc = 1, p_incentive_rate, NULL);
    SET v_od = IF(IFNULL(p_is_overdue, 0) = 1, 1, 0);
    SET v_grace = IF(v_od = 1, p_repay_grace_days, NULL);
    SET v_od_on = IF(v_od = 1, p_overdue_on_cd, NULL);
    SET v_od_rate = IF(v_od = 1, p_overdur_rate, NULL);
    SET v_npa = IF(IFNULL(p_is_npa, 0) = 1, 1, 0);
    SET v_npa_days = IF(v_npa = 1, p_npa_after_days, NULL);

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Invalid action. Use ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_loan_scheme WHERE Scheme_Id = p_scheme_id;
        IF p_scheme_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan scheme not found';
        ELSE
            SELECT Loan_Ledger, Intt_Ledger, OdIntt_Ledger
            INTO v_old_loan, v_old_intt, v_old_odintt
            FROM mst_loan_scheme WHERE Scheme_Id = p_scheme_id;
        END IF;
    END IF;

    IF v_err IS NULL AND v_name IS NULL THEN
        SET v_err = 'Scheme name is required';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_loan_scheme
        WHERE LOWER(TRIM(Scheme_Name)) = LOWER(v_name)
          AND (v_action = 'ADD' OR Scheme_Id <> p_scheme_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Scheme name already exists';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 17 AND Opt_Code = p_product_type_cd AND Is_Active = 1;
        IF p_product_type_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid product type';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 18 AND Opt_Code = p_repay_type_cd AND Is_Active = 1;
        IF p_repay_type_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid repay type';
        END IF;
    END IF;

    IF v_err IS NULL AND (p_roi_percent IS NULL OR p_roi_percent < 0 OR p_roi_percent > 100) THEN
        SET v_err = 'Rate of interest is required and must be between 0 and 100';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 19 AND Opt_Code = p_intt_type_cd AND Is_Active = 1;
        IF p_intt_type_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid interest type';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 22 AND Opt_Code = p_repay_schedule_cd AND Is_Active = 1;
        IF p_repay_schedule_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid repay schedule';
        END IF;
    END IF;

    IF v_err IS NULL AND v_cap = 1 THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 20 AND Opt_Code = v_cap_on AND Is_Active = 1;
        IF v_cap_on IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid interest capitalisation on';
        END IF;
    END IF;

    IF v_err IS NULL AND v_inc = 1 AND (v_inc_day IS NULL OR v_inc_day < 1) THEN
        SET v_err = 'Incentive day is required and must be at least 1';
    END IF;

    IF v_err IS NULL AND v_inc = 1 AND (v_inc_rate IS NULL OR v_inc_rate < 0 OR v_inc_rate > 100) THEN
        SET v_err = 'Incentive rate is required and must be between 0 and 100';
    END IF;

    IF v_err IS NULL AND v_od = 1 AND v_grace IS NOT NULL AND v_grace < 0 THEN
        SET v_err = 'Repay grace days cannot be negative';
    END IF;

    IF v_err IS NULL AND v_od = 1 THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 21 AND Opt_Code = v_od_on AND Is_Active = 1;
        IF v_od_on IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid overdue on';
        END IF;
    END IF;

    IF v_err IS NULL AND v_od = 1 AND (v_od_rate IS NULL OR v_od_rate < 0 OR v_od_rate > 100) THEN
        SET v_err = 'Overdue rate is required and must be between 0 and 100';
    END IF;

    IF v_err IS NULL AND v_npa = 1 AND (v_npa_days IS NULL OR v_npa_days < 1) THEN
        SET v_err = 'NPA after days is required and must be at least 1';
    END IF;

    
    
    IF v_err IS NULL AND p_loan_ledger IS NOT NULL THEN
        SET v_ledger_active = (SELECT IFNULL(Is_Active, 0) FROM mst_acct_ledger WHERE Ledger_Id = p_loan_ledger);
        IF v_ledger_active IS NULL THEN
            SET v_err = 'Loan ledger not found';
        ELSEIF v_ledger_active <> 1 AND NOT (p_loan_ledger <=> v_old_loan) THEN
            SET v_err = 'Loan ledger is inactive';
        END IF;
    END IF;

    IF v_err IS NULL AND p_intt_ledger IS NOT NULL THEN
        SET v_ledger_active = (SELECT IFNULL(Is_Active, 0) FROM mst_acct_ledger WHERE Ledger_Id = p_intt_ledger);
        IF v_ledger_active IS NULL THEN
            SET v_err = 'Interest ledger not found';
        ELSEIF v_ledger_active <> 1 AND NOT (p_intt_ledger <=> v_old_intt) THEN
            SET v_err = 'Interest ledger is inactive';
        END IF;
    END IF;

    IF v_err IS NULL AND p_odintt_ledger IS NOT NULL THEN
        SET v_ledger_active = (SELECT IFNULL(Is_Active, 0) FROM mst_acct_ledger WHERE Ledger_Id = p_odintt_ledger);
        IF v_ledger_active IS NULL THEN
            SET v_err = 'Overdue interest ledger not found';
        ELSEIF v_ledger_active <> 1 AND NOT (p_odintt_ledger <=> v_old_odintt) THEN
            SET v_err = 'Overdue interest ledger is inactive';
        END IF;
    END IF;

    IF v_err IS NULL AND (
        (p_loan_ledger IS NOT NULL AND (p_loan_ledger = p_intt_ledger OR p_loan_ledger = p_odintt_ledger))
        OR (p_intt_ledger IS NOT NULL AND p_intt_ledger = p_odintt_ledger)
    ) THEN
        SET v_err = 'Loan, interest and overdue interest ledgers must be different';
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        CALL USP_CODE_SERIES_GENERATE('loan_scheme', v_gen_code, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
            SET v_err = IFNULL(v_gen_msg, 'Unable to generate scheme code');
        ELSEIF CHAR_LENGTH(v_gen_code) > 25 THEN
            SET v_err = 'Generated scheme code exceeds 25 characters. Check loan_scheme code series';
        ELSE
            SET v_code = CONVERT(v_gen_code USING utf8mb4) COLLATE utf8mb4_0900_ai_ci;
            SELECT COUNT(*) INTO v_cnt FROM mst_loan_scheme WHERE UPPER(Scheme_Code) = UPPER(v_code);
            IF v_cnt > 0 THEN
                SET v_err = 'Scheme code already exists. Check loan_scheme code series counter';
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status,
               IF(v_action = 'EDIT', p_scheme_id, NULL) AS scheme_id,
               NULL AS scheme_code,
               v_err AS message;

    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_scheme (
            Scheme_Name, Scheme_Code, Product_Type_Cd, Repay_Type_Cd, RoI_Percent,
            Intt_Type_Cd, Repay_Schedule_Cd, Is_Intt_Capitalisation, Capitalisation_On_Cd,
            Is_Incentive, Incentive_Day, Incentive_Rate,
            Is_Overdue, Repay_Grace_Days, OverdueOn_Cd, Overdur_Rate,
            Is_NPA, NPA_After_Days, Is_Mortgage_Reqd, Is_Guarantor_Reqd,
            Loan_Ledger, Intt_Ledger, OdIntt_Ledger, Field_Coll_Allow,
            Is_Active, Created_By, Created_At
        ) VALUES (
            v_name, v_code, p_product_type_cd, p_repay_type_cd, p_roi_percent,
            p_intt_type_cd, p_repay_schedule_cd, v_cap, v_cap_on,
            v_inc, v_inc_day, v_inc_rate,
            v_od, v_grace, v_od_on, v_od_rate,
            v_npa, v_npa_days,
            IF(IFNULL(p_is_mortgage_reqd, 0) = 1, 1, 0),
            IF(IFNULL(p_is_guarantor_reqd, 0) = 1, 1, 0),
            p_loan_ledger, p_intt_ledger, p_odintt_ledger,
            IF(IFNULL(p_field_coll_allow, 0) = 1, 1, 0),
            IF(IFNULL(p_is_active, 1) = 1, 1, 0), p_user_id, NOW()
        );

        SET v_new_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_new_id AS scheme_id, v_code AS scheme_code,
               'Loan scheme created successfully' AS message;

    ELSE
        UPDATE mst_loan_scheme
        SET Scheme_Name = v_name,
            Product_Type_Cd = p_product_type_cd,
            Repay_Type_Cd = p_repay_type_cd,
            RoI_Percent = p_roi_percent,
            Intt_Type_Cd = p_intt_type_cd,
            Repay_Schedule_Cd = p_repay_schedule_cd,
            Is_Intt_Capitalisation = v_cap,
            Capitalisation_On_Cd = v_cap_on,
            Is_Incentive = v_inc,
            Incentive_Day = v_inc_day,
            Incentive_Rate = v_inc_rate,
            Is_Overdue = v_od,
            Repay_Grace_Days = v_grace,
            OverdueOn_Cd = v_od_on,
            Overdur_Rate = v_od_rate,
            Is_NPA = v_npa,
            NPA_After_Days = v_npa_days,
            Is_Mortgage_Reqd = IF(IFNULL(p_is_mortgage_reqd, 0) = 1, 1, 0),
            Is_Guarantor_Reqd = IF(IFNULL(p_is_guarantor_reqd, 0) = 1, 1, 0),
            Loan_Ledger = p_loan_ledger,
            Intt_Ledger = p_intt_ledger,
            OdIntt_Ledger = p_odintt_ledger,
            Field_Coll_Allow = IF(IFNULL(p_field_coll_allow, 0) = 1, 1, 0),
            Is_Active = IF(p_is_active IS NULL, Is_Active, IF(p_is_active = 1, 1, 0)),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Scheme_Id = p_scheme_id;

        SELECT 'SUCCESS' AS status, p_scheme_id AS scheme_id, Scheme_Code AS scheme_code,
               'Loan scheme updated successfully' AS message
        FROM mst_loan_scheme
        WHERE Scheme_Id = p_scheme_id;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEME_CHARGES_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_CHARGES_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_scheme_id INT,
    IN p_charge_ids TEXT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_action VARCHAR(10);
    DECLARE v_err VARCHAR(500) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_bad TEXT DEFAULT NULL;
    DECLARE v_inserted INT DEFAULT 0;
    DECLARE v_reactivated INT DEFAULT 0;
    DECLARE v_deactivated INT DEFAULT 0;
    DECLARE v_unchanged INT DEFAULT 0;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Invalid action. Use ADD or EDIT';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_loan_scheme WHERE Scheme_Id = p_scheme_id;
        IF p_scheme_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan scheme not found';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        IF p_charge_ids IS NULL OR JSON_VALID(p_charge_ids) = 0 THEN
            SET v_err = 'Charge ids must be a JSON array';
        ELSEIF JSON_TYPE(p_charge_ids) <> 'ARRAY' THEN
            SET v_err = 'Charge ids must be a JSON array';
        ELSEIF v_action = 'ADD' AND JSON_LENGTH(p_charge_ids) = 0 THEN
            SET v_err = 'At least one charge is required';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM JSON_TABLE(p_charge_ids, '$[*]' COLUMNS (cid INT PATH '$' NULL ON EMPTY NULL ON ERROR)) jt
        WHERE jt.cid IS NULL OR jt.cid < 1;
        IF v_cnt > 0 THEN
            SET v_err = 'Charge ids must be positive integers';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT GROUP_CONCAT(DISTINCT jt.cid ORDER BY jt.cid SEPARATOR ', ') INTO v_bad
        FROM JSON_TABLE(p_charge_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
        LEFT JOIN mst_loan_charges c ON c.Charge_Id = jt.cid AND IFNULL(c.Is_Active, 0) = 1
        WHERE c.Charge_Id IS NULL;
        IF v_bad IS NOT NULL THEN
            SET v_err = CONCAT('Invalid or inactive loan charge id(s): ', v_bad);
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_scheme_id AS scheme_id,
               0 AS inserted, 0 AS reactivated, 0 AS deactivated, 0 AS unchanged,
               v_err AS message;
    ELSE
        SELECT COUNT(DISTINCT jt.cid) INTO v_unchanged
        FROM JSON_TABLE(p_charge_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
        JOIN mst_loan_scheme_charges sc
          ON sc.Scheme_Id = p_scheme_id AND sc.Charge_Id = jt.cid AND IFNULL(sc.Is_Active, 0) = 1;

        UPDATE mst_loan_scheme_charges sc
        JOIN (
            SELECT DISTINCT jt.cid
            FROM JSON_TABLE(p_charge_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
        ) j ON j.cid = sc.Charge_Id
        SET sc.Is_Active = 1
        WHERE sc.Scheme_Id = p_scheme_id
          AND IFNULL(sc.Is_Active, 0) = 0;
        SET v_reactivated = ROW_COUNT();

        INSERT INTO mst_loan_scheme_charges (Scheme_Id, Charge_Id, Is_Active, Created_By, Created_At)
        SELECT p_scheme_id, j.cid, 1, p_user_id, NOW()
        FROM (
            SELECT DISTINCT jt.cid
            FROM JSON_TABLE(p_charge_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
        ) j
        WHERE NOT EXISTS (
            SELECT 1 FROM mst_loan_scheme_charges sc
            WHERE sc.Scheme_Id = p_scheme_id AND sc.Charge_Id = j.cid
        );
        SET v_inserted = ROW_COUNT();

        IF v_action = 'EDIT' THEN
            UPDATE mst_loan_scheme_charges
            SET Is_Active = 0
            WHERE Scheme_Id = p_scheme_id
              AND IFNULL(Is_Active, 0) = 1
              AND Charge_Id NOT IN (
                  SELECT jt.cid
                  FROM JSON_TABLE(p_charge_ids, '$[*]' COLUMNS (cid INT PATH '$')) jt
              );
            SET v_deactivated = ROW_COUNT();
        END IF;

        SELECT 'SUCCESS' AS status, p_scheme_id AS scheme_id,
               v_inserted AS inserted, v_reactivated AS reactivated,
               v_deactivated AS deactivated, v_unchanged AS unchanged,
               IF(v_action = 'ADD',
                  'Loan scheme charges assigned successfully',
                  'Loan scheme charges updated successfully') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEME_CHARGES_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_CHARGES_LIST`(
    IN p_id INT,
    IN p_scheme_id INT,
    IN p_charge_id INT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_loan_scheme_charges sc
    WHERE (p_id IS NULL OR sc.Id = p_id)
      AND (p_scheme_id IS NULL OR sc.Scheme_Id = p_scheme_id)
      AND (p_charge_id IS NULL OR sc.Charge_Id = p_charge_id)
      AND (p_is_active IS NULL OR IFNULL(sc.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        sc.Id,
        sc.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        sc.Charge_Id,
        c.Charge_Name,
        c.Charge_Rate,
        c.Figure_Cd,
        fg.Opt_Description AS Figure_Desc,
        c.Max_Amount,
        c.Tax_Prcent,
        c.Deduct_During_Cd,
        dd.Opt_Description AS Deduct_During_Desc,
        c.Charges_Gl,
        l.Ledger_Code AS Charges_Gl_Code,
        l.Ledger_Name AS Charges_Gl_Name,
        IFNULL(c.Is_Refundable, 0) AS Is_Refundable,
        IFNULL(c.Is_Active, 0) AS Charge_Is_Active,
        IFNULL(sc.Is_Active, 0) AS Is_Active,
        sc.Created_By,
        sc.Created_At
    FROM mst_loan_scheme_charges sc
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = sc.Scheme_Id
    LEFT JOIN mst_loan_charges c ON c.Charge_Id = sc.Charge_Id
    LEFT JOIN mst_appl_options fg ON fg.Opt_Grp_Id = 16 AND fg.Opt_Code = c.Figure_Cd
    LEFT JOIN mst_appl_options dd ON dd.Opt_Grp_Id = 23 AND dd.Opt_Code = c.Deduct_During_Cd
    LEFT JOIN mst_acct_ledger l ON l.Ledger_Id = c.Charges_Gl
    WHERE (p_id IS NULL OR sc.Id = p_id)
      AND (p_scheme_id IS NULL OR sc.Scheme_Id = p_scheme_id)
      AND (p_charge_id IS NULL OR sc.Charge_Id = p_charge_id)
      AND (p_is_active IS NULL OR IFNULL(sc.Is_Active, 0) = p_is_active)
    ORDER BY s.Scheme_Code ASC, c.Charge_Name ASC, sc.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEME_CHARGES_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_CHARGES_STATUS`(
    IN p_id INT,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current TINYINT DEFAULT NULL;
    DECLARE v_charge_active TINYINT DEFAULT 0;

    SELECT COUNT(*) INTO v_cnt FROM mst_loan_scheme_charges WHERE Id = p_id;

    IF p_id IS NULL OR v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_id AS id, NULL AS is_active, 'Loan scheme charge not found' AS message;
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_id AS id, NULL AS is_active,
               'Status must be 1 (active) or 0 (inactive)' AS message;
    ELSE
        SELECT IFNULL(sc.Is_Active, 0), IFNULL(c.Is_Active, 0)
        INTO v_current, v_charge_active
        FROM mst_loan_scheme_charges sc
        LEFT JOIN mst_loan_charges c ON c.Charge_Id = sc.Charge_Id
        WHERE sc.Id = p_id;

        IF v_current = p_is_active THEN
            SELECT 'SUCCESS' AS status, p_id AS id, v_current AS is_active,
                   IF(p_is_active = 1, 'Loan scheme charge is already active', 'Loan scheme charge is already inactive') AS message;
        ELSEIF p_is_active = 1 AND v_charge_active = 0 THEN
            SELECT 'ERROR' AS status, p_id AS id, v_current AS is_active,
                   'Loan charge is inactive and cannot be assigned to a scheme' AS message;
        ELSE
            UPDATE mst_loan_scheme_charges SET Is_Active = p_is_active WHERE Id = p_id;

            SELECT 'SUCCESS' AS status, p_id AS id, p_is_active AS is_active,
                   IF(p_is_active = 1, 'Loan scheme charge activated successfully', 'Loan scheme charge deactivated successfully') AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
