CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_LIST`(
    IN p_scheme_id INT,
    IN p_keyword VARCHAR(150),
    IN p_product_type_cd TINYINT,
    IN p_repay_type_cd TINYINT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_loan_scheme s
    WHERE (p_scheme_id IS NULL OR s.Scheme_Id = p_scheme_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(s.Scheme_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(s.Scheme_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_product_type_cd IS NULL OR s.Product_Type_Cd = p_product_type_cd)
      AND (p_repay_type_cd IS NULL OR s.Repay_Type_Cd = p_repay_type_cd)
      AND (p_is_active IS NULL OR IFNULL(s.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        s.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        s.Product_Type_Cd,
        pt.Opt_Description AS Product_Type_Desc,
        s.Repay_Type_Cd,
        rt.Opt_Description AS Repay_Type_Desc,
        s.RoI_Percent,
        s.Intt_Type_Cd,
        it.Opt_Description AS Intt_Type_Desc,
        s.Repay_Schedule_Cd,
        rs.Opt_Description AS Repay_Schedule_Desc,
        IFNULL(s.Is_Intt_Capitalisation, 0) AS Is_Intt_Capitalisation,
        s.Capitalisation_On_Cd,
        co.Opt_Description AS Capitalisation_On_Desc,
        IFNULL(s.Is_Incentive, 0) AS Is_Incentive,
        s.Incentive_Day,
        s.Incentive_Rate,
        IFNULL(s.Is_Overdue, 0) AS Is_Overdue,
        s.Repay_Grace_Days,
        s.OverdueOn_Cd,
        oo.Opt_Description AS Overdue_On_Desc,
        s.Overdur_Rate,
        IFNULL(s.Is_NPA, 0) AS Is_NPA,
        s.NPA_After_Days,
        IFNULL(s.Is_Mortgage_Reqd, 0) AS Is_Mortgage_Reqd,
        IFNULL(s.Is_Guarantor_Reqd, 0) AS Is_Guarantor_Reqd,
        s.Loan_Ledger,
        ll.Ledger_Code AS Loan_Ledger_Code,
        ll.Ledger_Name AS Loan_Ledger_Name,
        ll.Ledger_Type AS Loan_Ledger_Type,
        ll.MainHd_Id AS Loan_Ledger_MainHd_Id,
        lh.MainHd_Name AS Loan_Ledger_MainHd_Name,
        ll.Is_Active AS Loan_Ledger_Is_Active,
        s.Intt_Ledger,
        il.Ledger_Code AS Intt_Ledger_Code,
        il.Ledger_Name AS Intt_Ledger_Name,
        il.Ledger_Type AS Intt_Ledger_Type,
        il.MainHd_Id AS Intt_Ledger_MainHd_Id,
        ih.MainHd_Name AS Intt_Ledger_MainHd_Name,
        il.Is_Active AS Intt_Ledger_Is_Active,
        s.OdIntt_Ledger,
        ol.Ledger_Code AS OdIntt_Ledger_Code,
        ol.Ledger_Name AS OdIntt_Ledger_Name,
        ol.Ledger_Type AS OdIntt_Ledger_Type,
        ol.MainHd_Id AS OdIntt_Ledger_MainHd_Id,
        oh.MainHd_Name AS OdIntt_Ledger_MainHd_Name,
        ol.Is_Active AS OdIntt_Ledger_Is_Active,
        IFNULL(s.Field_Coll_Allow, 0) AS Field_Coll_Allow,
        IFNULL(s.Is_Active, 0) AS Is_Active,
        s.Created_By,
        s.Created_At,
        s.Updated_By,
        s.Updated_At
    FROM mst_loan_scheme s
    LEFT JOIN mst_appl_options pt ON pt.Opt_Grp_Id = 17 AND pt.Opt_Code = s.Product_Type_Cd
    LEFT JOIN mst_appl_options rt ON rt.Opt_Grp_Id = 18 AND rt.Opt_Code = s.Repay_Type_Cd
    LEFT JOIN mst_appl_options it ON it.Opt_Grp_Id = 19 AND it.Opt_Code = s.Intt_Type_Cd
    LEFT JOIN mst_appl_options co ON co.Opt_Grp_Id = 20 AND co.Opt_Code = s.Capitalisation_On_Cd
    LEFT JOIN mst_appl_options oo ON oo.Opt_Grp_Id = 21 AND oo.Opt_Code = s.OverdueOn_Cd
    LEFT JOIN mst_appl_options rs ON rs.Opt_Grp_Id = 22 AND rs.Opt_Code = s.Repay_Schedule_Cd
    LEFT JOIN mst_acct_ledger ll ON ll.Ledger_Id = s.Loan_Ledger
    LEFT JOIN mst_acct_head lh ON lh.MainHd_Id = ll.MainHd_Id
    LEFT JOIN mst_acct_ledger il ON il.Ledger_Id = s.Intt_Ledger
    LEFT JOIN mst_acct_head ih ON ih.MainHd_Id = il.MainHd_Id
    LEFT JOIN mst_acct_ledger ol ON ol.Ledger_Id = s.OdIntt_Ledger
    LEFT JOIN mst_acct_head oh ON oh.MainHd_Id = ol.MainHd_Id
    WHERE (p_scheme_id IS NULL OR s.Scheme_Id = p_scheme_id)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(s.Scheme_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(s.Scheme_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_product_type_cd IS NULL OR s.Product_Type_Cd = p_product_type_cd)
      AND (p_repay_type_cd IS NULL OR s.Repay_Type_Cd = p_repay_type_cd)
      AND (p_is_active IS NULL OR IFNULL(s.Is_Active, 0) = p_is_active)
    ORDER BY s.Scheme_Code ASC, s.Scheme_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEME_SLAB_ADD_EDIT` */;
