/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_SLAB_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_id INT,
    IN p_scheme_id INT,
    IN p_min_amount DECIMAL(12,2),
    IN p_max_amount DECIMAL(12,2),
    IN p_roi DECIMAL(6,2),
    IN p_max_duration INT,
    IN p_amt_per1000 DECIMAL(10,2),
    IN p_effect_from DATE,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_action VARCHAR(10);
    DECLARE v_active TINYINT DEFAULT 1;
    DECLARE v_scheme_active TINYINT DEFAULT 0;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(IFNULL(Is_Active, 0)) INTO v_cnt, v_active
        FROM mst_loan_scheme_slab WHERE Id = p_id;
        IF p_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan scheme slab not found';
        END IF;
        IF p_is_active IS NOT NULL THEN
            SET v_active = IF(p_is_active = 1, 1, 0);
        END IF;
    ELSE
        SET v_active = IF(IFNULL(p_is_active, 1) = 1, 1, 0);
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(IFNULL(Is_Active, 0)) INTO v_cnt, v_scheme_active
        FROM mst_loan_scheme WHERE Scheme_Id = p_scheme_id;
        IF p_scheme_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Loan scheme not found';
        ELSEIF v_action = 'ADD' AND v_scheme_active = 0 THEN
            SET v_err = 'Loan scheme is inactive';
        END IF;
    END IF;

    IF v_err IS NULL AND (p_min_amount IS NULL OR p_max_amount IS NULL) THEN
        SET v_err = 'Minimum and maximum amount are required';
    END IF;

    IF v_err IS NULL AND (p_min_amount <> FLOOR(p_min_amount) OR p_max_amount <> FLOOR(p_max_amount)) THEN
        SET v_err = 'Amounts must be whole numbers';
    END IF;

    IF v_err IS NULL AND (p_min_amount < 0 OR p_max_amount > 9999999999) THEN
        SET v_err = 'Amounts must be between 0 and 9999999999';
    END IF;

    IF v_err IS NULL AND (p_max_amount < 1 OR p_max_amount < p_min_amount) THEN
        SET v_err = 'Maximum amount must be at least 1 and not less than minimum amount';
    END IF;

    IF v_err IS NULL AND (p_roi IS NULL OR p_roi < 0 OR p_roi > 100) THEN
        SET v_err = 'Rate of interest is required and must be between 0 and 100';
    END IF;

    IF v_err IS NULL AND (p_max_duration IS NULL OR p_max_duration < 1 OR p_max_duration > 32767) THEN
        SET v_err = 'Maximum duration is required and must be between 1 and 32767';
    END IF;

    IF v_err IS NULL AND p_amt_per1000 IS NOT NULL AND (p_amt_per1000 < 0 OR p_amt_per1000 > 999999.99) THEN
        SET v_err = 'Amount per 1000 must be between 0 and 999999.99';
    END IF;

    IF v_err IS NULL AND p_effect_from IS NULL THEN
        SET v_err = 'Effective from date is required';
    END IF;

    IF v_err IS NULL AND v_active = 1 THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_loan_scheme_slab
        WHERE Scheme_Id = p_scheme_id
          AND IFNULL(Is_Active, 0) = 1
          AND Effect_From = p_effect_from
          AND Min_Amount <= p_max_amount
          AND Max_Amount >= p_min_amount
          AND (v_action = 'ADD' OR Id <> p_id);
        IF v_cnt > 0 THEN
            SET v_err = 'An active slab already covers this amount range for this scheme from the same effective date';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_id AS id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_loan_scheme_slab (
            Scheme_Id, Min_Amount, Max_Amount, RoI, Max_Duration, Amt_Per1000,
            Effect_From, Is_Active, Created_By, Created_At
        ) VALUES (
            p_scheme_id, p_min_amount, p_max_amount, p_roi, p_max_duration, p_amt_per1000,
            p_effect_from, v_active, p_user_id, NOW()
        );

        SELECT 'SUCCESS' AS status, LAST_INSERT_ID() AS id, 'Loan scheme slab created successfully' AS message;
    ELSE
        UPDATE mst_loan_scheme_slab
        SET Scheme_Id = p_scheme_id,
            Min_Amount = p_min_amount,
            Max_Amount = p_max_amount,
            RoI = p_roi,
            Max_Duration = p_max_duration,
            Amt_Per1000 = p_amt_per1000,
            Effect_From = p_effect_from,
            Is_Active = v_active
        WHERE Id = p_id;

        SELECT 'SUCCESS' AS status, p_id AS id, 'Loan scheme slab updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEME_SLAB_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_SLAB_LIST`(
    IN p_id INT,
    IN p_scheme_id INT,
    IN p_amount DECIMAL(12,2),
    IN p_effective_on DATE,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_loan_scheme_slab sl
    WHERE (p_id IS NULL OR sl.Id = p_id)
      AND (p_scheme_id IS NULL OR sl.Scheme_Id = p_scheme_id)
      AND (p_amount IS NULL OR (sl.Min_Amount <= p_amount AND sl.Max_Amount >= p_amount))
      AND (p_effective_on IS NULL OR sl.Effect_From <= p_effective_on)
      AND (p_is_active IS NULL OR IFNULL(sl.Is_Active, 0) = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        sl.Id,
        sl.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        s.Repay_Schedule_Cd,
        rs.Opt_Description AS Repay_Schedule_Desc,
        IFNULL(s.Is_Active, 0) AS Scheme_Is_Active,
        sl.Min_Amount,
        sl.Max_Amount,
        sl.RoI,
        sl.Max_Duration,
        sl.Amt_Per1000,
        sl.Effect_From,
        sl.Is_Active,
        sl.Created_By,
        sl.Created_At
    FROM mst_loan_scheme_slab sl
    LEFT JOIN mst_loan_scheme s ON s.Scheme_Id = sl.Scheme_Id
    LEFT JOIN mst_appl_options rs ON rs.Opt_Grp_Id = 22 AND rs.Opt_Code = s.Repay_Schedule_Cd
    WHERE (p_id IS NULL OR sl.Id = p_id)
      AND (p_scheme_id IS NULL OR sl.Scheme_Id = p_scheme_id)
      AND (p_amount IS NULL OR (sl.Min_Amount <= p_amount AND sl.Max_Amount >= p_amount))
      AND (p_effective_on IS NULL OR sl.Effect_From <= p_effective_on)
      AND (p_is_active IS NULL OR IFNULL(sl.Is_Active, 0) = p_is_active)
    ORDER BY s.Scheme_Code ASC, sl.Min_Amount ASC, sl.Effect_From DESC, sl.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEME_SLAB_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_SLAB_STATUS`(
    IN p_id INT,
    IN p_is_active TINYINT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current TINYINT DEFAULT NULL;
    DECLARE v_scheme_id INT;
    DECLARE v_min DECIMAL(10,0);
    DECLARE v_max DECIMAL(10,0);
    DECLARE v_frm DATE;

    SELECT COUNT(*) INTO v_cnt FROM mst_loan_scheme_slab WHERE Id = p_id;

    IF p_id IS NULL OR v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_id AS id, NULL AS is_active, 'Loan scheme slab not found' AS message;
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_id AS id, NULL AS is_active,
               'Status must be 1 (active) or 0 (inactive)' AS message;
    ELSE
        SELECT IFNULL(Is_Active, 0), Scheme_Id, Min_Amount, Max_Amount, Effect_From
        INTO v_current, v_scheme_id, v_min, v_max, v_frm
        FROM mst_loan_scheme_slab
        WHERE Id = p_id;

        IF v_current = p_is_active THEN
            SELECT 'SUCCESS' AS status, p_id AS id, v_current AS is_active,
                   IF(p_is_active = 1, 'Loan scheme slab is already active', 'Loan scheme slab is already inactive') AS message;
        ELSE
            SET v_cnt = 0;

            IF p_is_active = 1 THEN
                SELECT COUNT(*) INTO v_cnt
                FROM mst_loan_scheme_slab
                WHERE Scheme_Id = v_scheme_id
                  AND IFNULL(Is_Active, 0) = 1
                  AND Id <> p_id
                  AND Effect_From = v_frm
                  AND Min_Amount <= v_max
                  AND Max_Amount >= v_min;
            END IF;

            IF v_cnt > 0 THEN
                SELECT 'ERROR' AS status, p_id AS id, v_current AS is_active,
                       'An active slab already covers this amount range for this scheme from the same effective date' AS message;
            ELSE
                UPDATE mst_loan_scheme_slab SET Is_Active = p_is_active WHERE Id = p_id;

                SELECT 'SUCCESS' AS status, p_id AS id, p_is_active AS is_active,
                       IF(p_is_active = 1, 'Loan scheme slab activated successfully', 'Loan scheme slab deactivated successfully') AS message;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_SCHEME_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_SCHEME_STATUS`(
    IN p_scheme_id INT,
    IN p_is_active TINYINT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_code VARCHAR(25) DEFAULT NULL;
    DECLARE v_current TINYINT DEFAULT NULL;

    SELECT COUNT(*) INTO v_cnt FROM mst_loan_scheme WHERE Scheme_Id = p_scheme_id;

    IF p_scheme_id IS NULL OR v_cnt = 0 THEN
        SELECT 'ERROR' AS status, p_scheme_id AS scheme_id, NULL AS scheme_code, NULL AS is_active,
               'Loan scheme not found' AS message;
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SELECT 'ERROR' AS status, p_scheme_id AS scheme_id, NULL AS scheme_code, NULL AS is_active,
               'Status must be 1 (active) or 0 (inactive)' AS message;
    ELSE
        SELECT Scheme_Code, IFNULL(Is_Active, 0) INTO v_code, v_current
        FROM mst_loan_scheme
        WHERE Scheme_Id = p_scheme_id;

        IF v_current = p_is_active THEN
            SELECT 'SUCCESS' AS status, p_scheme_id AS scheme_id, v_code AS scheme_code, v_current AS is_active,
                   IF(p_is_active = 1, 'Loan scheme is already active', 'Loan scheme is already inactive') AS message;
        ELSE
            UPDATE mst_loan_scheme
            SET Is_Active = p_is_active,
                Updated_By = p_user_id,
                Updated_At = NOW()
            WHERE Scheme_Id = p_scheme_id;

            SELECT 'SUCCESS' AS status, p_scheme_id AS scheme_id, v_code AS scheme_code, p_is_active AS is_active,
                   IF(p_is_active = 1, 'Loan scheme activated successfully', 'Loan scheme deactivated successfully') AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
