CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_VOUCHER_POST`(
    IN p_branch_id INT,
    IN p_date DATE,
    IN p_vou_type INT,
    IN p_payment_mode INT,
    IN p_particulars VARCHAR(255),
    IN p_user_id INT,
    OUT p_voucher_id BIGINT,
    OUT p_voucher_no VARCHAR(25),
    OUT p_note VARCHAR(255)
)
proc: BEGIN
    DECLARE v_contra INT DEFAULT NULL;
    DECLARE v_missing VARCHAR(255) DEFAULT NULL;
    DECLARE v_dr DECIMAL(14,2) DEFAULT 0;
    DECLARE v_cr DECIMAL(14,2) DEFAULT 0;
    DECLARE v_year INT DEFAULT NULL;
    DECLARE v_no INT DEFAULT NULL;
    DECLARE v_ref VARCHAR(150) DEFAULT NULL;
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET p_voucher_id = NULL;
    SET p_voucher_no = NULL;
    SET p_note = NULL;

    IF p_payment_mode = 1 THEN
        SELECT NULLIF(MAX(Value), 0) INTO v_contra FROM mst_settings_global WHERE Id = 101;
    ELSEIF p_payment_mode IN (2, 3) THEN
        SELECT NULLIF(MAX(Value), 0) INTO v_contra FROM mst_settings_global WHERE Id = 102;
    END IF;

    UPDATE tmp_loan_voucher_lines SET GL_Account_Id = v_contra WHERE Line_Role = 'CONTRA';
    DELETE FROM tmp_loan_voucher_lines WHERE Debit_Amount = 0 AND Credit_Amount = 0;

    SELECT GROUP_CONCAT(DISTINCT t.Line_Role ORDER BY t.Line_Role SEPARATOR ', ') INTO v_missing
    FROM tmp_loan_voucher_lines t
    LEFT JOIN mst_acct_ledger l ON l.Ledger_Id = t.GL_Account_Id AND IFNULL(l.Is_Active, 0) = 1
    WHERE l.Ledger_Id IS NULL;

    IF v_missing IS NOT NULL THEN
        SET p_note = LEFT(CONCAT('Voucher not posted: ledger not mapped for ', v_missing), 255);
        LEAVE proc;
    END IF;

    SELECT IFNULL(SUM(Debit_Amount), 0), IFNULL(SUM(Credit_Amount), 0), COUNT(*) INTO v_dr, v_cr, v_no
    FROM tmp_loan_voucher_lines;

    IF v_no = 0 THEN
        SET p_note = 'Voucher not posted: nothing to post';
        LEAVE proc;
    ELSEIF v_dr <> v_cr THEN
        SET p_note = CONCAT('Voucher not posted: debit ', FORMAT(v_dr, 2), ' <> credit ', FORMAT(v_cr, 2));
        LEAVE proc;
    END IF;

    SELECT MAX(Year_Id) INTO v_year FROM mst_fin_year WHERE p_date BETWEEN Start_Date AND End_Date;
    IF v_year IS NULL THEN
        SET p_note = 'Voucher not posted: no financial year covers the transaction date';
        LEAVE proc;
    END IF;

    SELECT IFNULL(MAX(Voucher_No), 0) + 1 INTO v_no
    FROM trans_vouchers WHERE Branch_Id = p_branch_id AND Year_Id = v_year FOR UPDATE;

    CALL USP_CODE_SERIES_GENERATE(IF(p_vou_type = 1, 'receipt', 'voucher_journal'), v_ref, v_gen_status, v_gen_msg);
    IF v_gen_status <> 'SUCCESS' OR v_ref IS NULL THEN
        SET v_ref = CONCAT('V', v_year, '-', v_no);
    END IF;

    INSERT INTO trans_vouchers (
        Voucher_No, Vou_No_Ref, Year_Id, Voucher_Date, Vou_Type_Cd, Vou_Mode_Cd, Vou_Particulars,
        Total_Debit, Total_Credit, Branch_Id, Vou_Status_Cd, Created_By, Created_At, Approved_By, Approved_At
    ) VALUES (
        v_no, LEFT(v_ref, 25), v_year, p_date, p_vou_type,
        CASE WHEN p_payment_mode = 1 THEN 1 WHEN p_payment_mode IN (2, 3) THEN 2 ELSE 3 END,
        LEFT(IFNULL(p_particulars, 'Loan transaction'), 255),
        v_dr, v_cr, p_branch_id, 2, p_user_id, NOW(), p_user_id, NOW()
    );

    SET p_voucher_id = LAST_INSERT_ID();
    SET p_voucher_no = LEFT(v_ref, 25);

    INSERT INTO trans_voucher_details (Voucher_Id, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration)
    SELECT p_voucher_id, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration
    FROM tmp_loan_voucher_lines ORDER BY Line_No;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_VOUCHER_RESET` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_VOUCHER_RESET`()
BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_loan_voucher_lines;
    CREATE TEMPORARY TABLE tmp_loan_voucher_lines (
        Line_No INT AUTO_INCREMENT PRIMARY KEY,
        Line_Role VARCHAR(30) NOT NULL,
        GL_Account_Id INT NULL,
        Debit_Amount DECIMAL(12,2) NOT NULL DEFAULT 0,
        Credit_Amount DECIMAL(12,2) NOT NULL DEFAULT 0,
        Line_Narration VARCHAR(300) NULL
    );
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_LOAN_VOUCHER_REVERSE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_LOAN_VOUCHER_REVERSE`(
    IN p_voucher_id BIGINT,
    IN p_date DATE,
    IN p_user_id INT,
    OUT p_new_voucher_id BIGINT,
    OUT p_new_voucher_no VARCHAR(25)
)
proc: BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_branch INT;
    DECLARE v_year INT;
    DECLARE v_type INT;
    DECLARE v_mode INT;
    DECLARE v_part VARCHAR(255);
    DECLARE v_dr DECIMAL(14,2);
    DECLARE v_cr DECIMAL(14,2);
    DECLARE v_no INT;
    DECLARE v_ref VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET p_new_voucher_id = NULL;
    SET p_new_voucher_no = NULL;

    IF p_voucher_id IS NULL THEN
        LEAVE proc;
    END IF;

    SELECT COUNT(*), MAX(Branch_Id), MAX(Vou_Type_Cd), MAX(Vou_Mode_Cd), MAX(Vou_Particulars), MAX(Total_Debit), MAX(Total_Credit)
    INTO v_cnt, v_branch, v_type, v_mode, v_part, v_dr, v_cr
    FROM trans_vouchers WHERE Voucher_Id = p_voucher_id AND Vou_Status_Cd <> 4 FOR UPDATE;

    IF v_cnt = 0 THEN
        LEAVE proc;
    END IF;

    SELECT MAX(Year_Id) INTO v_year FROM mst_fin_year WHERE p_date BETWEEN Start_Date AND End_Date;
    IF v_year IS NULL THEN
        SELECT Year_Id INTO v_year FROM trans_vouchers WHERE Voucher_Id = p_voucher_id;
    END IF;

    SELECT IFNULL(MAX(Voucher_No), 0) + 1 INTO v_no
    FROM trans_vouchers WHERE Branch_Id = v_branch AND Year_Id = v_year FOR UPDATE;

    CALL USP_CODE_SERIES_GENERATE('voucher_journal', v_ref, v_gen_status, v_gen_msg);
    IF v_gen_status <> 'SUCCESS' OR v_ref IS NULL THEN
        SET v_ref = CONCAT('V', v_year, '-', v_no);
    END IF;

    INSERT INTO trans_vouchers (
        Voucher_No, Vou_No_Ref, Year_Id, Voucher_Date, Vou_Type_Cd, Vou_Mode_Cd, Vou_Particulars,
        Total_Debit, Total_Credit, Branch_Id, Vou_Status_Cd, Reversed_Voucher_Id, Created_By, Created_At, Approved_By, Approved_At
    ) VALUES (
        v_no, LEFT(v_ref, 25), v_year, p_date, 3, v_mode, LEFT(CONCAT('Reversal: ', IFNULL(v_part, '')), 255),
        v_cr, v_dr, v_branch, 2, p_voucher_id, p_user_id, NOW(), p_user_id, NOW()
    );

    SET p_new_voucher_id = LAST_INSERT_ID();
    SET p_new_voucher_no = LEFT(v_ref, 25);

    INSERT INTO trans_voucher_details (Voucher_Id, GL_Account_Id, SubLedg_Ac_Id, Debit_Amount, Credit_Amount, Line_Narration)
    SELECT p_new_voucher_id, GL_Account_Id, SubLedg_Ac_Id, Credit_Amount, Debit_Amount, LEFT(CONCAT('Reversal: ', IFNULL(Line_Narration, '')), 300)
    FROM trans_voucher_details WHERE Voucher_Id = p_voucher_id ORDER BY Voucher_Detail_Id;

    UPDATE trans_vouchers SET Vou_Status_Cd = 4 WHERE Voucher_Id = p_voucher_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_member_id INT,
    IN p_ref_code VARCHAR(25),
    IN p_member_name VARCHAR(150),
    IN p_father_name VARCHAR(150),
    IN p_mother_name VARCHAR(150),
    IN p_spouse_name VARCHAR(150),
    IN p_gender_cd INT,
    IN p_date_of_birth DATE,
    IN p_marital_status_cd INT,
    IN p_religion_cd INT,
    IN p_caste_cd INT,
    IN p_mobile_no VARCHAR(20),
    IN p_alternate_mobile_no VARCHAR(20),
    IN p_email_id VARCHAR(100),
    IN p_pan_no VARCHAR(20),
    IN p_branch_id INT,
    IN p_center_id INT,
    IN p_joining_date DATE,
    IN p_occupation_details VARCHAR(200),
    IN p_monthly_income DECIMAL(12,2),
    IN p_monthly_expense DECIMAL(12,2),
    IN p_bank_name VARCHAR(150),
    IN p_bank_branch VARCHAR(150),
    IN p_bank_account_no VARCHAR(40),
    IN p_ifsc_code VARCHAR(20),
    IN p_nominee_name VARCHAR(150),
    IN p_nominee_rel_cd INT,
    IN p_nominee_dob DATE,
    IN p_nominee_mobile VARCHAR(20),
    IN p_photo_path VARCHAR(300),
    IN p_signature_path VARCHAR(300),
    IN p_fo_id INT,
    IN p_adm_fees DECIMAL(10,2),
    IN p_remarks VARCHAR(100),
    IN p_status_cd INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_action VARCHAR(10);
    DECLARE v_member_id INT DEFAULT NULL;
    DECLARE v_member_code VARCHAR(25) DEFAULT NULL;
    DECLARE v_cur_branch INT DEFAULT NULL;
    DECLARE v_cur_center INT DEFAULT NULL;
    DECLARE v_cur_fo INT DEFAULT NULL;
    DECLARE v_cur_status INT DEFAULT NULL;
    DECLARE v_cur_ref VARCHAR(25) DEFAULT NULL;
    DECLARE v_in_group INT DEFAULT 0;
    DECLARE v_status INT DEFAULT 1;
    DECLARE v_age INT DEFAULT NULL;
    DECLARE v_join DATE;
    DECLARE v_name VARCHAR(150);
    DECLARE v_ref VARCHAR(25);
    DECLARE v_mobile VARCHAR(20);
    DECLARE v_alt_mobile VARCHAR(20);
    DECLARE v_email VARCHAR(100);
    DECLARE v_pan VARCHAR(20);
    DECLARE v_acct VARCHAR(40);
    DECLARE v_ifsc VARCHAR(20);
    DECLARE v_nominee VARCHAR(150);
    DECLARE v_nominee_rel INT;
    DECLARE v_nominee_mobile VARCHAR(20);
    DECLARE v_gen_code VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_name = NULLIF(TRIM(IFNULL(p_member_name, '')), '');
    SET v_ref = NULLIF(TRIM(IFNULL(p_ref_code, '')), '');
    SET v_mobile = NULLIF(TRIM(IFNULL(p_mobile_no, '')), '');
    SET v_alt_mobile = NULLIF(TRIM(IFNULL(p_alternate_mobile_no, '')), '');
    SET v_email = LOWER(NULLIF(TRIM(IFNULL(p_email_id, '')), ''));
    SET v_pan = UPPER(NULLIF(TRIM(IFNULL(p_pan_no, '')), ''));
    SET v_acct = NULLIF(TRIM(IFNULL(p_bank_account_no, '')), '');
    SET v_ifsc = UPPER(NULLIF(TRIM(IFNULL(p_ifsc_code, '')), ''));
    SET v_nominee = NULLIF(TRIM(IFNULL(p_nominee_name, '')), '');
    SET v_nominee_rel = p_nominee_rel_cd;
    SET v_nominee_mobile = NULLIF(TRIM(IFNULL(p_nominee_mobile, '')), '');

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT COUNT(*), MAX(Branch_Id), MAX(Center_Id), MAX(FO_Id), MAX(Current_Status_Cd), MAX(Ref_Code)
        INTO v_cnt, v_cur_branch, v_cur_center, v_cur_fo, v_cur_status, v_cur_ref
        FROM mst_member WHERE Member_Id = p_member_id;

        IF p_member_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Member not found';
        ELSEIF v_cur_status IN (4, 5) THEN
            SET v_err = 'Closed or deceased member cannot be edited';
        ELSE
            SELECT COUNT(*) INTO v_in_group
            FROM mst_member_group WHERE Member_Id = p_member_id AND Is_Active = 1;
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        SET v_status = IFNULL(p_status_cd, 1);
        IF v_status NOT IN (1, 2) THEN
            SET v_err = 'New member status must be 1 (Active) or 2 (Inactive)';
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_name IS NULL THEN
        SET v_err = 'Member name is required';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 28 AND Opt_Code = p_gender_cd AND Is_Active = 1;
        IF p_gender_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid gender';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        IF p_date_of_birth IS NULL THEN
            SET v_err = 'Date of birth is required';
        ELSE
            SET v_age = TIMESTAMPDIFF(YEAR, p_date_of_birth, CURDATE());
            IF p_date_of_birth > CURDATE() THEN
                SET v_err = 'Date of birth cannot be in the future';
            ELSEIF v_age < 18 THEN
                SET v_err = 'Member must be at least 18 years old';
            ELSEIF v_age > 100 THEN
                SET v_err = 'Member age cannot be more than 100 years';
            END IF;
        END IF;
    END IF;

    IF v_err IS NULL AND p_marital_status_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 29 AND Opt_Code = p_marital_status_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid marital status';
        END IF;
    END IF;

    IF v_err IS NULL AND p_religion_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 30 AND Opt_Code = p_religion_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid religion';
        END IF;
    END IF;

    IF v_err IS NULL AND p_caste_cd IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 32 AND Opt_Code = p_caste_cd AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid caste';
        END IF;
    END IF;

    
    IF v_err IS NULL AND (v_mobile IS NULL OR v_mobile NOT REGEXP '^[6-9][0-9]{9}$') THEN
        SET v_err = 'Mobile number must be a valid 10-digit number';
    END IF;

    IF v_err IS NULL AND v_alt_mobile IS NOT NULL THEN
        IF v_alt_mobile NOT REGEXP '^[6-9][0-9]{9}$' THEN
            SET v_err = 'Alternate mobile number must be a valid 10-digit number';
        ELSEIF v_alt_mobile = v_mobile THEN
            SET v_err = 'Alternate mobile number must be different from mobile number';
        END IF;
    END IF;

    IF v_err IS NULL AND v_email IS NOT NULL AND v_email NOT REGEXP '^[^@[:space:]]+@[^@[:space:]]+\\.[^@[:space:]]+$' THEN
        SET v_err = 'Invalid email address';
    END IF;

    IF v_err IS NULL AND v_pan IS NOT NULL THEN
        IF v_pan NOT REGEXP '^[A-Z]{5}[0-9]{4}[A-Z]$' THEN
            SET v_err = 'Invalid PAN number';
        ELSE
            SELECT COUNT(*) INTO v_cnt FROM mst_member
            WHERE PAN_No = v_pan AND (v_action = 'ADD' OR Member_Id <> p_member_id);
            IF v_cnt > 0 THEN
                SET v_err = 'PAN number already registered for another member';
            END IF;
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_member
        WHERE LOWER(TRIM(Member_Name)) = LOWER(v_name)
          AND Date_of_Birth = p_date_of_birth
          AND Mobile_No = v_mobile
          AND (v_action = 'ADD' OR Member_Id <> p_member_id);
        IF v_cnt > 0 THEN
            SET v_err = 'A member with the same name, date of birth and mobile number already exists';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM priomicro_core.mst_org_branch
        WHERE Branch_Id = p_branch_id
          AND (IFNULL(Is_Active, 0) = 1 OR (v_action = 'EDIT' AND Branch_Id = v_cur_branch));
        IF p_branch_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Active branch not found';
        ELSEIF v_action = 'EDIT' AND p_branch_id <> v_cur_branch AND v_in_group > 0 THEN
            SET v_err = 'Branch cannot be changed while the member belongs to an active group';
        END IF;
    END IF;

    IF v_err IS NULL AND p_center_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_center
        WHERE Center_Id = p_center_id
          AND Branch_Id = p_branch_id
          AND (IFNULL(Is_Active, 0) = 1 OR (v_action = 'EDIT' AND Center_Id = v_cur_center));
        IF v_cnt = 0 THEN
            SET v_err = 'Active center not found for this branch';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SET v_join = IFNULL(p_joining_date, IF(v_action = 'ADD', CURDATE(), NULL));
        IF v_join IS NOT NULL AND v_join > CURDATE() THEN
            SET v_err = 'Joining date cannot be in the future';
        ELSEIF v_join IS NOT NULL AND TIMESTAMPDIFF(YEAR, p_date_of_birth, v_join) < 18 THEN
            SET v_err = 'Member must be at least 18 years old on the joining date';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_monthly_income IS NOT NULL AND (p_monthly_income < 0 OR p_monthly_income > 999999.99) THEN
        SET v_err = 'Monthly income must be between 0 and 999999.99';
    END IF;

    IF v_err IS NULL AND p_monthly_expense IS NOT NULL AND (p_monthly_expense < 0 OR p_monthly_expense > 999999.99) THEN
        SET v_err = 'Monthly expense must be between 0 and 999999.99';
    END IF;

    
    IF v_err IS NULL AND (v_acct IS NULL) <> (v_ifsc IS NULL) THEN
        SET v_err = 'Bank account number and IFSC code must be given together';
    END IF;

    IF v_err IS NULL AND v_acct IS NOT NULL AND v_acct NOT REGEXP '^[0-9]{6,20}$' THEN
        SET v_err = 'Bank account number must be 6 to 20 digits';
    END IF;

    IF v_err IS NULL AND v_ifsc IS NOT NULL AND v_ifsc NOT REGEXP '^[A-Z]{4}0[A-Z0-9]{6}$' THEN
        SET v_err = 'Invalid IFSC code';
    END IF;

    
    IF v_err IS NULL AND v_nominee IS NULL
       AND (v_nominee_rel IS NOT NULL OR p_nominee_dob IS NOT NULL OR v_nominee_mobile IS NOT NULL) THEN
        SET v_err = 'Nominee name is required when nominee details are given';
    END IF;

    IF v_err IS NULL AND v_nominee IS NOT NULL AND v_nominee_rel IS NULL THEN
        SET v_err = 'Nominee relation is required';
    END IF;

    IF v_err IS NULL AND v_nominee_rel IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_appl_options
        WHERE Opt_Grp_Id = 35 AND Opt_Code = v_nominee_rel AND Is_Active = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Invalid nominee relation';
        ELSEIF v_nominee_rel = 9 THEN
            SET v_err = 'Nominee relation cannot be Self';
        END IF;
    END IF;

    IF v_err IS NULL AND p_nominee_dob IS NOT NULL AND p_nominee_dob > CURDATE() THEN
        SET v_err = 'Nominee date of birth cannot be in the future';
    END IF;

    IF v_err IS NULL AND v_nominee_mobile IS NOT NULL AND v_nominee_mobile NOT REGEXP '^[6-9][0-9]{9}$' THEN
        SET v_err = 'Nominee mobile number must be a valid 10-digit number';
    END IF;

    
    IF v_err IS NULL AND p_fo_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_staff
        WHERE Staff_Id = p_fo_id
          AND Branch_Id = p_branch_id
          AND (IFNULL(Status, 0) = 1 OR (v_action = 'EDIT' AND Staff_Id = v_cur_fo));
        IF v_cnt = 0 THEN
            SET v_err = 'Active field officer not found for this branch';
        END IF;
    END IF;

    IF v_err IS NULL AND p_adm_fees IS NOT NULL AND (p_adm_fees < 0 OR p_adm_fees > 9999.99) THEN
        SET v_err = 'Admission fees must be between 0 and 9999.99';
    END IF;

    
    IF v_err IS NULL AND v_ref IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_member
        WHERE UPPER(Ref_Code) = UPPER(v_ref) AND (v_action = 'ADD' OR Member_Id <> p_member_id);
        IF v_cnt > 0 THEN
            SET v_err = 'Reference code already exists';
        END IF;
    END IF;

    IF v_err IS NULL AND v_action = 'ADD' THEN
        CALL USP_CODE_SERIES_GENERATE('borrower', v_gen_code, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
            SET v_err = CONCAT('Unable to generate member code: ', IFNULL(v_gen_msg, 'check the borrower code series'));
        ELSEIF CHAR_LENGTH(v_gen_code) > 25 THEN
            SET v_err = 'Generated member code exceeds 25 characters. Check borrower code series';
        ELSE
            SET v_member_code = v_gen_code;
            SELECT COUNT(*) INTO v_cnt FROM mst_member WHERE UPPER(Member_Code) = UPPER(v_member_code);
            IF v_cnt > 0 THEN
                SET v_err = 'Generated member code already exists. Check borrower code series counter';
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_member_id AS member_id, NULL AS member_code, NULL AS ref_code, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_member (
            Member_Code, Ref_Code, Member_Name, Father_Name, Mother_Name, Spouse_Name,
            Gender_Cd, Date_of_Birth, Age, Marital_Status_Cd, Religion_Cd, Caste_Cd,
            Mobile_No, Alternate_Mobile_No, Email_Id, PAN_No, Branch_Id, Center_Id,
            Joining_Date, Occupation_Details, Monthly_Income, Monthly_Expense,
            Bank_Name, Bank_Branch, Bank_Account_No, IFSC_Code,
            Nominee_Name, Nominee_Rel_Cd, Nominee_DOB, Nominee_Mobile,
            Photo_Path, Signature_Path, FO_Id, Adm_Fees, Remarks,
            Current_Status_Cd, Created_By, Created_At
        ) VALUES (
            v_member_code, v_ref, v_name,
            NULLIF(TRIM(IFNULL(p_father_name, '')), ''),
            NULLIF(TRIM(IFNULL(p_mother_name, '')), ''),
            NULLIF(TRIM(IFNULL(p_spouse_name, '')), ''),
            p_gender_cd, p_date_of_birth, v_age, p_marital_status_cd, p_religion_cd, p_caste_cd,
            v_mobile, v_alt_mobile, v_email, v_pan, p_branch_id, p_center_id,
            v_join, NULLIF(TRIM(IFNULL(p_occupation_details, '')), ''),
            IFNULL(p_monthly_income, 0), IFNULL(p_monthly_expense, 0),
            NULLIF(TRIM(IFNULL(p_bank_name, '')), ''),
            NULLIF(TRIM(IFNULL(p_bank_branch, '')), ''),
            v_acct, v_ifsc,
            v_nominee, v_nominee_rel, p_nominee_dob, v_nominee_mobile,
            NULLIF(TRIM(IFNULL(p_photo_path, '')), ''),
            NULLIF(TRIM(IFNULL(p_signature_path, '')), ''),
            p_fo_id, p_adm_fees, NULLIF(TRIM(IFNULL(p_remarks, '')), ''),
            v_status, p_user_id, NOW()
        );

        SET v_member_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_member_id AS member_id, v_member_code AS member_code,
               v_ref AS ref_code, 'Member created successfully' AS message;
    ELSE
        UPDATE mst_member
        SET Ref_Code = v_ref,
            Member_Name = v_name,
            Father_Name = NULLIF(TRIM(IFNULL(p_father_name, '')), ''),
            Mother_Name = NULLIF(TRIM(IFNULL(p_mother_name, '')), ''),
            Spouse_Name = NULLIF(TRIM(IFNULL(p_spouse_name, '')), ''),
            Gender_Cd = p_gender_cd,
            Date_of_Birth = p_date_of_birth,
            Age = v_age,
            Marital_Status_Cd = p_marital_status_cd,
            Religion_Cd = p_religion_cd,
            Caste_Cd = p_caste_cd,
            Mobile_No = v_mobile,
            Alternate_Mobile_No = v_alt_mobile,
            Email_Id = v_email,
            PAN_No = v_pan,
            Branch_Id = p_branch_id,
            Center_Id = p_center_id,
            Joining_Date = v_join,
            Occupation_Details = NULLIF(TRIM(IFNULL(p_occupation_details, '')), ''),
            Monthly_Income = IFNULL(p_monthly_income, 0),
            Monthly_Expense = IFNULL(p_monthly_expense, 0),
            Bank_Name = NULLIF(TRIM(IFNULL(p_bank_name, '')), ''),
            Bank_Branch = NULLIF(TRIM(IFNULL(p_bank_branch, '')), ''),
            Bank_Account_No = v_acct,
            IFSC_Code = v_ifsc,
            Nominee_Name = v_nominee,
            Nominee_Rel_Cd = v_nominee_rel,
            Nominee_DOB = p_nominee_dob,
            Nominee_Mobile = v_nominee_mobile,
            Photo_Path = NULLIF(TRIM(IFNULL(p_photo_path, '')), ''),
            Signature_Path = NULLIF(TRIM(IFNULL(p_signature_path, '')), ''),
            FO_Id = p_fo_id,
            Adm_Fees = p_adm_fees,
            Remarks = NULLIF(TRIM(IFNULL(p_remarks, '')), ''),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Member_Id = p_member_id;

        SELECT 'SUCCESS' AS status, p_member_id AS member_id,
               (SELECT Member_Code FROM mst_member WHERE Member_Id = p_member_id) AS member_code,
               v_ref AS ref_code, 'Member updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
