DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_GROUP_ASSIGN`(
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_member_role VARCHAR(20),
    IN p_join_date DATE,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_found INT DEFAULT 0;
    DECLARE v_role VARCHAR(20);
    DECLARE v_join DATE;
    DECLARE v_cur_group_name VARCHAR(250) DEFAULT NULL;
    DECLARE v_fo INT DEFAULT NULL;
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_group_name VARCHAR(250);

    SET v_role = CASE UPPER(TRIM(IFNULL(p_member_role, '')))
        WHEN '' THEN 'Member'
        WHEN 'MEMBER' THEN 'Member'
        WHEN 'PRESIDENT' THEN 'President'
        WHEN 'SECRETARY' THEN 'Secretary'
        WHEN 'TREASURER' THEN 'Treasurer'
        ELSE NULL
    END;
    SET v_join = IFNULL(p_join_date, CURDATE());

    SELECT COUNT(*) INTO v_found FROM mst_member WHERE Member_Id = p_member_id FOR UPDATE;

    IF v_found = 0 THEN
        SET v_err = 'Member not found';
    ELSEIF v_role IS NULL THEN
        SET v_err = 'Member role must be Member, President, Secretary or Treasurer';
    END IF;

    IF v_err IS NULL THEN
        SELECT MIN(g.Group_Name) INTO v_cur_group_name
        FROM mst_member_group mg
        JOIN mst_group g ON g.Group_Id = mg.Group_Id
        WHERE mg.Member_Id = p_member_id AND mg.Is_Active = 1;

        IF v_cur_group_name IS NOT NULL THEN
            SET v_err = CONCAT('Member already belongs to group ', v_cur_group_name, '; use reassign to move the member');
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_MEMBER_GROUP_VALIDATE_TARGET(p_member_id, p_group_id, v_role, v_join, v_err, v_fo);
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS mem_group_id, p_member_id AS member_id, p_group_id AS group_id,
               0 AS active_loan_count, v_err AS message;
    ELSE
        INSERT INTO mst_member_group (Member_Id, Group_Id, FO_Id, Join_Date, Member_Role, Is_Active, Created_By, Created_At)
        VALUES (p_member_id, p_group_id, v_fo, v_join, v_role, 1, p_user_id, NOW());

        SET v_new_id = LAST_INSERT_ID();

        IF v_role <> 'Member' THEN
            CALL USP_MEMBER_GROUP_SYNC_LEADERS(p_group_id, p_user_id);
        END IF;

        SELECT Group_Name INTO v_group_name FROM mst_group WHERE Group_Id = p_group_id;

        SELECT 'SUCCESS' AS status, v_new_id AS mem_group_id, p_member_id AS member_id, p_group_id AS group_id,
               0 AS active_loan_count, CONCAT('Member assigned to group ', v_group_name) AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_GROUP_CHECK` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_GROUP_CHECK`(
    IN p_member_id INT
)
BEGIN
    DECLARE v_found INT DEFAULT 0;
    DECLARE v_member_name VARCHAR(150);
    DECLARE v_member_status INT;
    DECLARE v_mem_group_id INT DEFAULT NULL;
    DECLARE v_group_id INT DEFAULT NULL;
    DECLARE v_group_name VARCHAR(250) DEFAULT NULL;
    DECLARE v_role VARCHAR(20) DEFAULT NULL;
    DECLARE v_join DATE DEFAULT NULL;
    DECLARE v_loans INT DEFAULT 0;

    SELECT COUNT(*), MIN(Member_Name), MIN(Current_Status_Cd)
      INTO v_found, v_member_name, v_member_status
    FROM mst_member WHERE Member_Id = p_member_id;

    SELECT mg.Mem_Group_Id, mg.Group_Id, g.Group_Name, IFNULL(NULLIF(mg.Member_Role, ''), 'Member'), mg.Join_Date
      INTO v_mem_group_id, v_group_id, v_group_name, v_role, v_join
    FROM mst_member_group mg
    JOIN mst_group g ON g.Group_Id = mg.Group_Id
    WHERE mg.Member_Id = p_member_id AND mg.Is_Active = 1
    ORDER BY mg.Mem_Group_Id DESC
    LIMIT 1;

    IF v_group_id IS NOT NULL THEN
        CALL USP_MEMBER_GROUP_LOAN_CHECK(p_member_id, v_group_id, v_loans);
    END IF;

    IF v_found = 0 THEN
        SELECT 'ERROR' AS status, p_member_id AS member_id, 'Member not found' AS message;
    ELSE
        SELECT
            'SUCCESS' AS status,
            p_member_id AS member_id,
            v_member_name AS member_name,
            v_member_status AS member_status_cd,
            v_mem_group_id AS mem_group_id,
            v_group_id AS group_id,
            v_group_name AS group_name,
            v_role AS member_role,
            v_join AS join_date,
            v_loans AS active_loan_count,
            CASE
                WHEN IFNULL(v_member_status, 0) <> 1 THEN 0
                WHEN v_group_id IS NOT NULL AND v_loans > 0 THEN 0
                ELSE 1
            END AS can_change,
            CASE
                WHEN IFNULL(v_member_status, 0) <> 1 THEN 'Only active members can be assigned to a group'
                WHEN v_group_id IS NULL THEN 'Member is not in any group and can be assigned'
                WHEN v_loans > 0 THEN CONCAT('Member has ', v_loans, ' active loan(s) under group ', v_group_name,
                                             '. Close or settle the loan(s) before changing the group.')
                ELSE CONCAT('Member is in group ', v_group_name, ' and can be moved to another group')
            END AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_GROUP_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_GROUP_EDIT`(
    IN p_mem_group_id INT,
    IN p_member_role VARCHAR(20),
    IN p_fo_id INT,
    IN p_join_date DATE,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_member_id INT DEFAULT NULL;
    DECLARE v_group_id INT DEFAULT NULL;
    DECLARE v_active INT DEFAULT NULL;
    DECLARE v_cur_role VARCHAR(20) DEFAULT NULL;
    DECLARE v_cur_fo INT DEFAULT NULL;
    DECLARE v_role VARCHAR(20);
    DECLARE v_group_name VARCHAR(250);
    DECLARE v_group_branch INT;
    DECLARE v_formation DATE;
    DECLARE v_m_joining DATE;
    DECLARE v_last_exit DATE;
    DECLARE v_holder VARCHAR(150);

    SET v_role = CASE UPPER(TRIM(IFNULL(p_member_role, '')))
        WHEN '' THEN 'Member'
        WHEN 'MEMBER' THEN 'Member'
        WHEN 'PRESIDENT' THEN 'President'
        WHEN 'SECRETARY' THEN 'Secretary'
        WHEN 'TREASURER' THEN 'Treasurer'
        ELSE NULL
    END;

    SELECT mg.Member_Id, mg.Group_Id, mg.Is_Active, IFNULL(NULLIF(mg.Member_Role, ''), 'Member'), mg.FO_Id
      INTO v_member_id, v_group_id, v_active, v_cur_role, v_cur_fo
    FROM mst_member_group mg
    WHERE mg.Mem_Group_Id = p_mem_group_id
    FOR UPDATE;

    IF v_member_id IS NULL THEN
        SET v_err = 'Group membership not found';
    ELSEIF v_active <> 1 THEN
        SET v_err = 'Only the current group membership can be edited';
    ELSEIF v_role IS NULL THEN
        SET v_err = 'Member role must be Member, President, Secretary or Treasurer';
    END IF;

    IF v_err IS NULL THEN
        SELECT Group_Name, Branch_Id, Formation_Date INTO v_group_name, v_group_branch, v_formation
        FROM mst_group WHERE Group_Id = v_group_id FOR UPDATE;

        SELECT Joining_Date INTO v_m_joining FROM mst_member WHERE Member_Id = v_member_id;

        SELECT MAX(Exit_Date) INTO v_last_exit
        FROM mst_member_group WHERE Member_Id = v_member_id AND Is_Active = 0;

        IF p_join_date IS NULL THEN
            SET v_err = 'Join date is required';
        ELSEIF p_join_date > CURDATE() THEN
            SET v_err = 'Join date cannot be in the future';
        ELSEIF v_m_joining IS NOT NULL AND p_join_date < v_m_joining THEN
            SET v_err = CONCAT('Join date cannot be before the member''s joining date (', DATE_FORMAT(v_m_joining, '%d-%m-%Y'), ')');
        ELSEIF v_formation IS NOT NULL AND p_join_date < v_formation THEN
            SET v_err = CONCAT('Join date cannot be before the group''s formation date (', DATE_FORMAT(v_formation, '%d-%m-%Y'), ')');
        ELSEIF v_last_exit IS NOT NULL AND p_join_date < v_last_exit THEN
            SET v_err = CONCAT('Join date cannot be before the member left the previous group (', DATE_FORMAT(v_last_exit, '%d-%m-%Y'), ')');
        END IF;
    END IF;

    IF v_err IS NULL AND v_role IN ('President', 'Secretary', 'Treasurer') THEN
        SELECT MIN(m.Member_Name) INTO v_holder
        FROM mst_member_group mg
        JOIN mst_member m ON m.Member_Id = mg.Member_Id
        WHERE mg.Group_Id = v_group_id AND mg.Is_Active = 1
          AND mg.Member_Role = v_role AND mg.Member_Id <> v_member_id;

        IF v_holder IS NOT NULL THEN
            SET v_err = CONCAT('Group ', v_group_name, ' already has a ', LOWER(v_role), ' (', v_holder, '); change their role first');
        END IF;
    END IF;

    IF v_err IS NULL AND p_fo_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_staff
        WHERE Staff_Id = p_fo_id
          AND Branch_Id = v_group_branch
          AND (IFNULL(Status, 0) = 1 OR Staff_Id <=> v_cur_fo);
        IF v_cnt = 0 THEN
            SET v_err = 'Active field officer not found for this branch';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_mem_group_id AS mem_group_id, v_member_id AS member_id, v_group_id AS group_id,
               0 AS active_loan_count, v_err AS message;
    ELSE
        UPDATE mst_member_group
        SET Member_Role = v_role,
            FO_Id = p_fo_id,
            Join_Date = p_join_date,
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Mem_Group_Id = p_mem_group_id;

        IF v_cur_role <> v_role THEN
            CALL USP_MEMBER_GROUP_SYNC_LEADERS(v_group_id, p_user_id);
        END IF;

        SELECT 'SUCCESS' AS status, p_mem_group_id AS mem_group_id, v_member_id AS member_id, v_group_id AS group_id,
               0 AS active_loan_count, 'Group membership updated successfully' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_GROUP_EXIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_GROUP_EXIT`(
    IN p_member_id INT,
    IN p_exit_date DATE,
    IN p_reason VARCHAR(200),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_warn VARCHAR(255) DEFAULT NULL;
    DECLARE v_found INT DEFAULT 0;
    DECLARE v_date DATE;
    DECLARE v_reason VARCHAR(200);
    DECLARE v_cur_id INT DEFAULT NULL;
    DECLARE v_cur_group INT DEFAULT NULL;
    DECLARE v_cur_join DATE DEFAULT NULL;
    DECLARE v_cur_role VARCHAR(20) DEFAULT NULL;
    DECLARE v_cur_name VARCHAR(250) DEFAULT NULL;
    DECLARE v_loans INT DEFAULT 0;
    DECLARE v_left INT DEFAULT 0;
    DECLARE v_min INT DEFAULT 0;
    DECLARE v_msg VARCHAR(400);

    SET v_date = IFNULL(p_exit_date, CURDATE());
    SET v_reason = NULLIF(TRIM(p_reason), '');

    SELECT COUNT(*) INTO v_found FROM mst_member WHERE Member_Id = p_member_id FOR UPDATE;

    IF v_found = 0 THEN
        SET v_err = 'Member not found';
    END IF;

    IF v_err IS NULL THEN
        SELECT mg.Mem_Group_Id, mg.Group_Id, mg.Join_Date, IFNULL(NULLIF(mg.Member_Role, ''), 'Member'), g.Group_Name
          INTO v_cur_id, v_cur_group, v_cur_join, v_cur_role, v_cur_name
        FROM mst_member_group mg
        JOIN mst_group g ON g.Group_Id = mg.Group_Id
        WHERE mg.Member_Id = p_member_id AND mg.Is_Active = 1
        ORDER BY mg.Mem_Group_Id DESC
        LIMIT 1
        FOR UPDATE;

        IF v_cur_id IS NULL THEN
            SET v_err = 'Member is not in any group';
        ELSEIF v_reason IS NULL THEN
            SET v_err = 'Exit reason is required';
        ELSEIF v_date > CURDATE() THEN
            SET v_err = 'Exit date cannot be in the future';
        ELSEIF v_date < v_cur_join THEN
            SET v_err = CONCAT('Exit date cannot be before the member joined group ', v_cur_name,
                               ' (', DATE_FORMAT(v_cur_join, '%d-%m-%Y'), ')');
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_MEMBER_GROUP_LOAN_CHECK(p_member_id, v_cur_group, v_loans);
        IF v_loans > 0 THEN
            SET v_warn = CONCAT('Member has ', v_loans, ' active loan(s) under group ', v_cur_name,
                                '. Close or settle the loan(s) before removing the member from the group.');
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, v_cur_id AS mem_group_id, p_member_id AS member_id, v_cur_group AS group_id,
               v_loans AS active_loan_count, v_err AS message;
    ELSEIF v_warn IS NOT NULL THEN
        SELECT 'WARNING' AS status, v_cur_id AS mem_group_id, p_member_id AS member_id, v_cur_group AS group_id,
               v_loans AS active_loan_count, v_warn AS message;
    ELSE
        UPDATE mst_member_group
        SET Is_Active = 0,
            Exit_Date = v_date,
            Exit_Reason = v_reason,
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Mem_Group_Id = v_cur_id;

        IF v_cur_role <> 'Member' THEN
            CALL USP_MEMBER_GROUP_SYNC_LEADERS(v_cur_group, p_user_id);
        END IF;

        SELECT COUNT(*) INTO v_left FROM mst_member_group WHERE Group_Id = v_cur_group AND Is_Active = 1;
        SELECT IFNULL(MAX(Value), 0) INTO v_min FROM mst_settings_global WHERE Id = 3;

        SET v_msg = CONCAT('Member removed from group ', v_cur_name);
        IF v_cur_role <> 'Member' THEN
            SET v_msg = CONCAT(v_msg, '. Group ', v_cur_name, ' no longer has a ', LOWER(v_cur_role));
        END IF;
        IF v_min > 0 AND v_left < v_min THEN
            SET v_msg = CONCAT(v_msg, '. Group ', v_cur_name, ' now has ', v_left,
                               ' member(s), below the minimum of ', v_min);
        END IF;

        SELECT 'SUCCESS' AS status, v_cur_id AS mem_group_id, p_member_id AS member_id, v_cur_group AS group_id,
               0 AS active_loan_count, v_msg AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_GROUP_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_GROUP_LIST`(
    IN p_mem_group_id INT,
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_branch_id INT,
    IN p_center_id INT,
    IN p_member_role VARCHAR(20),
    IN p_is_active INT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_member_group mg
    JOIN mst_member m ON m.Member_Id = mg.Member_Id
    JOIN mst_group g ON g.Group_Id = mg.Group_Id
    WHERE (p_mem_group_id IS NULL OR mg.Mem_Group_Id = p_mem_group_id)
      AND (p_member_id IS NULL OR mg.Member_Id = p_member_id)
      AND (p_group_id IS NULL OR mg.Group_Id = p_group_id)
      AND (p_branch_id IS NULL OR g.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR g.Center_Id = p_center_id)
      AND (p_member_role IS NULL OR p_member_role = '' OR IFNULL(NULLIF(mg.Member_Role, ''), 'Member') = p_member_role)
      AND (p_is_active IS NULL OR mg.Is_Active = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR CAST(m.Member_Code AS CHAR) = p_keyword
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR g.Group_Name LIKE CONCAT('%', p_keyword, '%')
          OR CAST(g.Group_Code AS CHAR) = p_keyword
          OR IFNULL(g.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        mg.Mem_Group_Id,
        mg.Member_Id,
        m.Member_Code,
        m.Ref_Code AS Member_Ref_Code,
        m.Member_Name,
        m.Gender_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 28 AND o.Opt_Code = m.Gender_Cd) AS Gender_Desc,
        m.Mobile_No,
        m.Current_Status_Cd AS Member_Status_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 27 AND o.Opt_Code = m.Current_Status_Cd) AS Member_Status_Desc,
        mg.Group_Id,
        g.Group_Code,
        g.Ref_Code AS Group_Ref_Code,
        g.Group_Name,
        g.Group_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 24 AND o.Opt_Code = g.Group_Type_Cd) AS Group_Type_Desc,
        g.Current_Status_Cd AS Group_Status_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 27 AND o.Opt_Code = g.Current_Status_Cd) AS Group_Status_Desc,
        g.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        g.Center_Id,
        c.Center_Name,
        mg.FO_Id,
        fo.Employee_Code AS FO_Code,
        fo.Full_Name AS FO_Name,
        IFNULL(NULLIF(mg.Member_Role, ''), 'Member') AS Member_Role,
        mg.Join_Date,
        mg.Exit_Date,
        mg.Exit_Reason,
        mg.Is_Active,
        mg.Created_By,
        cu.User_Name AS Created_By_Name,
        mg.Created_At,
        mg.Updated_By,
        mg.Updated_At
    FROM mst_member_group mg
    JOIN mst_member m ON m.Member_Id = mg.Member_Id
    JOIN mst_group g ON g.Group_Id = mg.Group_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = g.Branch_Id
    LEFT JOIN mst_center c ON c.Center_Id = g.Center_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = mg.FO_Id
    LEFT JOIN priomicro_core.mst_org_user cu ON cu.User_Id = mg.Created_By
    WHERE (p_mem_group_id IS NULL OR mg.Mem_Group_Id = p_mem_group_id)
      AND (p_member_id IS NULL OR mg.Member_Id = p_member_id)
      AND (p_group_id IS NULL OR mg.Group_Id = p_group_id)
      AND (p_branch_id IS NULL OR g.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR g.Center_Id = p_center_id)
      AND (p_member_role IS NULL OR p_member_role = '' OR IFNULL(NULLIF(mg.Member_Role, ''), 'Member') = p_member_role)
      AND (p_is_active IS NULL OR mg.Is_Active = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR CAST(m.Member_Code AS CHAR) = p_keyword
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR g.Group_Name LIKE CONCAT('%', p_keyword, '%')
          OR CAST(g.Group_Code AS CHAR) = p_keyword
          OR IFNULL(g.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
      )
    ORDER BY
        mg.Is_Active DESC,
        mg.Join_Date DESC,
        g.Group_Name,
        FIELD(IFNULL(NULLIF(mg.Member_Role, ''), 'Member'), 'President', 'Secretary', 'Treasurer', 'Member'),
        m.Member_Name,
        mg.Mem_Group_Id DESC
    LIMIT v_offset, v_per_page;
END ;;
DELIMITER ;
