DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_GROUP_REASSIGN`(
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_member_role VARCHAR(20),
    IN p_transfer_date DATE,
    IN p_reason VARCHAR(200),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_warn VARCHAR(255) DEFAULT NULL;
    DECLARE v_found INT DEFAULT 0;
    DECLARE v_role VARCHAR(20);
    DECLARE v_date DATE;
    DECLARE v_cur_id INT DEFAULT NULL;
    DECLARE v_cur_group INT DEFAULT NULL;
    DECLARE v_cur_join DATE DEFAULT NULL;
    DECLARE v_cur_role VARCHAR(20) DEFAULT NULL;
    DECLARE v_cur_name VARCHAR(250) DEFAULT NULL;
    DECLARE v_new_name VARCHAR(250) DEFAULT NULL;
    DECLARE v_loans INT DEFAULT 0;
    DECLARE v_fo INT DEFAULT NULL;
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_left INT DEFAULT 0;
    DECLARE v_min INT DEFAULT 0;
    DECLARE v_msg VARCHAR(400);

    SET v_role = CASE UPPER(TRIM(IFNULL(p_member_role, '')))
        WHEN '' THEN 'Member'
        WHEN 'MEMBER' THEN 'Member'
        WHEN 'PRESIDENT' THEN 'President'
        WHEN 'SECRETARY' THEN 'Secretary'
        WHEN 'TREASURER' THEN 'Treasurer'
        ELSE NULL
    END;
    SET v_date = IFNULL(p_transfer_date, CURDATE());

    SELECT COUNT(*) INTO v_found FROM mst_member WHERE Member_Id = p_member_id FOR UPDATE;

    IF v_found = 0 THEN
        SET v_err = 'Member not found';
    ELSEIF v_role IS NULL THEN
        SET v_err = 'Member role must be Member, President, Secretary or Treasurer';
    END IF;

    IF v_err IS NULL THEN
        SELECT mg.Mem_Group_Id, mg.Group_Id, mg.Join_Date, IFNULL(NULLIF(mg.Member_Role, ''), 'Member'), g.Group_Name
          INTO v_cur_id, v_cur_group, v_cur_join, v_cur_role, v_cur_name
        FROM mst_member_group mg
        JOIN mst_group g ON g.Group_Id = mg.Group_Id
        WHERE mg.Member_Id = p_member_id AND mg.Is_Active = 1
        ORDER BY mg.Mem_Group_Id DESC
        LIMIT 1
        FOR UPDATE;

        IF v_cur_id IS NULL THEN
            SET v_err = 'Member is not in any group; use assign instead';
        ELSEIF v_cur_group = p_group_id THEN
            SET v_err = CONCAT('Member is already in group ', v_cur_name);
        ELSEIF v_date > CURDATE() THEN
            SET v_err = 'Transfer date cannot be in the future';
        ELSEIF v_date < v_cur_join THEN
            SET v_err = CONCAT('Transfer date cannot be before the member joined group ', v_cur_name,
                               ' (', DATE_FORMAT(v_cur_join, '%d-%m-%Y'), ')');
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_MEMBER_GROUP_LOAN_CHECK(p_member_id, v_cur_group, v_loans);
        IF v_loans > 0 THEN
            SET v_warn = CONCAT('Member has ', v_loans, ' active loan(s) under group ', v_cur_name,
                                '. Close or settle the loan(s) before changing the group.');
        END IF;
    END IF;

    IF v_err IS NULL AND v_warn IS NULL THEN
        CALL USP_MEMBER_GROUP_VALIDATE_TARGET(p_member_id, p_group_id, v_role, v_date, v_err, v_fo);
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, v_cur_id AS mem_group_id, p_member_id AS member_id, p_group_id AS group_id,
               v_loans AS active_loan_count, v_err AS message;
    ELSEIF v_warn IS NOT NULL THEN
        SELECT 'WARNING' AS status, v_cur_id AS mem_group_id, p_member_id AS member_id, v_cur_group AS group_id,
               v_loans AS active_loan_count, v_warn AS message;
    ELSE
        SELECT Group_Name INTO v_new_name FROM mst_group WHERE Group_Id = p_group_id;

        UPDATE mst_member_group
        SET Is_Active = 0,
            Exit_Date = v_date,
            Exit_Reason = IFNULL(NULLIF(TRIM(p_reason), ''), CONCAT('Transferred to group ', v_new_name)),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Mem_Group_Id = v_cur_id;

        INSERT INTO mst_member_group (Member_Id, Group_Id, FO_Id, Join_Date, Member_Role, Is_Active, Created_By, Created_At)
        VALUES (p_member_id, p_group_id, v_fo, v_date, v_role, 1, p_user_id, NOW());

        SET v_new_id = LAST_INSERT_ID();

        IF v_cur_role <> 'Member' THEN
            CALL USP_MEMBER_GROUP_SYNC_LEADERS(v_cur_group, p_user_id);
        END IF;
        IF v_role <> 'Member' THEN
            CALL USP_MEMBER_GROUP_SYNC_LEADERS(p_group_id, p_user_id);
        END IF;

        SELECT COUNT(*) INTO v_left FROM mst_member_group WHERE Group_Id = v_cur_group AND Is_Active = 1;
        SELECT IFNULL(MAX(Value), 0) INTO v_min FROM mst_settings_global WHERE Id = 3;

        SET v_msg = CONCAT('Member moved from group ', v_cur_name, ' to group ', v_new_name);
        IF v_cur_role <> 'Member' THEN
            SET v_msg = CONCAT(v_msg, '. Group ', v_cur_name, ' no longer has a ', LOWER(v_cur_role));
        END IF;
        IF v_min > 0 AND v_left < v_min THEN
            SET v_msg = CONCAT(v_msg, '. Group ', v_cur_name, ' now has ', v_left,
                               ' member(s), below the minimum of ', v_min);
        END IF;

        SELECT 'SUCCESS' AS status, v_new_id AS mem_group_id, p_member_id AS member_id, p_group_id AS group_id,
               0 AS active_loan_count, v_msg AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_GROUP_SYNC_LEADERS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_GROUP_SYNC_LEADERS`(
    IN p_group_id INT,
    IN p_user_id INT
)
BEGIN
    UPDATE mst_group g
    SET g.President_Member_Id = (
            SELECT MIN(mg.Member_Id) FROM mst_member_group mg
            WHERE mg.Group_Id = g.Group_Id AND mg.Is_Active = 1 AND mg.Member_Role = 'President'),
        g.Secretary_Member_Id = (
            SELECT MIN(mg.Member_Id) FROM mst_member_group mg
            WHERE mg.Group_Id = g.Group_Id AND mg.Is_Active = 1 AND mg.Member_Role = 'Secretary'),
        g.Treasurer_Member_Id = (
            SELECT MIN(mg.Member_Id) FROM mst_member_group mg
            WHERE mg.Group_Id = g.Group_Id AND mg.Is_Active = 1 AND mg.Member_Role = 'Treasurer'),
        g.Updated_By = p_user_id,
        g.Updated_At = NOW()
    WHERE g.Group_Id = p_group_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_GROUP_VALIDATE_TARGET` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_GROUP_VALIDATE_TARGET`(
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_role VARCHAR(20),
    IN p_join_date DATE,
    OUT p_err VARCHAR(255),
    OUT p_fo_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_g_found INT DEFAULT 0;
    DECLARE v_g_name VARCHAR(250);
    DECLARE v_g_status INT;
    DECLARE v_g_branch INT;
    DECLARE v_g_center INT;
    DECLARE v_g_gender INT;
    DECLARE v_g_member_no INT;
    DECLARE v_g_formation DATE;
    DECLARE v_m_status INT;
    DECLARE v_m_branch INT;
    DECLARE v_m_center INT;
    DECLARE v_m_gender INT;
    DECLARE v_m_joining DATE;
    DECLARE v_last_exit DATE;
    DECLARE v_max INT DEFAULT 0;
    DECLARE v_cap INT DEFAULT NULL;
    DECLARE v_holder VARCHAR(150);

    SET p_err = NULL;
    SET p_fo_id = NULL;

    SELECT COUNT(*), MIN(Group_Name), MIN(Current_Status_Cd), MIN(Branch_Id), MIN(Center_Id), MIN(Group_Gender_Cd),
           MIN(Member_No), MIN(Formation_Date), MIN(FO_Id)
      INTO v_g_found, v_g_name, v_g_status, v_g_branch, v_g_center, v_g_gender,
           v_g_member_no, v_g_formation, p_fo_id
    FROM mst_group
    WHERE Group_Id = p_group_id
    FOR UPDATE;

    SELECT Current_Status_Cd, Branch_Id, Center_Id, Gender_Cd, Joining_Date
      INTO v_m_status, v_m_branch, v_m_center, v_m_gender, v_m_joining
    FROM mst_member
    WHERE Member_Id = p_member_id;

    SELECT MAX(Exit_Date) INTO v_last_exit
    FROM mst_member_group
    WHERE Member_Id = p_member_id AND Is_Active = 0;

    IF v_g_found = 0 THEN
        SET p_err = 'Group not found';
    ELSEIF IFNULL(v_g_status, 0) <> 1 THEN
        SET p_err = CONCAT('Group ', v_g_name, ' is not active');
    ELSEIF IFNULL(v_m_status, 0) <> 1 THEN
        SET p_err = 'Only active members can be assigned to a group';
    ELSEIF NOT (v_m_branch <=> v_g_branch) THEN
        SET p_err = 'Member and group must belong to the same branch';
    ELSEIF v_g_center IS NOT NULL AND v_m_center IS NOT NULL AND v_g_center <> v_m_center THEN
        SET p_err = 'Member belongs to a different center than the group';
    ELSEIF v_g_gender = 2 AND IFNULL(v_m_gender, 0) <> 2 THEN
        SET p_err = CONCAT('Group ', v_g_name, ' is a women''s group; only female members can join');
    ELSEIF v_g_gender = 3 AND IFNULL(v_m_gender, 0) <> 1 THEN
        SET p_err = CONCAT('Group ', v_g_name, ' is a men''s group; only male members can join');
    ELSEIF p_join_date > CURDATE() THEN
        SET p_err = 'Join date cannot be in the future';
    ELSEIF v_m_joining IS NOT NULL AND p_join_date < v_m_joining THEN
        SET p_err = CONCAT('Join date cannot be before the member''s joining date (', DATE_FORMAT(v_m_joining, '%d-%m-%Y'), ')');
    ELSEIF v_g_formation IS NOT NULL AND p_join_date < v_g_formation THEN
        SET p_err = CONCAT('Join date cannot be before the group''s formation date (', DATE_FORMAT(v_g_formation, '%d-%m-%Y'), ')');
    ELSEIF v_last_exit IS NOT NULL AND p_join_date < v_last_exit THEN
        SET p_err = CONCAT('Join date cannot be before the member left the previous group (', DATE_FORMAT(v_last_exit, '%d-%m-%Y'), ')');
    END IF;

    IF p_err IS NULL THEN
        SELECT IFNULL(MAX(Value), 0) INTO v_max FROM mst_settings_global WHERE Id = 4;
        SET v_cap = CASE
            WHEN v_max > 0 AND v_g_member_no IS NOT NULL THEN LEAST(v_max, v_g_member_no)
            WHEN v_max > 0 THEN v_max
            ELSE v_g_member_no
        END;

        SELECT COUNT(*) INTO v_cnt
        FROM mst_member_group
        WHERE Group_Id = p_group_id AND Is_Active = 1 AND Member_Id <> p_member_id;

        IF v_cap IS NOT NULL AND v_cnt >= v_cap THEN
            SET p_err = CONCAT('Group ', v_g_name, ' is full (', v_cnt, ' of ', v_cap, ' members)');
        END IF;
    END IF;

    IF p_err IS NULL AND p_role IN ('President', 'Secretary', 'Treasurer') THEN
        SELECT MIN(m.Member_Name) INTO v_holder
        FROM mst_member_group mg
        JOIN mst_member m ON m.Member_Id = mg.Member_Id
        WHERE mg.Group_Id = p_group_id AND mg.Is_Active = 1
          AND mg.Member_Role = p_role AND mg.Member_Id <> p_member_id;

        IF v_holder IS NOT NULL THEN
            SET p_err = CONCAT('Group ', v_g_name, ' already has a ', LOWER(p_role), ' (', v_holder, '); change their role first');
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_KYC_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_KYC_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_member_kyc_id INT,
    IN p_member_id INT,
    IN p_doc_type_cd INT,
    IN p_kyc_no VARCHAR(50),
    IN p_issue_date DATE,
    IN p_expiry_date DATE,
    IN p_photo_path VARCHAR(300),
    IN p_back_photo_path VARCHAR(300),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_member_id INT DEFAULT NULL;
    DECLARE v_member_status INT DEFAULT NULL;
    DECLARE v_dob DATE DEFAULT NULL;
    DECLARE v_cur_verified INT DEFAULT NULL;
    DECLARE v_cur_active INT DEFAULT NULL;
    DECLARE v_no VARCHAR(50) DEFAULT NULL;
    DECLARE v_new_id INT DEFAULT NULL;
    DECLARE v_msg VARCHAR(255) DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT k.Member_Id, IFNULL(k.KYC_Verified, 0), IFNULL(k.Is_Active, 1) + 0
          INTO v_member_id, v_cur_verified, v_cur_active
        FROM mst_member_kyc k
        WHERE k.Member_Kyc_Id = p_member_kyc_id
        FOR UPDATE;

        IF v_member_id IS NULL THEN
            SET v_err = 'KYC document not found';
        ELSEIF v_cur_active = 0 THEN
            SET v_err = 'Inactive KYC document cannot be edited; activate it first';
        ELSEIF v_cur_verified = 1 THEN
            SET v_err = 'Verified KYC document cannot be edited; reopen it (set to Pending) first';
        END IF;
    ELSEIF v_err IS NULL THEN
        SET v_member_id = p_member_id;
    END IF;

    IF v_err IS NULL THEN
        SELECT m.Current_Status_Cd, m.Date_of_Birth INTO v_member_status, v_dob
        FROM mst_member m
        WHERE m.Member_Id = v_member_id
        FOR UPDATE;

        SELECT COUNT(*) INTO v_cnt FROM mst_member WHERE Member_Id = v_member_id;
        IF v_member_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Member not found';
        ELSEIF IFNULL(v_member_status, 0) IN (4, 5) THEN
            SET v_err = 'KYC cannot be changed for a closed or deceased member';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 33 AND Opt_Group = 'Document Type' AND Opt_Code = p_doc_type_cd;
        IF p_doc_type_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid document type';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SET v_no = UPPER(REPLACE(TRIM(IFNULL(p_kyc_no, '')), ' ', ''));
        IF p_doc_type_cd IN (1, 2, 4, 5) THEN
            SET v_no = REPLACE(v_no, '-', '');
        END IF;

        IF v_no = '' THEN
            SET v_err = 'Document number is required';
        ELSEIF CHAR_LENGTH(v_no) > 25 THEN
            SET v_err = 'Document number cannot exceed 25 characters';
        ELSEIF p_doc_type_cd = 1 AND v_no NOT REGEXP '^[2-9][0-9]{11}$' THEN
            SET v_err = 'Aadhaar number must be 12 digits and cannot start with 0 or 1';
        ELSEIF p_doc_type_cd = 2 AND v_no NOT REGEXP '^[A-Z]{3}[0-9]{7}$' THEN
            SET v_err = 'Voter ID must be 3 letters followed by 7 digits (e.g. ABC1234567)';
        ELSEIF p_doc_type_cd = 3 AND v_no NOT REGEXP '^[A-Z0-9/-]{4,20}$' THEN
            SET v_err = 'Ration card number must be 4 to 20 letters/digits';
        ELSEIF p_doc_type_cd = 4 AND v_no NOT REGEXP '^[A-Z][0-9]{7}$' THEN
            SET v_err = 'Passport number must be 1 letter followed by 7 digits (e.g. A1234567)';
        ELSEIF p_doc_type_cd = 5 AND v_no NOT REGEXP '^[A-Z]{2}[0-9]{2}[0-9A-Z]{9,12}$' THEN
            SET v_err = 'Driving licence number must start with the state code and RTO code (e.g. WB0120190012345)';
        ELSEIF p_doc_type_cd = 6 AND v_no NOT REGEXP '^[A-Z0-9/-]{3,25}$' THEN
            SET v_err = 'Document number must be 3 to 25 letters/digits';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        IF p_issue_date IS NOT NULL AND p_issue_date > CURDATE() THEN
            SET v_err = 'Issue date cannot be in the future';
        ELSEIF p_issue_date IS NOT NULL AND v_dob IS NOT NULL AND p_issue_date < v_dob THEN
            SET v_err = 'Issue date cannot be before the member''s date of birth';
        ELSEIF p_doc_type_cd IN (4, 5) AND p_expiry_date IS NULL THEN
            SET v_err = 'Expiry date is required for passport and driving licence';
        ELSEIF p_expiry_date IS NOT NULL AND p_issue_date IS NOT NULL AND p_expiry_date <= p_issue_date THEN
            SET v_err = 'Expiry date must be after the issue date';
        ELSEIF p_expiry_date IS NOT NULL AND p_expiry_date < CURDATE() THEN
            SET v_err = 'Document has expired';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        CALL USP_MEMBER_KYC_DUP_CHECK(IF(v_action = 'EDIT', p_member_kyc_id, NULL), v_member_id, p_doc_type_cd, v_no, v_err);
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_member_kyc_id AS member_kyc_id, v_member_id AS member_id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_member_kyc (
            Member_Id, Doc_Type_Cd, KYC_No, Issue_Date, Expiry_Date,
            KYC_Verified, Photo_Path, Back_Photo_Path, Is_Active, Created_By, Created_At
        ) VALUES (
            v_member_id, p_doc_type_cd, v_no, p_issue_date, p_expiry_date,
            0, NULLIF(TRIM(p_photo_path), ''), NULLIF(TRIM(p_back_photo_path), ''), b'1', p_user_id, NOW()
        );

        SET v_new_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_new_id AS member_kyc_id, v_member_id AS member_id,
               'KYC document added successfully' AS message;
    ELSE
        SET v_msg = IF(v_cur_verified = 2,
                       'KYC document updated and sent for re-verification',
                       'KYC document updated successfully');

        UPDATE mst_member_kyc
        SET Doc_Type_Cd = p_doc_type_cd,
            KYC_No = v_no,
            Issue_Date = p_issue_date,
            Expiry_Date = p_expiry_date,
            Photo_Path = NULLIF(TRIM(p_photo_path), ''),
            Back_Photo_Path = NULLIF(TRIM(p_back_photo_path), ''),
            KYC_Verified = 0,
            Verify_Remarks = IF(v_cur_verified = 2, NULL, Verify_Remarks),
            Verified_By = IF(v_cur_verified = 2, NULL, Verified_By),
            Verified_At = IF(v_cur_verified = 2, NULL, Verified_At),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Member_Kyc_Id = p_member_kyc_id;

        SELECT 'SUCCESS' AS status, p_member_kyc_id AS member_kyc_id, v_member_id AS member_id, v_msg AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_KYC_DUP_CHECK` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
