/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_KYC_DUP_CHECK`(
    IN p_member_kyc_id INT,
    IN p_member_id INT,
    IN p_doc_type_cd INT,
    IN p_kyc_no VARCHAR(25),
    OUT p_err VARCHAR(255)
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_doc_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_other_ref VARCHAR(50) DEFAULT NULL;

    SET p_err = NULL;

    SELECT MIN(o.Opt_Description) INTO v_doc_desc
    FROM mst_appl_options o
    WHERE o.Opt_Grp_Id = 33 AND o.Opt_Group = 'Document Type' AND o.Opt_Code = p_doc_type_cd;

    IF p_doc_type_cd <> 6 THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_member_kyc k
        WHERE k.Member_Id = p_member_id
          AND k.Doc_Type_Cd = p_doc_type_cd
          AND IFNULL(k.Is_Active, 1) = 1
          AND IFNULL(k.KYC_Verified, 0) <> 2
          AND (p_member_kyc_id IS NULL OR k.Member_Kyc_Id <> p_member_kyc_id);

        IF v_cnt > 0 THEN
            SET p_err = CONCAT('Member already has an active ', IFNULL(v_doc_desc, 'document of this type'),
                               '; edit or deactivate it first');
        END IF;
    ELSE
        SELECT COUNT(*) INTO v_cnt
        FROM mst_member_kyc k
        WHERE k.Member_Id = p_member_id
          AND k.Doc_Type_Cd = p_doc_type_cd
          AND k.KYC_No = p_kyc_no
          AND IFNULL(k.Is_Active, 1) = 1
          AND IFNULL(k.KYC_Verified, 0) <> 2
          AND (p_member_kyc_id IS NULL OR k.Member_Kyc_Id <> p_member_kyc_id);

        IF v_cnt > 0 THEN
            SET p_err = 'Member already has this document number';
        END IF;
    END IF;

    IF p_err IS NULL THEN
        SELECT MIN(IFNULL(m.Ref_Code, CAST(m.Member_Code AS CHAR))) INTO v_other_ref
        FROM mst_member_kyc k
        JOIN mst_member m ON m.Member_Id = k.Member_Id
        WHERE k.Doc_Type_Cd = p_doc_type_cd
          AND k.KYC_No = p_kyc_no
          AND k.Member_Id <> p_member_id
          AND IFNULL(k.Is_Active, 1) = 1
          AND IFNULL(k.KYC_Verified, 0) <> 2;

        IF v_other_ref IS NOT NULL THEN
            SET p_err = CONCAT('This ', IFNULL(v_doc_desc, 'document'), ' number is already registered for member ', v_other_ref);
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_KYC_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_KYC_LIST`(
    IN p_member_kyc_id INT,
    IN p_member_id INT,
    IN p_branch_id INT,
    IN p_doc_type_cd INT,
    IN p_verify_status INT,
    IN p_is_active INT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;
    DECLARE v_kw_no VARCHAR(150) DEFAULT NULL;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;
    SET v_kw_no = UPPER(REPLACE(REPLACE(TRIM(IFNULL(p_keyword, '')), ' ', ''), '-', ''));

    SELECT COUNT(*) INTO v_total
    FROM mst_member_kyc k
    JOIN mst_member m ON m.Member_Id = k.Member_Id
    WHERE (p_member_kyc_id IS NULL OR k.Member_Kyc_Id = p_member_kyc_id)
      AND (p_member_id IS NULL OR k.Member_Id = p_member_id)
      AND (p_branch_id IS NULL OR m.Branch_Id = p_branch_id)
      AND (p_doc_type_cd IS NULL OR k.Doc_Type_Cd = p_doc_type_cd)
      AND (p_verify_status IS NULL OR IFNULL(k.KYC_Verified, 0) = p_verify_status)
      AND (p_is_active IS NULL OR IFNULL(k.Is_Active, 1) = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR CAST(m.Member_Code AS CHAR) = p_keyword
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR k.KYC_No LIKE CONCAT('%', v_kw_no, '%')
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        k.Member_Kyc_Id,
        k.Member_Id,
        m.Member_Code,
        m.Ref_Code,
        m.Member_Name,
        m.Mobile_No,
        m.Current_Status_Cd AS Member_Status_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 27 AND o.Opt_Code = m.Current_Status_Cd) AS Member_Status_Desc,
        m.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        k.Doc_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o
          WHERE o.Opt_Grp_Id = 33 AND o.Opt_Group = 'Document Type' AND o.Opt_Code = k.Doc_Type_Cd) AS Doc_Type_Desc,
        k.KYC_No,
        k.Issue_Date,
        k.Expiry_Date,
        IF(k.Expiry_Date IS NOT NULL AND k.Expiry_Date < CURDATE(), 1, 0) AS Is_Expired,
        IFNULL(k.KYC_Verified, 0) AS Verify_Status,
        CASE IFNULL(k.KYC_Verified, 0) WHEN 1 THEN 'Verified' WHEN 2 THEN 'Rejected' ELSE 'Pending' END AS Verify_Status_Desc,
        k.Verify_Remarks,
        k.Verified_By,
        vu.User_Name AS Verified_By_Name,
        k.Verified_At,
        k.Photo_Path,
        k.Back_Photo_Path,
        IFNULL(k.Is_Active, 1) + 0 AS Is_Active,
        k.Created_By,
        cu.User_Name AS Created_By_Name,
        k.Created_At,
        k.Updated_By,
        k.Updated_At
    FROM mst_member_kyc k
    JOIN mst_member m ON m.Member_Id = k.Member_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = m.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user vu ON vu.User_Id = k.Verified_By
    LEFT JOIN priomicro_core.mst_org_user cu ON cu.User_Id = k.Created_By
    WHERE (p_member_kyc_id IS NULL OR k.Member_Kyc_Id = p_member_kyc_id)
      AND (p_member_id IS NULL OR k.Member_Id = p_member_id)
      AND (p_branch_id IS NULL OR m.Branch_Id = p_branch_id)
      AND (p_doc_type_cd IS NULL OR k.Doc_Type_Cd = p_doc_type_cd)
      AND (p_verify_status IS NULL OR IFNULL(k.KYC_Verified, 0) = p_verify_status)
      AND (p_is_active IS NULL OR IFNULL(k.Is_Active, 1) = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR CAST(m.Member_Code AS CHAR) = p_keyword
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR k.KYC_No LIKE CONCAT('%', v_kw_no, '%')
      )
    ORDER BY k.Member_Kyc_Id DESC
    LIMIT v_offset, v_per_page;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_KYC_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_KYC_STATUS`(
    IN p_member_kyc_id INT,
    IN p_is_active INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_member_id INT DEFAULT NULL;
    DECLARE v_member_status INT DEFAULT NULL;
    DECLARE v_doc_type INT DEFAULT NULL;
    DECLARE v_no VARCHAR(25) DEFAULT NULL;
    DECLARE v_verified INT DEFAULT NULL;
    DECLARE v_current INT DEFAULT NULL;

    SELECT k.Member_Id, k.Doc_Type_Cd, k.KYC_No, IFNULL(k.KYC_Verified, 0), IFNULL(k.Is_Active, 1) + 0
      INTO v_member_id, v_doc_type, v_no, v_verified, v_current
    FROM mst_member_kyc k
    WHERE k.Member_Kyc_Id = p_member_kyc_id
    FOR UPDATE;

    IF v_member_id IS NULL THEN
        SET v_err = 'KYC document not found';
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SET v_err = 'Status must be 0 (Inactive) or 1 (Active)';
    END IF;

    IF v_err IS NULL AND v_current <> p_is_active THEN
        SELECT Current_Status_Cd INTO v_member_status FROM mst_member WHERE Member_Id = v_member_id;

        IF IFNULL(v_member_status, 0) IN (4, 5) THEN
            SET v_err = 'KYC cannot be changed for a closed or deceased member';
        ELSEIF p_is_active = 1 AND v_verified <> 2 THEN
            CALL USP_MEMBER_KYC_DUP_CHECK(p_member_kyc_id, v_member_id, v_doc_type, v_no, v_err);
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_member_kyc_id AS member_kyc_id, v_current AS is_active, v_err AS message;
    ELSEIF v_current = p_is_active THEN
        SELECT 'SUCCESS' AS status, p_member_kyc_id AS member_kyc_id, v_current AS is_active,
               IF(p_is_active = 1, 'KYC document is already active', 'KYC document is already inactive') AS message;
    ELSE
        UPDATE mst_member_kyc
        SET Is_Active = IF(p_is_active = 1, b'1', b'0'),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Member_Kyc_Id = p_member_kyc_id;

        SELECT 'SUCCESS' AS status, p_member_kyc_id AS member_kyc_id, p_is_active AS is_active,
               IF(p_is_active = 1, 'KYC document activated', 'KYC document deactivated') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_KYC_VERIFY` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_KYC_VERIFY`(
    IN p_member_kyc_id INT,
    IN p_verify_status INT,
    IN p_remarks VARCHAR(200),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_member_id INT DEFAULT NULL;
    DECLARE v_member_status INT DEFAULT NULL;
    DECLARE v_doc_type INT DEFAULT NULL;
    DECLARE v_no VARCHAR(25) DEFAULT NULL;
    DECLARE v_expiry DATE DEFAULT NULL;
    DECLARE v_current INT DEFAULT NULL;
    DECLARE v_active INT DEFAULT NULL;
    DECLARE v_remarks VARCHAR(200) DEFAULT NULL;
    DECLARE v_desc VARCHAR(20);

    SET v_remarks = NULLIF(TRIM(p_remarks), '');
    SET v_desc = CASE p_verify_status WHEN 1 THEN 'Verified' WHEN 2 THEN 'Rejected' ELSE 'Pending' END;

    SELECT k.Member_Id, k.Doc_Type_Cd, k.KYC_No, k.Expiry_Date, IFNULL(k.KYC_Verified, 0), IFNULL(k.Is_Active, 1) + 0
      INTO v_member_id, v_doc_type, v_no, v_expiry, v_current, v_active
    FROM mst_member_kyc k
    WHERE k.Member_Kyc_Id = p_member_kyc_id
    FOR UPDATE;

    IF v_member_id IS NULL THEN
        SET v_err = 'KYC document not found';
    ELSEIF p_verify_status IS NULL OR p_verify_status NOT IN (0, 1, 2) THEN
        SET v_err = 'Verify status must be 0 (Pending), 1 (Verified) or 2 (Rejected)';
    END IF;

    IF v_err IS NULL AND v_current <> p_verify_status THEN
        SELECT Current_Status_Cd INTO v_member_status FROM mst_member WHERE Member_Id = v_member_id;

        IF v_active = 0 THEN
            SET v_err = 'Inactive KYC document cannot be verified or rejected';
        ELSEIF IFNULL(v_member_status, 0) IN (4, 5) THEN
            SET v_err = 'KYC cannot be changed for a closed or deceased member';
        ELSEIF p_verify_status = 2 AND v_remarks IS NULL THEN
            SET v_err = 'Rejection reason is required';
        ELSEIF p_verify_status = 0 AND v_remarks IS NULL THEN
            SET v_err = 'Reason is required to reopen a KYC document';
        ELSEIF p_verify_status = 1 AND v_current = 2 THEN
            SET v_err = 'Rejected KYC document must be corrected or reopened (set to Pending) before verifying';
        ELSEIF p_verify_status = 1 AND v_expiry IS NOT NULL AND v_expiry < CURDATE() THEN
            SET v_err = 'Expired KYC document cannot be verified';
        ELSEIF v_current = 2 THEN
            CALL USP_MEMBER_KYC_DUP_CHECK(p_member_kyc_id, v_member_id, v_doc_type, v_no, v_err);
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_member_kyc_id AS member_kyc_id, v_current AS verify_status, v_err AS message;
    ELSEIF v_current = p_verify_status THEN
        SELECT 'SUCCESS' AS status, p_member_kyc_id AS member_kyc_id, v_current AS verify_status,
               CONCAT('KYC document is already ', LOWER(v_desc)) AS message;
    ELSE
        UPDATE mst_member_kyc
        SET KYC_Verified = p_verify_status,
            Verify_Remarks = v_remarks,
            Verified_By = IF(p_verify_status = 0, NULL, p_user_id),
            Verified_At = IF(p_verify_status = 0, NULL, NOW()),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Member_Kyc_Id = p_member_kyc_id;

        SELECT 'SUCCESS' AS status, p_member_kyc_id AS member_kyc_id, p_verify_status AS verify_status,
               CASE p_verify_status
                   WHEN 1 THEN 'KYC document verified'
                   WHEN 2 THEN 'KYC document rejected'
                   ELSE 'KYC document reopened for verification'
               END AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_LIST`(
    IN p_member_id INT,
    IN p_branch_id INT,
    IN p_center_id INT,
    IN p_group_id INT,
    IN p_fo_id INT,
    IN p_gender_cd INT,
    IN p_status_cd INT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_member m
    WHERE (p_member_id IS NULL OR m.Member_Id = p_member_id)
      AND (p_branch_id IS NULL OR m.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR m.Center_Id = p_center_id)
      AND (p_fo_id IS NULL OR m.FO_Id = p_fo_id)
      AND (p_gender_cd IS NULL OR m.Gender_Cd = p_gender_cd)
      AND (p_status_cd IS NULL OR m.Current_Status_Cd = p_status_cd)
      AND (
          p_group_id IS NULL
          OR EXISTS (
              SELECT 1 FROM mst_member_group mg
              WHERE mg.Member_Id = m.Member_Id AND mg.Group_Id = p_group_id AND mg.Is_Active = 1
          )
      )
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR m.Member_Code LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.PAN_No, '') = UPPER(p_keyword)
          OR IFNULL(m.Father_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Spouse_Name, '') LIKE CONCAT('%', p_keyword, '%')
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        m.Member_Id,
        m.Member_Code,
        m.Ref_Code,
        m.Member_Name,
        m.Father_Name,
        m.Mother_Name,
        m.Spouse_Name,
        m.Gender_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 28 AND o.Opt_Code = m.Gender_Cd) AS Gender_Desc,
        m.Date_of_Birth,
        IF(m.Date_of_Birth IS NULL, m.Age, TIMESTAMPDIFF(YEAR, m.Date_of_Birth, CURDATE())) AS Age,
        m.Marital_Status_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 29 AND o.Opt_Code = m.Marital_Status_Cd) AS Marital_Status_Desc,
        m.Religion_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 30 AND o.Opt_Code = m.Religion_Cd) AS Religion_Desc,
        m.Caste_Cd,
        (SELECT GROUP_CONCAT(o.Opt_Description ORDER BY o.Option_Id SEPARATOR ' / ') FROM mst_appl_options o WHERE o.Opt_Grp_Id = 32 AND o.Opt_Code = m.Caste_Cd) AS Caste_Desc,
        m.Mobile_No,
        m.Alternate_Mobile_No,
        m.Email_Id,
        m.PAN_No,
        m.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        m.Center_Id,
        c.Center_Name,
        cg.Group_Id,
        g.Group_Code,
        g.Group_Name,
        cg.Member_Role,
        m.Joining_Date,
        m.Occupation_Details,
        m.Monthly_Income,
        m.Monthly_Expense,
        m.Bank_Name,
        m.Bank_Branch,
        m.Bank_Account_No,
        m.IFSC_Code,
        m.Nominee_Name,
        m.Nominee_Rel_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 35 AND o.Opt_Code = m.Nominee_Rel_Cd) AS Nominee_Rel_Desc,
        m.Nominee_DOB,
        m.Nominee_Mobile,
        m.Photo_Path,
        m.Signature_Path,
        m.FO_Id,
        fo.Employee_Code AS FO_Code,
        fo.Full_Name AS FO_Name,
        m.Adm_Fees,
        m.Remarks,
        (SELECT COUNT(*) FROM mst_member_kyc k WHERE k.Member_Id = m.Member_Id AND IFNULL(k.Is_Active, 1) = 1) AS Kyc_Count,
        (SELECT COUNT(*) FROM mst_member_kyc k WHERE k.Member_Id = m.Member_Id AND IFNULL(k.Is_Active, 1) = 1 AND k.KYC_Verified = 1) AS Kyc_Verified_Count,
        (SELECT COUNT(*) FROM mst_member_kyc k WHERE k.Member_Id = m.Member_Id AND IFNULL(k.Is_Active, 1) = 1 AND IFNULL(k.KYC_Verified, 0) = 0) AS Kyc_Pending_Count,
        (SELECT COUNT(*) FROM mst_member_kyc k WHERE k.Member_Id = m.Member_Id AND IFNULL(k.Is_Active, 1) = 1 AND k.KYC_Verified = 2) AS Kyc_Rejected_Count,
        m.Current_Status_Cd AS Status_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 27 AND o.Opt_Code = m.Current_Status_Cd) AS Status_Desc,
        m.Created_By,
        m.Created_At,
        m.Updated_By,
        m.Updated_At
    FROM mst_member m
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = m.Branch_Id
    LEFT JOIN mst_center c ON c.Center_Id = m.Center_Id
    LEFT JOIN mst_staff fo ON fo.Staff_Id = m.FO_Id
    LEFT JOIN mst_member_group cg ON cg.Mem_Group_Id = (
        SELECT mg.Mem_Group_Id FROM mst_member_group mg
        WHERE mg.Member_Id = m.Member_Id AND mg.Is_Active = 1
        ORDER BY mg.Join_Date DESC, mg.Mem_Group_Id DESC
        LIMIT 1
    )
    LEFT JOIN mst_group g ON g.Group_Id = cg.Group_Id
    WHERE (p_member_id IS NULL OR m.Member_Id = p_member_id)
      AND (p_branch_id IS NULL OR m.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR m.Center_Id = p_center_id)
      AND (p_fo_id IS NULL OR m.FO_Id = p_fo_id)
      AND (p_gender_cd IS NULL OR m.Gender_Cd = p_gender_cd)
      AND (p_status_cd IS NULL OR m.Current_Status_Cd = p_status_cd)
      AND (
          p_group_id IS NULL
          OR EXISTS (
              SELECT 1 FROM mst_member_group mg
              WHERE mg.Member_Id = m.Member_Id AND mg.Group_Id = p_group_id AND mg.Is_Active = 1
          )
      )
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR m.Member_Code LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.PAN_No, '') = UPPER(p_keyword)
          OR IFNULL(m.Father_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Spouse_Name, '') LIKE CONCAT('%', p_keyword, '%')
      )
    ORDER BY m.Member_Name ASC, m.Member_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_LOCATION_ADD_EDIT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_LOCATION_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_member_loc_id INT,
    IN p_member_id INT,
    IN p_add_type_cd INT,
    IN p_address_line1 VARCHAR(200),
    IN p_address_line2 VARCHAR(200),
    IN p_village VARCHAR(100),
    IN p_gram_panchayat VARCHAR(100),
    IN p_block_name VARCHAR(100),
    IN p_district_name VARCHAR(100),
    IN p_state_cd INT,
    IN p_pin_code VARCHAR(10),
    IN p_latitude DECIMAL(10,8),
    IN p_longitude DECIMAL(11,8),
    IN p_photo_path VARCHAR(300),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_action VARCHAR(10);
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_member_id INT DEFAULT NULL;
    DECLARE v_member_status INT DEFAULT NULL;
    DECLARE v_cur_active INT DEFAULT NULL;
    DECLARE v_cur_geo INT DEFAULT 0;
    DECLARE v_changed INT DEFAULT 0;
    DECLARE v_type_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_line1 VARCHAR(200);
    DECLARE v_line2 VARCHAR(200);
    DECLARE v_village VARCHAR(100);
    DECLARE v_gp VARCHAR(100);
    DECLARE v_block VARCHAR(100);
    DECLARE v_district VARCHAR(100);
    DECLARE v_pin VARCHAR(10);
    DECLARE v_photo VARCHAR(300);
    DECLARE v_new_id INT DEFAULT NULL;

    SET v_action = UPPER(TRIM(IFNULL(p_action, '')));
    SET v_line1 = NULLIF(TRIM(p_address_line1), '');
    SET v_line2 = NULLIF(TRIM(p_address_line2), '');
    SET v_village = NULLIF(TRIM(p_village), '');
    SET v_gp = NULLIF(TRIM(p_gram_panchayat), '');
    SET v_block = NULLIF(TRIM(p_block_name), '');
    SET v_district = NULLIF(TRIM(p_district_name), '');
    SET v_pin = NULLIF(REPLACE(TRIM(p_pin_code), ' ', ''), '');
    SET v_photo = NULLIF(TRIM(p_photo_path), '');

    IF v_action NOT IN ('ADD', 'EDIT') THEN
        SET v_err = 'Action must be ADD or EDIT';
    END IF;

    IF v_err IS NULL AND v_action = 'EDIT' THEN
        SELECT l.Member_Id, IFNULL(l.Is_Active, 1), IFNULL(l.Geo_Verified, 0)
          INTO v_member_id, v_cur_active, v_cur_geo
        FROM mst_member_location l
        WHERE l.Member_Loc_Id = p_member_loc_id
        FOR UPDATE;

        IF v_member_id IS NULL THEN
            SET v_err = 'Member location not found';
        ELSEIF v_cur_active = 0 THEN
            SET v_err = 'Inactive location cannot be edited; activate it first';
        END IF;
    ELSEIF v_err IS NULL THEN
        SET v_member_id = p_member_id;
    END IF;

    IF v_err IS NULL THEN
        SET v_member_status = NULL;
        SELECT m.Current_Status_Cd INTO v_member_status
        FROM mst_member m
        WHERE m.Member_Id = v_member_id
        FOR UPDATE;

        SELECT COUNT(*) INTO v_cnt FROM mst_member WHERE Member_Id = v_member_id;
        IF v_member_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Member not found';
        ELSEIF IFNULL(v_member_status, 0) IN (4, 5) THEN
            SET v_err = 'Location cannot be changed for a closed or deceased member';
        END IF;
    END IF;

    IF v_err IS NULL THEN
        SELECT MIN(Opt_Description) INTO v_type_desc
        FROM mst_appl_options
        WHERE Opt_Grp_Id = 33 AND Opt_Group = 'Address Type' AND Opt_Code = p_add_type_cd;
        IF p_add_type_cd IS NULL OR v_type_desc IS NULL THEN
            SET v_err = 'Invalid address type';
        END IF;
    END IF;

    IF v_err IS NULL AND p_add_type_cd <> 4 THEN
        SELECT COUNT(*) INTO v_cnt
        FROM mst_member_location
        WHERE Member_Id = v_member_id
          AND Add_Type_Cd = p_add_type_cd
          AND IFNULL(Is_Active, 1) = 1
          AND (v_action = 'ADD' OR Member_Loc_Id <> p_member_loc_id);
        IF v_cnt > 0 THEN
            SET v_err = CONCAT('Member already has an active ', v_type_desc, ' address; edit or deactivate it first');
        END IF;
    END IF;

    IF v_err IS NULL AND v_line1 IS NULL THEN
        SET v_err = 'Address line 1 is required';
    END IF;

    IF v_err IS NULL AND v_district IS NULL THEN
        SET v_err = 'District is required';
    END IF;

    IF v_err IS NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM priomicro_core.mst_states WHERE State_Cd = p_state_cd;
        IF p_state_cd IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Invalid state';
        END IF;
    END IF;

    IF v_err IS NULL AND (v_pin IS NULL OR v_pin NOT REGEXP '^[1-9][0-9]{5}$') THEN
        SET v_err = 'PIN code must be 6 digits and cannot start with 0';
    END IF;

    IF v_err IS NULL AND ((p_latitude IS NULL) <> (p_longitude IS NULL)) THEN
        SET v_err = 'Latitude and longitude must be given together';
    END IF;

    IF v_err IS NULL AND p_latitude IS NOT NULL
       AND (p_latitude < 6 OR p_latitude > 37.6 OR p_longitude < 68 OR p_longitude > 97.5) THEN
        SET v_err = 'Coordinates are outside India';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_member_loc_id AS member_loc_id, v_member_id AS member_id, v_err AS message;
    ELSEIF v_action = 'ADD' THEN
        INSERT INTO mst_member_location (
            Member_Id, Add_Type_Cd, Address_Line1, Address_Line2, Village, Gram_Panchayat, Block_Name,
            District_Name, State_Cd, Pin_Code, Latitude, Longitude, Geo_Verified, Photo_Path,
            Is_Active, Created_By, Created_At
        ) VALUES (
            v_member_id, p_add_type_cd, v_line1, v_line2, v_village, v_gp, v_block,
            v_district, p_state_cd, v_pin, p_latitude, p_longitude, 0, v_photo,
            1, p_user_id, NOW()
        );

        SET v_new_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_new_id AS member_loc_id, v_member_id AS member_id,
               'Member location added successfully' AS message;
    ELSE
        SELECT COUNT(*) INTO v_changed
        FROM mst_member_location
        WHERE Member_Loc_Id = p_member_loc_id
          AND NOT (
              Address_Line1 <=> v_line1
              AND Address_Line2 <=> v_line2
              AND Village <=> v_village
              AND Gram_Panchayat <=> v_gp
              AND Block_Name <=> v_block
              AND District_Name <=> v_district
              AND State_Cd <=> p_state_cd
              AND Pin_Code <=> v_pin
              AND Latitude <=> p_latitude
              AND Longitude <=> p_longitude
          );

        UPDATE mst_member_location
        SET Add_Type_Cd = p_add_type_cd,
            Address_Line1 = v_line1,
            Address_Line2 = v_line2,
            Village = v_village,
            Gram_Panchayat = v_gp,
            Block_Name = v_block,
            District_Name = v_district,
            State_Cd = p_state_cd,
            Pin_Code = v_pin,
            Latitude = p_latitude,
            Longitude = p_longitude,
            Photo_Path = v_photo,
            Geo_Verified = IF(v_changed > 0, 0, Geo_Verified),
            Geo_Verified_Date = IF(v_changed > 0, NULL, Geo_Verified_Date),
            Geo_Verified_By = IF(v_changed > 0, NULL, Geo_Verified_By),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Member_Loc_Id = p_member_loc_id;

        SELECT 'SUCCESS' AS status, p_member_loc_id AS member_loc_id, v_member_id AS member_id,
               IF(v_changed > 0 AND v_cur_geo = 1,
                  'Member location updated; geo verification has been reset',
                  'Member location updated successfully') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_LOCATION_GEO_VERIFY` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_LOCATION_GEO_VERIFY`(
    IN p_member_loc_id INT,
    IN p_geo_verified INT,
    IN p_latitude DECIMAL(10,8),
    IN p_longitude DECIMAL(11,8),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_member_id INT DEFAULT NULL;
    DECLARE v_member_status INT DEFAULT NULL;
    DECLARE v_active INT DEFAULT NULL;
    DECLARE v_current INT DEFAULT NULL;
    DECLARE v_lat DECIMAL(10,8) DEFAULT NULL;
    DECLARE v_lng DECIMAL(11,8) DEFAULT NULL;
    DECLARE v_coords_changed INT DEFAULT 0;

    SELECT l.Member_Id, IFNULL(l.Is_Active, 1), IFNULL(l.Geo_Verified, 0), l.Latitude, l.Longitude
      INTO v_member_id, v_active, v_current, v_lat, v_lng
    FROM mst_member_location l
    WHERE l.Member_Loc_Id = p_member_loc_id
    FOR UPDATE;

    IF v_member_id IS NULL THEN
        SET v_err = 'Member location not found';
    ELSEIF p_geo_verified IS NULL OR p_geo_verified NOT IN (0, 1) THEN
        SET v_err = 'Geo verified must be 0 (Not verified) or 1 (Verified)';
    ELSEIF (p_latitude IS NULL) <> (p_longitude IS NULL) THEN
        SET v_err = 'Latitude and longitude must be given together';
    ELSEIF p_latitude IS NOT NULL AND p_geo_verified = 0 THEN
        SET v_err = 'Coordinates can only be captured when verifying';
    ELSEIF p_latitude IS NOT NULL
       AND (p_latitude < 6 OR p_latitude > 37.6 OR p_longitude < 68 OR p_longitude > 97.5) THEN
        SET v_err = 'Coordinates are outside India';
    END IF;

    IF v_err IS NULL THEN
        SET v_coords_changed = IF(p_latitude IS NOT NULL AND NOT (v_lat <=> p_latitude AND v_lng <=> p_longitude), 1, 0);
    END IF;

    IF v_err IS NULL AND (v_current <> p_geo_verified OR v_coords_changed = 1) THEN
        SELECT Current_Status_Cd INTO v_member_status FROM mst_member WHERE Member_Id = v_member_id;

        IF v_active = 0 THEN
            SET v_err = 'Inactive location cannot be geo-verified';
        ELSEIF IFNULL(v_member_status, 0) IN (4, 5) THEN
            SET v_err = 'Location cannot be changed for a closed or deceased member';
        ELSEIF p_geo_verified = 1 AND IFNULL(p_latitude, v_lat) IS NULL THEN
            SET v_err = 'Capture the GPS coordinates before geo-verifying';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_member_loc_id AS member_loc_id, v_current AS geo_verified, v_err AS message;
    ELSEIF v_current = p_geo_verified AND v_coords_changed = 0 THEN
        SELECT 'SUCCESS' AS status, p_member_loc_id AS member_loc_id, v_current AS geo_verified,
               IF(v_current = 1, 'Location is already geo-verified', 'Location is already not geo-verified') AS message;
    ELSE
        UPDATE mst_member_location
        SET Geo_Verified = p_geo_verified,
            Latitude = IFNULL(p_latitude, Latitude),
            Longitude = IFNULL(p_longitude, Longitude),
            Geo_Verified_Date = IF(p_geo_verified = 1, NOW(), NULL),
            Geo_Verified_By = IF(p_geo_verified = 1, p_user_id, NULL),
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Member_Loc_Id = p_member_loc_id;

        SELECT 'SUCCESS' AS status, p_member_loc_id AS member_loc_id, p_geo_verified AS geo_verified,
               IF(p_geo_verified = 1, 'Location geo-verified', 'Geo verification removed') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_LOCATION_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_LOCATION_LIST`(
    IN p_member_loc_id INT,
    IN p_member_id INT,
    IN p_branch_id INT,
    IN p_center_id INT,
    IN p_add_type_cd INT,
    IN p_state_cd INT,
    IN p_geo_verified INT,
    IN p_has_coordinates INT,
    IN p_is_active INT,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_member_location l
    JOIN mst_member m ON m.Member_Id = l.Member_Id
    WHERE (p_member_loc_id IS NULL OR l.Member_Loc_Id = p_member_loc_id)
      AND (p_member_id IS NULL OR l.Member_Id = p_member_id)
      AND (p_branch_id IS NULL OR m.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR m.Center_Id = p_center_id)
      AND (p_add_type_cd IS NULL OR l.Add_Type_Cd = p_add_type_cd)
      AND (p_state_cd IS NULL OR l.State_Cd = p_state_cd)
      AND (p_geo_verified IS NULL OR IFNULL(l.Geo_Verified, 0) = p_geo_verified)
      AND (
          p_has_coordinates IS NULL
          OR (p_has_coordinates = 1 AND l.Latitude IS NOT NULL AND l.Longitude IS NOT NULL)
          OR (p_has_coordinates = 0 AND (l.Latitude IS NULL OR l.Longitude IS NULL))
      )
      AND (p_is_active IS NULL OR IFNULL(l.Is_Active, 1) = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR CAST(m.Member_Code AS CHAR) = p_keyword
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Village, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Gram_Panchayat, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Block_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.District_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Pin_Code, '') = p_keyword
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        l.Member_Loc_Id,
        l.Member_Id,
        m.Member_Code,
        m.Ref_Code,
        m.Member_Name,
        m.Mobile_No,
        m.Current_Status_Cd AS Member_Status_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 27 AND o.Opt_Code = m.Current_Status_Cd) AS Member_Status_Desc,
        m.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        m.Center_Id,
        c.Center_Name,
        l.Add_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o
          WHERE o.Opt_Grp_Id = 33 AND o.Opt_Group = 'Address Type' AND o.Opt_Code = l.Add_Type_Cd) AS Add_Type_Desc,
        l.Address_Line1,
        l.Address_Line2,
        l.Village,
        l.Gram_Panchayat,
        l.Block_Name,
        l.District_Name,
        l.State_Cd,
        s.State_Name,
        l.Pin_Code,
        l.Latitude,
        l.Longitude,
        IFNULL(l.Geo_Verified, 0) AS Geo_Verified,
        l.Geo_Verified_Date,
        l.Geo_Verified_By,
        vu.User_Name AS Geo_Verified_By_Name,
        l.Photo_Path,
        IFNULL(l.Is_Active, 1) AS Is_Active,
        l.Created_By,
        cu.User_Name AS Created_By_Name,
        l.Created_At,
        l.Updated_By,
        l.Updated_At
    FROM mst_member_location l
    JOIN mst_member m ON m.Member_Id = l.Member_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = m.Branch_Id
    LEFT JOIN mst_center c ON c.Center_Id = m.Center_Id
    LEFT JOIN priomicro_core.mst_states s ON s.State_Cd = l.State_Cd
    LEFT JOIN priomicro_core.mst_org_user vu ON vu.User_Id = l.Geo_Verified_By
    LEFT JOIN priomicro_core.mst_org_user cu ON cu.User_Id = l.Created_By
    WHERE (p_member_loc_id IS NULL OR l.Member_Loc_Id = p_member_loc_id)
      AND (p_member_id IS NULL OR l.Member_Id = p_member_id)
      AND (p_branch_id IS NULL OR m.Branch_Id = p_branch_id)
      AND (p_center_id IS NULL OR m.Center_Id = p_center_id)
      AND (p_add_type_cd IS NULL OR l.Add_Type_Cd = p_add_type_cd)
      AND (p_state_cd IS NULL OR l.State_Cd = p_state_cd)
      AND (p_geo_verified IS NULL OR IFNULL(l.Geo_Verified, 0) = p_geo_verified)
      AND (
          p_has_coordinates IS NULL
          OR (p_has_coordinates = 1 AND l.Latitude IS NOT NULL AND l.Longitude IS NOT NULL)
          OR (p_has_coordinates = 0 AND (l.Latitude IS NULL OR l.Longitude IS NULL))
      )
      AND (p_is_active IS NULL OR IFNULL(l.Is_Active, 1) = p_is_active)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR m.Member_Name LIKE CONCAT('%', p_keyword, '%')
          OR CAST(m.Member_Code AS CHAR) = p_keyword
          OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(m.Mobile_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Village, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Gram_Panchayat, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Block_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.District_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(l.Pin_Code, '') = p_keyword
      )
    ORDER BY l.Member_Id DESC, l.Add_Type_Cd, l.Member_Loc_Id
    LIMIT v_offset, v_per_page;
END ;;
DELIMITER ;
