DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_LOCATION_STATUS`(
    IN p_member_loc_id INT,
    IN p_is_active INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_member_id INT DEFAULT NULL;
    DECLARE v_member_status INT DEFAULT NULL;
    DECLARE v_type INT DEFAULT NULL;
    DECLARE v_type_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_current INT DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;

    SELECT l.Member_Id, l.Add_Type_Cd, IFNULL(l.Is_Active, 1)
      INTO v_member_id, v_type, v_current
    FROM mst_member_location l
    WHERE l.Member_Loc_Id = p_member_loc_id
    FOR UPDATE;

    IF v_member_id IS NULL THEN
        SET v_err = 'Member location not found';
    ELSEIF p_is_active IS NULL OR p_is_active NOT IN (0, 1) THEN
        SET v_err = 'Status must be 0 (Inactive) or 1 (Active)';
    END IF;

    IF v_err IS NULL AND v_current <> p_is_active THEN
        SELECT Current_Status_Cd INTO v_member_status FROM mst_member WHERE Member_Id = v_member_id;

        IF IFNULL(v_member_status, 0) IN (4, 5) THEN
            SET v_err = 'Location cannot be changed for a closed or deceased member';
        ELSEIF p_is_active = 1 AND IFNULL(v_type, 0) <> 4 THEN
            SELECT COUNT(*) INTO v_cnt
            FROM mst_member_location
            WHERE Member_Id = v_member_id
              AND Add_Type_Cd = v_type
              AND IFNULL(Is_Active, 1) = 1
              AND Member_Loc_Id <> p_member_loc_id;

            IF v_cnt > 0 THEN
                SELECT MIN(Opt_Description) INTO v_type_desc
                FROM mst_appl_options
                WHERE Opt_Grp_Id = 33 AND Opt_Group = 'Address Type' AND Opt_Code = v_type;

                SET v_err = CONCAT('Member already has an active ', IFNULL(v_type_desc, 'address of this type'),
                                   ' address; deactivate it first');
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_member_loc_id AS member_loc_id, v_current AS is_active, v_err AS message;
    ELSEIF v_current = p_is_active THEN
        SELECT 'SUCCESS' AS status, p_member_loc_id AS member_loc_id, v_current AS is_active,
               IF(p_is_active = 1, 'Location is already active', 'Location is already inactive') AS message;
    ELSE
        UPDATE mst_member_location
        SET Is_Active = p_is_active,
            Updated_By = p_user_id,
            Updated_At = NOW()
        WHERE Member_Loc_Id = p_member_loc_id;

        SELECT 'SUCCESS' AS status, p_member_loc_id AS member_loc_id, p_is_active AS is_active,
               IF(p_is_active = 1, 'Location activated', 'Location deactivated') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MEMBER_STATUS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
