/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MEMBER_STATUS`(
    IN p_member_id INT,
    IN p_status_cd INT,
    IN p_user_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_current INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_center INT DEFAULT NULL;
    DECLARE v_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_err VARCHAR(255) DEFAULT NULL;

    SELECT COUNT(*), MAX(Current_Status_Cd), MAX(Branch_Id), MAX(Center_Id)
    INTO v_cnt, v_current, v_branch, v_center
    FROM mst_member WHERE Member_Id = p_member_id;

    SELECT MIN(Opt_Description) INTO v_desc
    FROM mst_appl_options WHERE Opt_Grp_Id = 27 AND Opt_Code = p_status_cd;

    IF p_member_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Member not found';
    ELSEIF p_status_cd IS NULL OR p_status_cd NOT IN (1, 2, 3, 4, 5) THEN
        SET v_err = 'Status must be 1 (Active), 2 (Inactive), 3 (Suspended), 4 (Closed) or 5 (Death)';
    END IF;

    IF v_err IS NULL AND IFNULL(v_current, 0) <> p_status_cd THEN
        IF p_status_cd = 1 THEN
            SELECT COUNT(*) INTO v_cnt FROM priomicro_core.mst_org_branch
            WHERE Branch_Id = v_branch AND IFNULL(Is_Active, 0) = 1;
            IF v_cnt = 0 THEN
                SET v_err = 'Branch is inactive; member cannot be activated';
            ELSEIF v_center IS NOT NULL THEN
                SELECT COUNT(*) INTO v_cnt FROM mst_center
                WHERE Center_Id = v_center AND IFNULL(Is_Active, 0) = 1;
                IF v_cnt = 0 THEN
                    SET v_err = 'Center is inactive; member cannot be activated';
                END IF;
            END IF;
        ELSEIF p_status_cd = 4 THEN
            SELECT COUNT(*) INTO v_cnt FROM mst_member_group
            WHERE Member_Id = p_member_id AND Is_Active = 1;
            IF v_cnt > 0 THEN
                SET v_err = 'Member is still in an active group; remove the member from the group before closing';
            END IF;
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_member_id AS member_id, v_current AS status_cd, v_err AS message;
    ELSEIF v_current = p_status_cd THEN
        SELECT 'SUCCESS' AS status, p_member_id AS member_id, v_current AS status_cd,
               CONCAT('Member is already ', LOWER(IFNULL(v_desc, 'in this status'))) AS message;
    ELSE
        UPDATE mst_member
        SET Current_Status_Cd = p_status_cd, Updated_By = p_user_id, Updated_At = NOW()
        WHERE Member_Id = p_member_id;

        SELECT 'SUCCESS' AS status, p_member_id AS member_id, p_status_cd AS status_cd,
               CONCAT('Member status changed to ', IFNULL(v_desc, p_status_cd)) AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
