CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MENU_LIST`(
    IN p_role_id SMALLINT,
    IN p_menu_sl SMALLINT,
    IN p_menu_id SMALLINT,
    IN p_submenu_id SMALLINT,
    IN p_status TINYINT,
    IN p_lang_code VARCHAR(5)
)
BEGIN
    DECLARE v_is_admin TINYINT DEFAULT 0;
    DECLARE v_lang CHAR(2) DEFAULT 'EN';

    SET v_lang = UPPER(IFNULL(NULLIF(TRIM(p_lang_code), ''), 'EN'));
    IF v_lang NOT IN ('EN', 'BN', 'HI', 'OR') THEN
        SET v_lang = 'EN';
    END IF;

    IF p_role_id IS NOT NULL THEN
        SELECT IFNULL(Is_Admin, 0) INTO v_is_admin
        FROM mst_role
        WHERE Id = p_role_id
          AND Status = 1
        LIMIT 1;
    END IF;

    IF p_role_id IS NULL OR v_is_admin = 1 THEN
        SELECT
            m.Menu_Sl,
            m.Menu_Id,
            CASE
                WHEN v_lang = 'EN' THEN m.Menu_Name
                ELSE COALESCE(NULLIF(TRIM(ml.Menu_Name), ''), m.Menu_Name)
            END AS Menu_Name,
            m.Menu_Name AS Menu_Name_Default,
            m.SubMenu_Id,
            CASE
                WHEN v_lang = 'EN' THEN m.SubMenu_Name
                ELSE COALESCE(NULLIF(TRIM(ml.SubMenu_Name), ''), m.SubMenu_Name)
            END AS SubMenu_Name,
            m.SubMenu_Name AS SubMenu_Name_Default,
            m.Icon,
            m.Route,
            m.Status,
            v_lang AS Lang_Code
        FROM mst_menus m
        LEFT JOIN mst_menu_lang ml
            ON ml.Menu_Sl = m.Menu_Sl
           AND ml.Lang_Code = v_lang
           AND ml.Status = 1
        WHERE (p_menu_sl IS NULL OR m.Menu_Sl = p_menu_sl)
          AND (p_menu_id IS NULL OR m.Menu_Id = p_menu_id)
          AND (p_submenu_id IS NULL OR m.SubMenu_Id = p_submenu_id)
          AND (p_status IS NULL OR m.Status = p_status)
        ORDER BY m.Menu_Id, IFNULL(m.SubMenu_Id, 0), m.Menu_Sl;
    ELSE
        SELECT DISTINCT
            m.Menu_Sl,
            m.Menu_Id,
            CASE
                WHEN v_lang = 'EN' THEN m.Menu_Name
                ELSE COALESCE(NULLIF(TRIM(ml.Menu_Name), ''), m.Menu_Name)
            END AS Menu_Name,
            m.Menu_Name AS Menu_Name_Default,
            m.SubMenu_Id,
            CASE
                WHEN v_lang = 'EN' THEN m.SubMenu_Name
                ELSE COALESCE(NULLIF(TRIM(ml.SubMenu_Name), ''), m.SubMenu_Name)
            END AS SubMenu_Name,
            m.SubMenu_Name AS SubMenu_Name_Default,
            m.Icon,
            m.Route,
            m.Status,
            v_lang AS Lang_Code
        FROM mst_menus m
        LEFT JOIN mst_menu_lang ml
            ON ml.Menu_Sl = m.Menu_Sl
           AND ml.Lang_Code = v_lang
           AND ml.Status = 1
        WHERE (p_menu_sl IS NULL OR m.Menu_Sl = p_menu_sl)
          AND (p_menu_id IS NULL OR m.Menu_Id = p_menu_id)
          AND (p_submenu_id IS NULL OR m.SubMenu_Id = p_submenu_id)
          AND (p_status IS NULL OR m.Status = p_status)
          AND (
            m.Menu_Sl IN (
                SELECT rm.Menu_Sl
                FROM mst_role_menu rm
                WHERE rm.Role_Id = p_role_id
                  AND rm.Status = 1
            )
            OR (
                m.SubMenu_Id IS NULL
                AND m.Menu_Name IS NOT NULL
                AND EXISTS (
                    SELECT 1
                    FROM mst_menus child
                    INNER JOIN mst_role_menu rm
                        ON rm.Menu_Sl = child.Menu_Sl
                       AND rm.Role_Id = p_role_id
                       AND rm.Status = 1
                    WHERE child.Menu_Id = m.Menu_Id
                      AND child.SubMenu_Id IS NOT NULL
                )
            )
          )
        ORDER BY m.Menu_Id, IFNULL(m.SubMenu_Id, 0), m.Menu_Sl;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_MENU_LIST_BY_USER` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MENU_LIST_BY_USER`(
    IN p_user_id SMALLINT,
    IN p_status TINYINT,
    IN p_lang_code VARCHAR(5)
)
BEGIN
    DECLARE v_is_admin INT DEFAULT 0;
    DECLARE v_lang CHAR(2) DEFAULT 'EN';

    SET v_lang = UPPER(IFNULL(NULLIF(TRIM(p_lang_code), ''), 'EN'));
    IF v_lang NOT IN ('EN', 'BN', 'HI', 'OR') THEN
        SET v_lang = 'EN';
    END IF;

    SELECT COUNT(*) INTO v_is_admin
    FROM mst_user_role ur
    INNER JOIN mst_role r ON r.Id = ur.Role_Id
    WHERE ur.User_Id = p_user_id
      AND ur.Status = 1
      AND r.Status = 1
      AND IFNULL(r.Is_Admin, 0) = 1;

    IF v_is_admin > 0 THEN
        SELECT
            m.Menu_Sl,
            m.Menu_Id,
            CASE
                WHEN v_lang = 'EN' THEN m.Menu_Name
                ELSE COALESCE(NULLIF(TRIM(ml.Menu_Name), ''), m.Menu_Name)
            END AS Menu_Name,
            m.Menu_Name AS Menu_Name_Default,
            m.SubMenu_Id,
            CASE
                WHEN v_lang = 'EN' THEN m.SubMenu_Name
                ELSE COALESCE(NULLIF(TRIM(ml.SubMenu_Name), ''), m.SubMenu_Name)
            END AS SubMenu_Name,
            m.SubMenu_Name AS SubMenu_Name_Default,
            m.Icon,
            m.Route,
            m.Status,
            v_lang AS Lang_Code
        FROM mst_menus m
        LEFT JOIN mst_menu_lang ml
            ON ml.Menu_Sl = m.Menu_Sl
           AND ml.Lang_Code = v_lang
           AND ml.Status = 1
        WHERE (p_status IS NULL OR m.Status = p_status)
        ORDER BY m.Menu_Id, IFNULL(m.SubMenu_Id, 0), m.Menu_Sl;
    ELSE
        SELECT DISTINCT
            m.Menu_Sl,
            m.Menu_Id,
            CASE
                WHEN v_lang = 'EN' THEN m.Menu_Name
                ELSE COALESCE(NULLIF(TRIM(ml.Menu_Name), ''), m.Menu_Name)
            END AS Menu_Name,
            m.Menu_Name AS Menu_Name_Default,
            m.SubMenu_Id,
            CASE
                WHEN v_lang = 'EN' THEN m.SubMenu_Name
                ELSE COALESCE(NULLIF(TRIM(ml.SubMenu_Name), ''), m.SubMenu_Name)
            END AS SubMenu_Name,
            m.SubMenu_Name AS SubMenu_Name_Default,
            m.Icon,
            m.Route,
            m.Status,
            v_lang AS Lang_Code
        FROM mst_menus m
        LEFT JOIN mst_menu_lang ml
            ON ml.Menu_Sl = m.Menu_Sl
           AND ml.Lang_Code = v_lang
           AND ml.Status = 1
        WHERE (p_status IS NULL OR m.Status = p_status)
          AND (
            m.Menu_Sl IN (
                SELECT rm.Menu_Sl
                FROM mst_user_role ur
                INNER JOIN mst_role_menu rm
                    ON rm.Role_Id = ur.Role_Id
                   AND rm.Status = 1
                WHERE ur.User_Id = p_user_id
                  AND ur.Status = 1
            )
            OR (
                m.SubMenu_Id IS NULL
                AND m.Menu_Name IS NOT NULL
                AND EXISTS (
                    SELECT 1
                    FROM mst_menus child
                    INNER JOIN mst_role_menu rm ON rm.Menu_Sl = child.Menu_Sl AND rm.Status = 1
                    INNER JOIN mst_user_role ur ON ur.Role_Id = rm.Role_Id AND ur.Status = 1
                    WHERE ur.User_Id = p_user_id
                      AND child.Menu_Id = m.Menu_Id
                      AND child.SubMenu_Id IS NOT NULL
                )
            )
          )
        ORDER BY m.Menu_Id, IFNULL(m.SubMenu_Id, 0), m.Menu_Sl;
    END IF;
END ;;
DELIMITER ;
