CREATE DEFINER=`priority`@`%` PROCEDURE `USP_MODULE_ACCESS_LIST`(
    IN p_status TINYINT
)
BEGIN
    SELECT Module_Id, Module_Key, Module_Label, Status
    FROM mst_module_access
    WHERE (p_status IS NULL OR Status = p_status)
    ORDER BY Module_Id ASC;
