CREATE DEFINER=`priority`@`%` PROCEDURE `USP_OPERATIONAL_DAYS_ADD_EDIT`(
    IN p_mode VARCHAR(10),
    IN p_rec_id SMALLINT UNSIGNED,
    IN p_branch_id SMALLINT,
    IN p_day_of_week TINYINT,
    IN p_is_operational TINYINT,
    IN p_is_half_day TINYINT,
    IN p_open_time TIME,
    IN p_close_time TIME,
    IN p_is_active TINYINT,
    IN p_created_by SMALLINT
)
BEGIN
    DECLARE v_rec_id SMALLINT UNSIGNED DEFAULT NULL;
    DECLARE v_branch_exists INT DEFAULT 0;
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;

    IF p_mode IS NULL OR p_mode NOT IN ('ADD', 'EDIT') THEN
        SELECT 'ERROR' AS status, NULL AS rec_id, 'Invalid mode. Use ADD or EDIT' AS message;
    ELSEIF p_branch_id IS NULL OR p_branch_id < 1 THEN
        SELECT 'ERROR' AS status, NULL AS rec_id, 'Branch is required' AS message;
    ELSEIF p_day_of_week IS NULL OR p_day_of_week < 1 OR p_day_of_week > 7 THEN
        SELECT 'ERROR' AS status, NULL AS rec_id, 'Day of week must be between 1 (Monday) and 7 (Sunday)' AS message;
    ELSEIF IFNULL(p_is_operational, 0) = 1
           AND p_open_time IS NOT NULL
           AND p_close_time IS NOT NULL
           AND p_close_time <= p_open_time THEN
        SELECT 'ERROR' AS status, NULL AS rec_id, 'Close time must be after open time' AS message;
    ELSE
        SELECT COUNT(*) INTO v_branch_exists
        FROM priomicro_core.mst_org_branch
        WHERE Branch_Id = p_branch_id
          AND IFNULL(Is_Active, 0) = 1;

        IF v_branch_exists = 0 THEN
            SELECT 'ERROR' AS status, NULL AS rec_id, 'Active branch not found' AS message;
        ELSEIF p_mode = 'ADD' THEN
            SELECT COUNT(*) INTO v_dup
            FROM mst_operational_days
            WHERE Branch_Id = p_branch_id
              AND Day_Of_Week = p_day_of_week;

            IF v_dup > 0 THEN
                SELECT 'ERROR' AS status, NULL AS rec_id, 'Operational day already exists for this branch and weekday' AS message;
            ELSE
                INSERT INTO mst_operational_days (
                    Branch_Id,
                    Day_Of_Week,
                    Is_Operational,
                    Is_Half_Day,
                    Open_Time,
                    Close_Time,
                    Is_Active,
                    Created_by,
                    Created_at
                ) VALUES (
                    p_branch_id,
                    p_day_of_week,
                    IFNULL(p_is_operational, 1),
                    IFNULL(p_is_half_day, 0),
                    p_open_time,
                    p_close_time,
                    IFNULL(p_is_active, 1),
                    p_created_by,
                    NOW()
                );

                SET v_rec_id = LAST_INSERT_ID();
                SELECT 'SUCCESS' AS status, v_rec_id AS rec_id, 'Operational day created successfully' AS message;
            END IF;
        ELSE
            IF p_rec_id IS NULL OR p_rec_id < 1 THEN
                SELECT 'ERROR' AS status, NULL AS rec_id, 'Rec id is required for EDIT' AS message;
            ELSE
                SELECT COUNT(*) INTO v_exists
                FROM mst_operational_days
                WHERE Rec_Id = p_rec_id;

                IF v_exists = 0 THEN
                    SELECT 'ERROR' AS status, p_rec_id AS rec_id, 'Operational day not found' AS message;
                ELSE
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_operational_days
                    WHERE Branch_Id = p_branch_id
                      AND Day_Of_Week = p_day_of_week
                      AND Rec_Id <> p_rec_id;

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, p_rec_id AS rec_id, 'Operational day already exists for this branch and weekday' AS message;
                    ELSE
                        UPDATE mst_operational_days
                        SET
                            Branch_Id = p_branch_id,
                            Day_Of_Week = p_day_of_week,
                            Is_Operational = IFNULL(p_is_operational, Is_Operational),
                            Is_Half_Day = IFNULL(p_is_half_day, Is_Half_Day),
                            Open_Time = p_open_time,
                            Close_Time = p_close_time,
                            Is_Active = IFNULL(p_is_active, Is_Active)
                        WHERE Rec_Id = p_rec_id;

                        SELECT 'SUCCESS' AS status, p_rec_id AS rec_id, 'Operational day updated successfully' AS message;
                    END IF;
                END IF;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_OPERATIONAL_DAYS_LIST` */;
