CREATE DEFINER=`priority`@`%` PROCEDURE `USP_OPERATIONAL_DAYS_LIST`(
    IN p_rec_id SMALLINT UNSIGNED,
    IN p_branch_id SMALLINT,
    IN p_day_of_week TINYINT,
    IN p_is_operational TINYINT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_operational_days od
    WHERE (p_rec_id IS NULL OR od.Rec_Id = p_rec_id)
      AND (p_branch_id IS NULL OR od.Branch_Id = p_branch_id)
      AND (p_day_of_week IS NULL OR od.Day_Of_Week = p_day_of_week)
      AND (p_is_operational IS NULL OR od.Is_Operational = p_is_operational)
      AND (p_is_active IS NULL OR od.Is_Active = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        od.Rec_Id,
        od.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        od.Day_Of_Week,
        CASE od.Day_Of_Week
            WHEN 1 THEN 'Monday'
            WHEN 2 THEN 'Tuesday'
            WHEN 3 THEN 'Wednesday'
            WHEN 4 THEN 'Thursday'
            WHEN 5 THEN 'Friday'
            WHEN 6 THEN 'Saturday'
            WHEN 7 THEN 'Sunday'
            ELSE NULL
        END AS Day_Name,
        CAST(od.Is_Operational AS UNSIGNED) AS Is_Operational,
        CAST(od.Is_Half_Day AS UNSIGNED) AS Is_Half_Day,
        TIME_FORMAT(od.Open_Time, '%H:%i') AS Open_Time,
        TIME_FORMAT(od.Close_Time, '%H:%i') AS Close_Time,
        od.Is_Active,
        od.Created_by,
        od.Created_at
    FROM mst_operational_days od
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = od.Branch_Id
    WHERE (p_rec_id IS NULL OR od.Rec_Id = p_rec_id)
      AND (p_branch_id IS NULL OR od.Branch_Id = p_branch_id)
      AND (p_day_of_week IS NULL OR od.Day_Of_Week = p_day_of_week)
      AND (p_is_operational IS NULL OR od.Is_Operational = p_is_operational)
      AND (p_is_active IS NULL OR od.Is_Active = p_is_active)
    ORDER BY od.Branch_Id ASC, od.Day_Of_Week ASC, od.Rec_Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
