CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ROLE_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_role_id SMALLINT,
    IN p_role_name VARCHAR(100),
    IN p_description VARCHAR(255),
    IN p_is_admin TINYINT,
    IN p_status TINYINT,
    IN p_created_by SMALLINT
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;
    DECLARE v_name VARCHAR(100);
    DECLARE v_desc VARCHAR(255);
    DECLARE v_new_id SMALLINT DEFAULT NULL;

    SET v_name = NULLIF(TRIM(p_role_name), '');
    SET v_desc = NULLIF(TRIM(IFNULL(p_description, '')), '');

    IF UPPER(p_action) = 'ADD' THEN
        IF v_name IS NULL THEN
            SELECT 'ERROR' AS status, NULL AS role_id, 'Role name is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_dup
            FROM mst_role
            WHERE LOWER(Role_Name) = LOWER(v_name);

            IF v_dup > 0 THEN
                SELECT 'ERROR' AS status, NULL AS role_id, 'Role already exists' AS message;
            ELSE
                INSERT INTO mst_role (Role_Name, Description, Is_Admin, Status, Created_by, Created_at)
                VALUES (v_name, v_desc, IFNULL(p_is_admin, 0), IFNULL(p_status, 1), p_created_by, NOW());

                SET v_new_id = LAST_INSERT_ID();

                SELECT 'SUCCESS' AS status, v_new_id AS role_id, 'Role created successfully' AS message;
            END IF;
        END IF;

    ELSEIF UPPER(p_action) = 'EDIT' THEN
        SELECT COUNT(*) INTO v_exists FROM mst_role WHERE Id = p_role_id;

        IF v_exists = 0 THEN
            SELECT 'ERROR' AS status, p_role_id AS role_id, 'Role not found' AS message;
        ELSEIF v_name IS NULL THEN
            SELECT 'ERROR' AS status, p_role_id AS role_id, 'Role name is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_dup
            FROM mst_role
            WHERE LOWER(Role_Name) = LOWER(v_name)
              AND Id <> p_role_id;

            IF v_dup > 0 THEN
                SELECT 'ERROR' AS status, p_role_id AS role_id, 'Role already exists' AS message;
            ELSE
                UPDATE mst_role
                SET Role_Name = v_name,
                    Description = v_desc,
                    Is_Admin = IFNULL(p_is_admin, Is_Admin),
                    Status = IFNULL(p_status, Status)
                WHERE Id = p_role_id;

                SELECT 'SUCCESS' AS status, p_role_id AS role_id, 'Role updated successfully' AS message;
            END IF;
        END IF;

    ELSE
        SELECT 'ERROR' AS status, p_role_id AS role_id, 'Invalid action. Use ADD or EDIT' AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_ROLE_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ROLE_LIST`(
    IN p_role_id SMALLINT,
    IN p_keyword VARCHAR(100),
    IN p_is_admin TINYINT,
    IN p_status TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_role r
    WHERE (p_role_id IS NULL OR r.Id = p_role_id)
      AND (
          p_keyword IS NULL
          OR p_keyword = ''
          OR r.Role_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(r.Description, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_is_admin IS NULL OR IFNULL(r.Is_Admin, 0) = p_is_admin)
      AND (p_status IS NULL OR IFNULL(r.Status, 1) = p_status);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE
            WHEN v_total = 0 THEN 1
            ELSE CEIL(v_total / v_per_page)
        END AS last_page;

    SELECT
        r.Id,
        r.Role_Name,
        r.Description,
        r.Is_Admin,
        r.Status,
        r.Created_by,
        r.Created_at
    FROM mst_role r
    WHERE (p_role_id IS NULL OR r.Id = p_role_id)
      AND (
          p_keyword IS NULL
          OR p_keyword = ''
          OR r.Role_Name LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(r.Description, '') LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_is_admin IS NULL OR IFNULL(r.Is_Admin, 0) = p_is_admin)
      AND (p_status IS NULL OR IFNULL(r.Status, 1) = p_status)
    ORDER BY r.Role_Name ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
