CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ROLE_MENU_ASSIGN`(
    IN p_role_id SMALLINT,
    IN p_menus_json LONGTEXT,
    IN p_created_by SMALLINT
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_assigned INT DEFAULT 0;
    DECLARE v_skipped INT DEFAULT 0;

    SELECT COUNT(*) INTO v_exists
    FROM mst_role
    WHERE Id = p_role_id;

    IF v_exists = 0 THEN
        SELECT 'ERROR' AS status, p_role_id AS role_id, 0 AS assigned_count,
               'Role not found' AS message;
    ELSEIF p_menus_json IS NULL OR TRIM(p_menus_json) = '' THEN
        SELECT 'ERROR' AS status, p_role_id AS role_id, 0 AS assigned_count,
               'menus payload is required (use [] to clear)' AS message;
    ELSEIF JSON_VALID(p_menus_json) = 0 OR JSON_TYPE(p_menus_json) <> 'ARRAY' THEN
        SELECT 'ERROR' AS status, p_role_id AS role_id, 0 AS assigned_count,
               'menus must be a JSON array' AS message;
    ELSE
        DELETE FROM mst_role_menu WHERE Role_Id = p_role_id;

        INSERT INTO mst_role_menu (
            Role_Id,
            Menu_Sl,
            Allow_Create,
            Allow_Read,
            Allow_Edit,
            Allow_Del,
            Allow_Approve,
            Allow_Reverse,
            Allow_Print,
            Status,
            Created_by,
            Created_at
        )
        SELECT
            p_role_id,
            j.menu_sl,
            IFNULL(j.allow_create, 1),
            IFNULL(j.allow_read, 1),
            IFNULL(j.allow_edit, 1),
            IFNULL(j.allow_del, 1),
            IFNULL(j.allow_approve, 0),
            IFNULL(j.allow_reverse, 0),
            IFNULL(j.allow_print, 1),
            IFNULL(j.status, 1),
            p_created_by,
            NOW()
        FROM JSON_TABLE(
            p_menus_json,
            '$[*]' COLUMNS (
                menu_sl SMALLINT PATH '$.menu_sl' NULL ON EMPTY NULL ON ERROR,
                allow_create TINYINT PATH '$.allow_create' NULL ON EMPTY NULL ON ERROR,
                allow_read TINYINT PATH '$.allow_read' NULL ON EMPTY NULL ON ERROR,
                allow_edit TINYINT PATH '$.allow_edit' NULL ON EMPTY NULL ON ERROR,
                allow_del TINYINT PATH '$.allow_del' NULL ON EMPTY NULL ON ERROR,
                allow_approve TINYINT PATH '$.allow_approve' NULL ON EMPTY NULL ON ERROR,
                allow_reverse TINYINT PATH '$.allow_reverse' NULL ON EMPTY NULL ON ERROR,
                allow_print TINYINT PATH '$.allow_print' NULL ON EMPTY NULL ON ERROR,
                status TINYINT PATH '$.status' NULL ON EMPTY NULL ON ERROR
            )
        ) AS j
        INNER JOIN mst_menus m ON m.Menu_Sl = j.menu_sl
        WHERE j.menu_sl IS NOT NULL;

        SELECT COUNT(*) INTO v_assigned
        FROM mst_role_menu
        WHERE Role_Id = p_role_id;

        SELECT
            GREATEST(
                0,
                (
                    SELECT COUNT(*)
                    FROM JSON_TABLE(
                        p_menus_json,
                        '$[*]' COLUMNS (menu_sl SMALLINT PATH '$.menu_sl' NULL ON ERROR)
                    ) AS x
                    WHERE x.menu_sl IS NOT NULL
                ) - v_assigned
            )
        INTO v_skipped;

        SELECT 'SUCCESS' AS status, p_role_id AS role_id, v_assigned AS assigned_count,
               CONCAT('Role menu permissions assigned (', v_assigned, ' menus',
                      IF(v_skipped > 0, CONCAT(', ', v_skipped, ' skipped'), ''),
                      ')') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_ROLE_MENU_GET` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_ROLE_MENU_GET`(
    IN p_role_id SMALLINT,
    IN p_status TINYINT,
    IN p_assigned_only TINYINT
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;

    SELECT COUNT(*) INTO v_exists
    FROM mst_role
    WHERE Id = p_role_id;

    IF v_exists = 0 THEN
        SELECT 'ERROR' AS status, p_role_id AS role_id, 'Role not found' AS message;
    ELSE
        SELECT 'SUCCESS' AS status, p_role_id AS role_id, 'OK' AS message;

        SELECT
            r.Id AS Role_Id,
            r.Role_Name,
            r.Description,
            r.Is_Admin,
            r.Status AS Role_Status
        FROM mst_role r
        WHERE r.Id = p_role_id;

        SELECT
            m.Menu_Sl,
            m.Menu_Id,
            m.Menu_Name,
            m.SubMenu_Id,
            m.SubMenu_Name,
            m.Icon,
            m.Route,
            m.Status AS Menu_Status,
            CASE WHEN rm.Id IS NOT NULL AND IFNULL(rm.Status, 1) = 1 THEN 1 ELSE 0 END AS Assigned,
            IFNULL(rm.Allow_Create, 0) AS Allow_Create,
            IFNULL(rm.Allow_Read, 0) AS Allow_Read,
            IFNULL(rm.Allow_Edit, 0) AS Allow_Edit,
            IFNULL(rm.Allow_Del, 0) AS Allow_Del,
            IFNULL(rm.Allow_Approve, 0) AS Allow_Approve,
            IFNULL(rm.Allow_Reverse, 0) AS Allow_Reverse,
            IFNULL(rm.Allow_Print, 0) AS Allow_Print,
            rm.Status AS Grant_Status,
            rm.Id AS Role_Menu_Id
        FROM mst_menus m
        LEFT JOIN mst_role_menu rm
            ON rm.Menu_Sl = m.Menu_Sl
           AND rm.Role_Id = p_role_id
        WHERE (p_status IS NULL OR m.Status = p_status)
          AND (
              IFNULL(p_assigned_only, 0) = 0
              OR (rm.Id IS NOT NULL AND IFNULL(rm.Status, 1) = 1)
          )
        ORDER BY m.Menu_Id, IFNULL(m.SubMenu_Id, 0), m.Menu_Sl;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_SAVINGS_TRANSACTION_ADD` */;
