CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SAVINGS_TRANSACTION_ADD`(
    IN p_account_id INT,
    IN p_trans_type_cd INT,
    IN p_trans_amount DECIMAL(18,2),
    IN p_trans_mode VARCHAR(2),
    IN p_trans_date DATE,
    IN p_effect_date DATE,
    IN p_fo_id INT,
    IN p_ledger_narration VARCHAR(75),
    IN p_remarks VARCHAR(250),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_type_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_mode VARCHAR(2);
    DECLARE v_mode_desc VARCHAR(20) DEFAULT NULL;
    DECLARE v_date DATE;
    DECLARE v_effect DATE;
    DECLARE v_narration VARCHAR(75);
    DECLARE v_remarks VARCHAR(250);

    DECLARE v_deposit_type INT DEFAULT NULL;
    DECLARE v_scheme INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_acc_status INT DEFAULT NULL;
    DECLARE v_acc_status_desc VARCHAR(100) DEFAULT NULL;

    DECLARE v_min_bal DECIMAL(12,2) DEFAULT 0;
    DECLARE v_withd_allow TINYINT DEFAULT 0;
    DECLARE v_max_withd DECIMAL(12,2) DEFAULT NULL;
    DECLARE v_field_coll TINYINT DEFAULT 0;

    DECLARE v_detail_id INT DEFAULT NULL;
    DECLARE v_start DATE DEFAULT NULL;
    DECLARE v_current DECIMAL(14,2) DEFAULT 0;
    DECLARE v_available DECIMAL(14,2) DEFAULT 0;
    DECLARE v_inst_amt DECIMAL(12,2) DEFAULT NULL;
    DECLARE v_inst_no INT DEFAULT NULL;
    DECLARE v_maturity DATE DEFAULT NULL;
    DECLARE v_pending_dep DECIMAL(14,2) DEFAULT 0;
    DECLARE v_cap DECIMAL(14,2) DEFAULT 0;

    DECLARE v_allow_prev INT DEFAULT 0;
    DECLARE v_max_back INT DEFAULT 0;
    DECLARE v_day_end INT DEFAULT 0;
    DECLARE v_field_with INT DEFAULT 0;

    DECLARE v_rule_cnt INT DEFAULT 0;
    DECLARE v_threshold DECIMAL(12,0) DEFAULT NULL;
    DECLARE v_checker_roles VARCHAR(25) DEFAULT NULL;
    DECLARE v_dual TINYINT DEFAULT 1;
    DECLARE v_auto TINYINT DEFAULT 0;
    DECLARE v_is_checker INT DEFAULT 0;

    DECLARE v_status INT DEFAULT 1;
    DECLARE v_new_balance DECIMAL(14,2) DEFAULT NULL;
    DECLARE v_trans_no VARCHAR(150) DEFAULT NULL;
    DECLARE v_gen_status VARCHAR(10) DEFAULT NULL;
    DECLARE v_gen_msg VARCHAR(255) DEFAULT NULL;
    DECLARE v_trans_id BIGINT DEFAULT NULL;

    SET v_mode = UPPER(NULLIF(TRIM(IFNULL(p_trans_mode, '')), ''));
    SET v_mode = IFNULL(v_mode, 'CA');
    SET v_mode_desc = CASE v_mode WHEN 'CA' THEN 'Cash' WHEN 'CQ' THEN 'Cheque' WHEN 'TR' THEN 'Transfer' WHEN 'OL' THEN 'Online' END;
    SET v_date = IFNULL(p_trans_date, CURDATE());
    SET v_effect = IFNULL(p_effect_date, v_date);
    SET v_narration = NULLIF(TRIM(IFNULL(p_ledger_narration, '')), '');
    SET v_remarks = NULLIF(TRIM(IFNULL(p_remarks, '')), '');

    
    SELECT MIN(Opt_Description) INTO v_type_desc
    FROM mst_appl_options WHERE Opt_Grp_Id = 36 AND Opt_Code = p_trans_type_cd AND Is_Active = 1;

    IF p_trans_type_cd IS NULL OR p_trans_type_cd NOT IN (1, 2) OR v_type_desc IS NULL THEN
        SET v_err = 'Transaction type must be 1 (Deposit) or 2 (Withdrawal)';
    ELSEIF p_trans_amount IS NULL OR p_trans_amount <= 0 THEN
        SET v_err = 'Transaction amount must be greater than 0';
    ELSEIF v_mode_desc IS NULL THEN
        SET v_err = 'Transaction mode must be CA (Cash), CQ (Cheque), TR (Transfer) or OL (Online)';
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Deposit_Type_Cd), MAX(Scheme_Id), MAX(Branch_Id), MAX(Closing_Date), MAX(Appl_Status_Cd)
        INTO v_cnt, v_deposit_type, v_scheme, v_branch, v_closing, v_acc_status
        FROM mst_deposit_account WHERE Account_Id = p_account_id;

        SELECT MIN(Opt_Description) INTO v_acc_status_desc
        FROM mst_appl_options WHERE Opt_Grp_Id = 14 AND Opt_Code = v_acc_status;

        IF p_account_id IS NULL OR v_cnt = 0 THEN
            SET v_err = 'Deposit account not found';
        ELSEIF v_closing IS NOT NULL THEN
            SET v_err = 'Transactions are not allowed on a closed deposit account';
        ELSEIF v_acc_status = 4 THEN
            SET v_err = 'Freezed account: no deposit or withdrawal is allowed';
        ELSEIF p_trans_type_cd = 2 AND v_acc_status IN (2, 3, 5, 7) THEN
            SET v_err = CONCAT('Withdrawal is not allowed on an account with status ', IFNULL(v_acc_status_desc, v_acc_status));
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_deposit_type = 1 THEN
        SELECT MAX(Id) INTO v_detail_id FROM mst_deposit_account_sb WHERE Account_Id = p_account_id;
        IF v_detail_id IS NOT NULL THEN
            SELECT Start_Date, IFNULL(Current_Balance, 0), IFNULL(Available_Balance, 0)
            INTO v_start, v_current, v_available
            FROM mst_deposit_account_sb WHERE Id = v_detail_id FOR UPDATE;
        END IF;
    ELSEIF v_err IS NULL AND v_deposit_type = 2 THEN
        SELECT MAX(Id) INTO v_detail_id FROM mst_deposit_account_td WHERE Account_Id = p_account_id;
        IF v_detail_id IS NOT NULL THEN
            SELECT Start_Date, IFNULL(Current_Balance, 0), Inst_Amount, IFNULL(Inst_No, 1), Maturity_Date
            INTO v_start, v_current, v_inst_amt, v_inst_no, v_maturity
            FROM mst_deposit_account_td WHERE Id = v_detail_id FOR UPDATE;

            SELECT IFNULL(SUM(IF(Trans_Type_Cd = 1, Trans_Amount, 0)), 0),
                   v_current - IFNULL(SUM(IF(Trans_Type_Cd = 2, Trans_Amount, 0)), 0)
            INTO v_pending_dep, v_available
            FROM trans_savings_transaction
            WHERE Account_Id = p_account_id AND Tr_Status_Cd = 2;
        END IF;
    END IF;

    IF v_err IS NULL AND v_detail_id IS NULL THEN
        SET v_err = 'Account details (SB / TD) are not set up yet for this account';
    END IF;

    IF v_err IS NULL THEN
        SELECT IFNULL(MAX(Min_Balance), 0), IFNULL(MAX(Withd_Allow), 0), MAX(Max_Withd_Amt), IFNULL(MAX(Field_Coll), 0)
        INTO v_min_bal, v_withd_allow, v_max_withd, v_field_coll
        FROM mst_deposit_scheme WHERE Scheme_Id = v_scheme;

        SELECT IFNULL(MAX(IF(Code = 'AllowPrev', Status, NULL)), 0),
               IFNULL(MAX(IF(Code = 'DayEnd', Status, NULL)), 0),
               IFNULL(MAX(IF(Code = 'FieldWith', Status, NULL)), 0)
        INTO v_allow_prev, v_day_end, v_field_with
        FROM mst_settings_general;

        SELECT IFNULL(MAX(CAST(Value AS UNSIGNED)), 0) INTO v_max_back FROM mst_settings_global WHERE Id = 2;
    END IF;

    
    IF v_err IS NULL THEN
        IF v_date > CURDATE() THEN
            SET v_err = 'Transaction date cannot be in the future';
        ELSEIF v_date < CURDATE() AND v_allow_prev <> 1 THEN
            SET v_err = 'Backdated transactions are not allowed';
        ELSEIF v_date < CURDATE() AND v_max_back > 0 AND DATEDIFF(CURDATE(), v_date) > v_max_back THEN
            SET v_err = CONCAT('Transaction date can be at most ', v_max_back, ' day(s) back');
        ELSEIF NOT EXISTS (SELECT 1 FROM mst_fin_year WHERE Is_Active = 1 AND v_date BETWEEN Start_Date AND End_Date) THEN
            SET v_err = 'Transaction date is outside the active financial year';
        ELSEIF v_date < v_start THEN
            SET v_err = CONCAT('Transaction date cannot be before the account start date (', DATE_FORMAT(v_start, '%d-%m-%Y'), ')');
        ELSEIF v_effect < v_start OR v_effect > v_date THEN
            SET v_err = 'Effect date must be between the account start date and the transaction date';
        END IF;
    END IF;

    IF v_err IS NULL AND v_day_end = 1 THEN
        SELECT COUNT(*) INTO v_cnt FROM trans_sod_eod
        WHERE Branch_Id = v_branch AND DATE(SOD) = v_date AND EOD IS NULL;
        IF v_cnt = 0 THEN
            SET v_err = 'Branch day is not open for the transaction date (start of day not done or day already closed)';
        END IF;
    END IF;

    
    IF v_err IS NULL AND p_fo_id IS NOT NULL THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_staff
        WHERE Staff_Id = p_fo_id AND Branch_Id = v_branch AND IFNULL(Status, 0) = 1;
        IF v_cnt = 0 THEN
            SET v_err = 'Active field officer not found for the account branch';
        ELSEIF p_trans_type_cd = 1 AND v_field_coll <> 1 THEN
            SET v_err = 'Field collection is not enabled for this deposit scheme';
        ELSEIF p_trans_type_cd = 2 AND v_field_with <> 1 THEN
            SET v_err = 'Withdrawal in the field is not allowed';
        END IF;
    END IF;

    
    IF v_err IS NULL AND v_deposit_type = 1 AND p_trans_type_cd = 1 THEN
        IF v_current + p_trans_amount > 99999999.99 THEN
            SET v_err = 'Balance after this deposit would exceed 99999999.99';
        END IF;
    ELSEIF v_err IS NULL AND v_deposit_type = 1 THEN
        IF v_withd_allow <> 1 THEN
            SET v_err = 'Withdrawals are not allowed for this deposit scheme';
        ELSEIF IFNULL(v_max_withd, 0) > 0 AND p_trans_amount > v_max_withd THEN
            SET v_err = CONCAT('Withdrawal cannot exceed ', FORMAT(v_max_withd, 2), ' per transaction');
        ELSEIF p_trans_amount > v_available THEN
            SET v_err = CONCAT('Insufficient available balance (available ', FORMAT(v_available, 2), ')');
        ELSEIF p_trans_amount <> v_available AND v_available - p_trans_amount < v_min_bal THEN
            SET v_err = CONCAT('Withdrawal must leave the minimum balance of ', FORMAT(v_min_bal, 2),
                               ' (or withdraw the full available balance ', FORMAT(v_available, 2), ')');
        END IF;
    ELSEIF v_err IS NULL AND p_trans_type_cd = 1 THEN
        SET v_cap = v_inst_amt * v_inst_no;
        IF v_date > v_maturity THEN
            SET v_err = 'Deposits are not accepted after the maturity date';
        ELSEIF MOD(p_trans_amount, v_inst_amt) <> 0 THEN
            SET v_err = CONCAT('Amount must be a multiple of the installment amount ', FORMAT(v_inst_amt, 2));
        ELSEIF v_current + v_pending_dep + p_trans_amount > v_cap THEN
            SET v_err = CONCAT('Total deposit cannot exceed ', FORMAT(v_cap, 2), ' (already deposited ',
                               FORMAT(v_current + v_pending_dep, 2), ')');
        END IF;
    ELSEIF v_err IS NULL THEN
        IF v_date < v_maturity THEN
            SET v_err = CONCAT('Term deposit can be withdrawn only on or after the maturity date (',
                               DATE_FORMAT(v_maturity, '%d-%m-%Y'), ')');
        ELSEIF p_trans_amount > v_available THEN
            SET v_err = CONCAT('Insufficient available balance (available ', FORMAT(v_available, 2), ')');
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Thresold_Limit), MAX(Checker_Role_Id), MAX(IFNULL(DualAuth_Req, 1)), MAX(IFNULL(Auto_Apprv, 0))
        INTO v_rule_cnt, v_threshold, v_checker_roles, v_dual, v_auto
        FROM mst_settings_maker_checker
        WHERE Voucher_Type = p_trans_type_cd AND IFNULL(Is_Active, 0) = 1;

        IF v_rule_cnt > 0 AND v_auto <> 1 AND p_trans_amount > IFNULL(v_threshold, 0) THEN
            SELECT COUNT(*) INTO v_is_checker
            FROM mst_user_role ur
            WHERE ur.User_Id = p_user_id AND IFNULL(ur.Status, 0) = 1
              AND FIND_IN_SET(ur.Role_Id, REPLACE(IFNULL(v_checker_roles, ''), ' ', '')) > 0;

            SET v_status = IF(v_dual = 0 AND v_is_checker > 0, 1, 2);
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        CALL USP_CODE_SERIES_GENERATE('savings_transaction', v_trans_no, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_trans_no IS NULL THEN
            SET v_err = CONCAT('Transaction number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS trans_id, NULL AS trans_no, NULL AS status_cd, NULL AS balance_after, v_err AS message;
    ELSE
        SET v_narration = IFNULL(v_narration, LEFT(CONCAT(v_type_desc, ' - ', v_mode_desc), 75));

        IF v_status = 1 THEN
            SET v_new_balance = IF(p_trans_type_cd = 1, v_current + p_trans_amount, v_current - p_trans_amount);

            IF v_deposit_type = 1 THEN
                UPDATE mst_deposit_account_sb
                SET Current_Balance = v_new_balance,
                    Available_Balance = IF(p_trans_type_cd = 1, v_available + p_trans_amount, v_available - p_trans_amount)
                WHERE Id = v_detail_id;
            ELSE
                UPDATE mst_deposit_account_td SET Current_Balance = v_new_balance WHERE Id = v_detail_id;
            END IF;
        ELSEIF p_trans_type_cd = 2 AND v_deposit_type = 1 THEN
            UPDATE mst_deposit_account_sb SET Available_Balance = v_available - p_trans_amount WHERE Id = v_detail_id;
        END IF;

        INSERT INTO trans_savings_transaction (
            Account_Id, Trans_No, Trans_Date, Effect_Date, Trans_Mode, Trans_Type_Cd, Trans_Amount, Balance_After,
            Ledger_Narration, Branch_Id, FO_Id, Remarks, Voucher_Id, Tr_Status_Cd, Created_By, Created_At,
            Approved_By, Approved_At
        ) VALUES (
            p_account_id, LEFT(v_trans_no, 40), v_date, v_effect, v_mode, p_trans_type_cd, p_trans_amount, v_new_balance,
            v_narration, v_branch, p_fo_id, v_remarks, NULL, v_status, p_user_id, NOW(),
            IF(v_status = 1, p_user_id, NULL), IF(v_status = 1, NOW(), NULL)
        );

        SET v_trans_id = LAST_INSERT_ID();

        SELECT 'SUCCESS' AS status, v_trans_id AS trans_id, LEFT(v_trans_no, 40) AS trans_no, v_status AS status_cd,
               v_new_balance AS balance_after,
               IF(v_status = 1,
                  CONCAT(v_type_desc, ' of ', FORMAT(p_trans_amount, 2), ' posted successfully'),
                  CONCAT(v_type_desc, ' of ', FORMAT(p_trans_amount, 2), ' is above ', FORMAT(v_threshold, 0),
                         ' and was sent for approval')) AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_SAVINGS_TRANSACTION_APPROVE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SAVINGS_TRANSACTION_APPROVE`(
    IN p_trans_id BIGINT,
    IN p_approve TINYINT,
    IN p_remarks VARCHAR(250),
    IN p_user_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_account_id INT DEFAULT NULL;
    DECLARE v_type INT DEFAULT NULL;
    DECLARE v_type_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_amount DECIMAL(18,2) DEFAULT 0;
    DECLARE v_status INT DEFAULT NULL;
    DECLARE v_maker INT DEFAULT NULL;
    DECLARE v_remarks VARCHAR(250);
    DECLARE v_note VARCHAR(250);

    DECLARE v_deposit_type INT DEFAULT NULL;
    DECLARE v_closing DATE DEFAULT NULL;
    DECLARE v_acc_status INT DEFAULT NULL;
    DECLARE v_acc_status_desc VARCHAR(100) DEFAULT NULL;
    DECLARE v_detail_id INT DEFAULT NULL;
    DECLARE v_current DECIMAL(14,2) DEFAULT 0;
    DECLARE v_available DECIMAL(14,2) DEFAULT 0;
    DECLARE v_inst_amt DECIMAL(12,2) DEFAULT 0;
    DECLARE v_inst_no INT DEFAULT 1;
    DECLARE v_new_balance DECIMAL(14,2) DEFAULT NULL;

    DECLARE v_rule_cnt INT DEFAULT 0;
    DECLARE v_checker_roles VARCHAR(25) DEFAULT NULL;
    DECLARE v_dual TINYINT DEFAULT 1;
    DECLARE v_is_checker INT DEFAULT 0;

    SET v_note = NULLIF(TRIM(IFNULL(p_remarks, '')), '');

    SELECT COUNT(*), MAX(Account_Id), MAX(Trans_Type_Cd), MAX(Trans_Amount), MAX(Tr_Status_Cd), MAX(Created_By), MAX(Remarks)
    INTO v_cnt, v_account_id, v_type, v_amount, v_status, v_maker, v_remarks
    FROM trans_savings_transaction WHERE Sav_Trans_Id = p_trans_id FOR UPDATE;

    SELECT MIN(Opt_Description) INTO v_type_desc
    FROM mst_appl_options WHERE Opt_Grp_Id = 36 AND Opt_Code = v_type;

    IF p_trans_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Transaction not found';
    ELSEIF p_approve IS NULL OR p_approve NOT IN (0, 1) THEN
        SET v_err = 'Approve must be 1 (approve) or 0 (reject)';
    ELSEIF v_status <> 2 THEN
        SET v_err = CONCAT('Only pending transactions can be approved or rejected (this one is ',
                           CASE v_status WHEN 1 THEN 'posted' WHEN 3 THEN 'rejected' ELSE 'not pending' END, ')');
    ELSEIF p_approve = 0 AND v_note IS NULL THEN
        SET v_err = 'Rejection reason is required';
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Checker_Role_Id), MAX(IFNULL(DualAuth_Req, 1))
        INTO v_rule_cnt, v_checker_roles, v_dual
        FROM mst_settings_maker_checker
        WHERE Voucher_Type = v_type AND IFNULL(Is_Active, 0) = 1;

        SELECT COUNT(*) INTO v_is_checker
        FROM mst_user_role ur
        JOIN mst_role r ON r.Id = ur.Role_Id AND IFNULL(r.Status, 0) = 1
        WHERE ur.User_Id = p_user_id AND IFNULL(ur.Status, 0) = 1
          AND (r.Is_Admin = 1 OR (v_rule_cnt > 0 AND FIND_IN_SET(ur.Role_Id, REPLACE(IFNULL(v_checker_roles, ''), ' ', '')) > 0));

        IF v_is_checker = 0 THEN
            SET v_err = 'You do not have a checker role to approve or reject this transaction';
        ELSEIF (v_rule_cnt = 0 OR v_dual = 1) AND v_maker = p_user_id THEN
            SET v_err = 'The maker cannot approve or reject their own transaction';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT MAX(Deposit_Type_Cd), MAX(Closing_Date), MAX(Appl_Status_Cd)
        INTO v_deposit_type, v_closing, v_acc_status
        FROM mst_deposit_account WHERE Account_Id = v_account_id;

        SELECT MIN(Opt_Description) INTO v_acc_status_desc
        FROM mst_appl_options WHERE Opt_Grp_Id = 14 AND Opt_Code = v_acc_status;

        IF v_deposit_type = 1 THEN
            SELECT MAX(Id) INTO v_detail_id FROM mst_deposit_account_sb WHERE Account_Id = v_account_id;
            SELECT IFNULL(Current_Balance, 0), IFNULL(Available_Balance, 0) INTO v_current, v_available
            FROM mst_deposit_account_sb WHERE Id = v_detail_id FOR UPDATE;
        ELSE
            SELECT MAX(Id) INTO v_detail_id FROM mst_deposit_account_td WHERE Account_Id = v_account_id;
            SELECT IFNULL(Current_Balance, 0), Inst_Amount, IFNULL(Inst_No, 1) INTO v_current, v_inst_amt, v_inst_no
            FROM mst_deposit_account_td WHERE Id = v_detail_id FOR UPDATE;
        END IF;

        IF v_detail_id IS NULL THEN
            SET v_err = 'Account details (SB / TD) not found';
        ELSEIF p_approve = 1 AND v_closing IS NOT NULL THEN
            SET v_err = 'The account is closed; reject this transaction instead';
        ELSEIF p_approve = 1 AND v_acc_status = 4 THEN
            SET v_err = 'The account is freezed; the transaction cannot be approved now';
        ELSEIF p_approve = 1 AND v_type = 2 AND v_acc_status IN (2, 3, 5, 7) THEN
            SET v_err = CONCAT('Withdrawal is not allowed on an account with status ', IFNULL(v_acc_status_desc, v_acc_status));
        ELSEIF p_approve = 1 AND v_type = 1 AND v_deposit_type = 2 AND v_current + v_amount > v_inst_amt * v_inst_no THEN
            SET v_err = CONCAT('Total deposit cannot exceed ', FORMAT(v_inst_amt * v_inst_no, 2));
        ELSEIF p_approve = 1 AND v_type = 2 AND v_amount > v_current THEN
            SET v_err = CONCAT('Insufficient balance (current ', FORMAT(v_current, 2), ')');
        ELSEIF p_approve = 1 AND v_type = 1 AND v_current + v_amount > 99999999.99 THEN
            SET v_err = 'Balance after this deposit would exceed 99999999.99';
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, p_trans_id AS trans_id, v_status AS status_cd, NULL AS balance_after, v_err AS message;
    ELSEIF p_approve = 1 THEN
        SET v_new_balance = IF(v_type = 1, v_current + v_amount, v_current - v_amount);

        IF v_deposit_type = 1 THEN
            UPDATE mst_deposit_account_sb
            SET Current_Balance = v_new_balance,
                Available_Balance = IF(v_type = 1, v_available + v_amount, v_available)
            WHERE Id = v_detail_id;
        ELSE
            UPDATE mst_deposit_account_td SET Current_Balance = v_new_balance WHERE Id = v_detail_id;
        END IF;

        UPDATE trans_savings_transaction
        SET Tr_Status_Cd = 1,
            Balance_After = v_new_balance,
            Remarks = IF(v_note IS NULL, Remarks, LEFT(CONCAT_WS(' | ', Remarks, CONCAT('Approved: ', v_note)), 250)),
            Approved_By = p_user_id,
            Approved_At = NOW()
        WHERE Sav_Trans_Id = p_trans_id;

        SELECT 'SUCCESS' AS status, p_trans_id AS trans_id, 1 AS status_cd, v_new_balance AS balance_after,
               CONCAT(v_type_desc, ' of ', FORMAT(v_amount, 2), ' approved and posted') AS message;
    ELSE
        IF v_type = 2 AND v_deposit_type = 1 THEN
            UPDATE mst_deposit_account_sb SET Available_Balance = v_available + v_amount WHERE Id = v_detail_id;
        END IF;

        UPDATE trans_savings_transaction
        SET Tr_Status_Cd = 3,
            Remarks = LEFT(CONCAT_WS(' | ', Remarks, CONCAT('Rejected: ', v_note)), 250),
            Approved_By = p_user_id,
            Approved_At = NOW()
        WHERE Sav_Trans_Id = p_trans_id;

        SELECT 'SUCCESS' AS status, p_trans_id AS trans_id, 3 AS status_cd, NULL AS balance_after,
               CONCAT(v_type_desc, ' of ', FORMAT(v_amount, 2), ' rejected') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_SAVINGS_TRANSACTION_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SAVINGS_TRANSACTION_LIST`(
    IN p_trans_id BIGINT,
    IN p_account_id INT,
    IN p_member_id INT,
    IN p_group_id INT,
    IN p_branch_id INT,
    IN p_fo_id INT,
    IN p_deposit_type_cd INT,
    IN p_trans_type_cd INT,
    IN p_trans_mode VARCHAR(2),
    IN p_status_cd INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM trans_savings_transaction t
    LEFT JOIN mst_deposit_account a ON a.Account_Id = t.Account_Id
    LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
    LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
    WHERE (p_trans_id IS NULL OR t.Sav_Trans_Id = p_trans_id)
      AND (p_account_id IS NULL OR t.Account_Id = p_account_id)
      AND (p_member_id IS NULL OR (a.Cust_Type_Cd = 2 AND p_member_id IN (a.Cust_Id_Primay, IFNULL(a.Cust_Id_Joint1, 0), IFNULL(a.Cust_Id_Joint2, 0))))
      AND (p_group_id IS NULL OR (a.Cust_Type_Cd = 1 AND a.Cust_Id_Primay = p_group_id))
      AND (p_branch_id IS NULL OR t.Branch_Id = p_branch_id)
      AND (p_fo_id IS NULL OR t.FO_Id = p_fo_id)
      AND (p_deposit_type_cd IS NULL OR a.Deposit_Type_Cd = p_deposit_type_cd)
      AND (p_trans_type_cd IS NULL OR t.Trans_Type_Cd = p_trans_type_cd)
      AND (p_trans_mode IS NULL OR p_trans_mode = '' OR t.Trans_Mode = p_trans_mode)
      AND (p_status_cd IS NULL OR t.Tr_Status_Cd = p_status_cd)
      AND (p_from_date IS NULL OR t.Trans_Date >= p_from_date)
      AND (p_to_date IS NULL OR t.Trans_Date <= p_to_date)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(t.Trans_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Appl_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Holder_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR EXISTS (SELECT 1 FROM mst_deposit_account_sb sb WHERE sb.Account_Id = t.Account_Id
                     AND (CAST(sb.Account_No AS CHAR) = p_keyword OR IFNULL(sb.Ref_AcNo, '') LIKE CONCAT('%', p_keyword, '%')))
          OR EXISTS (SELECT 1 FROM mst_deposit_account_td td WHERE td.Account_Id = t.Account_Id
                     AND (CAST(td.Account_No AS CHAR) = p_keyword OR IFNULL(td.Ref_AcNo, '') LIKE CONCAT('%', p_keyword, '%')))
      );

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        t.Sav_Trans_Id,
        t.Account_Id,
        a.Appl_No,
        a.Holder_Name,
        a.Deposit_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 3 AND o.Opt_Code = a.Deposit_Type_Cd) AS Deposit_Type_Desc,
        a.Scheme_Id,
        s.Scheme_Code,
        s.Scheme_Name,
        a.Cust_Type_Cd,
        a.Cust_Id_Primay AS Cust_Id_Primary,
        IF(a.Cust_Type_Cd = 1, pg.Ref_Code, pm.Ref_Code) AS Primary_Ref_Code,
        IF(a.Cust_Type_Cd = 1, pg.Group_Name, pm.Member_Name) AS Primary_Name,
        COALESCE(
            (SELECT sb.Account_No FROM mst_deposit_account_sb sb WHERE sb.Account_Id = t.Account_Id ORDER BY sb.Id DESC LIMIT 1),
            (SELECT td.Account_No FROM mst_deposit_account_td td WHERE td.Account_Id = t.Account_Id ORDER BY td.Id DESC LIMIT 1)
        ) AS Account_No,
        t.Trans_No,
        t.Trans_Date,
        t.Effect_Date,
        t.Trans_Mode,
        CASE t.Trans_Mode WHEN 'CA' THEN 'Cash' WHEN 'CQ' THEN 'Cheque' WHEN 'TR' THEN 'Transfer' WHEN 'OL' THEN 'Online' END AS Trans_Mode_Desc,
        t.Trans_Type_Cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 36 AND o.Opt_Code = t.Trans_Type_Cd) AS Trans_Type_Desc,
        t.Trans_Amount,
        t.Balance_After,
        t.Ledger_Narration,
        t.Branch_Id,
        b.Branch_Code,
        b.Branch_Name,
        t.FO_Id,
        fo.Employee_Code AS FO_Code,
        fo.Full_Name AS FO_Name,
        t.Remarks,
        t.Voucher_Id,
        t.Tr_Status_Cd AS Status_Cd,
        CASE t.Tr_Status_Cd WHEN 1 THEN 'Posted' WHEN 2 THEN 'Pending Approval' WHEN 3 THEN 'Rejected' END AS Status_Desc,
        t.Created_By,
        cu.User_Name AS Created_By_Name,
        t.Created_At,
        t.Approved_By,
        au.User_Name AS Approved_By_Name,
        t.Approved_At
    FROM trans_savings_transaction t
    LEFT JOIN mst_deposit_account a ON a.Account_Id = t.Account_Id
    LEFT JOIN mst_deposit_scheme s ON s.Scheme_Id = a.Scheme_Id
    LEFT JOIN mst_member pm ON a.Cust_Type_Cd = 2 AND pm.Member_Id = a.Cust_Id_Primay
    LEFT JOIN mst_group pg ON a.Cust_Type_Cd = 1 AND pg.Group_Id = a.Cust_Id_Primay
    LEFT JOIN mst_staff fo ON fo.Staff_Id = t.FO_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = t.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user cu ON cu.User_Id = t.Created_By
    LEFT JOIN priomicro_core.mst_org_user au ON au.User_Id = t.Approved_By
    WHERE (p_trans_id IS NULL OR t.Sav_Trans_Id = p_trans_id)
      AND (p_account_id IS NULL OR t.Account_Id = p_account_id)
      AND (p_member_id IS NULL OR (a.Cust_Type_Cd = 2 AND p_member_id IN (a.Cust_Id_Primay, IFNULL(a.Cust_Id_Joint1, 0), IFNULL(a.Cust_Id_Joint2, 0))))
      AND (p_group_id IS NULL OR (a.Cust_Type_Cd = 1 AND a.Cust_Id_Primay = p_group_id))
      AND (p_branch_id IS NULL OR t.Branch_Id = p_branch_id)
      AND (p_fo_id IS NULL OR t.FO_Id = p_fo_id)
      AND (p_deposit_type_cd IS NULL OR a.Deposit_Type_Cd = p_deposit_type_cd)
      AND (p_trans_type_cd IS NULL OR t.Trans_Type_Cd = p_trans_type_cd)
      AND (p_trans_mode IS NULL OR p_trans_mode = '' OR t.Trans_Mode = p_trans_mode)
      AND (p_status_cd IS NULL OR t.Tr_Status_Cd = p_status_cd)
      AND (p_from_date IS NULL OR t.Trans_Date >= p_from_date)
      AND (p_to_date IS NULL OR t.Trans_Date <= p_to_date)
      AND (
          p_keyword IS NULL OR p_keyword = ''
          OR IFNULL(t.Trans_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Appl_No, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(a.Holder_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pm.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
          OR IFNULL(pg.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
          OR EXISTS (SELECT 1 FROM mst_deposit_account_sb sb WHERE sb.Account_Id = t.Account_Id
                     AND (CAST(sb.Account_No AS CHAR) = p_keyword OR IFNULL(sb.Ref_AcNo, '') LIKE CONCAT('%', p_keyword, '%')))
          OR EXISTS (SELECT 1 FROM mst_deposit_account_td td WHERE td.Account_Id = t.Account_Id
                     AND (CAST(td.Account_No AS CHAR) = p_keyword OR IFNULL(td.Ref_AcNo, '') LIKE CONCAT('%', p_keyword, '%')))
      )
    ORDER BY t.Trans_Date DESC, t.Sav_Trans_Id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
