CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SECURITY_POLICY_GET`()
BEGIN
    IF NOT EXISTS (SELECT 1 FROM mst_security_policy LIMIT 1) THEN
        INSERT INTO mst_security_policy (
            Max_Attempts, Lock_Minutes, Daily_Reset_Time,
            Min_Chars, Max_Chars, Require_Upper, Require_Lower, Require_Number, Require_Special,
            Unique_Recent, Passwords_Expire, Expire_Days
        ) VALUES (5, 15, '00:00:00', 8, 32, 1, 1, 1, 1, 5, 1, 90);
    END IF;

    SELECT
        Id,
        Max_Attempts,
        Lock_Minutes,
        TIME_FORMAT(Daily_Reset_Time, '%H:%i:%s') AS Daily_Reset_Time,
        Min_Chars,
        Max_Chars,
        Require_Upper,
        Require_Lower,
        Require_Number,
        Require_Special,
        Unique_Recent,
        Passwords_Expire,
        Expire_Days,
        Updated_by,
        Created_at,
        Updated_at
    FROM mst_security_policy
    ORDER BY Id ASC
    LIMIT 1;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
