DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SECURITY_POLICY_UPDATE`(
    IN p_max_attempts SMALLINT UNSIGNED,
    IN p_lock_minutes SMALLINT UNSIGNED,
    IN p_daily_reset_time TIME,
    IN p_min_chars SMALLINT UNSIGNED,
    IN p_max_chars SMALLINT UNSIGNED,
    IN p_require_upper TINYINT,
    IN p_require_lower TINYINT,
    IN p_require_number TINYINT,
    IN p_require_special TINYINT,
    IN p_unique_recent SMALLINT UNSIGNED,
    IN p_passwords_expire TINYINT,
    IN p_expire_days SMALLINT UNSIGNED,
    IN p_updated_by SMALLINT UNSIGNED
)
BEGIN
    DECLARE v_id SMALLINT UNSIGNED DEFAULT NULL;
    DECLARE v_expire_days SMALLINT UNSIGNED;

    IF p_max_attempts IS NULL OR p_max_attempts < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Maximum attempts must be at least 1';
    END IF;
    IF p_lock_minutes IS NULL OR p_lock_minutes < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Lock duration must be at least 1 minute';
    END IF;
    IF p_daily_reset_time IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Daily reset time is required';
    END IF;
    IF p_min_chars IS NULL OR p_min_chars < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Minimum characters must be at least 1';
    END IF;
    IF p_max_chars IS NULL OR p_max_chars < p_min_chars THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Maximum characters must be >= minimum characters';
    END IF;
    IF p_unique_recent IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unique recent passwords is required';
    END IF;

    SET v_expire_days = IFNULL(p_expire_days, 90);
    IF IFNULL(p_passwords_expire, 0) = 1 AND v_expire_days < 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Expire after days must be at least 1 when passwords expire';
    END IF;
    IF IFNULL(p_passwords_expire, 0) = 0 THEN
        SET v_expire_days = IFNULL(p_expire_days, 90);
    END IF;

    SELECT Id INTO v_id FROM mst_security_policy ORDER BY Id ASC LIMIT 1;

    IF v_id IS NULL THEN
        INSERT INTO mst_security_policy (
            Max_Attempts, Lock_Minutes, Daily_Reset_Time,
            Min_Chars, Max_Chars, Require_Upper, Require_Lower, Require_Number, Require_Special,
            Unique_Recent, Passwords_Expire, Expire_Days, Updated_by
        ) VALUES (
            p_max_attempts, p_lock_minutes, p_daily_reset_time,
            p_min_chars, p_max_chars,
            IFNULL(p_require_upper, 0), IFNULL(p_require_lower, 0),
            IFNULL(p_require_number, 0), IFNULL(p_require_special, 0),
            p_unique_recent, IFNULL(p_passwords_expire, 0), v_expire_days, p_updated_by
        );
        SET v_id = LAST_INSERT_ID();
    ELSE
        UPDATE mst_security_policy
        SET
            Max_Attempts = p_max_attempts,
            Lock_Minutes = p_lock_minutes,
            Daily_Reset_Time = p_daily_reset_time,
            Min_Chars = p_min_chars,
            Max_Chars = p_max_chars,
            Require_Upper = IFNULL(p_require_upper, 0),
            Require_Lower = IFNULL(p_require_lower, 0),
            Require_Number = IFNULL(p_require_number, 0),
            Require_Special = IFNULL(p_require_special, 0),
            Unique_Recent = p_unique_recent,
            Passwords_Expire = IFNULL(p_passwords_expire, 0),
            Expire_Days = v_expire_days,
            Updated_by = p_updated_by,
            Updated_at = NOW()
        WHERE Id = v_id;
    END IF;

    SELECT
        Id,
        Max_Attempts,
        Lock_Minutes,
        TIME_FORMAT(Daily_Reset_Time, '%H:%i:%s') AS Daily_Reset_Time,
        Min_Chars,
        Max_Chars,
        Require_Upper,
        Require_Lower,
        Require_Number,
        Require_Special,
        Unique_Recent,
        Passwords_Expire,
        Expire_Days,
        Updated_by,
        Created_at,
        Updated_at
    FROM mst_security_policy
    WHERE Id = v_id;
END ;;
DELIMITER ;
