CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SETTINGS_MAKER_CHECKER_ADD_EDIT`(
    IN p_mode VARCHAR(10),
    IN p_id SMALLINT UNSIGNED,
    IN p_voucher_type TINYINT,
    IN p_thresold_limit DECIMAL(12, 0),
    IN p_checker_role_id VARCHAR(25),
    IN p_dual_auth_req TINYINT,
    IN p_auto_apprv TINYINT,
    IN p_is_active TINYINT,
    IN p_created_by SMALLINT
)
BEGIN
    DECLARE v_id SMALLINT UNSIGNED DEFAULT NULL;
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;

    IF p_mode IS NULL OR p_mode NOT IN ('ADD', 'EDIT') THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Invalid mode. Use ADD or EDIT' AS message;
    ELSEIF p_voucher_type IS NULL OR p_voucher_type < 1 THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Voucher type is required' AS message;
    ELSEIF p_thresold_limit IS NULL OR p_thresold_limit < 0 THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Threshold limit must be 0 or greater' AS message;
    ELSEIF p_checker_role_id IS NULL OR TRIM(p_checker_role_id) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Checker role id is required' AS message;
    ELSE
        IF p_mode = 'EDIT' THEN
            IF p_id IS NULL OR p_id < 1 THEN
                SELECT 'ERROR' AS status, NULL AS id, 'Id is required for EDIT' AS message;
            ELSE
                SELECT COUNT(*) INTO v_exists
                FROM mst_settings_maker_checker
                WHERE Id = p_id;

                IF v_exists = 0 THEN
                    SELECT 'ERROR' AS status, NULL AS id, 'Maker-checker rule not found' AS message;
                ELSE
                    SELECT COUNT(*) INTO v_dup
                    FROM mst_settings_maker_checker
                    WHERE Voucher_Type = p_voucher_type
                      AND Id <> p_id;

                    IF v_dup > 0 THEN
                        SELECT 'ERROR' AS status, p_id AS id, 'A rule already exists for this voucher type' AS message;
                    ELSE
                        UPDATE mst_settings_maker_checker
                        SET
                            Voucher_Type = p_voucher_type,
                            Thresold_Limit = p_thresold_limit,
                            Checker_Role_Id = TRIM(p_checker_role_id),
                            DualAuth_Req = IFNULL(p_dual_auth_req, DualAuth_Req),
                            Auto_Apprv = IFNULL(p_auto_apprv, Auto_Apprv),
                            Is_Active = IFNULL(p_is_active, Is_Active)
                        WHERE Id = p_id;

                        SELECT 'SUCCESS' AS status, p_id AS id, 'Maker-checker rule updated successfully' AS message;
                    END IF;
                END IF;
            END IF;
        ELSE
            SELECT COUNT(*) INTO v_dup
            FROM mst_settings_maker_checker
            WHERE Voucher_Type = p_voucher_type;

            IF v_dup > 0 THEN
                SELECT 'ERROR' AS status, NULL AS id, 'A rule already exists for this voucher type' AS message;
            ELSE
                INSERT INTO mst_settings_maker_checker (
                    Voucher_Type,
                    Thresold_Limit,
                    Checker_Role_Id,
                    DualAuth_Req,
                    Auto_Apprv,
                    Is_Active,
                    Created_by,
                    Created_at
                ) VALUES (
                    p_voucher_type,
                    p_thresold_limit,
                    TRIM(p_checker_role_id),
                    IFNULL(p_dual_auth_req, 1),
                    IFNULL(p_auto_apprv, 0),
                    IFNULL(p_is_active, 1),
                    p_created_by,
                    NOW()
                );

                SET v_id = LAST_INSERT_ID();
                SELECT 'SUCCESS' AS status, v_id AS id, 'Maker-checker rule created successfully' AS message;
            END IF;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
