CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SETTINGS_MAKER_CHECKER_LIST`(
    IN p_id SMALLINT UNSIGNED,
    IN p_voucher_type TINYINT,
    IN p_is_active TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_settings_maker_checker mc
    WHERE (p_id IS NULL OR mc.Id = p_id)
      AND (p_voucher_type IS NULL OR mc.Voucher_Type = p_voucher_type)
      AND (p_is_active IS NULL OR mc.Is_Active = p_is_active);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        mc.Id,
        mc.Voucher_Type,
        mc.Thresold_Limit,
        mc.Checker_Role_Id,
        CAST(mc.DualAuth_Req AS UNSIGNED) AS DualAuth_Req,
        CAST(mc.Auto_Apprv AS UNSIGNED) AS Auto_Apprv,
        CAST(mc.Is_Active AS UNSIGNED) AS Is_Active,
        mc.Created_by,
        mc.Created_at
    FROM mst_settings_maker_checker mc
    WHERE (p_id IS NULL OR mc.Id = p_id)
      AND (p_voucher_type IS NULL OR mc.Voucher_Type = p_voucher_type)
      AND (p_is_active IS NULL OR mc.Is_Active = p_is_active)
    ORDER BY mc.Voucher_Type ASC, mc.Id ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
