CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SETTINGS_SMS_UPDATE`(
    IN p_api_key VARCHAR(255),
    IN p_header_key VARCHAR(10),
    IN p_user_nm VARCHAR(25),
    IN p_user_pwd VARCHAR(100),
    IN p_is_default TINYINT,
    IN p_updated_by SMALLINT UNSIGNED
)
BEGIN
    DECLARE v_id SMALLINT UNSIGNED DEFAULT NULL;

    IF p_api_key IS NULL OR TRIM(p_api_key) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id, 'API key is required' AS message;
    ELSEIF p_header_key IS NULL OR TRIM(p_header_key) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Header key (sender ID) is required' AS message;
    ELSEIF p_user_nm IS NULL OR TRIM(p_user_nm) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id, 'User name is required' AS message;
    ELSEIF p_user_pwd IS NULL OR TRIM(p_user_pwd) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id, 'User password is required' AS message;
    ELSE
        SELECT Id INTO v_id
        FROM mst_settings_sms
        ORDER BY Id ASC
        LIMIT 1;

        IF v_id IS NULL THEN
            INSERT INTO mst_settings_sms (
                API_Key,
                Header_Key,
                User_Nm,
                User_Pwd,
                Is_Default,
                Updated_by
            ) VALUES (
                TRIM(p_api_key),
                TRIM(p_header_key),
                TRIM(p_user_nm),
                TRIM(p_user_pwd),
                IFNULL(p_is_default, 1),
                p_updated_by
            );

            SET v_id = LAST_INSERT_ID();
            SELECT 'SUCCESS' AS status, v_id AS id, 'SMS settings saved successfully' AS message;
        ELSE
            UPDATE mst_settings_sms
            SET
                API_Key = TRIM(p_api_key),
                Header_Key = TRIM(p_header_key),
                User_Nm = TRIM(p_user_nm),
                User_Pwd = TRIM(p_user_pwd),
                Is_Default = IFNULL(p_is_default, Is_Default),
                Updated_by = p_updated_by,
                Updated_at = NOW()
            WHERE Id = v_id;

            SELECT 'SUCCESS' AS status, v_id AS id, 'SMS settings updated successfully' AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
