CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SETTINGS_WHATSAPP_GET`()
BEGIN
    SELECT
        Id,
        Access_Token,
        PnNo_Id,
        Waba_Id,
        Webhook_URL,
        Verify_Token,
        Is_Default,
        Updated_by,
        Created_at,
        Updated_at
    FROM mst_settings_whatsapp
    ORDER BY Id ASC
    LIMIT 1;
END ;;
