/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SETTINGS_WHATSAPP_UPDATE`(
    IN p_access_token VARCHAR(255),
    IN p_pnno_id VARCHAR(25),
    IN p_waba_id VARCHAR(25),
    IN p_webhook_url VARCHAR(150),
    IN p_verify_token VARCHAR(25),
    IN p_is_default TINYINT,
    IN p_updated_by SMALLINT UNSIGNED
)
BEGIN
    DECLARE v_id SMALLINT UNSIGNED DEFAULT NULL;

    IF p_access_token IS NULL OR TRIM(p_access_token) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id,
               'Access token is required' AS message;
    ELSEIF p_pnno_id IS NULL OR TRIM(p_pnno_id) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id,
               'Phone number ID (PnNo_Id) is required' AS message;
    ELSEIF p_waba_id IS NULL OR TRIM(p_waba_id) = '' THEN
        SELECT 'ERROR' AS status, NULL AS id,
               'WABA ID is required' AS message;
    ELSE
        SELECT Id INTO v_id
        FROM mst_settings_whatsapp
        ORDER BY Id ASC
        LIMIT 1;

        IF v_id IS NULL THEN
            INSERT INTO mst_settings_whatsapp (
                Access_Token,
                PnNo_Id,
                Waba_Id,
                Webhook_URL,
                Verify_Token,
                Is_Default,
                Updated_by
            ) VALUES (
                TRIM(p_access_token),
                TRIM(p_pnno_id),
                TRIM(p_waba_id),
                NULLIF(TRIM(IFNULL(p_webhook_url, '')), ''),
                NULLIF(TRIM(IFNULL(p_verify_token, '')), ''),
                IFNULL(p_is_default, 1),
                p_updated_by
            );

            SET v_id = LAST_INSERT_ID();
            SELECT 'SUCCESS' AS status, v_id AS id,
                   'WhatsApp settings saved successfully' AS message;
        ELSE
            UPDATE mst_settings_whatsapp
            SET
                Access_Token = TRIM(p_access_token),
                PnNo_Id = TRIM(p_pnno_id),
                Waba_Id = TRIM(p_waba_id),
                Webhook_URL = IF(
                    p_webhook_url IS NULL,
                    Webhook_URL,
                    NULLIF(TRIM(p_webhook_url), '')
                ),
                Verify_Token = IF(
                    p_verify_token IS NULL,
                    Verify_Token,
                    NULLIF(TRIM(p_verify_token), '')
                ),
                Is_Default = IFNULL(p_is_default, Is_Default),
                Updated_by = p_updated_by,
                Updated_at = NOW()
            WHERE Id = v_id;

            SELECT 'SUCCESS' AS status, v_id AS id,
                   'WhatsApp settings updated successfully' AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
