CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SHARE_HOLDING_GET`(
    IN p_cust_type_cd INT,
    IN p_customer_id INT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_face DECIMAL(8,2) DEFAULT 0;
    DECLARE v_min INT DEFAULT NULL;
    DECLARE v_max INT DEFAULT NULL;

    IF p_cust_type_cd = 2 THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_member WHERE Member_Id = p_customer_id;
    ELSEIF p_cust_type_cd = 1 THEN
        SELECT COUNT(*) INTO v_cnt FROM mst_group WHERE Group_Id = p_customer_id;
    END IF;

    SELECT IFNULL(MAX(IF(Id = 5, Value, NULL)), 0),
           MAX(IF(Id = 6, Value, NULL)),
           NULLIF(MAX(IF(Id = 7, Value, NULL)), 0)
    INTO v_face, v_min, v_max
    FROM mst_settings_global WHERE Id IN (5, 6, 7);

    IF p_cust_type_cd IS NULL OR p_cust_type_cd NOT IN (1, 2) OR v_cnt = 0 THEN
        SET v_err = 'Subscriber not found';
    ELSEIF v_face <= 0 THEN
        SET v_err = 'Share face value is not configured';
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, v_err AS message;
    ELSE
        SELECT 'SUCCESS' AS status,
               p_cust_type_cd AS cust_type_cd,
               p_customer_id AS customer_id,
               v_face AS face_value,
               v_min AS min_shares,
               v_max AS max_shares,
               IFNULL(SUM(IF(Tr_Status_Cd = 1, No_Of_Shares, 0)), 0) AS total_shares,
               IFNULL(SUM(IF(Tr_Status_Cd = 1, Subscription_Amount, 0)), 0) AS total_amount,
               IFNULL(SUM(IF(Tr_Status_Cd = 1, Paid_Amount, 0)), 0) AS paid_amount,
               IFNULL(SUM(IF(Tr_Status_Cd = 1, Outstanding_Amount, 0)), 0) AS outstanding_amount,
               IFNULL(SUM(IF(Tr_Status_Cd = 1, Outstanding_Amount, 0)), 0) AS share_capital,
               IFNULL(SUM(IF(Tr_Status_Cd = 2, No_Of_Shares, 0)), 0) AS pending_shares,
               IFNULL(SUM(IF(Tr_Status_Cd = 2, Subscription_Amount, 0)), 0) AS pending_amount,
               MAX(IF(Tr_Status_Cd = 1, Subscription_Date, NULL)) AS last_subscription_date
        FROM trans_share_subscription
        WHERE Cust_Type_Cd = p_cust_type_cd AND Customer_Id = p_customer_id;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
