/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SHARE_LEDGER_ENSURE`(
    IN p_setting_id INT,
    IN p_ledger_code VARCHAR(50),
    IN p_ledger_name VARCHAR(150),
    IN p_ledger_type VARCHAR(1),
    IN p_head_code VARCHAR(50),
    IN p_head_name VARCHAR(150),
    IN p_categ_name VARCHAR(100),
    IN p_categ_type VARCHAR(2),
    IN p_user_id INT,
    OUT p_ledger_id INT
)
proc: BEGIN
    DECLARE v_categ INT DEFAULT NULL;
    DECLARE v_head INT DEFAULT NULL;

    SET p_ledger_id = NULL;

    SELECT MAX(l.Ledger_Id) INTO p_ledger_id
    FROM mst_settings_global s
    JOIN mst_acct_ledger l ON l.Ledger_Id = s.Value AND IFNULL(l.Is_Active, 0) = 1
    WHERE s.Id = p_setting_id;

    IF p_ledger_id IS NOT NULL THEN
        LEAVE proc;
    END IF;

    SELECT MAX(Ledger_Id) INTO p_ledger_id FROM mst_acct_ledger WHERE UPPER(Ledger_Code) = UPPER(p_ledger_code);

    IF p_ledger_id IS NOT NULL THEN
        UPDATE mst_acct_ledger SET Is_Active = 1 WHERE Ledger_Id = p_ledger_id AND IFNULL(Is_Active, 0) <> 1;
    ELSE
        SELECT MAX(MainHd_Id) INTO v_head FROM mst_acct_head WHERE UPPER(MainHd_Code) = UPPER(p_head_code);

        IF v_head IS NULL THEN
            SELECT MIN(Categ_Id) INTO v_categ FROM mst_acct_category WHERE LOWER(TRIM(Categ_Name)) = LOWER(p_categ_name);
            IF v_categ IS NULL THEN
                INSERT INTO mst_acct_category (Categ_Code, Categ_Name, Categy_Type)
                VALUES (CONCAT('SYS-', UPPER(p_categ_name)), p_categ_name, p_categ_type);
                SET v_categ = LAST_INSERT_ID();
            END IF;

            INSERT INTO mst_acct_head (MainHd_Code, MainHd_Name, Categ_Id, Is_Active)
            VALUES (p_head_code, p_head_name, v_categ, 1);
            SET v_head = LAST_INSERT_ID();
        ELSE
            UPDATE mst_acct_head SET Is_Active = 1 WHERE MainHd_Id = v_head AND IFNULL(Is_Active, 0) <> 1;
        END IF;

        INSERT INTO mst_acct_ledger (Ledger_Code, Ledger_Name, Ledger_Type, MainHd_Id, Is_Active, Created_By, Created_At)
        VALUES (p_ledger_code, p_ledger_name, p_ledger_type, v_head, 1, p_user_id, NOW());
        SET p_ledger_id = LAST_INSERT_ID();
    END IF;

    UPDATE mst_settings_global SET Value = p_ledger_id WHERE Id = p_setting_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
