/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SHARE_SUBSCRIPTION_ADD`(
    IN p_cust_type_cd INT,
    IN p_customer_id INT,
    IN p_subscription_date DATE,
    IN p_no_of_shares INT,
    IN p_paid_amount DECIMAL(10,2),
    IN p_payment_mode_cd INT,
    IN p_trans_ref_no VARCHAR(25),
    IN p_remarks VARCHAR(250),
    IN p_user_id INT,
    IN p_user_branch_id INT,
    IN p_user_is_head TINYINT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_status_cd INT DEFAULT NULL;
    DECLARE v_name VARCHAR(250) DEFAULT NULL;
    DECLARE v_face DECIMAL(8,2) DEFAULT 0;
    DECLARE v_min INT DEFAULT NULL;
    DECLARE v_max INT DEFAULT 0;
    DECLARE v_held INT DEFAULT 0;
    DECLARE v_amount DECIMAL(10,2) DEFAULT 0;
    DECLARE v_ref VARCHAR(25);
    DECLARE v_remarks VARCHAR(250);
    DECLARE v_allow_prev INT DEFAULT 0;
    DECLARE v_day_end INT DEFAULT 0;
    DECLARE v_max_back INT DEFAULT 0;
    DECLARE v_rule_cnt INT DEFAULT 0;
    DECLARE v_threshold DECIMAL(12,0) DEFAULT NULL;
    DECLARE v_checker_roles VARCHAR(25) DEFAULT NULL;
    DECLARE v_dual TINYINT DEFAULT 1;
    DECLARE v_auto TINYINT DEFAULT 0;
    DECLARE v_is_checker INT DEFAULT 0;
    DECLARE v_status INT DEFAULT 1;
    DECLARE v_no VARCHAR(150) DEFAULT NULL;
    DECLARE v_gen_status VARCHAR(10) DEFAULT NULL;
    DECLARE v_gen_msg VARCHAR(255) DEFAULT NULL;
    DECLARE v_id BIGINT DEFAULT NULL;
    DECLARE v_vid BIGINT DEFAULT NULL;
    DECLARE v_vno VARCHAR(25) DEFAULT NULL;
    DECLARE v_vnote VARCHAR(255) DEFAULT NULL;

    SET v_ref = NULLIF(TRIM(IFNULL(p_trans_ref_no, '')), '');
    SET v_remarks = NULLIF(TRIM(IFNULL(p_remarks, '')), '');

    
    IF p_cust_type_cd IS NULL OR p_cust_type_cd NOT IN (1, 2) THEN
        SET v_err = 'Subscriber type must be 1 (Group) or 2 (Individual)';
    ELSEIF p_no_of_shares IS NULL OR p_no_of_shares <= 0 THEN
        SET v_err = 'Number of shares must be greater than 0';
    ELSEIF p_paid_amount IS NULL OR p_paid_amount < 0 THEN
        SET v_err = 'Amount paid cannot be negative';
    ELSEIF p_payment_mode_cd IS NULL OR p_payment_mode_cd NOT IN (1, 2, 3) THEN
        SET v_err = 'Payment mode must be Cash, Bank Cheque or Bank Transfer';
    ELSEIF p_payment_mode_cd IN (2, 3) AND v_ref IS NULL THEN
        SET v_err = 'Reference no is required for cheque and bank transfer';
    END IF;

    
    IF v_err IS NULL THEN
        IF p_cust_type_cd = 2 THEN
            SELECT COUNT(*), MAX(Branch_Id), MAX(Current_Status_Cd), MAX(Member_Name)
            INTO v_cnt, v_branch, v_status_cd, v_name
            FROM mst_member WHERE Member_Id = p_customer_id;
        ELSE
            SELECT COUNT(*), MAX(Branch_Id), MAX(Current_Status_Cd), MAX(Group_Name)
            INTO v_cnt, v_branch, v_status_cd, v_name
            FROM mst_group WHERE Group_Id = p_customer_id;
        END IF;

        IF v_cnt = 0 THEN
            SET v_err = 'Subscriber not found';
        ELSEIF IFNULL(v_status_cd, 0) <> 1 THEN
            SET v_err = 'Shares can be allotted only to an active member or group';
        ELSEIF IFNULL(p_user_is_head, 0) <> 1 AND NOT (v_branch <=> p_user_branch_id) THEN
            SET v_err = 'Subscriber belongs to another branch';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT IFNULL(MAX(IF(Id = 5, Value, NULL)), 0),
               MAX(IF(Id = 6, Value, NULL)),
               IFNULL(MAX(IF(Id = 7, Value, NULL)), 0),
               IFNULL(MAX(IF(Id = 2, Value, NULL)), 0)
        INTO v_face, v_min, v_max, v_max_back
        FROM mst_settings_global WHERE Id IN (2, 5, 6, 7);

        SELECT IFNULL(MAX(IF(Code = 'AllowPrev', Status, NULL)), 0),
               IFNULL(MAX(IF(Code = 'DayEnd', Status, NULL)), 0)
        INTO v_allow_prev, v_day_end
        FROM mst_settings_general;

        SELECT IFNULL(SUM(No_Of_Shares), 0) INTO v_held
        FROM trans_share_subscription
        WHERE Cust_Type_Cd = p_cust_type_cd AND Customer_Id = p_customer_id AND Tr_Status_Cd IN (1, 2)
        FOR UPDATE;

        SET v_amount = ROUND(p_no_of_shares * v_face, 2);

        IF v_face <= 0 THEN
            SET v_err = 'Share face value is not configured';
        ELSEIF v_min IS NOT NULL AND p_no_of_shares < v_min THEN
            SET v_err = CONCAT('At least ', v_min, ' shares are required');
        ELSEIF v_max > 0 AND v_held + p_no_of_shares > v_max THEN
            SET v_err = CONCAT('Holding cannot go above ', v_max, ' shares (', GREATEST(v_max - v_held, 0), ' more allowed)');
        ELSEIF p_paid_amount > v_amount THEN
            SET v_err = CONCAT('Amount paid cannot be more than ', FORMAT(v_amount, 2));
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        IF p_subscription_date IS NULL THEN
            SET v_err = 'Subscription date is required';
        ELSEIF p_subscription_date > CURDATE() THEN
            SET v_err = 'Subscription date cannot be in the future';
        ELSEIF p_subscription_date < CURDATE() AND v_allow_prev <> 1 THEN
            SET v_err = 'Backdated entries are not allowed';
        ELSEIF p_subscription_date < CURDATE() AND v_max_back > 0 AND DATEDIFF(CURDATE(), p_subscription_date) > v_max_back THEN
            SET v_err = CONCAT('Subscription date can be at most ', v_max_back, ' day(s) back');
        ELSEIF NOT EXISTS (SELECT 1 FROM mst_fin_year WHERE Is_Active = 1 AND p_subscription_date BETWEEN Start_Date AND End_Date) THEN
            SET v_err = 'Subscription date is outside the active financial year';
        END IF;
    END IF;

    IF v_err IS NULL AND v_day_end = 1 THEN
        SELECT COUNT(*) INTO v_cnt FROM trans_sod_eod
        WHERE Branch_Id = v_branch AND DATE(SOD) = p_subscription_date AND EOD IS NULL;
        IF v_cnt = 0 THEN
            SET v_err = 'Branch day is not open for the subscription date';
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        SELECT COUNT(*), MAX(Thresold_Limit), MAX(Checker_Role_Id), MAX(IFNULL(DualAuth_Req, 1)), MAX(IFNULL(Auto_Apprv, 0))
        INTO v_rule_cnt, v_threshold, v_checker_roles, v_dual, v_auto
        FROM mst_settings_maker_checker
        WHERE Voucher_Type = 1 AND IFNULL(Is_Active, 0) = 1;

        IF v_rule_cnt > 0 AND v_auto <> 1 AND v_amount > IFNULL(v_threshold, 0) THEN
            SELECT COUNT(*) INTO v_is_checker
            FROM mst_user_role ur
            WHERE ur.User_Id = p_user_id AND IFNULL(ur.Status, 0) = 1
              AND FIND_IN_SET(ur.Role_Id, REPLACE(IFNULL(v_checker_roles, ''), ' ', '')) > 0;

            SET v_status = IF(v_dual = 0 AND v_is_checker > 0, 1, 2);
        END IF;
    END IF;

    
    IF v_err IS NULL THEN
        CALL USP_CODE_SERIES_GENERATE('share_subscription', v_no, v_gen_status, v_gen_msg);
        IF v_gen_status <> 'SUCCESS' OR v_no IS NULL THEN
            SET v_err = CONCAT('Subscription number could not be generated: ', IFNULL(v_gen_msg, 'code series error'));
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS subscription_id, NULL AS status_cd, NULL AS voucher_id, NULL AS voucher_no,
               NULL AS voucher_note, v_err AS message;
    ELSE
        INSERT INTO trans_share_subscription (
            Subscription_No, Cust_Type_Cd, Customer_Id, Branch_Id, Subscription_Date, No_Of_Shares, Face_Value,
            Subscription_Amount, Paid_Amount, Outstanding_Amount, Payment_Mode_Cd, Trans_Ref_No, Voucher_Id,
            Remarks, Tr_Status_Cd, Created_By, Created_At, Approved_By, Approved_At
        ) VALUES (
            LEFT(v_no, 40), p_cust_type_cd, p_customer_id, v_branch, p_subscription_date, p_no_of_shares, v_face,
            v_amount, p_paid_amount, v_amount, p_payment_mode_cd, v_ref, NULL,
            v_remarks, v_status, p_user_id, NOW(), IF(v_status = 1, p_user_id, NULL), IF(v_status = 1, NOW(), NULL)
        );

        SET v_id = LAST_INSERT_ID();

        IF v_status = 1 THEN
            CALL USP_SHARE_VOUCHER_POST(v_id, p_user_id, v_vid, v_vno, v_vnote);
        END IF;

        SELECT 'SUCCESS' AS status, v_id AS subscription_id, v_status AS status_cd,
               v_vid AS voucher_id, v_vno AS voucher_no, v_vnote AS voucher_note,
               IF(v_status = 1,
                  CONCAT(p_no_of_shares, ' shares allotted to ', v_name),
                  CONCAT('Share subscription of ', FORMAT(v_amount, 2), ' is above ', FORMAT(v_threshold, 0),
                         ' and was sent for approval')) AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_SHARE_SUBSCRIPTION_APPROVE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SHARE_SUBSCRIPTION_APPROVE`(
    IN p_subscription_id BIGINT,
    IN p_approve TINYINT,
    IN p_remarks VARCHAR(200),
    IN p_user_id INT,
    IN p_user_branch_id INT,
    IN p_user_is_head TINYINT
)
BEGIN
    DECLARE v_err VARCHAR(255) DEFAULT NULL;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_status INT DEFAULT NULL;
    DECLARE v_branch INT DEFAULT NULL;
    DECLARE v_created_by INT DEFAULT NULL;
    DECLARE v_cust_type INT DEFAULT NULL;
    DECLARE v_customer INT DEFAULT NULL;
    DECLARE v_shares INT DEFAULT 0;
    DECLARE v_held INT DEFAULT 0;
    DECLARE v_max INT DEFAULT 0;
    DECLARE v_checker_roles VARCHAR(25) DEFAULT NULL;
    DECLARE v_dual TINYINT DEFAULT 1;
    DECLARE v_is_checker INT DEFAULT 0;
    DECLARE v_remarks VARCHAR(200);
    DECLARE v_vid BIGINT DEFAULT NULL;
    DECLARE v_vno VARCHAR(25) DEFAULT NULL;
    DECLARE v_vnote VARCHAR(255) DEFAULT NULL;

    SET v_remarks = NULLIF(TRIM(IFNULL(p_remarks, '')), '');

    SELECT COUNT(*), MAX(Tr_Status_Cd), MAX(Branch_Id), MAX(Created_By), MAX(Cust_Type_Cd), MAX(Customer_Id), MAX(No_Of_Shares)
    INTO v_cnt, v_status, v_branch, v_created_by, v_cust_type, v_customer, v_shares
    FROM trans_share_subscription WHERE Subscription_Id = p_subscription_id FOR UPDATE;

    SELECT MAX(Checker_Role_Id), MAX(IFNULL(DualAuth_Req, 1))
    INTO v_checker_roles, v_dual
    FROM mst_settings_maker_checker WHERE Voucher_Type = 1 AND IFNULL(Is_Active, 0) = 1;

    SELECT COUNT(*) INTO v_is_checker
    FROM mst_user_role ur
    WHERE ur.User_Id = p_user_id AND IFNULL(ur.Status, 0) = 1
      AND FIND_IN_SET(ur.Role_Id, REPLACE(IFNULL(v_checker_roles, ''), ' ', '')) > 0;

    IF p_subscription_id IS NULL OR v_cnt = 0 THEN
        SET v_err = 'Share subscription not found';
    ELSEIF v_status <> 2 THEN
        SET v_err = 'Only pending subscriptions can be approved or rejected';
    ELSEIF IFNULL(p_user_is_head, 0) <> 1 AND NOT (v_branch <=> p_user_branch_id) THEN
        SET v_err = 'Subscription belongs to another branch';
    ELSEIF v_is_checker = 0 THEN
        SET v_err = 'You are not allowed to approve share subscriptions';
    ELSEIF IFNULL(v_dual, 1) = 1 AND v_created_by = p_user_id THEN
        SET v_err = 'The person who entered the subscription cannot approve it';
    ELSEIF IFNULL(p_approve, 0) = 0 AND v_remarks IS NULL THEN
        SET v_err = 'A reason is required to reject';
    END IF;

    IF v_err IS NULL AND p_approve = 1 THEN
        SELECT IFNULL(MAX(Value), 0) INTO v_max FROM mst_settings_global WHERE Id = 7;

        SELECT IFNULL(SUM(No_Of_Shares), 0) INTO v_held
        FROM trans_share_subscription
        WHERE Cust_Type_Cd = v_cust_type AND Customer_Id = v_customer AND Tr_Status_Cd = 1;

        IF v_max > 0 AND v_held + v_shares > v_max THEN
            SET v_err = CONCAT('Holding cannot go above ', v_max, ' shares');
        END IF;
    END IF;

    IF v_err IS NOT NULL THEN
        SELECT 'ERROR' AS status, NULL AS subscription_id, NULL AS status_cd, NULL AS voucher_id, NULL AS voucher_no,
               NULL AS voucher_note, v_err AS message;
    ELSE
        UPDATE trans_share_subscription
        SET Tr_Status_Cd = IF(p_approve = 1, 1, 3),
            Approved_By = p_user_id,
            Approved_At = NOW(),
            Approval_Remarks = v_remarks
        WHERE Subscription_Id = p_subscription_id;

        IF p_approve = 1 THEN
            CALL USP_SHARE_VOUCHER_POST(p_subscription_id, p_user_id, v_vid, v_vno, v_vnote);
        END IF;

        SELECT 'SUCCESS' AS status, p_subscription_id AS subscription_id, IF(p_approve = 1, 1, 3) AS status_cd,
               v_vid AS voucher_id, v_vno AS voucher_no, v_vnote AS voucher_note,
               IF(p_approve = 1, 'Share subscription approved', 'Share subscription rejected') AS message;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_SHARE_SUBSCRIPTION_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SHARE_SUBSCRIPTION_LIST`(
    IN p_subscription_id BIGINT,
    IN p_cust_type_cd INT,
    IN p_customer_id INT,
    IN p_branch_id INT,
    IN p_status_cd INT,
    IN p_from_date DATE,
    IN p_to_date DATE,
    IN p_keyword VARCHAR(150),
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM trans_share_subscription s
    LEFT JOIN mst_member m ON s.Cust_Type_Cd = 2 AND m.Member_Id = s.Customer_Id
    LEFT JOIN mst_group g ON s.Cust_Type_Cd = 1 AND g.Group_Id = s.Customer_Id
    WHERE (p_subscription_id IS NULL OR s.Subscription_Id = p_subscription_id)
      AND (p_cust_type_cd IS NULL OR s.Cust_Type_Cd = p_cust_type_cd)
      AND (p_customer_id IS NULL OR s.Customer_Id = p_customer_id)
      AND (p_branch_id IS NULL OR s.Branch_Id = p_branch_id)
      AND (p_status_cd IS NULL OR s.Tr_Status_Cd = p_status_cd)
      AND (p_from_date IS NULL OR s.Subscription_Date >= p_from_date)
      AND (p_to_date IS NULL OR s.Subscription_Date <= p_to_date)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(s.Subscription_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(m.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(g.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(g.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%'));

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        s.Subscription_Id AS subscription_id,
        s.Subscription_No AS subscription_no,
        s.Cust_Type_Cd AS cust_type_cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 34 AND o.Opt_Code = s.Cust_Type_Cd) AS cust_type_desc,
        s.Customer_Id AS customer_id,
        IF(s.Cust_Type_Cd = 1, IFNULL(g.Ref_Code, CAST(g.Group_Code AS CHAR)), IFNULL(m.Ref_Code, CAST(m.Member_Code AS CHAR))) AS customer_code,
        IF(s.Cust_Type_Cd = 1, g.Group_Name, m.Member_Name) AS customer_name,
        s.Branch_Id AS branch_id,
        b.Branch_Name AS branch_name,
        s.Subscription_Date AS subscription_date,
        s.No_Of_Shares AS no_of_shares,
        s.Face_Value AS face_value,
        s.Subscription_Amount AS subscription_amount,
        s.Paid_Amount AS paid_amount,
        s.Outstanding_Amount AS outstanding_amount,
        s.Payment_Mode_Cd AS payment_mode_cd,
        (SELECT MIN(o.Opt_Description) FROM mst_appl_options o WHERE o.Opt_Grp_Id = 41 AND o.Opt_Code = s.Payment_Mode_Cd) AS payment_mode_desc,
        s.Trans_Ref_No AS trans_ref_no,
        s.Voucher_Id AS voucher_id,
        IFNULL(v.Vou_No_Ref, CAST(v.Voucher_No AS CHAR)) AS voucher_no,
        s.Remarks AS remarks,
        s.Tr_Status_Cd AS tr_status_cd,
        CASE s.Tr_Status_Cd WHEN 1 THEN 'Approved' WHEN 2 THEN 'Pending Approval' WHEN 3 THEN 'Rejected' WHEN 4 THEN 'Reversed' END AS tr_status_desc,
        s.Created_By AS created_by,
        cu.User_Name AS created_by_name,
        s.Created_At AS created_at,
        s.Approved_By AS approved_by,
        au.User_Name AS approved_by_name,
        s.Approved_At AS approved_at,
        s.Approval_Remarks AS approval_remarks
    FROM trans_share_subscription s
    LEFT JOIN mst_member m ON s.Cust_Type_Cd = 2 AND m.Member_Id = s.Customer_Id
    LEFT JOIN mst_group g ON s.Cust_Type_Cd = 1 AND g.Group_Id = s.Customer_Id
    LEFT JOIN trans_vouchers v ON v.Voucher_Id = s.Voucher_Id
    LEFT JOIN priomicro_core.mst_org_branch b ON b.Branch_Id = s.Branch_Id
    LEFT JOIN priomicro_core.mst_org_user cu ON cu.User_Id = s.Created_By
    LEFT JOIN priomicro_core.mst_org_user au ON au.User_Id = s.Approved_By
    WHERE (p_subscription_id IS NULL OR s.Subscription_Id = p_subscription_id)
      AND (p_cust_type_cd IS NULL OR s.Cust_Type_Cd = p_cust_type_cd)
      AND (p_customer_id IS NULL OR s.Customer_Id = p_customer_id)
      AND (p_branch_id IS NULL OR s.Branch_Id = p_branch_id)
      AND (p_status_cd IS NULL OR s.Tr_Status_Cd = p_status_cd)
      AND (p_from_date IS NULL OR s.Subscription_Date >= p_from_date)
      AND (p_to_date IS NULL OR s.Subscription_Date <= p_to_date)
      AND (p_keyword IS NULL OR p_keyword = ''
           OR IFNULL(s.Subscription_No, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(m.Member_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(m.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(g.Group_Name, '') LIKE CONCAT('%', p_keyword, '%')
           OR IFNULL(g.Ref_Code, '') LIKE CONCAT('%', p_keyword, '%'))
    ORDER BY s.Subscription_Date DESC, s.Subscription_Id DESC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_SHARE_VOUCHER_BACKFILL` */;
