/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SHARE_VOUCHER_BACKFILL`()
BEGIN
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_id BIGINT;
    DECLARE v_user INT;
    DECLARE v_vid BIGINT;
    DECLARE v_vno VARCHAR(25);
    DECLARE v_vnote VARCHAR(255);
    DECLARE cur CURSOR FOR
        SELECT Subscription_Id, IFNULL(Approved_By, Created_By)
        FROM trans_share_subscription
        WHERE Tr_Status_Cd = 1 AND Voucher_Id IS NULL
        ORDER BY Subscription_Date, Subscription_Id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    DROP TEMPORARY TABLE IF EXISTS tmp_share_backfill;
    CREATE TEMPORARY TABLE tmp_share_backfill (
        Subscription_Id BIGINT, Voucher_Id BIGINT, Voucher_No VARCHAR(25), Note VARCHAR(255)
    );

    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO v_id, v_user;
        IF v_done = 1 THEN
            LEAVE read_loop;
        END IF;
        CALL USP_SHARE_VOUCHER_POST(v_id, v_user, v_vid, v_vno, v_vnote);
        INSERT INTO tmp_share_backfill VALUES (v_id, v_vid, v_vno, v_vnote);
    END LOOP;
    CLOSE cur;

    SELECT * FROM tmp_share_backfill;
    DROP TEMPORARY TABLE IF EXISTS tmp_share_backfill;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `USP_SHARE_VOUCHER_POST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
