/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_SHARE_VOUCHER_POST`(
    IN p_subscription_id BIGINT,
    IN p_user_id INT,
    OUT p_voucher_id BIGINT,
    OUT p_voucher_no VARCHAR(25),
    OUT p_note VARCHAR(255)
)
proc: BEGIN
    DECLARE v_no VARCHAR(40);
    DECLARE v_branch INT;
    DECLARE v_date DATE;
    DECLARE v_amount DECIMAL(10,2) DEFAULT 0;
    DECLARE v_paid DECIMAL(10,2) DEFAULT 0;
    DECLARE v_mode INT;
    DECLARE v_existing BIGINT;
    DECLARE v_name VARCHAR(250);
    DECLARE v_capital INT DEFAULT NULL;
    DECLARE v_receivable INT DEFAULT NULL;
    DECLARE v_contra INT DEFAULT NULL;
    DECLARE v_narr VARCHAR(255);

    SET p_voucher_id = NULL;
    SET p_voucher_no = NULL;
    SET p_note = NULL;

    SELECT s.Subscription_No, s.Branch_Id, s.Subscription_Date, s.Outstanding_Amount, IFNULL(s.Paid_Amount, 0),
           s.Payment_Mode_Cd, s.Voucher_Id, IF(s.Cust_Type_Cd = 1, g.Group_Name, m.Member_Name)
    INTO v_no, v_branch, v_date, v_amount, v_paid, v_mode, v_existing, v_name
    FROM trans_share_subscription s
    LEFT JOIN mst_member m ON s.Cust_Type_Cd = 2 AND m.Member_Id = s.Customer_Id
    LEFT JOIN mst_group g ON s.Cust_Type_Cd = 1 AND g.Group_Id = s.Customer_Id
    WHERE s.Subscription_Id = p_subscription_id;

    IF v_existing IS NOT NULL THEN
        SET p_voucher_id = v_existing;
        SELECT IFNULL(Vou_No_Ref, CAST(Voucher_No AS CHAR)) INTO p_voucher_no FROM trans_vouchers WHERE Voucher_Id = v_existing;
        LEAVE proc;
    END IF;

    IF v_no IS NULL THEN
        SET p_note = 'Voucher not posted: share subscription not found';
        LEAVE proc;
    END IF;

    CALL USP_SHARE_LEDGER_ENSURE(106, 'SYS-SHARE-CAPITAL', 'Share Capital', 'L',
                                 'SYS-SHARE-CAPITAL', 'Share Capital', 'Equity', 'CR', p_user_id, v_capital);
    IF v_amount - v_paid > 0 THEN
        CALL USP_SHARE_LEDGER_ENSURE(107, 'SYS-SHARE-RECEIVABLE', 'Share Subscription Receivable', 'A',
                                     'SYS-RECEIVABLES', 'Receivables', 'Assets', 'DR', p_user_id, v_receivable);
    END IF;
    IF v_paid > 0 AND v_mode = 1 THEN
        CALL USP_SHARE_LEDGER_ENSURE(101, 'SYS-CASH', 'Cash in Hand', 'A',
                                     'SYS-CASH-BANK', 'Cash and Bank Balances', 'Assets', 'DR', p_user_id, v_contra);
    ELSEIF v_paid > 0 AND v_mode IN (2, 3) THEN
        CALL USP_SHARE_LEDGER_ENSURE(102, 'SYS-BANK', 'Bank Account', 'A',
                                     'SYS-CASH-BANK', 'Cash and Bank Balances', 'Assets', 'DR', p_user_id, v_contra);
    END IF;

    SET v_narr = LEFT(CONCAT('Share subscription ', IFNULL(v_no, p_subscription_id), ' - ', IFNULL(v_name, '')), 255);

    CALL USP_LOAN_VOUCHER_RESET();
    INSERT INTO tmp_loan_voucher_lines (Line_Role, GL_Account_Id, Debit_Amount, Credit_Amount, Line_Narration) VALUES
        ('CONTRA', NULL, v_paid, 0, v_narr),
        ('SHARE RECEIVABLE', v_receivable, GREATEST(v_amount - v_paid, 0), 0, v_narr),
        ('SHARE CAPITAL', v_capital, 0, v_amount, v_narr);

    CALL USP_LOAN_VOUCHER_POST(v_branch, v_date, IF(v_paid > 0, 1, 3), IF(v_paid > 0, v_mode, NULL), v_narr,
                               p_user_id, p_voucher_id, p_voucher_no, p_note);

    IF p_voucher_id IS NOT NULL THEN
        UPDATE trans_share_subscription SET Voucher_Id = p_voucher_id WHERE Subscription_Id = p_subscription_id;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
