DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_STAFF_ADD_EDIT`(
    IN p_action VARCHAR(10),
    IN p_staff_id SMALLINT UNSIGNED,
    IN p_branch_id SMALLINT UNSIGNED,
    IN p_employee_code VARCHAR(25),
    IN p_full_name VARCHAR(100),
    IN p_short_name VARCHAR(50),
    IN p_designation_id SMALLINT UNSIGNED,
    IN p_mobile VARCHAR(20),
    IN p_email VARCHAR(75),
    IN p_join_date DATE,
    IN p_aadhaar VARCHAR(20),
    IN p_pan VARCHAR(15),
    IN p_device_id SMALLINT UNSIGNED,
    IN p_linked_user_id SMALLINT UNSIGNED,
    IN p_module_ids VARCHAR(255),
    IN p_status TINYINT,
    IN p_actor_user_id SMALLINT UNSIGNED
)
BEGIN
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_dup INT DEFAULT 0;
    DECLARE v_name VARCHAR(100);
    DECLARE v_short VARCHAR(50);
    DECLARE v_code VARCHAR(25);
    DECLARE v_new_id SMALLINT UNSIGNED DEFAULT NULL;
    DECLARE v_gen_code VARCHAR(150);
    DECLARE v_gen_status VARCHAR(10);
    DECLARE v_gen_msg VARCHAR(255);
    DECLARE v_pos INT DEFAULT 1;
    DECLARE v_next INT DEFAULT 0;
    DECLARE v_token VARCHAR(20);
    DECLARE v_module_id SMALLINT UNSIGNED;

    SET v_name = NULLIF(TRIM(p_full_name), '');
    SET v_short = NULLIF(TRIM(p_short_name), '');
    SET v_code = NULLIF(TRIM(p_employee_code), '');

    IF v_short IS NULL AND v_name IS NOT NULL THEN
        SET v_short = SUBSTRING_INDEX(v_name, ' ', 1);
    END IF;

    IF UPPER(p_action) = 'ADD' THEN
        IF v_name IS NULL THEN
            SELECT 'ERROR' AS status, NULL AS staff_id, NULL AS employee_code, NULL AS user_id,
                   'Full name is required' AS message;
        ELSE
            IF v_code IS NULL THEN
                CALL USP_CODE_SERIES_GENERATE('employee', v_gen_code, v_gen_status, v_gen_msg);
                IF v_gen_status <> 'SUCCESS' OR v_gen_code IS NULL THEN
                    SELECT 'ERROR' AS status, NULL AS staff_id, NULL AS employee_code, NULL AS user_id,
                           IFNULL(v_gen_msg, 'Unable to generate employee code') AS message;
                ELSE
                    SET v_code = v_gen_code;
                END IF;
            END IF;

            IF v_code IS NOT NULL THEN
                SELECT COUNT(*) INTO v_dup
                FROM mst_staff
                WHERE UPPER(Employee_Code) = UPPER(v_code);

                IF v_dup > 0 THEN
                    SELECT 'ERROR' AS status, NULL AS staff_id, NULL AS employee_code, NULL AS user_id,
                           'Employee code already exists' AS message;
                ELSE
                    INSERT INTO mst_staff (
                        Branch_Id, Employee_Code, Full_Name, Short_Name, Designation_Id,
                        Mobile, Email, Join_Date, Aadhaar, PAN,
                        Device_Id, User_Id,
                        Status, Created_by, Updated_by
                    ) VALUES (
                        p_branch_id,
                        v_code,
                        v_name,
                        v_short,
                        p_designation_id,
                        NULLIF(TRIM(p_mobile), ''),
                        NULLIF(TRIM(p_email), ''),
                        p_join_date,
                        NULLIF(TRIM(p_aadhaar), ''),
                        NULLIF(TRIM(UPPER(p_pan)), ''),
                        p_device_id,
                        p_linked_user_id,
                        IFNULL(p_status, 1),
                        p_actor_user_id,
                        p_actor_user_id
                    );

                    SET v_new_id = LAST_INSERT_ID();

                    IF p_module_ids IS NOT NULL AND TRIM(p_module_ids) <> '' THEN
                        SET v_pos = 1;
                        WHILE v_pos <= CHAR_LENGTH(p_module_ids) DO
                            SET v_next = LOCATE(',', p_module_ids, v_pos);
                            IF v_next = 0 THEN
                                SET v_token = TRIM(SUBSTRING(p_module_ids, v_pos));
                                SET v_pos = CHAR_LENGTH(p_module_ids) + 1;
                            ELSE
                                SET v_token = TRIM(SUBSTRING(p_module_ids, v_pos, v_next - v_pos));
                                SET v_pos = v_next + 1;
                            END IF;

                            IF v_token <> '' AND v_token REGEXP '^[0-9]+$' THEN
                                SET v_module_id = CAST(v_token AS UNSIGNED);
                                IF EXISTS (SELECT 1 FROM mst_module_access WHERE Module_Id = v_module_id AND Status = 1) THEN
                                    INSERT IGNORE INTO mst_staff_module (Staff_Id, Module_Id, Status)
                                    VALUES (v_new_id, v_module_id, 1);
                                END IF;
                            END IF;
                        END WHILE;
                    END IF;

                    SELECT 'SUCCESS' AS status, v_new_id AS staff_id, v_code AS employee_code,
                           p_linked_user_id AS user_id, 'Staff created successfully' AS message;
                END IF;
            END IF;
        END IF;

    ELSEIF UPPER(p_action) = 'EDIT' THEN
        SELECT COUNT(*) INTO v_exists FROM mst_staff WHERE Staff_Id = p_staff_id;

        IF v_exists = 0 THEN
            SELECT 'ERROR' AS status, p_staff_id AS staff_id, NULL AS employee_code, NULL AS user_id,
                   'Staff not found' AS message;
        ELSEIF v_name IS NULL THEN
            SELECT 'ERROR' AS status, p_staff_id AS staff_id, NULL AS employee_code, NULL AS user_id,
                   'Full name is required' AS message;
        ELSEIF v_code IS NULL THEN
            SELECT 'ERROR' AS status, p_staff_id AS staff_id, NULL AS employee_code, NULL AS user_id,
                   'Employee code is required' AS message;
        ELSE
            SELECT COUNT(*) INTO v_dup
            FROM mst_staff
            WHERE UPPER(Employee_Code) = UPPER(v_code)
              AND Staff_Id <> p_staff_id;

            IF v_dup > 0 THEN
                SELECT 'ERROR' AS status, p_staff_id AS staff_id, NULL AS employee_code, NULL AS user_id,
                       'Employee code already exists' AS message;
            ELSE
                UPDATE mst_staff
                SET
                    Branch_Id = p_branch_id,
                    Employee_Code = v_code,
                    Full_Name = v_name,
                    Short_Name = IFNULL(v_short, Short_Name),
                    Designation_Id = p_designation_id,
                    Mobile = NULLIF(TRIM(p_mobile), ''),
                    Email = NULLIF(TRIM(p_email), ''),
                    Join_Date = p_join_date,
                    Aadhaar = NULLIF(TRIM(p_aadhaar), ''),
                    PAN = NULLIF(TRIM(UPPER(p_pan)), ''),
                    Device_Id = p_device_id,
                    User_Id = IFNULL(p_linked_user_id, User_Id),
                    Status = IFNULL(p_status, Status),
                    Updated_by = p_actor_user_id,
                    Updated_at = NOW()
                WHERE Staff_Id = p_staff_id;

                DELETE FROM mst_staff_module WHERE Staff_Id = p_staff_id;

                IF p_module_ids IS NOT NULL AND TRIM(p_module_ids) <> '' THEN
                    SET v_pos = 1;
                    WHILE v_pos <= CHAR_LENGTH(p_module_ids) DO
                        SET v_next = LOCATE(',', p_module_ids, v_pos);
                        IF v_next = 0 THEN
                            SET v_token = TRIM(SUBSTRING(p_module_ids, v_pos));
                            SET v_pos = CHAR_LENGTH(p_module_ids) + 1;
                        ELSE
                            SET v_token = TRIM(SUBSTRING(p_module_ids, v_pos, v_next - v_pos));
                            SET v_pos = v_next + 1;
                        END IF;

                        IF v_token <> '' AND v_token REGEXP '^[0-9]+$' THEN
                            SET v_module_id = CAST(v_token AS UNSIGNED);
                            IF EXISTS (SELECT 1 FROM mst_module_access WHERE Module_Id = v_module_id AND Status = 1) THEN
                                INSERT IGNORE INTO mst_staff_module (Staff_Id, Module_Id, Status)
                                VALUES (p_staff_id, v_module_id, 1);
                            END IF;
                        END IF;
                    END WHILE;
                END IF;

                SELECT 'SUCCESS' AS status, p_staff_id AS staff_id, v_code AS employee_code,
                       (SELECT User_Id FROM mst_staff WHERE Staff_Id = p_staff_id) AS user_id,
                       'Staff updated successfully' AS message;
            END IF;
        END IF;

    ELSE
        SELECT 'ERROR' AS status, p_staff_id AS staff_id, NULL AS employee_code, NULL AS user_id,
               'Invalid action. Use ADD or EDIT' AS message;
    END IF;
END ;;
DELIMITER ;
