CREATE DEFINER=`priority`@`%` PROCEDURE `USP_STAFF_GET_MODULES`(
    IN p_staff_id SMALLINT UNSIGNED
)
BEGIN
    SELECT
        m.Module_Id,
        m.Module_Key,
        m.Module_Label
    FROM mst_staff_module sm
    INNER JOIN mst_module_access m ON m.Module_Id = sm.Module_Id
    WHERE sm.Staff_Id = p_staff_id
      AND sm.Status = 1
      AND m.Status = 1
    ORDER BY m.Module_Id ASC;
END ;;
DELIMITER ;
