/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_STAFF_LIST`(
    IN p_staff_id SMALLINT UNSIGNED,
    IN p_branch_id SMALLINT UNSIGNED,
    IN p_designation_id SMALLINT UNSIGNED,
    IN p_keyword VARCHAR(100),
    IN p_status TINYINT,
    IN p_page INT,
    IN p_per_page INT
)
BEGIN
    DECLARE v_page INT DEFAULT 1;
    DECLARE v_per_page INT DEFAULT 50;
    DECLARE v_offset INT DEFAULT 0;
    DECLARE v_total INT DEFAULT 0;

    SET v_page = GREATEST(IFNULL(p_page, 1), 1);
    SET v_per_page = LEAST(GREATEST(IFNULL(p_per_page, 50), 1), 200);
    SET v_offset = (v_page - 1) * v_per_page;

    SELECT COUNT(*) INTO v_total
    FROM mst_staff s
    WHERE (p_staff_id IS NULL OR s.Staff_Id = p_staff_id)
      AND (p_branch_id IS NULL OR s.Branch_Id = p_branch_id)
      AND (p_designation_id IS NULL OR s.Designation_Id = p_designation_id)
      AND (
          p_keyword IS NULL
          OR p_keyword = ''
          OR s.Full_Name LIKE CONCAT('%', p_keyword, '%')
          OR s.Employee_Code LIKE CONCAT('%', p_keyword, '%')
          OR s.Mobile LIKE CONCAT('%', p_keyword, '%')
          OR s.Email LIKE CONCAT('%', p_keyword, '%')
          OR s.Short_Name LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_status IS NULL OR s.Status = p_status);

    SELECT
        v_total AS total,
        v_page AS page,
        v_per_page AS per_page,
        CASE WHEN v_total = 0 THEN 1 ELSE CEIL(v_total / v_per_page) END AS last_page;

    SELECT
        s.Staff_Id,
        s.Branch_Id,
        s.Employee_Code,
        s.Full_Name,
        s.Short_Name,
        s.Designation_Id,
        d.Designation_Name,
        s.Mobile,
        s.Email,
        s.Join_Date,
        s.Aadhaar,
        s.PAN,
        s.Device_Id,
        s.User_Id,
        s.Status,
        s.Created_by,
        s.Updated_by,
        s.Created_at,
        s.Updated_at
    FROM mst_staff s
    LEFT JOIN mst_designation d ON d.Designation_Id = s.Designation_Id
    WHERE (p_staff_id IS NULL OR s.Staff_Id = p_staff_id)
      AND (p_branch_id IS NULL OR s.Branch_Id = p_branch_id)
      AND (p_designation_id IS NULL OR s.Designation_Id = p_designation_id)
      AND (
          p_keyword IS NULL
          OR p_keyword = ''
          OR s.Full_Name LIKE CONCAT('%', p_keyword, '%')
          OR s.Employee_Code LIKE CONCAT('%', p_keyword, '%')
          OR s.Mobile LIKE CONCAT('%', p_keyword, '%')
          OR s.Email LIKE CONCAT('%', p_keyword, '%')
          OR s.Short_Name LIKE CONCAT('%', p_keyword, '%')
      )
      AND (p_status IS NULL OR s.Status = p_status)
    ORDER BY s.Full_Name ASC
    LIMIT v_per_page OFFSET v_offset;
END ;;
DELIMITER ;
