CREATE DEFINER=`priority`@`%` PROCEDURE `USP_WORKING_HOURS_GET`()
BEGIN
    SELECT
        t.Id,
        TIME_FORMAT(t.SOD_Time, '%H:%i') AS SOD_Time,
        TIME_FORMAT(t.EOD_Time, '%H:%i') AS EOD_Time,
        TIME_FORMAT(t.BatchExe_Time, '%H:%i') AS BatchExe_Time,
        TIME_FORMAT(t.SessionInc_Time, '%H:%i') AS SessionInc_Time
    FROM mst_timmings t
    ORDER BY t.Id ASC
    LIMIT 1;
END ;;
DELIMITER ;
