/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`priority`@`%` PROCEDURE `USP_WORKING_HOURS_UPDATE`(
    IN p_sod_time TIME,
    IN p_eod_time TIME,
    IN p_batch_exe_time TIME,
    IN p_session_inc_time TIME
)
BEGIN
    DECLARE v_id TINYINT DEFAULT NULL;

    IF p_sod_time IS NULL OR p_eod_time IS NULL THEN
        SELECT 'ERROR' AS status, NULL AS id, 'SOD and EOD time are required' AS message;
    ELSEIF p_eod_time <= p_sod_time THEN
        SELECT 'ERROR' AS status, NULL AS id, 'EOD time must be after SOD time' AS message;
    ELSEIF p_session_inc_time IS NULL THEN
        SELECT 'ERROR' AS status, NULL AS id, 'Session inactivity time is required' AS message;
    ELSE
        SELECT Id INTO v_id
        FROM mst_timmings
        ORDER BY Id ASC
        LIMIT 1;

        IF v_id IS NULL THEN
            INSERT INTO mst_timmings (
                SOD_Time,
                EOD_Time,
                BatchExe_Time,
                SessionInc_Time
            ) VALUES (
                p_sod_time,
                p_eod_time,
                p_batch_exe_time,
                p_session_inc_time
            );

            SET v_id = LAST_INSERT_ID();
            SELECT 'SUCCESS' AS status, v_id AS id, 'Working hours saved successfully' AS message;
        ELSE
            UPDATE mst_timmings
            SET
                SOD_Time = p_sod_time,
                EOD_Time = p_eod_time,
                BatchExe_Time = p_batch_exe_time,
                SessionInc_Time = p_session_inc_time
            WHERE Id = v_id;

            SELECT 'SUCCESS' AS status, v_id AS id, 'Working hours updated successfully' AS message;
        END IF;
    END IF;
END ;;
DELIMITER ;
